window.CARDIO = window.CARDIO || {};
CARDIO.registry = CARDIO.registry || {};
CARDIO.registry.fcPub = {"cards":[{"id":"fc-152-4dad7f","poly":"cardio","fiche":"152","front":"Endocardite infectieuse (EI) : définition ?","back":"Infection de l'**endocarde**, le plus souvent d'une ou plusieurs **valves natives** ; aussi endocarde **pariétal** ou tout **matériel intracardiaque**.","prio":"P1","sec":"s1"},{"id":"fc-152-0d595a","poly":"cardio","fiche":"152","front":"EI : citer les matériels intracardiaques qui peuvent être infectés ?","back":"**Prothèse valvulaire** · sonde de **stimulateur** ou de **défibrillateur** · **assistance ventriculaire** · **cathéter veineux central**.","prio":"P2","sec":"s1"},{"id":"fc-152-d0e029","poly":"cardio","fiche":"152","front":"EI : quels types de germes en cause ?","back":"Une **bactérie** le plus souvent ; plus rarement un **champignon**.","prio":"P2","sec":"s1"},{"id":"fc-152-ce8c85","poly":"cardio","fiche":"152","front":"Endocardites non infectieuses : citer les causes ?","back":"**Cancers** (endocardites **marastiques**) ; maladies auto-immunes : **lupus** (lésions de Libman-Sacks), **syndrome des antiphospholipides**.","prio":"P2","sec":"s1"},{"id":"fc-152-56805f","poly":"cardio","fiche":"152","front":"Lupus : nom des lésions d'endocardite non infectieuse ?","back":"Lésions de **Libman-Sacks**.","prio":"P3","sec":"s1"},{"id":"fc-152-0209f2","poly":"cardio","fiche":"152","front":"Endocardites non infectieuses : dans quel cadre diagnostique de l'EI entrent-elles ?","back":"Causes d'EI **à hémocultures négatives**.","prio":"P3","sec":"s1"},{"id":"fc-152-7510c5","poly":"cardio","fiche":"152","front":"EI : comment a évolué l'incidence ces dernières décennies ?","back":"**Pas de diminution** ; ce sont le **profil des patients** (plus âgés) et la **répartition des germes** qui ont changé.","prio":"P2","sec":"s1"},{"id":"fc-152-b1aecd","poly":"cardio","fiche":"152","front":"EI : citer des procédures à risque en augmentation ?","back":"Chirurgie sous **CEC**, **cathéters veineux**, cathétérisme cardiaque, **hémodialyse**, pose de stimulateur/défibrillateur, ponction articulaire, chambre implantable, **toxicomanie IV**.","prio":"P2","sec":"s1"},{"id":"fc-152-3785e9","poly":"cardio","fiche":"152","front":"EI : quelles valvulopathies dégénératives sont citées comme situations à risque ?","back":"**Fibrose** valvulaire et **prolapsus mitral**.","prio":"P3","sec":"s1"},{"id":"fc-152-d9d366","poly":"cardio","fiche":"152","front":"EI : mécanisme physiopathologique de départ ?","back":"**Porte d'entrée** → **bactériémie** (ou fongémie) importante et/ou répétée → fixation sur un endocarde, de préférence **déjà lésé**.","prio":"P2","sec":"s1"},{"id":"fc-152-b6d699","poly":"cardio","fiche":"152","front":"EI : un endocarde sain peut-il être infecté ?","back":"**Oui** : un germe très virulent comme ***S. aureus*** peut infecter un endocarde **sain**.","prio":"P1","sec":"s1"},{"id":"fc-152-b69adc","poly":"cardio","fiche":"152","front":"Végétation d'EI : composition ?","back":"Amas de **fibrine**, **plaquettes**, **cellules inflammatoires** et **germes**.","prio":"P1","sec":"s1"},{"id":"fc-152-d2dbfe","poly":"cardio","fiche":"152","front":"Végétation d'EI : conséquences ?","back":"**Embolies** systémiques (cœur gauche) ou pulmonaires septiques (cœur droit) ; **foyers infectieux à distance** ; rarement obstruction valvulaire.","prio":"P1","sec":"s1"},{"id":"fc-152-3b7c20","poly":"cardio","fiche":"152","front":"EI : conséquence d'une destruction valvulaire (perforation, rupture de cordages) ?","back":"**Fuite (régurgitation) aiguë** → **insuffisance cardiaque**.","prio":"P2","sec":"s1"},{"id":"fc-152-d64773","poly":"cardio","fiche":"152","front":"EI aortique : quel abcès peut donner un BAV ?","back":"Un **abcès septal**, proche des voies de conduction.","prio":"P1","sec":"s1"},{"id":"fc-152-7ee19d","poly":"cardio","fiche":"152","front":"Abcès d'EI : conséquence d'une rupture ?","back":"**Faux anévrisme** ou **fistule intracardiaque**.","prio":"P3","sec":"s1"},{"id":"fc-152-95b5e1","poly":"cardio","fiche":"152","front":"EI sur prothèse : conséquence d'une désinsertion ?","back":"**Fuite paraprothétique**.","prio":"P2","sec":"s1"},{"id":"fc-152-0d2fc0","poly":"cardio","fiche":"152","front":"EI : citer des manifestations de l'atteinte systémique (inflammatoire, immunologique, vasculaire) ?","back":"**Choc septique**, **anévrismes infectieux (mycotiques)**, glomérulonéphrite, purpura vasculaire, faux panaris d'Osler, Janeway, Roth, facteurs rhumatoïdes, parfois cryoglobulinémie.","prio":"P2","sec":"s1"},{"id":"fc-152-41b38a","poly":"cardio","fiche":"152","front":"EI : quelle proportion survient sans cardiopathie à risque connue ?","back":"**50 %** (cardiopathie non connue ou absente).","prio":"P1","sec":"s1"},{"id":"fc-152-c5ba2a","poly":"cardio","fiche":"152","front":"EI : citer les 4 situations du groupe à haut risque ?","back":"**Antécédent d'EI** · **prothèse valvulaire** (TAVI inclus) ou matériel de réparation valvulaire · **cardiopathie congénitale cyanogène** · **assistance ventriculaire**.","prio":"P1","sec":"s2"},{"id":"fc-152-6ec78b","poly":"cardio","fiche":"152","front":"EI : un TAVI classe-t-il le patient à haut risque ?","back":"**Oui** : toute prothèse valvulaire, chirurgicale ou **percutanée (TAVI inclus)**.","prio":"P1","sec":"s2"},{"id":"fc-152-1d01f8","poly":"cardio","fiche":"152","front":"EI : dispositifs à haut risque pendant les 6 mois suivant la pose ?","back":"Dispositifs de **fermeture** (CIV, auricule gauche), **prothèses vasculaires**, **filtres caves**, **shunts ventriculoatriaux**.","prio":"P2","sec":"s2"},{"id":"fc-152-336e50","poly":"cardio","fiche":"152","front":"EI : cardiopathie congénitale réparée avec matériel prothétique, durée du haut risque (points clés) ?","back":"**6 mois** après le geste, ou **à vie** s'il persiste un **shunt résiduel**.","prio":"P2","sec":"s2"},{"id":"fc-152-062543","poly":"cardio","fiche":"152","front":"EI : citer les situations à risque intermédiaire ?","back":"Valvulopathies **dégénératives** ; **congénitales** (bicuspidie aortique) ; **post-rhumatismale** ; **CMH** ; **stimulateur/défibrillateur**.","prio":"P2","sec":"s2"},{"id":"fc-152-f0cf91","poly":"cardio","fiche":"152","front":"Bicuspidie aortique ou stimulateur cardiaque : antibioprophylaxie de l'EI ?","back":"**Non** à ce seul titre : risque **intermédiaire** (éducation seulement).","prio":"P2","sec":"s2"},{"id":"fc-152-980592","poly":"cardio","fiche":"152","front":"EI : à quels patients s'adressent les mesures d'éducation ?","back":"À **tous** les patients à risque (**haut** ou **intermédiaire**).","prio":"P1","sec":"s2"},{"id":"fc-152-f7bc47","poly":"cardio","fiche":"152","front":"EI : à quels patients est réservée l'antibioprophylaxie ?","back":"Aux seuls patients à **haut risque**.","prio":"P1","sec":"s2"},{"id":"fc-152-d2b6ac","poly":"cardio","fiche":"152","front":"Prévention de l'EI : fréquence des visites chez le dentiste ?","back":"**2 fois/an** si haut risque ; **1 fois/an** pour les autres cardiopathies à risque.","prio":"P1","sec":"s2"},{"id":"fc-152-efeafb","poly":"cardio","fiche":"152","front":"EI : germe le plus fréquent et sa part ?","back":"***Staphylococcus aureus*** : **30 %** des EI.","prio":"P1","sec":"s2"},{"id":"fc-152-506bf9","poly":"cardio","fiche":"152","front":"EI à S. aureus : porte d'entrée ?","back":"**Cutanée** : plaie, cathéter veineux ou de dialyse, toxicomanie IV, geste peropératoire, stimulateur/défibrillateur.","prio":"P1","sec":"s2"},{"id":"fc-152-9a4024","poly":"cardio","fiche":"152","front":"EI à streptocoques oraux : part et porte d'entrée ?","back":"**20 %** ; porte d'entrée **buccodentaire**.","prio":"P1","sec":"s2"},{"id":"fc-152-9dade4","poly":"cardio","fiche":"152","front":"EI à streptocoque du groupe D (S. gallolyticus) : part et porte d'entrée ?","back":"**13 %** ; porte d'entrée **digestive** : cancer, polypes, diverticules coliques.","prio":"P1","sec":"s2"},{"id":"fc-152-978f6f","poly":"cardio","fiche":"152","front":"EI à staphylocoques à coagulase négative : part et porte d'entrée ?","back":"**10 %** ; porte d'entrée **cutanée**.","prio":"P2","sec":"s2"},{"id":"fc-152-a11404","poly":"cardio","fiche":"152","front":"EI à entérocoques : part et porte d'entrée ?","back":"**10 %** ; porte d'entrée **digestive** et **urinaire**.","prio":"P1","sec":"s2"},{"id":"fc-152-194809","poly":"cardio","fiche":"152","front":"EI à germes du groupe HACEK : part et porte d'entrée ?","back":"**5 %** ; porte d'entrée **buccodentaire**.","prio":"P2","sec":"s2"},{"id":"fc-152-eec320","poly":"cardio","fiche":"152","front":"EI à Candida : part et porte d'entrée ?","back":"**< 5 %** ; porte d'entrée **cutanée** (immunosuppression, cathéter, toxicomanie IV…).","prio":"P2","sec":"s2"},{"id":"fc-152-9b3488","poly":"cardio","fiche":"152","front":"EI : proportion sans germe retrouvé malgré plusieurs techniques ?","back":"**5-10 %**.","prio":"P3","sec":"s2"},{"id":"fc-152-329919","poly":"cardio","fiche":"152","front":"EI : citer des germes « autres » rares (< 5 %) ?","back":"***Coxiella burnetii***, ***Bartonella***, ***Brucella***, ***Chlamydia***, ***Tropheryma whipplei***.","prio":"P3","sec":"s2"},{"id":"fc-152-01644c","poly":"cardio","fiche":"152","front":"EI : quelle famille de germes domine ?","back":"**Cocci Gram positif** : en **amas** (staphylocoques) et en **chaînettes** (streptocoques, entérocoques).","prio":"P2","sec":"s2"},{"id":"fc-152-7f5a28","poly":"cardio","fiche":"152","front":"Groupe HACEK : signification ?","back":"***Haemophilus*** spp., ***Aggregatibacter*** actinomycetemcomitans, ***Cardiobacterium*** hominis, ***Eikenella*** corrodens, ***Kingella*** kingae.","prio":"P2","sec":"s2"},{"id":"fc-152-427bd2","poly":"cardio","fiche":"152","front":"EI : citer les 5 associations « fièvre + … » qu'il est inacceptable de ne pas rattacher à une EI ?","back":"Fièvre + **souffle** · + **cardiopathie à risque** · + **AVC** · + **lombalgie** · + **purpura**.","prio":"P1","sec":"s3"},{"id":"fc-152-36ceb4","poly":"cardio","fiche":"152","front":"Insuffisance cardiaque fébrile : quel diagnostic évoquer ?","back":"Une **endocardite infectieuse**.","prio":"P1","sec":"s3"},{"id":"fc-152-14e313","poly":"cardio","fiche":"152","front":"EI : caractère de la présentation clinique ?","back":"Maladie **systémique**, **polymorphe** : signes inconstants, c'est le **contexte** qui fait évoquer le diagnostic.","prio":"P2","sec":"s3"},{"id":"fc-152-de71b7","poly":"cardio","fiche":"152","front":"EI : quelle association de signes est très évocatrice ?","back":"Un **syndrome infectieux** associé à des **signes d'atteinte de l'endocarde**.","prio":"P2","sec":"s3"},{"id":"fc-152-daee22","poly":"cardio","fiche":"152","front":"EI : quel signe clinique a la plus grande valeur chez un patient fébrile ?","back":"Un **souffle nouveau ou modifié**.","prio":"P1","sec":"s3"},{"id":"fc-152-8a7395","poly":"cardio","fiche":"152","front":"EI : l'absence de souffle élimine-t-elle le diagnostic ?","back":"**Non**.","prio":"P1","sec":"s3"},{"id":"fc-152-dc2f6a","poly":"cardio","fiche":"152","front":"EI : fréquence de la splénomégalie ?","back":"**20-30 %**.","prio":"P3","sec":"s3"},{"id":"fc-152-9da18f","poly":"cardio","fiche":"152","front":"EI : que traduisent des syncopes ou lipothymies ?","back":"Un **BAV** par **abcès septal** interrompant les voies de conduction.","prio":"P1","sec":"s3"},{"id":"fc-152-bb4473","poly":"cardio","fiche":"152","front":"EI : citer les atteintes neurologiques possibles ?","back":"**AVC** ischémique ou hémorragique, **méningite**, **hémorragie méningée**, **abcès cérébral**.","prio":"P2","sec":"s3"},{"id":"fc-152-dedcb4","poly":"cardio","fiche":"152","front":"EI : signes pulmonaires et leurs mécanismes ?","back":"**OAP** (insuffisance cardiaque gauche) ; **pneumopathies récidivantes abcédées** (**embolies pulmonaires septiques**).","prio":"P2","sec":"s3"},{"id":"fc-152-01361a","poly":"cardio","fiche":"152","front":"EI : atteintes articulaires possibles ?","back":"**Arthrite** périphérique, **spondylodiscite** (foyers infectieux à distance).","prio":"P2","sec":"s3"},{"id":"fc-152-8a7663","poly":"cardio","fiche":"152","front":"EI : fréquence des signes cutanéomuqueux ?","back":"**Rares** : **5-15 %**.","prio":"P3","sec":"s3"},{"id":"fc-152-1abf54","poly":"cardio","fiche":"152","front":"EI : quel signe cutané est pathognomonique ?","back":"Les **nodosités d'Osler** (« faux panaris »).","prio":"P1","sec":"s3"},{"id":"fc-152-2a3bd1","poly":"cardio","fiche":"152","front":"EI : citer les signes cutanéomuqueux possibles ?","back":"**Purpura**, nodosités d'**Osler**, placards de **Janeway**, hémorragies **sous-conjonctivales** et **sous-unguéales**.","prio":"P3","sec":"s3"},{"id":"fc-152-742952","poly":"cardio","fiche":"152","front":"EI : placards de Janeway, définition ?","back":"**Placards érythémateux palmoplantaires**.","prio":"P2","sec":"s3"},{"id":"fc-152-bf9f4d","poly":"cardio","fiche":"152","front":"EI : taches de Roth, définition ?","back":"**Exsudats hémorragiques rétiniens** vus au **fond d'œil**.","prio":"P2","sec":"s3"},{"id":"fc-152-0473c5","poly":"cardio","fiche":"152","front":"EI : atteinte rénale clinique et mécanismes ?","back":"**Hématurie** et/ou **protéinurie** : **glomérulonéphrite** immunologique ou **infarctus rénal**.","prio":"P2","sec":"s3"},{"id":"fc-152-9a2d5e","poly":"cardio","fiche":"152","front":"EI : les deux piliers du diagnostic ?","back":"**Hémocultures** (germe) + **échographie cardiaque** (atteinte de l'endocarde).","prio":"P1","sec":"s4"},{"id":"fc-152-7f707f","poly":"cardio","fiche":"152","front":"EI : quelle erreur est une notion inacceptable vis-à-vis des hémocultures ?","back":"**Débuter les antibiotiques avant les hémocultures**.","prio":"P1","sec":"s4"},{"id":"fc-152-3bf0b5","poly":"cardio","fiche":"152","front":"Hémocultures dans l'EI : nombre et espacement ?","back":"Idéalement **3** prélèvements veineux, espacés d'**au moins 30 min**.","prio":"P1","sec":"s4"},{"id":"fc-152-1c6d7c","poly":"cardio","fiche":"152","front":"Hémocultures dans l'EI : type de culture et site interdit ?","back":"Culture **aéroanaérobie** ; **jamais sur un cathéter déjà en place**.","prio":"P1","sec":"s4"},{"id":"fc-152-3a3e2e","poly":"cardio","fiche":"152","front":"Hémocultures dans l'EI : pourquoi prévenir le laboratoire ?","back":"Germes à croissance difficile (**HACEK**, ***Brucella***, streptocoques déficients, **levures**) : culture parfois **prolongée**.","prio":"P2","sec":"s4"},{"id":"fc-152-64d8a3","poly":"cardio","fiche":"152","front":"EI : hémocultures initiales négatives, que faire ?","back":"Les **répéter pendant 2 ou 3 jours**, surtout si antibiotiques déjà reçus.","prio":"P2","sec":"s4"},{"id":"fc-152-5252ae","poly":"cardio","fiche":"152","front":"EI : rentabilité des hémocultures ?","back":"Germe isolé dans **90 %** des cas (**10 %** d'EI à hémocultures négatives).","prio":"P1","sec":"s4"},{"id":"fc-152-da3b36","poly":"cardio","fiche":"152","front":"EI : place de l'ETT ?","back":"**Systématique en 1re intention**, chez **tous**.","prio":"P1","sec":"s4"},{"id":"fc-152-d4a0ba","poly":"cardio","fiche":"152","front":"EI : 3 indications de l'ETO systématique ?","back":"ETT **positive** ; ETT **négative avec forte suspicion** ; **matériel intracardiaque**.","prio":"P1","sec":"s4"},{"id":"fc-152-d64ca2","poly":"cardio","fiche":"152","front":"EI : échographie normale, conduite ?","back":"EI **non éliminée** : refaire **ETT + ETO après 7-10 jours**.","prio":"P1","sec":"s4"},{"id":"fc-152-38086f","poly":"cardio","fiche":"152","front":"EI : lésions recherchées en échographie ?","back":"**Végétations**, destructions valvulaires, **abcès**, fistules, pseudoanévrismes, désinsertion de prothèse, fuite paraprothétique ; + sévérité et retentissement des fuites.","prio":"P2","sec":"s4"},{"id":"fc-152-430d31","poly":"cardio","fiche":"152","front":"EI : intérêt du scanner cardiaque injecté ?","back":"Abcès ou végétations **non vus en échographie**, notamment sur **prothèse valvulaire**.","prio":"P2","sec":"s4"},{"id":"fc-152-c6c073","poly":"cardio","fiche":"152","front":"EI : indication du TEP-scanner au ¹⁸FDG ou de la scintigraphie aux leucocytes marqués ?","back":"Suspicion d'EI **sur prothèse valvulaire** ou **sur stimulateur/défibrillateur** quand le **diagnostic reste douteux**.","prio":"P2","sec":"s4"},{"id":"fc-152-ef7fc0","poly":"cardio","fiche":"152","front":"EI : intérêt supplémentaire du TEP-scanner corps entier ?","back":"Il montre aussi les **localisations septiques secondaires**.","prio":"P3","sec":"s4"},{"id":"fc-152-110a21","poly":"cardio","fiche":"152","front":"EI : intérêt de l'ECG dans le bilan ?","back":"**BAV** (troubles de conduction) ; **ischémie** par embolie coronarienne.","prio":"P1","sec":"s4"},{"id":"fc-152-da162d","poly":"cardio","fiche":"152","front":"EI : anomalies possibles de la NFS ?","back":"**Hyperleucocytose à PNN**, **anémie** inflammatoire ou hémolytique, **thrombopénie**.","prio":"P3","sec":"s4"},{"id":"fc-152-7fdf48","poly":"cardio","fiche":"152","front":"EI : examens biologiques du bilan des complications, hors NFS ?","back":"**CRP** (inflammation) ; **facteur rhumatoïde** (immunologie) ; **ionogramme**, **créatininémie**, hématurie, protéinurie (rein).","prio":"P3","sec":"s4"},{"id":"fc-152-9aac1e","poly":"cardio","fiche":"152","front":"EI : objectif du scanner cérébral et thoraco-abdomino-pelvien ?","back":"**Localisations septiques secondaires** (parfois asymptomatiques) et **anévrismes infectieux** ; injecté seulement **si la fonction rénale le permet**.","prio":"P1","sec":"s4"},{"id":"fc-152-241f36","poly":"cardio","fiche":"152","front":"EI : localisations secondaires recherchées au scanner ?","back":"**Encéphale**, **rate**, **rein**, **foie**, **vertèbres**.","prio":"P3","sec":"s4"},{"id":"fc-152-38dc71","poly":"cardio","fiche":"152","front":"EI : IRM cérébrale versus scanner ?","back":"**Plus sensible**, mais **moins disponible**.","prio":"P3","sec":"s4"},{"id":"fc-152-c9a774","poly":"cardio","fiche":"152","front":"EI : indication de l'angiographie cérébrale ?","back":"Suspicion d'**anévrisme infectieux (mycotique)**.","prio":"P2","sec":"s4"},{"id":"fc-152-1ba1f0","poly":"cardio","fiche":"152","front":"EI : examens si suspicion d'embolie coronarienne ?","back":"**Coronarographie** et **troponine**.","prio":"P3","sec":"s4"},{"id":"fc-152-a1ff65","poly":"cardio","fiche":"152","front":"EI : radiographie thoracique, que chercher ?","back":"**OAP** (EI du cœur gauche) ; **pneumopathies** (EI du cœur droit).","prio":"P3","sec":"s4"},{"id":"fc-152-26189d","poly":"cardio","fiche":"152","front":"EI certaine : critères cliniques ?","back":"**2 majeurs**, ou **1 majeur + 3 mineurs**, ou **5 mineurs** (ou critères histologiques).","prio":"P2","sec":"s5"},{"id":"fc-152-2a4c1f","poly":"cardio","fiche":"152","front":"EI possible : critères ?","back":"**1 majeur + 1 ou 2 mineurs**, ou **3 mineurs**.","prio":"P2","sec":"s5"},{"id":"fc-152-533ee9","poly":"cardio","fiche":"152","front":"EI : critères histologiques d'EI certaine ?","back":"Patient opéré : **germe en culture** d'une valve ou d'un embole, ou végétation/abcès avec **infection active** à l'anatomopathologie.","prio":"P3","sec":"s5"},{"id":"fc-152-c3603a","poly":"cardio","fiche":"152","front":"EI : 2 critères majeurs ?","back":"**Hémocultures positives pour l'EI** + **imagerie positive** (échographie, scanner cardiaque, TEP-¹⁸FDG ou scintigraphie aux leucocytes marqués).","prio":"P2","sec":"s5"},{"id":"fc-152-ffaa2a","poly":"cardio","fiche":"152","front":"Critère majeur d'EI : germes « typiques » sur ≥ 2 hémocultures ?","back":"***S. aureus***, **streptocoques oraux**, ***S. gallolyticus***, ***Enterococcus faecalis***, **HACEK**.","prio":"P2","sec":"s5"},{"id":"fc-152-e63fac","poly":"cardio","fiche":"152","front":"Critère majeur d'EI : ≥ 2 hémocultures positives, quel intervalle entre les prélèvements ?","back":"Prélevées à **plus de 12 heures** d'intervalle.","prio":"P3","sec":"s5"},{"id":"fc-152-4035f9","poly":"cardio","fiche":"152","front":"Critère majeur d'EI : 3 hémocultures à germe typique, délai exigé ?","back":"**≥ 1 heure** entre le premier et le dernier prélèvement.","prio":"P3","sec":"s5"},{"id":"fc-152-2d0791","poly":"cardio","fiche":"152","front":"Critère majeur d'EI pour Coxiella burnetii ?","back":"**≥ 1 hémoculture positive** ou **IgG de phase I > 1/800**.","prio":"P3","sec":"s5"},{"id":"fc-152-09f81f","poly":"cardio","fiche":"152","front":"EI : citer les 5 critères mineurs ?","back":"**Terrain** à risque (haut/intermédiaire, toxicomanie IV) · **fièvre > 38 °C** · phénomènes **vasculaires** · phénomènes **immunologiques** · argument **microbiologique** non majeur.","prio":"P2","sec":"s5"},{"id":"fc-152-f5e98e","poly":"cardio","fiche":"152","front":"Critère mineur d'EI : phénomènes vasculaires ?","back":"**Embolies** artérielles ou pulmonaires, **anévrismes infectieux**, **hémorragies**, **placards de Janeway** (même asymptomatiques).","prio":"P3","sec":"s5"},{"id":"fc-152-740be4","poly":"cardio","fiche":"152","front":"Critère mineur d'EI : phénomènes immunologiques ?","back":"**Glomérulonéphrite**, **nodosités d'Osler**, **taches de Roth**, **facteurs rhumatoïdes**.","prio":"P3","sec":"s5"},{"id":"fc-152-8decb6","poly":"cardio","fiche":"152","front":"EI du cœur droit : terrains ?","back":"**Toxicomanes IV**, porteurs de **stimulateur/défibrillateur**, de **voie veineuse centrale**, cardiopathie congénitale avec atteinte droite.","prio":"P2","sec":"s5"},{"id":"fc-152-cffb9a","poly":"cardio","fiche":"152","front":"EI du cœur droit : germe le plus fréquent chez le toxicomane ou le porteur de stimulateur ?","back":"Les **staphylocoques**.","prio":"P2","sec":"s5"},{"id":"fc-152-03907a","poly":"cardio","fiche":"152","front":"EI du cœur droit : signes révélateurs ?","back":"**Signes respiratoires** : pneumopathies récidivantes, souvent **abcédées**, par **embolies pulmonaires septiques**.","prio":"P2","sec":"s5"},{"id":"fc-152-fd1fa3","poly":"cardio","fiche":"152","front":"EI sur prothèse précoce : définition et mécanisme habituel ?","back":"Dans l'**année** qui suit la pose ; souvent **contamination périopératoire**.","prio":"P2","sec":"s5"},{"id":"fc-152-22562d","poly":"cardio","fiche":"152","front":"EI sur prothèse tardive : définition ?","back":"Survenue **plus d'un an** après la pose de la prothèse.","prio":"P3","sec":"s5"},{"id":"fc-152-22bea3","poly":"cardio","fiche":"152","front":"EI sur prothèse : pronostic par rapport à la valve native ?","back":"**Plus sévère**, que l'EI soit précoce ou tardive.","prio":"P2","sec":"s5"},{"id":"fc-152-b04ce8","poly":"cardio","fiche":"152","front":"EI : risque selon le type de prothèse (biologique ou mécanique) ?","back":"**Même risque** d'EI.","prio":"P3","sec":"s5"},{"id":"fc-152-d22a06","poly":"cardio","fiche":"152","front":"EI : mortalité hospitalière ?","back":"**15-30 %**.","prio":"P1","sec":"s6"},{"id":"fc-152-79bc4c","poly":"cardio","fiche":"152","front":"EI : deux principales causes de décès ?","back":"**Insuffisance cardiaque aiguë** et **complications neurologiques**.","prio":"P1","sec":"s6"},{"id":"fc-152-e9f580","poly":"cardio","fiche":"152","front":"EI : quelles formes sont les plus graves ?","back":"EI **sur prothèse** et EI **à staphylocoque**.","prio":"P1","sec":"s6"},{"id":"fc-152-6cebed","poly":"cardio","fiche":"152","front":"EI : foyers infectieux à distance issus des végétations ?","back":"**Abcès spléniques ou rénaux**, **arthrites**, **spondylodiscite**, **méningite**.","prio":"P2","sec":"s6"},{"id":"fc-152-3c4dff","poly":"cardio","fiche":"152","front":"EI : complications de la destruction valvulaire, de l'abcès ou de la désinsertion ?","back":"Fuites valvulaires/paraprothétiques, fistules, **insuffisance cardiaque aiguë** (OAP, choc cardiogénique), **BAV**.","prio":"P2","sec":"s6"},{"id":"fc-152-54a008","poly":"cardio","fiche":"152","front":"EI : complications de l'inflammation systémique ?","back":"AEG, **choc septique**, vascularite, glomérulonéphrite, **anévrismes infectieux**, **hémorragies** (cérébrale…).","prio":"P2","sec":"s6"},{"id":"fc-152-22ca63","poly":"cardio","fiche":"152","front":"EI : citer des facteurs de mauvais pronostic ?","back":"**IC aiguë**, complications **neurologiques**, sepsis mal maîtrisé, **abcès** intracardiaque, **prothèse**, végétations **volumineuses**, *S. aureus*/champignons, terrain fragile.","prio":"P1","sec":"s6"},{"id":"fc-152-769f06","poly":"cardio","fiche":"152","front":"EI : germes très virulents de mauvais pronostic ?","back":"***S. aureus*** et **champignons**.","prio":"P2","sec":"s6"},{"id":"fc-152-d8c2d3","poly":"cardio","fiche":"152","front":"EI : terrain fragile de mauvais pronostic ?","back":"**Âge avancé**, **diabète**, **immunodépression**, insuffisance cardiaque, rénale ou respiratoire préexistante.","prio":"P3","sec":"s6"},{"id":"fc-152-c32c70","poly":"cardio","fiche":"152","front":"EI : quand prévenir le chirurgien cardiaque ?","back":"**Dès que le diagnostic est posé**.","prio":"P1","sec":"s6"},{"id":"fc-152-d2f450","poly":"cardio","fiche":"152","front":"Équipe endocardite : composition minimale ?","back":"**Cardiologues**, **chirurgiens cardiaques**, **infectiologues**, **microbiologistes** (± imageurs), dans un centre des valvulopathies.","prio":"P3","sec":"s6"},{"id":"fc-152-bcda51","poly":"cardio","fiche":"152","front":"Équipe endocardite : intérêt et sollicitation ?","back":"Elle **améliore le pronostic** ; **toujours sollicitée** (patients graves/complexes adressés, sinon avis à distance).","prio":"P3","sec":"s6"},{"id":"fc-152-bebec0","poly":"cardio","fiche":"152","front":"EI : la spondylodiscite est-elle un phénomène inflammatoire ou un foyer septique ?","back":"Un **foyer infectieux à distance** issu des végétations.","prio":"P2","sec":"s6"},{"id":"fc-152-2aeb35","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : proportion ?","back":"**10 %** des EI.","prio":"P1","sec":"s7"},{"id":"fc-152-383f37","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives avec forte présomption : examens complémentaires ?","back":"**Techniques spéciales d'hémocultures**, **sérologies**, **PCR**.","prio":"P2","sec":"s7"},{"id":"fc-152-f1a007","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : 4 grandes causes ?","back":"**Antibiothérapie préalable** · germes à **croissance lente** · germes **intracellulaires** · **endocardites non infectieuses**.","prio":"P2","sec":"s7"},{"id":"fc-152-4ff619","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : germes à croissance lente ou difficile ?","back":"**Streptocoques déficients**, **HACEK**, ***Brucella***, **champignons**.","prio":"P3","sec":"s7"},{"id":"fc-152-59b917","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : germes intracellulaires ?","back":"***Coxiella*** (fièvre Q), ***Chlamydia***, ***Bartonella***, ***Tropheryma whipplei***, ***Mycoplasma***, ***Legionella***.","prio":"P3","sec":"s7"},{"id":"fc-152-041442","poly":"cardio","fiche":"152","front":"EI opérée : devenir des pièces opératoires ?","back":"**Histologie**, **culture** et éventuellement **PCR**.","prio":"P2","sec":"s7"},{"id":"fc-152-108602","poly":"cardio","fiche":"152","front":"EI à S. gallolyticus ou à entérocoque : examen digestif imposé ?","back":"**Coloscopie** à la recherche d'une **tumeur colique**.","prio":"P2","sec":"s7"},{"id":"fc-152-cfdcbe","poly":"cardio","fiche":"152","front":"Traitement de l'EI : citer les 5 volets ?","back":"**Antibiotiques** (ou antifongiques) · indications **chirurgicales** · **complications** · **porte d'entrée** · **surveillance**.","prio":"P2","sec":"s8"},{"id":"fc-152-fbb661","poly":"cardio","fiche":"152","front":"Antibiothérapie de l'EI : 4 caractéristiques et durée ?","back":"**Bactéricide**, **synergique** (plusieurs molécules), **fortes doses**, **IV**, **4 à 6 semaines**.","prio":"P1","sec":"s8"},{"id":"fc-152-4c59bc","poly":"cardio","fiche":"152","front":"Antibiothérapie de l'EI : effet d'une chirurgie sur sa durée ?","back":"**Aucun** : durée **inchangée**.","prio":"P1","sec":"s8"},{"id":"fc-152-e56f02","poly":"cardio","fiche":"152","front":"EI : germe identifié, comment ajuster l'antibiothérapie ?","back":"**Adaptée à l'antibiogramme**, avec l'aide d'un **infectiologue**.","prio":"P2","sec":"s8"},{"id":"fc-152-4fccf1","poly":"cardio","fiche":"152","front":"Antibiothérapie de l'EI : sur quoi adapter les doses ?","back":"Fonctions **rénale** et **hépatique** + **concentrations plasmatiques** d'aminosides et de vancomycine.","prio":"P2","sec":"s8"},{"id":"fc-152-813e48","poly":"cardio","fiche":"152","front":"EI : 3 indications de l'antibiothérapie probabiliste ?","back":"**Forte suspicion**, **sepsis sévère**, **indication chirurgicale urgente** ; juste après les hémocultures, sans attendre le résultat.","prio":"P1","sec":"s8"},{"id":"fc-152-5c8290","poly":"cardio","fiche":"152","front":"EI communautaire sur valve native ou prothèse ≥ 1 an : antibiothérapie probabiliste ?","back":"**Ampicilline + ceftriaxone** (ou oxacilline) **+ gentamicine**, IV.","prio":"P1","sec":"s8"},{"id":"fc-152-aa1783","poly":"cardio","fiche":"152","front":"EI communautaire, allergie à la pénicilline : probabiliste ?","back":"**Céfazoline** (ou vancomycine) **+ gentamicine**.","prio":"P2","sec":"s8"},{"id":"fc-152-543e3b","poly":"cardio","fiche":"152","front":"EI non communautaire ou prothèse < 1 an : antibiothérapie probabiliste ?","back":"**Vancomycine** (ou daptomycine) **+ gentamicine + rifampicine** ; même schéma si allergie.","prio":"P1","sec":"s8"},{"id":"fc-152-fc5245","poly":"cardio","fiche":"152","front":"EI postopératoire précoce sur prothèse : germes et mortalité ?","back":"Germes **hospitaliers** parfois multirésistants, surtout **staphylocoque doré ou blanc** ; mortalité **≈ 50 %**.","prio":"P2","sec":"s8"},{"id":"fc-152-f513dd","poly":"cardio","fiche":"152","front":"EI postopératoire précoce : lésions habituelles et conduite ?","back":"EI souvent aiguë avec **abcès de l'anneau** et **désinsertion** ; **réintervention précoce** le plus souvent.","prio":"P3","sec":"s8"},{"id":"fc-152-c7b799","poly":"cardio","fiche":"152","front":"EI sur prothèse : quand faire l'ETO ?","back":"En cas de **forte suspicion**, et aussi **une fois le diagnostic confirmé** (bilan des lésions).","prio":"P3","sec":"s8"},{"id":"fc-152-46e6ff","poly":"cardio","fiche":"152","front":"EI à SAMS sur valve native : traitement ?","back":"**Cloxacilline** (ou céfazoline) IV, **4 à 6 semaines** ; céfazoline si allergie.","prio":"P1","sec":"s9"},{"id":"fc-152-fc5820","poly":"cardio","fiche":"152","front":"EI à SARM sur valve native : traitement ?","back":"**Vancomycine** IV, **4-6 semaines** (idem si allergie).","prio":"P1","sec":"s9"},{"id":"fc-152-ea2878","poly":"cardio","fiche":"152","front":"EI à SAMS sur prothèse : traitement ?","back":"**Cloxacilline** (ou céfazoline) **+ rifampicine** 6 semaines **+ gentamicine 2 semaines**.","prio":"P1","sec":"s9"},{"id":"fc-152-e73559","poly":"cardio","fiche":"152","front":"EI à SARM sur prothèse : traitement ?","back":"**Vancomycine + rifampicine** 6 semaines **+ gentamicine 2 semaines** (idem si allergie).","prio":"P2","sec":"s9"},{"id":"fc-152-722caf","poly":"cardio","fiche":"152","front":"EI sur prothèse à S. aureus : implication chirurgicale ?","back":"**Indication chirurgicale** (infectieuse) en phase active.","prio":"P2","sec":"s9"},{"id":"fc-152-c40f0e","poly":"cardio","fiche":"152","front":"EI à streptocoque oral ou S. gallolyticus sur valve native : traitement ?","back":"**Pénicilline G** (ou amoxicilline ou ceftriaxone) IV, **4 semaines**.","prio":"P1","sec":"s10"},{"id":"fc-152-a04010","poly":"cardio","fiche":"152","front":"EI à streptocoque sur valve native résistant à la pénicilline : ajout ?","back":"**Gentamicine 2 semaines**.","prio":"P2","sec":"s10"},{"id":"fc-152-ecabc7","poly":"cardio","fiche":"152","front":"EI à streptocoque sur valve native, allergie : traitement ?","back":"**Vancomycine 4 semaines**.","prio":"P2","sec":"s10"},{"id":"fc-152-ddd6f4","poly":"cardio","fiche":"152","front":"EI à streptocoque sur prothèse : traitement ?","back":"**Pénicilline G** (ou amoxicilline ou ceftriaxone) **6 semaines** ; allergie : vancomycine 6 sem + gentamicine 2 sem.","prio":"P2","sec":"s10"},{"id":"fc-152-0e69fe","poly":"cardio","fiche":"152","front":"EI à streptocoque oral : bilan de la porte d'entrée ?","back":"**Panoramique dentaire** + **consultation de stomatologie**.","prio":"P2","sec":"s10"},{"id":"fc-152-e3243f","poly":"cardio","fiche":"152","front":"EI à entérocoque, cas général : traitement ?","back":"**Amoxicilline** (ou ampicilline) **+ ceftriaxone**, **6 semaines** (ou ceftriaxone remplacée par gentamicine 2 semaines).","prio":"P1","sec":"s10"},{"id":"fc-152-a87990","poly":"cardio","fiche":"152","front":"EI à entérocoque : le traitement diffère-t-il entre valve native et prothèse ?","back":"**Non** : même traitement, **6 semaines** dans les deux cas.","prio":"P2","sec":"s10"},{"id":"fc-152-b559cc","poly":"cardio","fiche":"152","front":"EI à entérocoque : allergie ou résistance aux bêtalactamines ?","back":"**Vancomycine 6 semaines + gentamicine 2 semaines**.","prio":"P2","sec":"s10"},{"id":"fc-152-e5af34","poly":"cardio","fiche":"152","front":"EI à entérocoque résistant à la gentamicine : traitement ?","back":"**Amoxicilline** (ou ampicilline) **+ ceftriaxone**, 6 semaines.","prio":"P3","sec":"s10"},{"id":"fc-152-aac46c","poly":"cardio","fiche":"152","front":"EI à entérocoque résistant à la vancomycine : traitement ?","back":"**Daptomycine + ampicilline** (ou fosfomycine), 6 semaines ; allergie : **daptomycine + fosfomycine**.","prio":"P2","sec":"s10"},{"id":"fc-152-81555b","poly":"cardio","fiche":"152","front":"EI à entérocoque : bilan de la porte d'entrée ?","back":"**Coloscopie** ; **ECBU** + échographie (ou scanner) des voies urinaires.","prio":"P2","sec":"s10"},{"id":"fc-152-f47b53","poly":"cardio","fiche":"152","front":"EI : durée d'antibiotiques pour streptocoque versus entérocoque ?","back":"Streptocoque : **4 sem** (native), **6 sem** (prothèse) ; entérocoque : **6 sem** dans les deux cas.","prio":"P1","sec":"s10"},{"id":"fc-152-45e882","poly":"cardio","fiche":"152","front":"Allergie à la pénicilline : quelle prescription est une notion inacceptable ?","back":"**Prescrire une pénicilline**.","prio":"P1","sec":"s11"},{"id":"fc-152-2fef94","poly":"cardio","fiche":"152","front":"EI chez l'allergique à la pénicilline : exceptions à la vancomycine ?","back":"**Céfazoline** pour le SAMS (et 1er choix du probabiliste communautaire) ; **daptomycine + fosfomycine** pour l'entérocoque résistant à la vancomycine.","prio":"P2","sec":"s11"},{"id":"fc-152-3a8afd","poly":"cardio","fiche":"152","front":"EI fongique : traitement anti-infectieux ?","back":"**Antifongiques** à la place des antibiotiques (molécule non précisée).","prio":"P2","sec":"s11"},{"id":"fc-152-dcec2d","poly":"cardio","fiche":"152","front":"EI fongique : implication chirurgicale et porte d'entrée ?","back":"**Indication chirurgicale** (infectieuse) en phase active ; porte d'entrée **cutanée** (*Candida*).","prio":"P2","sec":"s11"},{"id":"fc-152-0363a2","poly":"cardio","fiche":"152","front":"EI : fréquence d'une indication chirurgicale en phase active ?","back":"**Environ 50 %** des cas, sans attendre la fin des antibiotiques.","prio":"P1","sec":"s12"},{"id":"fc-152-5f6dba","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : déroulement du geste ?","back":"**Débridement** des tissus infectés, puis **plastie** si possible, sinon **remplacement** valvulaire (biologique ou mécanique).","prio":"P2","sec":"s12"},{"id":"fc-152-2d7f92","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : 3 familles d'indications ?","back":"**Hémodynamiques**, **infectieuses**, **emboliques** (« HIE »).","prio":"P1","sec":"s12"},{"id":"fc-152-78b18b","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : indications hémodynamiques ?","back":"IC gauche **réfractaire** ou **choc cardiogénique** ; IC gauche ou signe échographique de **mauvaise tolérance**.","prio":"P2","sec":"s12"},{"id":"fc-152-7bba82","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : signes d'infection non contrôlée localement ?","back":"**Abcès**, **fistule**, faux anévrisme, végétations qui **grossissent**, **désinsertion** de prothèse, **BAV**.","prio":"P2","sec":"s12"},{"id":"fc-152-5c5f85","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : indications infectieuses liées au germe ?","back":"EI **fongique** ou à germes **multirésistants** ; EI sur prothèse à ***S. aureus*** ou à **Gram négatif non HACEK**.","prio":"P2","sec":"s12"},{"id":"fc-152-36c662","poly":"cardio","fiche":"152","front":"EI : délai d'hémocultures positives sous antibiotiques qui indique la chirurgie ?","back":"Toujours positives après **plus de 7 jours** (embolies et métastases septiques contrôlées).","prio":"P3","sec":"s12"},{"id":"fc-152-314449","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : indications emboliques ?","back":"Végétation du cœur gauche **≥ 10 mm** persistante après embolie(s) malgré antibiotiques adaptés, ou associée à une autre indication.","prio":"P2","sec":"s12"},{"id":"fc-152-85164e","poly":"cardio","fiche":"152","front":"EI tardive sur prothèse : part du staphylocoque et pronostic ?","back":"Staphylocoque dans **50 %** des cas ; pronostic **meilleur** que l'EI précoce.","prio":"P3","sec":"s12"},{"id":"fc-152-dde171","poly":"cardio","fiche":"152","front":"EI tardive sur prothèse : quand discuter la réintervention ?","back":"**Sepsis non maîtrisé**, **risque embolique** important, **dysfonction sévère** de prothèse, atteinte périvalvulaire avec **désinsertion**.","prio":"P3","sec":"s12"},{"id":"fc-152-58ce0f","poly":"cardio","fiche":"152","front":"EI : faut-il attendre la fin des antibiotiques pour opérer ?","back":"**Non** : on opère dès que l'indication existe.","prio":"P1","sec":"s12"},{"id":"fc-152-0c51c4","poly":"cardio","fiche":"152","front":"EI sur stimulateur, défibrillateur ou cathéter central : geste obligatoire ?","back":"**Extraire tout le matériel** (souvent par voie **percutanée**), puis **réimplanter à distance**.","prio":"P1","sec":"s13"},{"id":"fc-152-05b3b2","poly":"cardio","fiche":"152","front":"EI du cœur droit chez le toxicomane IV : valve et image pulmonaire typiques ?","back":"Végétation **tricuspide** ; pneumopathie bilatérale avec **abcès pulmonaire** (embolies pulmonaires septiques).","prio":"P2","sec":"s13"},{"id":"fc-152-fe1293","poly":"cardio","fiche":"152","front":"EI : porte d'entrée retrouvée dans quelle proportion ?","back":"**50 %** des cas : la chercher **selon le germe**.","prio":"P3","sec":"s13"},{"id":"fc-152-ab3152","poly":"cardio","fiche":"152","front":"EI : place du traitement de la porte d'entrée ?","back":"Il **fait partie du traitement** de l'EI.","prio":"P2","sec":"s13"},{"id":"fc-152-5007b6","poly":"cardio","fiche":"152","front":"EI sous traitement : critères d'efficacité ?","back":"Régression **fièvre** et **syndrome inflammatoire** ; **stérilisation des hémocultures** ; évolution échographique favorable ; **pas de complication**.","prio":"P1","sec":"s14"},{"id":"fc-152-05eb35","poly":"cardio","fiche":"152","front":"EI sous traitement : surveillance de tolérance principale ?","back":"**Fonction rénale** : aminosides, vancomycine, mais aussi **amoxicilline**.","prio":"P1","sec":"s14"},{"id":"fc-152-85aba5","poly":"cardio","fiche":"152","front":"Amoxicilline : mécanismes de toxicité rénale ?","back":"**Réaction immunoallergique** ou **cristallurie** → atteinte interstitielle aiguë ou nécrose tubulaire aiguë.","prio":"P2","sec":"s14"},{"id":"fc-152-aff409","poly":"cardio","fiche":"152","front":"EI sous traitement : examen pour dépister un BAV ?","back":"**ECG**.","prio":"P2","sec":"s14"},{"id":"fc-152-7250f6","poly":"cardio","fiche":"152","front":"EI guérie : groupe de risque du patient ?","back":"**Haut risque** (antécédent d'EI).","prio":"P1","sec":"s15"},{"id":"fc-152-bd5bcd","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI : son efficacité est-elle prouvée ?","back":"**Non**, jamais formellement prouvée.","prio":"P3","sec":"s15"},{"id":"fc-152-feb34a","poly":"cardio","fiche":"152","front":"Prévention de l'EI : document à remettre ?","back":"**Carte de prévention** adaptée au groupe de risque, à montrer au médecin/dentiste.","prio":"P2","sec":"s15"},{"id":"fc-152-f88448","poly":"cardio","fiche":"152","front":"Prévention de l'EI : fréquence du brossage des dents ?","back":"**2 à 3 fois par jour**.","prio":"P3","sec":"s15"},{"id":"fc-152-891f5e","poly":"cardio","fiche":"152","front":"Prévention de l'EI : mesures cutanées et urinaires ?","back":"**Désinfecter les plaies** ; **éradiquer les colonisations bactériennes chroniques** cutanées et urinaires.","prio":"P2","sec":"s15"},{"id":"fc-152-47b74f","poly":"cardio","fiche":"152","front":"Prévention de l'EI : conduite face à une infection bactérienne locale ?","back":"La **traiter par antibiotiques**.","prio":"P3","sec":"s15"},{"id":"fc-152-e426c1","poly":"cardio","fiche":"152","front":"Prévention de l'EI : mesures concernant les voies veineuses ?","back":"**Asepsie stricte** lors des gestes à risque ; **limiter** les voies veineuses et les **changer régulièrement** si besoin prolongé.","prio":"P3","sec":"s15"},{"id":"fc-152-bd4705","poly":"cardio","fiche":"152","front":"Prévention de l'EI : interdits et conduites à tenir pour le patient ?","back":"Pas de **tatouage** ni **piercing** ; pas d'**automédication antibiotique** ; **consulter vite si fièvre**.","prio":"P1","sec":"s15"},{"id":"fc-152-ba5286","poly":"cardio","fiche":"152","front":"Patient à risque d'EI : quelle omission est une notion inacceptable ?","back":"**Oublier les mesures de prévention non médicamenteuses**.","prio":"P1","sec":"s15"},{"id":"fc-152-e75655","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI : soins dentaires concernés ?","back":"Manipulation de la **gencive** ou de la **région périapicale**, ou **effraction de la muqueuse**.","prio":"P1","sec":"s15"},{"id":"fc-152-d5a9c1","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI chez l'adulte (référence item 152) ?","back":"**Amoxicilline 2 g** per os ou IV, **dose unique**, **30-60 min avant** le geste.","prio":"P1","sec":"s15"},{"id":"fc-152-a65677","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI : alternative céphalosporine ?","back":"**Céfazoline** (ou ceftriaxone) **1 g** IM ou IV, 30-60 min avant.","prio":"P2","sec":"s15"},{"id":"fc-152-4de59e","poly":"cardio","fiche":"152","front":"Antibioprophylaxie chez le porteur de valve (item 153) : schéma « en général » ?","back":"**Amoxicilline 3 g**, **1 heure avant**, pour tout geste dentaire à risque infectieux, détartrage compris.","prio":"P3","sec":"s15"},{"id":"fc-152-43bc9b","poly":"cardio","fiche":"152","front":"Fièvre chez un patient à risque d'EI : conduite du patient ?","back":"Prévenir **rapidement son médecin**, présenter sa **carte** ; **aucun antibiotique sans avis médical**.","prio":"P1","sec":"s15"},{"id":"fc-152-565915","poly":"cardio","fiche":"152","front":"EI sans indication opératoire en phase active : chirurgie ultérieure ?","back":"Parfois **chirurgie à distance**, selon les indications habituelles des **valvulopathies**.","prio":"P3","sec":"s15"},{"id":"fc-153-87e2cd","poly":"cardio","fiche":"153","front":"Prothèses valvulaires : 2 grandes familles ?","back":"**Mécanique** et **biologique** (bioprothèse chirurgicale ou **percutanée = TAVI**).","prio":"P1","sec":"s1"},{"id":"fc-153-c8d246","poly":"cardio","fiche":"153","front":"Prothèse valvulaire : risque d'endocardite par rapport à une valve native ?","back":"**Accru** pour toute prothèse (**corps étranger**).","prio":"P1","sec":"s1"},{"id":"fc-153-fa544f","poly":"cardio","fiche":"153","front":"Valve mécanique : composition ?","back":"Partie mécanique en **titane et carbone** ; collerette en tissu type **Dacron** pour la suture.","prio":"P3","sec":"s1"},{"id":"fc-153-ff108b","poly":"cardio","fiche":"153","front":"Valve mécanique : traitement antithrombotique ?","back":"**AVK définitif**, à vie.","prio":"P1","sec":"s1"},{"id":"fc-153-d7cf27","poly":"cardio","fiche":"153","front":"Valve mécanique : place des AOD ?","back":"**Formellement contre-indiqués**, **même transitoirement**.","prio":"P1","sec":"s1"},{"id":"fc-153-f80adb","poly":"cardio","fiche":"153","front":"Valve mécanique : avec quoi relayer l'AVK si besoin ?","back":"**HNF** ou **HBPM** (jamais d'AOD).","prio":"P1","sec":"s1"},{"id":"fc-153-940540","poly":"cardio","fiche":"153","front":"Valve mécanique : durabilité ?","back":"**Excellente**, prévue pour **toute la vie** (plus de 15 ans sans complication).","prio":"P2","sec":"s1"},{"id":"fc-153-cdad40","poly":"cardio","fiche":"153","front":"Bioprothèse chirurgicale : origine habituelle du tissu ?","back":"Surtout **xénogreffe** : péricarde bovin ou équin, valve aortique porcine ; le plus souvent montée sur armature (**stentée**).","prio":"P2","sec":"s1"},{"id":"fc-153-f25bfe","poly":"cardio","fiche":"153","front":"Bioprothèse chirurgicale : durabilité moyenne ?","back":"**Limitée** : **10 ans** en moyenne, parfois moins (sujet jeune, type de prothèse).","prio":"P1","sec":"s1"},{"id":"fc-153-f17b5c","poly":"cardio","fiche":"153","front":"TAVI : principe de pose ?","back":"Tissu animal sur armature métallique type stent, fixé sur l'anneau aortique calcifié par **cathétérisme rétrograde sous anesthésie locale**.","prio":"P2","sec":"s1"},{"id":"fc-153-5347ae","poly":"cardio","fiche":"153","front":"TAVI : durabilité ?","back":"Dégénère comme toute bioprothèse ; durabilité **encore à définir** (très peu de recul au-delà de 5 ans).","prio":"P3","sec":"s1"},{"id":"fc-153-aba15c","poly":"cardio","fiche":"153","front":"Valves mécaniques : 3 générations ?","back":"À **bille** (Starr®, retirée en 2007) · **monodisques** (Björk-Shiley®, Medtronic-Hall®) · **double ailette** (Saint-Jude®…).","prio":"P2","sec":"s1"},{"id":"fc-153-35a6df","poly":"cardio","fiche":"153","front":"Valve mécanique la plus posée aujourd'hui et ses atouts ?","back":"**Double ailette** : bonne hémodynamique, **moins thrombogène**.","prio":"P1","sec":"s1"},{"id":"fc-153-b06f8e","poly":"cardio","fiche":"153","front":"Valve mécanique : les AVK suppriment-ils le risque de thrombose ?","back":"**Non** : ils le **réduisent sans l'annuler**.","prio":"P2","sec":"s1"},{"id":"fc-153-935514","poly":"cardio","fiche":"153","front":"Prothèses en tissu humain : 2 types ?","back":"**Allogreffe/homogreffe** (valve aortique d'un donneur surtout) et **autogreffe**.","prio":"P3","sec":"s1"},{"id":"fc-153-9090e4","poly":"cardio","fiche":"153","front":"Intervention de Ross : principe ?","back":"Racine aortique remplacée par la **racine pulmonaire du patient** ; homogreffe ou xénogreffe en position pulmonaire.","prio":"P3","sec":"s1"},{"id":"fc-153-06e12e","poly":"cardio","fiche":"153","front":"Intervention d'Ozaki : principe ?","back":"Le **péricarde postérieur du patient** sert à fabriquer une valve aortique à trois cusps.","prio":"P3","sec":"s1"},{"id":"fc-153-8ac6c1","poly":"cardio","fiche":"153","front":"Bioprothèse stentless : avantages et inconvénient ?","back":"Meilleure **hémodynamique**, durée parfois plus longue ; mais se soude et se calcifie → **réintervention difficile** (rarement posée).","prio":"P3","sec":"s1"},{"id":"fc-153-7af7ea","poly":"cardio","fiche":"153","front":"TAVI : 2 modes de déploiement ?","back":"**Par ballon** (Sapien 3®) ou **autodéployable** (Evolut R®, Evolut Pro®, recapturables).","prio":"P3","sec":"s1"},{"id":"fc-153-2d16f3","poly":"cardio","fiche":"153","front":"Choix de prothèse : inconvénient de chaque famille ?","back":"Mécanique : risque **thromboembolique** + **saignement** sous anticoagulant ; biologique : **dégénérescence** → réintervention.","prio":"P1","sec":"s2"},{"id":"fc-153-9e65c8","poly":"cardio","fiche":"153","front":"Choix de prothèse : 3 critères ?","back":"**Choix éclairé du patient** · balance **thromboembolique/hémorragique** · risque de **dégénérescence**.","prio":"P2","sec":"s2"},{"id":"fc-153-832ab4","poly":"cardio","fiche":"153","front":"Valve mécanique préférée : âges repères ?","back":"**< 60 ans** en aortique ; **< 65 ans** en mitral.","prio":"P1","sec":"s2"},{"id":"fc-153-99c3b1","poly":"cardio","fiche":"153","front":"Bioprothèse préférée : âges repères ?","back":"**> 65 ans** en aortique ; **> 70 ans** en mitral.","prio":"P1","sec":"s2"},{"id":"fc-153-399462","poly":"cardio","fiche":"153","front":"Bioprothèse mitrale : pourquoi un âge seuil plus élevé qu'en aortique ?","back":"La bioprothèse **mitrale dure moins**.","prio":"P2","sec":"s2"},{"id":"fc-153-a24543","poly":"cardio","fiche":"153","front":"Arguments pour une valve mécanique (hors âge) ?","back":"Souhait du patient ; pas de CI aux AVK ; risque de **dégénérescence précoce** (hypoparathyroïdie, IRC) ; autre indication d'AVK (**FA, MTE**) ; réintervention à haut risque.","prio":"P2","sec":"s2"},{"id":"fc-153-1dd0e6","poly":"cardio","fiche":"153","front":"Maladies exposant à une dégénérescence précoce de bioprothèse ?","back":"**Hypoparathyroïdie** et **IRC**.","prio":"P3","sec":"s2"},{"id":"fc-153-a07387","poly":"cardio","fiche":"153","front":"Arguments pour une bioprothèse (hors âge) ?","back":"Souhait ; **CI aux AVK** ou risque de complication ; **thrombose de valve mécanique malgré INR efficace** ; **désir de grossesse** ; faible risque de réintervention.","prio":"P2","sec":"s2"},{"id":"fc-153-d9a0a2","poly":"cardio","fiche":"153","front":"Désir de grossesse : quel type de prothèse privilégier et pourquoi ?","back":"**Bioprothèse** : les **AVK sont tératogènes**.","prio":"P1","sec":"s2"},{"id":"fc-153-daa417","poly":"cardio","fiche":"153","front":"Valve mécanique : conséquences d'un sous-dosage et d'un surdosage en AVK ?","back":"Sous-dosage : **thrombose** ; surdosage : **saignement**.","prio":"P1","sec":"s2"},{"id":"fc-153-1f640b","poly":"cardio","fiche":"153","front":"Aortique ≥ 60 ans (mitral ≥ 65 ans) sans FA ni risque cardioembolique : prothèse ?","back":"**Bioprothèse**.","prio":"P2","sec":"s2"},{"id":"fc-153-345188","poly":"cardio","fiche":"153","front":"Aortique ≥ 60 ans (mitral ≥ 65 ans) avec FA : prothèse ?","back":"**Valve mécanique**, sauf risque hémorragique élevé ou très élevé (→ bioprothèse).","prio":"P2","sec":"s2"},{"id":"fc-153-0241f7","poly":"cardio","fiche":"153","front":"Aortique < 60 ans (mitral < 65 ans) sans FA : quand préférer une bioprothèse ?","back":"Espérance de vie **très courte (≤ 5 ans)** ; aussi si espérance de vie **< 10-12 ans**, CI ou impossibilité d'anticoaguler, risque hémorragique accru sous AVK, **INR labiles**.","prio":"P3","sec":"s2"},{"id":"fc-153-e7961e","poly":"cardio","fiche":"153","front":"Algorithme de choix : arguments qui orientent vers la bioprothèse ?","back":"Espérance de vie **< 10-12 ans**, CI ou impossibilité d'anticoaguler, risque hémorragique accru sous AVK, **INR labiles**.","prio":"P3","sec":"s2"},{"id":"fc-153-155523","poly":"cardio","fiche":"153","front":"TAVI : indications ?","back":"**RA serré** contre-indiqué à la chirurgie ou à risque **haut ou intermédiaire** (tout âge) ; et **dès 75 ans** quel que soit le risque.","prio":"P1","sec":"s2"},{"id":"fc-153-78075e","poly":"cardio","fiche":"153","front":"Après 75 ans : place du TAVI (ESC 2021) ?","back":"Envisagé **en 1re intention si l'anatomie est favorable**.","prio":"P1","sec":"s2"},{"id":"fc-153-88643d","poly":"cardio","fiche":"153","front":"TAVI : qui décide ?","back":"La **Heart Team** : cardiologues, chirurgiens cardiaques, anesthésistes-réanimateurs, gériatres.","prio":"P2","sec":"s2"},{"id":"fc-153-9c6035","poly":"cardio","fiche":"153","front":"Valve-in-valve : définition ?","back":"**TAVI posé par voie percutanée dans une bioprothèse** chirurgicale ou un TAVI **dégénéré**.","prio":"P2","sec":"s2"},{"id":"fc-153-a4afdb","poly":"cardio","fiche":"153","front":"Valve-in-valve : quand l'anticiper ?","back":"**Dès tout remplacement aortique par bioprothèse**, en Heart Team.","prio":"P3","sec":"s2"},{"id":"fc-153-b0701f","poly":"cardio","fiche":"153","front":"Valve-in-valve : intérêt chez les patients à risque haut ou intermédiaire ?","back":"Éviter une chirurgie **redux** à haut risque.","prio":"P3","sec":"s2"},{"id":"fc-153-b44580","poly":"cardio","fiche":"153","front":"Remplacement d'une seule valve chez un jeune en bonne santé : mortalité périopératoire ?","back":"**Pas plus de 1 à 2 %** ; augmente avec l'âge, le nombre de gestes et les comorbidités.","prio":"P2","sec":"s2"},{"id":"fc-153-8ba683","poly":"cardio","fiche":"153","front":"Bioprothèse : mécanismes de la dégénérescence des feuillets ?","back":"**Calcification** (valve sténosante) ou **déchirure**, surtout commissurale (valve fuyante).","prio":"P2","sec":"s3"},{"id":"fc-153-8fe9ee","poly":"cardio","fiche":"153","front":"Bioprothèse : anticoagulant systématique au long cours ?","back":"**Non justifié** (bioprothèse chirurgicale) et **non indiqué** (TAVI) : risque de thrombose de feuillets **faible**.","prio":"P2","sec":"s3"},{"id":"fc-153-377fe6","poly":"cardio","fiche":"153","front":"Prothèses : 5 familles de complications ?","back":"**T**hromboemboliques · **H**émorragiques · **I**nfectieuses · **D**égénérescence · **D**ésinsertion (THIDD).","prio":"P1","sec":"s3"},{"id":"fc-153-7cd650","poly":"cardio","fiche":"153","front":"Prothèses : complications les plus fréquentes ?","back":"**Thromboemboliques**, surtout sur valve **mécanique**.","prio":"P1","sec":"s3"},{"id":"fc-153-5253af","poly":"cardio","fiche":"153","front":"Complications thromboemboliques des prothèses : principal facteur de risque ?","back":"Une **anticoagulation insuffisante**.","prio":"P1","sec":"s3"},{"id":"fc-153-7b25cb","poly":"cardio","fiche":"153","front":"Valve mécanique sous anticoagulant : risque hémorragique annuel ?","back":"Environ **1,2 % par an**.","prio":"P3","sec":"s3"},{"id":"fc-153-bc54d8","poly":"cardio","fiche":"153","front":"Endocardite précoce sur prothèse (jusqu'à 1 an) : mortalité ?","back":"De l'ordre de **50 %**.","prio":"P1","sec":"s3"},{"id":"fc-153-294a38","poly":"cardio","fiche":"153","front":"Bioprothèse : délai habituel de dégénérescence ?","back":"En général **5 à 15 ans** ; plus tôt en **mitral** et chez le **jeune**.","prio":"P1","sec":"s3"},{"id":"fc-153-a433be","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : fréquence et moment ?","back":"**5 %** des cas, surtout les **premiers mois**.","prio":"P2","sec":"s3"},{"id":"fc-153-083f0b","poly":"cardio","fiche":"153","front":"Valve mécanique : fourchette d'INR cible ?","back":"Entre **2,5 et 4**.","prio":"P1","sec":"s4"},{"id":"fc-153-a1d6fb","poly":"cardio","fiche":"153","front":"INR cible d'une valve mécanique : 2 paramètres qui le déterminent ?","back":"**Risque thrombotique de la prothèse** (modèle) + présence d'**au moins 1 facteur de risque patient**.","prio":"P1","sec":"s4"},{"id":"fc-153-6866ac","poly":"cardio","fiche":"153","front":"Valve mécanique à risque faible : INR cible ?","back":"**2,5** sans facteur patient ; **3,0** avec ≥ 1 facteur.","prio":"P1","sec":"s4"},{"id":"fc-153-b833d6","poly":"cardio","fiche":"153","front":"Valve mécanique à risque moyen : INR cible ?","back":"**3,0** sans facteur patient ; **3,5** avec ≥ 1 facteur.","prio":"P1","sec":"s4"},{"id":"fc-153-afde94","poly":"cardio","fiche":"153","front":"Valve mécanique à risque élevé : INR cible ?","back":"**3,5** sans facteur patient ; **4,0** avec ≥ 1 facteur.","prio":"P1","sec":"s4"},{"id":"fc-153-2e7ed8","poly":"cardio","fiche":"153","front":"Valves mécaniques à risque thrombotique faible : exemples ?","back":"**Carbomedics®**, **Medtronic Hall®**, ATS®, Medtronic Open-Pivot®, **St Jude Medical®**, Sorin Bicarbon®.","prio":"P3","sec":"s4"},{"id":"fc-153-96e294","poly":"cardio","fiche":"153","front":"Valves mécaniques à risque thrombotique moyen ?","back":"**Autres doubles ailettes**, récentes ou à données de suivi insuffisantes.","prio":"P2","sec":"s4"},{"id":"fc-153-8fc42f","poly":"cardio","fiche":"153","front":"Valves mécaniques à risque thrombotique élevé ?","back":"**Starr-Edwards®** (bille), Lillehei-Kaster®, Omniscience®, **Björk-Shiley®** et autres **prothèses à disque**.","prio":"P2","sec":"s4"},{"id":"fc-153-67678a","poly":"cardio","fiche":"153","front":"INR cible des valves mécaniques : facteurs de risque liés au patient ?","back":"Remplacement **mitral ou tricuspide** · **ATCD thromboembolique** · **FA** · **sténose mitrale** (tout degré) · **FEVG < 35 %**.","prio":"P1","sec":"s4"},{"id":"fc-153-112314","poly":"cardio","fiche":"153","front":"INR cible : une sténose mitrale peu serrée compte-t-elle comme facteur patient ?","back":"**Oui**, quel que soit son degré.","prio":"P2","sec":"s4"},{"id":"fc-153-f90687","poly":"cardio","fiche":"153","front":"INR cible d'une valve mécanique : qui le fixe et selon quoi ?","back":"**Individuellement avec le cardiologue** : type et position de prothèse, facteurs emboliques, **risque hémorragique**.","prio":"P2","sec":"s4"},{"id":"fc-153-c1f92c","poly":"cardio","fiche":"153","front":"Valve mécanique : rythme des contrôles d'INR ?","back":"**1 à 2 fois/semaine** jusqu'à l'équilibre, puis **au moins 1 fois/mois**.","prio":"P1","sec":"s4"},{"id":"fc-153-e19946","poly":"cardio","fiche":"153","front":"Valve mécanique : écart toléré autour de l'INR cible ?","back":"**± 0,5** point au maximum.","prio":"P1","sec":"s4"},{"id":"fc-153-abee5d","poly":"cardio","fiche":"153","front":"AVK : définition d'un patient bien équilibré ?","back":"**Au moins 70 %** des INR dans la cible.","prio":"P2","sec":"s4"},{"id":"fc-153-47cca4","poly":"cardio","fiche":"153","front":"Valve mécanique : quand débuter l'AVK ?","back":"**Tôt**, dès les **premiers jours postopératoires**, puis **à vie**.","prio":"P1","sec":"s5"},{"id":"fc-153-fc524c","poly":"cardio","fiche":"153","front":"Valve mécanique : où inscrire l'INR cible ?","back":"Dans le **carnet de surveillance** de l'anticoagulant.","prio":"P2","sec":"s5"},{"id":"fc-153-d07afa","poly":"cardio","fiche":"153","front":"Relais héparine-AVK : délai d'efficacité de l'AVK ?","back":"**4 à 6 jours**.","prio":"P2","sec":"s5"},{"id":"fc-153-3b9af7","poly":"cardio","fiche":"153","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"Après **≥ 4-5 jours** de chevauchement et **2 INR efficaces à 24 h** d'intervalle.","prio":"P2","sec":"s5"},{"id":"fc-153-e93b78","poly":"cardio","fiche":"153","front":"HBPM chez le porteur de valve mécanique : statut ?","back":"**Pas d'AMM**, mais acceptées comme **alternative à l'HNF** par les recommandations européennes.","prio":"P3","sec":"s5"},{"id":"fc-153-bdf139","poly":"cardio","fiche":"153","front":"Valve mécanique : ajout d'un antiagrégant à l'AVK en Europe ?","back":"**Non**, sauf **transitoire** (stent récent) ou **définitif** (thromboembolie sous INR efficace).","prio":"P1","sec":"s5"},{"id":"fc-153-0a6107","poly":"cardio","fiche":"153","front":"Valve mécanique : structure recommandée pour l'éducation thérapeutique ?","back":"Une **clinique des anticoagulants**.","prio":"P3","sec":"s5"},{"id":"fc-153-09864e","poly":"cardio","fiche":"153","front":"AVK : contenu de l'éducation thérapeutique ?","back":"Éviter les **coprescriptions**, connaître les **seuils d'alerte** de l'INR, consulter si **saignement**, signaler l'AVK à tout médecin.","prio":"P2","sec":"s5"},{"id":"fc-153-eb6b39","poly":"cardio","fiche":"153","front":"Automesure de l'INR : remboursement et proportion de patients concernés ?","back":"**Remboursée depuis 2017** (porteurs de valve mécanique) ; possible chez **≈ 50 %** des patients.","prio":"P2","sec":"s5"},{"id":"fc-153-84a4f0","poly":"cardio","fiche":"153","front":"Valve mécanique et geste à haut risque hémorragique : gestion de l'AVK ?","back":"**Arrêt 4 à 5 jours avant** + relais préopératoire par **héparine à dose curative**.","prio":"P1","sec":"s5"},{"id":"fc-153-1732a9","poly":"cardio","fiche":"153","front":"Geste à haut risque hémorragique sous AVK : INR visé le jour de l'acte ?","back":"**< 1,5** (**< 1,2** en neurochirurgie).","prio":"P2","sec":"s5"},{"id":"fc-153-252cc7","poly":"cardio","fiche":"153","front":"Valve mécanique : reprise de l'AVK après un geste ?","back":"Dans les **24-48 h**, sous couverture d'héparine jusqu'à INR efficace.","prio":"P2","sec":"s5"},{"id":"fc-153-175edc","poly":"cardio","fiche":"153","front":"Après chirurgie sous AVK : délai minimal de reprise de l'héparine curative ?","back":"**Pas avant la 6ᵉ heure** postopératoire.","prio":"P3","sec":"s5"},{"id":"fc-153-1d3462","poly":"cardio","fiche":"153","front":"Geste à risque hémorragique modéré (soins dentaires) sous AVK : conduite ?","back":"Le plus souvent **sans arrêter l'AVK**, après avoir vérifié un INR dans le **bas de la fourchette**.","prio":"P2","sec":"s5"},{"id":"fc-153-af1aec","poly":"cardio","fiche":"153","front":"Arrêt simple de l'AVK 3-4 jours sans relais : applicable à une valve mécanique ?","back":"**Non** (réservé à TVP/EP au-delà du 3ᵉ mois ou FA à faible risque embolique).","prio":"P2","sec":"s5"},{"id":"fc-153-f97490","poly":"cardio","fiche":"153","front":"Surdosage en AVK sans saignement : lieu de prise en charge et conduite générale ?","back":"Le plus souvent en **ambulatoire** ; chercher la **cause** ; **INR de contrôle le lendemain**.","prio":"P2","sec":"s5"},{"id":"fc-153-531794","poly":"cardio","fiche":"153","front":"Valve mécanique (cible 3), 4 < INR < 6 sans saignement : conduite ?","back":"Pas de saut de prise, pas de vitamine K : **adapter la posologie**.","prio":"P3","sec":"s5"},{"id":"fc-153-9e61a1","poly":"cardio","fiche":"153","front":"Valve mécanique (cible 3), 6 < INR < 10 sans saignement : conduite ?","back":"**Sauter une prise** ; avis cardiologique pour discuter **1-2 mg de vitamine K per os**.","prio":"P3","sec":"s5"},{"id":"fc-153-836498","poly":"cardio","fiche":"153","front":"Valve mécanique, INR > 10 sans saignement : conduite ?","back":"**Avis spécialisé sans délai** ou **hospitalisation**.","prio":"P3","sec":"s5"},{"id":"fc-153-0b90b6","poly":"cardio","fiche":"153","front":"Porteur de valve mécanique : prescription constituant une notion inacceptable ?","back":"Prescrire un **AOD** (anti-IIa ou anti-Xa).","prio":"P1","sec":"s5"},{"id":"fc-153-9f7d17","poly":"cardio","fiche":"153","front":"Bioprothèse aortique en rythme sinusal : antithrombotique ?","back":"**Aspirine ou AVK 3 mois**, puis **plus rien**.","prio":"P1","sec":"s6"},{"id":"fc-153-dddda4","poly":"cardio","fiche":"153","front":"Bioprothèse aortique : autres options citées que l'aspirine ?","back":"**AOD** ou simple **antiagrégant** pendant **au moins 3 mois** (AVK par certaines équipes).","prio":"P3","sec":"s6"},{"id":"fc-153-7b0652","poly":"cardio","fiche":"153","front":"Bioprothèse mitrale en rythme sinusal : antithrombotique ?","back":"**AVK les 3 premiers mois**, puis plus rien.","prio":"P1","sec":"s6"},{"id":"fc-153-07d35b","poly":"cardio","fiche":"153","front":"Bioprothèse tricuspide ou plastie mitrale : antithrombotique ?","back":"**AVK 3 mois**, puis plus rien.","prio":"P2","sec":"s6"},{"id":"fc-153-2ea47f","poly":"cardio","fiche":"153","front":"Bioprothèse après le 3ᵉ mois : AOD autorisés ?","back":"**Oui**, si l'indication **n'est pas valvulaire** (FA…).","prio":"P2","sec":"s6"},{"id":"fc-153-85bbff","poly":"cardio","fiche":"153","front":"Bioprothèse + FA : faut-il anticoaguler au long cours ?","back":"**Oui** : la FA impose une anticoagulation au long cours.","prio":"P1","sec":"s6"},{"id":"fc-153-0ac068","poly":"cardio","fiche":"153","front":"Bioprothèse mitrale + FA : AOD dès le postopératoire ?","back":"**Toléré dès le postopératoire** immédiat.","prio":"P2","sec":"s6"},{"id":"fc-153-3707e4","poly":"cardio","fiche":"153","front":"Bioprothèse aortique + FA : AOD ?","back":"**Envisageable dès le postopératoire**.","prio":"P3","sec":"s6"},{"id":"fc-153-816a65","poly":"cardio","fiche":"153","front":"TAVI en rythme sinusal : antithrombotique ?","back":"**Aspirine faible dose seule**, au long cours ; **pas d'anticoagulation efficace**.","prio":"P1","sec":"s6"},{"id":"fc-153-b13418","poly":"cardio","fiche":"153","front":"TAVI + FA ou maladie thromboembolique : antithrombotique ?","back":"**AVK ou AOD seul**, au long cours, **sans aspirine** associée.","prio":"P1","sec":"s6"},{"id":"fc-153-dc2357","poly":"cardio","fiche":"153","front":"AOD : valve mécanique versus bioprothèse ?","back":"**Interdits** sur valve mécanique ; **permis** sur bioprothèse (FA dès le postopératoire, ou après 3 mois si indication non valvulaire).","prio":"P1","sec":"s6"},{"id":"fc-153-c9a8a4","poly":"cardio","fiche":"153","front":"Porteur de prothèse : pourquoi une prophylaxie draconienne à vie ?","back":"**Sujet à risque infectieux** : risque majoré d'**endocardite** ; prévenir et traiter tout foyer, surtout **ORL et dentaire**.","prio":"P1","sec":"s7"},{"id":"fc-153-5b53ed","poly":"cardio","fiche":"153","front":"Porteur de prothèse chez le dentiste : document à présenter ?","back":"Sa **carte d'antibioprophylaxie**.","prio":"P2","sec":"s7"},{"id":"fc-153-8085cf","poly":"cardio","fiche":"153","front":"Porteur de prothèse : le détartrage nécessite-t-il une antibioprophylaxie ?","back":"**Oui** : tout geste dentaire à risque infectieux, **détartrage compris**.","prio":"P1","sec":"s7"},{"id":"fc-153-64fe4d","poly":"cardio","fiche":"153","front":"Porteur de prothèse : fréquence minimale du suivi dentaire ?","back":"**Au moins 2 fois par an**, contrôlé à l'interrogatoire.","prio":"P1","sec":"s7"},{"id":"fc-153-1bab5d","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire : dose de référence d'amoxicilline (item 152) ?","back":"**2 g** per os ou IV, **30-60 min avant**, prise unique.","prio":"P1","sec":"s7"},{"id":"fc-153-66adba","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire selon l'item 153 (« en général ») ?","back":"**Amoxicilline 3 g**, **1 heure avant** les soins.","prio":"P2","sec":"s7"},{"id":"fc-153-9c0d10","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire : alternative par céphalosporine ?","back":"**Céfazoline** (ou ceftriaxone) **1 g IM ou IV**, 30-60 min avant.","prio":"P2","sec":"s7"},{"id":"fc-153-7850aa","poly":"cardio","fiche":"153","front":"Points clés item 152 : molécules de l'antibioprophylaxie résumées ?","back":"**Amoxicilline ou clindamycine** 30-60 min avant.","prio":"P3","sec":"s7"},{"id":"fc-153-71923d","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire : soins concernés (item 152) ?","back":"Manipulation de la **gencive** ou de la **région périapicale**, ou **effraction muqueuse**.","prio":"P2","sec":"s7"},{"id":"fc-153-9a663c","poly":"cardio","fiche":"153","front":"Après remplacement valvulaire : quand l'ETT postopératoire précoce et pourquoi ?","back":"**Dans les premiers jours** ; essentielle pour **dépister les complications**.","prio":"P2","sec":"s8"},{"id":"fc-153-2193e5","poly":"cardio","fiche":"153","front":"Après remplacement valvulaire : réadaptation, quand et combien de temps ?","back":"Vers le **8ᵉ jour**, centre de **réadaptation cardiorespiratoire** pour **3 à 4 semaines**.","prio":"P2","sec":"s8"},{"id":"fc-153-7377fe","poly":"cardio","fiche":"153","front":"Porteur de prothèse : rythme du suivi par le médecin traitant ?","back":"À **1 mois**, puis **tous les 3 mois** (clinique + équilibre de l'AVK).","prio":"P1","sec":"s8"},{"id":"fc-153-2f92f8","poly":"cardio","fiche":"153","front":"Porteur de prothèse : quand l'ETT de référence ?","back":"Au **2ᵉ-4ᵉ mois**, chez le cardiologue.","prio":"P1","sec":"s8"},{"id":"fc-153-817035","poly":"cardio","fiche":"153","front":"ETT de référence : pourquoi attendre le 2ᵉ-4ᵉ mois ?","back":"Une fois corrigées l'**anémie** et la **tachycardie** postopératoires (qui augmentent le débit).","prio":"P2","sec":"s8"},{"id":"fc-153-8e62f5","poly":"cardio","fiche":"153","front":"Porteur de prothèse : fréquence du suivi cardiologique au long cours ?","back":"**1 à 2 fois/an** ; suivi spécialisé **au minimum annuel**.","prio":"P1","sec":"s8"},{"id":"fc-153-8c830b","poly":"cardio","fiche":"153","front":"Porteur de prothèse : les 3 documents ?","back":"**Carte de porteur de prothèse** · **carnet de surveillance de l'anticoagulant** · **carte d'antibioprophylaxie**.","prio":"P1","sec":"s8"},{"id":"fc-153-88e393","poly":"cardio","fiche":"153","front":"Carte de porteur de prothèse : informations et moment de remise ?","back":"**Type, diamètre, numéro de série** ; remise **à la sortie de chirurgie cardiaque**.","prio":"P3","sec":"s8"},{"id":"fc-153-f9968c","poly":"cardio","fiche":"153","front":"Suivi du porteur de prothèse : 5 volets ?","back":"**Cartes**, **clinique**, **ECG**, **échocardiographie**, **biologie** (INR).","prio":"P2","sec":"s8"},{"id":"fc-153-fa03f5","poly":"cardio","fiche":"153","front":"Bioprothèse : auscultation normale ?","back":"Bruits **identiques à une valve native** ; en aortique, **petit souffle éjectionnel systolique** normal.","prio":"P2","sec":"s8"},{"id":"fc-153-db2548","poly":"cardio","fiche":"153","front":"Valve mécanique : auscultation normale ?","back":"Bruits d'ouverture et surtout de fermeture **intenses, claqués, métalliques** (doubles ailettes récentes moins bruyantes).","prio":"P2","sec":"s8"},{"id":"fc-153-e6ffe2","poly":"cardio","fiche":"153","front":"Prothèse : modifications auscultatoires pathologiques ?","back":"Bruits **moins intenses** ou **variables** (hors FA) ; **souffle systolique** nouveau/renforcé ; **bruit diastolique** surajouté.","prio":"P1","sec":"s8"},{"id":"fc-153-b58c59","poly":"cardio","fiche":"153","front":"Porteur de prothèse : points à vérifier à chaque consultation ?","back":"Pas de **symptômes**, de **fièvre** ni foyer infectieux, ni manifestation **ischémique** ou **hémorragique** ; suivi **dentaire** régulier.","prio":"P2","sec":"s8"},{"id":"fc-153-b34e2c","poly":"cardio","fiche":"153","front":"Porteur de prothèse : dyspnée ou récidive d'insuffisance cardiaque, conduite ?","back":"Suspecter une **dysfonction de prothèse** → **réhospitalisation**.","prio":"P1","sec":"s8"},{"id":"fc-153-2c5170","poly":"cardio","fiche":"153","front":"Porteur de prothèse : 3 situations où ne pas adresser au spécialiste est inacceptable ?","back":"Patient **symptomatique** · **souffle de novo** (symptomatique ou non) · **suivi annuel**.","prio":"P1","sec":"s8"},{"id":"fc-153-4c3208","poly":"cardio","fiche":"153","front":"Porteur de prothèse : apports et limites de l'ECG ?","back":"Surveille le **rythme** (régression d'HVG/HVD) ; **ne renseigne pas spécifiquement sur la prothèse**.","prio":"P2","sec":"s9"},{"id":"fc-153-37db4c","poly":"cardio","fiche":"153","front":"Porteur de prothèse : principal intérêt de l'ECG ?","back":"Dépister un **passage en FA**, surtout avec une prothèse **mitrale**.","prio":"P2","sec":"s9"},{"id":"fc-153-7ce8a8","poly":"cardio","fiche":"153","front":"Valve mécanique sans complication : rythme de l'ETT ?","back":"**Tous les 1 à 2 ans**.","prio":"P1","sec":"s9"},{"id":"fc-153-2366e3","poly":"cardio","fiche":"153","front":"Bioprothèse conventionnelle : rythme de l'ETT ?","back":"À **3 mois**, **1 an**, puis **chaque année**.","prio":"P1","sec":"s9"},{"id":"fc-153-b1ea67","poly":"cardio","fiche":"153","front":"Prothèses justifiant une vigilance échographique accrue ?","back":"**TAVI**, bioprothèses de **dernière génération**, situations à risque de **dégénérescence précoce**.","prio":"P3","sec":"s9"},{"id":"fc-153-d08352","poly":"cardio","fiche":"153","front":"Prothèse : rôle respectif ETT et ETO ?","back":"**ETT** = surveillance ; **ETO** = diagnostic des **dysfonctions** (seulement si suspicion).","prio":"P1","sec":"s9"},{"id":"fc-153-aa625d","poly":"cardio","fiche":"153","front":"Prothèse : 3 suspicions imposant une ETO systématique ?","back":"**Thrombose**, **endocardite**, **désinsertion**.","prio":"P1","sec":"s9"},{"id":"fc-153-75fcb1","poly":"cardio","fiche":"153","front":"Prothèse mitrale : intérêt particulier de l'ETO ?","back":"Elle est **très bien vue** par voie transœsophagienne.","prio":"P3","sec":"s9"},{"id":"fc-153-dc801b","poly":"cardio","fiche":"153","front":"Dysfonction de prothèse : imagerie de recours ?","back":"**Imagerie multimodale** : ETO, **radiocinéma**, scanner, TEP-scanner.","prio":"P3","sec":"s9"},{"id":"fc-153-33ee49","poly":"cardio","fiche":"153","front":"Complications thromboemboliques : valve mécanique ou bioprothèse ?","back":"**Beaucoup plus** fréquentes sur valve **mécanique**.","prio":"P1","sec":"s10"},{"id":"fc-153-5ef859","poly":"cardio","fiche":"153","front":"Thromboses de prothèse : période de risque maximal ?","back":"La **1re année** (collerette non endothélialisée) ; le risque **persiste** ensuite.","prio":"P2","sec":"s10"},{"id":"fc-153-305a45","poly":"cardio","fiche":"153","front":"Thrombose de prothèse : situations à risque plus élevé ?","back":"Prothèse **mitrale** · prothèse **ancienne** (bille) · **FA** · **dysfonction VG**.","prio":"P2","sec":"s10"},{"id":"fc-153-8bbcfd","poly":"cardio","fiche":"153","front":"Embolies systémiques d'origine prothétique : localisation principale ?","back":"**Cérébrales dans 70 %** des cas (AIT, AVC).","prio":"P1","sec":"s10"},{"id":"fc-153-3a653c","poly":"cardio","fiche":"153","front":"Embolies d'origine prothétique : autres localisations ?","back":"**Ischémie aiguë de membre**, **IDM** par embolie coronaire, **infarctus rénal ou splénique**.","prio":"P3","sec":"s10"},{"id":"fc-153-2a13ae","poly":"cardio","fiche":"153","front":"Thrombose non obstructive de valve mécanique : terrain et diagnostic ?","back":"Surtout prothèses **mitrales** ; thrombus sur la **face atriale** vu en **ETO**.","prio":"P2","sec":"s10"},{"id":"fc-153-076c47","poly":"cardio","fiche":"153","front":"Thromboembolie sous INR efficace (valve mécanique) : conduite ?","back":"Ajout **définitif** d'un **antiagrégant**.","prio":"P2","sec":"s10"},{"id":"fc-153-428571","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : présentation clinique ?","back":"Accidents **brutaux** : **OAP**, **syncope**, **choc**, voire **mort subite**.","prio":"P1","sec":"s10"},{"id":"fc-153-8f28f5","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : auscultation ?","back":"**Bruits de prothèse atténués** ; souffle systolique (aortique) ou **roulement diastolique** (mitrale).","prio":"P1","sec":"s10"},{"id":"fc-153-a8118c","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : examens diagnostiques ?","back":"**Radiocinéma** (jeu diminué) ; **ETT + ETO** (gradients élevés, thrombus) ; **scanner injecté synchronisé**.","prio":"P2","sec":"s10"},{"id":"fc-153-4bd308","poly":"cardio","fiche":"153","front":"Valve mécanique mitrale : gradient moyen transmitral normal ?","back":"**< 6 mmHg**.","prio":"P3","sec":"s10"},{"id":"fc-153-b56246","poly":"cardio","fiche":"153","front":"Thrombose de bioprothèse : sur quel type surtout ?","back":"Les prothèses **percutanées** (TAVI) ; plus rarement chirurgicales.","prio":"P2","sec":"s10"},{"id":"fc-153-e63fb1","poly":"cardio","fiche":"153","front":"Thrombose de bioprothèse : signe ETT évocateur ?","back":"Gradients qui montent **brutalement** (**> 10 mmHg**, gradient moyen jusqu'à > 20) **sans calcification** des cusps.","prio":"P2","sec":"s10"},{"id":"fc-153-b734b1","poly":"cardio","fiche":"153","front":"Thrombose de bioprothèse : confirmation et traitement ?","back":"**ETO** (image d'addition) ± scanner (hypodense) ; **anticoagulation par AVK ou AOD**.","prio":"P2","sec":"s10"},{"id":"fc-153-a1098f","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : premier examen biologique ?","back":"**INR en urgence** (anticoagulation souvent insuffisante).","prio":"P1","sec":"s10"},{"id":"fc-153-3cde76","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : lieu d'hospitalisation et traitement médical ?","back":"**USIC** ; **héparine IV à la seringue + aspirine** (bolus IV puis per os).","prio":"P1","sec":"s10"},{"id":"fc-153-f92f56","poly":"cardio","fiche":"153","front":"Thrombose de valve mécanique : indications de réintervention urgente ?","back":"Thrombose **aiguë** (mortalité **30 %**) ou ailette bloquée **non réversible** sous héparine-aspirine.","prio":"P2","sec":"s10"},{"id":"fc-153-5ee509","poly":"cardio","fiche":"153","front":"Thrombose de valve mécanique : indications de la thrombolyse ?","back":"**Chirurgie contre-indiquée** ou forme **subaiguë résistante** à l'anticoagulation.","prio":"P2","sec":"s10"},{"id":"fc-153-efe00c","poly":"cardio","fiche":"153","front":"Thrombose de prothèse : pourquoi penser aux hémocultures ?","back":"**Fébricule** possible : distinction (ou association) avec une **endocardite** parfois difficile.","prio":"P2","sec":"s10"},{"id":"fc-153-cb34c7","poly":"cardio","fiche":"153","front":"Fièvre inexpliquée chez un porteur de prothèse : premier geste ?","back":"**Hémocultures systématiques avant toute antibiothérapie**, puis échocardiographie.","prio":"P1","sec":"s11"},{"id":"fc-153-ff6e35","poly":"cardio","fiche":"153","front":"Fièvre chez un porteur de prothèse : 2 notions inacceptables ?","back":"Antibiothérapie **à l'aveugle** ; **ne pas penser à l'endocardite**.","prio":"P1","sec":"s11"},{"id":"fc-153-f9af9f","poly":"cardio","fiche":"153","front":"EI postopératoire précoce sur prothèse : germes ?","back":"Germes **hospitaliers** parfois multirésistants, surtout **staphylocoque doré ou blanc** (contamination peropératoire).","prio":"P1","sec":"s11"},{"id":"fc-153-8000c5","poly":"cardio","fiche":"153","front":"EI postopératoire précoce : présentation et lésions ?","back":"En général **aiguë**, avec **abcès de l'anneau** et **désinsertion**.","prio":"P2","sec":"s11"},{"id":"fc-153-e92dc5","poly":"cardio","fiche":"153","front":"EI postopératoire précoce : délai maximal de révélation ?","back":"**Jusqu'à 1 an** après la chirurgie.","prio":"P2","sec":"s11"},{"id":"fc-153-f07880","poly":"cardio","fiche":"153","front":"EI postopératoire précoce : traitement habituel ?","back":"**Réintervention précoce** le plus souvent.","prio":"P2","sec":"s11"},{"id":"fc-153-cb4abf","poly":"cardio","fiche":"153","front":"EI tardive sur prothèse : germes ?","back":"Proches de la valve native, mais **staphylocoque dans 50 %** des cas.","prio":"P2","sec":"s11"},{"id":"fc-153-c778c4","poly":"cardio","fiche":"153","front":"EI tardive sur prothèse : pronostic ?","back":"**Meilleur** que l'EI précoce.","prio":"P2","sec":"s11"},{"id":"fc-153-02f01f","poly":"cardio","fiche":"153","front":"EI tardive sur prothèse : indications de réintervention ?","back":"**Sepsis non maîtrisé**, **risque embolique** important, **dysfonction sévère**, **atteinte périvalvulaire** (désinsertion).","prio":"P2","sec":"s11"},{"id":"fc-153-1ef2f5","poly":"cardio","fiche":"153","front":"EI sur prothèse : intérêt du TEP-scanner ?","back":"Aide au **diagnostic** et **bilan des emboles** ; fixation focale autour de la prothèse ; utile **dès le postopératoire**.","prio":"P2","sec":"s11"},{"id":"fc-153-afccf5","poly":"cardio","fiche":"153","front":"EI sur prothèse : qui discute le dossier ?","back":"Un **staff multidisciplinaire** (**équipe endocardite**).","prio":"P2","sec":"s11"},{"id":"fc-153-30b188","poly":"cardio","fiche":"153","front":"EI sur prothèse < 1 an : antibiothérapie probabiliste ?","back":"**Vancomycine** (ou daptomycine) **+ gentamicine + rifampicine**.","prio":"P1","sec":"s11"},{"id":"fc-153-1ca6b0","poly":"cardio","fiche":"153","front":"EI sur prothèse ≥ 1 an, communautaire : antibiothérapie probabiliste ?","back":"**Ampicilline + ceftriaxone** (ou oxacilline) **+ gentamicine**.","prio":"P2","sec":"s11"},{"id":"fc-153-5a28f7","poly":"cardio","fiche":"153","front":"EI sur prothèse à staphylocoque méti-S : traitement ?","back":"**Cloxacilline** (ou céfazoline) **+ rifampicine** 6 semaines **+ gentamicine 2 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-153-0bf16c","poly":"cardio","fiche":"153","front":"EI sur prothèse à streptocoque oral : traitement ?","back":"**Pénicilline G** (ou amoxicilline ou ceftriaxone) **6 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-153-661144","poly":"cardio","fiche":"153","front":"EI sur prothèse : durée des schémas antibiotiques ?","back":"**6 semaines**, inchangée même si chirurgie.","prio":"P1","sec":"s11"},{"id":"fc-153-4b8a6f","poly":"cardio","fiche":"153","front":"EI sur prothèse : indications infectieuses de chirurgie liées au germe ?","back":"**Staphylococcus aureus** ou bactéries **à Gram négatif non HACEK**.","prio":"P2","sec":"s11"},{"id":"fc-153-da9987","poly":"cardio","fiche":"153","front":"EI : risque selon prothèse biologique ou mécanique ?","back":"**Le même** ; pronostic plus sévère que sur valve native.","prio":"P3","sec":"s11"},{"id":"fc-153-bbbd79","poly":"cardio","fiche":"153","front":"Hémorragies sous AVK : types possibles ?","back":"**Cérébral**, **digestif**, **hématurie**, ménométrorragies, hématome post-traumatique.","prio":"P3","sec":"s12"},{"id":"fc-153-cebc6c","poly":"cardio","fiche":"153","front":"Saignement digestif ou hématurie sous AVK : que rechercher ?","back":"Une **lésion organique sous-jacente**.","prio":"P2","sec":"s12"},{"id":"fc-153-e622c0","poly":"cardio","fiche":"153","front":"Hémorragie grave sous AVK : critères ?","back":"Non contrôlable par moyens usuels · **instabilité hémodynamique** · geste hémostatique · **transfusion** · localisation menaçant le pronostic vital/fonctionnel.","prio":"P1","sec":"s12"},{"id":"fc-153-14e07f","poly":"cardio","fiche":"153","front":"Hémorragie sous AVK : mesures locales possibles ?","back":"**Compression**, hémostatique local (colle), **vasoconstricteur** local (adrénaline), **embolisation**.","prio":"P3","sec":"s12"},{"id":"fc-153-446590","poly":"cardio","fiche":"153","front":"Hémorragie non grave sous AVK : conduite ?","back":"Souvent en **ambulatoire** ; **INR en urgence** ; corriger un surdosage ; rechercher la cause.","prio":"P2","sec":"s12"},{"id":"fc-153-3aebb0","poly":"cardio","fiche":"153","front":"Traumatisme crânien sous AVK : conduite ?","back":"**INR en urgence**, **scanner cérébral en urgence**, hospitalisation **au moins 24 h**.","prio":"P1","sec":"s12"},{"id":"fc-153-0c30f2","poly":"cardio","fiche":"153","front":"Hémorragie grave sous AVK : antidotes ?","back":"**Vitamine K** + **CCP (PPSB)** ; INR en urgence sans attendre le résultat pour traiter.","prio":"P2","sec":"s12"},{"id":"fc-153-b3b6f8","poly":"cardio","fiche":"153","front":"Valve mécanique et hémorragie sévère : gestion de l'anticoagulation ?","back":"**Arrêter l'AVK** mais **garder obligatoirement une héparine** (HNF : **TCA 1,5 à 2 fois le témoin**).","prio":"P2","sec":"s12"},{"id":"fc-153-203289","poly":"cardio","fiche":"153","front":"Valve mécanique : quand interrompre toute anticoagulation ?","back":"**Très temporairement**, seulement si le saignement **menace la vie** (**hémorragie intracrânienne**).","prio":"P2","sec":"s12"},{"id":"fc-153-80b872","poly":"cardio","fiche":"153","front":"CCP et vitamine K : pourquoi les associer ?","back":"CCP d'action **très rapide mais courte** ; vitamine K agit en **quelques heures**.","prio":"P3","sec":"s12"},{"id":"fc-153-af259a","poly":"cardio","fiche":"153","front":"Après CCP : surveillance de l'INR ?","back":"**À 30 min** (CCP complémentaire si > 1,5), puis **6-8 h** après, puis **1 fois/jour**.","prio":"P3","sec":"s12"},{"id":"fc-153-250d8b","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : définition ?","back":"Altération **non infectieuse** des feuillets (**calcifications** ou **déchirure**) → **sténose et/ou fuite**.","prio":"P1","sec":"s13"},{"id":"fc-153-1ef477","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : facteurs de précocité ?","back":"Type de substitut, site **mitral > aortique**, âge **jeune > âgé**.","prio":"P2","sec":"s13"},{"id":"fc-153-38d981","poly":"cardio","fiche":"153","front":"Bioprothèse : délai moyen de réopération selon les notions indispensables ?","back":"En moyenne **10 ans** après la pose.","prio":"P3","sec":"s13"},{"id":"fc-153-3cd470","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : signes d'appel ?","back":"**Souffle** qui apparaît ou change, **symptômes d'effort**, cusps calcifiées ou prothèse sténosante/fuyante à l'écho, **IC**.","prio":"P2","sec":"s13"},{"id":"fc-153-8ba495","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : examens diagnostiques ?","back":"**ETT** ; **scanner** souvent nécessaire pour la distinguer d'une **thrombose**.","prio":"P2","sec":"s13"},{"id":"fc-153-e9c58d","poly":"cardio","fiche":"153","front":"Dégénérescence sévère et symptomatique : traitement ?","back":"**Réintervention** (souvent à risque, redux) ou **valve-in-valve** percutané, discuté en Heart Team.","prio":"P1","sec":"s13"},{"id":"fc-153-899874","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : conséquence hémodynamique ?","back":"**Fuite paraprothétique**.","prio":"P2","sec":"s14"},{"id":"fc-153-f64caa","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : 2 mécanismes ?","back":"**Spontanée** (sutures lâchées sur tissus fragiles) ou, le plus souvent, **endocardite infectieuse**.","prio":"P2","sec":"s14"},{"id":"fc-153-22c38c","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : souffle selon la position ?","back":"**Diastolique** si prothèse aortique ; **systolique** si prothèse mitrale.","prio":"P2","sec":"s14"},{"id":"fc-153-900f37","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : signes d'appel ?","back":"**Souffle nouveau**, flux de régurgitation anormal à l'écho, **anémie hémolytique**, insuffisance cardiaque.","prio":"P2","sec":"s14"},{"id":"fc-153-de707d","poly":"cardio","fiche":"153","front":"Hémolyse mécanique : bilan biologique ?","back":"**LDH élevées**, **haptoglobine basse**, **schizocytes**.","prio":"P2","sec":"s14"},{"id":"fc-153-c1ce1f","poly":"cardio","fiche":"153","front":"Hémolyse : quel marqueur signe l'origine mécanique ?","back":"Les **schizocytes** (hématies fragmentées).","prio":"P2","sec":"s14"},{"id":"fc-153-d5bf8e","poly":"cardio","fiche":"153","front":"Désinsertion importante et symptomatique : traitement ?","back":"Réintervention **chirurgicale** ou **percutanée** avec un **plug** dans la zone désinsérée.","prio":"P3","sec":"s14"},{"id":"fc-153-1c4f00","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : quelle cause rechercher systématiquement ?","back":"Une **endocardite** (hémocultures, échographie).","prio":"P2","sec":"s14"},{"id":"fc-153-af77e4","poly":"cardio","fiche":"153","front":"Bioprothèse dont les gradients montent : dégénérescence ou thrombose ?","back":"Dégénérescence : **progressive**, cusps **calcifiées** ; thrombose : **brutale**, **sans calcification**.","prio":"P1","sec":"s15"},{"id":"fc-153-ce167b","poly":"cardio","fiche":"153","front":"Porteur de prothèse avec AIT ou AVC : examens ?","back":"**INR** et **ETO** (thrombose obstructive ou non).","prio":"P2","sec":"s15"},{"id":"fc-153-ac8039","poly":"cardio","fiche":"153","front":"Porteur de prothèse avec souffle nouveau sans symptôme : conduite ?","back":"**Avis cardiologique**, même asymptomatique ; ETT.","prio":"P1","sec":"s15"},{"id":"fc-153-10c169","poly":"cardio","fiche":"153","front":"Porteur de prothèse fébrile : quelles complications peuvent coexister ?","back":"**Thrombose** et **endocardite**.","prio":"P2","sec":"s15"},{"id":"fc-153-004099","poly":"cardio","fiche":"153","front":"Survie après remplacement valvulaire : déterminants ?","back":"**Maladie initiale**, son **retentissement cardiaque**, **comorbidités**, **complications des prothèses**.","prio":"P3","sec":"s16"},{"id":"fc-153-79f51b","poly":"cardio","fiche":"153","front":"Porteur de prothèse : 2 contraintes à vie ?","back":"**Observance de l'anticoagulant** (valve mécanique) et **prophylaxie de l'endocardite** (toutes).","prio":"P1","sec":"s16"},{"id":"fc-153-7b325b","poly":"cardio","fiche":"153","front":"Valve mécanique : objectif principal du suivi par le médecin traitant ?","back":"L'**équilibre parfait** de l'anticoagulation.","prio":"P1","sec":"s16"},{"id":"fc-153-8930fa","poly":"cardio","fiche":"153","front":"Remplacement percutané : situations où il est en essor ?","back":"**Sténose aortique sur valve native** et **bioprothèse dégénérée**, dans des indications sélectionnées.","prio":"P3","sec":"s16"},{"id":"fc-153-1e6084","poly":"cardio","fiche":"153","front":"Porteur de prothèse : notion inacceptable concernant l'éducation ?","back":"**Oublier l'éducation** : prévention de l'EI et, si besoin, anticoagulation efficace.","prio":"P1","sec":"s16"},{"id":"fc-153-94d651","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire chez un allergique à la pénicilline : notion inacceptable ?","back":"Prescrire une **pénicilline** malgré l'allergie.","prio":"P1","sec":"s7"},{"id":"fc-153-15aa47","poly":"cardio","fiche":"153","front":"Valve-in-valve à anticiper, espérance de vie > 10 ans : quelle bioprothèse chirurgicale préférer ?","back":"Une bioprothèse **qui s'y prête** : **stentée**, **bien visible**, à **feuillets internes courts**.","prio":"P3","sec":"s2"},{"id":"fc-153-b3c48b","poly":"cardio","fiche":"153","front":"Prévention de l'endocardite : mesures non médicamenteuses ?","back":"**Hygiène buccodentaire**, dentiste 2 fois/an, désinfection des plaies, **éviter tatouages et piercings**, limiter les voies veineuses, **pas d'automédication antibiotique**, consulter vite si fièvre.","prio":"P2","sec":"s7"},{"id":"fc-153-f4377b","poly":"cardio","fiche":"153","front":"EI sur prothèse : caractéristiques de l'antibiothérapie ?","back":"**Bactéricide**, molécules **synergiques**, **fortes doses**, **IV**, durée prolongée ; adaptée à l'antibiogramme avec l'infectiologue.","prio":"P2","sec":"s11"},{"id":"fc-153-9d159a","poly":"cardio","fiche":"153","front":"EI : part des cas avec chirurgie indiquée en phase active ?","back":"Environ **50 %** : prévenir le chirurgien cardiaque **dès le diagnostic**.","prio":"P3","sec":"s11"},{"id":"fc-153-c7b799","poly":"cardio","fiche":"153","front":"EI sur prothèse : quand faire l'ETO ?","back":"En cas de **forte suspicion**, et **aussi une fois le diagnostic confirmé** (bilan précis des lésions).","prio":"P2","sec":"s11"},{"id":"fc-153-adab29","poly":"cardio","fiche":"153","front":"EI sur prothèse : quand débuter une antibiothérapie probabiliste ?","back":"Forte suspicion, **sepsis sévère** ou chirurgie urgente, toujours **après les hémocultures**.","prio":"P2","sec":"s11"},{"id":"fc-153-58dd94","poly":"cardio","fiche":"153","front":"EI sur prothèse à staphylocoque méti-R : traitement ?","back":"**Vancomycine + rifampicine** 6 semaines **+ gentamicine 2 semaines**.","prio":"P3","sec":"s11"},{"id":"fc-153-e6272b","poly":"cardio","fiche":"153","front":"EI sur prothèse à entérocoque : traitement ?","back":"**Amoxicilline** (ou ampicilline) **+ ceftriaxone** (ou gentamicine à sa place) : **6 semaines** (gentamicine **2 semaines**).","prio":"P3","sec":"s11"},{"id":"fc-153-7757c8","poly":"cardio","fiche":"153","front":"Surdosage en AVK sur valve mécanique (cible 3) : quelle colonne du tableau ne pas appliquer ?","back":"Celle de l'**INR cible 2,5** (saut de prise dès 4 < INR < 6 ; arrêt + vitamine K si INR > 6).","prio":"P3","sec":"s5"},{"id":"fc-153-283999","poly":"cardio","fiche":"153","front":"Relais par héparine autour d'un geste : risques propres ?","back":"Complications **hémorragiques et thrombotiques**, malgré une apparence rassurante.","prio":"P3","sec":"s5"},{"id":"fc-153-8173d9","poly":"cardio","fiche":"153","front":"Après une thrombose de valve mécanique : mesures à la sortie ?","back":"AVK à vie avec **INR cible à adapter** + **éducation renforcée** (le **sous-dosage** est la cause principale).","prio":"P2","sec":"s10"},{"id":"fc-153-d283cb","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : examens de confirmation ?","back":"**ETT** et surtout **ETO** (systématique si suspicion) : fuite paraprothétique.","prio":"P2","sec":"s14"},{"id":"fc-203-682fa9","poly":"cardio","fiche":"203","front":"Dyspnée : définition ?","back":"**Sensation subjective** de gêne respiratoire lors d'une activité qui normalement n'en provoque pas.","prio":"P1","sec":"s1"},{"id":"fc-203-8e8e8d","poly":"cardio","fiche":"203","front":"Dyspnée et insuffisance respiratoire : exemple de dyspnée sans insuffisance respiratoire ?","back":"**Anémie aiguë**.","prio":"P1","sec":"s1"},{"id":"fc-203-1d0f00","poly":"cardio","fiche":"203","front":"Exemple d'insuffisance respiratoire sans dyspnée ?","back":"**Coma**.","prio":"P1","sec":"s1"},{"id":"fc-203-6b2ba8","poly":"cardio","fiche":"203","front":"Dyspnée aiguë versus chronique : délais d'installation ?","back":"Aiguë : **heures à jours** ; chronique : **semaines à mois**.","prio":"P1","sec":"s1"},{"id":"fc-203-4f546e","poly":"cardio","fiche":"203","front":"Orthopnée : définition ?","back":"Dyspnée en **décubitus**.","prio":"P1","sec":"s1"},{"id":"fc-203-8a9c17","poly":"cardio","fiche":"203","front":"Platypnée : définition ?","back":"Dyspnée en **orthostatisme** (debout).","prio":"P1","sec":"s1"},{"id":"fc-203-7a1ce6","poly":"cardio","fiche":"203","front":"NYHA I : définition ?","back":"**Aucune gêne** lors des efforts habituels.","prio":"P2","sec":"s1"},{"id":"fc-203-11e8fd","poly":"cardio","fiche":"203","front":"NYHA II : définition ?","back":"Gêne aux **efforts importants** : marche rapide ou en côte, escaliers **≥ 2 étages**.","prio":"P1","sec":"s1"},{"id":"fc-203-8886b1","poly":"cardio","fiche":"203","front":"NYHA III : définition ?","back":"Gêne aux **efforts peu intenses** : marche à plat, escaliers **< 2 étages**.","prio":"P1","sec":"s1"},{"id":"fc-203-083e8c","poly":"cardio","fiche":"203","front":"NYHA IV : définition ?","back":"Gêne **au repos** ou aux **efforts minimes** (se laver, s'habiller).","prio":"P1","sec":"s1"},{"id":"fc-203-2e347d","poly":"cardio","fiche":"203","front":"Échelle MRC : nombre de stades ?","back":"**5 stades, de 0 à 4** (version pneumologique).","prio":"P2","sec":"s1"},{"id":"fc-203-cde9d7","poly":"cardio","fiche":"203","front":"MRC stade 0 ?","back":"Dyspnée seulement lors d'un **exercice intense**.","prio":"P3","sec":"s1"},{"id":"fc-203-cc29be","poly":"cardio","fiche":"203","front":"MRC stade 1 ?","back":"Dyspnée à la **marche rapide à plat** ou en montant une **pente légère**.","prio":"P3","sec":"s1"},{"id":"fc-203-fb1119","poly":"cardio","fiche":"203","front":"MRC stade 2 ?","back":"Marche à plat **plus lente que les gens du même âge**, ou arrêt à son propre rythme.","prio":"P3","sec":"s1"},{"id":"fc-203-83badd","poly":"cardio","fiche":"203","front":"MRC stade 3 ?","back":"Arrêt après environ **100 m** ou quelques minutes de marche.","prio":"P2","sec":"s1"},{"id":"fc-203-9a6d06","poly":"cardio","fiche":"203","front":"MRC stade 4 ?","back":"Empêche de **sortir de chez soi**, ou dès l'**habillage**.","prio":"P3","sec":"s1"},{"id":"fc-203-ae73df","poly":"cardio","fiche":"203","front":"Dyspnée : éléments de l'interrogatoire ?","back":"**Terrain** · **rapidité d'installation** · **circonstances** (effort, position, facteurs déclenchants, horaire) · **intensité** · **signes associés**.","prio":"P2","sec":"s2"},{"id":"fc-203-c71b00","poly":"cardio","fiche":"203","front":"Dyspnée inspiratoire : orientation ?","back":"Cause **laryngée**.","prio":"P1","sec":"s2"},{"id":"fc-203-edbe0f","poly":"cardio","fiche":"203","front":"Dyspnée expiratoire : orientation ?","back":"Cause **bronchique** (asthme, BPCO).","prio":"P1","sec":"s2"},{"id":"fc-203-f7ec2e","poly":"cardio","fiche":"203","front":"Polypnée et bradypnée : seuils ?","back":"Polypnée **> 20 cycles/min** ; bradypnée **< 10 cycles/min**.","prio":"P1","sec":"s2"},{"id":"fc-203-25c4c2","poly":"cardio","fiche":"203","front":"Dyspnée de Kussmaul : rythme et orientation ?","back":"Inspiration, pause, expiration, pause ; **acidose métabolique**.","prio":"P1","sec":"s2"},{"id":"fc-203-5539ef","poly":"cardio","fiche":"203","front":"Dyspnée de Cheyne-Stokes : rythme et orientation ?","back":"Polypnée **croissante puis décroissante** entrecoupée d'**apnées** ; **IC grave** (origine centrale).","prio":"P1","sec":"s2"},{"id":"fc-203-e1f3bd","poly":"cardio","fiche":"203","front":"Hyperpnée et hypopnée : définitions ?","back":"Hyperpnée : volume courant **augmenté** ; hypopnée (oligopnée) : volume courant **diminué**.","prio":"P3","sec":"s2"},{"id":"fc-203-f5b5b0","poly":"cardio","fiche":"203","front":"Dyspnée : examens physiques à ne pas oublier en dehors des poumons ?","back":"**Cardiovasculaire** complet (IC, **TVP**), **ORL**, **thyroïdien**, **neuromusculaire**.","prio":"P2","sec":"s2"},{"id":"fc-203-119e3a","poly":"cardio","fiche":"203","front":"Dyspnée : éléments d'orientation à l'auscultation pulmonaire ?","back":"Normale, **crépitants**, **sibilants**, râles bronchiques, **abolition du murmure vésiculaire**.","prio":"P3","sec":"s2"},{"id":"fc-203-1ebd64","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : 3 mécanismes traduits par les signes de gravité ?","back":"**Épuisement ventilatoire**, **hypoxémie/hypercapnie**, **défaillance circulatoire**.","prio":"P2","sec":"s3"},{"id":"fc-203-b55649","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : signes de lutte (muscles accessoires) ?","back":"**Tirage** sus-sternal/sus-claviculaire, creusement intercostal, **battement des ailes du nez**, **balancement thoraco-abdominal**, expiration abdominale active.","prio":"P1","sec":"s3"},{"id":"fc-203-9e5356","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : signes de gravité généraux et circulatoires ?","back":"**Cyanose**, sueurs, **tachycardie > 120/min**, **marbrures**, angoisse, **SpO₂ < 90 %**.","prio":"P1","sec":"s3"},{"id":"fc-203-55d01b","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : signes de gravité neurologiques ?","back":"**Astérixis** (encéphalopathie respiratoire), **agitation**, **somnolence**, coma.","prio":"P1","sec":"s3"},{"id":"fc-203-4f0c03","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : conduite si SpO₂ < 90 % ?","back":"**Oxygène**.","prio":"P1","sec":"s3"},{"id":"fc-203-3f2e2a","poly":"cardio","fiche":"203","front":"Dyspnée aiguë avec signes de choc : priorité ?","back":"**Traiter le choc** avant l'analyse de la dyspnée.","prio":"P1","sec":"s3"},{"id":"fc-203-6e54d5","poly":"cardio","fiche":"203","front":"Exacerbation de BPCO : signes de gravité ?","back":"Dyspnée de **repos**, cyanose, désaturation, **polypnée > 25/min**, défaillance hémodynamique, signes neurologiques, **hypercapnie**.","prio":"P1","sec":"s3"},{"id":"fc-203-39daff","poly":"cardio","fiche":"203","front":"Asthme aigu grave : signes ?","back":"**Thorax bloqué** en inflation, **disparition des sibilants et du murmure**, pouls paradoxal possible, **parole impossible**.","prio":"P1","sec":"s3"},{"id":"fc-203-c6c51e","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : causes dont la gravité est souvent sous-estimée ?","back":"**Laryngées** (œdème de Quincke) et **neuromusculaires** (polyradiculonévrites).","prio":"P2","sec":"s3"},{"id":"fc-203-664081","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : quelle omission est une notion inacceptable ?","back":"**Oublier les examens de 1re intention**.","prio":"P1","sec":"s4"},{"id":"fc-203-2e87ce","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : bilan de 1re intention ?","back":"**Gazométrie artérielle**, **ECG**, **radiographie thoracique**, NFP, iono, glycémie, **BNP/NT-proBNP**, **D-dimères** si suspicion d'EP.","prio":"P1","sec":"s4"},{"id":"fc-203-dec0ed","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : apport de la gazométrie artérielle ?","back":"**Gravité** (hypoxémie, hypercapnie) ; parfois orientation (**effet shunt** de l'EP).","prio":"P2","sec":"s4"},{"id":"fc-203-bbb792","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : apport de l'ECG ?","back":"Signes d'**EP**, de **coronaropathie**, de **trouble du rythme**.","prio":"P2","sec":"s4"},{"id":"fc-203-5bfd82","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : ce que recherche la radiographie du thorax ?","back":"Anomalie de la **paroi**, de la **plèvre**, du **parenchyme**, du **médiastin** ; **cardiomégalie**.","prio":"P2","sec":"s4"},{"id":"fc-203-3ec168","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : seuil de BNP rendant l'IC peu probable ?","back":"**BNP < 100 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-203-7d9080","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : seuil de NT-proBNP rendant l'IC peu probable ?","back":"**NT-proBNP < 300 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-203-97f668","poly":"cardio","fiche":"203","front":"NT-proBNP : seuils selon l'âge (ESC 2021) ?","back":"**> 450** avant 55 ans ; **> 900** de 55 à 75 ans ; **> 1 800 pg/mL** après 75 ans.","prio":"P3","sec":"s4"},{"id":"fc-203-c9cdf0","poly":"cardio","fiche":"203","front":"D-dimères : seuil et condition d'exclusion de l'EP ?","back":"**< 500 µg/L**, si probabilité clinique **faible ou intermédiaire**.","prio":"P1","sec":"s4"},{"id":"fc-203-a3c7ab","poly":"cardio","fiche":"203","front":"Suspicion d'EP : examens de 2e intention ?","back":"**Échodoppler veineux** des MI et/ou **angioscanner pulmonaire** et/ou **scintigraphie V/Q**.","prio":"P1","sec":"s4"},{"id":"fc-203-d8bd94","poly":"cardio","fiche":"203","front":"Dyspnée : autres examens de 2e intention (hors EP) ?","back":"**Échocardiographie doppler**, **EFR**, cathétérisme cardiaque, épreuve d'effort métabolique.","prio":"P2","sec":"s4"},{"id":"fc-203-38e620","poly":"cardio","fiche":"203","front":"Dyspnée aiguë de l'adulte : 3 causes les plus fréquentes ?","back":"**OAP**, **embolie pulmonaire**, **décompensation d'une maladie respiratoire chronique**.","prio":"P1","sec":"s5"},{"id":"fc-203-b45566","poly":"cardio","fiche":"203","front":"Dyspnée aiguë de l'enfant : 3 causes les plus fréquentes ?","back":"**Corps étranger inhalé**, **laryngite**, **épiglottite**.","prio":"P1","sec":"s5"},{"id":"fc-203-0e53c3","poly":"cardio","fiche":"203","front":"Arbre décisionnel de la dyspnée aiguë : première question ?","back":"**Signes de choc ?**","prio":"P1","sec":"s5"},{"id":"fc-203-e4ab34","poly":"cardio","fiche":"203","front":"Dyspnée expiratoire avec sibilants ou ronchi : causes ?","back":"**Asthme**, **BPCO**, **pseudo-asthme cardiaque**.","prio":"P1","sec":"s5"},{"id":"fc-203-c41007","poly":"cardio","fiche":"203","front":"Dyspnée aiguë avec crépitants : orientations ?","back":"**OAP** (IVG) ; attention pseudo-asthme et **SDRA** ; avec fièvre/condensation : **pneumopathie**.","prio":"P1","sec":"s5"},{"id":"fc-203-d08af3","poly":"cardio","fiche":"203","front":"Dyspnée aiguë avec syndrome pleural : causes ?","back":"**Pneumothorax** ou **épanchement pleural**.","prio":"P1","sec":"s5"},{"id":"fc-203-8358fe","poly":"cardio","fiche":"203","front":"Dyspnée aiguë isolée (auscultation normale) : causes à chercher ?","back":"**EP**, **sepsis sévère**, **anémie**, **acidose métabolique**, **atteinte neuromusculaire** ; psychogène en dernier.","prio":"P1","sec":"s5"},{"id":"fc-203-68192b","poly":"cardio","fiche":"203","front":"Dyspnée psychogène (hyperventilation) : statut diagnostique ?","back":"**Diagnostic d'élimination**.","prio":"P1","sec":"s5"},{"id":"fc-203-9e68a5","poly":"cardio","fiche":"203","front":"Atteinte neuromusculaire : particularité de la dyspnée ?","back":"**Tardive**, peut précéder de peu l'**arrêt respiratoire**.","prio":"P1","sec":"s5"},{"id":"fc-203-5f9bb8","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : cause cardiaque la plus fréquente ?","back":"L'**œdème aigu du poumon**.","prio":"P1","sec":"s6"},{"id":"fc-203-142e7d","poly":"cardio","fiche":"203","front":"OAP : signes cliniques ?","back":"**Orthopnée**, wheezing, **crépitants bilatéraux**, expectoration **rose saumonée**.","prio":"P1","sec":"s6"},{"id":"fc-203-cf355e","poly":"cardio","fiche":"203","front":"OAP : terrain et facteur déclenchant typiques ?","back":"Cardiopathie connue, **ATCD d'infarctus** ; déclencheur type **FA**.","prio":"P2","sec":"s6"},{"id":"fc-203-8caf15","poly":"cardio","fiche":"203","front":"OAP : arguments paracliniques ?","back":"Radio : **œdème alvéolaire**, cardiomégalie ; ECG : **onde Q**, FA rapide ; **BNP/NT-proBNP élevé**.","prio":"P1","sec":"s6"},{"id":"fc-203-befbe8","poly":"cardio","fiche":"203","front":"OAP : argument diagnostique thérapeutique ?","back":"Amélioration sous **diurétique** ou **trinitrine IV**.","prio":"P2","sec":"s6"},{"id":"fc-203-dc1cba","poly":"cardio","fiche":"203","front":"Pseudo-asthme cardiaque : clinique et signification ?","back":"Orthopnée, **sibilants ± crépitants** ; **équivalent d'OAP** (forme bronchospastique).","prio":"P2","sec":"s6"},{"id":"fc-203-0b52d3","poly":"cardio","fiche":"203","front":"Tamponnade : signes cliniques ?","back":"Orthopnée, tachycardie, **bruits du cœur assourdis**, **poumons normaux**, **turgescence jugulaire**, **pouls paradoxal**.","prio":"P2","sec":"s6"},{"id":"fc-203-a061c4","poly":"cardio","fiche":"203","front":"Pouls paradoxal : définition ?","back":"Pouls qui **diminue à l'inspiration profonde**.","prio":"P3","sec":"s6"},{"id":"fc-203-feab1b","poly":"cardio","fiche":"203","front":"Tamponnade : contexte et tableau hémodynamique habituel ?","back":"Complication d'une **péricardite avec épanchement** ; en général **collapsus** ou **état de choc** avec signes d'**insuffisance ventriculaire droite**.","prio":"P3","sec":"s6"},{"id":"fc-203-c5678d","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : troubles du rythme pouvant être en cause ?","back":"**Troubles du rythme supraventriculaire** et **tachycardie ventriculaire**.","prio":"P3","sec":"s6"},{"id":"fc-203-0bef22","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : 5 causes cardiaques ?","back":"**OAP**, **pseudo-asthme cardiaque**, **tamponnade**, **troubles du rythme**, **choc cardiogénique**.","prio":"P2","sec":"s6"},{"id":"fc-203-a5ee89","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : contextes favorisants ?","back":"**Alitement**, **long voyage**, **immobilisation plâtrée**, **période postopératoire**.","prio":"P1","sec":"s7"},{"id":"fc-203-31a76e","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : mode de début ?","back":"En règle **très brutal** ; douleur thoracique fréquente mais **inconstante**.","prio":"P2","sec":"s7"},{"id":"fc-203-0741b6","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : auscultation ?","back":"**Souvent normale**, sauf **tachycardie**.","prio":"P1","sec":"s7"},{"id":"fc-203-95bddc","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : anomalie gazométrique ?","back":"**Effet shunt** : **hypoxie avec hypocapnie**.","prio":"P1","sec":"s7"},{"id":"fc-203-57c315","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : complication à distance ?","back":"**Hypertension pulmonaire post-embolique**.","prio":"P2","sec":"s7"},{"id":"fc-203-090fbf","poly":"cardio","fiche":"203","front":"EP : 2 tableaux trompeurs chez le patient respiratoire ?","back":"EP sur **terrain bronchoemphysémateux** ; EP **associée** à une exacerbation de BPCO.","prio":"P2","sec":"s7"},{"id":"fc-203-0ac37d","poly":"cardio","fiche":"203","front":"Crise d'asthme : signes ?","back":"Dyspnée **expiratoire** avec **sibilants**.","prio":"P2","sec":"s8"},{"id":"fc-203-a9bfcd","poly":"cardio","fiche":"203","front":"Exacerbation de BPCO : déclencheur fréquent et signes ?","back":"**Surinfection bronchique** ; majoration de la dyspnée, de la toux, du volume ou de la **purulence des crachats**.","prio":"P2","sec":"s8"},{"id":"fc-203-e3bd43","poly":"cardio","fiche":"203","front":"Pneumopathie infectieuse : signes ?","back":"**Fièvre** + toux/expectoration purulente ; **foyer de crépitants** ± condensation ; opacité **systématisée**.","prio":"P2","sec":"s8"},{"id":"fc-203-bd1602","poly":"cardio","fiche":"203","front":"SDRA : définition ?","back":"Défaillance pulmonaire aiguë très sévère : **perméabilité alvéolocapillaire augmentée**, **œdème lésionnel**, mortalité élevée.","prio":"P2","sec":"s8"},{"id":"fc-203-0d4ee6","poly":"cardio","fiche":"203","front":"SDRA : causes ?","back":"**Pneumopathie**, **sepsis**, **inhalation**, EP, **traumatisme**, état de choc, toxique.","prio":"P2","sec":"s8"},{"id":"fc-203-f3d467","poly":"cardio","fiche":"203","front":"SDRA : principal diagnostic différentiel ?","back":"L'**œdème pulmonaire hémodynamique** (OAP cardiogénique).","prio":"P2","sec":"s8"},{"id":"fc-203-00a68d","poly":"cardio","fiche":"203","front":"Pneumothorax : terrain ?","back":"Sujet **longiligne**, **tabac**, **emphysème**.","prio":"P2","sec":"s8"},{"id":"fc-203-75fc05","poly":"cardio","fiche":"203","front":"Pneumothorax : signes d'examen et radiologiques ?","back":"Abolition des **vibrations vocales** et du **murmure**, **tympanisme** ; **hyperclarté** radiographique.","prio":"P1","sec":"s8"},{"id":"fc-203-7e52c2","poly":"cardio","fiche":"203","front":"BPCO : quelle décompensation cardiaque une surinfection bronchopulmonaire peut-elle déclencher ?","back":"Une **poussée d'insuffisance cardiaque** (les deux maladies s'intriquent).","prio":"P2","sec":"s8"},{"id":"fc-203-0b33d4","poly":"cardio","fiche":"203","front":"BPCO encombré : piège diagnostique concernant l'OAP ?","back":"L'**OAP est souvent diagnostiqué par excès**.","prio":"P2","sec":"s8"},{"id":"fc-203-8b44a8","poly":"cardio","fiche":"203","front":"Atélectasie : origines possibles ?","back":"**Bénigne** ou **maligne**.","prio":"P3","sec":"s8"},{"id":"fc-203-4b8244","poly":"cardio","fiche":"203","front":"Dyspnée laryngotrachéale : signes ?","back":"Dyspnée **inspiratoire**, bradypnée inspiratoire, **cornage**, **tirage** ; **dysphonie** fréquente si origine laryngée.","prio":"P1","sec":"s9"},{"id":"fc-203-72d05c","poly":"cardio","fiche":"203","front":"Dyspnée laryngée : causes ?","back":"**Œdème de Quincke**, **corps étranger** inhalé, chez l'enfant **épiglottite** et **laryngite**.","prio":"P1","sec":"s9"},{"id":"fc-203-ad0453","poly":"cardio","fiche":"203","front":"Œdème de Quincke : contexte fréquent ?","back":"**Choc anaphylactique** (œdème de la glotte).","prio":"P2","sec":"s9"},{"id":"fc-203-e5458c","poly":"cardio","fiche":"203","front":"Dyspnée trachéale : causes ?","back":"**Sténose tumorale**, **corps étranger**, **granulome post-intubation**.","prio":"P3","sec":"s9"},{"id":"fc-203-7b3193","poly":"cardio","fiche":"203","front":"Dyspnée inspiratoire d'installation progressive : orientation ?","back":"Cause **néoplasique**.","prio":"P2","sec":"s9"},{"id":"fc-203-994cf0","poly":"cardio","fiche":"203","front":"Dyspnée laryngée : 2 consignes immédiates ?","back":"**Laisser le patient assis** ; **ne pas examiner l'oropharynx**.","prio":"P1","sec":"s9"},{"id":"fc-203-a746ac","poly":"cardio","fiche":"203","front":"Dyspnée : causes neurologiques ?","back":"**Atteintes bulbaires**, **polyradiculonévrite**, **myasthénie**.","prio":"P2","sec":"s9"},{"id":"fc-203-73a309","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : causes rares à connaître ?","back":"Pseudo-asthme, tamponnade, chocs, acidose, hyperthermie, sténoses trachéales, **intoxication au CO**, **pneumocystose**.","prio":"P3","sec":"s9"},{"id":"fc-203-eeaec3","poly":"cardio","fiche":"203","front":"Causes extrathoraciques (acidose, anémie) : type de trouble ventilatoire ?","back":"Plutôt une **polypnée** qu'une dyspnée.","prio":"P3","sec":"s9"},{"id":"fc-203-cf84a8","poly":"cardio","fiche":"203","front":"Dyspnée : notion indispensable sur les causes non cardiopulmonaires ?","back":"Savoir évoquer les causes **extracardiaques et extrapulmonaires** (anémie, ORL…).","prio":"P2","sec":"s10"},{"id":"fc-203-f060be","poly":"cardio","fiche":"203","front":"OAP cardiogénique : diagnostic différentiel lésionnel ?","back":"**OAP lésionnel du SDRA** (contexte d'agression : infection, sepsis, inhalation, traumatisme, choc).","prio":"P2","sec":"s10"},{"id":"fc-203-c04667","poly":"cardio","fiche":"203","front":"Dyspnée aiguë grave : examens de 2e intention aux urgences ?","back":"**Angioscanner** ou scanner pulmonaire, **échocardiographie**, selon l'orientation.","prio":"P3","sec":"s11"},{"id":"fc-203-90576a","poly":"cardio","fiche":"203","front":"Item 203 : traitements cités directement (sans dose) ?","back":"**Oxygène** dès SpO₂ < 90 % ; réponse au **diurétique** ou à la **trinitrine IV** comme argument d'OAP.","prio":"P3","sec":"s11"},{"id":"fc-203-d34153","poly":"cardio","fiche":"203","front":"OAP au domicile : prise en charge initiale ?","back":"Patient **assis/demi-assis**, **furosémide IV**, **nitrés sublinguaux** si PAS > 100 mmHg, Samu selon gravité, hospitalisation.","prio":"P1","sec":"s12"},{"id":"fc-203-d4ec45","poly":"cardio","fiche":"203","front":"OAP : dose de furosémide ?","back":"**1 mg/kg IV**, à répéter si besoin ; adaptée ensuite à la **diurèse**.","prio":"P1","sec":"s12"},{"id":"fc-203-7134b7","poly":"cardio","fiche":"203","front":"OAP : condition des nitrés sublinguaux ?","back":"**PAS > 100 mmHg**.","prio":"P1","sec":"s12"},{"id":"fc-203-8f4dfa","poly":"cardio","fiche":"203","front":"OAP : trinitrine IV, dose et condition ?","back":"**1 mg/h**, adaptée à la PA, si **PAS ≥ 110 mmHg**.","prio":"P1","sec":"s12"},{"id":"fc-203-ee4c91","poly":"cardio","fiche":"203","front":"OAP : objectif d'oxygénation ?","back":"**SaO₂ > 90 %** (sonde nasale ou masque) ; prudence si risque d'hypercapnie.","prio":"P2","sec":"s12"},{"id":"fc-203-509031","poly":"cardio","fiche":"203","front":"OAP : indications de la CPAP ?","back":"Échec du traitement médical : **FR > 25/min** ou **SaO₂ < 90 %**.","prio":"P1","sec":"s12"},{"id":"fc-203-d9843f","poly":"cardio","fiche":"203","front":"OAP : quand intuber ?","back":"CPAP insuffisante, **détresse persistante** ou **épuisement** → ventilation invasive.","prio":"P2","sec":"s12"},{"id":"fc-203-547df5","poly":"cardio","fiche":"203","front":"OAP : place de la morphine ?","back":"**Non systématique** : seulement si anxiété importante non contrôlée ou douleur thoracique.","prio":"P1","sec":"s12"},{"id":"fc-203-6f0172","poly":"cardio","fiche":"203","front":"OAP : bêtabloquant pendant la poussée ?","back":"**Ne pas l'introduire** ; si déjà pris, en général arrêté ou diminué.","prio":"P1","sec":"s12"},{"id":"fc-203-7562e0","poly":"cardio","fiche":"203","front":"OAP : prévention thromboembolique ?","back":"**HBPM préventive systématique** (ex. énoxaparine 2 000 ou 4 000 UI/j) ; **plaquettes** avant toute héparine.","prio":"P2","sec":"s12"},{"id":"fc-203-f40149","poly":"cardio","fiche":"203","front":"HBPM et insuffisance rénale sévère : règle ?","back":"**Contre-indiquée si ClCr < 30 mL/min** ; la prescrire = **notion inacceptable**.","prio":"P1","sec":"s12"},{"id":"fc-203-a6928e","poly":"cardio","fiche":"203","front":"OAP déclenché par une FA rapide : traitement ?","back":"**Digoxine IV** + **anticoagulation efficace**.","prio":"P2","sec":"s12"},{"id":"fc-203-4b8c52","poly":"cardio","fiche":"203","front":"Digoxine IV en urgence chez l'insuffisant cardiaque : condition ?","back":"**Kaliémie normale**.","prio":"P3","sec":"s12"},{"id":"fc-203-227bae","poly":"cardio","fiche":"203","front":"OAP sur poussée hypertensive : traitement (item 234) ?","back":"**Nicardipine IV** 1 à 5 mg/h.","prio":"P2","sec":"s12"},{"id":"fc-203-fd9f6d","poly":"cardio","fiche":"203","front":"Nicardipine et insuffisance cardiaque : divergence du Collège ?","back":"Item 224 : **CI dans l'IC** (nitrés IV en 1re intention) ; item 234 : **nicardipine IV** pour l'OAP hypertensif.","prio":"P3","sec":"s12"},{"id":"fc-203-807ada","poly":"cardio","fiche":"203","front":"OAP : quand instaurer IEC, ARA2 ou ARNI ?","back":"**Secondairement**, **après la poussée**.","prio":"P2","sec":"s12"},{"id":"fc-203-9412f1","poly":"cardio","fiche":"203","front":"Insuffisance cardiaque aiguë : causes à traitement spécifique (CHAMPIT) ?","back":"**SCA**, urgence **hypertensive**, **arythmie**, complication **mécanique** d'un SCA, **EP**, **infection**, **tamponnade**.","prio":"P1","sec":"s12"},{"id":"fc-203-764dc1","poly":"cardio","fiche":"203","front":"Choc cardiogénique : définition ?","back":"**PA < 90 mmHg** + **hypoperfusion** (PA pincée, oligurie, marbrures, extrémités froides, obnubilation).","prio":"P1","sec":"s13"},{"id":"fc-203-78d635","poly":"cardio","fiche":"203","front":"Choc cardiogénique : prise en charge et monitorage ?","back":"**Inotropes**, **sonde urinaire systématique**, **PA invasive** radiale ; sans réponse : **assistance circulatoire**.","prio":"P2","sec":"s13"},{"id":"fc-203-ff66d6","poly":"cardio","fiche":"203","front":"Choc cardiogénique : inotrope de référence ?","back":"**Dobutamine IV**.","prio":"P1","sec":"s13"},{"id":"fc-203-88fb32","poly":"cardio","fiche":"203","front":"Choc cardiogénique sous bêtabloquant : inotrope à préférer ?","back":"**Milrinone** ou **énoximone** (inhibiteurs des phosphodiestérases).","prio":"P2","sec":"s13"},{"id":"fc-203-049af4","poly":"cardio","fiche":"203","front":"Lévosimendan : classe et usage ?","back":"**Sensibilisateur calcique** ; parfois si sevrage des inotropes impossible.","prio":"P3","sec":"s13"},{"id":"fc-203-7ce192","poly":"cardio","fiche":"203","front":"Tamponnade : traitement ?","back":"Urgence médicochirurgicale en USIC : **remplissage par macromolécules**, **ponction péricardique écho-guidée** ou drainage chirurgical.","prio":"P1","sec":"s13"},{"id":"fc-203-1340dd","poly":"cardio","fiche":"203","front":"Tamponnade confirmée : pourquoi drainer ?","back":"Risque d'**arrêt cardiaque par adiastolie**.","prio":"P2","sec":"s13"},{"id":"fc-203-f0dc4c","poly":"cardio","fiche":"203","front":"EP grave (choc ou hypotension sévère) : traitement ?","back":"Réanimation/USIC, **fibrinolyse** sauf CI ; si CI ou échec : **embolectomie chirurgicale sous CEC**.","prio":"P1","sec":"s13"},{"id":"fc-203-9e4ea3","poly":"cardio","fiche":"203","front":"EP sans choc : fibrinolyse systématique ?","back":"**Non** ; risque intermédiaire haut : reperfusion seulement si **détérioration**.","prio":"P1","sec":"s13"},{"id":"fc-203-ee80ac","poly":"cardio","fiche":"203","front":"EP à haut risque : dose initiale d'HNF ?","back":"**500 UI/kg/j**, puis adaptée au TCA ou à l'anti-Xa.","prio":"P2","sec":"s13"},{"id":"fc-203-d20322","poly":"cardio","fiche":"203","front":"HNF dans l'EP (item 226) : cibles biologiques ?","back":"TCA **1,5 à 2,5 × le témoin** ou anti-Xa **0,3 à 0,7 U**.","prio":"P2","sec":"s13"},{"id":"fc-203-98d8cb","poly":"cardio","fiche":"203","front":"HNF selon l'item 330 : cibles biologiques ?","back":"TCA **2 à 3 × le témoin** et/ou anti-Xa **0,5 à 0,8/mL**.","prio":"P3","sec":"s13"},{"id":"fc-203-3fcbfd","poly":"cardio","fiche":"203","front":"HNF : antidote et utilisation en insuffisance rénale ?","back":"Antidote : **sulfate de protamine IV** ; utilisable si **ClCr < 30 mL/min**.","prio":"P2","sec":"s13"},{"id":"fc-203-9a3e79","poly":"cardio","fiche":"203","front":"Relais HNF-AVK dans l'EP : quand arrêter l'HNF ?","back":"Après **≥ 5 jours** et **2 INR consécutifs > 2** à 24 h d'intervalle.","prio":"P2","sec":"s13"},{"id":"fc-203-01776f","poly":"cardio","fiche":"203","front":"EP : durée minimale d'anticoagulation ?","back":"**Au moins 3 mois**.","prio":"P1","sec":"s13"},{"id":"fc-203-51855e","poly":"cardio","fiche":"203","front":"EP grave avec choc : durée d'anticoagulation ?","back":"Facteur de risque majeur persistant : **> 6 mois**, voire au long cours.","prio":"P3","sec":"s13"},{"id":"fc-203-865380","poly":"cardio","fiche":"203","front":"FA avec état de choc : traitement ?","back":"**Cardioversion électrique immédiate**.","prio":"P2","sec":"s13"},{"id":"fc-203-6ebf21","poly":"cardio","fiche":"203","front":"Suspicion de tachycardie ventriculaire : critères ECG ?","back":"**FC > 100/min**, **QRS > 120 ms** sur **au moins 3 battements**.","prio":"P2","sec":"s13"},{"id":"fc-203-fe0dbf","poly":"cardio","fiche":"203","front":"Suspicion de TV : conduite immédiate ?","back":"**Alerter le 15** et se préparer à une **réanimation**.","prio":"P2","sec":"s13"},{"id":"fc-203-6ecc0d","poly":"cardio","fiche":"203","front":"Tamponnade chez l'anticoagulé : neutralisation selon l'anticoagulant ?","back":"Héparine : **protamine** ; AVK : **vitamine K** ; dabigatran : **idarucizumab** ; autres AOD : **PPSB** ou Feiba®.","prio":"P3","sec":"s13"},{"id":"fc-203-1a9104","poly":"cardio","fiche":"203","front":"Dyspnée expiratoire grave : examen pour rechercher l'hypercapnie ?","back":"**Gazométrie artérielle**.","prio":"P2","sec":"s14"},{"id":"fc-203-a68e2c","poly":"cardio","fiche":"203","front":"SDRA : lieu de prise en charge ?","back":"**Réanimation**.","prio":"P1","sec":"s14"},{"id":"fc-203-196398","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : surveillance commune à toutes les situations ?","back":"**Gazométrie** + réévaluation des **signes de gravité**.","prio":"P2","sec":"s15"},{"id":"fc-203-ddd360","poly":"cardio","fiche":"203","front":"OAP : paramètres pour adapter furosémide et trinitrine ?","back":"**Diurèse** pour le furosémide ; **PA** pour la trinitrine.","prio":"P2","sec":"s15"},{"id":"fc-203-d96674","poly":"cardio","fiche":"203","front":"HNF : quand contrôler TCA ou anti-Xa ?","back":"Entre 2 injections (SC) ou **4 h** après le début de la perfusion IV, et **4 h** après chaque changement de dose.","prio":"P3","sec":"s15"},{"id":"fc-203-716cd0","poly":"cardio","fiche":"203","front":"HNF : surveillance plaquettaire ?","back":"**2 fois/semaine pendant 21 jours** (risque de **TIH**).","prio":"P1","sec":"s15"},{"id":"fc-203-e7f0d4","poly":"cardio","fiche":"203","front":"TIH : critères plaquettaires ?","back":"Plaquettes **< 150 G/L** ou **baisse de 50 %**.","prio":"P2","sec":"s15"},{"id":"fc-203-cb0c77","poly":"cardio","fiche":"203","front":"Après un OAP : correction des causes curables ?","back":"**Revascularisation coronaire** si possible, **correction valvulaire**.","prio":"P3","sec":"s15"},{"id":"fc-203-026241","poly":"cardio","fiche":"203","front":"Dyspnée chronique : premier examen à réaliser ?","back":"**NFP** : toujours **éliminer une anémie**.","prio":"P1","sec":"s16"},{"id":"fc-203-85cedb","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes les plus fréquentes ?","back":"**Cardiaques** ou **pulmonaires**.","prio":"P2","sec":"s16"},{"id":"fc-203-c8e6d5","poly":"cardio","fiche":"203","front":"Dyspnée chronique : examens à discuter après la NFP ?","back":"**EFR** + gazométrie, **ECG**, **radio**, **échocardiographie**, épreuve d'effort avec gaz, scanner, cathétérisme.","prio":"P2","sec":"s16"},{"id":"fc-203-8a2b45","poly":"cardio","fiche":"203","front":"Épreuve d'effort avec mesure des gaz respiratoires : intérêt ?","back":"**Objective la gêne** et oriente vers une cause **cardiaque ou pulmonaire**.","prio":"P2","sec":"s16"},{"id":"fc-203-368345","poly":"cardio","fiche":"203","front":"Dyspnée chronique : valeur d'un BNP strictement normal ?","back":"**IC peu probable** (BNP moins validé qu'en aigu).","prio":"P2","sec":"s16"},{"id":"fc-203-f86cc6","poly":"cardio","fiche":"203","front":"Dyspnée chronique, IC suspectée : examen clé ?","back":"**Échocardiographie** (cardiopathie, pressions intracardiaques élevées).","prio":"P2","sec":"s16"},{"id":"fc-203-348f95","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes cardiaques ?","back":"Toutes les causes d'**insuffisance cardiaque** + **constriction péricardique**.","prio":"P1","sec":"s17"},{"id":"fc-203-6327cb","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes pulmonaires obstructives ?","back":"**BPCO**, **asthme à dyspnée continue**.","prio":"P1","sec":"s17"},{"id":"fc-203-7ea8a7","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes de trouble restrictif ?","back":"**PID**, **pneumoconioses**, séquelles pleurales post-tuberculeuses, **paralysie phrénique**, **cyphoscoliose**, **obésité morbide**.","prio":"P2","sec":"s17"},{"id":"fc-203-2da7a6","poly":"cardio","fiche":"203","front":"Pneumoconiose : définition ?","back":"Maladie **non cancéreuse** due à l'**inhalation de particules** (ex. **asbestose**).","prio":"P3","sec":"s17"},{"id":"fc-203-5558ab","poly":"cardio","fiche":"203","front":"HTAP : causes ?","back":"**Idiopathique**, **familiale**, **connectivite** (sclérodermie), **shunt intracardiaque**, **VIH**, **toxique**.","prio":"P2","sec":"s17"},{"id":"fc-203-e405fa","poly":"cardio","fiche":"203","front":"HTP post-embolique : définition ?","back":"Complication **grave** après une ou plusieurs EP, avec HTP **précapillaire** persistante.","prio":"P2","sec":"s17"},{"id":"fc-203-5801ad","poly":"cardio","fiche":"203","front":"Dyspnée chronique : autres causes (hors cœur, poumon, HTP) ?","back":"Obstacle des **VAS**, **anémie**, acidose, cause **neuromusculaire**, hyperventilation, troubles du transport de l'O₂ ou **CO**.","prio":"P2","sec":"s17"},{"id":"fc-203-8dd9c2","poly":"cardio","fiche":"203","front":"Platypnée-orthodéoxie : définition et cause à rechercher ?","back":"Dyspnée **debout** avec **désaturation** ; **shunt droite-gauche** (foramen ovale perméable).","prio":"P2","sec":"s17"},{"id":"fc-221-12f6e5","poly":"cardio","fiche":"221","front":"Athérome : définition ?","back":"Remaniements de l'**intima** des artères de **gros et moyen calibre**, par accumulation **focale**, avec **modifications de la média**.","prio":"P1","sec":"s1"},{"id":"fc-221-084fb3","poly":"cardio","fiche":"221","front":"Athérome : composants de l'accumulation focale ?","back":"**Lipides** et glucides complexes · **sang** et produits sanguins · **tissu fibreux** · **dépôts calcaires**.","prio":"P2","sec":"s1"},{"id":"fc-221-603ecf","poly":"cardio","fiche":"221","front":"Malade polyathéromateux (polyvasculaire) : définition ?","back":"Atteinte d'**au moins 2 territoires artériels**, **symptomatique** ou **asymptomatique mais significative**.","prio":"P1","sec":"s1"},{"id":"fc-221-20b2e3","poly":"cardio","fiche":"221","front":"Une plaque < 50 % non compliquée dans un 2ᵉ territoire suffit-elle à définir le polyvasculaire ?","back":"**Non** : elle reflète une athérosclérose débutante.","prio":"P1","sec":"s1"},{"id":"fc-221-bedb11","poly":"cardio","fiche":"221","front":"Sténose carotidienne à 50 % asymptomatique chez un patient AOMI : polyvasculaire ?","back":"**Oui** : atteinte **asymptomatique mais significative**.","prio":"P2","sec":"s1"},{"id":"fc-221-5fe89f","poly":"cardio","fiche":"221","front":"Athérome : quand dépister les autres territoires ?","back":"À **chaque lésion** découverte, puis **tout au long** de la prise en charge et du suivi.","prio":"P1","sec":"s1"},{"id":"fc-221-c5a94e","poly":"cardio","fiche":"221","front":"Dépistage des autres territoires athéromateux : condition d'intérêt ?","back":"Qu'il **change la prise en charge** (ex. revasculariser une sténose carotidienne trouvée dans le bilan d'une AOMI).","prio":"P2","sec":"s1"},{"id":"fc-221-712fb7","poly":"cardio","fiche":"221","front":"Maladies cardiovasculaires : rang de mortalité dans le monde ?","back":"**1re cause de mortalité** dans le monde.","prio":"P2","sec":"s2"},{"id":"fc-221-234e4c","poly":"cardio","fiche":"221","front":"Mortalité CV en France : rang actuel ?","back":"**2e rang, derrière le cancer** ; reste la **1re cause chez les femmes**.","prio":"P2","sec":"s2"},{"id":"fc-221-400273","poly":"cardio","fiche":"221","front":"France : niveau de mortalité CV en Europe ?","back":"Parmi les **plus faibles** ; pays à **faible niveau de risque CV** (ESC).","prio":"P3","sec":"s2"},{"id":"fc-221-2abcf8","poly":"cardio","fiche":"221","front":"Écarts de mortalité CV entre pays : explication principale ?","back":"**Environnement** et **habitudes alimentaires** plus que la génétique.","prio":"P3","sec":"s2"},{"id":"fc-221-86bacb","poly":"cardio","fiche":"221","front":"Mortalité CV : gradient géographique ?","back":"**Plus élevée** : nord et est de l'Europe ; intermédiaire : Amérique du Nord ; **plus faible** : Europe du Sud et Japon.","prio":"P3","sec":"s2"},{"id":"fc-221-13a16e","poly":"cardio","fiche":"221","front":"Maladie athéromateuse : rapport d'incidence homme/femme ?","back":"**3 à 5 fois** plus élevée chez l'homme ; écart qui **diminue avec l'âge**.","prio":"P2","sec":"s2"},{"id":"fc-221-142ba8","poly":"cardio","fiche":"221","front":"SCA chez la femme, notamment jeune : tendance et cause ?","back":"En **augmentation**, à cause de la hausse du **tabagisme**.","prio":"P2","sec":"s2"},{"id":"fc-221-f7069d","poly":"cardio","fiche":"221","front":"Maladies CV : évolution de la mortalité et de la prévalence ?","back":"Mortalité **en baisse** (prise en charge, prévention) ; prévalence **en hausse** (**vieillissement** et baisse de la mortalité de ces maladies).","prio":"P2","sec":"s2"},{"id":"fc-221-d09639","poly":"cardio","fiche":"221","front":"Incidence mondiale des maladies CV : tendance et causes ?","back":"**Fort accroissement attendu** : alimentation, **sédentarité**, **obésité**, **diabète**.","prio":"P3","sec":"s2"},{"id":"fc-221-c5b09f","poly":"cardio","fiche":"221","front":"Pays en voie de développement : évolution des maladies athéromateuses ?","back":"**Transition épidémiologique** : prévalence et incidence en hausse.","prio":"P3","sec":"s2"},{"id":"fc-221-2f8ec4","poly":"cardio","fiche":"221","front":"Formation de la plaque : étape initiale ?","back":"**Accumulation des LDL** dans l'intima puis **oxydation** par les radicaux libres.","prio":"P2","sec":"s3"},{"id":"fc-221-56b3d3","poly":"cardio","fiche":"221","front":"Athérogenèse : devenir des monocytes attirés dans la paroi ?","back":"Ils deviennent **macrophages** puis **cellules spumeuses**.","prio":"P2","sec":"s3"},{"id":"fc-221-421b3e","poly":"cardio","fiche":"221","front":"Athérogenèse : quels récepteurs captent les LDL oxydées ?","back":"Les **récepteurs scavengers** (« éboueurs »).","prio":"P3","sec":"s3"},{"id":"fc-221-40221b","poly":"cardio","fiche":"221","front":"Dysfonction endothéliale : facteurs favorisants et conséquences ?","back":"**Tabagisme**, LDL oxydées ; baisse des capacités **vasodilatatrices** et **antithrombotiques**.","prio":"P2","sec":"s3"},{"id":"fc-221-64844a","poly":"cardio","fiche":"221","front":"Athérogenèse : rôle des métalloprotéases ?","back":"Libérées par l'inflammation, elles **détruisent la matrice extracellulaire**.","prio":"P3","sec":"s3"},{"id":"fc-221-7b74e6","poly":"cardio","fiche":"221","front":"Athérogenèse : rôle des cellules musculaires lisses ?","back":"Migrent de la **média** vers la néo-intima ; sécrètent **collagène**, matrice et facteurs de croissance.","prio":"P2","sec":"s3"},{"id":"fc-221-2f2dcc","poly":"cardio","fiche":"221","front":"Plaque d'athérome : structure finale ?","back":"**Centre lipidique** recouvert **tardivement** d'une **chape fibreuse**.","prio":"P2","sec":"s3"},{"id":"fc-221-eb8d28","poly":"cardio","fiche":"221","front":"Stries lipidiques : à quel âge sont-elles observées ?","back":"**Dès le jeune âge** (autopsie).","prio":"P3","sec":"s3"},{"id":"fc-221-099bfa","poly":"cardio","fiche":"221","front":"Plaque instable : composition et risque ?","back":"**Très lipidique** et **très inflammatoire** ; **très vulnérable à la rupture**.","prio":"P2","sec":"s3"},{"id":"fc-221-312e86","poly":"cardio","fiche":"221","front":"Plaque d'athérome stable : composition ?","back":"**Centre lipidique**, cellules **spumeuses**, musculaires et inflammatoires, recouverts d'une **chape fibreuse**.","prio":"P3","sec":"s3"},{"id":"fc-221-b5827e","poly":"cardio","fiche":"221","front":"Sténose athéromateuse : 2 modes d'aggravation ?","back":"**Progressif** (croissance de plaque) ou **brutal** (rupture/érosion → **thrombus** → réduction, voire **occlusion**).","prio":"P1","sec":"s4"},{"id":"fc-221-dcc6cc","poly":"cardio","fiche":"221","front":"Hémorragie intraplaque : conséquence ?","back":"**Aggrave la sténose** ; augmente brusquement le volume, la chape peut se rompre.","prio":"P3","sec":"s4"},{"id":"fc-221-97ad15","poly":"cardio","fiche":"221","front":"Rupture de plaque : plaques les plus exposées ?","back":"Plaques **jeunes**, riches en **lipides** et cellules inflammatoires, à **chape fine**, souvent **peu sténosantes**.","prio":"P2","sec":"s4"},{"id":"fc-221-bc5ea0","poly":"cardio","fiche":"221","front":"Rupture de plaque : est-elle toujours symptomatique ?","back":"**Non** : beaucoup restent **asymptomatiques**.","prio":"P3","sec":"s4"},{"id":"fc-221-588e6b","poly":"cardio","fiche":"221","front":"Progression de la plaque : mode principal ?","back":"**Surtout par poussées**, lors des ruptures, en incorporant du matériel thrombotique.","prio":"P3","sec":"s4"},{"id":"fc-221-ef0442","poly":"cardio","fiche":"221","front":"Régression de plaque : est-elle démontrée chez l'homme ?","back":"**Difficile à démontrer** (vue chez l'animal).","prio":"P3","sec":"s4"},{"id":"fc-221-e01ee8","poly":"cardio","fiche":"221","front":"Remodelage artériel compensateur versus constrictif ?","back":"Compensateur : **élargit** le diamètre, préserve la lumière ; constrictif : **réduit** le diamètre, majore la sténose.","prio":"P3","sec":"s4"},{"id":"fc-221-ef47c7","poly":"cardio","fiche":"221","front":"Réduction progressive de la lumière artérielle : tableaux cliniques ?","back":"**Ischémie chronique stable** : angor d'effort, claudication intermittente, claudication digestive.","prio":"P2","sec":"s4"},{"id":"fc-221-7bc876","poly":"cardio","fiche":"221","front":"Érosion de plaque : mécanisme et exemple ?","back":"Fortes contraintes de **cisaillement** → thrombose superficielle, embolisation distale ; ex. **SCA sans sus-décalage de ST**.","prio":"P3","sec":"s4"},{"id":"fc-221-927cef","poly":"cardio","fiche":"221","front":"Athérome : quand commence-t-il ?","back":"**Très tôt, dès l'enfance** ; progression selon les **FDR** et le **vieillissement**.","prio":"P2","sec":"s4"},{"id":"fc-221-9f0470","poly":"cardio","fiche":"221","front":"Accident athéromateux : sa gravité est-elle proportionnelle à l'ancienneté de l'athérome ?","back":"**Pas toujours** : une plaque coronaire **jeune** qui se rompt peut donner un infarctus ou une **mort subite**.","prio":"P2","sec":"s4"},{"id":"fc-221-31e5a0","poly":"cardio","fiche":"221","front":"Occlusion artérielle chronique asymptomatique : explication ?","back":"Une **collatéralité** supplée le territoire.","prio":"P3","sec":"s4"},{"id":"fc-221-300430","poly":"cardio","fiche":"221","front":"Anévrismes : sont-ils tous dus à l'athérome ?","back":"**Non**.","prio":"P3","sec":"s4"},{"id":"fc-221-65c987","poly":"cardio","fiche":"221","front":"Rupture de plaque : complications aiguës selon le territoire ?","back":"**SCA avec sus-décalage du ST** (thrombose occlusive), **AVC ischémique**, **ischémie aiguë** d'un membre inférieur.","prio":"P2","sec":"s4"},{"id":"fc-221-0562a3","poly":"cardio","fiche":"221","front":"Maladie athéromateuse : de quoi dépend surtout le risque de complication ou de récidive ?","back":"Du **nombre de facteurs de risque** présents.","prio":"P2","sec":"s4"},{"id":"fc-221-3e332f","poly":"cardio","fiche":"221","front":"Athérome : sites de développement préférentiels ?","back":"Près des **flux turbulents** : **ostium**, **bifurcation**, zone de **contrainte mécanique**.","prio":"P1","sec":"s5"},{"id":"fc-221-461628","poly":"cardio","fiche":"221","front":"Maladie athéromateuse : 4 territoires principaux ?","back":"**Coronaires**, **carotides**, **artères des membres inférieurs**, **aorte abdominale**.","prio":"P1","sec":"s5"},{"id":"fc-221-be1ce1","poly":"cardio","fiche":"221","front":"Plaques de la crosse aortique : conséquence clinique ?","back":"**AVC**.","prio":"P2","sec":"s5"},{"id":"fc-221-b3a0d9","poly":"cardio","fiche":"221","front":"Sténose des artères rénales : conséquences ?","back":"**HTA** et **insuffisance rénale**.","prio":"P1","sec":"s5"},{"id":"fc-221-4ea8d1","poly":"cardio","fiche":"221","front":"Sténose des artères digestives : conséquence ?","back":"**Ischémie mésentérique**.","prio":"P1","sec":"s5"},{"id":"fc-221-161b96","poly":"cardio","fiche":"221","front":"Lésions de l'aorte terminale : complication favorisée ?","back":"**Anévrisme de l'aorte abdominale**.","prio":"P2","sec":"s5"},{"id":"fc-221-e19f0f","poly":"cardio","fiche":"221","front":"Athérome : facteurs de risque non modifiables ?","back":"**Âge**, **sexe masculin**, **antécédents familiaux**.","prio":"P1","sec":"s6"},{"id":"fc-221-51797c","poly":"cardio","fiche":"221","front":"Athérome : facteurs de risque modifiables principaux ?","back":"**Tabagisme**, **HTA**, **dyslipidémies**, **diabète**.","prio":"P1","sec":"s6"},{"id":"fc-221-0bc3a2","poly":"cardio","fiche":"221","front":"Athérome : facteurs prédisposants ?","back":"**Obésité**, **sédentarité**, stress/conditions psychosociales, **pollution atmosphérique**.","prio":"P2","sec":"s6"},{"id":"fc-221-1a6906","poly":"cardio","fiche":"221","front":"Facteur de risque CV propre à la femme : exemple ?","back":"**Ménopause précoce**.","prio":"P2","sec":"s6"},{"id":"fc-221-03e4fb","poly":"cardio","fiche":"221","front":"Marqueur de risque CV : définition ?","back":"**Associé** à un risque plus élevé, **sans lien de causalité établi**.","prio":"P1","sec":"s6"},{"id":"fc-221-d1d4c2","poly":"cardio","fiche":"221","front":"Marqueur de risque biologique : exemple ?","back":"Marqueurs inflammatoires : **CRP**.","prio":"P2","sec":"s6"},{"id":"fc-221-a693e4","poly":"cardio","fiche":"221","front":"Plaque carotidienne à l'échographie : facteur ou marqueur de risque coronarien ?","back":"**Marqueur** de risque (vasculaire).","prio":"P2","sec":"s6"},{"id":"fc-221-28b2b1","poly":"cardio","fiche":"221","front":"Prévention primaire versus secondaire : définitions ?","back":"Primaire : **avant** l'expression clinique ; secondaire : **après** une maladie CV chronique ou aiguë.","prio":"P1","sec":"s6"},{"id":"fc-221-e34587","poly":"cardio","fiche":"221","front":"Lésion sévère asymptomatique (ex. sténose carotidienne serrée) : niveau de prévention ?","back":"Stratégie en général **équivalente à la prévention secondaire**.","prio":"P1","sec":"s6"},{"id":"fc-221-0f9c49","poly":"cardio","fiche":"221","front":"Coronarien : fréquence d'une AOMI, sténose carotidienne ou rénale associée ?","back":"**20 %** chacune.","prio":"P3","sec":"s7"},{"id":"fc-221-94caa2","poly":"cardio","fiche":"221","front":"AOMI, sténose carotidienne ou AAA : fréquence d'une atteinte coronarienne associée ?","back":"**40-50 %**.","prio":"P2","sec":"s7"},{"id":"fc-221-d4dfa2","poly":"cardio","fiche":"221","front":"Quel terrain est le plus souvent polyvasculaire ?","back":"Les patients atteints d'**AOMI**.","prio":"P2","sec":"s7"},{"id":"fc-221-6963fb","poly":"cardio","fiche":"221","front":"Athérome : symptôme sexuel pouvant révéler une maladie artérielle ?","back":"La **dysfonction érectile**.","prio":"P3","sec":"s7"},{"id":"fc-221-4e876e","poly":"cardio","fiche":"221","front":"Bilan d'extension du polyathéromateux : éléments ?","back":"**FDR** + **risque CV global**, clinique de **tous les territoires**, **PA aux 2 bras**, **ECG**, **IPS**, dépistage de l'**AAA**.","prio":"P1","sec":"s7"},{"id":"fc-221-0f396b","poly":"cardio","fiche":"221","front":"PA aux deux bras : écart évocateur de sténose subclavière ?","back":"**> 15 mmHg** sur **plusieurs mesures**.","prio":"P1","sec":"s7"},{"id":"fc-221-900744","poly":"cardio","fiche":"221","front":"Polyathéromateux : place de l'ECG ?","back":"**Systématique**.","prio":"P1","sec":"s7"},{"id":"fc-221-b5e2fe","poly":"cardio","fiche":"221","front":"Bilan d'extension du polyathéromateux : chez qui dépister notamment l'AAA ?","back":"Notamment l'**homme après 65 ans**.","prio":"P1","sec":"s7"},{"id":"fc-221-56aa39","poly":"cardio","fiche":"221","front":"Polyathéromateux : critères de choix des explorations complémentaires ?","back":"Bilan **clinique**, **risque CV global**, prévalence d'un autre territoire, besoin d'un **geste invasif**.","prio":"P2","sec":"s7"},{"id":"fc-221-054c00","poly":"cardio","fiche":"221","front":"AOMI : examen d'imagerie de dépistage et de diagnostic ?","back":"**Échodoppler artériel des MI** avec **mesure de l'IPS**.","prio":"P2","sec":"s7"},{"id":"fc-221-9bcd4f","poly":"cardio","fiche":"221","front":"AAA asymptomatique : seuils d'intervention ?","back":"Diamètre **55 mm** (**50 mm chez la femme**) ou croissance **≥ 5 mm/an**.","prio":"P1","sec":"s8"},{"id":"fc-221-047ffc","poly":"cardio","fiche":"221","front":"Sténose carotidienne asymptomatique : seuil d'endartériectomie ?","back":"**> 60 %** (le plus souvent > 80 %), si espérance de vie **> 5 ans**.","prio":"P1","sec":"s8"},{"id":"fc-221-3e8fd7","poly":"cardio","fiche":"221","front":"Après un SCA : seuil de revascularisation des sténoses coronaires ?","back":"Sténoses significatives **> 70 %**.","prio":"P1","sec":"s8"},{"id":"fc-221-ae1ade","poly":"cardio","fiche":"221","front":"Angor stable ou ischémie silencieuse : la revascularisation est-elle systématique ?","back":"**Non**.","prio":"P1","sec":"s8"},{"id":"fc-221-568a6f","poly":"cardio","fiche":"221","front":"Angor stable : indications de revascularisation ?","back":"Symptômes **malgré traitement**, **FEVG altérée**, ischémie à **seuil bas** ou **étendue**, chirurgie à haut risque prévue, **FFR ≤ 0,8**.","prio":"P1","sec":"s8"},{"id":"fc-221-db14b7","poly":"cardio","fiche":"221","front":"FFR : seuil de sténose hémodynamiquement significative ?","back":"**FFR ≤ 0,8**.","prio":"P1","sec":"s8"},{"id":"fc-221-0352cf","poly":"cardio","fiche":"221","front":"Polyvasculaire en situation aiguë ou instable : conduite ?","back":"Revasculariser **rapidement la lésion coupable**, **sans prolonger le dépistage**.","prio":"P1","sec":"s8"},{"id":"fc-221-0cec23","poly":"cardio","fiche":"221","front":"Plusieurs lésions à traiter hors urgence : qui décide de l'ordre des gestes ?","back":"**Réunion pluridisciplinaire**, au cas par cas.","prio":"P2","sec":"s8"},{"id":"fc-221-2909ba","poly":"cardio","fiche":"221","front":"Bêtabloquant : chez quels patients athéromateux son efficacité est-elle prouvée ?","back":"**Seulement après un infarctus** (notamment FEVG altérée).","prio":"P1","sec":"s9"},{"id":"fc-221-341948","poly":"cardio","fiche":"221","front":"Bêtabloquant chez le polyvasculaire ou le coronarien stable : bénéfice pronostique ?","back":"**Non démontré**.","prio":"P2","sec":"s9"},{"id":"fc-221-f18f07","poly":"cardio","fiche":"221","front":"Prévention de l'athérome : moyens contre la dysfonction endothéliale ?","back":"Supprimer ou traiter **tous les FDR modifiables** (tabac, sédentarité).","prio":"P2","sec":"s10"},{"id":"fc-221-fba57e","poly":"cardio","fiche":"221","front":"Statines : actions sur la plaque d'athérome ?","back":"Baisse des **LDL**, **stabilisation** de la plaque, baisse de l'**inflammation**.","prio":"P1","sec":"s10"},{"id":"fc-221-e37dba","poly":"cardio","fiche":"221","front":"Faire régresser le volume des plaques : moyens ?","back":"**Statines à fortes doses** ± **ézétimibe**, ou **anti-PCSK9**.","prio":"P2","sec":"s10"},{"id":"fc-221-015741","poly":"cardio","fiche":"221","front":"Athérome : traitements réduisant l'inflammation ?","back":"**Aspirine** et **statines**.","prio":"P2","sec":"s10"},{"id":"fc-221-f67128","poly":"cardio","fiche":"221","front":"Athérome : traitement réduisant les contraintes mécaniques ?","back":"Les **antihypertenseurs**.","prio":"P2","sec":"s10"},{"id":"fc-221-14dfe2","poly":"cardio","fiche":"221","front":"Lésions menaçantes : gestes selon le territoire ?","back":"Coronaires : **angioplastie/pontage** ; carotides : **chirurgie/angioplastie** ; anévrismes : **chirurgie/endoprothèse** ; MI : angioplastie/pontage.","prio":"P2","sec":"s10"},{"id":"fc-221-f6a66a","poly":"cardio","fiche":"221","front":"Aspirine en prévention primaire : recommandation ?","back":"**Pas de prescription systématique**, même chez le diabétique ; seulement si très haut risque vasculaire et faible risque hémorragique.","prio":"P1","sec":"s10"},{"id":"fc-221-c45916","poly":"cardio","fiche":"221","front":"Aspirine : effets indésirables et contre-indications ?","back":"EI : **saignements**, **intolérance gastrique** ; CI rares : intolérance gastrique, **allergie**.","prio":"P2","sec":"s10"},{"id":"fc-221-195e01","poly":"cardio","fiche":"221","front":"Polyathéromateux : mesures hygiénodiététiques ?","back":"**Arrêt du tabac**, **diététique + éducation thérapeutique**, **activité physique régulière** prescrite.","prio":"P1","sec":"s11"},{"id":"fc-221-9158f5","poly":"cardio","fiche":"221","front":"Polyathéromateux : trio médicamenteux de fond ?","back":"**Antiagrégant** (aspirine ou clopidogrel) + **statine** + **IEC (ou ARA2)**.","prio":"P1","sec":"s11"},{"id":"fc-221-e6f679","poly":"cardio","fiche":"221","front":"Polyvasculaire : dose d'aspirine ?","back":"**Entre 75 et 325 mg/j**, au long cours.","prio":"P1","sec":"s11"},{"id":"fc-221-23427d","poly":"cardio","fiche":"221","front":"Coronarien : dose d'aspirine (item 339) ?","back":"**75 à 100 mg/j**.","prio":"P2","sec":"s11"},{"id":"fc-221-a4a0d3","poly":"cardio","fiche":"221","front":"Polyvasculaire : indications du clopidogrel à la place de l'aspirine ?","back":"**Intolérance à l'aspirine** ou atteinte polyvasculaire **compliquée**, notamment **AOMI**.","prio":"P1","sec":"s11"},{"id":"fc-221-0fd752","poly":"cardio","fiche":"221","front":"Prévention secondaire (très haut risque) : objectif de LDL-C ?","back":"**< 0,55 g/L** (< 1,4 mmol/L).","prio":"P1","sec":"s11"},{"id":"fc-221-f82174","poly":"cardio","fiche":"221","front":"Polyvasculaire : bénéfices des IEC (ou ARA2) ?","back":"Baisse du risque d'**infarctus** et d'**AVC** ; freinent l'altération de la **fonction rénale**.","prio":"P2","sec":"s11"},{"id":"fc-221-7d0866","poly":"cardio","fiche":"221","front":"Prévention secondaire : quelle omission est une notion inacceptable ?","back":"**Oublier l'aspirine et les statines**.","prio":"P1","sec":"s11"},{"id":"fc-221-40d952","poly":"cardio","fiche":"221","front":"Bêtabloquant après infarctus à FEVG normale : bénéfice à distance ?","back":"**Remis en cause**.","prio":"P3","sec":"s11"},{"id":"fc-221-dcb879","poly":"cardio","fiche":"221","front":"AOMI : objectifs tensionnels et glycémique (item 225) ?","back":"PAS **≤ 120-129**, PAD **≤ 70-79 mmHg** ; **HbA1c < 7 %**.","prio":"P2","sec":"s12"},{"id":"fc-221-56e450","poly":"cardio","fiche":"221","front":"AOMI : objectifs LDL et IMC ?","back":"LDL-C **< 0,55 g/L** et baisse **≥ 50 %** ; IMC **20-25 kg/m²** ; régime méditerranéen.","prio":"P2","sec":"s12"},{"id":"fc-221-424231","poly":"cardio","fiche":"221","front":"AOMI : modalités de la marche ?","back":"Régulière, de préférence **supervisée** : **≥ 30-45 min**, **≥ 3 fois/semaine**, en **ralentissant ou s'arrêtant** quelques minutes au seuil douloureux.","prio":"P1","sec":"s12"},{"id":"fc-221-1f62fb","poly":"cardio","fiche":"221","front":"AOMI : durée du réentraînement supervisé ?","back":"**3 fois/semaine pendant 12 semaines**.","prio":"P3","sec":"s12"},{"id":"fc-221-1a05c2","poly":"cardio","fiche":"221","front":"AOMI : indications de revascularisation ?","back":"Autant que possible si **ischémie permanente** ; possible si claudication sévère malgré traitement + réadaptation ; **parfois** d'emblée si périmètre **< 100 m** handicapant et/ou atteinte aorto-iliaque sévère.","prio":"P2","sec":"s12"},{"id":"fc-221-b336c6","poly":"cardio","fiche":"221","front":"AOMI : techniques de revascularisation ?","back":"**Angioplastie** (± stent) ou **pontage** (de préférence **veineux**).","prio":"P2","sec":"s12"},{"id":"fc-221-23523d","poly":"cardio","fiche":"221","front":"AOMI : bénéfice supplémentaire de la statine ?","back":"Peut **allonger le périmètre de marche**.","prio":"P3","sec":"s12"},{"id":"fc-221-b16d3c","poly":"cardio","fiche":"221","front":"AOMI : chez qui envisager un IEC ou un sartan ?","back":"Chez **tout** patient avec AOMI, **quel que soit le niveau de PA** (sauf CI).","prio":"P1","sec":"s12"},{"id":"fc-221-875b05","poly":"cardio","fiche":"221","front":"AOMI : précaution avec les bêtabloquants ?","back":"Prudence si **ischémie critique** sans revascularisation possible.","prio":"P3","sec":"s12"},{"id":"fc-221-c679b7","poly":"cardio","fiche":"221","front":"AOMI symptomatique versus asymptomatique : antiagrégant ?","back":"Symptomatique : **pour tous** ; asymptomatique (IPS < 0,90) : **débattu**, sauf atteinte d'un autre territoire.","prio":"P2","sec":"s12"},{"id":"fc-221-5bbd33","poly":"cardio","fiche":"221","front":"Vasoactifs (pentoxifylline) dans l'AOMI : intérêt ?","back":"Gain **modeste** du périmètre de marche, **sans bénéfice pronostique**.","prio":"P3","sec":"s12"},{"id":"fc-221-94a203","poly":"cardio","fiche":"221","front":"Après angioplastie des MI : durée de bithérapie antiplaquettaire ?","back":"**1 à 6 mois** selon le geste et sa localisation.","prio":"P3","sec":"s12"},{"id":"fc-221-787636","poly":"cardio","fiche":"221","front":"Après revascularisation des MI : surveillance ?","back":"**Clinique + échodoppler** (thrombose de stent ou de pontage, dégradation des anastomoses).","prio":"P3","sec":"s12"},{"id":"fc-221-2fb4a9","poly":"cardio","fiche":"221","front":"AAA : population à dépister par échographie ?","back":"**Homme > 65 ans**, ou plus jeune avec FDR (tabac, maladie athéromateuse, ATCD familiaux d'anévrisme).","prio":"P1","sec":"s13"},{"id":"fc-221-060b59","poly":"cardio","fiche":"221","front":"AAA : 2 techniques de traitement ?","back":"**Chirurgie ouverte** (mise à plat-greffe) ou **endoprothèse** par voie fémorale.","prio":"P2","sec":"s13"},{"id":"fc-221-905d9d","poly":"cardio","fiche":"221","front":"Endoprothèse aortique : indications ?","back":"Anatomie favorable ; sujets à **haut risque chirurgical** (possible à bas risque après information).","prio":"P3","sec":"s13"},{"id":"fc-221-7b871f","poly":"cardio","fiche":"221","front":"AAA sous le seuil opératoire, de diamètre > 45 mm : rythme de surveillance échographique ?","back":"**Tous les 6 mois**.","prio":"P3","sec":"s13"},{"id":"fc-221-0c7d3e","poly":"cardio","fiche":"221","front":"AAA : effet de la poursuite du tabac ?","back":"L'anévrisme grossit **3 fois plus vite**.","prio":"P3","sec":"s13"},{"id":"fc-221-9a530e","poly":"cardio","fiche":"221","front":"Après traitement d'un AAA : surveillance selon la technique ?","back":"Prothèse : **échodoppler** (faux anévrismes anastomotiques) ; endoprothèse : **scanner ou écho** (endofuites).","prio":"P3","sec":"s13"},{"id":"fc-221-35930d","poly":"cardio","fiche":"221","front":"Porteur d'AAA : risque de décès CV par une autre atteinte versus rupture ?","back":"**10 fois plus** de risque de mourir d'une autre atteinte CV (coronaire, AVC).","prio":"P2","sec":"s13"},{"id":"fc-221-641604","poly":"cardio","fiche":"221","front":"Sténose carotidienne asymptomatique serrée, espérance de vie ≤ 5 ans : geste ?","back":"**Pas d'endartériectomie**.","prio":"P1","sec":"s13"},{"id":"fc-221-44bade","poly":"cardio","fiche":"221","front":"Lésions carotidiennes menaçantes : alternative à l'endartériectomie ?","back":"**Angioplastie carotidienne**.","prio":"P3","sec":"s13"},{"id":"fc-221-9d0b37","poly":"cardio","fiche":"221","front":"Porteur de prothèse artérielle : antibioprophylaxie ?","back":"Peut se justifier lors de **tout acte à risque bactérien**.","prio":"P3","sec":"s13"},{"id":"fc-221-b730b6","poly":"cardio","fiche":"221","front":"Après SCA : durée habituelle de la bithérapie P2Y12 + aspirine ?","back":"**12 mois**.","prio":"P1","sec":"s14"},{"id":"fc-221-e78982","poly":"cardio","fiche":"221","front":"Angor stable après stent actif : bithérapie antiplaquettaire ?","back":"**Clopidogrel + aspirine 6 mois**.","prio":"P2","sec":"s14"},{"id":"fc-221-2b4794","poly":"cardio","fiche":"221","front":"Angor stable après angioplastie : prasugrel ou ticagrélor ?","back":"**Non indiqués** : **clopidogrel**.","prio":"P2","sec":"s14"},{"id":"fc-221-754960","poly":"cardio","fiche":"221","front":"Après SCA : statine, dose et objectifs ?","back":"**Forte dose** d'emblée (atorvastatine 80 ou rosuvastatine 20 mg) ; baisse **≥ 50 %** et LDL-C **< 0,55 g/L**.","prio":"P1","sec":"s14"},{"id":"fc-221-cb44ab","poly":"cardio","fiche":"221","front":"Après SCA : quand ajouter l'ézétimibe ?","back":"Objectif non atteint après **4 semaines** à dose maximale tolérée : **ézétimibe 10 mg**.","prio":"P2","sec":"s14"},{"id":"fc-221-614fd3","poly":"cardio","fiche":"221","front":"Anti-PCSK9 après SCA : condition de remboursement ?","back":"LDL-C restant **> 0,7 g/L**.","prio":"P3","sec":"s14"},{"id":"fc-221-e25b19","poly":"cardio","fiche":"221","front":"Après SCA : les IEC/ARA2 sont-ils systématiques ?","back":"**Non** : surtout si **FEVG ≤ 40 %**, **diabète**, **IRC**.","prio":"P2","sec":"s14"},{"id":"fc-221-008713","poly":"cardio","fiche":"221","front":"Après infarctus : quand le bêtabloquant est-il formellement indiqué ?","back":"**FEVG ≤ 40 %**.","prio":"P2","sec":"s14"},{"id":"fc-221-a40207","poly":"cardio","fiche":"221","front":"Bêtabloquant : contre-indications ?","back":"**Asthme**, **BPCO très sévère**, **Raynaud**, **bradycardie < 50/min**, **BAV 2e-3e degré**.","prio":"P1","sec":"s14"},{"id":"fc-221-8da5d0","poly":"cardio","fiche":"221","front":"Trinitrine sublinguale : effets indésirables et précaution de prise ?","back":"**Céphalées**, **chute de PA** → **s'asseoir ou s'allonger**.","prio":"P2","sec":"s14"},{"id":"fc-221-761db2","poly":"cardio","fiche":"221","front":"Inhibiteurs calciques bradycardisants : quand les utiliser et association interdite ?","back":"Si BB CI ou mal tolérés ; **ne pas associer aux BB** (trouble de conduction).","prio":"P2","sec":"s14"},{"id":"fc-221-191db7","poly":"cardio","fiche":"221","front":"Dérivés nitrés : association contre-indiquée ?","back":"**IPDE5** (sildénafil).","prio":"P1","sec":"s14"},{"id":"fc-221-981cee","poly":"cardio","fiche":"221","front":"Ivabradine : conditions d'utilisation ?","back":"BB CI ou mal tolérés, **rythme sinusal**, **FC ≥ 70 bpm** ; inefficace en **FA**.","prio":"P3","sec":"s14"},{"id":"fc-221-1a9b96","poly":"cardio","fiche":"221","front":"Antiangineux : effets indésirables caractéristiques ?","back":"Dihydropyridines : **œdèmes des MI** ; nitrés : céphalées ; nicorandil : **ulcérations** ; ivabradine : **phosphènes**.","prio":"P3","sec":"s14"},{"id":"fc-221-ecbace","poly":"cardio","fiche":"221","front":"Après SCA : indications d'un IPP associé à l'aspirine ?","back":"Risque hémorragique digestif : **âge ≥ 65 ans**, **ATCD d'ulcère**, **corticothérapie** prolongée.","prio":"P3","sec":"s14"},{"id":"fc-221-f60521","poly":"cardio","fiche":"221","front":"Après SCA : indication de l'antiminéralocorticoïde ?","back":"**FEVG ≤ 40 %** avec **IC congestive** ou **diabète**, après BB et IEC.","prio":"P3","sec":"s14"},{"id":"fc-221-8fb060","poly":"cardio","fiche":"221","front":"Antiminéralocorticoïde : contre-indications ?","back":"**Insuffisance rénale** (créatinine > 221 µmol/L), **hyperkaliémie**.","prio":"P3","sec":"s14"},{"id":"fc-221-ea39ae","poly":"cardio","fiche":"221","front":"Après SCA : réadaptation cardiovasculaire ?","back":"**Recommandée et proposée à tous** (hospitalisation ou ambulatoire), avec éducation thérapeutique.","prio":"P1","sec":"s14"},{"id":"fc-221-1f5b2e","poly":"cardio","fiche":"221","front":"Angor stable : revascularisation systématique versus traitement médical optimal ?","back":"La revascularisation systématique **ne fait pas mieux**.","prio":"P2","sec":"s14"},{"id":"fc-221-b6c84b","poly":"cardio","fiche":"221","front":"Angor stable : place des dihydropyridines ?","back":"**1re intention** si CI aux BB ou FC < 60 bpm ; **2e intention** avec les BB si angor résiduel.","prio":"P3","sec":"s14"},{"id":"fc-221-5bb50c","poly":"cardio","fiche":"221","front":"Rupture de plaque en urgence : traitement antithrombotique ?","back":"**Antiplaquettaires** (aspirine, clopidogrel) + **héparine**.","prio":"P1","sec":"s15"},{"id":"fc-221-1c48bf","poly":"cardio","fiche":"221","front":"SCA : dose initiale puis d'entretien de l'aspirine ?","back":"**250 mg IVD**, puis **75-100 mg/j** per os.","prio":"P1","sec":"s15"},{"id":"fc-221-ce6b35","poly":"cardio","fiche":"221","front":"SCA : posologie du clopidogrel ?","back":"Charge **600 mg** per os puis **75 mg/j** ; avec fibrinolyse : **300 mg** seulement si âge < 75 ans.","prio":"P2","sec":"s15"},{"id":"fc-221-c9c15d","poly":"cardio","fiche":"221","front":"SCA : posologie du prasugrel et du ticagrélor ?","back":"Prasugrel **60 mg** puis **10 mg/j** ; ticagrélor **180 mg** puis **90 mg × 2/j**.","prio":"P2","sec":"s15"},{"id":"fc-221-7353a2","poly":"cardio","fiche":"221","front":"Prasugrel : contre-indication et situations où il est non recommandé ?","back":"**ATCD d'AVC** ; non recommandé après **75 ans** et/ou si poids **< 60 kg**.","prio":"P2","sec":"s15"},{"id":"fc-221-57d77a","poly":"cardio","fiche":"221","front":"Ticagrélor : effets indésirables réversibles ?","back":"**Bradycardie** et **dyspnée**.","prio":"P3","sec":"s15"},{"id":"fc-221-a841d0","poly":"cardio","fiche":"221","front":"SCA avec angioplastie immédiate : anticoagulation ?","back":"HNF **70-100 UI/kg IVD** ou énoxaparine **0,5 mg/kg IVD**.","prio":"P2","sec":"s15"},{"id":"fc-221-2025fd","poly":"cardio","fiche":"221","front":"SCA ST- à haut risque : anticoagulation ?","back":"Énoxaparine **1 mg/kg SC × 2/j** ou fondaparinux **2,5 mg/j SC**.","prio":"P3","sec":"s15"},{"id":"fc-221-b9b9aa","poly":"cardio","fiche":"221","front":"Ischémie aiguë de membre : héparinothérapie ?","back":"HNF bolus **5 000 UI** puis **500 UI/kg/j** IV, **TCA entre 2 et 3**, dès le diagnostic.","prio":"P2","sec":"s15"},{"id":"fc-221-4f8214","poly":"cardio","fiche":"221","front":"Ischémie aiguë de membre : mesures associées ?","back":"Antalgiques de **niveau 3**, **oxygène** nasal, remplissage si besoin, **soins locaux** immédiats.","prio":"P3","sec":"s15"},{"id":"fc-221-2eb5d2","poly":"cardio","fiche":"221","front":"Ischémie aiguë de membre : traitement au long cours selon l'origine ?","back":"Thrombotique : **antiagrégant** + FDR ; embolique : traitement **étiologique** (anticoagulation si FA).","prio":"P3","sec":"s15"},{"id":"fc-221-7c65a7","poly":"cardio","fiche":"221","front":"SCA ST- : bithérapie antiagrégante dès l'admission ?","back":"**Non** tant que la coronarographie n'est pas faite (sauf délai **> 24 h**).","prio":"P2","sec":"s15"},{"id":"fc-221-280d27","poly":"cardio","fiche":"221","front":"SCA : choix de l'inhibiteur P2Y12 ?","back":"**Prasugrel ou ticagrélor** en 1re intention si angioplastie primaire ; **clopidogrel** si CI, risque hémorragique ou **fibrinolyse**.","prio":"P2","sec":"s15"},{"id":"fc-221-ab6234","poly":"cardio","fiche":"221","front":"Polyathéromateux : rythme du bilan clinique de suivi ?","back":"**Annuel**, examen de **tous les territoires** artériels.","prio":"P1","sec":"s16"},{"id":"fc-221-6a548d","poly":"cardio","fiche":"221","front":"Polyathéromateux au long cours : réévaluations régulières ?","back":"**FDR**, **risque CV global**, bilan d'extension annuel ; atteinte des **objectifs de prévention secondaire**.","prio":"P2","sec":"s16"},{"id":"fc-221-a864e0","poly":"cardio","fiche":"221","front":"Polyathéromateux : 4 apprentissages de l'éducation thérapeutique ?","back":"**Activité physique** et hygiène · **observance/tolérance** · **objectifs** de prévention · **signes d'alerte** (douleur thoracique, déficit).","prio":"P2","sec":"s16"},{"id":"fc-222-2191e4","poly":"cardio","fiche":"222","front":"Facteur de risque cardiovasculaire : définition ?","back":"Donnée clinique ou biologique qui augmente le risque de maladie **et** en est une **cause** : le réduire diminue la maladie.","prio":"P1","sec":"s1"},{"id":"fc-222-9d3ff9","poly":"cardio","fiche":"222","front":"Marqueur de risque : définition ?","back":"Simple **témoin** qui évolue avec la maladie ; le faire baisser **ne change pas** son évolution.","prio":"P1","sec":"s1"},{"id":"fc-222-8211fb","poly":"cardio","fiche":"222","front":"Lien causal d'un facteur de risque : 5 conditions ?","back":"**Précède** la maladie · relation **dose-effet** · caractère **universel** · **plausible** · liaison **forte et indépendante**.","prio":"P1","sec":"s1"},{"id":"fc-222-b59568","poly":"cardio","fiche":"222","front":"Prévention CV : principe général ?","back":"Supprimer ou abaisser autant que possible **l'ensemble** des facteurs de risque.","prio":"P2","sec":"s1"},{"id":"fc-222-84baeb","poly":"cardio","fiche":"222","front":"Prévention primaire : définition et objectif ?","back":"Sujet **sans aucun accident vasculaire** ; réduire l'incidence en dépistant et contrôlant les FDR.","prio":"P1","sec":"s1"},{"id":"fc-222-cda528","poly":"cardio","fiche":"222","front":"Prévention secondaire : définition ?","back":"Après un **accident vasculaire** **ou** devant des **lésions vasculaires documentées**.","prio":"P1","sec":"s1"},{"id":"fc-222-81ed4c","poly":"cardio","fiche":"222","front":"Prévention secondaire : objectifs ?","back":"Réduire le risque de **récidive** et **freiner la progression** des lésions.","prio":"P2","sec":"s1"},{"id":"fc-222-25b5f6","poly":"cardio","fiche":"222","front":"Prévention primosecondaire : population visée ?","back":"Patients sans pathologie CV cliniquement décelable mais avec des **lésions athéromateuses infracliniques**.","prio":"P1","sec":"s1"},{"id":"fc-222-0a8a62","poly":"cardio","fiche":"222","front":"Prévention individuelle : de quoi dépend son effet ?","back":"D'autant plus grand que le **risque CV global** (tous les FDR) est **élevé**.","prio":"P1","sec":"s1"},{"id":"fc-222-f34859","poly":"cardio","fiche":"222","front":"Prévention collective : caractéristiques ?","back":"Mesures simples à **effet individuel modéré**, mais fort impact car touchant un **très grand nombre**.","prio":"P2","sec":"s1"},{"id":"fc-222-9508e8","poly":"cardio","fiche":"222","front":"Recommandations HAS de prévention CV : 4 grands facteurs de risque ciblés ?","back":"**Dyslipidémies**, **HTA**, **diabète**, **tabagisme**.","prio":"P2","sec":"s1"},{"id":"fc-222-91d711","poly":"cardio","fiche":"222","front":"Facteurs de risque CV non modifiables ?","back":"**Âge**, **sexe masculin**, **hérédité**.","prio":"P1","sec":"s2"},{"id":"fc-222-2e4119","poly":"cardio","fiche":"222","front":"Décès cardiovasculaires : répartition par sexe en nombre absolu ?","back":"Plus nombreux chez la **femme (54 %)**.","prio":"P2","sec":"s2"},{"id":"fc-222-def54b","poly":"cardio","fiche":"222","front":"Mortalité CV avant 65 ans : homme versus femme ?","back":"**3 à 4 fois** plus élevée chez l'homme ; accidents **10 ans plus tôt** en moyenne.","prio":"P2","sec":"s2"},{"id":"fc-222-d474f3","poly":"cardio","fiche":"222","front":"Hérédité cardiovasculaire : définition ?","back":"Événement **précoce** chez un parent ou dans la fratrie : **< 55 ans** (homme), **< 65 ans** (femme).","prio":"P1","sec":"s2"},{"id":"fc-222-58d59a","poly":"cardio","fiche":"222","front":"Hérédité CV : 2 mécanismes possibles ?","back":"Transmission **génétique** d'un FDR modifiable, ou souvent **environnement familial** défavorable (tabac, alimentation, sédentarité).","prio":"P2","sec":"s2"},{"id":"fc-222-c9a589","poly":"cardio","fiche":"222","front":"Étude Interheart : nombre de facteurs modifiables d'IDM retenus ?","back":"**9 facteurs**, à tout âge et dans les deux sexes.","prio":"P1","sec":"s2"},{"id":"fc-222-d98236","poly":"cardio","fiche":"222","front":"Interheart : 6 facteurs de risque délétères ?","back":"**Tabac**, **hypercholestérolémie**, **HTA**, **diabète**, **obésité abdominale**, **facteurs psychosociaux**.","prio":"P1","sec":"s2"},{"id":"fc-222-ba3c2c","poly":"cardio","fiche":"222","front":"Interheart : facteurs protecteurs (rang A) ?","back":"**Fruits et légumes** et **activité physique**.","prio":"P1","sec":"s2"},{"id":"fc-222-59f12f","poly":"cardio","fiche":"222","front":"Interheart : part des IDM expliqués par les 9 facteurs ?","back":"**90 %**.","prio":"P3","sec":"s2"},{"id":"fc-222-f463c2","poly":"cardio","fiche":"222","front":"Consommation légère d'alcool et risque CV ?","back":"Associée à une **absence de risque**, voire une possible **baisse** du risque CV.","prio":"P3","sec":"s2"},{"id":"fc-222-d88209","poly":"cardio","fiche":"222","front":"Tabac : rang parmi les causes de mortalité ?","back":"**1re cause de mortalité évitable**.","prio":"P1","sec":"s3"},{"id":"fc-222-756099","poly":"cardio","fiche":"222","front":"Tabac : décès annuels dans le monde ?","back":"Environ **5 millions** ; 1 décès sur 5 chez l'homme, 1 sur 20 chez la femme.","prio":"P3","sec":"s3"},{"id":"fc-222-3cb197","poly":"cardio","fiche":"222","front":"Tabac en France : décès annuels et part cardiovasculaire ?","back":"**73 000 décès/an** (dont ~2 000 par tabagisme passif) ; **un quart** cardiovasculaires.","prio":"P1","sec":"s3"},{"id":"fc-222-ffd340","poly":"cardio","fiche":"222","front":"Tabac : 4 mécanismes de toxicité cardiovasculaire ?","back":"**Baisse du HDL-C** · sang **thrombogène** · altération de la **vasomotricité** (spasmes) · **CO** gênant le transport d'O₂.","prio":"P2","sec":"s3"},{"id":"fc-222-ce5ef3","poly":"cardio","fiche":"222","front":"Nicotine : rôle dans les complications CV du tabac ?","back":"**Aucun rôle propre** ; elle crée surtout la **dépendance**.","prio":"P1","sec":"s3"},{"id":"fc-222-fb4895","poly":"cardio","fiche":"222","front":"Substituts nicotiniques : effets sur FC et PA ?","back":"Les petits effets de la cigarette sur FC et PAS **disparaissent totalement** sous substituts.","prio":"P2","sec":"s3"},{"id":"fc-222-53fc85","poly":"cardio","fiche":"222","front":"Interheart : rang du tabac parmi les facteurs de risque d'IDM ?","back":"**2e**, juste derrière les **dyslipidémies**.","prio":"P2","sec":"s3"},{"id":"fc-222-e03eed","poly":"cardio","fiche":"222","front":"Tabac : existe-t-il un seuil de consommation sans danger ?","back":"**Non** : risque proportionnel à la consommation, **sans seuil**.","prio":"P1","sec":"s3"},{"id":"fc-222-b23073","poly":"cardio","fiche":"222","front":"Tabac : le risque varie-t-il selon le mode de consommation ?","back":"**Non** : identique (cigarette avec/sans filtre, pipe, cigare, narguilé, tabac à mâcher).","prio":"P1","sec":"s3"},{"id":"fc-222-fccbaa","poly":"cardio","fiche":"222","front":"Accident coronarien aigu du sujet jeune : facteur de risque essentiel ?","back":"Le **tabac**, souvent **isolé**.","prio":"P1","sec":"s3"},{"id":"fc-222-b59abc","poly":"cardio","fiche":"222","front":"Tabagisme passif : augmentation du risque d'IDM ?","back":"**+24 %** pour 1-7 h/semaine ; **+62 %** au-delà de 22 h/semaine.","prio":"P3","sec":"s3"},{"id":"fc-222-51d2c1","poly":"cardio","fiche":"222","front":"AOMI : proportion de fumeurs ?","back":"**90 %**.","prio":"P1","sec":"s3"},{"id":"fc-222-e056d2","poly":"cardio","fiche":"222","front":"Tabac : atteintes CV hors coronaires ?","back":"**AOMI**, **anévrisme de l'aorte abdominale**, **AVC** (corrélé à la consommation).","prio":"P2","sec":"s3"},{"id":"fc-222-2ce433","poly":"cardio","fiche":"222","front":"Maladie coronarienne : facteur de risque le plus important ?","back":"L'**hypercholestérolémie**.","prio":"P1","sec":"s4"},{"id":"fc-222-a44fc1","poly":"cardio","fiche":"222","front":"Cholestérolémie totale et risque coronarien : type de relation ?","back":"Corrélation **positive** et **exponentielle**.","prio":"P3","sec":"s4"},{"id":"fc-222-042d30","poly":"cardio","fiche":"222","front":"Cholestérol : fraction déterminante au niveau individuel ?","back":"Le **LDL-C élevé**.","prio":"P1","sec":"s4"},{"id":"fc-222-1aeb2b","poly":"cardio","fiche":"222","front":"HDL-C : rôle dans le risque CV ?","back":"HDL-C **bas** = FDR **indépendant** ; élevé = protecteur, **mais pas au-delà de 1 g/L**.","prio":"P2","sec":"s4"},{"id":"fc-222-0919d2","poly":"cardio","fiche":"222","front":"Bilan lipidique de référence : composition ?","back":"**EAL à jeun** : cholestérol total, **HDL-C**, **triglycérides** ; LDL-C calculé.","prio":"P1","sec":"s4"},{"id":"fc-222-de3585","poly":"cardio","fiche":"222","front":"Formule de Friedewald ?","back":"**LDL-C = CT − HDL-C − TG/5** (en g/L).","prio":"P1","sec":"s4"},{"id":"fc-222-1c9b4a","poly":"cardio","fiche":"222","front":"Formule de Friedewald : condition de validité ?","back":"**TG < 3,5 g/L**.","prio":"P1","sec":"s4"},{"id":"fc-222-fefec5","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale : mutations en cause ?","back":"Surtout le **récepteur au LDL**, plus rarement **apoB** ou **PCSK9**.","prio":"P3","sec":"s4"},{"id":"fc-222-ef7809","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale hétérozygote : fréquence et LDL-C ?","back":"**1/500** ; LDL-C **2 à 4 g/L**.","prio":"P1","sec":"s4"},{"id":"fc-222-e923a4","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale hétérozygote : signes cliniques ?","back":"Parfois **xanthomes tendineux** (calcanéen, extenseurs), **arc cornéen**, **xanthélasma**.","prio":"P2","sec":"s4"},{"id":"fc-222-cdf020","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale hétérozygote non traitée : âge des complications coronariennes ?","back":"Dès la **quarantaine**, voire avant si autres FDR.","prio":"P2","sec":"s4"},{"id":"fc-222-35dac2","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale homozygote : fréquence, LDL-C, complications ?","back":"**1/1 000 000** ; LDL-C **> 5 g/L** ; complications coronariennes possibles **avant 20 ans**.","prio":"P2","sec":"s4"},{"id":"fc-222-7b6eed","poly":"cardio","fiche":"222","front":"Hypercholestérolémies : forme la plus fréquente ?","back":"**Polygénique** (terrain génétique + alimentation riche en graisses saturées).","prio":"P2","sec":"s4"},{"id":"fc-222-d1d1cf","poly":"cardio","fiche":"222","front":"HTA : prévalence chez l'adulte en France ?","back":"**20 à 30 %** ; < 5 % avant 35 ans, **> 60 %** après 65 ans.","prio":"P3","sec":"s5"},{"id":"fc-222-e997ca","poly":"cardio","fiche":"222","front":"HTA : seuil en consultation ?","back":"PA **≥ 140/90 mmHg**, persistante.","prio":"P1","sec":"s5"},{"id":"fc-222-9e462a","poly":"cardio","fiche":"222","front":"HTA : seuil en automesure ?","back":"**≥ 135/85 mmHg**.","prio":"P1","sec":"s5"},{"id":"fc-222-8b237c","poly":"cardio","fiche":"222","front":"HTA : seuil en MAPA des 24 h ?","back":"**≥ 130/80 mmHg**.","prio":"P1","sec":"s5"},{"id":"fc-222-4c53f4","poly":"cardio","fiche":"222","front":"« PA élevée » (ESC 2024) : définition et conduite ?","back":"PA **> 120/70** sans critère d'HTA ; évaluer le **risque CV global** (SCORE2) et discuter un antihypertenseur.","prio":"P3","sec":"s5"},{"id":"fc-222-c7baae","poly":"cardio","fiche":"222","front":"HTA stade 1 : chiffres ?","back":"PAS **140-159** · PAD **90-99 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-c904e6","poly":"cardio","fiche":"222","front":"HTA stade 2 : chiffres ?","back":"PAS **160-179** · PAD **100-109 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-33d75d","poly":"cardio","fiche":"222","front":"HTA stade 3 : chiffres ?","back":"PAS **≥ 180** · PAD **≥ 110 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-587474","poly":"cardio","fiche":"222","front":"HTA systolique isolée : définition ?","back":"PAS **≥ 140** et PAD **< 90 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-9144c1","poly":"cardio","fiche":"222","front":"HTA : 3 organes cibles ?","back":"**Cœur** (coronaires, IC), **cerveau** (AVC), **reins** (insuffisance rénale).","prio":"P1","sec":"s5"},{"id":"fc-222-f019de","poly":"cardio","fiche":"222","front":"HTA secondaire : proportion et causes ?","back":"**10 %** : maladie **rénale**, cause **hormonale** (surrénalienne), **médicaments** ou toxiques.","prio":"P1","sec":"s5"},{"id":"fc-222-7edfea","poly":"cardio","fiche":"222","front":"HTA essentielle : facteurs environnementaux ?","back":"**Surpoids**, **sédentarité**, excès d'**alcool** et de **sel**.","prio":"P2","sec":"s5"},{"id":"fc-222-029dce","poly":"cardio","fiche":"222","front":"Mesure de la PA au cabinet : méthode recommandée ?","back":"**Appareil semi-automatique**, mesures répétées sur **plus d'une visite** ; stéthoscope seulement si **FA**.","prio":"P2","sec":"s5"},{"id":"fc-222-c888b0","poly":"cardio","fiche":"222","front":"HTA : comment confirmer le diagnostic ?","back":"Mesure **hors du cabinet** : **automesure** ou **MAPA** ; jamais sur une seule mesure.","prio":"P1","sec":"s5"},{"id":"fc-222-6c6af1","poly":"cardio","fiche":"222","front":"MAPA : indications ?","back":"Effet **blouse blanche**, **HTA masquée**, HTA **résistante**, absence de baisse nocturne, hypotension (diabétique, sujet âgé).","prio":"P2","sec":"s5"},{"id":"fc-222-077c31","poly":"cardio","fiche":"222","front":"HTA masquée : définition ?","back":"**Absente au cabinet** mais **confirmée en MAPA**.","prio":"P2","sec":"s5"},{"id":"fc-222-a7b842","poly":"cardio","fiche":"222","front":"Automesure tensionnelle : 2 usages ?","back":"**Confirmer** le diagnostic d'HTA hors du cabinet et **vérifier l'efficacité du traitement**.","prio":"P2","sec":"s5"},{"id":"fc-222-2ece22","poly":"cardio","fiche":"222","front":"Diabète : critères diagnostiques ?","back":"Glycémie à jeun **> 1,26 g/L (7 mmol/L) à 2 reprises**, ou **> 2 g/L (11,1 mmol/L)** à tout moment.","prio":"P1","sec":"s6"},{"id":"fc-222-0ff00d","poly":"cardio","fiche":"222","front":"Hyperglycémie à jeun non diabétique : définition ?","back":"Glycémie à jeun **entre 1,00 et 1,26 g/L**.","prio":"P1","sec":"s6"},{"id":"fc-222-334be0","poly":"cardio","fiche":"222","front":"Diabète en France : prévalence et répartition des types ?","back":"**≈ 3 millions** (5 %) ; type 1 ≈ 5 %, **type 2 ≈ 95 %**.","prio":"P3","sec":"s6"},{"id":"fc-222-19264b","poly":"cardio","fiche":"222","front":"Diabète de type 2 : circonstances de découverte habituelles ?","back":"**Dépistage systématique** : > 50 ans, sédentaire, surpoids, asymptomatique, souvent hérédité de diabète.","prio":"P2","sec":"s6"},{"id":"fc-222-7771d1","poly":"cardio","fiche":"222","front":"Quel type de diabète domine le risque cardiovasculaire ?","back":"Le **DT2** (prévalence élevée et croissante).","prio":"P2","sec":"s6"},{"id":"fc-222-d44ce3","poly":"cardio","fiche":"222","front":"Diabète : complications microvasculaires ?","back":"**Rétinopathie**, **néphropathie**, **neuropathie**.","prio":"P1","sec":"s6"},{"id":"fc-222-faad75","poly":"cardio","fiche":"222","front":"Diabète : complications macrovasculaires ?","back":"**Maladie coronarienne**, **AVC**, **AOMI**.","prio":"P1","sec":"s6"},{"id":"fc-222-3e307c","poly":"cardio","fiche":"222","front":"Diabète : facteur multiplicatif du risque cardiovasculaire ?","back":"**× 2 à 3** (types 1 et 2).","prio":"P3","sec":"s6"},{"id":"fc-222-4e0da5","poly":"cardio","fiche":"222","front":"Maladie cardiovasculaire chez un patient : quel trouble métabolique rechercher ?","back":"Un **diabète** (souvent non diagnostiqué).","prio":"P2","sec":"s6"},{"id":"fc-222-97d6a4","poly":"cardio","fiche":"222","front":"Diabète de type 1 : caractéristiques ?","back":"**Insulinodépendant d'emblée**, début le plus souvent **avant 20 ans** ; ≈ 5 % des diabètes.","prio":"P3","sec":"s6"},{"id":"fc-222-7d7ffb","poly":"cardio","fiche":"222","front":"IMC : formule et seuil d'obésité ?","back":"**Poids/taille²** (kg/m²) ; obésité si **≥ 30**.","prio":"P1","sec":"s7"},{"id":"fc-222-ebf02d","poly":"cardio","fiche":"222","front":"IMC : seuils de maigreur, normal et surpoids ?","back":"Maigreur **< 18,5** ; normal **18,5-25** ; surpoids **25-29,9**.","prio":"P2","sec":"s7"},{"id":"fc-222-95948a","poly":"cardio","fiche":"222","front":"Surpoids et obésité en France : chiffres ?","back":"**≈ 20 millions** en surpoids dont **6 millions** d'obèses.","prio":"P3","sec":"s7"},{"id":"fc-222-546848","poly":"cardio","fiche":"222","front":"Quel indicateur anthropométrique est le mieux corrélé au risque CV ?","back":"Le **périmètre ombilical** (graisse viscérale), mieux que l'IMC.","prio":"P1","sec":"s7"},{"id":"fc-222-4e69fd","poly":"cardio","fiche":"222","front":"Syndrome métabolique (FID 2005) : critère obligatoire ?","back":"**Obésité centrale** : périmètre **≥ 94 cm** (homme), **≥ 80 cm** (femme).","prio":"P1","sec":"s7"},{"id":"fc-222-038e75","poly":"cardio","fiche":"222","front":"Syndrome métabolique : critères associés (au moins 2) ?","back":"**TG > 1,50 g/L** · **HDL-C < 0,40** (H) / **< 0,50 g/L** (F) · **PA ≥ 130/85** · **glycémie > 1 g/L** ou DT2.","prio":"P1","sec":"s7"},{"id":"fc-222-b2cddb","poly":"cardio","fiche":"222","front":"Cumul de plusieurs facteurs de risque : effet sur le risque ?","back":"Les risques se **multiplient** (ne s'additionnent pas).","prio":"P2","sec":"s7"},{"id":"fc-222-e268dc","poly":"cardio","fiche":"222","front":"Facteurs psychosociaux de risque CV : exemples ?","back":"**Dépression**, troubles psychiques, catégorie sociale **défavorisée**, **isolement social**.","prio":"P2","sec":"s7"},{"id":"fc-222-38845a","poly":"cardio","fiche":"222","front":"Facteurs psychosociaux : pourquoi absents des équations de risque ?","back":"Faute d'**évaluation simple et rigoureuse**.","prio":"P2","sec":"s7"},{"id":"fc-222-05688f","poly":"cardio","fiche":"222","front":"Alcool en excès : effet tensionnel ?","back":"**Favorise l'HTA** ; sa réduction fait partie des mesures hygiénodiététiques.","prio":"P2","sec":"s7"},{"id":"fc-222-111ebc","poly":"cardio","fiche":"222","front":"Évaluer le risque CV global : intérêt ?","back":"Repérer les personnes qui **profiteront le plus** de la prévention.","prio":"P1","sec":"s8"},{"id":"fc-222-6995de","poly":"cardio","fiche":"222","front":"Risque CV global : définition ?","back":"Probabilité de développer une maladie CV dans un temps donné, compte tenu de **tous** les FDR.","prio":"P2","sec":"s8"},{"id":"fc-222-d3c66d","poly":"cardio","fiche":"222","front":"Prévention primaire : scores européens de risque CV ?","back":"**SCORE2**, **SCORE2-OP**, **SCORE2-Diabetes** (connaître leur existence, pas les calculer).","prio":"P2","sec":"s8"},{"id":"fc-222-1c9651","poly":"cardio","fiche":"222","front":"Ancien SCORE (ESC 2016) : ce qu'il estimait ?","back":"Seulement la **mortalité** CV à 10 ans, de 40 à 65 ans.","prio":"P3","sec":"s8"},{"id":"fc-222-429c58","poly":"cardio","fiche":"222","front":"SCORE2 : population et événements estimés ?","back":"**40-69 ans** apparemment sains ; événements **mortels et non mortels** (IDM, AVC) à **10 ans**.","prio":"P2","sec":"s8"},{"id":"fc-222-e8bb19","poly":"cardio","fiche":"222","front":"SCORE2 : paramètres utilisés ?","back":"Région, **sexe**, **âge**, **tabagisme** actif, **PAS**, **cholestérol total**, **HDL-C**.","prio":"P3","sec":"s8"},{"id":"fc-222-db5f0a","poly":"cardio","fiche":"222","front":"SCORE2-OP : population et particularité ?","back":"**≥ 70 ans** ; **ajusté aux risques concurrents** (sinon surestimation du risque et du bénéfice).","prio":"P3","sec":"s8"},{"id":"fc-222-e1344a","poly":"cardio","fiche":"222","front":"SCORE2-Diabetes : population et paramètres ajoutés ?","back":"**DT2 de 40-69 ans** sans maladie CV ; ajoute **âge au diagnostic**, **HbA1c**, **DFGe**.","prio":"P3","sec":"s8"},{"id":"fc-222-571ef6","poly":"cardio","fiche":"222","front":"SCORE2 : groupe de risque de la France ?","back":"Groupe **à faible risque**.","prio":"P3","sec":"s8"},{"id":"fc-222-2edfa5","poly":"cardio","fiche":"222","front":"SCORE2 et SCORE2-OP : situations où ils ne s'appliquent pas ?","back":"Maladie CV **documentée**, **diabète**, **hypercholestérolémie familiale**, **insuffisance rénale**, **grossesse** (d'emblée haut risque).","prio":"P2","sec":"s8"},{"id":"fc-222-07405d","poly":"cardio","fiche":"222","front":"SCORE2 < 50 ans : seuils de risque élevé et très élevé ?","back":"Élevé **2,5 à < 7,5 %** ; très élevé **≥ 7,5 %**.","prio":"P3","sec":"s9"},{"id":"fc-222-04f29a","poly":"cardio","fiche":"222","front":"SCORE2 entre 50 et 69 ans : seuils de risque élevé et très élevé ?","back":"Élevé **5 à < 10 %** ; très élevé **≥ 10 %**.","prio":"P2","sec":"s9"},{"id":"fc-222-bcbe86","poly":"cardio","fiche":"222","front":"SCORE2-OP ≥ 70 ans : seuils de risque élevé et très élevé ?","back":"Élevé **7,5 à < 15 %** ; très élevé **≥ 15 %**.","prio":"P3","sec":"s9"},{"id":"fc-222-da3476","poly":"cardio","fiche":"222","front":"Catégories SCORE2 : indication médicamenteuse selon le risque ?","back":"Faible à modéré : **généralement non** ; élevé : **le plus souvent** ; très élevé : **généralement**.","prio":"P2","sec":"s9"},{"id":"fc-222-b29c51","poly":"cardio","fiche":"222","front":"Seuils SCORE2 variables avec l'âge : pourquoi ?","back":"Éviter de **sous-traiter les jeunes** et de **surtraiter les âgés**.","prio":"P3","sec":"s9"},{"id":"fc-222-0780a0","poly":"cardio","fiche":"222","front":"Sujet sain ≥ 70 ans : hypolipémiant ?","back":"**Peut être envisagé** (classe IIb) ; décision **individuelle et partagée**.","prio":"P3","sec":"s9"},{"id":"fc-222-bab68a","poly":"cardio","fiche":"222","front":"Diabétique : seuil de risque très élevé à 10 ans ?","back":"**≥ 20 %**, ou maladie CV athéroscléreuse, ou lésion grave d'organe cible.","prio":"P2","sec":"s9"},{"id":"fc-222-c3f47f","poly":"cardio","fiche":"222","front":"Diabétique : lésions d'organe cible classant à très haut risque ?","back":"**Insuffisance rénale**, **protéinurie**, **microalbuminurie**, **rétinopathie**.","prio":"P3","sec":"s9"},{"id":"fc-222-c618aa","poly":"cardio","fiche":"222","front":"Insuffisant rénal chronique : niveau de risque CV ?","back":"**D'emblée haut ou très haut risque** ; SCORE2 **sous-estimerait** son risque.","prio":"P2","sec":"s9"},{"id":"fc-222-1e9dec","poly":"cardio","fiche":"222","front":"IRC : marqueurs dont l'aggravation majore le risque CV ?","back":"**Baisse du DFGe** et hausse de l'**albuminurie** (RAC).","prio":"P3","sec":"s9"},{"id":"fc-222-9ffe59","poly":"cardio","fiche":"222","front":"Scores de risque : 2 éléments associés au risque mais non intégrés ?","back":"**Antécédents familiaux** d'accident CV prématuré et **facteurs psychosociaux**.","prio":"P1","sec":"s10"},{"id":"fc-222-bafb3d","poly":"cardio","fiche":"222","front":"Imagerie des organes cibles pour stratifier le risque CV : en routine ?","back":"**Non** (épaisseur intima-média, **score calcique**, HVG échographique).","prio":"P1","sec":"s10"},{"id":"fc-222-6a2a88","poly":"cardio","fiche":"222","front":"Microalbuminurie : signification ?","back":"Marqueur **précoce de néphropathie** ; prédit le risque CV et rénal **indépendamment du DFGe**.","prio":"P2","sec":"s10"},{"id":"fc-222-4a1f97","poly":"cardio","fiche":"222","front":"Diabétique : dépistage de l'IRC ?","back":"**Au moins 1 fois/an** : **rapport albuminurie/créatininurie** (RAC) sur échantillon urinaire.","prio":"P1","sec":"s10"},{"id":"fc-222-a399a7","poly":"cardio","fiche":"222","front":"Biomarqueurs sans valeur ajoutée pour stratifier le risque CV ?","back":"**Facteurs de thrombose**, **CRP ultrasensible**, **homocystéine**.","prio":"P2","sec":"s10"},{"id":"fc-222-bad7af","poly":"cardio","fiche":"222","front":"Prévention primaire : données à recueillir en consultation ?","back":"**Tabac**, **PA**, **poids**, **taille**, **périmètre abdominal**, ATCD familiaux, **alimentation**, **activité physique**.","prio":"P1","sec":"s11"},{"id":"fc-222-f28029","poly":"cardio","fiche":"222","front":"Prévention primaire : biologie de référence ?","back":"**Glycémie** et **bilan lipidique complet à jeun**.","prio":"P1","sec":"s11"},{"id":"fc-222-a7399a","poly":"cardio","fiche":"222","front":"Prévention primaire : conduite selon le niveau de risque ?","back":"Favorable : **encourager** ; faible/modéré : **prévention collective** ; haut risque : prise en charge **médicalisée**.","prio":"P1","sec":"s11"},{"id":"fc-222-94111a","poly":"cardio","fiche":"222","front":"Prévention : conditions d'un changement de comportement durable ?","back":"**Dialogue** médecin-patient de qualité et **éducation thérapeutique** ; convaincre sans contraindre.","prio":"P2","sec":"s11"},{"id":"fc-222-258611","poly":"cardio","fiche":"222","front":"Prévention : quand acquérir les comportements protecteurs pour qu'ils durent ?","back":"**Dès l'enfance et l'adolescence**.","prio":"P3","sec":"s11"},{"id":"fc-222-f19fce","poly":"cardio","fiche":"222","front":"Prévention CV : à quelle occasion l'aborder ?","back":"À **chaque consultation**.","prio":"P2","sec":"s11"},{"id":"fc-222-a0e25c","poly":"cardio","fiche":"222","front":"LDL-C au-dessus de l'objectif, risque faible ou modéré : 1re intention ?","back":"**Modification du mode de vie seule**.","prio":"P1","sec":"s12"},{"id":"fc-222-c167d3","poly":"cardio","fiche":"222","front":"LDL-C au-dessus de l'objectif, risque élevé ou très élevé : 1re intention ?","back":"Mode de vie **associé d'emblée à un hypolipémiant**.","prio":"P1","sec":"s12"},{"id":"fc-222-e9619e","poly":"cardio","fiche":"222","front":"Prévention primaire lipidique : délai de réévaluation ?","back":"**3 mois** ; si objectif non atteint, instaurer/intensifier l'hypolipémiant.","prio":"P1","sec":"s12"},{"id":"fc-222-1226cd","poly":"cardio","fiche":"222","front":"Objectifs de LDL-C selon le risque ?","back":"Faible **< 1,15** ; modéré **< 1** ; élevé **< 0,70** ; très élevé/prévention secondaire **< 0,55 g/L**.","prio":"P1","sec":"s12"},{"id":"fc-222-31b919","poly":"cardio","fiche":"222","front":"Régime hypolipémiant : apport en graisses saturées et œufs ?","back":"Graisses saturées **< 10-12 %** des calories ; pas d'acides gras trans ; **≈ 3 œufs/semaine**.","prio":"P3","sec":"s12"},{"id":"fc-222-cd4a36","poly":"cardio","fiche":"222","front":"Hypolipémiant de 1er choix en prévention primaire ?","back":"Une **statine**, à dose faible/modérée augmentée progressivement.","prio":"P1","sec":"s12"},{"id":"fc-222-76864e","poly":"cardio","fiche":"222","front":"Objectif lipidique non atteint sous statine : stratégie ?","back":"Statine à dose **maximale tolérée** ou plus puissante, puis **+ ézétimibe** (en dernier colestyramine).","prio":"P2","sec":"s12"},{"id":"fc-222-f75b99","poly":"cardio","fiche":"222","front":"Intolérance aux statines : alternatives ?","back":"**Ézétimibe**, voire colestyramine, rarement fibrate.","prio":"P2","sec":"s12"},{"id":"fc-222-3f8be8","poly":"cardio","fiche":"222","front":"Statines : contre-indication citée ?","back":"**Grossesse**.","prio":"P2","sec":"s12"},{"id":"fc-222-414dfa","poly":"cardio","fiche":"222","front":"Sous hypolipémiant : quand contrôler le bilan lipidique ?","back":"**8 à 12 semaines** après le début, puis après chaque adaptation.","prio":"P2","sec":"s12"},{"id":"fc-222-3c2dea","poly":"cardio","fiche":"222","front":"Statine : surveillance des ALAT ?","back":"**Avant**, à **8-12 semaines**, puis **1 fois/an** ; arrêt ou baisse si **> 3 N**.","prio":"P2","sec":"s12"},{"id":"fc-222-b1ec18","poly":"cardio","fiche":"222","front":"Statine : quand doser les CPK et seuil d'arrêt ?","back":"Seulement si **myalgies** ou situation à risque ; arrêt si **CPK > 5 N**.","prio":"P2","sec":"s12"},{"id":"fc-222-c27dea","poly":"cardio","fiche":"222","front":"Prévention primaire lipidique : cible thérapeutique principale et pourquoi ?","back":"Le **LDL-C** : les preuves de bénéfice reposent sur sa baisse ; objectif fixé par la catégorie de risque.","prio":"P1","sec":"s12"},{"id":"fc-222-1d520c","poly":"cardio","fiche":"222","front":"Traitement antihypertenseur : 2 paramètres qui décident ?","back":"**Niveau de PA** et **risque CV global**.","prio":"P1","sec":"s13"},{"id":"fc-222-a83e53","poly":"cardio","fiche":"222","front":"Antihypertenseur : limite d'âge (ESC 2024) ?","back":"**Aucune**.","prio":"P3","sec":"s13"},{"id":"fc-222-178b30","poly":"cardio","fiche":"222","front":"HTA : 4 piliers de la prise en charge ?","back":"**Mesures hygiénodiététiques**, **FDR associés**, **médicaments**, **éducation thérapeutique**.","prio":"P3","sec":"s13"},{"id":"fc-222-f599b4","poly":"cardio","fiche":"222","front":"HTA confirmée : délai de traitement médicamenteux ?","back":"**Traitement immédiat chez tous**.","prio":"P1","sec":"s13"},{"id":"fc-222-81c706","poly":"cardio","fiche":"222","front":"PAS 130-139 avec risque CV élevé : conduite ?","back":"Médicament **après 3 mois** de mesures hygiénodiététiques si cible non atteinte.","prio":"P2","sec":"s13"},{"id":"fc-222-690d9b","poly":"cardio","fiche":"222","front":"PAS 130-139 sans risque élevé : conduite ?","back":"**Pas de médicament** ; surveillance, risque réévalué chaque année.","prio":"P2","sec":"s13"},{"id":"fc-222-80be44","poly":"cardio","fiche":"222","front":"HTA : mesures hygiénodiététiques chiffrées ?","back":"IMC **20-25**, tour de taille < 94/80 cm, alcool **< 10 unités/semaine**, sel **5-6 g/j**, + potassium, arrêt du tabac.","prio":"P2","sec":"s13"},{"id":"fc-222-c47638","poly":"cardio","fiche":"222","front":"Hypertendu : PA cible et délai ?","back":"PAS **120-129**, PAD **70-79 mmHg**, idéalement à **3 mois**.","prio":"P2","sec":"s13"},{"id":"fc-222-602692","poly":"cardio","fiche":"222","front":"HTA : traitement de 1re intention chez la majorité des patients ?","back":"**Bithérapie d'emblée** : IEC/ARA2 + **inhibiteur calcique** ou **diurétique thiazidique**, faible dose, association fixe.","prio":"P1","sec":"s13"},{"id":"fc-222-4f9221","poly":"cardio","fiche":"222","front":"HTA : association interdite ?","back":"**IEC + ARA2**.","prio":"P1","sec":"s13"},{"id":"fc-222-a90bfe","poly":"cardio","fiche":"222","front":"HTA : place du bêtabloquant ?","back":"Seulement s'il existe une **autre indication** ; **jamais en monothérapie**.","prio":"P1","sec":"s13"},{"id":"fc-222-81b3c5","poly":"cardio","fiche":"222","front":"HTA : indications de la monothérapie plutôt que la bithérapie ?","back":"PA élevée 120-139/70-89 avec indication, **fragilité**, **hypotension orthostatique**, âge **≥ 85 ans** ; PA élevée + risque élevé : si **≥ 130/80 après 3 mois** de MHD.","prio":"P2","sec":"s13"},{"id":"fc-222-f83537","poly":"cardio","fiche":"222","front":"Sevrage tabagique : objectif ?","back":"**Arrêt total et définitif**, le plus tôt possible.","prio":"P1","sec":"s14"},{"id":"fc-222-09ef21","poly":"cardio","fiche":"222","front":"Conseil minimum d'arrêt du tabac : principe et effet ?","back":"Aborder le tabac **à chaque consultation** ; peut **doubler le taux de sevrage à 1 an**.","prio":"P1","sec":"s14"},{"id":"fc-222-345a17","poly":"cardio","fiche":"222","front":"Fumeur : évaluations avant sevrage ?","back":"**Motivation**, dépendance physique (**test de Fagerström**), **autres dépendances**.","prio":"P1","sec":"s14"},{"id":"fc-222-1a29af","poly":"cardio","fiche":"222","front":"Substituts nicotiniques : bénéfice ?","back":"Évitent le syndrome de sevrage et **doublent les chances d'arrêt**.","prio":"P1","sec":"s14"},{"id":"fc-222-d8a200","poly":"cardio","fiche":"222","front":"Substituts nicotiniques : schéma de prescription ?","back":"**Patch + forme orale** ; dose ajustée vite ; décroissance sur **au moins 3 mois**.","prio":"P1","sec":"s14"},{"id":"fc-222-35e51f","poly":"cardio","fiche":"222","front":"Fumer sous patch nicotinique : contre-indication ?","back":"**Non** (sevrage progressif possible).","prio":"P2","sec":"s14"},{"id":"fc-222-63085d","poly":"cardio","fiche":"222","front":"Femme enceinte fumeuse : substituts nicotiniques ?","back":"**Prescriptibles**, avec **accompagnement médical**.","prio":"P2","sec":"s14"},{"id":"fc-222-f0be07","poly":"cardio","fiche":"222","front":"Sevrage tabagique : médicaments autres que les substituts ?","back":"**Bupropion** ou **varénicline**.","prio":"P2","sec":"s14"},{"id":"fc-222-6d3abb","poly":"cardio","fiche":"222","front":"Cigarette électronique : place dans le sevrage ?","back":"**Pas un dispositif médical** ; avec nicotine, en **2e intention**, associée aux autres méthodes.","prio":"P2","sec":"s14"},{"id":"fc-222-3b140c","poly":"cardio","fiche":"222","front":"Sevrage tabagique : quand orienter en tabacologie ?","back":"**Dépendance sévère**, **rechutes** antérieures, **dépendances multiples**.","prio":"P2","sec":"s14"},{"id":"fc-222-4f1ca3","poly":"cardio","fiche":"222","front":"Sevrage tabagique : prise de poids moyenne ?","back":"**5 kg** ; bénéfice de l'arrêt bien supérieur.","prio":"P2","sec":"s14"},{"id":"fc-222-693370","poly":"cardio","fiche":"222","front":"Interdiction de fumer dans les lieux publics : effet ?","back":"Baisse **significative et rapide** de l'incidence des **IDM**.","prio":"P2","sec":"s14"},{"id":"fc-222-45d9bf","poly":"cardio","fiche":"222","front":"Sevrage tabagique : thérapies comportementales validées ?","back":"**TCC** (autocontrôle, gestion du stress, affirmation de soi), efficaces dans des études contrôlées.","prio":"P3","sec":"s14"},{"id":"fc-222-eccd6c","poly":"cardio","fiche":"222","front":"PNNS : 4 messages ?","back":"**5 fruits et légumes/j** · **poisson 2 fois/semaine** · limiter graisses saturées, sucres, sel · **activité physique**.","prio":"P1","sec":"s15"},{"id":"fc-222-15b7b5","poly":"cardio","fiche":"222","front":"Activité physique recommandée chez l'adulte ?","back":"**≥ 30 min, 5 j/semaine** : **150-300 min/sem** modérée ou **75-150 min** intense.","prio":"P2","sec":"s15"},{"id":"fc-222-ac0abd","poly":"cardio","fiche":"222","front":"Alimentation méditerranéenne : composition ?","back":"Fruits et légumes, **acides gras insaturés** (huile d'olive), produits de la mer ; **peu de viande rouge**.","prio":"P1","sec":"s15"},{"id":"fc-222-7e9244","poly":"cardio","fiche":"222","front":"Étude validant l'alimentation méditerranéenne ?","back":"**PREDIMED**.","prio":"P2","sec":"s15"},{"id":"fc-222-31b50e","poly":"cardio","fiche":"222","front":"Activité physique minimale réduisant déjà la mortalité CV ?","back":"**1 h 30/semaine** d'intensité modérée (3 à 5 séances).","prio":"P3","sec":"s15"},{"id":"fc-222-e1972a","poly":"cardio","fiche":"222","front":"Activité physique et comorbidités : volume à risque ?","back":"**> 5 h/semaine**.","prio":"P3","sec":"s15"},{"id":"fc-222-09a928","poly":"cardio","fiche":"222","front":"Avant une activité physique modérée ou plus : outil HAS ?","back":"Autoquestionnaire **Q-AAP+**.","prio":"P3","sec":"s15"},{"id":"fc-222-0679fc","poly":"cardio","fiche":"222","front":"Bilan médical minimal avant activité physique : indications ?","back":"**Q-AAP+ positif**, **> 45 ans**, sujet **inactif**, activité très intense, suspicion de maladie.","prio":"P3","sec":"s15"},{"id":"fc-222-8ad029","poly":"cardio","fiche":"222","front":"Épreuve d'effort avant activité > 6 MET chez l'asymptomatique : quand est-elle recommandée ?","back":"Si risque CV **élevé ou très élevé** (actif ou inactif).","prio":"P3","sec":"s15"},{"id":"fc-222-2bc22f","poly":"cardio","fiche":"222","front":"Prévention secondaire : 4 caractéristiques ?","back":"**Systématique**, **multirisque**, **intensive**, **médicalisée**.","prio":"P1","sec":"s16"},{"id":"fc-222-392405","poly":"cardio","fiche":"222","front":"Prévention secondaire : faut-il calculer un score de risque ?","back":"**Non** : risque **d'emblée très élevé**.","prio":"P2","sec":"s16"},{"id":"fc-222-dbf34a","poly":"cardio","fiche":"222","front":"BASIC : signification ?","back":"**B**êtabloquant, **A**ntiagrégant, **S**tatine, **I**EC, **C**ontrôle des facteurs de risque.","prio":"P1","sec":"s16"},{"id":"fc-222-9afda7","poly":"cardio","fiche":"222","front":"BASIC : réduction de mortalité totale post-IDM par classe ?","back":"Environ **25 %** pour chacune des 4 classes.","prio":"P1","sec":"s16"},{"id":"fc-222-668a36","poly":"cardio","fiche":"222","front":"BASIC : contenu du « C » ?","back":"**Arrêt du tabac**, contrôle de la **PA** et de la **glycémie**, lutte contre la **sédentarité**.","prio":"P2","sec":"s16"},{"id":"fc-222-c7486b","poly":"cardio","fiche":"222","front":"Prévention secondaire : place de la statine ?","back":"**Systématique** quels que soient âge, sexe, FDR et cholestérol de départ ; cible **LDL-C < 0,55 g/L**.","prio":"P1","sec":"s16"},{"id":"fc-222-092e13","poly":"cardio","fiche":"222","front":"Après un accident coronarien : quelle démarche chez les apparentés, et surtout dans quel cas ?","back":"Une **enquête familiale** chez les apparentés, surtout si le patient est **jeune**.","prio":"P1","sec":"s16"},{"id":"fc-222-35a9ce","poly":"cardio","fiche":"222","front":"Inhibiteurs de PCSK9 : nature et efficacité ?","back":"**Anticorps SC** (alirocumab, évolocumab) ; baisse supplémentaire du LDL-C **≈ 50 %** sous statine.","prio":"P3","sec":"s16"},{"id":"fc-222-c15dab","poly":"cardio","fiche":"222","front":"Après IDM : statine prescrite et objectif ?","back":"**Atorvastatine 80 mg** ou **rosuvastatine 20 mg** ; LDL-C **< 0,55 g/L** et baisse **≥ 50 %**.","prio":"P1","sec":"s16"},{"id":"fc-222-16e91a","poly":"cardio","fiche":"222","front":"Après IDM : aspirine, dose ?","back":"**75 à 100 mg/j**, au long cours.","prio":"P1","sec":"s16"},{"id":"fc-222-0c5449","poly":"cardio","fiche":"222","front":"Après IDM : doses d'entretien des inhibiteurs P2Y12 ?","back":"Clopidogrel **75 mg/j** ; prasugrel **10 mg/j** ; ticagrélor **90 mg × 2/j** ; habituellement **12 mois**.","prio":"P2","sec":"s16"},{"id":"fc-222-4d05b9","poly":"cardio","fiche":"222","front":"Après IDM à FEVG basse : bêtabloquants validés ?","back":"**Carvédilol**, **métoprolol**, **bisoprolol**, **nébivolol**.","prio":"P2","sec":"s16"},{"id":"fc-222-f6eefc","poly":"cardio","fiche":"222","front":"Bêtabloquant si FEVG basse : schéma de titration ?","back":"Débuter très bas (bisoprolol **1,25 mg/j**), paliers **hebdomadaires** jusqu'à **10 mg/j** selon tolérance.","prio":"P3","sec":"s16"},{"id":"fc-222-e89aec","poly":"cardio","fiche":"222","front":"IEC : contre-indications ?","back":"**Grossesse**, ATCD d'**angio-œdème**, **sténose bilatérale des artères rénales**, **hyperkaliémie**.","prio":"P1","sec":"s16"},{"id":"fc-222-fcf5f0","poly":"cardio","fiche":"222","front":"Après IDM : BB et IEC sont-ils systématiques selon l'item SCA ?","back":"**Non** : formellement indiqués si **FEVG ≤ 40 %** (IEC/ARA2 aussi si diabète ou IRC).","prio":"P2","sec":"s16"},{"id":"fc-222-c7202b","poly":"cardio","fiche":"222","front":"Après IDM : indication de l'éplérénone ?","back":"**FEVG ≤ 40 %** avec IC congestive ou diabète, **après** BB + IEC.","prio":"P3","sec":"s16"},{"id":"fc-222-59ecdc","poly":"cardio","fiche":"222","front":"Après IDM avec indication d'anticoagulation (FA) : schéma ?","back":"Anticoagulant pleine dose **+ clopidogrel 12 mois**, puis anticoagulant seul ; trithérapie possible ≈ 1 mois.","prio":"P3","sec":"s16"},{"id":"fc-222-3dd333","poly":"cardio","fiche":"222","front":"FEVG < 35 % à distance d'un IDM malgré traitement optimal : conduite ?","back":"**Défibrillateur automatique implantable** (≥ 6 semaines post-IDM).","prio":"P2","sec":"s16"},{"id":"fc-222-d670aa","poly":"cardio","fiche":"222","front":"Prévention secondaire : 2 notions inacceptables ?","back":"**Oublier le BASIC** ; **ignorer la cible de LDL-C < 0,55 g/L**.","prio":"P1","sec":"s16"},{"id":"fc-222-165279","poly":"cardio","fiche":"222","front":"Après un SCA : à qui proposer une réadaptation cardiovasculaire ?","back":"À **tout patient** (hospitalisation ou ambulatoire) : surveillance, éducation thérapeutique, reprise de l'activité physique.","prio":"P2","sec":"s16"},{"id":"fc-222-b1016c","poly":"cardio","fiche":"222","front":"Après IDM : quand ajouter l'ézétimibe à la statine ?","back":"**10 mg** si LDL-C au-dessus de l'objectif après **4 semaines** de statine à dose maximale tolérée.","prio":"P3","sec":"s16"},{"id":"fc-222-1f8547","poly":"cardio","fiche":"222","front":"Prévention secondaire : quand associer un IPP ?","back":"Si **risque hémorragique digestif élevé** (âge ≥ 65 ans, ATCD d'ulcère, corticothérapie prolongée…).","prio":"P3","sec":"s16"},{"id":"fc-222-60498f","poly":"cardio","fiche":"222","front":"Après un accident coronarien : bénéfice de l'arrêt du tabac ?","back":"Décès **−36 %** ; récidive d'IDM **−32 %** ; bénéfice aussi important après **pontage** ou **angioplastie**.","prio":"P3","sec":"s17"},{"id":"fc-222-67035d","poly":"cardio","fiche":"222","front":"Coronarien fumeur : substituts nicotiniques ?","back":"**Recommandés** (HAS 2014) : bien tolérés, sans aggravation coronarienne ni trouble du rythme.","prio":"P1","sec":"s17"},{"id":"fc-222-e44d2b","poly":"cardio","fiche":"222","front":"Coronarien fumeur : pourquoi une aide médicalisée ?","back":"Rechutes **fréquentes et précoces** (dépendance forte + changement brutal).","prio":"P2","sec":"s17"},{"id":"fc-222-e3a4c3","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : objectif de base et première étape ?","back":"**PA ≤ 140/90 mmHg**, d'abord par les **mesures hygiénodiététiques**.","prio":"P2","sec":"s17"},{"id":"fc-222-0679e0","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : quand ajouter un médicament ?","back":"PA d'emblée **≥ 160/100**, ou **≥ 140/90 après 3 mois** de mesures hygiénodiététiques.","prio":"P1","sec":"s17"},{"id":"fc-222-e759f5","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : PAS cible selon l'âge (ESC 2021) ?","back":"**120-129** avant 70 ans ; **130-139** à partir de 70 ans (voire jusqu'à 130 si bien toléré) ; **PAD < 80** pour tous.","prio":"P2","sec":"s17"},{"id":"fc-222-b017af","poly":"cardio","fiche":"222","front":"Prévention secondaire : PA cible des points clés ?","back":"**< 130/80 mmHg**.","prio":"P1","sec":"s17"},{"id":"fc-222-e9287d","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : antihypertenseurs de 1re intention ?","back":"**IEC**, **ARA2** ou **bêtabloquant**.","prio":"P2","sec":"s17"},{"id":"fc-222-83415f","poly":"cardio","fiche":"222","front":"Hypertendu angineux : antihypertenseurs préférentiels ?","back":"**Inhibiteur calcique** ou **bêtabloquant**.","prio":"P3","sec":"s17"},{"id":"fc-222-1b681e","poly":"cardio","fiche":"222","front":"Après IDM : facteur multiplicatif du risque lié au diabète ?","back":"**× 2 à 3** le risque d'événement cardiaque grave.","prio":"P2","sec":"s18"},{"id":"fc-222-f310fa","poly":"cardio","fiche":"222","front":"Coronarien diabétique : stratégie principale de prévention ?","back":"**Correction agressive de tous les autres FDR** (bénéfice glycémique post-IDM non démontré).","prio":"P1","sec":"s18"},{"id":"fc-222-ed6750","poly":"cardio","fiche":"222","front":"Enquête familiale : âges définissant un coronarien « relativement jeune » ?","back":"**< 55 ans** (homme), **< 65 ans** (femme).","prio":"P1","sec":"s18"},{"id":"fc-222-ffa2b9","poly":"cardio","fiche":"222","front":"Enquête familiale : qui dépister ?","back":"**Frères, sœurs** et **enfants**, pour une prévention primaire précoce.","prio":"P2","sec":"s18"},{"id":"fc-222-e012e6","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale : objectif de LDL-C jusqu'à 20 ans ?","back":"**< 1,3 g/L**.","prio":"P3","sec":"s18"},{"id":"fc-222-f254bf","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale : dépistage des apparentés ?","back":"**Dépistage en cascade** des apparentés du **1er degré**.","prio":"P2","sec":"s18"},{"id":"fc-222-34f0c3","poly":"cardio","fiche":"222","front":"Coronarien : effet de l'activité physique sur la mortalité ?","back":"Mortalité totale et coronarienne **−20 à 25 %**.","prio":"P1","sec":"s18"},{"id":"fc-222-ab50bb","poly":"cardio","fiche":"222","front":"Coronarien : l'activité physique réduit-elle les récidives d'IDM non mortels ?","back":"**Non**, pas significativement.","prio":"P2","sec":"s18"},{"id":"fc-222-d226dc","poly":"cardio","fiche":"222","front":"Activité physique chez le coronarien : effets biologiques ?","back":"**Antiagrégant**, **anti-inflammatoire**, hausse **VO₂max**, meilleure **fonction endothéliale**, effet **antiarythmique**.","prio":"P3","sec":"s18"},{"id":"fc-222-605679","poly":"cardio","fiche":"222","front":"Coronarien jeune : quelle dyslipidémie génétique évoquer ?","back":"L'**hypercholestérolémie familiale hétérozygote** (LDL-C 2 à 4 g/L).","prio":"P2","sec":"s18"},{"id":"fc-222-776d52","poly":"cardio","fiche":"222","front":"Sous IEC : surveillance biologique ?","back":"**Créatininémie** et **kaliémie** **1 semaine** après l'introduction et chaque hausse de dose.","prio":"P2","sec":"s19"},{"id":"fc-222-3073c7","poly":"cardio","fiche":"222","front":"Sous bêtabloquant : surveillance ?","back":"**FC et PA** à chaque consultation.","prio":"P2","sec":"s19"},{"id":"fc-222-11195e","poly":"cardio","fiche":"222","front":"Après un SCA : examens pour rechercher d'autres localisations athéromateuses ?","back":"Échodoppler des **TSA**, échographie de l'**aorte abdominale**, échodoppler des **MI**.","prio":"P2","sec":"s19"},{"id":"fc-222-1b9a08","poly":"cardio","fiche":"222","front":"Tabac : fréquence de réévaluation au long cours ?","back":"**À chaque visite** (rechutes fréquentes et précoces).","prio":"P2","sec":"s19"},{"id":"fc-222-077ba3","poly":"cardio","fiche":"222","front":"Après IDM : éléments de sortie et suivi ?","back":"**BASIC complet**, **réadaptation**, plan tabac/PA/glycémie/activité ; suivi médecin traitant + cardiologue.","prio":"P2","sec":"s19"},{"id":"fc-223-5c5242","poly":"cardio","fiche":"223","front":"Dyslipidémie : principal danger ?","back":"La **maladie cardiovasculaire athéromateuse**, quel que soit le territoire.","prio":"P1","sec":"s1"},{"id":"fc-223-e0577f","poly":"cardio","fiche":"223","front":"Risque athéromateux : relation avec le LDL-C et le HDL-C ?","back":"**Augmente** avec le LDL-C (et le cholestérol non HDL) ; **diminue** avec le HDL-C ; risque **graduel**.","prio":"P1","sec":"s1"},{"id":"fc-223-3cc11c","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie : de quoi dépend le risque CV associé ?","back":"En grande partie des facteurs qui l'accompagnent : **surpoids**, **diabète**, **HDL bas**.","prio":"P2","sec":"s1"},{"id":"fc-223-baaf23","poly":"cardio","fiche":"223","front":"Triglycérides : seuil de risque de pancréatite aiguë ?","back":"**TG > 10 g/L**.","prio":"P1","sec":"s1"},{"id":"fc-223-a2e683","poly":"cardio","fiche":"223","front":"Dyslipidémie : cible principale du traitement et pourquoi ?","back":"Le **LDL-C** : c'est en le baissant que le **bénéfice CV** a été prouvé.","prio":"P1","sec":"s1"},{"id":"fc-223-8569ad","poly":"cardio","fiche":"223","front":"Hypercholestérolémie pure (HCH) : définition ?","back":"**LDL-C > 1,60 g/L** (ex-type IIa).","prio":"P1","sec":"s1"},{"id":"fc-223-5c0611","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie pure (HTG) : définition ?","back":"**TG > 1,5 g/L** (essentiellement type IV).","prio":"P1","sec":"s1"},{"id":"fc-223-dd3ef9","poly":"cardio","fiche":"223","front":"Hyperlipidémie mixte (HLM) : définition ?","back":"**HCH + HTG** (essentiellement type IIb, très rarement III).","prio":"P1","sec":"s1"},{"id":"fc-223-2a227d","poly":"cardio","fiche":"223","front":"Hypo-HDLémie : définition ?","back":"HDL-C **< 0,40 g/L** (homme), **< 0,50 g/L** (femme) ; peut s'ajouter aux 3 types.","prio":"P1","sec":"s1"},{"id":"fc-223-08db59","poly":"cardio","fiche":"223","front":"Classification de Fredrickson : place actuelle ?","back":"Biochimique, **de moins en moins utilisée** ; on raisonne en HCH, HTG, HLM.","prio":"P2","sec":"s1"},{"id":"fc-223-2e4be3","poly":"cardio","fiche":"223","front":"Bilan lipidique : valeur dans le temps ?","back":"**Photo à un instant donné**, variable avec l'**alimentation** et le **poids**.","prio":"P2","sec":"s1"},{"id":"fc-223-0906aa","poly":"cardio","fiche":"223","front":"Dyslipidémie : le phénotype renseigne-t-il sur le génotype ?","back":"**Pas forcément** : un même génotype peut donner plusieurs phénotypes selon les circonstances.","prio":"P3","sec":"s1"},{"id":"fc-223-9172d4","poly":"cardio","fiche":"223","front":"Étude génétique des dyslipidémies : nécessaire pour traiter ?","back":"**Peu souvent nécessaire** pour décider du traitement.","prio":"P3","sec":"s1"},{"id":"fc-223-9307d8","poly":"cardio","fiche":"223","front":"Bilan lipidique : chez qui est-il conseillé ?","back":"Chez **tout adulte**.","prio":"P1","sec":"s2"},{"id":"fc-223-23c070","poly":"cardio","fiche":"223","front":"Bilan lipidique normal : délai avant de le refaire ?","back":"**Pas avant 5 ans**.","prio":"P1","sec":"s2"},{"id":"fc-223-838e08","poly":"cardio","fiche":"223","front":"EAL : paramètres dosés ?","back":"**Cholestérol total**, **HDL-C**, **triglycérides** ; LDL-C **calculé**.","prio":"P1","sec":"s2"},{"id":"fc-223-51fe0f","poly":"cardio","fiche":"223","front":"Friedewald : formule en g/L et en mmol/L ?","back":"LDL-C = CT − HDL-C − **TG/5** (g/L) ou − **TG/2,2** (mmol/L).","prio":"P1","sec":"s2"},{"id":"fc-223-a49eb9","poly":"cardio","fiche":"223","front":"Friedewald : seuil de TG au-delà duquel le LDL-C calculé n'a pas de valeur ?","back":"**TG ≥ 3,5 g/L**.","prio":"P1","sec":"s2"},{"id":"fc-223-9580fb","poly":"cardio","fiche":"223","front":"Bilan lipidique normal (Afssaps 2005) : 3 conditions réunies ?","back":"LDL-C **< 1,6** · HDL-C **> 0,4** · TG **< 1,5 g/L**, chez un sujet sans autre FDR.","prio":"P1","sec":"s2"},{"id":"fc-223-52e52b","poly":"cardio","fiche":"223","front":"Bilan lipidique anormal : 2 étapes suivantes ?","back":"**Classer** l'anomalie (HCH, HTG, HLM ± hypo-HDL) puis chercher une **cause secondaire**.","prio":"P2","sec":"s2"},{"id":"fc-223-5d4dcc","poly":"cardio","fiche":"223","front":"Dyslipidémie : causes secondaires recherchées à l'interrogatoire ?","back":"**Alcool** et **médicaments**.","prio":"P1","sec":"s3"},{"id":"fc-223-9e7343","poly":"cardio","fiche":"223","front":"Hypothyroïdie : examen et dyslipidémie associée ?","back":"**TSH** ; le plus souvent HCH ou HLM.","prio":"P1","sec":"s3"},{"id":"fc-223-ef376f","poly":"cardio","fiche":"223","front":"Cholestase : examens et dyslipidémie associée ?","back":"**Bilirubine**, **phosphatases alcalines** ; **HCH**.","prio":"P2","sec":"s3"},{"id":"fc-223-1fd687","poly":"cardio","fiche":"223","front":"Syndrome néphrotique : dyslipidémie associée et moyens diagnostiques ?","back":"**HLM** ; **protéinurie**, œdèmes.","prio":"P2","sec":"s3"},{"id":"fc-223-11920e","poly":"cardio","fiche":"223","front":"Insuffisance rénale chronique : dyslipidémie associée ?","back":"**HTG** ou **HLM** (créatinine).","prio":"P2","sec":"s3"},{"id":"fc-223-47333e","poly":"cardio","fiche":"223","front":"Alcoolisme et diabète : dyslipidémie associée ?","back":"**Hypertriglycéridémie**.","prio":"P1","sec":"s3"},{"id":"fc-223-568d14","poly":"cardio","fiche":"223","front":"Médicaments responsables d'hypertriglycéridémie ?","back":"**Œstrogènes**, **rétinoïdes**, **antirétroviraux** ; aussi corticoïdes et antipsychotiques (HTG ou HLM).","prio":"P2","sec":"s3"},{"id":"fc-223-51fe84","poly":"cardio","fiche":"223","front":"Ciclosporine : dyslipidémie induite ?","back":"**HCH** ou **HLM**.","prio":"P3","sec":"s3"},{"id":"fc-223-1a2485","poly":"cardio","fiche":"223","front":"Dyslipidémie : bilan biologique des causes secondaires ?","back":"**TSH**, **bilirubine + PAL**, **protéinurie**, **créatinine**, **glycémie + HbA1c**.","prio":"P1","sec":"s3"},{"id":"fc-223-723d75","poly":"cardio","fiche":"223","front":"Hypercholestérolémie polygénique : fréquence et LDL-C habituel ?","back":"**Très fréquente** ; LDL-C le plus souvent **1,3-2,5 g/L**.","prio":"P2","sec":"s4"},{"id":"fc-223-bb1494","poly":"cardio","fiche":"223","front":"Hypercholestérolémie polygénique : particularité ?","back":"Souvent assez **sensible à l'alimentation**.","prio":"P2","sec":"s4"},{"id":"fc-223-d364c0","poly":"cardio","fiche":"223","front":"Hyperlipidémie familiale combinée : fréquence ?","back":"**1 à 2 %** de la population.","prio":"P2","sec":"s4"},{"id":"fc-223-083d66","poly":"cardio","fiche":"223","front":"Hyperlipidémie familiale combinée : bilan typique ?","back":"**HLM modérée** : CT 2,5-3,5 g/L (LDL-C 1,6-2,5), **TG 1,5-5 g/L**.","prio":"P3","sec":"s4"},{"id":"fc-223-682420","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie familiale : bilan et risque athérogène ?","back":"**HTG pure** chez le sujet et ses apparentés ; risque athérogène **incertain**.","prio":"P2","sec":"s4"},{"id":"fc-223-1785c5","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie familiale : 2 diagnostics différentiels ?","back":"**HTG dépendante de l'alimentation** et **hyperlipidémie familiale combinée**.","prio":"P2","sec":"s4"},{"id":"fc-223-95c983","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : fréquence et bilan ?","back":"**Rare** (1/10 000 à 1/5 000) ; CT 3-6 g/L, TG 4-10 g/L.","prio":"P3","sec":"s4"},{"id":"fc-223-6d1c04","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : 2 conditions d'expression ?","back":"Génotype **apoE E2/E2** + un **facteur associé** (surpoids, diabète, hypothyroïdie, certains traitements).","prio":"P2","sec":"s4"},{"id":"fc-223-5bb132","poly":"cardio","fiche":"223","front":"Hyperchylomicronémies primitives : TG et risque ?","back":"Très rares ; TG **> 10 g/L** (jusqu'à 100) ; risque majeur de **pancréatite aiguë**.","prio":"P2","sec":"s4"},{"id":"fc-223-48cc91","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale monogénique : cause la plus fréquente ?","back":"Mutation du gène du **récepteur aux LDL (LDL-R)**.","prio":"P1","sec":"s4"},{"id":"fc-223-676408","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale par mutation de l'apoB : particularités ?","back":"Plus rare ; LDL moins bien fixées ; hypercholestérolémie **plus modérée** (LDL-C **classiquement 2-3 g/L**), xanthomes rares.","prio":"P3","sec":"s4"},{"id":"fc-223-19f846","poly":"cardio","fiche":"223","front":"Mutation gain de fonction de PCSK9 : mécanisme ?","back":"PCSK9 se lie davantage au LDL-R, qui est **détruit** au lieu d'être recyclé.","prio":"P3","sec":"s4"},{"id":"fc-223-760b4a","poly":"cardio","fiche":"223","front":"Score Dutch-HF : rôle ?","back":"Diagnostic de **probabilité** d'hypercholestérolémie familiale (ATCD, xanthomes, LDL-C).","prio":"P3","sec":"s4"},{"id":"fc-223-473a3e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote : LDL-C avant traitement (points clés) ?","back":"Entre **2 et 4 g/L** ; forme hétérozygote **fréquente**, homozygote très rare.","prio":"P1","sec":"s4"},{"id":"fc-223-3832b9","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote (LDL-R) : fréquence ?","back":"**1/300** (mutation retrouvée dans 80 % des cas).","prio":"P3","sec":"s4"},{"id":"fc-223-801a08","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale homozygote : fréquence, LDL-C, risque ?","back":"**1/500 000** ; LDL-C **> 5 g/L** ; complications dès la **1re décennie**.","prio":"P3","sec":"s4"},{"id":"fc-223-532eea","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote : dépôts lipidiques évocateurs ?","back":"**Xanthomes tendineux** et **arc cornéen prématuré** (inconstants).","prio":"P2","sec":"s4"},{"id":"fc-223-8f05e7","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : xanthomes caractéristiques ?","back":"**Xanthomes plans palmaires** et **tubéreux** jaune orangé.","prio":"P3","sec":"s4"},{"id":"fc-223-535de5","poly":"cardio","fiche":"223","front":"Hyperlipidémie familiale combinée : stabilité du phénotype ?","back":"**Variable** dans une famille, voire chez une même personne (HLM, HCH ou HTG).","prio":"P3","sec":"s4"},{"id":"fc-223-58f846","poly":"cardio","fiche":"223","front":"SCORE2 (ESC 2021) : population et événement estimé ?","back":"**40-69 ans** ; risque à **10 ans** d'événement CV majeur (IDM, AVC, décès CV).","prio":"P1","sec":"s5"},{"id":"fc-223-c967a1","poly":"cardio","fiche":"223","front":"SCORE2 : paramètre lipidique utilisé ?","back":"**Cholestérol non-HDL** (= CT − HDL-C).","prio":"P2","sec":"s5"},{"id":"fc-223-b22d76","poly":"cardio","fiche":"223","front":"SCORE2-OP : population ?","back":"**70 ans ou plus**.","prio":"P2","sec":"s5"},{"id":"fc-223-86278c","poly":"cardio","fiche":"223","front":"SCORE2-Diabetes : population ?","back":"**DT2** sans maladie CV athéroscléreuse ni lésion grave d'organe cible.","prio":"P2","sec":"s5"},{"id":"fc-223-66e19c","poly":"cardio","fiche":"223","front":"Dyslipidémie : situations où SCORE2 n'est pas adapté ?","back":"**Diabète**, **IRC** (DFG < 60), **hypercholestérolémie familiale** (élevé/très élevé d'emblée) ; **prévention secondaire** (très élevé).","prio":"P1","sec":"s5"},{"id":"fc-223-83c4df","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : catégorie de risque CV ?","back":"**Élevé** d'emblée.","prio":"P1","sec":"s5"},{"id":"fc-223-072cdd","poly":"cardio","fiche":"223","front":"Maladie CV établie (coronaire, AIT/AVC, AOMI) : catégorie de risque ?","back":"**Très élevé** d'emblée.","prio":"P1","sec":"s5"},{"id":"fc-223-0cade0","poly":"cardio","fiche":"223","front":"IRC à risque CV très élevé : critères ?","back":"**DFG < 30**, ou **DFG 30-44 avec RAC > 30**.","prio":"P2","sec":"s5"},{"id":"fc-223-77d08b","poly":"cardio","fiche":"223","front":"IRC à risque CV élevé : critères ?","back":"DFG 30-45 et RAC < 30 ; DFG 45-59 et RAC 30-299 ; DFG > 60 et RAC > 300.","prio":"P3","sec":"s5"},{"id":"fc-223-61beba","poly":"cardio","fiche":"223","front":"Diabète à risque modéré : définition ?","back":"**Bien contrôlé depuis < 10 ans**, sans atteinte d'organe cible ni FDR associé.","prio":"P2","sec":"s5"},{"id":"fc-223-cf40cf","poly":"cardio","fiche":"223","front":"Diabète à risque élevé : définition ?","back":"Sans maladie CV ni AOC, mais avec un **FDR associé** ou **> 10 ans** d'évolution.","prio":"P1","sec":"s5"},{"id":"fc-223-e294ca","poly":"cardio","fiche":"223","front":"Diabète à risque très élevé : définition ?","back":"**Maladie CV** ou **AOC sévère** (insuffisance rénale, microangiopathie sur 3 sites).","prio":"P2","sec":"s5"},{"id":"fc-223-2da0c0","poly":"cardio","fiche":"223","front":"Sujet sain 50-69 ans : seuils SCORE2 des catégories ?","back":"Faible-modéré **< 5 %** ; élevé **5-10 %** ; très élevé **> 10 %**.","prio":"P2","sec":"s5"},{"id":"fc-223-6e7590","poly":"cardio","fiche":"223","front":"Sujet sain < 50 ans : seuils SCORE2 ?","back":"Faible-modéré **< 2,5 %** ; élevé **2,5-7,5 %** ; très élevé **> 7,5 %**.","prio":"P3","sec":"s5"},{"id":"fc-223-8d4112","poly":"cardio","fiche":"223","front":"Sujet sain ≥ 70 ans : seuils SCORE2-OP ?","back":"Faible-modéré **< 7,5 %** ; élevé **7,5-15 %** ; très élevé **> 15 %**.","prio":"P3","sec":"s5"},{"id":"fc-223-8e251f","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque faible ?","back":"**< 1,15 g/L** (< 3 mmol/L).","prio":"P1","sec":"s5"},{"id":"fc-223-6a6e5b","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque modéré ?","back":"**< 1 g/L** (< 2,6 mmol/L).","prio":"P1","sec":"s5"},{"id":"fc-223-00a58d","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque élevé ?","back":"**< 0,70 g/L** (< 1,8 mmol/L).","prio":"P1","sec":"s5"},{"id":"fc-223-56291f","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque très élevé ?","back":"**< 0,55 g/L** (< 1,4 mmol/L), en prévention primaire ou secondaire.","prio":"P1","sec":"s5"},{"id":"fc-223-af2ee1","poly":"cardio","fiche":"223","front":"Stratégie ESC : LDL-C au-dessus de la cible versus nettement au-dessus ?","back":"Au-dessus : **envisager** un médicament ; nettement au-dessus : **associer** un médicament.","prio":"P2","sec":"s5"},{"id":"fc-223-3e82b6","poly":"cardio","fiche":"223","front":"Prévention secondaire avec LDL-C au-dessus de la cible : conduite ?","back":"Médicament associé **d'emblée** aux conseils de mode de vie.","prio":"P1","sec":"s5"},{"id":"fc-223-dc04f4","poly":"cardio","fiche":"223","front":"Seuils ESC de LDL-C pour un médicament d'emblée selon le risque ?","back":"**> 1,9 g/L** (faible/modéré) ; **> 1 g/L** (élevé) ; **> 0,70 g/L** (très élevé) ; **> 0,55** (secondaire).","prio":"P3","sec":"s5"},{"id":"fc-223-cf0d1d","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : les 4 cibles générales s'appliquent-elles ?","back":"**Non** : objectifs propres.","prio":"P2","sec":"s5"},{"id":"fc-223-718e26","poly":"cardio","fiche":"223","front":"LDL-C à 1,6 g/L : signification ?","back":"Seuil d'un **bilan normal** chez un sujet sans autre FDR, **pas la cible** thérapeutique.","prio":"P1","sec":"s6"},{"id":"fc-223-fc9210","poly":"cardio","fiche":"223","front":"LDL-C à 1,3 g/L dans l'hypercholestérolémie familiale : signification ?","back":"**Cible jusqu'à 20 ans**.","prio":"P2","sec":"s6"},{"id":"fc-223-f333e7","poly":"cardio","fiche":"223","front":"Coronarien dyslipidémique : faut-il calculer SCORE2 ?","back":"**Non** : maladie CV établie = **très élevé d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-223-b5c1bb","poly":"cardio","fiche":"223","front":"Fibrates « souvent efficaces » : dans quelle dyslipidémie primitive ?","back":"La **dysbêtalipoprotéinémie** (pas l'hypercholestérolémie familiale).","prio":"P3","sec":"s6"},{"id":"fc-223-75696f","poly":"cardio","fiche":"223","front":"Diététique dans les dyslipidémies : indication et durée ?","back":"**Toute** anomalie lipidique et tout FDR ; **au long cours**, même sous médicament.","prio":"P1","sec":"s7"},{"id":"fc-223-22086c","poly":"cardio","fiche":"223","front":"Hypercholestérolémie, régime : apport maximal en acides gras saturés ?","back":"**< 10-12 %** des calories, remplacés par des **mono- ou poly-insaturés**.","prio":"P1","sec":"s7"},{"id":"fc-223-8442d5","poly":"cardio","fiche":"223","front":"Acides gras trans : recommandation ?","back":"**À supprimer** (« partiellement hydrogénés »).","prio":"P2","sec":"s7"},{"id":"fc-223-65431c","poly":"cardio","fiche":"223","front":"Régime hypocholestérolémiant : aliments à augmenter ?","back":"**Oméga-3** (poissons) et **fibres** (fruits, légumes, céréales complètes).","prio":"P2","sec":"s7"},{"id":"fc-223-94d39f","poly":"cardio","fiche":"223","front":"Cholestérol alimentaire : limitation et œufs ?","back":"Limitation **modérée** ; œufs conservés, **≈ 3 par semaine**.","prio":"P2","sec":"s7"},{"id":"fc-223-0f66a6","poly":"cardio","fiche":"223","front":"Régime méditerranéen : repères chiffrés ?","back":"**Huile d'olive** ; **5 portions** de fruits et légumes/j ; fruits à coque **30 g/j**.","prio":"P2","sec":"s7"},{"id":"fc-223-f3c657","poly":"cardio","fiche":"223","front":"Points clés diététiques : lipides totaux, cholestérol alimentaire, sel ?","back":"Lipides **< 35 %** de l'apport ; cholestérol **< 300 mg/j** ; NaCl **< 6 g/j**.","prio":"P3","sec":"s7"},{"id":"fc-223-f410d5","poly":"cardio","fiche":"223","front":"HTG modérée sans hyperchylomicronémie : mesures diététiques ?","back":"**Perte de poids** (graisse abdominale), moins d'**alcool**, moins de **sucres**, équilibre du **diabète**.","prio":"P1","sec":"s7"},{"id":"fc-223-1ef288","poly":"cardio","fiche":"223","front":"HTG modérée : place des médicaments ?","back":"**Impact mineur** ; la diététique est l'essentiel du traitement.","prio":"P2","sec":"s7"},{"id":"fc-223-1aae46","poly":"cardio","fiche":"223","front":"HTG majeure avec hyperchylomicronémie : prise en charge diététique ?","back":"**Avis spécialisé** ; lipides **< 30 g/j**.","prio":"P3","sec":"s7"},{"id":"fc-223-d48ade","poly":"cardio","fiche":"223","front":"Aliments enrichis en stérols végétaux : place ?","back":"Utilisation seulement **discutée**.","prio":"P3","sec":"s7"},{"id":"fc-223-b09f49","poly":"cardio","fiche":"223","front":"Prévention primaire : délai minimal de diététique avant médicament ?","back":"**Au moins 3 mois**, si le LDL-C reste éloigné de la cible.","prio":"P1","sec":"s8"},{"id":"fc-223-6475fb","poly":"cardio","fiche":"223","front":"Prévention primaire : quand un hypolipémiant d'emblée ?","back":"LDL-C **très au-dessus** de la cible.","prio":"P2","sec":"s8"},{"id":"fc-223-bdce9a","poly":"cardio","fiche":"223","front":"Hypercholestérolémie : hypolipémiant de 1er choix et pourquoi ?","back":"**Statine** : bénéfice CV le **mieux démontré**.","prio":"P1","sec":"s8"},{"id":"fc-223-c0fd54","poly":"cardio","fiche":"223","front":"Statine en prévention primaire : posologie initiale ?","back":"**Faible ou modérée**, augmentée progressivement jusqu'à la cible.","prio":"P2","sec":"s8"},{"id":"fc-223-67f5e0","poly":"cardio","fiche":"223","front":"Statines anciennes versus récentes ?","back":"Anciennes : **simvastatine**, **pravastatine** ; récentes : **atorvastatine**, **rosuvastatine**.","prio":"P2","sec":"s8"},{"id":"fc-223-ccab71","poly":"cardio","fiche":"223","front":"Statines : contre-indication ?","back":"**Grossesse**.","prio":"P1","sec":"s8"},{"id":"fc-223-8b057e","poly":"cardio","fiche":"223","front":"Statine : baisse attendue du LDL-C ?","back":"**25 à 50 %** selon la molécule et la dose.","prio":"P3","sec":"s8"},{"id":"fc-223-e7c540","poly":"cardio","fiche":"223","front":"Prévention secondaire : délai de mise sous hypolipémiant ?","back":"**D'emblée**, avec la diététique, souvent à **forte posologie** (baisse > 50 %).","prio":"P1","sec":"s9"},{"id":"fc-223-f684d0","poly":"cardio","fiche":"223","front":"Après un SCA : statine et posologie ?","back":"**Statine forte dose**, ex. atorvastatine **80 mg** ou rosuvastatine **20 mg**.","prio":"P1","sec":"s9"},{"id":"fc-223-396bbb","poly":"cardio","fiche":"223","front":"Après un SCA : double objectif lipidique ?","back":"Baisse du LDL-C **≥ 50 %** et LDL-C **< 0,55 g/L**.","prio":"P1","sec":"s9"},{"id":"fc-223-ca4ac6","poly":"cardio","fiche":"223","front":"Après un SCA, cible non atteinte sous statine : délai et ajout ?","back":"Après **4 semaines** à dose maximale tolérée : **ézétimibe 10 mg**.","prio":"P1","sec":"s9"},{"id":"fc-223-154434","poly":"cardio","fiche":"223","front":"Après un SCA, cible toujours non atteinte malgré l'ézétimibe (item 339) ?","back":"**Inhibiteur de PCSK9**, remboursé si LDL-C **> 0,7 g/L**.","prio":"P2","sec":"s9"},{"id":"fc-223-a2687c","poly":"cardio","fiche":"223","front":"Après un SCA : aspirine et durée du P2Y12 ?","back":"Aspirine **75-100 mg/j** au long cours ; P2Y12 habituellement **12 mois**.","prio":"P2","sec":"s9"},{"id":"fc-223-28b67f","poly":"cardio","fiche":"223","front":"Antiminéralocorticoïde : effets indésirables de la spironolactone ?","back":"**Hyperkaliémie**, insuffisance rénale ; **gynécomastie**, **impuissance**.","prio":"P3","sec":"s9"},{"id":"fc-223-42032e","poly":"cardio","fiche":"223","front":"Après un SCA : quand le bêtabloquant est-il formellement indiqué ?","back":"Si **FEVG ≤ 40 %** (non systématique sinon).","prio":"P3","sec":"s9"},{"id":"fc-223-d7a79e","poly":"cardio","fiche":"223","front":"Après un SCA : quand implanter un DAI ?","back":"**FEVG < 35 %** à **≥ 6 semaines** de l'IDM après optimisation ; gilet en attendant.","prio":"P3","sec":"s9"},{"id":"fc-223-7721f0","poly":"cardio","fiche":"223","front":"Cible de LDL-C non atteinte sous statine : 1re étape ?","back":"**Intensifier** : dose **maximale tolérée** ou statine **plus puissante**.","prio":"P1","sec":"s10"},{"id":"fc-223-6c560b","poly":"cardio","fiche":"223","front":"Cible non atteinte à dose maximale tolérée de statine : 2e étape ?","back":"**Statine + ézétimibe**.","prio":"P1","sec":"s10"},{"id":"fc-223-3074f4","poly":"cardio","fiche":"223","front":"Escalade hypolipémiante (item 223) : dernier recours ?","back":"**Statine + colestyramine**.","prio":"P2","sec":"s10"},{"id":"fc-223-568060","poly":"cardio","fiche":"223","front":"Ézétimibe ajouté à la statine : baisse supplémentaire du LDL-C ?","back":"**≈ 20 %**.","prio":"P3","sec":"s10"},{"id":"fc-223-f75b99","poly":"cardio","fiche":"223","front":"Intolérance aux statines : alternatives ?","back":"**Ézétimibe**, voire colestyramine, **rarement fibrates** ; diététique maintenue.","prio":"P1","sec":"s10"},{"id":"fc-223-b68000","poly":"cardio","fiche":"223","front":"Anti-PCSK9 : molécules et voie ?","back":"**Alirocumab**, **évolocumab** ; anticorps monoclonaux **sous-cutanés**.","prio":"P3","sec":"s10"},{"id":"fc-223-48d8bd","poly":"cardio","fiche":"223","front":"Anti-PCSK9 : efficacité ?","back":"**−50 %** de LDL-C en plus de la statine ; **moins d'événements CV**.","prio":"P3","sec":"s10"},{"id":"fc-223-856871","poly":"cardio","fiche":"223","front":"Anti-PCSK9 : conditions de remboursement ?","back":"**Accord préalable** ; prévention secondaire ou LDL-C **> 0,7 g/L** malgré statine à dose maximale tolérée.","prio":"P3","sec":"s10"},{"id":"fc-223-f777ed","poly":"cardio","fiche":"223","front":"Ajout d'un anti-PCSK9 : que faire de la statine ?","back":"La **poursuivre** à dose maximale tolérée.","prio":"P3","sec":"s10"},{"id":"fc-223-e83c29","poly":"cardio","fiche":"223","front":"HTG : causes secondaires à éliminer ?","back":"**Alcoolisme**, **diabète**, **IRC**, médicaments (œstrogènes, rétinoïdes, antirétroviraux, corticoïdes, antipsychotiques).","prio":"P1","sec":"s11"},{"id":"fc-223-a111b0","poly":"cardio","fiche":"223","front":"HTG entre 1,5 et 5 g/L : traitement ?","back":"**Diététique seule**.","prio":"P1","sec":"s11"},{"id":"fc-223-3782c7","poly":"cardio","fiche":"223","front":"HTG : indication du fibrate ?","back":"**TG > 5 g/L malgré une diététique bien suivie**, en association à celle-ci.","prio":"P1","sec":"s11"},{"id":"fc-223-6bd414","poly":"cardio","fiche":"223","front":"HTG > 5 g/L : traitement éventuellement associé au fibrate ?","back":"**Oméga-3 (n-3) à forte posologie** (formulation non commercialisée en France en 2025).","prio":"P3","sec":"s11"},{"id":"fc-223-d80547","poly":"cardio","fiche":"223","front":"HTG : contrôle biologique après mise en route du traitement ?","back":"Bilan lipidique **8 à 12 semaines** après.","prio":"P2","sec":"s11"},{"id":"fc-223-1fa443","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote : dépistage familial ?","back":"**Dépistage en cascade** des **apparentés du 1er degré**.","prio":"P1","sec":"s12"},{"id":"fc-223-bcaf9e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : cible de LDL-C jusqu'à 20 ans ?","back":"**< 1,3 g/L** (3,4 mmol/L).","prio":"P1","sec":"s12"},{"id":"fc-223-608f5e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale après 20 ans : cible de LDL-C ?","back":"Cible du **risque élevé** (< 0,70) ou de la **prévention secondaire** (< 0,55 g/L).","prio":"P2","sec":"s12"},{"id":"fc-223-90df0e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : traitement ?","back":"**Identique** à l'hypercholestérolémie isolée (diététique, statine, escalade) ; **avis spécialisé** si résistance.","prio":"P2","sec":"s12"},{"id":"fc-223-b00e06","poly":"cardio","fiche":"223","front":"Diabète à risque modéré : cible de LDL-C ?","back":"**< 1 g/L**.","prio":"P2","sec":"s12"},{"id":"fc-223-63cd2f","poly":"cardio","fiche":"223","front":"Diabète avec FDR associé ou > 10 ans d'évolution : cible de LDL-C ?","back":"**< 0,70 g/L** (risque élevé).","prio":"P1","sec":"s12"},{"id":"fc-223-dc0a66","poly":"cardio","fiche":"223","front":"Diabète avec maladie CV ou atteinte d'organe cible sévère : cible de LDL-C ?","back":"**< 0,55 g/L**.","prio":"P2","sec":"s12"},{"id":"fc-223-cc4981","poly":"cardio","fiche":"223","front":"Insuffisance rénale sous statine : précaution ?","back":"IR modérée à sévère = **situation à risque** : doser les **CPK**.","prio":"P2","sec":"s12"},{"id":"fc-223-b6e5f7","poly":"cardio","fiche":"223","front":"Dyslipidémie pendant la grossesse : traitement ?","back":"**Diététique** ; statines **contre-indiquées**.","prio":"P1","sec":"s12"},{"id":"fc-223-d0171c","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : traitement ?","back":"**Diététique** et **statines** ; **fibrates** souvent efficaces.","prio":"P3","sec":"s12"},{"id":"fc-223-a29c82","poly":"cardio","fiche":"223","front":"Hypolipémiant : délai du bilan lipidique de contrôle ?","back":"**8 à 12 semaines** après l'instauration et après chaque adaptation.","prio":"P1","sec":"s13"},{"id":"fc-223-b637a5","poly":"cardio","fiche":"223","front":"Hypolipémiants (surtout statines) : effet indésirable le plus fréquent ?","back":"Les **myalgies** ; surveillance **essentiellement clinique**.","prio":"P1","sec":"s13"},{"id":"fc-223-073bf2","poly":"cardio","fiche":"223","front":"Statine : CPK systématiques ?","back":"**Non** : seulement en **situation à risque**.","prio":"P1","sec":"s13"},{"id":"fc-223-60fbf4","poly":"cardio","fiche":"223","front":"Statine : seuil de CPK imposant l'arrêt ?","back":"**CPK > 5 N** (dosées à distance d'un effort sportif).","prio":"P1","sec":"s13"},{"id":"fc-223-58b2cc","poly":"cardio","fiche":"223","front":"Statine : situations à risque justifiant un dosage des CPK ?","back":"**Douleurs musculaires**, **IR** modérée-sévère, **hypothyroïdie**, ATCD de myopathie génétique, **alcool**, **> 70 ans**.","prio":"P2","sec":"s13"},{"id":"fc-223-15a413","poly":"cardio","fiche":"223","front":"Statine : calendrier des ALAT ?","back":"**Avant**, **8-12 semaines** après le début ou toute hausse de dose, puis **tous les ans** si < 3 N.","prio":"P2","sec":"s13"},{"id":"fc-223-c4d2e3","poly":"cardio","fiche":"223","front":"Statine avec ALAT > 3 N : conduite ?","back":"**Arrêter ou réduire** la statine ; recontrôle après **4 à 6 semaines**.","prio":"P1","sec":"s13"},{"id":"fc-223-2a68f0","poly":"cardio","fiche":"223","front":"Points clés : délai d'évaluation de l'efficacité hypolipémiante et des transaminases ?","back":"Bilan lipidique à **2-3 mois** ; transaminases à **3 mois**.","prio":"P3","sec":"s13"},{"id":"fc-223-ffe2c1","poly":"cardio","fiche":"223","front":"Dyslipidémie au long cours : suivi une fois la cible atteinte ?","back":"Tolérance : **myalgies**, **ALAT annuelles** si < 3 N ; diététique poursuivie.","prio":"P2","sec":"s14"},{"id":"fc-223-ca6b24","poly":"cardio","fiche":"223","front":"Après un SCA : suivi conjoint et objectifs ?","back":"**Médecin référent + cardiologue** ; tabac, activité, régime, **LDL-C dans l'objectif** sans toxicité, glycémie, PA.","prio":"P2","sec":"s14"},{"id":"fc-223-83fd8d","poly":"cardio","fiche":"223","front":"Après un SCA : localisations athéromateuses à rechercher ?","back":"Échodoppler des **TSA**, échographie de l'**aorte abdominale**, échodoppler des **MI**.","prio":"P2","sec":"s14"},{"id":"fc-223-f98e46","poly":"cardio","fiche":"223","front":"Après un SCA : réadaptation cardiovasculaire ?","back":"**Proposée à tous**.","prio":"P1","sec":"s14"},{"id":"fc-224-f236f7","poly":"cardio","fiche":"224","front":"HTA : quel est le seuil diagnostique de PA au cabinet (consultation) ?","back":"Moyenne des PAS **≥ 140 mmHg** et/ou des PAD **≥ 90 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-6b1876","poly":"cardio","fiche":"224","front":"HTA : quel est le seuil diagnostique en automesure (AMT) ?","back":"PA moyenne **≥ 135/85 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-d77e3d","poly":"cardio","fiche":"224","front":"HTA : quel est le seuil diagnostique en MAPA des 24 h ?","back":"PA moyenne des 24 h **≥ 130/80 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-f9736c","poly":"cardio","fiche":"224","front":"PA normale chez l'adulte (cabinet ou AMT) : quelles valeurs ?","back":"PAS **< 120** **et** PAD **< 70 mmHg**.","prio":"P2","sec":"s1"},{"id":"fc-224-b8154b","poly":"cardio","fiche":"224","front":"PA dite « élevée » : quelle définition simple ?","back":"PA **> 120/70 mmHg** sans critère diagnostique d'HTA.","prio":"P2","sec":"s1"},{"id":"fc-224-b420e6","poly":"cardio","fiche":"224","front":"PA élevée (ESC 2024) au cabinet : quelles valeurs ?","back":"PAS **120-139** et/ou PAD **70-89 mmHg** (AMT : 120-134 et/ou 70-84).","prio":"P3","sec":"s1"},{"id":"fc-224-a8059c","poly":"cardio","fiche":"224","front":"PA élevée (ESC 2024) : qu'impose-t-elle ?","back":"D'évaluer le **risque CV global** (SCORE2, SCORE2-OP, SCORE2-Diabetes ou haut risque d'emblée) ; antihypertenseur parfois si risque assez élevé.","prio":"P3","sec":"s1"},{"id":"fc-224-07b30c","poly":"cardio","fiche":"224","front":"MAPA nocturne : quel seuil définit l'HTA ?","back":"PAS **≥ 120** et/ou PAD **≥ 70 mmHg** (MAPA diurne : ≥ 135/85).","prio":"P3","sec":"s1"},{"id":"fc-224-02d79e","poly":"cardio","fiche":"224","front":"HTA : quelles sont les valeurs du grade 1 (consultation) ?","back":"PAS **140-159** et/ou PAD **90-99 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-fe0b28","poly":"cardio","fiche":"224","front":"HTA : quelles sont les valeurs du grade 2 (consultation) ?","back":"PAS **160-179** et/ou PAD **100-109 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-ded472","poly":"cardio","fiche":"224","front":"HTA : quelles sont les valeurs du grade 3 (consultation) ?","back":"PAS **≥ 180** et/ou PAD **≥ 110 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-6a9f3a","poly":"cardio","fiche":"224","front":"HTA de grade 3 : que faut-il rechercher systématiquement ?","back":"Une **urgence hypertensive** (atteinte **aiguë** d'un organe cible).","prio":"P1","sec":"s1"},{"id":"fc-224-c1b9ea","poly":"cardio","fiche":"224","front":"HTA dans le monde : combien de personnes et quel rang de mortalité ?","back":"Plus de **1,5 milliard** de personnes ; **1re cause de mortalité** (plus de **10 millions** de décès/an).","prio":"P3","sec":"s1"},{"id":"fc-224-9103b2","poly":"cardio","fiche":"224","front":"HTA en France (2023) : combien d'adultes hypertendus ?","back":"**17 millions** ; **1,6 million** de nouveaux patients traités chaque année.","prio":"P3","sec":"s1"},{"id":"fc-224-189c34","poly":"cardio","fiche":"224","front":"Étude ESTEBAN : quelle prévalence de l'HTA chez les 18-74 ans ?","back":"**30 %** des adultes.","prio":"P2","sec":"s1"},{"id":"fc-224-5e2a3a","poly":"cardio","fiche":"224","front":"Étude ESTEBAN : quelle part des hypertendus est diagnostiquée, traitée et contrôlée ?","back":"Seulement **25 %** (50 % non traités ; 50 % des traités hors objectif).","prio":"P2","sec":"s1"},{"id":"fc-224-0710df","poly":"cardio","fiche":"224","front":"Prévalence de l'HTA selon l'âge : chiffres après 70 et 80 ans ?","back":"**Plus de 60 %** après 70 ans ; **70 %** après 80 ans.","prio":"P2","sec":"s1"},{"id":"fc-224-275672","poly":"cardio","fiche":"224","front":"HTA : quelle répartition essentielle / secondaire ?","back":"**90 %** essentielle ; **10 %** secondaire.","prio":"P1","sec":"s1"},{"id":"fc-224-04ffc1","poly":"cardio","fiche":"224","front":"Dépistage de l'HTA (ESC 2024) : à quel rythme mesurer la PA ?","back":"Au moins **tous les 3 ans avant 40 ans** ; au moins **1 fois/an à partir de 40 ans**.","prio":"P1","sec":"s1"},{"id":"fc-224-9aa5c1","poly":"cardio","fiche":"224","front":"HTA en France : quel rang comme facteur de risque CV de mortalité ?","back":"**1er FDR CV** de mortalité ; 1re maladie chronique ; 2e facteur d'années de vie perdues en bonne santé.","prio":"P3","sec":"s1"},{"id":"fc-224-c211cd","poly":"cardio","fiche":"224","front":"Hypertendu vs normotendu : quel surrisque d'AVC ?","back":"**× 7** (mortalité CV globale doublée).","prio":"P2","sec":"s1"},{"id":"fc-224-48ea76","poly":"cardio","fiche":"224","front":"Hypertendu vs normotendu : surrisques d'IC, d'insuffisance coronarienne et d'AOMI ?","back":"IC **× 4** ; insuffisance coronarienne **× 3** ; AOMI **× 2**.","prio":"P2","sec":"s1"},{"id":"fc-224-ac6de4","poly":"cardio","fiche":"224","front":"HTA : quelles autres complications sont plus fréquentes que chez le normotendu (hors AVC, IC, coronaires, AOMI) ?","back":"**FA**, **IRC terminale**, **démence vasculaire**.","prio":"P3","sec":"s1"},{"id":"fc-224-5c63ef","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : la réversibilité du risque est-elle meilleure pour les AVC ou les coronaires ?","back":"Bien meilleure pour les **AVC** que pour les accidents coronariens.","prio":"P3","sec":"s1"},{"id":"fc-224-af9831","poly":"cardio","fiche":"224","front":"Méta-analyse 2015 : baisser la PAS de 10 et la PAD de 5-6 mmHg pendant 5 ans réduit le risque d'AVC de combien ?","back":"D'**un tiers** (coronaires : 1/6 ; IC : 46 %).","prio":"P3","sec":"s1"},{"id":"fc-224-65c90a","poly":"cardio","fiche":"224","front":"Régulation de la PA à court terme : quel système ?","back":"Le système **sympathique** (baroréflexe carotidien et aortique, centre vasopresseur, médullosurrénales).","prio":"P3","sec":"s2"},{"id":"fc-224-9c9223","poly":"cardio","fiche":"224","front":"Régulation de la PA à moyen terme : quels systèmes ?","back":"**SRAA** et **peptides natriurétiques** (ANP, BNP).","prio":"P3","sec":"s2"},{"id":"fc-224-0eb90a","poly":"cardio","fiche":"224","front":"Régulation de la PA à long terme : quels mécanismes ?","back":"**Natriurèse de pression** et système **arginine-vasopressine**.","prio":"P3","sec":"s2"},{"id":"fc-224-48ebcc","poly":"cardio","fiche":"224","front":"HTA essentielle : quels facteurs environnementaux alimentaires ?","back":"Alimentation **riche en sodium** et **pauvre en potassium** (fruits, légumes) ; + surpoids, alcool, sédentarité.","prio":"P2","sec":"s2"},{"id":"fc-224-4f44f6","poly":"cardio","fiche":"224","front":"HTA essentielle : quelle part est familiale et quel profil ?","back":"**15 %** ; début souvent **avant 30 ans**, même profil chez un ou les deux parents.","prio":"P3","sec":"s2"},{"id":"fc-224-ad7957","poly":"cardio","fiche":"224","front":"HTA familiale précoce : faut-il un test génétique ?","back":"**Non** : composante **polygénique** ; formes monogéniques très rares.","prio":"P2","sec":"s2"},{"id":"fc-224-0a1fb1","poly":"cardio","fiche":"224","front":"HTA essentielle : quelles 4 anomalies l'entretiennent ?","back":"Vaisseaux de résistance **hyperréactifs** ; artérioles **remodelées** ; aorte **rigide** ; **rétention hydrosodée**.","prio":"P3","sec":"s2"},{"id":"fc-224-c12e35","poly":"cardio","fiche":"224","front":"HTA secondaire : quel est l'intérêt d'en identifier la cause ?","back":"Un **traitement ciblé** peut nettement améliorer le contrôle, voire **guérir** l'HTA.","prio":"P3","sec":"s2"},{"id":"fc-224-4cf9ef","poly":"cardio","fiche":"224","front":"HTA : comment est-elle le plus souvent découverte ?","back":"Elle est le plus souvent **totalement latente** : découverte lors d'un examen systématique (d'où le dépistage régulier).","prio":"P2","sec":"s3"},{"id":"fc-224-0f6b79","poly":"cardio","fiche":"224","front":"HTA : quelles céphalées typiques peut-elle donner ?","back":"Céphalées **occipitales matinales**, un peu battantes, résistant aux antalgiques, cédant au lever ou dans la matinée.","prio":"P3","sec":"s3"},{"id":"fc-224-064fc0","poly":"cardio","fiche":"224","front":"Symptômes non spécifiques de l'HTA (céphalées, phosphènes, épistaxis) : justifient-ils un traitement immédiat ?","back":"**Non** : ils n'affirment pas l'HTA et ne justifient pas à eux seuls un antihypertenseur immédiat.","prio":"P2","sec":"s3"},{"id":"fc-224-408876","poly":"cardio","fiche":"224","front":"PA ≥ 140/90 mmHg au cabinet : que conclut-on ?","back":"**Suspicion** d'HTA, à **confirmer hors cabinet** avant de traiter (sauf urgence hypertensive).","prio":"P1","sec":"s3"},{"id":"fc-224-3776db","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : quel appareil, et quand garder le stéthoscope ?","back":"Appareil **électronique validé** au bras ; stéthoscope plus en 1re intention, **sauf en fibrillation atriale**.","prio":"P2","sec":"s3"},{"id":"fc-224-dbd0b4","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : combien de temps de repos préalable ?","back":"Assis au calme **plus de 5 min** ; plus de **30 min** après effort, café ou cigarette ; vessie vide.","prio":"P1","sec":"s3"},{"id":"fc-224-dece75","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : combien de mesures et laquelle retenir ?","back":"**Au moins 3** mesures à 1-2 min ; **moyenne des 2 dernières**.","prio":"P1","sec":"s3"},{"id":"fc-224-954fda","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : quand faire des mesures supplémentaires ?","back":"Si les **2 premières PAS** diffèrent de plus de **10 mmHg**.","prio":"P3","sec":"s3"},{"id":"fc-224-9db537","poly":"cardio","fiche":"224","front":"1re consultation pour HTA : pourquoi mesurer la PA aux deux bras ?","back":"Une asymétrie fait suspecter une **sténose de l'artère subclavière** ; le bras le plus haut = bras de référence.","prio":"P2","sec":"s3"},{"id":"fc-224-6ee31f","poly":"cardio","fiche":"224","front":"Hypotension orthostatique : quelle définition ?","back":"Baisse de PAS **≥ 20 mmHg** et/ou de PAD **≥ 10 mmHg** debout à **1 et 3 min**.","prio":"P1","sec":"s3"},{"id":"fc-224-97e8ae","poly":"cardio","fiche":"224","front":"Mesure de la PA : combien de temps prendre la FC de repos au pouls ?","back":"Au moins **30 s**, à la recherche d'une arythmie.","prio":"P3","sec":"s3"},{"id":"fc-224-fb9952","poly":"cardio","fiche":"224","front":"Artères calcifiées incompressibles : de combien le brassard surestime-t-il la PA ?","back":"D'environ **20 mmHg** (parfois 40 à 50).","prio":"P3","sec":"s3"},{"id":"fc-224-ac2460","poly":"cardio","fiche":"224","front":"Manœuvre d'Osler : que montre-t-elle ?","back":"Pouls radial encore perçu brassard gonflé au-dessus de la PAS = **artère calcifiée incompressible**.","prio":"P3","sec":"s3"},{"id":"fc-224-e2d705","poly":"cardio","fiche":"224","front":"Pression pulsée : quel seuil marque une rigidité artérielle ?","back":"PAS − PAD **> 65 mmHg**.","prio":"P3","sec":"s3"},{"id":"fc-224-8b989c","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : quel brassard et à quelle hauteur ?","back":"**Brassard adapté** au bras (3 tailles : obèse, standard, enfant), **à hauteur du cœur**.","prio":"P2","sec":"s3"},{"id":"fc-224-259259","poly":"cardio","fiche":"224","front":"HTA : quel examen hors cabinet est recommandé en France pour la confirmer ?","back":"L'**automesure (AMT)** ; MAPA à défaut.","prio":"P1","sec":"s4"},{"id":"fc-224-35a46e","poly":"cardio","fiche":"224","front":"HTA suspectée : que faut-il faire avant tout antihypertenseur (hors urgence) ?","back":"**Confirmer l'HTA hors cabinet** (AMT de préférence, sinon MAPA).","prio":"P1","sec":"s4"},{"id":"fc-224-484869","poly":"cardio","fiche":"224","front":"Automesure : quel appareil utiliser ?","back":"Appareil **validé, semi-automatique**, à **brassard huméral** (le poignet expose à plus d'erreurs).","prio":"P2","sec":"s4"},{"id":"fc-224-2cdb58","poly":"cardio","fiche":"224","front":"Automesure : en quoi consiste la « règle des 3 » ?","back":"**3 jours** de suite ; **3 mesures** le matin et **3** le soir ; soit **18 mesures**.","prio":"P1","sec":"s4"},{"id":"fc-224-58af79","poly":"cardio","fiche":"224","front":"Automesure : à quels moments mesurer ?","back":"**Matin** 20 min après le lever, avant petit-déjeuner et médicaments ; **soir** dans l'heure avant le coucher.","prio":"P2","sec":"s4"},{"id":"fc-224-e69848","poly":"cardio","fiche":"224","front":"MAPA : quand la préférer à l'automesure pour confirmer l'HTA ?","back":"Quand l'AMT est **impossible ou peu fiable** (manipulation, report des valeurs, anxiété).","prio":"P2","sec":"s4"},{"id":"fc-224-a5fb4a","poly":"cardio","fiche":"224","front":"MAPA : quelle fréquence de mesure le jour et la nuit ?","back":"Toutes les **15-30 min le jour**, **30-60 min la nuit**, sur 24 h avec journal.","prio":"P3","sec":"s4"},{"id":"fc-224-f5c7d6","poly":"cardio","fiche":"224","front":"MAPA : quelle PA prédit le mieux le risque CV ?","back":"La **PA nocturne** (plus que la diurne).","prio":"P2","sec":"s4"},{"id":"fc-224-24b6bc","poly":"cardio","fiche":"224","front":"MAPA : quelles autres indications que la confirmation de l'HTA ?","back":"Confirmer une **HTA résistante** ; hypotensions symptomatiques ; forte variabilité ; explorer la **PA nocturne**.","prio":"P2","sec":"s4"},{"id":"fc-224-c29e5b","poly":"cardio","fiche":"224","front":"HTA de grade 2 à la 1re consultation : dans quel délai faire la mesure hors cabinet ?","back":"**Dans le mois**.","prio":"P1","sec":"s4"},{"id":"fc-224-44065a","poly":"cardio","fiche":"224","front":"HTA de grade 3 sans urgence : dans quel délai faire la mesure hors cabinet ?","back":"**Dans la semaine**.","prio":"P1","sec":"s4"},{"id":"fc-224-9ff965","poly":"cardio","fiche":"224","front":"HTA « blouse blanche » : quelle définition ?","back":"PA de cabinet **> 140/90 mmHg** mais mesures ambulatoires **ne confirmant pas** l'HTA.","prio":"P1","sec":"s4"},{"id":"fc-224-1322af","poly":"cardio","fiche":"224","front":"HTA blouse blanche : quelle conduite ?","back":"**Pas de médicament** ; MHD ; surveillance régulière hors cabinet (risque d'HTA confirmée plus tard).","prio":"P1","sec":"s4"},{"id":"fc-224-ad0e63","poly":"cardio","fiche":"224","front":"HTA masquée : quelle définition ?","back":"PA de cabinet **< 140/90 mmHg** mais **HTA en ambulatoire** (ex. AMT > 135/85).","prio":"P1","sec":"s4"},{"id":"fc-224-fc58f0","poly":"cardio","fiche":"224","front":"HTA masquée : quel risque et quelle prise en charge ?","back":"**Même risque** CV que l'HTA habituelle → **même prise en charge**, guidée par les mesures hors cabinet.","prio":"P1","sec":"s4"},{"id":"fc-224-2faef2","poly":"cardio","fiche":"224","front":"HTA blouse blanche et HTA masquée : quelles fréquences chez l'adulte ?","back":"Blouse blanche **15-20 %** ; masquée **10-15 %**.","prio":"P3","sec":"s4"},{"id":"fc-224-029753","poly":"cardio","fiche":"224","front":"HTA confirmée : quels sont les 5 objectifs de l'évaluation initiale ?","back":"**Niveau de PA** ; **risque CV global** ; **organes cibles** ; **facteurs aggravants** ; arguments pour une **HTA secondaire**.","prio":"P1","sec":"s5"},{"id":"fc-224-a8610a","poly":"cardio","fiche":"224","front":"HTA : quel signe d'examen clinique rechercher sur le poids et la silhouette ?","back":"Une **obésité viscérale** : poids, IMC, **tour de taille** debout.","prio":"P3","sec":"s5"},{"id":"fc-224-9a35b0","poly":"cardio","fiche":"224","front":"HTA : quels antécédents obstétricaux rechercher à l'interrogatoire ?","back":"HTA ou diabète **gravidique**, **prééclampsie**, prématurité, fausses couches répétées, mort fœtale in utero.","prio":"P3","sec":"s5"},{"id":"fc-224-d6e0ea","poly":"cardio","fiche":"224","front":"HTA : quel facteur aggravant évoquent des ronflements et des pauses respiratoires nocturnes ?","back":"Un **SAOS**.","prio":"P2","sec":"s5"},{"id":"fc-224-042dea","poly":"cardio","fiche":"224","front":"HTA : quel est le bilan biologique systématique ?","back":"Glycémie à jeun + **HbA1c** ; bilan lipidique ; natrémie, **kaliémie** ; Hb ; **créatininémie** + DFG ; rapport **protéinurie/créatininurie**.","prio":"P1","sec":"s5"},{"id":"fc-224-69cca4","poly":"cardio","fiche":"224","front":"HTA : quel examen non biologique est systématique dans le bilan initial ?","back":"**ECG de repos** (HVG, séquelle d'infarctus, repolarisation, FA).","prio":"P1","sec":"s5"},{"id":"fc-224-01e146","poly":"cardio","fiche":"224","front":"HTA : que cherche le dosage systématique de la kaliémie ?","back":"Une **hypokaliémie**, argument pour une **HTA secondaire**.","prio":"P2","sec":"s5"},{"id":"fc-224-6d99eb","poly":"cardio","fiche":"224","front":"HTA : quand faire une échocardiographie ?","back":"Si **ECG anormal** ou **symptômes cardiaques** ; **pas** chez l'asymptomatique à ECG normal.","prio":"P1","sec":"s5"},{"id":"fc-224-020816","poly":"cardio","fiche":"224","front":"HTA : quand faire un IPS ou un échodoppler (TSA, membres inférieurs) ?","back":"Si **souffle** ou **symptômes d'AOMI** ; pas chez l'asymptomatique.","prio":"P2","sec":"s5"},{"id":"fc-224-fe672d","poly":"cardio","fiche":"224","front":"HTA : quand le fond d'œil est-il recommandé ?","back":"**Recommandé dans le grade 3** ; grade 2-3 avec suspicion d'**HTA maligne**.","prio":"P2","sec":"s5"},{"id":"fc-224-c2dac0","poly":"cardio","fiche":"224","front":"HTA chez une femme : quel dosage faire si une grossesse est possible ?","back":"**β-hCG** (certains antihypertenseurs sont contre-indiqués).","prio":"P1","sec":"s5"},{"id":"fc-224-89117c","poly":"cardio","fiche":"224","front":"HVG à l'ECG : quels indices, et quelle est la sensibilité de l'ECG ?","back":"Indices de **Sokolow, Cornell, Lewis** ; ECG **peu sensible** (signes = HVG marquée).","prio":"P2","sec":"s5"},{"id":"fc-224-3b112c","poly":"cardio","fiche":"224","front":"Échocardiographie : quels seuils de masse VG définissent l'HVG ?","back":"**> 115 g/m²** chez l'homme ; **> 95 g/m²** chez la femme.","prio":"P3","sec":"s5"},{"id":"fc-224-04bf21","poly":"cardio","fiche":"224","front":"Atteinte rénale de l'HTA : quel seuil de DFG définit l'insuffisance rénale ?","back":"DFG **< 60 ml/min/1,73 m²**.","prio":"P2","sec":"s5"},{"id":"fc-224-2aa53d","poly":"cardio","fiche":"224","front":"Rapport protéinurie/créatininurie : quels seuils (pathologique, protéinurie) ?","back":"Pathologique dès **> 30 mg/g** ; protéinurie si **> 300 mg/g**.","prio":"P3","sec":"s5"},{"id":"fc-224-b7b792","poly":"cardio","fiche":"224","front":"HTA : chez qui la microalbuminurie est-elle systématique ?","back":"**Seulement chez le diabétique**.","prio":"P2","sec":"s5"},{"id":"fc-224-49eef5","poly":"cardio","fiche":"224","front":"Fond d'œil dans l'HTA : que définissent les stades 3 et 4 ?","back":"Stade 3 : **hémorragies, exsudats** ; stade 4 : **œdème papillaire** (PA non contrôlée + stade 4 = HTA maligne).","prio":"P1","sec":"s5"},{"id":"fc-224-e9b977","poly":"cardio","fiche":"224","front":"HTA et FA : quelle place de l'HTA ?","back":"**1re cause** de FA : **70 %** des patients en FA sont hypertendus.","prio":"P2","sec":"s5"},{"id":"fc-224-f744e4","poly":"cardio","fiche":"224","front":"HTA : par combien multiplie-t-elle le risque de mort subite ?","back":"**× 3**.","prio":"P3","sec":"s5"},{"id":"fc-224-acbe96","poly":"cardio","fiche":"224","front":"AVC de l'hypertendu : quelle part ischémique / hémorragique ?","back":"**80 %** ischémiques (dont AIT) ; **20 %** hémorragies cérébrales.","prio":"P2","sec":"s5"},{"id":"fc-224-b318ec","poly":"cardio","fiche":"224","front":"HTA : quelle atteinte rénale chronique typique ?","back":"La **néphroangiosclérose** (microalbuminurie précoce puis insuffisance rénale qui aggrave l'HTA).","prio":"P2","sec":"s5"},{"id":"fc-224-6b30c3","poly":"cardio","fiche":"224","front":"HTA : quelles causes d'IRA iatrogène ?","back":"**Diurétique** (déshydratation extracellulaire) ; **bloqueur du SRA** sur sténose bilatérale des artères rénales ou sur rein unique.","prio":"P1","sec":"s5"},{"id":"fc-224-1257fd","poly":"cardio","fiche":"224","front":"HTA : par combien la mortalité CV est-elle multipliée selon le sexe ?","back":"**× 5** chez l'homme ; **× 3** chez la femme.","prio":"P3","sec":"s5"},{"id":"fc-224-d6d6e0","poly":"cardio","fiche":"224","front":"HVG de l'HTA : quel mécanisme peut donner un angor sans athérome ?","back":"La baisse de la **réserve coronarienne** due à l'HVG.","prio":"P3","sec":"s5"},{"id":"fc-224-b95cb7","poly":"cardio","fiche":"224","front":"Hypertendu à risque CV élevé d'emblée : quelles situations ?","back":"Antécédent coronarien, **AVC/AIT**, **AOMI**, IC, IR modérée/sévère, atteinte d'organe cible **cardiaque ou vasculaire**, **hypercholestérolémie familiale**.","prio":"P2","sec":"s5"},{"id":"fc-224-940249","poly":"cardio","fiche":"224","front":"Hypertendu diabétique de 40 à 69 ans : quel score de risque CV ?","back":"**SCORE2-Diabetes**.","prio":"P2","sec":"s5"},{"id":"fc-224-5760d4","poly":"cardio","fiche":"224","front":"Hypertendu sans haut risque d'emblée ni diabète : quels scores de risque CV ?","back":"**SCORE2** ou **SCORE2-OP** (risque à 10 ans).","prio":"P2","sec":"s5"},{"id":"fc-224-6413e8","poly":"cardio","fiche":"224","front":"HTA : quand demander un avis spécialisé d'emblée ?","back":"Grade **3** ; HTA **avant 40 ans** (si obèse : dépister d'abord un SAOS) ; HTA **résistante** ; contexte d'HTA secondaire.","prio":"P1","sec":"s5"},{"id":"fc-224-412263","poly":"cardio","fiche":"224","front":"HTA : quel mécanisme d'insuffisance cardiaque à FEVG préservée ?","back":"**Trouble du remplissage** lié à l'**HVG** et à la fibrose, sur cœur hypertrophié **non dilaté**.","prio":"P3","sec":"s5"},{"id":"fc-224-de1029","poly":"cardio","fiche":"224","front":"HTA : quelles causes d'insuffisance cardiaque à FEVG altérée ?","back":"**Ischémique**, ou **postcharge élevée** (HTA sévère) sur cœur dilaté et hypertrophié (**HVG excentrique**).","prio":"P3","sec":"s5"},{"id":"fc-224-6e8227","poly":"cardio","fiche":"224","front":"HTA secondaire : dans quelles situations la dépister ?","back":"PA **> 180/110**, surtout brutale ; HTA **résistante** ; âge **≤ 40 ans** ; **hypokaliémie** ; tout point d'appel.","prio":"P1","sec":"s6"},{"id":"fc-224-cb4911","poly":"cardio","fiche":"224","front":"HTA + souffle précordial + pouls fémoraux faibles : quelle cause évoquer ?","back":"Une **coarctation aortique**.","prio":"P1","sec":"s6"},{"id":"fc-224-1e4062","poly":"cardio","fiche":"224","front":"HTA + crises de céphalées, sueurs, palpitations : quelle cause évoquer ?","back":"Un **phéochromocytome** (**triade de Ménard**).","prio":"P1","sec":"s6"},{"id":"fc-224-938657","poly":"cardio","fiche":"224","front":"HTA + crampes, asthénie, tétanie, constipation : quelle cause évoquer ?","back":"**Hypokaliémie** → **hyperaldostéronisme**.","prio":"P1","sec":"s6"},{"id":"fc-224-bbc68e","poly":"cardio","fiche":"224","front":"HTA + souffle aortique abdominal : quelle cause évoquer ?","back":"Une **HTA rénovasculaire**.","prio":"P2","sec":"s6"},{"id":"fc-224-0ea316","poly":"cardio","fiche":"224","front":"HTA + gros reins palpables : quelle cause évoquer ?","back":"Une **polykystose rénale**.","prio":"P2","sec":"s6"},{"id":"fc-224-7cc7e8","poly":"cardio","fiche":"224","front":"HTA + vergetures pourpres, amyotrophie proximale, bosse de bison : quelle cause ?","back":"Un **hypercortisolisme** (Cushing).","prio":"P2","sec":"s6"},{"id":"fc-224-01f8ba","poly":"cardio","fiche":"224","front":"HTA médicamenteuse : citer des médicaments en cause.","back":"**Contraceptifs oraux**, vasoconstricteurs nasaux, **corticoïdes**, **AINS**, EPO, ciclosporine, tacrolimus, anti-VEGF, ITK, ergot de seigle.","prio":"P1","sec":"s6"},{"id":"fc-224-f5dcb6","poly":"cardio","fiche":"224","front":"HTA toxique : citer les toxiques en cause.","back":"**Réglisse** (boissons anisées, bonbons, tisanes), cannabis, **cocaïne**, amphétamines, **alcool**.","prio":"P2","sec":"s6"},{"id":"fc-224-372dd4","poly":"cardio","fiche":"224","front":"HTA rénale : quelles sont les causes rénales les plus fréquentes ?","back":"**Glomérulopathies chroniques** et **polykystose**.","prio":"P2","sec":"s6"},{"id":"fc-224-742d59","poly":"cardio","fiche":"224","front":"Sténose athéromateuse de l'artère rénale : quel siège typique ?","back":"**Ostium et tiers proximal** ; cause rénovasculaire la plus fréquente.","prio":"P2","sec":"s6"},{"id":"fc-224-8da210","poly":"cardio","fiche":"224","front":"Dysplasie fibromusculaire des artères rénales : quel terrain et quel siège ?","back":"**Femme jeune** ; **deux tiers distaux** de l'artère.","prio":"P2","sec":"s6"},{"id":"fc-224-02f828","poly":"cardio","fiche":"224","front":"Phéochromocytome : dans quelle proportion donne-t-il une HTA ?","back":"**70 %** des cas (tumeur rare, souvent bénigne, de la médullosurrénale).","prio":"P3","sec":"s6"},{"id":"fc-224-dfd242","poly":"cardio","fiche":"224","front":"Phéochromocytome : quelles formes familiales ?","back":"**NEM2**, **von Hippel-Lindau**, **neurofibromatose 1**, paragangliomes familiaux.","prio":"P3","sec":"s6"},{"id":"fc-224-54b64e","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : quelles causes et leurs fréquences ?","back":"**Hyperplasie bilatérale (70 %)** ; **adénome surrénalien (30 %)** ; rarement corticosurrénalome malin.","prio":"P2","sec":"s6"},{"id":"fc-224-77b3fc","poly":"cardio","fiche":"224","front":"Coarctation aortique : quel mécanisme et quel siège ?","back":"Fermeture anormale du canal artériel → sténose de l'**isthme aortique** ; enfant et adulte jeune.","prio":"P2","sec":"s6"},{"id":"fc-224-bd7dc3","poly":"cardio","fiche":"224","front":"HTA et SAOS : chez qui évoquer un SAOS ?","back":"**Obèse**, surtout si HTA **résistante** ; profil **« non dipper »** en MAPA.","prio":"P2","sec":"s6"},{"id":"fc-224-d4c76a","poly":"cardio","fiche":"224","front":"Profil « non dipper » en MAPA : de quoi s'agit-il ?","back":"**Absence de baisse nocturne** de la PA.","prio":"P2","sec":"s6"},{"id":"fc-224-df99f2","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles substances interfèrent avec leur action ou métabolisme ?","back":"**AINS**, antirétroviraux, inhibiteurs du CYP17A1 (**jus de pamplemousse**, macrolides, antifongiques azolés).","prio":"P2","sec":"s6"},{"id":"fc-224-e1696f","poly":"cardio","fiche":"224","front":"Sténose de l'artère rénale : quel profil rénine-aldostérone ?","back":"Hyperaldostéronisme **secondaire** : rénine **et** aldostérone **élevées**.","prio":"P2","sec":"s6"},{"id":"fc-224-90de66","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : quel profil biologique ?","back":"Aldostérone **haute**, **rénine basse**, rapport aldostérone/rénine très élevé.","prio":"P2","sec":"s6"},{"id":"fc-224-82daa4","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : une kaliémie normale l'exclut-elle ?","back":"**Non** : hypokaliémie (< 3,7 mmol/L) **inconstante**.","prio":"P2","sec":"s6"},{"id":"fc-224-513ec8","poly":"cardio","fiche":"224","front":"Sténose de l'artère rénale : quels signes l'évoquent ?","back":"Souffle abdominal latéralisé ; **OAP récidivant** sans cause cardiaque ; IR parfois révélée par un IEC/ARA2 ; petit rein homolatéral.","prio":"P3","sec":"s6"},{"id":"fc-224-d43392","poly":"cardio","fiche":"224","front":"Phéochromocytome : quel dosage pour le diagnostic ?","back":"**Dérivés méthoxylés** (métanéphrines, normétanéphrines) urinaires et/ou plasmatiques.","prio":"P2","sec":"s6"},{"id":"fc-224-1ae797","poly":"cardio","fiche":"224","front":"Phéochromocytome : quels examens de localisation ?","back":"**Scanner** + **scintigraphie à la MIBG** (tumeur parfois extrasurrénalienne).","prio":"P3","sec":"s6"},{"id":"fc-224-cb79a7","poly":"cardio","fiche":"224","front":"Coarctation aortique : quels signes cliniques ?","back":"Souffle mésosystolique parasternal gauche et dorsal ; **pouls fémoraux absents** ; HTA aux bras, PA basse aux jambes.","prio":"P3","sec":"s6"},{"id":"fc-224-7f856e","poly":"cardio","fiche":"224","front":"Rénine et aldostérone : dans quelles conditions de prélèvement ?","back":"**Matin, 2 h après le lever**, **normokaliémie**, apports sodés larges, après arrêt des médicaments interférents.","prio":"P3","sec":"s6"},{"id":"fc-224-dbf604","poly":"cardio","fiche":"224","front":"Dosage rénine-aldostérone : quels délais d'arrêt des médicaments ?","back":"**ARM : 6 semaines** ; **IEC, ARA2, diurétiques, bêtabloquants : 2 semaines**.","prio":"P3","sec":"s6"},{"id":"fc-224-6127e0","poly":"cardio","fiche":"224","front":"SAOS suspecté chez un hypertendu : quel examen ?","back":"**Polygraphie ventilatoire** (ou polysomnographie) nocturne.","prio":"P3","sec":"s6"},{"id":"fc-224-8a88ab","poly":"cardio","fiche":"224","front":"HTA endocrinienne : quelles endocrinopathies citer en dehors du phéochromocytome et du Conn ?","back":"**Cushing**, **acromégalie**, **hyperthyroïdie**.","prio":"P3","sec":"s6"},{"id":"fc-224-d71b32","poly":"cardio","fiche":"224","front":"Crise hypertensive : quelle définition et quelle gravité ?","back":"HTA de **grade 3 sans souffrance viscérale** ; **pas une urgence**.","prio":"P1","sec":"s7"},{"id":"fc-224-01cab9","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quelle définition ?","back":"HTA (souvent **> 180/110**) + **atteinte aiguë d'un organe cible** ; pronostic vital engagé.","prio":"P1","sec":"s7"},{"id":"fc-224-bda761","poly":"cardio","fiche":"224","front":"HTA maligne : quelle définition ?","back":"PA élevée (pas de seuil) + **œdème papillaire** au fond d'œil (**stade 4**).","prio":"P1","sec":"s7"},{"id":"fc-224-b1885f","poly":"cardio","fiche":"224","front":"HTA maligne : quelles atteintes aiguës peuvent s'associer ?","back":"**IRA**, IVG/ischémie, **PRES**/encéphalopathie, **microangiopathie thrombotique** (hémolyse mécanique, thrombopénie).","prio":"P2","sec":"s7"},{"id":"fc-224-308293","poly":"cardio","fiche":"224","front":"HTA maligne non traitée : quelle évolution ?","back":"**Insuffisance rénale sévère, irréversible et mortelle en quelques mois**.","prio":"P2","sec":"s7"},{"id":"fc-224-b9f281","poly":"cardio","fiche":"224","front":"Urgences hypertensives : citer les principales.","back":"HTA + **SCA** ; **OAP** ; **dissection aortique** ; encéphalopathie ; **PRES** ; AVC/hémorragie méningée ; phéochromocytome ; toxiques ; **prééclampsie sévère** ; HTA maligne.","prio":"P1","sec":"s7"},{"id":"fc-224-1ec227","poly":"cardio","fiche":"224","front":"PRES : quels signes l'évoquent dans une urgence hypertensive ?","back":"**Cécité centrale** et **lésions occipitales**.","prio":"P3","sec":"s7"},{"id":"fc-224-4d16b3","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quel bilan cherche une microangiopathie thrombotique ?","back":"NFS, **schizocytes**, bilirubine libre, **haptoglobine**, **LDH**.","prio":"P2","sec":"s7"},{"id":"fc-224-6491d4","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quand faire un scanner cérébral ?","back":"Si suspicion d'**hémorragie** ou d'**AVC**.","prio":"P2","sec":"s7"},{"id":"fc-224-e572eb","poly":"cardio","fiche":"224","front":"Consultation d'annonce de l'HTA : quel en est l'aboutissement ?","back":"Un **plan de soins** et une **décision médicale partagée** (objectifs, dont la cible de PA).","prio":"P2","sec":"s8"},{"id":"fc-224-7798c3","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : de combien réduit-il le risque d'AVC ?","back":"De **20-30 %** (SCA et IC : 10-20 %).","prio":"P2","sec":"s8"},{"id":"fc-224-5e6fb3","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : existe-t-il une limite d'âge ?","back":"**Aucune limite d'âge**.","prio":"P1","sec":"s8"},{"id":"fc-224-e4b5a2","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : quels sont les 4 piliers ?","back":"**MHD** ; traitement des **FDR** associés ; **médicaments** ; **éducation thérapeutique**.","prio":"P2","sec":"s8"},{"id":"fc-224-73a493","poly":"cardio","fiche":"224","front":"Stratégie antihypertensive : de quoi dépend-elle ?","back":"Du **niveau de PA**, du **risque CV** et de l'**atteinte des organes cibles**.","prio":"P1","sec":"s8"},{"id":"fc-224-712a4b","poly":"cardio","fiche":"224","front":"PAS de consultation 130-139 mmHg sans risque CV élevé : quelle conduite ?","back":"**MHD** sans médicament ; surveillance de la PA ; réévaluation annuelle du risque.","prio":"P2","sec":"s8"},{"id":"fc-224-c79a1e","poly":"cardio","fiche":"224","front":"PAS 130-139 mmHg avec risque CV élevé : quand ajouter un médicament ?","back":"Après **3 mois** de MHD si cible non atteinte : **monothérapie** si PA ≥ 130/80.","prio":"P2","sec":"s8"},{"id":"fc-224-a2c1a5","poly":"cardio","fiche":"224","front":"HTA confirmée : quand débuter un médicament ?","back":"**D'emblée, chez tous**, en même temps que les MHD.","prio":"P1","sec":"s8"},{"id":"fc-224-0a3cbe","poly":"cardio","fiche":"224","front":"HTA : en combien de temps viser la cible tensionnelle ?","back":"Idéalement en **3 mois**, avec suivi fréquent (mensuel si besoin).","prio":"P1","sec":"s8"},{"id":"fc-224-661d5f","poly":"cardio","fiche":"224","front":"HTA : quelle est la cible tensionnelle générale (ESC 2024) ?","back":"PAS **120-129** et PAD **70-79 mmHg**, si possible **120/70**.","prio":"P1","sec":"s8"},{"id":"fc-224-394536","poly":"cardio","fiche":"224","front":"Cible tensionnelle inatteignable ou mal tolérée : quel objectif ?","back":"PA **la plus basse possible** et **< 140/90 mmHg**.","prio":"P2","sec":"s8"},{"id":"fc-224-e328b9","poly":"cardio","fiche":"224","front":"Cible tensionnelle : quand l'adapter d'emblée ?","back":"**Hypotension orthostatique**, **fragilité**, âge **> 85 ans**, espérance de vie limitée.","prio":"P2","sec":"s8"},{"id":"fc-224-0ebc74","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quel apport de sel viser ?","back":"**5-6 g/j** (natriurèse ≈ **100 mmol/j**), **sans régime sans sel strict**.","prio":"P1","sec":"s8"},{"id":"fc-224-ee101e","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quelle limite pour l'alcool ?","back":"**< 10 unités/semaine**.","prio":"P1","sec":"s8"},{"id":"fc-224-28278c","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quels objectifs de poids et de tour de taille ?","back":"IMC **20-25 kg/m²** ; tour de taille **< 94 cm (H)**, **< 80 cm (F)**.","prio":"P2","sec":"s8"},{"id":"fc-224-cb0a78","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quand ne pas majorer les apports en potassium ?","back":"En cas de **maladie rénale chronique avancée**.","prio":"P2","sec":"s8"},{"id":"fc-224-a4fe34","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : faut-il limiter le café ?","back":"**Non** ; boissons associant taurine et caféine déconseillées.","prio":"P2","sec":"s8"},{"id":"fc-224-c34ef1","poly":"cardio","fiche":"224","front":"Régime sans sel strict dans l'HTA : pourquoi l'éviter ?","back":"Inutile et dangereux : **déshydratation, hypovolémie**, atteinte rénale, surtout sous IEC/ARA2.","prio":"P2","sec":"s8"},{"id":"fc-224-a83ac3","poly":"cardio","fiche":"224","front":"MHD bien suivies : de combien baissent-elles la PAS ?","back":"De **5 à 10 mmHg**.","prio":"P2","sec":"s8"},{"id":"fc-224-96af02","poly":"cardio","fiche":"224","front":"Équivalence sel : 1 g de NaCl correspond à combien de sodium ?","back":"**17 mmol** de sodium.","prio":"P3","sec":"s8"},{"id":"fc-224-ad6d62","poly":"cardio","fiche":"224","front":"PAS de consultation 120-129 mmHg : quel traitement ?","back":"**MHD** seules, **sans médicament**.","prio":"P2","sec":"s8"},{"id":"fc-224-636781","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quelle activité physique conseiller ?","back":"**Aérobie** (endurance) + **résistance** dynamique et/ou isométrique, régulière et adaptée ; lutter contre la **sédentarité**.","prio":"P3","sec":"s8"},{"id":"fc-224-3a7f9a","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles sont les 5 classes qui réduisent la morbi-mortalité CV ?","back":"**Inhibiteurs calciques**, **IEC**, **ARA2**, **bêtabloquants**, **thiazidiques** (ou apparentés).","prio":"P1","sec":"s9"},{"id":"fc-224-2a66a5","poly":"cardio","fiche":"224","front":"HTA confirmée non compliquée : par quel schéma débuter ?","back":"**Bithérapie** à **faible dose**, **association fixe** (1 comprimé), **1 prise/j**.","prio":"P1","sec":"s9"},{"id":"fc-224-801f3e","poly":"cardio","fiche":"224","front":"HTA : quelles bithérapies initiales privilégier ?","back":"**IEC ou ARA2 + IC dihydropyridine**, ou **IEC ou ARA2 + thiazidique**.","prio":"P1","sec":"s9"},{"id":"fc-224-367899","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelle association est interdite ?","back":"**IEC + ARA2**.","prio":"P1","sec":"s9"},{"id":"fc-224-a89fba","poly":"cardio","fiche":"224","front":"HTA : quand utiliser un bêtabloquant à l'initiation ?","back":"**Seulement s'il a une autre indication** (moins efficace sur les AVC ; pas de monothérapie par bêtabloquant).","prio":"P1","sec":"s9"},{"id":"fc-224-8a5126","poly":"cardio","fiche":"224","front":"HTA : quels critères justifient une monothérapie initiale ?","back":"PA élevée avec indication de médicament ; **fragilité** modérée/sévère ; **hypotension orthostatique** ; âge **≥ 85 ans**.","prio":"P2","sec":"s9"},{"id":"fc-224-9b0726","poly":"cardio","fiche":"224","front":"Hypertendu post-infarctus ou angineux : quelles classes préférer ?","back":"Post-infarctus : **IEC, ARA2 ou bêtabloquant** ; angor : **IC ou bêtabloquant**.","prio":"P3","sec":"s9"},{"id":"fc-224-8d3bc5","poly":"cardio","fiche":"224","front":"HTA + diabète avec microalbuminurie ou insuffisance rénale : quelle classe préférer ?","back":"**IEC ou ARA2** (iSGLT2 probablement aussi).","prio":"P2","sec":"s9"},{"id":"fc-224-c1c885","poly":"cardio","fiche":"224","front":"IEC : quelles contre-indications absolues ?","back":"**Grossesse** ; **angio-œdème** sous IEC.","prio":"P1","sec":"s9"},{"id":"fc-224-556a39","poly":"cardio","fiche":"224","front":"ARA2 : quelle contre-indication absolue ?","back":"La **grossesse**.","prio":"P1","sec":"s9"},{"id":"fc-224-0096a2","poly":"cardio","fiche":"224","front":"IEC et ARA2 : quelles contre-indications relatives ?","back":"**Hyperkaliémie** ; femme en âge de procréer sans contraception efficace ; **sténose bilatérale** des artères rénales ; IR sévère.","prio":"P2","sec":"s9"},{"id":"fc-224-88d728","poly":"cardio","fiche":"224","front":"Diurétiques thiazidiques : quelles contre-indications ?","back":"**Aucune absolue** ; relatives : **hypercalcémie**, **hypokaliémie**, **goutte**, grossesse.","prio":"P1","sec":"s9"},{"id":"fc-224-7f00ee","poly":"cardio","fiche":"224","front":"Bêtabloquants : quelles contre-indications absolues ?","back":"**Asthme** ; **BAV 2 et 3**.","prio":"P1","sec":"s9"},{"id":"fc-224-74ce9b","poly":"cardio","fiche":"224","front":"Bêtabloquants : quelles contre-indications relatives ?","back":"**Bradycardie** ; **syndrome de Raynaud**.","prio":"P2","sec":"s9"},{"id":"fc-224-221ca3","poly":"cardio","fiche":"224","front":"IC dihydropyridines : quelles contre-indications ?","back":"**Aucune absolue** ; relative : **insuffisance cardiaque non contrôlée**.","prio":"P1","sec":"s9"},{"id":"fc-224-7e9dda","poly":"cardio","fiche":"224","front":"IC non dihydropyridines (bradycardisants) : quelles contre-indications absolues ?","back":"**BAV 2 et 3** ; **IC à fonction systolique altérée**.","prio":"P1","sec":"s9"},{"id":"fc-224-3bbf95","poly":"cardio","fiche":"224","front":"Thiazidiques : quels effets indésirables ?","back":"**Hypokaliémie**, **hyponatrémie**, hyperglycémie, **hyperuricémie**, IR fonctionnelle.","prio":"P1","sec":"s9"},{"id":"fc-224-9e0227","poly":"cardio","fiche":"224","front":"IEC : quel est l'effet indésirable typique (absent sous ARA2) ?","back":"La **toux** (+ hyperkaliémie, IR fonctionnelle, communes aux ARA2).","prio":"P1","sec":"s9"},{"id":"fc-224-92a860","poly":"cardio","fiche":"224","front":"IC dihydropyridines : quels effets indésirables ?","back":"**Œdèmes des membres inférieurs**, céphalées, vertiges, flushs.","prio":"P1","sec":"s9"},{"id":"fc-224-04c2c3","poly":"cardio","fiche":"224","front":"IC non dihydropyridines : quels effets indésirables propres ?","back":"Ceux des dihydropyridines + **bradycardie**, **troubles de conduction**, **constipation**.","prio":"P2","sec":"s9"},{"id":"fc-224-ddd48d","poly":"cardio","fiche":"224","front":"Bêtabloquants : quels effets indésirables ?","back":"**Asthénie**, **bradycardie sinusale**, acrosyndrome, hypoglycémie, baisse de libido, dysfonction érectile, prise de poids.","prio":"P2","sec":"s9"},{"id":"fc-224-5c1d01","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles classes ont la meilleure persistance au long cours ?","back":"**ARA2 et IEC** > IC > thiazidiques et bêtabloquants.","prio":"P3","sec":"s9"},{"id":"fc-224-6f40db","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles interactions imposent d'adapter le traitement ?","back":"**Bradycardisants + bêtabloquants** ; **AINS + IEC/ARA2**.","prio":"P3","sec":"s9"},{"id":"fc-224-5f19aa","poly":"cardio","fiche":"224","front":"Éducation thérapeutique dans l'HTA : quel geste apprendre en cas de risque d'hypovolémie ?","back":"**Diminuer ou suspendre transitoirement** diurétiques, IEC et ARA2.","prio":"P2","sec":"s9"},{"id":"fc-224-c188ed","poly":"cardio","fiche":"224","front":"Hypertendu en insuffisance cardiaque à fonction systolique altérée : quelles classes préférer ?","back":"**IEC** (ARA2 si intolérance), **bêtabloquant**, **diurétique** ; probablement iSGLT2 ; ARM aussi.","prio":"P3","sec":"s9"},{"id":"fc-224-6c4413","poly":"cardio","fiche":"224","front":"Sujet âgé hypertendu : sur quoi raisonner pour adapter le traitement ?","back":"Sur la **fragilité** et l'**espérance de vie**, pas sur l'âge seul ; dépister systématiquement l'**hypotension orthostatique**.","prio":"P1","sec":"s10"},{"id":"fc-224-9f32e0","poly":"cardio","fiche":"224","front":"Hypertendu de moins de 85 ans non fragile : faut-il adapter le traitement ?","back":"**Non** : prise en charge **standard**.","prio":"P2","sec":"s10"},{"id":"fc-224-167534","poly":"cardio","fiche":"224","front":"Hypertendu traité qui atteint 85 ans et tolère bien : faut-il baisser le traitement ?","back":"**Non** : pas d'arrêt ni de baisse systématique.","prio":"P2","sec":"s10"},{"id":"fc-224-57e33a","poly":"cardio","fiche":"224","front":"Sujet âgé : quels critères imposent de débuter en monothérapie ?","back":"**Fragilité** modérée/sévère, âge **≥ 85 ans** ou espérance de vie **< 3 ans**.","prio":"P1","sec":"s10"},{"id":"fc-224-4a0747","poly":"cardio","fiche":"224","front":"Sujet âgé hypertendu fragile ou ≥ 85 ans : quel nombre maximal de classes ?","back":"**Pas plus d'une trithérapie** ; cible individualisée, sans hypotension orthostatique.","prio":"P2","sec":"s10"},{"id":"fc-224-987edc","poly":"cardio","fiche":"224","front":"Sujet âgé fragile ou ≥ 85 ans : quels antihypertenseurs en 1re intention ?","back":"**IC dihydropyridine** et/ou **IEC/ARA2**.","prio":"P2","sec":"s10"},{"id":"fc-224-4e07b7","poly":"cardio","fiche":"224","front":"Sujet âgé fragile ou ≥ 85 ans : quel antihypertenseur en 2e intention ?","back":"**Thiazidique** (ou apparenté) à **faible dose**.","prio":"P2","sec":"s10"},{"id":"fc-224-683833","poly":"cardio","fiche":"224","front":"Sujet âgé fragile ou ≥ 85 ans : quels antihypertenseurs éviter ?","back":"**Bêtabloquants** (sauf indication formelle) et **alphabloquants**.","prio":"P2","sec":"s10"},{"id":"fc-224-8c70d5","poly":"cardio","fiche":"224","front":"Thiazidiques et grossesse : quel type de contre-indication ?","back":"CI **relative** (pas absolue), contrairement aux IEC/ARA2.","prio":"P2","sec":"s10"},{"id":"fc-224-e07632","poly":"cardio","fiche":"224","front":"Prééclampsie sévère ou éclampsie : quelle prise en charge ?","back":"Urgence hypertensive imposant une **extraction fœtale en urgence**.","prio":"P1","sec":"s10"},{"id":"fc-224-ec4aa9","poly":"cardio","fiche":"224","front":"Hypertendu sous diurétique/IEC/ARA2 avec diarrhée ou canicule : quelle conduite ?","back":"**Diminution ou arrêt transitoire** ; contrôle ionogramme et créatininémie/DFG.","prio":"P1","sec":"s10"},{"id":"fc-224-95043b","poly":"cardio","fiche":"224","front":"Urgence hypertensive : où hospitaliser et à quel rythme surveiller la PA ?","back":"**Soins intensifs** ou **réanimation** ; PA **toutes les 15 min**.","prio":"P2","sec":"s11"},{"id":"fc-224-2b29ca","poly":"cardio","fiche":"224","front":"Urgence hypertensive avec point d'appel neurologique : quel examen avant tout antihypertenseur ?","back":"Un **scanner cérébral**.","prio":"P2","sec":"s11"},{"id":"fc-224-f9c970","poly":"cardio","fiche":"224","front":"Urgence hypertensive (cas général) : quel objectif de baisse de PA ?","back":"**− 25 % en 2 h**, puis **160/110 mmHg en 2 à 6 h**, sans chute brutale.","prio":"P2","sec":"s11"},{"id":"fc-224-83fca2","poly":"cardio","fiche":"224","front":"Urgence hypertensive : pourquoi éviter une baisse trop rapide de la PA ?","back":"Autorégulation altérée : risque d'hypoperfusion **cérébrale**, d'ischémie **myocardique** ou **rénale**.","prio":"P2","sec":"s11"},{"id":"fc-224-7ec0ce","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quels antihypertenseurs IV de 1re intention ?","back":"**Urapidil IV** et/ou **nicardipine IV**.","prio":"P2","sec":"s11"},{"id":"fc-224-b136f8","poly":"cardio","fiche":"224","front":"Phéochromocytome en urgence hypertensive : quelle molécule IV ?","back":"Le **labétalol IV**.","prio":"P2","sec":"s11"},{"id":"fc-224-934d10","poly":"cardio","fiche":"224","front":"Urgence hypertensive avec SCA ou OAP : quel antihypertenseur IV de 1re intention ?","back":"Les **dérivés nitrés IV**.","prio":"P2","sec":"s11"},{"id":"fc-224-9472d1","poly":"cardio","fiche":"224","front":"Nicardipine IV dans l'item 224 : quelle contre-indication ?","back":"L'**insuffisance cardiaque** (l'item 234 la cite pourtant dans la poussée hypertensive de l'OAP).","prio":"P3","sec":"s11"},{"id":"fc-224-7d1eed","poly":"cardio","fiche":"224","front":"Dissection aortique : quel objectif tensionnel ?","back":"**PAS < 120 mmHg le plus vite possible** (pas de baisse progressive).","prio":"P2","sec":"s11"},{"id":"fc-224-de0ca3","poly":"cardio","fiche":"224","front":"Hémorragie intracérébrale : quel objectif tensionnel ?","back":"Baisse **dans les 6 h** vers une **PAS de 140-160 mmHg** ; éviter une chute de PAS > 70 mmHg.","prio":"P3","sec":"s11"},{"id":"fc-224-15a018","poly":"cardio","fiche":"224","front":"AVC ischémique sans reperfusion : quand baisser la PA ?","back":"Seulement si PA **> 220/120 mmHg** : − 10-15 % sur quelques heures.","prio":"P3","sec":"s11"},{"id":"fc-224-b86000","poly":"cardio","fiche":"224","front":"Thrombolyse IV d'un AVC : quels seuils de PA avant et pendant 24 h ?","back":"**< 185/110** avant, puis **< 180/105** pendant 24 h.","prio":"P3","sec":"s11"},{"id":"fc-224-857685","poly":"cardio","fiche":"224","front":"Thrombectomie d'un AVC : quel seuil de PA ?","back":"**< 180/105** avant et pendant les 24 h suivantes.","prio":"P3","sec":"s11"},{"id":"fc-224-c7cfac","poly":"cardio","fiche":"224","front":"Après un AVC ischémique : quand débuter ou reprendre l'antihypertenseur ?","back":"Patient **stable** encore **≥ 140/90 mmHg au moins 3 jours** après l'AVC.","prio":"P2","sec":"s11"},{"id":"fc-224-399e49","poly":"cardio","fiche":"224","front":"Après un AVC : quelles classes antihypertensives privilégier ?","back":"**IEC, ARA2, IC** ou **diurétique**.","prio":"P3","sec":"s11"},{"id":"fc-224-15b281","poly":"cardio","fiche":"224","front":"OAP hypertensif : quand introduire IEC, ARA2 ou valsartan/sacubitril ?","back":"**Secondairement**, une fois la poussée passée.","prio":"P3","sec":"s11"},{"id":"fc-224-ec7fb6","poly":"cardio","fiche":"224","front":"OAP : quand ne pas introduire de bêtabloquant ?","back":"**Pendant la poussée** (arrêt ou baisse s'il était déjà prescrit).","prio":"P3","sec":"s11"},{"id":"fc-224-e1041d","poly":"cardio","fiche":"224","front":"Dissection aortique : quand opérer en urgence ?","back":"Atteinte de l'**aorte ascendante** (type A de Stanford) ; sauf type B (aorte descendante) sans complication périphérique.","prio":"P3","sec":"s11"},{"id":"fc-224-a2c906","poly":"cardio","fiche":"224","front":"Sténose athéromateuse de l'artère rénale : quand discuter une revascularisation ?","back":"**Uniquement** si souffrance du rein homolatéral (HTA résistante, DFG qui baisse, protéinurie) **et** rein encore fonctionnel.","prio":"P3","sec":"s12"},{"id":"fc-224-905ce8","poly":"cardio","fiche":"224","front":"Sténose athéromateuse vs dysplasie fibromusculaire : quelle angioplastie ?","back":"Athérome : **avec endoprothèse** ; dysplasie : **sans endoprothèse** (plus largement utilisée).","prio":"P3","sec":"s12"},{"id":"fc-224-af85e1","poly":"cardio","fiche":"224","front":"Phéochromocytome : quelle préparation avant la chirurgie ?","back":"**Alphabloquant** à petites doses augmentées progressivement, **associé à un bêtabloquant**, avant l'**exérèse**.","prio":"P2","sec":"s12"},{"id":"fc-224-a95f82","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : quand proposer une surrénalectomie ?","back":"Lésion **unilatérale** (latéralisation par cathétérisme veineux) **et** patient demandeur.","prio":"P3","sec":"s12"},{"id":"fc-224-e1533f","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire non opéré : quel traitement médical ?","back":"**Spironolactone** (ARM) en 1re intention.","prio":"P2","sec":"s12"},{"id":"fc-224-d2d4b0","poly":"cardio","fiche":"224","front":"SAOS de l'hypertendu : quel traitement ?","back":"Masque de **pression positive** nocturne.","prio":"P3","sec":"s12"},{"id":"fc-224-855145","poly":"cardio","fiche":"224","front":"Insuffisance rénale apparue sous IEC/ARA2 : quelle cause évoquer ?","back":"Une **sténose des artères rénales**.","prio":"P2","sec":"s12"},{"id":"fc-224-9fb181","poly":"cardio","fiche":"224","front":"Premiers mois de traitement de l'HTA : quand contrôler la PA par AMT ?","back":"**1 mois après chaque adaptation** et **avant chaque consultation**.","prio":"P1","sec":"s13"},{"id":"fc-224-37d1a7","poly":"cardio","fiche":"224","front":"Introduction ou changement de dose d'IEC/ARA2 ou de diurétique : quel contrôle biologique ?","back":"**Ionogramme sanguin** + **créatininémie/DFGe**.","prio":"P1","sec":"s13"},{"id":"fc-224-6bf8db","poly":"cardio","fiche":"224","front":"HTA : que vérifier à chaque consultation de suivi des premiers mois ?","back":"**Hypotension orthostatique**, **effets indésirables**, tolérance (réadapter la cible si besoin).","prio":"P2","sec":"s13"},{"id":"fc-224-6ea4d6","poly":"cardio","fiche":"224","front":"Cible tensionnelle non atteinte à 1 mois sous bithérapie : quelle conduite ?","back":"Renforcer **MHD** et **observance**, puis passer à la **trithérapie** **avant** d'augmenter les doses.","prio":"P1","sec":"s13"},{"id":"fc-224-16ebe7","poly":"cardio","fiche":"224","front":"HTA : quelle trithérapie utiliser ?","back":"**IEC/ARA2 + IC + thiazidique** (ou apparenté).","prio":"P1","sec":"s13"},{"id":"fc-224-2cfe8d","poly":"cardio","fiche":"224","front":"Hypertendu contrôlé : à quel rythme le revoir en consultation ?","back":"**Tous les 3 à 6 mois** (6 mois si faible risque ou grade 1 ; 3 mois si risque élevé ou MHD seules).","prio":"P3","sec":"s13"},{"id":"fc-224-cc0992","poly":"cardio","fiche":"224","front":"Hypertendu contrôlé : à quel rythme le bilan rénal et ionique ?","back":"**Chaque année** (plus souvent chez l'âgé).","prio":"P3","sec":"s13"},{"id":"fc-224-717d8b","poly":"cardio","fiche":"224","front":"Hypertendu contrôlé sans diabète ni dyslipidémie : à quel rythme glycémie et lipides ?","back":"**Tous les 3 ans**.","prio":"P3","sec":"s13"},{"id":"fc-224-eeaae1","poly":"cardio","fiche":"224","front":"Hypertendu avec ECG initial normal : à quel rythme refaire l'ECG ?","back":"**Tous les 3 à 5 ans**, sauf cardiopathie ou nouveaux symptômes.","prio":"P3","sec":"s13"},{"id":"fc-224-84b2ad","poly":"cardio","fiche":"224","front":"HTA résistante : quelle définition ?","back":"PA hors cible malgré MHD et **≥ 3 classes à dose optimale dont un thiazidique**, confirmée par **AMT/MAPA**.","prio":"P2","sec":"s14"},{"id":"fc-224-3d106b","poly":"cardio","fiche":"224","front":"HTA hors cible sous trithérapie sans thiazidique : est-ce une HTA résistante ?","back":"**Non** : sans thiazidique, on ne parle pas d'HTA résistante.","prio":"P2","sec":"s14"},{"id":"fc-224-89dabb","poly":"cardio","fiche":"224","front":"HTA résistante : quelles causes de fausse résistance éliminer ?","back":"**Blouse blanche**, brassard inadapté, doses insuffisantes ou pas de diurétique, **mauvaise observance**, MHD non suivies.","prio":"P2","sec":"s14"},{"id":"fc-224-068138","poly":"cardio","fiche":"224","front":"HTA résistante : quels facteurs de résistance rechercher ?","back":"**Excès de sel**, prise de poids, alcool, dépression, **AINS**, corticoïdes, œstrogènes, toxiques, **apnées du sommeil**.","prio":"P2","sec":"s14"},{"id":"fc-224-50d0cb","poly":"cardio","fiche":"224","front":"HTA résistante sans cause curable : quel médicament de 4e ligne ?","back":"**Spironolactone** (ARM) ; **éplérénone** si mal tolérée.","prio":"P2","sec":"s14"},{"id":"fc-224-c2b3de","poly":"cardio","fiche":"224","front":"HTA résistante : quelles options après l'ARM ?","back":"**Bêtabloquant**, puis éventuellement alphabloquant ou antihypertenseur central ; **dénervation rénale** au cas par cas.","prio":"P3","sec":"s14"},{"id":"fc-224-3064d5","poly":"cardio","fiche":"224","front":"HTA de l'enfant : sur quoi repose sa définition ?","back":"Sur des **normes pédiatriques** (abaques selon l'**âge** et le **sexe**).","prio":"P1","sec":"s15"},{"id":"fc-224-888cae","poly":"cardio","fiche":"224","front":"HTA de l'enfant : quand mesurer la PA ?","back":"À l'**examen systématique annuel après 3 ans** et en présence de **facteurs de risque**.","prio":"P1","sec":"s15"},{"id":"fc-224-e2db86","poly":"cardio","fiche":"224","front":"Mesure de la PA chez l'enfant : quelle précaution technique ?","back":"Un **brassard adapté** à sa taille.","prio":"P2","sec":"s15"},{"id":"fc-224-c21b0a","poly":"cardio","fiche":"224","front":"HTA de l'enfant : quel terrain familial augmente le risque ?","back":"Parent(s) **hypertendu(s)**, surtout si l'HTA parentale a débuté **jeune**.","prio":"P3","sec":"s15"},{"id":"fc-225-458199","poly":"cardio","fiche":"225","front":"AOMI : de quelle maladie s'agit-il et quelle étendue artérielle ?","back":"**Athérome** rétrécissant ou bouchant les artères des membres inférieurs, de l'**aorte terminale** aux artères des orteils.","prio":"P1","sec":"s1"},{"id":"fc-225-8023b1","poly":"cardio","fiche":"225","front":"AOMI : pourquoi reste-t-elle longtemps asymptomatique ?","back":"Débit encore suffisant et développement d'**artères collatérales**, d'autant mieux que l'évolution est lente.","prio":"P2","sec":"s1"},{"id":"fc-225-05a2a5","poly":"cardio","fiche":"225","front":"AOMI : quel mécanisme explique la claudication ?","back":"**Ischémie d'effort** : le muscle manque d'oxygène quand ses besoins augmentent.","prio":"P2","sec":"s1"},{"id":"fc-225-5cc157","poly":"cardio","fiche":"225","front":"AOMI : quel rang parmi les localisations de l'athérosclérose ?","back":"**3ᵉ localisation**, après l'atteinte **coronarienne** et **cérébrale**.","prio":"P1","sec":"s1"},{"id":"fc-225-55baef","poly":"cardio","fiche":"225","front":"AOMI symptomatique : quel sexe et quel âge de pic ?","back":"Plus fréquente chez l'**homme** ; pic **60-75 ans** (homme), **70-80 ans** (femme).","prio":"P2","sec":"s1"},{"id":"fc-225-cb04a5","poly":"cardio","fiche":"225","front":"AOMI après 60 ans : quelle prévalence ?","back":"**1 à 5 %** (formes cliniques) ; jusqu'à **10-15 %** avec les formes asymptomatiques.","prio":"P3","sec":"s1"},{"id":"fc-225-03977c","poly":"cardio","fiche":"225","front":"AOMI : combien de formes infracliniques pour une forme clinique ?","back":"**Deux à quatre** (d'où l'intérêt du dépistage).","prio":"P2","sec":"s1"},{"id":"fc-225-ba6289","poly":"cardio","fiche":"225","front":"AOMI : quels sont les deux facteurs de risque principaux ?","back":"**Tabagisme** et **diabète** (+ souvent hypercholestérolémie, HTA).","prio":"P2","sec":"s1"},{"id":"fc-225-432567","poly":"cardio","fiche":"225","front":"AOMI du diabétique : quelles particularités ?","back":"Formes plus souvent **graves d'emblée**, plus **distales**, de pronostic plus sévère.","prio":"P2","sec":"s1"},{"id":"fc-225-d3ae07","poly":"cardio","fiche":"225","front":"AOMI : quel facteur de risque concerne plutôt le sujet jeune ?","back":"Le **tabac**.","prio":"P3","sec":"s1"},{"id":"fc-225-9189ef","poly":"cardio","fiche":"225","front":"Classification de Leriche et Fontaine : que définit chaque stade ?","back":"**I** asymptomatique ; **II** claudication ; **III** douleur de repos ; **IV** ulcération ou gangrène.","prio":"P1","sec":"s2"},{"id":"fc-225-8ac67e","poly":"cardio","fiche":"225","front":"AOMI : quelle classification a largement remplacé celle de Leriche et Fontaine ?","back":"Celle de **Rutherford** (grade 0 à III).","prio":"P2","sec":"s2"},{"id":"fc-225-2e7d32","poly":"cardio","fiche":"225","front":"Claudication intermittente typique : quelles caractéristiques ?","back":"Crampe du **mollet** après une distance, obligeant à **s'arrêter**, cédant en **moins de 5 min** ; distance **classiquement stable**.","prio":"P1","sec":"s2"},{"id":"fc-225-c048ff","poly":"cardio","fiche":"225","front":"Claudication : à partir de quelle distance de marche est-elle sévère ?","back":"Distance de marche **inférieure à 100 m**.","prio":"P1","sec":"s2"},{"id":"fc-225-3afed6","poly":"cardio","fiche":"225","front":"Claudication fessière : quel niveau d'atteinte ?","back":"Atteinte **aorto-iliaque**.","prio":"P1","sec":"s2"},{"id":"fc-225-804b9b","poly":"cardio","fiche":"225","front":"Claudication atypique : citer des formes fréquentes.","back":"Distance **variable** ; douleur au pied, à la cuisse ou à la fesse ; **paresthésies** d'effort ; patient qui **ralentit** sans s'arrêter.","prio":"P2","sec":"s2"},{"id":"fc-225-603446","poly":"cardio","fiche":"225","front":"Syndrome de Leriche : quels signes ?","back":"Claudication **fessière** et/ou fatigabilité à la marche + **impuissance**, par atteinte **aorto-iliaque** (homme).","prio":"P1","sec":"s2"},{"id":"fc-225-f0d270","poly":"cardio","fiche":"225","front":"AOMI masquée : quelles situations peuvent masquer une atteinte sévère ?","back":"Collatérales très développées ; sujet qui **ne marche plus assez** ; **neuropathie** (diabète, IR, grand âge).","prio":"P1","sec":"s2"},{"id":"fc-225-d0d004","poly":"cardio","fiche":"225","front":"AOMI masquée (neuropathie, sujet qui ne marche plus assez) : quel risque évolutif ?","back":"Le patient **peut** arriver **d'emblée en ischémie permanente**.","prio":"P2","sec":"s2"},{"id":"fc-225-fcc9fd","poly":"cardio","fiche":"225","front":"Douleurs de décubitus de l'AOMI (stade III) : quelles caractéristiques ?","back":"Brûlures des **orteils et de l'avant-pied** en position couchée, **calmées jambe pendante**.","prio":"P1","sec":"s2"},{"id":"fc-225-bdc876","poly":"cardio","fiche":"225","front":"Ulcères artériels : où siègent-ils surtout ?","back":"**Zones de frottement ou d'appui** : orteil, dos et bord externe du pied, talon.","prio":"P2","sec":"s2"},{"id":"fc-225-776b21","poly":"cardio","fiche":"225","front":"Gangrène de l'AOMI : chez qui est-elle plus fréquente ?","back":"Chez le **diabétique**, souvent avec des lésions infectées.","prio":"P2","sec":"s2"},{"id":"fc-225-1d7283","poly":"cardio","fiche":"225","front":"Ischémie permanente : quelle définition ?","back":"Stades **III et IV**, douleurs depuis **plus de 15 jours** résistant aux antalgiques usuels.","prio":"P1","sec":"s2"},{"id":"fc-225-4e0c8b","poly":"cardio","fiche":"225","front":"Ischémie critique : quels seuils de pression la définissent ?","back":"Ischémie permanente + pression de **cheville < 50 mmHg** ou d'**hallux < 30 mmHg**.","prio":"P1","sec":"s2"},{"id":"fc-225-68fa23","poly":"cardio","fiche":"225","front":"Ischémie critique : quel risque pour le membre ?","back":"Membre **menacé** : haut risque d'**amputation** sans revascularisation.","prio":"P2","sec":"s2"},{"id":"fc-225-b827f5","poly":"cardio","fiche":"225","front":"AOMI : quel est le temps de recoloration normal ?","back":"**Moins de 3 secondes** (allongé si ischémie).","prio":"P2","sec":"s2"},{"id":"fc-225-4fe174","poly":"cardio","fiche":"225","front":"Pouls pédieux : dans quelle proportion est-il absent de naissance ?","back":"Chez **5 %** de la population.","prio":"P3","sec":"s2"},{"id":"fc-225-79588f","poly":"cardio","fiche":"225","front":"Examen d'un patient avec AOMI : quels anévrismes rechercher systématiquement ?","back":"**Abdominal** (aortique) et **poplité**.","prio":"P2","sec":"s2"},{"id":"fc-225-edee33","poly":"cardio","fiche":"225","front":"AOMI : que signifie une douleur à la pression du mollet ?","back":"Une **ischémie sévère**.","prio":"P3","sec":"s2"},{"id":"fc-225-01eb04","poly":"cardio","fiche":"225","front":"Suspicion clinique d'AOMI : quel examen compléter systématiquement ?","back":"La mesure de l'**IPS**.","prio":"P1","sec":"s2"},{"id":"fc-225-034b73","poly":"cardio","fiche":"225","front":"AOMI : quelles autres atteintes athéromateuses rechercher ?","back":"**Maladie coronarienne** et atteinte **cérébrovasculaire** (fréquemment associées).","prio":"P2","sec":"s2"},{"id":"fc-225-a4c008","poly":"cardio","fiche":"225","front":"Troubles trophiques de l'AOMI : quel risque infectieux ?","back":"**Portes d'entrée** d'infection : cellulite, arthrite, **ostéite**, voire septicémie.","prio":"P3","sec":"s2"},{"id":"fc-225-a600bd","poly":"cardio","fiche":"225","front":"IPS : comment le calculer pour chaque jambe ?","back":"**Plus haute** pression de cheville (tibiale postérieure ou pédieuse) / **plus haute** pression des **deux bras**.","prio":"P1","sec":"s3"},{"id":"fc-225-089111","poly":"cardio","fiche":"225","front":"IPS : avec quel matériel le mesure-t-on au cabinet ?","back":"Un brassard et un **doppler de poche**.","prio":"P3","sec":"s3"},{"id":"fc-225-dc93a8","poly":"cardio","fiche":"225","front":"IPS : quelles valeurs sont normales ?","back":"**1,00 à 1,40**.","prio":"P1","sec":"s3"},{"id":"fc-225-954d06","poly":"cardio","fiche":"225","front":"IPS : quel seuil définit l'AOMI ?","back":"IPS **< 0,90** (au moins une cheville).","prio":"P1","sec":"s3"},{"id":"fc-225-9b2a87","poly":"cardio","fiche":"225","front":"IPS : quel seuil définit une AOMI sévère ?","back":"IPS **< 0,70** (le texte du chapitre ; les points clés ont une coquille).","prio":"P1","sec":"s3"},{"id":"fc-225-bd5286","poly":"cardio","fiche":"225","front":"IPS < 0,90 : quelle portée au-delà du diagnostic d'AOMI ?","back":"**Marqueur de risque cardiovasculaire** élevé (accidents coronariens ou cérébraux).","prio":"P1","sec":"s3"},{"id":"fc-225-afd4ac","poly":"cardio","fiche":"225","front":"IPS > 1,40 : que traduit-il ?","back":"Des artères **anormalement rigides** par **médiacalcose** (diabétique âgé, dialysé).","prio":"P1","sec":"s3"},{"id":"fc-225-381cd6","poly":"cardio","fiche":"225","front":"IPS > 1,40 : quelle mesure faire à la place ?","back":"La **pression d'orteil** : index d'orteil **< 0,70** = AOMI ; pression d'orteil **< 30 mmHg** = ischémie critique.","prio":"P2","sec":"s3"},{"id":"fc-225-665799","poly":"cardio","fiche":"225","front":"Médiacalcose : en quoi diffère-t-elle de l'athérosclérose ?","back":"**Calcification de la média** sans rétrécissement de la lumière.","prio":"P3","sec":"s3"},{"id":"fc-225-65a06f","poly":"cardio","fiche":"225","front":"Diabétique symptomatique avec IPS de repos normal : quelle conduite ?","back":"**Pression d'orteil** et **tests d'effort** (IPS après effort, TcPO2 à l'effort) : l'IPS de repos peut faussement rassurer.","prio":"P2","sec":"s3"},{"id":"fc-225-f3c82e","poly":"cardio","fiche":"225","front":"Test sur tapis roulant : quel résultat évoque une AOMI chez un claudicant à IPS de repos normal ?","back":"Baisse de la pression de cheville **> 30 mmHg** et/ou de l'IPS **> 20 %** juste après la marche.","prio":"P3","sec":"s3"},{"id":"fc-225-6fa425","poly":"cardio","fiche":"225","front":"Test de marche de 6 minutes : que mesure-t-il ?","back":"Le **handicap fonctionnel global** (non spécifique de l'AOMI).","prio":"P3","sec":"s3"},{"id":"fc-225-eb7810","poly":"cardio","fiche":"225","front":"TcPO2 : à quoi sert-elle dans l'AOMI ?","back":"Diagnostic et évaluation de l'**ischémie critique** (oxygénation cutanée, après hyperémie par la chaleur).","prio":"P2","sec":"s3"},{"id":"fc-225-25f6f3","poly":"cardio","fiche":"225","front":"TcPO2 au dos du pied : quel seuil définit l'hypoxie critique ?","back":"**< 10 mmHg** (normale > 50 mmHg).","prio":"P2","sec":"s3"},{"id":"fc-225-1c4546","poly":"cardio","fiche":"225","front":"AOMI : quel examen d'imagerie est le plus utilisé ?","back":"L'**échodoppler artériel** (non invasif ; localise et quantifie les sténoses).","prio":"P1","sec":"s3"},{"id":"fc-225-c1221e","poly":"cardio","fiche":"225","front":"AOMI : quand demander un angioscanner ou une angio-IRM ?","back":"**Seulement si une revascularisation est envisagée**.","prio":"P1","sec":"s3"},{"id":"fc-225-d23040","poly":"cardio","fiche":"225","front":"Angio-IRM des membres inférieurs : quelle limite pour le chirurgien ?","back":"Elle **ne voit pas les calcifications** ; gadolinium CI si clairance < 30 mL/min/1,73 m².","prio":"P3","sec":"s3"},{"id":"fc-225-528242","poly":"cardio","fiche":"225","front":"AOMI : quand réalise-t-on l'artériographie ?","back":"Essentiellement **pendant les procédures de revascularisation**.","prio":"P2","sec":"s3"},{"id":"fc-225-04fa1d","poly":"cardio","fiche":"225","front":"AOMI : quel est le bilan de base ?","back":"**IPS + échodoppler**.","prio":"P1","sec":"s3"},{"id":"fc-225-3930fc","poly":"cardio","fiche":"225","front":"Douleur du mollet à l'effort cédant au repos : quel diagnostic différentiel neurologique ?","back":"Le **canal lombaire étroit**.","prio":"P1","sec":"s4"},{"id":"fc-225-443758","poly":"cardio","fiche":"225","front":"Douleur de jambe à la marche : quels diagnostics différentiels non artériels ?","back":"**Neurologiques** (canal lombaire étroit), **rhumatologiques**, **veineux** (claudication post-thrombotique), **musculaires** (statines).","prio":"P2","sec":"s4"},{"id":"fc-225-eaf911","poly":"cardio","fiche":"225","front":"Douleur de décubitus de jambe : quels diagnostics différentiels ?","back":"**Neuropathie sensitive**, syndromes douloureux régionaux complexes, **compression radiculaire**.","prio":"P3","sec":"s4"},{"id":"fc-225-ace6ac","poly":"cardio","fiche":"225","front":"Ulcère de jambe non artériel : quelles autres causes ?","back":"**Veineux**, microcirculatoire, **neuropathique**, traumatique.","prio":"P3","sec":"s4"},{"id":"fc-225-cf5979","poly":"cardio","fiche":"225","front":"Sujet âgé avec canal lombaire étroit ou myalgies sous statine : l'AOMI est-elle exclue ?","back":"**Non** : plusieurs causes peuvent **coexister**.","prio":"P2","sec":"s4"},{"id":"fc-225-495f5a","poly":"cardio","fiche":"225","front":"Artériopathies oblitérantes des membres inférieurs : quelle part est athéromateuse ?","back":"**Plus de 95 %**.","prio":"P3","sec":"s4"},{"id":"fc-225-fbe736","poly":"cardio","fiche":"225","front":"Artériopathies non athéromateuses inflammatoires : lesquelles ?","back":"Maladies de **Buerger**, **Takayasu**, **Horton** ; certaines collagénoses (PAN, lupus).","prio":"P3","sec":"s4"},{"id":"fc-225-cf6d50","poly":"cardio","fiche":"225","front":"Artériopathies non athéromateuses propres à l'artère poplitée : lesquelles ?","back":"**Artère poplitée piégée** ; **kyste poplité sous-adventiciel**.","prio":"P3","sec":"s4"},{"id":"fc-225-80e957","poly":"cardio","fiche":"225","front":"Traitement de l'AOMI : quels sont les deux objectifs distincts ?","back":"**Général** : pronostic CV et vital ; **local** : symptômes et protection du membre.","prio":"P1","sec":"s5"},{"id":"fc-225-d10a8c","poly":"cardio","fiche":"225","front":"AOMI : à quels stades s'applique le traitement général ?","back":"À **tous les stades**, asymptomatique compris, et **après revascularisation**.","prio":"P1","sec":"s5"},{"id":"fc-225-2aa5c0","poly":"cardio","fiche":"225","front":"AOMI : quelles mesures viennent en tête du traitement général ?","back":"**Arrêt du tabac** et contrôle du **diabète**.","prio":"P1","sec":"s5"},{"id":"fc-225-0e86e6","poly":"cardio","fiche":"225","front":"AOMI : quel réentraînement à la marche viser ?","back":"**3 fois/semaine pendant 12 semaines**.","prio":"P2","sec":"s5"},{"id":"fc-225-c989eb","poly":"cardio","fiche":"225","front":"AOMI : chez qui prescrire une statine ?","back":"**Tous** les patients (systématique).","prio":"P1","sec":"s5"},{"id":"fc-225-8e0c09","poly":"cardio","fiche":"225","front":"AOMI : quel objectif de LDL-c ?","back":"**< 0,55 g/L (1,4 mmol/L)** et baisse d'**au moins 50 %**.","prio":"P1","sec":"s5"},{"id":"fc-225-17ef18","poly":"cardio","fiche":"225","front":"AOMI : quand l'antiagrégant plaquettaire est-il indiqué ?","back":"Chez **tout patient avec AOMI symptomatique** (aspirine ou clopidogrel).","prio":"P1","sec":"s5"},{"id":"fc-225-b27648","poly":"cardio","fiche":"225","front":"AOMI asymptomatique isolée (IPS < 0,90) : faut-il un antiagrégant ?","back":"Indication **débattue**, sauf autre atteinte athéromateuse.","prio":"P2","sec":"s5"},{"id":"fc-225-b16d3c","poly":"cardio","fiche":"225","front":"AOMI : chez qui envisager un IEC ou un sartan ?","back":"Chez **tout patient avec AOMI**, quel que soit le niveau de PA, sans contre-indication.","prio":"P1","sec":"s5"},{"id":"fc-225-bd9d2d","poly":"cardio","fiche":"225","front":"AOMI : quelles cibles tensionnelle et glycémique ?","back":"PAS **≤ 120-129** et PAD **≤ 70-79 mmHg** ; **HbA1c < 7 %**.","prio":"P2","sec":"s5"},{"id":"fc-225-f02c89","poly":"cardio","fiche":"225","front":"AOMI : quand proposer un bêtabloquant ?","back":"Si **indication formelle** (cardiopathie ischémique, IC à FE altérée, certaines arythmies) ; **prudence** si ischémie critique non revascularisable.","prio":"P2","sec":"s5"},{"id":"fc-225-b804ef","poly":"cardio","fiche":"225","front":"Antiagrégant dans l'AOMI : quelles molécules ?","back":"**Aspirine** ou **clopidogrel**.","prio":"P1","sec":"s5"},{"id":"fc-225-85778c","poly":"cardio","fiche":"225","front":"AOMI : quelles mesures hygiéno-diététiques ?","back":"**Arrêt du tabac**, **régime méditerranéen**, IMC entre **20 et 25 kg/m²**, **exercice modéré**.","prio":"P2","sec":"s5"},{"id":"fc-225-4cf018","poly":"cardio","fiche":"225","front":"Arrêt du tabac et marche régulière : comment améliorent-ils la claudication ?","back":"Développement des **collatérales** et du métabolisme musculaire (plus de **mitochondries**).","prio":"P2","sec":"s6"},{"id":"fc-225-019fa8","poly":"cardio","fiche":"225","front":"Claudication : quel programme de marche ?","back":"Au moins **30-45 min**, **au moins 3 fois/semaine**, en **ralentissant ou s'arrêtant** quelques minutes dès la douleur.","prio":"P1","sec":"s6"},{"id":"fc-225-adfd45","poly":"cardio","fiche":"225","front":"Claudication : pourquoi préférer la réadaptation supervisée ?","back":"**Meilleurs résultats** que le programme seul ; toujours associée à l'**éducation thérapeutique**.","prio":"P2","sec":"s6"},{"id":"fc-225-1746c9","poly":"cardio","fiche":"225","front":"Claudication : quand envisager une revascularisation d'emblée ?","back":"Périmètre de marche **< 100 m** très invalidant ou atteinte **aorto-iliaque sévère et extensive**.","prio":"P1","sec":"s6"},{"id":"fc-225-335579","poly":"cardio","fiche":"225","front":"Claudication sans périmètre très court ni atteinte aorto-iliaque sévère : quelle stratégie ?","back":"**Réadaptation à la marche d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-225-b4c5c5","poly":"cardio","fiche":"225","front":"Claudication : quand revasculariser après le traitement médical ?","back":"Claudication sévère altérant la qualité de vie **malgré** un traitement bien mené incluant la réadaptation.","prio":"P2","sec":"s6"},{"id":"fc-225-e2b9ff","poly":"cardio","fiche":"225","front":"Revascularisation de l'AOMI : quelles techniques ?","back":"**Angioplastie au ballonnet ± stent**, ou **pontage**.","prio":"P2","sec":"s6"},{"id":"fc-225-0b6da4","poly":"cardio","fiche":"225","front":"Vasoactifs (pentoxifylline) dans la claudication : quel intérêt ?","back":"Gain **modeste** du périmètre de marche, **aucun bénéfice pronostique**.","prio":"P3","sec":"s6"},{"id":"fc-225-a0290c","poly":"cardio","fiche":"225","front":"Statine dans la claudication : quel effet possible en plus du pronostic ?","back":"Un **allongement du périmètre de marche**.","prio":"P3","sec":"s6"},{"id":"fc-225-922f85","poly":"cardio","fiche":"225","front":"Ischémie permanente ou critique : quel est l'objectif principal ?","back":"**Revasculariser autant que possible**.","prio":"P1","sec":"s7"},{"id":"fc-225-c4a59e","poly":"cardio","fiche":"225","front":"Ischémie permanente : quel geste endovasculaire principal ?","back":"**Angioplastie intraluminale au ballonnet**, ± **stent**.","prio":"P2","sec":"s7"},{"id":"fc-225-5d9db5","poly":"cardio","fiche":"225","front":"Angioplastie des artères des membres inférieurs : quelles lésions donnent les meilleurs résultats ?","back":"Lésions **courtes et proximales**.","prio":"P3","sec":"s7"},{"id":"fc-225-faee2f","poly":"cardio","fiche":"225","front":"Pontage dans l'AOMI : quel matériau préférer ?","back":"Une **veine** (sinon une prothèse).","prio":"P2","sec":"s7"},{"id":"fc-225-8394bb","poly":"cardio","fiche":"225","front":"Endartériectomie fémorale : quel intérêt ?","back":"Améliore le réseau **fémoral profond**, donc les collatérales de cuisse si la fémorale superficielle est occluse.","prio":"P3","sec":"s7"},{"id":"fc-225-66f4af","poly":"cardio","fiche":"225","front":"Ischémie permanente : quels traitements associés à la revascularisation ?","back":"**Antalgiques**, **soins de plaies** pluridisciplinaires, socle médical (statine, antiagrégant, FDR).","prio":"P2","sec":"s7"},{"id":"fc-225-7ac1d5","poly":"cardio","fiche":"225","front":"AOMI : quand recourir à l'amputation ?","back":"Revascularisation **impossible ou en échec** : geste ultime contre la douleur et/ou l'infection.","prio":"P1","sec":"s7"},{"id":"fc-225-b52c59","poly":"cardio","fiche":"225","front":"Amputation dans l'AOMI : où et comment la réaliser ?","back":"En zone **saine et bien oxygénée** (**TcPO2**), en gardant si possible l'**appui** ou le **genou**.","prio":"P2","sec":"s7"},{"id":"fc-225-156dfa","poly":"cardio","fiche":"225","front":"Prostaglandines dans l'AOMI : quelle indication ?","back":"**Ischémie critique non revascularisable** (perfusions quotidiennes, plusieurs semaines).","prio":"P3","sec":"s7"},{"id":"fc-225-989575","poly":"cardio","fiche":"225","front":"Après angioplastie ± stent : quelle durée de bithérapie antiplaquettaire ?","back":"**1 à 6 mois** selon le geste et sa localisation.","prio":"P3","sec":"s7"},{"id":"fc-225-80f7d5","poly":"cardio","fiche":"225","front":"Patient revascularisé devenu asymptomatique : peut-on arrêter le traitement préventif ?","back":"**Non** : il n'est pas guéri, hygiène de vie et médicaments continuent.","prio":"P1","sec":"s7"},{"id":"fc-225-5e9e59","poly":"cardio","fiche":"225","front":"Pontage dans l'AOMI : quels sont les plus fréquents ?","back":"**Aorto-bi-iliaque** (ou bifémoral), **fémoropoplité**, **fémorojambier** ; extra-anatomique si besoin.","prio":"P3","sec":"s7"},{"id":"fc-225-dd2a0d","poly":"cardio","fiche":"225","front":"Claudication : de combien l'espérance de vie est-elle réduite ?","back":"De **10 ans** en moyenne.","prio":"P2","sec":"s8"},{"id":"fc-225-023f86","poly":"cardio","fiche":"225","front":"Claudication : quel pronostic vital à 5 ans ?","back":"**20 %** de complications CV et **20 %** de décès (moitié de cause CV).","prio":"P2","sec":"s8"},{"id":"fc-225-b6deb7","poly":"cardio","fiche":"225","front":"Claudication : quel pronostic local ?","back":"**25 %** s'aggravent (dont 1/5 jusqu'à l'amputation majeure) ; amputation à 5 ans ≈ **5 %**.","prio":"P3","sec":"s8"},{"id":"fc-225-d21db6","poly":"cardio","fiche":"225","front":"Ischémie critique : quelle mortalité à 5 ans ?","back":"Proche de **70 %**.","prio":"P1","sec":"s8"},{"id":"fc-225-b514b3","poly":"cardio","fiche":"225","front":"Ischémie permanente : à quoi compare-t-on son espérance de vie ?","back":"À celle de **certains cancers**.","prio":"P3","sec":"s8"},{"id":"fc-225-d8a10b","poly":"cardio","fiche":"225","front":"Après revascularisation d'une AOMI : quelle surveillance ?","back":"**Clinique et échodoppler** (thrombose de stent ou de pontage, dégradation des anastomoses).","prio":"P2","sec":"s8"},{"id":"fc-225-80e70b","poly":"cardio","fiche":"225","front":"Patient avec AOMI ou AAA : quelles atteintes rechercher (notion indispensable) ?","back":"Une **maladie coronarienne** et une **sténose carotidienne**.","prio":"P1","sec":"s8"},{"id":"fc-225-4a3ba3","poly":"cardio","fiche":"225","front":"Ischémie aiguë de membre : quelle définition ?","back":"Interruption **brutale** du flux artériel d'un membre : **urgence vasculaire**, pronostic du membre voire vital engagé.","prio":"P1","sec":"s9"},{"id":"fc-225-5ff412","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels éléments déterminent la gravité ?","back":"La **PA** du patient, la **circulation collatérale** et la qualité du **réseau d'aval**.","prio":"P2","sec":"s9"},{"id":"fc-225-02e727","poly":"cardio","fiche":"225","front":"Ischémie aiguë : en combien de temps souffrent nerfs, muscles et peau ?","back":"**Nerfs** dans les **2 h** ; **muscles** dans les **6-8 h** ; **peau** à partir de la **24ᵉ h**.","prio":"P1","sec":"s9"},{"id":"fc-225-f225ff","poly":"cardio","fiche":"225","front":"Syndrome des loges : quel mécanisme ?","back":"**Œdème musculaire** dans des **loges aponévrotiques inextensibles** comprimant les tissus jusqu'à l'arrêt circulatoire.","prio":"P2","sec":"s9"},{"id":"fc-225-11be60","poly":"cardio","fiche":"225","front":"Syndrome des loges : quel traitement ?","back":"**Aponévrotomie de décharge**.","prio":"P1","sec":"s9"},{"id":"fc-225-4e2a80","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle douleur typique ?","back":"Début **brutal**, intense, **en broiement**, avec impotence fonctionnelle.","prio":"P1","sec":"s9"},{"id":"fc-225-14a68d","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels signes physiques ?","back":"Membre **froid**, **livide**, muscles douloureux, **pouls abolis** en aval, **anesthésie**, **paralysie**.","prio":"P1","sec":"s9"},{"id":"fc-225-30e596","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quel déficit moteur fibulaire typique ?","back":"Le patient **ne peut plus relever le pied** (nerf fibulaire commun).","prio":"P3","sec":"s9"},{"id":"fc-225-a066d7","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle forme est la plus grave ?","back":"Occlusion de la **bifurcation aortique** : deux jambes, paralysie, jusqu'au **collapsus**.","prio":"P2","sec":"s9"},{"id":"fc-225-52b28f","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade I de Rutherford : quelles caractéristiques ?","back":"**Viable** : pas de déficit sensitif ni moteur ; urgence relative.","prio":"P1","sec":"s9"},{"id":"fc-225-2bd2ac","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade IIa : quelles caractéristiques ?","back":"Discrètement menaçante : déficit sensitif **absent ou limité aux orteils**, pas de déficit moteur.","prio":"P1","sec":"s9"},{"id":"fc-225-28aa12","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade IIb : quelles caractéristiques ?","back":"Immédiatement menaçante : déficit sensitif **au-delà des orteils**, déficit moteur **modéré**.","prio":"P1","sec":"s9"},{"id":"fc-225-aa7173","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade III : quelles caractéristiques ?","back":"**Irréversible** : anesthésie importante, **paralysie** ; perte tissulaire inévitable.","prio":"P1","sec":"s9"},{"id":"fc-225-2abb8a","poly":"cardio","fiche":"225","front":"Syndrome de revascularisation : quel mécanisme ?","back":"La **reperfusion** relargue **acides** et **radicaux libres**, avec des conséquences générales parfois sévères.","prio":"P2","sec":"s9"},{"id":"fc-225-5f432a","poly":"cardio","fiche":"225","front":"Ischémie aiguë : sur quoi repose le diagnostic ?","back":"Sur la **clinique** : équipe chirurgicale alertée au plus tôt, aucune imagerie ne doit retarder le geste.","prio":"P1","sec":"s10"},{"id":"fc-225-a6ce69","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels gestes faire toujours au lit du patient ?","back":"**Auscultation cardiaque + ECG**, **palpation abdominale** (anévrisme), **bilan de coagulation**.","prio":"P1","sec":"s10"},{"id":"fc-225-f6cfe6","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand réaliser un échodoppler ?","back":"Seulement s'il ne fait perdre **aucun temps** (notamment grade **I**).","prio":"P1","sec":"s10"},{"id":"fc-225-e8c854","poly":"cardio","fiche":"225","front":"Ischémie aiguë : où et pourquoi réaliser l'artériographie ?","back":"Le plus souvent **au bloc**, pour guider le geste (qualité du **réseau d'aval**).","prio":"P2","sec":"s10"},{"id":"fc-225-463fbf","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand faire le bilan cardiaque et artériel étiologique ?","back":"**Après** la revascularisation.","prio":"P2","sec":"s10"},{"id":"fc-225-30d063","poly":"cardio","fiche":"225","front":"Thrombose artérielle in situ : quel terrain et quelle douleur ?","back":"Sujet **plutôt âgé**, FDR, **souvent** AOMI préexistante ; douleur d'intensité **moyenne** (collatérales).","prio":"P2","sec":"s10"},{"id":"fc-225-e58495","poly":"cardio","fiche":"225","front":"Embolie artérielle sur artère saine : quel terrain et quelle douleur ?","back":"Sujet **classiquement jeune**, sans antécédent vasculaire ; douleur **brutale, sévère**, parfois précédée de **palpitations**.","prio":"P2","sec":"s10"},{"id":"fc-225-da2d74","poly":"cardio","fiche":"225","front":"Embolie artérielle : quel trouble du rythme en est une cause cardiaque ?","back":"La **fibrillation atriale**.","prio":"P2","sec":"s10"},{"id":"fc-225-833163","poly":"cardio","fiche":"225","front":"Embolie artérielle : citer d'autres causes cardiaques que la FA.","back":"**Infarctus** (anévrisme du VG), **endocardite**, valvulopathies et prothèses, **myxome**, FOP avec anévrisme du septum.","prio":"P3","sec":"s10"},{"id":"fc-225-665fe6","poly":"cardio","fiche":"225","front":"Thrombose artérielle in situ : citer des causes.","back":"**AOMI** ; **anévrisme poplité thrombosé** ; déshydratation du sujet âgé ; thrombopénie à l'héparine ; artériopathies non athéromateuses.","prio":"P3","sec":"s10"},{"id":"fc-225-e7f3aa","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quel traitement médical débuter dès le diagnostic ?","back":"**Héparine non fractionnée**, après prélèvement du **bilan de coagulation**.","prio":"P1","sec":"s11"},{"id":"fc-225-0d53cf","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle posologie d'HNF ?","back":"Bolus IV **5 000 UI** puis **500 UI/kg/j** ; objectif **TCA 2 à 3**.","prio":"P1","sec":"s11"},{"id":"fc-225-012562","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels traitements associés à l'héparine ?","back":"**Antalgiques de niveau 3**, **oxygène nasal**, remplissage si besoin, **soins locaux**.","prio":"P2","sec":"s11"},{"id":"fc-225-225ed0","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle position et protection du membre ?","back":"Position **légèrement déclive**, protection par mousse ou coton, sans frottement.","prio":"P3","sec":"s11"},{"id":"fc-225-e412c5","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade I : quelle stratégie ?","back":"**Imagerie en urgence** puis revascularisation **dans les heures à venir**.","prio":"P1","sec":"s11"},{"id":"fc-225-49f441","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade II : quelle stratégie ?","back":"**Revascularisation en urgence absolue** (thrombectomie ou pontage), sans imagerie qui retarde.","prio":"P1","sec":"s11"},{"id":"fc-225-dd4d81","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade III : quelle stratégie ?","back":"**Amputation**.","prio":"P1","sec":"s11"},{"id":"fc-225-a064f4","poly":"cardio","fiche":"225","front":"Embolie sur artère saine : quel est le geste de référence ?","back":"**Embolectomie par sonde de Fogarty** (sous contrôle angiographique).","prio":"P1","sec":"s11"},{"id":"fc-225-8732b7","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand discuter une thrombolyse in situ ?","back":"Lit d'aval jambier de **mauvaise qualité** **et** ischémie **peu sévère**.","prio":"P2","sec":"s11"},{"id":"fc-225-4af165","poly":"cardio","fiche":"225","front":"Ischémie aiguë revascularisée tardivement : quel geste associer ?","back":"**Aponévrotomie de décompression**, en général systématique.","prio":"P2","sec":"s11"},{"id":"fc-225-fc472a","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand l'angioplastie complète-t-elle la revascularisation ?","back":"Devant une **sténose résiduelle** après embolectomie ou thrombolyse.","prio":"P3","sec":"s11"},{"id":"fc-225-c5b779","poly":"cardio","fiche":"225","front":"Syndrome de revascularisation : quel trouble métabolique dépister systématiquement ?","back":"**Acidose métabolique hyperkaliémique** (ionogramme systématique).","prio":"P1","sec":"s12"},{"id":"fc-225-d1142e","poly":"cardio","fiche":"225","front":"Acidose hyperkaliémique après revascularisation : quel traitement ?","back":"**Bicarbonates IV** (correction progressive) ; chélateur du potassium voire **dialyse** ; lavage du membre.","prio":"P2","sec":"s12"},{"id":"fc-225-be1bfe","poly":"cardio","fiche":"225","front":"Après revascularisation d'une ischémie aiguë : comment dépister l'IRA ?","back":"**Sonde urinaire avec diurèse horaire**, urée, créatininémie, **CPK**.","prio":"P2","sec":"s12"},{"id":"fc-225-6b871d","poly":"cardio","fiche":"225","front":"IRA du syndrome de revascularisation : quel mécanisme principal ?","back":"**Nécrose tubulaire** : choc, **myoglobine** précipitant dans les tubules, produits de contraste.","prio":"P3","sec":"s12"},{"id":"fc-225-22393f","poly":"cardio","fiche":"225","front":"Syndrome de revascularisation : quels autres troubles biologiques ?","back":"Hyperuricémie, **myoglobinurie**, **hypocalcémie**, hyperphosphorémie ; CIVD possible.","prio":"P3","sec":"s12"},{"id":"fc-225-66c368","poly":"cardio","fiche":"225","front":"Ischémie aiguë d'origine embolique sur FA : quel traitement au long cours ?","back":"**Anticoagulation au long cours**.","prio":"P1","sec":"s12"},{"id":"fc-225-db146e","poly":"cardio","fiche":"225","front":"Ischémie aiguë par thrombose sur AOMI : quel traitement au long cours ?","back":"**Antiagrégant plaquettaire** + contrôle strict des FDR CV.","prio":"P1","sec":"s12"},{"id":"fc-225-eeb057","poly":"cardio","fiche":"225","front":"FA avec valve mécanique ou RM serré : quel anticoagulant oral ?","back":"Un **AVK** (warfarine) : **AOD contre-indiqués**.","prio":"P1","sec":"s12"},{"id":"fc-225-771ee3","poly":"cardio","fiche":"225","front":"AOD : quelle vérification faire avant la prescription ?","back":"La **fonction rénale** (déconseillés si clairance < 30 à 25 mL/min).","prio":"P2","sec":"s12"},{"id":"fc-225-73d4d2","poly":"cardio","fiche":"225","front":"AVK : quelle INR cible pour la plupart des indications ?","back":"INR **entre 2 et 3**.","prio":"P1","sec":"s12"},{"id":"fc-225-658e61","poly":"cardio","fiche":"225","front":"AVK : quel est l'AVK de référence et lequel ne pas débuter ?","back":"**Warfarine** ; ne pas débuter la **fluindione** (risque immunoallergique).","prio":"P2","sec":"s12"},{"id":"fc-225-3b9af7","poly":"cardio","fiche":"225","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"Après **au moins 4-5 jours** de chevauchement **et** **2 INR efficaces** à 24 h d'intervalle.","prio":"P2","sec":"s12"},{"id":"fc-225-be9b62","poly":"cardio","fiche":"225","front":"CHA₂DS₂-VA : combien de points pour un antécédent d'embolie artérielle ?","back":"**2 points** ; score > 1 → anticoagulation orale au long cours indiquée.","prio":"P2","sec":"s12"},{"id":"fc-225-c9a4ba","poly":"cardio","fiche":"225","front":"AVK : quand le patient est-il considéré équilibré ?","back":"Si **au moins 70 %** des INR sont dans la cible.","prio":"P3","sec":"s12"},{"id":"fc-225-5e2c63","poly":"cardio","fiche":"225","front":"Sous AOD : faut-il un suivi biologique de routine de la coagulation ?","back":"**Non** (TCA, TP, INR perturbés mais non interprétables).","prio":"P2","sec":"s12"},{"id":"fc-225-01537b","poly":"cardio","fiche":"225","front":"Valve mécanique mitrale ou à disque : quelle INR cible ?","back":"**3 à 4,5**.","prio":"P3","sec":"s12"},{"id":"fc-225-bc23d8","poly":"cardio","fiche":"225","front":"AOD : en combien de temps sont-ils efficaces après la 1re prise ?","back":"Environ **2 h** : anticoagulation immédiate, sans relais par héparine.","prio":"P3","sec":"s12"},{"id":"fc-225-df4df2","poly":"cardio","fiche":"225","front":"Anévrisme artériel : quelle définition ?","back":"Dilatation **focale et permanente**, perte du **parallélisme des parois**, diamètre augmenté de **> 50 %**.","prio":"P1","sec":"s13"},{"id":"fc-225-6a0c43","poly":"cardio","fiche":"225","front":"Anévrismes hors cerveau : quels sièges les plus fréquents ?","back":"**Aorte** (surtout **sous-rénale**), artères **poplitées**, artères **iliaques**.","prio":"P1","sec":"s13"},{"id":"fc-225-7d4441","poly":"cardio","fiche":"225","front":"AAA : quel mécanisme pariétal ?","back":"**Média** qui perd ses fibres élastiques et son collagène, sous l'action d'enzymes (**métalloprotéases**).","prio":"P3","sec":"s13"},{"id":"fc-225-a566d1","poly":"cardio","fiche":"225","front":"Porteur d'AAA : quel risque est le plus important ?","back":"**10 fois plus** de risque de mourir d'une autre atteinte CV (coronaire, AVC) que de la rupture.","prio":"P1","sec":"s13"},{"id":"fc-225-8654bc","poly":"cardio","fiche":"225","front":"AAA : quelle prévalence chez l'homme de plus de 65 ans ?","back":"**2 à 5 %**.","prio":"P3","sec":"s13"},{"id":"fc-225-5b850c","poly":"cardio","fiche":"225","front":"AAA : quels sont les facteurs de risque (hors âge) ?","back":"**Tabagisme** et **antécédents familiaux** d'anévrisme.","prio":"P1","sec":"s13"},{"id":"fc-225-3336b1","poly":"cardio","fiche":"225","front":"AAA : quel terrain est paradoxalement moins souvent atteint ?","back":"Les **diabétiques**.","prio":"P2","sec":"s13"},{"id":"fc-225-3bf73d","poly":"cardio","fiche":"225","front":"AAA sous-rénal < 40 mm : quel risque annuel de rupture ?","back":"Très faible : **0,4 %/an**.","prio":"P2","sec":"s13"},{"id":"fc-225-580f47","poly":"cardio","fiche":"225","front":"AAA sous-rénal de 50-59 mm : quel risque annuel de rupture ?","back":"**3 %/an**.","prio":"P2","sec":"s13"},{"id":"fc-225-d56bdd","poly":"cardio","fiche":"225","front":"AAA sous-rénal > 60 mm : quel risque annuel de rupture ?","back":"**15 %/an**.","prio":"P2","sec":"s13"},{"id":"fc-225-005f48","poly":"cardio","fiche":"225","front":"AAA : à diamètre égal, quel sexe a le plus de risque de rupture ?","back":"La **femme** : près de **4 fois** plus.","prio":"P1","sec":"s13"},{"id":"fc-225-a6859d","poly":"cardio","fiche":"225","front":"AAA : sur quel terrain survient-il dans 80-90 % des cas ?","back":"Chez un **athéromateux** (surtout AOMI).","prio":"P3","sec":"s13"},{"id":"fc-225-4303b0","poly":"cardio","fiche":"225","front":"AAA familial génétique : quelles maladies du tissu élastique ?","back":"**Marfan**, **Ehlers-Danlos**, **Loeys-Dietz**.","prio":"P3","sec":"s13"},{"id":"fc-225-fa9d6d","poly":"cardio","fiche":"225","front":"AAA : comment est-il le plus souvent découvert ?","back":"**Fortuitement** : masse **battante et expansive** paraombilicale ou, plus souvent, sur une imagerie abdominale.","prio":"P1","sec":"s13"},{"id":"fc-225-e1cf23","poly":"cardio","fiche":"225","front":"AAA symptomatique : quels signes de fissuration ou rupture ?","back":"Douleur **abdominale ou lombaire**, avec ou sans **choc hémorragique**.","prio":"P1","sec":"s13"},{"id":"fc-225-4ebd95","poly":"cardio","fiche":"225","front":"AAA : quelles fistules rares peut-il donner ?","back":"**Aortocave** (IC à débit élevé) ou **aortodigestive** (hémorragie digestive).","prio":"P3","sec":"s13"},{"id":"fc-225-e273ac","poly":"cardio","fiche":"225","front":"Anévrisme poplité : quelles associations rechercher ?","back":"AAA dans **30 %** des cas ; **bilatéral** dans près de la moitié des cas.","prio":"P1","sec":"s13"},{"id":"fc-225-7792b3","poly":"cardio","fiche":"225","front":"Anévrisme poplité : comment peut-il se révéler ?","back":"**Masse battante** du creux poplité, artériopathie progressive, voire **ischémie aiguë**.","prio":"P2","sec":"s13"},{"id":"fc-225-646e69","poly":"cardio","fiche":"225","front":"AAA : quelles complications symptomatiques beaucoup plus rares que la rupture ?","back":"**Embolie** (thrombus intra-anévrismal), **compression** des organes voisins, **syndrome inflammatoire**.","prio":"P3","sec":"s13"},{"id":"fc-225-42e7e9","poly":"cardio","fiche":"225","front":"AAA : chez qui le dépister par échographie ?","back":"Patient **polyathéromateux**, notamment **homme après 65 ans**.","prio":"P1","sec":"s14"},{"id":"fc-225-68303e","poly":"cardio","fiche":"225","front":"AAA : quelle population à risque dépister (détail item 225) ?","back":"**Hommes > 65 ans**, ou plus jeunes avec FDR (tabac, athérome, antécédents familiaux d'anévrisme).","prio":"P3","sec":"s14"},{"id":"fc-225-284edb","poly":"cardio","fiche":"225","front":"AAA : quel examen pour dépister, mesurer et surveiller ?","back":"L'**échographie abdominale** (diamètre maximal ; dépiste aussi poplitées et iliaques).","prio":"P1","sec":"s14"},{"id":"fc-225-d43573","poly":"cardio","fiche":"225","front":"AAA : quel est l'examen préthérapeutique de référence ?","back":"Le **scanner abdominopelvien injecté** (IRM en alternative).","prio":"P1","sec":"s14"},{"id":"fc-225-20c385","poly":"cardio","fiche":"225","front":"AAA : pourquoi l'artériographie n'est-elle pas utile ?","back":"Elle ne voit que la lumière : **pas de mesure fiable** (thrombus mural fréquent).","prio":"P2","sec":"s14"},{"id":"fc-225-47cfa0","poly":"cardio","fiche":"225","front":"AAA asymptomatique : quelle est la priorité de prise en charge ?","back":"La **prévention générale** : rechercher **maladie coronarienne** et **sténose carotidienne**.","prio":"P1","sec":"s15"},{"id":"fc-225-427fdc","poly":"cardio","fiche":"225","front":"AAA : quel est le principal facteur prédictif de rupture ?","back":"Le **diamètre**.","prio":"P2","sec":"s15"},{"id":"fc-225-525f5d","poly":"cardio","fiche":"225","front":"AAA : quelle croissance moyenne ?","back":"**2-4 mm/an**, non linéaire ; **3 fois plus rapide** si le tabagisme continue.","prio":"P3","sec":"s15"},{"id":"fc-225-c91e38","poly":"cardio","fiche":"225","front":"AAA : à partir de quel diamètre surveiller par échographie tous les 6 mois ?","back":"**Au-delà de 45 mm**.","prio":"P2","sec":"s15"},{"id":"fc-225-e2b413","poly":"cardio","fiche":"225","front":"AAA asymptomatique : à partir de quel diamètre intervenir (item 225) ?","back":"**Au-delà de 50-55 mm**, après scanner abdominopelvien.","prio":"P2","sec":"s15"},{"id":"fc-225-114a0d","poly":"cardio","fiche":"225","front":"AAA : quel seuil chirurgical donne l'item 221 ?","back":"**55 mm** (**50 mm chez la femme**) ou croissance **≥ 5 mm/an**.","prio":"P1","sec":"s15"},{"id":"fc-225-1b0bc4","poly":"cardio","fiche":"225","front":"AAA asymptomatique : quelles options de traitement ?","back":"**Chirurgie à ciel ouvert** (mise à plat-greffe) ou **endoprothèse** par voie endovasculaire.","prio":"P2","sec":"s15"},{"id":"fc-225-34e48e","poly":"cardio","fiche":"225","front":"Endoprothèse aortique : par quelle voie et chez qui ?","back":"Par l'**artère fémorale** ; patients à **haut risque chirurgical** si anatomie favorable.","prio":"P3","sec":"s15"},{"id":"fc-225-b10f5e","poly":"cardio","fiche":"225","front":"Douleur abdominale ou lombaire chez un porteur d'AAA : que craindre ?","back":"Une **fissuration ou rupture** : **urgence vitale**.","prio":"P1","sec":"s16"},{"id":"fc-225-ec5a0f","poly":"cardio","fiche":"225","front":"AAA rompu ou fissuré : où adresser le patient ?","back":"**En urgence** dans un **centre spécialisé de chirurgie vasculaire**.","prio":"P1","sec":"s16"},{"id":"fc-225-8c8198","poly":"cardio","fiche":"225","front":"AAA fissuré : quel examen avant le traitement ?","back":"Un **scanner** abdominal (aucune autre imagerie ne doit retarder en cas de choc).","prio":"P1","sec":"s16"},{"id":"fc-225-8e29bc","poly":"cardio","fiche":"225","front":"AAA rompu : quelles options thérapeutiques en urgence ?","back":"**Chirurgie** ou **endoprothèse**.","prio":"P3","sec":"s16"},{"id":"fc-225-3075e6","poly":"cardio","fiche":"225","front":"Rupture intrapéritonéale d'un AAA : quel tableau ?","back":"Tableau habituellement **cataclysmique**, sans possibilité d'intervenir à temps.","prio":"P2","sec":"s16"},{"id":"fc-225-9a37d3","poly":"cardio","fiche":"225","front":"Ischémie aiguë de membre par embolie partie d'un AAA : quel ordre de traitement ?","back":"Revasculariser le membre **en urgence**, la cure de l'AAA vient **ensuite**.","prio":"P3","sec":"s16"},{"id":"fc-225-1f6d94","poly":"cardio","fiche":"225","front":"Après chirurgie conventionnelle d'AAA : que surveiller et comment ?","back":"**Échodoppler** à long terme : **faux anévrismes anastomotiques**.","prio":"P2","sec":"s17"},{"id":"fc-225-b8ede1","poly":"cardio","fiche":"225","front":"Après endoprothèse aortique : quelle complication impose une imagerie au long cours ?","back":"Les **endofuites** (pression persistante dans le sac → évolution, voire rupture).","prio":"P2","sec":"s17"},{"id":"fc-225-ebb6aa","poly":"cardio","fiche":"225","front":"Prothèse artérielle : quelle prévention lors d'un acte à risque bactérien ?","back":"Une **antibioprophylaxie** (risque d'infection de prothèse lors d'une bactériémie).","prio":"P3","sec":"s17"},{"id":"fc-225-e8a18d","poly":"cardio","fiche":"225","front":"Athérome aortique : quels sièges préférentiels ?","back":"**Bifurcation aortique** et **origine de chaque branche**.","prio":"P2","sec":"s18"},{"id":"fc-225-e9e94c","poly":"cardio","fiche":"225","front":"Plaques aortiques : quelle prévalence à 40-55 ans et quel FDR le plus lié ?","back":"**25 %** des hommes, **20 %** des femmes ; FDR le plus lié : le **tabac**.","prio":"P3","sec":"s18"},{"id":"fc-225-b5841c","poly":"cardio","fiche":"225","front":"Athérome aortique : quelle complication peut-il donner ?","back":"Des **embolies** (cerveau, membres, viscères) ; le plus souvent muet.","prio":"P2","sec":"s18"},{"id":"fc-225-87c18d","poly":"cardio","fiche":"225","front":"Calcifications aortiques asymptomatiques : quelle signification ?","back":"**Marqueur de risque cardiovasculaire** (augmente avec leur étendue).","prio":"P2","sec":"s18"},{"id":"fc-225-583952","poly":"cardio","fiche":"225","front":"Sténose athéromateuse d'une artère rénale : quelle conséquence tensionnelle ?","back":"Activation du **SRAA** → **HTA rénovasculaire** (HTA secondaire).","prio":"P2","sec":"s18"},{"id":"fc-225-01fd0b","poly":"cardio","fiche":"225","front":"Ischémie mésentérique chronique : quel symptôme typique ?","back":"**Angor digestif** : douleurs abdominales **après les repas**.","prio":"P1","sec":"s18"},{"id":"fc-225-fefbac","poly":"cardio","fiche":"225","front":"Ischémie mésentérique chronique grave : quel retentissement ?","back":"Altération de l'état général et **amaigrissement** (peur de manger).","prio":"P2","sec":"s18"},{"id":"fc-225-f3eaf7","poly":"cardio","fiche":"225","front":"Ischémie mésentérique chronique : quel examen pour confirmer la sténose ?","back":"**Échodoppler des artères digestives** (ou angioscanner, angio-IRM).","prio":"P3","sec":"s18"},{"id":"fc-225-6df74a","poly":"cardio","fiche":"225","front":"Ischémie mésentérique aiguë : quelle triade évoque le diagnostic ?","back":"Douleur aiguë **pauvre en signes physiques** ; **vidange digestive accélérée** ; indices d'**embolie** (FA).","prio":"P1","sec":"s18"},{"id":"fc-225-7139f0","poly":"cardio","fiche":"225","front":"Ischémie mésentérique aiguë : quelle gravité ?","back":"**Urgence vitale chirurgicale** : pronostic lié à la rapidité de prise en charge.","prio":"P1","sec":"s18"},{"id":"fc-225-1f54d2","poly":"cardio","fiche":"225","front":"Ischémie mésentérique aiguë : quel mécanisme ?","back":"Occlusion **brutale** d'artère(s) digestive(s) par **thrombose in situ ou embolie** ; infarctus rare grâce aux collatérales.","prio":"P2","sec":"s18"},{"id":"fc-226-f8fb89","poly":"cardio","fiche":"226","front":"TVP et EP : quelle relation entre ces deux entités ?","back":"Deux présentations d'une **même maladie** : la **MTEV**, avec les mêmes facteurs favorisants.","prio":"P1","sec":"s1"},{"id":"fc-226-ec5a9c","poly":"cardio","fiche":"226","front":"EP : dans quelle proportion est-elle secondaire à une TVP ?","back":"Dans **70 %** des cas.","prio":"P1","sec":"s1"},{"id":"fc-226-f5b7c9","poly":"cardio","fiche":"226","front":"TVP proximale : quelle définition ?","back":"Atteinte de la veine **poplitée**, fémorale, iliaque ou cave (sus-poplitée).","prio":"P1","sec":"s1"},{"id":"fc-226-b3775c","poly":"cardio","fiche":"226","front":"TVP distale : quelles veines sont concernées ?","back":"Veines **jambières** (tibiales postérieures, fibulaires) et **surales** (soléaires, gastrocnémiennes).","prio":"P1","sec":"s1"},{"id":"fc-226-b04ac9","poly":"cardio","fiche":"226","front":"TVP poplitée : est-elle proximale ou distale ?","back":"**Proximale**.","prio":"P1","sec":"s1"},{"id":"fc-226-419bbd","poly":"cardio","fiche":"226","front":"TVP proximale vs distale : laquelle expose le plus à l'EP ?","back":"La TVP **proximale** (risque d'EP beaucoup plus important).","prio":"P1","sec":"s1"},{"id":"fc-226-c83e43","poly":"cardio","fiche":"226","front":"TVP distale mise en évidence : faut-il l'anticoaguler ?","back":"**Oui**, dès qu'elle est mise en évidence, même si son dépistage et son traitement sont discutés.","prio":"P1","sec":"s1"},{"id":"fc-226-e91778","poly":"cardio","fiche":"226","front":"EP grave ou à haut risque : quelle définition ?","back":"Choc ou hypotension : **PAS < 90 mmHg** ou **baisse > 40 mmHg pendant > 15 min**, hors cause rythmique, hypovolémique ou septique.","prio":"P1","sec":"s1"},{"id":"fc-226-8a3f8c","poly":"cardio","fiche":"226","front":"EP à haut risque : quelle mortalité ?","back":"**> 15 %**.","prio":"P1","sec":"s1"},{"id":"fc-226-7b0c93","poly":"cardio","fiche":"226","front":"TVP : quels sont les buts du traitement ?","back":"Éviter l'**EP** (précoce) et le **syndrome post-thrombotique** (tardif).","prio":"P2","sec":"s1"},{"id":"fc-226-7f472e","poly":"cardio","fiche":"226","front":"EP : quels sont les buts du traitement ?","back":"Baisser **mortalité** et morbidité, le risque de **cœur pulmonaire postembolique** et de **récidive**.","prio":"P2","sec":"s1"},{"id":"fc-226-0cc004","poly":"cardio","fiche":"226","front":"TVP proximale : environ quelle part a une EP asymptomatique visible à l'angioscanner ?","back":"Environ **la moitié**.","prio":"P3","sec":"s1"},{"id":"fc-226-c153a5","poly":"cardio","fiche":"226","front":"TVP distales asymptomatiques postopératoires : quelle part s'étend aux veines proximales ?","back":"Environ **25 %**.","prio":"P2","sec":"s1"},{"id":"fc-226-c4b6b2","poly":"cardio","fiche":"226","front":"TVP distale vs proximale : quel risque de récidive ?","back":"La TVP distale récidive **2 fois moins**.","prio":"P3","sec":"s1"},{"id":"fc-226-0981d0","poly":"cardio","fiche":"226","front":"TVP proximale : quelle part est symptomatique ?","back":"**80 %**, avec forte probabilité d'EP associée.","prio":"P3","sec":"s1"},{"id":"fc-226-25a6c4","poly":"cardio","fiche":"226","front":"EP : quand survient-elle par rapport au début de la TVP ?","back":"Dans les **3 à 7 jours**.","prio":"P2","sec":"s1"},{"id":"fc-226-99f0f4","poly":"cardio","fiche":"226","front":"EP : quelle part tue dans l'heure ?","back":"Près de **10 %**.","prio":"P2","sec":"s1"},{"id":"fc-226-1ae438","poly":"cardio","fiche":"226","front":"EP : quelle fréquence de choc et de dysfonction VD ?","back":"Choc : **5-10 %** des EP ; dysfonction VD : **1 fois sur 2**.","prio":"P3","sec":"s1"},{"id":"fc-226-3fee99","poly":"cardio","fiche":"226","front":"MTEV symptomatique sans anticoagulant : quel risque de récidive à 3 mois ?","back":"**50 %**.","prio":"P1","sec":"s1"},{"id":"fc-226-bc4942","poly":"cardio","fiche":"226","front":"MTEV : quel risque de récidive à 1 an selon qu'elle est provoquée ou non ?","back":"**9 %** si non provoquée ; **3 %** si provoquée.","prio":"P2","sec":"s1"},{"id":"fc-226-763047","poly":"cardio","fiche":"226","front":"Récidive de MTEV : sous quelle forme survient-elle souvent ?","back":"Souvent **sous la même forme** que le 1er épisode (TVP ou EP).","prio":"P3","sec":"s1"},{"id":"fc-226-77ad00","poly":"cardio","fiche":"226","front":"Syndrome post-thrombotique : quand apparaît-il en moyenne ?","back":"Dans les **2 premières années**.","prio":"P3","sec":"s1"},{"id":"fc-226-bc7930","poly":"cardio","fiche":"226","front":"Contention dès la phase initiale d'une TVP : quel effet sur le syndrome post-thrombotique ?","back":"Gardée **au moins 3 mois**, elle divise son risque par **2**.","prio":"P3","sec":"s1"},{"id":"fc-226-6b9625","poly":"cardio","fiche":"226","front":"Triade de Virchow : quels éléments ?","back":"**Stase** veineuse, **lésion** pariétale, **anomalie de l'hémostase**.","prio":"P2","sec":"s1"},{"id":"fc-226-267e4c","poly":"cardio","fiche":"226","front":"EP : à partir de quelle obstruction du lit artériel apparaît le retentissement hémodynamique ?","back":"**30 à 50 %** du lit artériel pulmonaire.","prio":"P3","sec":"s1"},{"id":"fc-226-9f9746","poly":"cardio","fiche":"226","front":"EP grave : quel mécanisme peut aboutir au décès secondaire dans les 24-48 h ?","back":"**Ischémie du VD** (besoins accrus en O₂, perfusion diminuée), ± nouvelles embolies.","prio":"P3","sec":"s1"},{"id":"fc-226-a57d60","poly":"cardio","fiche":"226","front":"EP : quelles conséquences des petites embolies distales ?","back":"**Hémoptysie**, **épanchement pleural**, voire **infarctus pulmonaire** (pas d'effet hémodynamique).","prio":"P3","sec":"s1"},{"id":"fc-226-d3aa1a","poly":"cardio","fiche":"226","front":"MTEV : à quelle question pratique répond le classement des facteurs de risque ?","back":"**Combien de temps traiter** (provoquée ou non).","prio":"P2","sec":"s2"},{"id":"fc-226-49b829","poly":"cardio","fiche":"226","front":"MTEV provoquée vs non provoquée : quelle différence ?","back":"Provoquée : facteur **transitoire** ; non provoquée : facteur **persistant** ou absent (risque de récidive plus élevé).","prio":"P1","sec":"s2"},{"id":"fc-226-b42dc6","poly":"cardio","fiche":"226","front":"Facteurs temporaires majeurs de MTEV (3 derniers mois) : lesquels ?","back":"Chirurgie sous AG **> 30 min**, **fracture** d'un MI, immobilisation **> 3 jours** ; + œstroprogestatifs, grossesse, post-partum, THM.","prio":"P1","sec":"s2"},{"id":"fc-226-2f330a","poly":"cardio","fiche":"226","front":"Facteurs temporaires mineurs de MTEV (2 derniers mois) : lesquels ?","back":"Chirurgie sous AG **< 30 min**, immobilisation **< 3 jours**, traumatisme non plâtré, **voyage > 6 h**.","prio":"P2","sec":"s2"},{"id":"fc-226-ee2f6c","poly":"cardio","fiche":"226","front":"Facteurs permanents de MTEV : lesquels ?","back":"**Cancer actif** ; maladies inflammatoires chroniques **digestives ou articulaires** (Crohn, RCH).","prio":"P1","sec":"s2"},{"id":"fc-226-d7f72d","poly":"cardio","fiche":"226","front":"Après une chirurgie : combien de temps dure le risque de MTEV ?","back":"**Élevé 2 semaines**, reste haut **2 à 3 mois**.","prio":"P2","sec":"s2"},{"id":"fc-226-a962b4","poly":"cardio","fiche":"226","front":"Chirurgies les plus à risque de MTEV : lesquelles ?","back":"**Orthopédie** (prothèse de hanche ou genou, fracture de hanche, plâtre), polytraumatisme, lésion médullaire, chirurgie majeure avec cancer.","prio":"P2","sec":"s2"},{"id":"fc-226-efd508","poly":"cardio","fiche":"226","front":"Thrombophilies constitutionnelles : lesquelles ?","back":"Mutations des **facteurs II et V** ; déficits en **protéine C**, **protéine S**, **antithrombine**.","prio":"P1","sec":"s2"},{"id":"fc-226-06eabb","poly":"cardio","fiche":"226","front":"Thrombophilie acquise : laquelle citer ?","back":"Le **syndrome des antiphospholipides**.","prio":"P2","sec":"s2"},{"id":"fc-226-e423f3","poly":"cardio","fiche":"226","front":"TVP iatrogène : quel matériel en est responsable ?","back":"Les **cathéters veineux profonds**.","prio":"P3","sec":"s2"},{"id":"fc-226-ef2710","poly":"cardio","fiche":"226","front":"TVP provoquée : quelle définition opérationnelle ?","back":"**Chirurgie ou fracture des MI dans les 3 mois**, ou **immobilisation > 3 jours**.","prio":"P1","sec":"s2"},{"id":"fc-226-e96ec1","poly":"cardio","fiche":"226","front":"TVP non provoquée : quelle conséquence diagnostique ?","back":"Un **bilan à visée étiologique** est nécessaire.","prio":"P1","sec":"s2"},{"id":"fc-226-3b21f7","poly":"cardio","fiche":"226","front":"TVP : sur quoi doit reposer le diagnostic ?","back":"Sur une **méthode objective** (la clinique ne fait qu'orienter).","prio":"P1","sec":"s3"},{"id":"fc-226-01fb9e","poly":"cardio","fiche":"226","front":"TVP : quels signes cliniques sont évocateurs ?","back":"Douleur du MI, **œdème unilatéral** (écart > 3 cm), signes inflammatoires, veines superficielles dilatées.","prio":"P1","sec":"s3"},{"id":"fc-226-3976c7","poly":"cardio","fiche":"226","front":"TVP : quel tableau clinique est le plus évocateur ?","back":"La **phlegmatia alba dolens**, typiquement unilatérale ou asymétrique, surtout si installation brutale.","prio":"P2","sec":"s3"},{"id":"fc-226-b925ed","poly":"cardio","fiche":"226","front":"Score de Wells de la TVP : quel item retire des points ?","back":"**Autre diagnostic** au moins aussi probable : **−2**.","prio":"P1","sec":"s3"},{"id":"fc-226-f3fbaa","poly":"cardio","fiche":"226","front":"Score de Wells de la TVP : comment lire le résultat ?","back":"**0** = faible (≈ 3 %) ; **1-2** = intermédiaire (≈ 17 %) ; **≥ 3** = forte (≈ 75 %).","prio":"P1","sec":"s3"},{"id":"fc-226-d4c791","poly":"cardio","fiche":"226","front":"Score de Wells de la TVP : citer des items à +1.","back":"Plâtre/paralysie, chirurgie < 4 sem ou alitement > 3 j, **cancer**, **ATCD de TVP**, mollet > 3 cm, œdème de tout le membre...","prio":"P2","sec":"s3"},{"id":"fc-226-5383be","poly":"cardio","fiche":"226","front":"Score de Wells : chez quels patients est-il valable ?","back":"Patient **hospitalisé comme ambulatoire** ; calculé **avant** tout examen.","prio":"P2","sec":"s3"},{"id":"fc-226-acf1da","poly":"cardio","fiche":"226","front":"D-dimères : quelle technique de dosage préconiser ?","back":"Technique **quantitative, très sensible et validée** (ELISA la plus efficace).","prio":"P2","sec":"s3"},{"id":"fc-226-0efaae","poly":"cardio","fiche":"226","front":"D-dimères ELISA dans la TVP : quelles performances ?","back":"Sensibilité **> 95 %**, VPN **> 95 %** ; seuil **500 µg/L**.","prio":"P1","sec":"s3"},{"id":"fc-226-ef8fc8","poly":"cardio","fiche":"226","front":"D-dimères : quel est leur rôle diagnostique ?","back":"**Éliminer** la TVP (peu spécifiques : positifs → échodoppler).","prio":"P1","sec":"s3"},{"id":"fc-226-cc11b9","poly":"cardio","fiche":"226","front":"D-dimères : quelles situations les élèvent en dehors de la MTEV ?","back":"**Âge**, inflammation, **cancer**, traumatisme, hématome, **postopératoire**, **grossesse**, post-partum.","prio":"P1","sec":"s3"},{"id":"fc-226-ebea45","poly":"cardio","fiche":"226","front":"TVP : quel est l'examen de 1re intention pour confirmer ou éliminer ?","back":"L'**échodoppler veineux** des MI (sensibilité et spécificité **> 95 %**).","prio":"P1","sec":"s3"},{"id":"fc-226-4757ae","poly":"cardio","fiche":"226","front":"Échodoppler veineux : quelle limite principale ?","back":"**Opérateur-dépendant** : appareil adapté et **opérateur expérimenté** requis.","prio":"P2","sec":"s3"},{"id":"fc-226-901ea2","poly":"cardio","fiche":"226","front":"Échodoppler : quels signes affirment une TVP ?","back":"**Thrombus vu directement**, veine **incompressible** sous la sonde, signal doppler diminué ou aboli.","prio":"P1","sec":"s3"},{"id":"fc-226-c58659","poly":"cardio","fiche":"226","front":"Phlébographie dans la TVP : quelle place ?","back":"**N'est plus utilisée**.","prio":"P2","sec":"s3"},{"id":"fc-226-eb44d7","poly":"cardio","fiche":"226","front":"Angioscanner dans la TVP : quand le faire ?","back":"Pour compléter l'échodoppler à l'étage **abdominopelvien** quand il ne conclut pas.","prio":"P3","sec":"s3"},{"id":"fc-226-de41bb","poly":"cardio","fiche":"226","front":"Suspicion de TVP : quand ne pas doser les D-dimères ?","back":"Âge **≥ 80 ans**, **cancer**, ou **chirurgie < 30 jours** : échodoppler directement.","prio":"P1","sec":"s3"},{"id":"fc-226-ee8ccf","poly":"cardio","fiche":"226","front":"Suspicion de TVP avec D-dimères négatifs : que conclure ?","back":"TVP **éliminée** : chercher un autre diagnostic.","prio":"P1","sec":"s3"},{"id":"fc-226-217f4d","poly":"cardio","fiche":"226","front":"Suspicion de TVP : dans quel délai réaliser l'échodoppler ?","back":"Dans les **24-48 h** (en urgence si possible).","prio":"P1","sec":"s3"},{"id":"fc-226-f1e566","poly":"cardio","fiche":"226","front":"Suspicion de TVP en probabilité forte avec échodoppler normal : quelle conduite ?","back":"Surveillance ± anticoagulant curatif et contention ± **nouvel échodoppler à 48 h**.","prio":"P2","sec":"s3"},{"id":"fc-226-11cda4","poly":"cardio","fiche":"226","front":"EP : devant quels symptômes faut-il toujours l'évoquer ?","back":"**Dyspnée** aiguë ou récente, **malaise ou syncope**, **douleur thoracique**.","prio":"P1","sec":"s4"},{"id":"fc-226-61877d","poly":"cardio","fiche":"226","front":"Suspicion d'EP : quels examens d'orientation sont indispensables ?","back":"**Radiographie thoracique**, **gazométrie artérielle**, **ECG**.","prio":"P1","sec":"s4"},{"id":"fc-226-a0235a","poly":"cardio","fiche":"226","front":"EP : quelle douleur thoracique est typique ?","back":"Douleur **pleurale** (point de côté brutal).","prio":"P2","sec":"s4"},{"id":"fc-226-ca333b","poly":"cardio","fiche":"226","front":"EP : que traduit une syncope ?","back":"Une **forte chute du débit systémique** (rare).","prio":"P2","sec":"s4"},{"id":"fc-226-505a0c","poly":"cardio","fiche":"226","front":"EP : quelle part est spontanée (idiopathique) ?","back":"**20 à 30 %**.","prio":"P3","sec":"s4"},{"id":"fc-226-ab7c84","poly":"cardio","fiche":"226","front":"EP : les signes de TVP sont-ils fréquents à l'examen ?","back":"**Non** : absents dans **deux tiers** des cas ; TVP symptomatique < 1 fois sur 4.","prio":"P2","sec":"s4"},{"id":"fc-226-727737","poly":"cardio","fiche":"226","front":"EP : que montre la radiographie thoracique et à quoi sert-elle ?","back":"Anomalies **aspécifiques** ; sert surtout à **éliminer une autre cause** ; **normale, elle n'élimine pas** l'EP.","prio":"P1","sec":"s4"},{"id":"fc-226-2be192","poly":"cardio","fiche":"226","front":"EP : quelle anomalie gazométrique typique ?","back":"**Hypoxémie-hypocapnie** (normale dans **20 %** des cas).","prio":"P1","sec":"s4"},{"id":"fc-226-7baf06","poly":"cardio","fiche":"226","front":"EP : quand faire encore une gazométrie artérielle ?","back":"Si **saturation < 90 %** en air ambiant.","prio":"P3","sec":"s4"},{"id":"fc-226-07a0b9","poly":"cardio","fiche":"226","front":"EP : quels signes ECG de souffrance VD ?","back":"ECG **normal** ou simple **tachycardie sinusale** possibles ; souffrance VD : **S1Q3**, **BBD**, arythmie supraventriculaire, **T négatives de V1 à V4**.","prio":"P1","sec":"s4"},{"id":"fc-226-a5e7c8","poly":"cardio","fiche":"226","front":"EP : quel piège ECG peut faire évoquer un SCA ?","back":"Les **T négatives de V1 à V4** (ischémie du VD).","prio":"P1","sec":"s4"},{"id":"fc-226-773034","poly":"cardio","fiche":"226","front":"Scores de probabilité d'EP : quelles probabilités réelles ?","back":"≈ **10 %** si faible ; **30 %** si modérée ; **65 %** si forte.","prio":"P3","sec":"s4"},{"id":"fc-226-42b43a","poly":"cardio","fiche":"226","front":"Scores de probabilité d'EP : lesquels utiliser ?","back":"**Genève révisé** et **Wells simplifié**.","prio":"P1","sec":"s4"},{"id":"fc-226-990332","poly":"cardio","fiche":"226","front":"Wells simplifié de l'EP : à partir de quel score l'EP est-elle probable ?","back":"**≥ 2** (peu probable : 0-1).","prio":"P2","sec":"s4"},{"id":"fc-226-dc9cd9","poly":"cardio","fiche":"226","front":"Genève révisé : quels seuils en 3 niveaux ?","back":"Faible **0-1** ; intermédiaire **2-4** ; forte **≥ 5**.","prio":"P3","sec":"s4"},{"id":"fc-226-4b2d38","poly":"cardio","fiche":"226","front":"EP : que signifient des D-dimères normaux ?","back":"MTEV **très peu probable** (forte VPN).","prio":"P1","sec":"s5"},{"id":"fc-226-aba85f","poly":"cardio","fiche":"226","front":"EP : quelle spécificité des D-dimères ELISA ?","back":"**40 %** (sensibilité > 95 %).","prio":"P3","sec":"s5"},{"id":"fc-226-8e0276","poly":"cardio","fiche":"226","front":"EP : quel seuil de D-dimères après 50 ans ?","back":"**Âge × 10** µg/L (si probabilité faible ou intermédiaire).","prio":"P1","sec":"s5"},{"id":"fc-226-be6752","poly":"cardio","fiche":"226","front":"Suspicion d'EP en probabilité forte : faut-il doser les D-dimères ?","back":"**Non** : **angioscanner d'emblée**.","prio":"P1","sec":"s5"},{"id":"fc-226-cab89c","poly":"cardio","fiche":"226","front":"EP : quel est l'examen le plus performant ?","back":"L'**angioscanner pulmonaire** multicoupe.","prio":"P1","sec":"s5"},{"id":"fc-226-856cdb","poly":"cardio","fiche":"226","front":"Angioscanner pulmonaire : quelles performances diagnostiques ?","back":"Sensibilité **83 %**, spécificité **> 90 %** (examen le plus performant).","prio":"P2","sec":"s5"},{"id":"fc-226-2334b9","poly":"cardio","fiche":"226","front":"Angioscanner pulmonaire négatif : quand exclut-il l'EP ?","back":"Si la probabilité clinique est **faible ou intermédiaire**.","prio":"P1","sec":"s5"},{"id":"fc-226-e7cff3","poly":"cardio","fiche":"226","front":"Probabilité forte d'EP et angioscanner négatif : quelle conduite ?","back":"Faire un **autre examen** (scintigraphie, voire angiographie) ou pas de traitement.","prio":"P2","sec":"s5"},{"id":"fc-226-e75c47","poly":"cardio","fiche":"226","front":"Angioscanner pulmonaire : quelles contre-indications ?","back":"**Insuffisance rénale**, **allergie à l'iode**.","prio":"P2","sec":"s5"},{"id":"fc-226-0ca99d","poly":"cardio","fiche":"226","front":"Suspicion d'EP : quel résultat d'échodoppler veineux suffit à confirmer l'EP ?","back":"Une **TVP proximale**.","prio":"P1","sec":"s5"},{"id":"fc-226-e90366","poly":"cardio","fiche":"226","front":"Suspicion d'EP : une TVP distale ou un échodoppler normal sont-ils concluants ?","back":"**Non** : TVP distale insuffisante ; échodoppler normal **n'élimine pas** l'EP.","prio":"P1","sec":"s5"},{"id":"fc-226-26e811","poly":"cardio","fiche":"226","front":"Scintigraphie V/Q : quel aspect évoque une EP ?","back":"Défaut de **perfusion** avec **ventilation normale** (mismatch).","prio":"P2","sec":"s5"},{"id":"fc-226-538b92","poly":"cardio","fiche":"226","front":"Scintigraphie V/Q : quand exclut-elle l'EP ?","back":"**Normale** + probabilité clinique **faible**.","prio":"P2","sec":"s5"},{"id":"fc-226-b3e151","poly":"cardio","fiche":"226","front":"ETT dans l'EP : quels signes de cœur pulmonaire aigu ?","back":"**VD dilaté**, **septum paradoxal**, hypokinésie VD, pressions pulmonaires élevées.","prio":"P2","sec":"s5"},{"id":"fc-226-445962","poly":"cardio","fiche":"226","front":"EP en choc sans angioscanner possible : quel rôle de l'ETT ?","back":"Une **surcharge droite peut suffire** pour fibrinoliser ; son absence rend l'EP peu probable.","prio":"P1","sec":"s5"},{"id":"fc-226-15ceeb","poly":"cardio","fiche":"226","front":"Suspicion d'EP sans choc, probabilité faible/intermédiaire : quelle stratégie ?","back":"**D-dimères** : négatifs → pas de traitement ; positifs → **angioscanner**.","prio":"P1","sec":"s5"},{"id":"fc-226-1fc7eb","poly":"cardio","fiche":"226","front":"Suspicion d'EP sans choc : que faire si le scanner est impossible ?","back":"**Échodoppler veineux** (TVP proximale = confirmation) et/ou **scintigraphie V/Q**.","prio":"P2","sec":"s5"},{"id":"fc-226-fc89ae","poly":"cardio","fiche":"226","front":"Suspicion d'EP à haut risque, scanner disponible tout de suite : quelle conduite ?","back":"**Angioscanner** : positif → **thrombolyse ou embolectomie** ; négatif → autre cause.","prio":"P1","sec":"s5"},{"id":"fc-226-d792bd","poly":"cardio","fiche":"226","front":"Suspicion d'EP en choc, patient instable avec dysfonction VD à l'ETT : quelle conduite ?","back":"**Thrombolyse ou embolectomie** d'emblée.","prio":"P1","sec":"s5"},{"id":"fc-226-1eb366","poly":"cardio","fiche":"226","front":"Angiographie pulmonaire : quelle place actuelle ?","back":"**N'est plus pratiquée**.","prio":"P3","sec":"s5"},{"id":"fc-226-5c9f53","poly":"cardio","fiche":"226","front":"EP et grossesse : l'angioscanner est-il contre-indiqué ?","back":"**Non** : l'irradiation n'est plus une contre-indication avec les techniques actuelles.","prio":"P2","sec":"s5"},{"id":"fc-226-5575b7","poly":"cardio","fiche":"226","front":"Suspicion d'EP pendant la grossesse : quel examen habituel ?","back":"L'**échodoppler veineux** (les D-dimères peuvent être **faussement positifs**).","prio":"P2","sec":"s5"},{"id":"fc-226-f1a550","poly":"cardio","fiche":"226","front":"EP : quel ordre de questions pour stratifier la gravité ?","back":"1) **Choc/hypotension** ? 2) **sPESI** et **VD** ? 3) **Troponine** si sPESI ≥ 1 ou VD+.","prio":"P1","sec":"s6"},{"id":"fc-226-86d872","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : quelle définition ?","back":"Pas de choc ; sPESI ≥ 1 ou VD+, avec **troponine positive et VD+**.","prio":"P1","sec":"s6"},{"id":"fc-226-138613","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire faible : quelle définition ?","back":"Pas de choc ; sPESI ≥ 1 ou VD+, **troponine négative**.","prio":"P1","sec":"s6"},{"id":"fc-226-78ebad","poly":"cardio","fiche":"226","front":"EP à faible risque : quelle définition ?","back":"Pas de choc ; **sPESI = 0** et **VD normal**.","prio":"P1","sec":"s6"},{"id":"fc-226-2ed1f7","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire : quelle mortalité ?","back":"**3 à 15 %**.","prio":"P2","sec":"s6"},{"id":"fc-226-baeb22","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : quelle orientation ?","back":"Anticoagulant, **réanimation/USIC**, surveillance ; reperfusion si **détérioration**.","prio":"P1","sec":"s6"},{"id":"fc-226-7f10c0","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire faible : quelle orientation ?","back":"Anticoagulant, **hospitalisation en médecine**.","prio":"P1","sec":"s6"},{"id":"fc-226-962d4a","poly":"cardio","fiche":"226","front":"EP à faible risque : quelle orientation ?","back":"Anticoagulant, **hospitalisation courte ou ambulatoire**.","prio":"P1","sec":"s6"},{"id":"fc-226-1de4fb","poly":"cardio","fiche":"226","front":"sPESI : quels sont les critères (1 point chacun) ?","back":"Âge **> 80 ans**, Sat **< 90 %**, PAS **< 100**, FC **> 110**, **cancer**, **IC ou maladie pulmonaire chronique**.","prio":"P1","sec":"s6"},{"id":"fc-226-f48e40","poly":"cardio","fiche":"226","front":"sPESI : quelle mortalité selon le score ?","back":"**0** → ≈ **1 %** ; **≥ 1** → ≈ **10 %**.","prio":"P2","sec":"s6"},{"id":"fc-226-1800cb","poly":"cardio","fiche":"226","front":"EP : quels marqueurs de dysfonction VD ?","back":"**ETT** (VD dilaté, VD/VG augmenté), **angioscanner** (VD/VG), turgescence jugulaire, ECG.","prio":"P2","sec":"s6"},{"id":"fc-226-cef7d7","poly":"cardio","fiche":"226","front":"EP : quel marqueur biologique d'ischémie du VD ?","back":"La **troponine** T ou I.","prio":"P2","sec":"s6"},{"id":"fc-226-893f7a","poly":"cardio","fiche":"226","front":"EP : que peut montrer l'ETT en plus de la dysfonction VD ?","back":"Un **foramen ovale perméable** (aggrave l'hypoxie) ou un **thrombus** des cavités droites.","prio":"P3","sec":"s6"},{"id":"fc-226-8947f3","poly":"cardio","fiche":"226","front":"EP : quelle est la règle concernant l'hospitalisation ?","back":"**L'hospitalisation reste la règle**.","prio":"P1","sec":"s6"},{"id":"fc-226-d23aea","poly":"cardio","fiche":"226","front":"EP : quand peut-on discuter un traitement ambulatoire ?","back":"**PESI = 0** **et** aucun critère d'hospitalisation de la TVP proximale.","prio":"P1","sec":"s6"},{"id":"fc-226-3eb93a","poly":"cardio","fiche":"226","front":"EP traitée en ambulatoire : quelles conditions ?","back":"**Diagnostic de certitude**, **éducation**, surveillance par **médecin traitant et infirmier**, risques et contexte psychosocial évalués.","prio":"P2","sec":"s6"},{"id":"fc-226-f66f43","poly":"cardio","fiche":"226","front":"Grosse jambe : quels diagnostics différentiels de la TVP ?","back":"Claquage, **kyste synovial**, SPT, insuffisance veineuse, **érysipèle**, lymphangite, lymphœdème, compression, œdème général.","prio":"P2","sec":"s7"},{"id":"fc-226-a85123","poly":"cardio","fiche":"226","front":"Suspicion d'EP avec douleur thoracique : quels diagnostics différentiels ?","back":"**Infarctus**, **péricardite**, **dissection aortique**, **pneumothorax**.","prio":"P2","sec":"s7"},{"id":"fc-226-4542ba","poly":"cardio","fiche":"226","front":"Suspicion d'EP avec dyspnée aiguë : quels diagnostics différentiels ?","back":"**OAP**, crise d'asthme, décompensation de **BPCO**, **pneumopathie**.","prio":"P2","sec":"s7"},{"id":"fc-226-c6a858","poly":"cardio","fiche":"226","front":"Œdème de jambe + D-dimères positifs : le diagnostic de TVP est-il posé ?","back":"**Non** : les D-dimères excluent, l'**imagerie** confirme.","prio":"P1","sec":"s7"},{"id":"fc-226-0be034","poly":"cardio","fiche":"226","front":"MTEV : quand débuter l'anticoagulation avant la confirmation ?","back":"Dès une probabilité **forte ou intermédiaire**, sans risque hémorragique important.","prio":"P1","sec":"s8"},{"id":"fc-226-5ebd2f","poly":"cardio","fiche":"226","front":"MTEV : quel bilan biologique avant le traitement ?","back":"Hémogramme avec **plaquettes**, TP, TCA, fibrinogène, **créatininémie avec DFG**.","prio":"P1","sec":"s8"},{"id":"fc-226-adf4c7","poly":"cardio","fiche":"226","front":"AOD anti-Xa dans la MTEV : quelles molécules et quelles modalités ?","back":"**Rivaroxaban**, **apixaban** : d'emblée, **sans héparine ni relais AVK** ; devenus la **référence**.","prio":"P1","sec":"s8"},{"id":"fc-226-1c52d0","poly":"cardio","fiche":"226","front":"AOD dans la MTEV : quelle contre-indication rénale ?","back":"**DFGe < 30 mL/min**.","prio":"P1","sec":"s8"},{"id":"fc-226-c67a8c","poly":"cardio","fiche":"226","front":"HBPM et fondaparinux : pourquoi les préférer à l'HNF ?","back":"Plus simples, **pas d'adaptation** à un test d'hémostase, **moins de TIH**.","prio":"P2","sec":"s8"},{"id":"fc-226-6b7a8a","poly":"cardio","fiche":"226","front":"HBPM et fondaparinux : quelle contre-indication rénale ?","back":"**DFG < 30 mL/min**.","prio":"P1","sec":"s8"},{"id":"fc-226-7b5594","poly":"cardio","fiche":"226","front":"EP : quelles HBPM ont l'AMM en France ?","back":"**Énoxaparine** et **tinzaparine** seulement.","prio":"P2","sec":"s8"},{"id":"fc-226-e29fe6","poly":"cardio","fiche":"226","front":"MTEV : dans quelles situations l'HNF est-elle recommandée ?","back":"**IR sévère** (< 30 mL/min), patient **instable**, **geste** prévisible, patient **fibrinolysé**, risque hémorragique.","prio":"P1","sec":"s8"},{"id":"fc-226-065854","poly":"cardio","fiche":"226","front":"MTEV sans insuffisance rénale : quelles options anticoagulantes ?","back":"**HBPM + relais AVK immédiat** (chevauchement ≥ 5 j), **ou AOD anti-Xa d'emblée**.","prio":"P1","sec":"s8"},{"id":"fc-226-a0decc","poly":"cardio","fiche":"226","front":"HNF : quand contrôler le TCA ou l'anti-Xa en IV continue ?","back":"**4 h** après le début, puis 4 h après chaque changement de dose.","prio":"P2","sec":"s8"},{"id":"fc-226-1b3a5f","poly":"cardio","fiche":"226","front":"HNF : quelle surveillance des plaquettes ?","back":"**Avant**, puis **2 fois/semaine pendant 21 jours**.","prio":"P1","sec":"s8"},{"id":"fc-226-d624ca","poly":"cardio","fiche":"226","front":"HBPM : quand surveiller les plaquettes ?","back":"Non systématique, sauf : après une **HNF**, MTEV **postopératoire**, nouvel épisode thrombotique, lésion cutanée au point d'injection.","prio":"P2","sec":"s8"},{"id":"fc-226-7575e9","poly":"cardio","fiche":"226","front":"HBPM : quand doser l'anti-Xa ?","back":"Si risque d'accumulation ou de saignement : **IR modérée**, âge élevé, petit poids, obésité.","prio":"P3","sec":"s8"},{"id":"fc-226-57028b","poly":"cardio","fiche":"226","front":"AVK : à quel rythme contrôler l'INR ?","back":"**2 à 3 fois/semaine** à l'initiation, puis toutes les **3 à 4 semaines**.","prio":"P2","sec":"s8"},{"id":"fc-226-c3ad17","poly":"cardio","fiche":"226","front":"TIH : quelle définition biologique ?","back":"Plaquettes **< 150 G/L** ou **baisse de 50 %** par rapport à la valeur avant traitement.","prio":"P1","sec":"s8"},{"id":"fc-226-8bf611","poly":"cardio","fiche":"226","front":"Relais héparine-AVK dans la MTEV : quand débuter l'AVK ?","back":"**Dès le 1er jour** de l'injectable.","prio":"P1","sec":"s8"},{"id":"fc-226-9dea2c","poly":"cardio","fiche":"226","front":"Relais AVK dans la MTEV : quelles doses initiales ?","back":"**Warfarine 5 mg** ou **acénocoumarol 4 mg** (moins chez le sujet âgé).","prio":"P2","sec":"s8"},{"id":"fc-226-9d7c98","poly":"cardio","fiche":"226","front":"Fluindione : peut-on l'initier ?","back":"**Non** : initiation déconseillée (risque d'atteinte rénale **immunoallergique**).","prio":"P2","sec":"s8"},{"id":"fc-226-ccf764","poly":"cardio","fiche":"226","front":"Relais héparine-AVK : quand arrêter l'injectable ?","back":"Après **au moins 5 jours** **et** **2 INR consécutifs > 2** à 24 h d'intervalle.","prio":"P1","sec":"s8"},{"id":"fc-226-c26582","poly":"cardio","fiche":"226","front":"AVK dans la MTEV : quelle INR cible ?","back":"**2,5** (entre **2 et 3**).","prio":"P1","sec":"s8"},{"id":"fc-226-7c3d3d","poly":"cardio","fiche":"226","front":"Compression élastique d'une TVP : quelle classe et quelle pression ?","back":"**Classe 3** : **30 à 40 mmHg** à la cheville.","prio":"P1","sec":"s8"},{"id":"fc-226-32de5d","poly":"cardio","fiche":"226","front":"Compression élastique d'une TVP : quelle durée ?","back":"**Au moins 6 mois** (texte) ; **2 ans** selon les points clés ; plus si symptômes.","prio":"P2","sec":"s8"},{"id":"fc-226-8657c5","poly":"cardio","fiche":"226","front":"Compression veineuse : quelles contre-indications ?","back":"**AOMI avec IPS < 0,6**, microangiopathie diabétique (> 30 mmHg), **phlegmatia caerulea**, **thrombose septique**.","prio":"P1","sec":"s8"},{"id":"fc-226-34e84f","poly":"cardio","fiche":"226","front":"MTEV : faut-il aliter le patient ?","back":"**Non** : lever précoce ; dans l'EP, après **24 h d'anticoagulation efficace**, avec contention.","prio":"P1","sec":"s8"},{"id":"fc-226-2ff113","poly":"cardio","fiche":"226","front":"Suspicion de TVP en probabilité intermédiaire ou forte : quel traitement avant l'échodoppler ?","back":"**Contention + HBPM ou fondaparinux à dose curative**, sans risque hémorragique important.","prio":"P1","sec":"s9"},{"id":"fc-226-8da98f","poly":"cardio","fiche":"226","front":"Suspicion de TVP en probabilité faible : quel traitement avant l'échodoppler ?","back":"**Contention seule** (pas d'anticoagulant).","prio":"P1","sec":"s9"},{"id":"fc-226-a41d52","poly":"cardio","fiche":"226","front":"TVP proximale : quels critères imposent l'hospitalisation ?","back":"Clairance **< 30 mL/min**, pathologie à **risque hémorragique**, **syndrome obstructif sévère** ou TVP **iliocave**, contexte inadapté.","prio":"P1","sec":"s9"},{"id":"fc-226-9388ed","poly":"cardio","fiche":"226","front":"TVP proximale sans critère d'hospitalisation : où traiter ?","back":"En **ambulatoire** (HBPM ou AOD) ou après courte hospitalisation.","prio":"P2","sec":"s9"},{"id":"fc-226-8c351d","poly":"cardio","fiche":"226","front":"TVP proximale : quand discuter une thrombolyse ?","back":"Pas en 1re intention, sauf **syndrome obstructif sévère** ou **phlegmatia caerulea** (sauver le membre).","prio":"P2","sec":"s9"},{"id":"fc-226-0a5533","poly":"cardio","fiche":"226","front":"Rivaroxaban dans la MTEV : quelle posologie ?","back":"**15 mg × 2/j pendant 21 jours**, puis **20 mg × 1/j**.","prio":"P1","sec":"s9"},{"id":"fc-226-ca4779","poly":"cardio","fiche":"226","front":"Apixaban dans la MTEV : quelle posologie ?","back":"**10 mg × 2/j pendant 7 jours**, puis **5 mg × 2/j**.","prio":"P1","sec":"s9"},{"id":"fc-226-c07d55","poly":"cardio","fiche":"226","front":"Énoxaparine curative : quelle posologie ?","back":"**100 UI/kg/12 h** SC (1 mg/kg/12 h).","prio":"P1","sec":"s9"},{"id":"fc-226-d05791","poly":"cardio","fiche":"226","front":"Tinzaparine curative : quelle posologie ?","back":"**175 UI/kg/24 h** SC.","prio":"P1","sec":"s9"},{"id":"fc-226-8e68f5","poly":"cardio","fiche":"226","front":"Fondaparinux curatif : quelle posologie ?","back":"**7,5 mg/24 h** SC pour un poids de 50 à 100 kg.","prio":"P2","sec":"s9"},{"id":"fc-226-ebefce","poly":"cardio","fiche":"226","front":"HNF dans la MTEV : quelle posologie ?","back":"**500 UI/kg/j**, SC ou IV continue, adaptée au TCA ou à l'anti-Xa.","prio":"P2","sec":"s9"},{"id":"fc-226-cadebc","poly":"cardio","fiche":"226","front":"Nadroparine curative : quelles posologies ?","back":"**85 UI/kg/12 h** (Fraxiparine®) ou **171 UI/kg/24 h** (Fraxodi®).","prio":"P3","sec":"s9"},{"id":"fc-226-c0afc0","poly":"cardio","fiche":"226","front":"TVP sous anticoagulant : quand refaire un échodoppler ?","back":"**En fin de traitement** (séquelles) ; pas d'imagerie pendant le traitement.","prio":"P2","sec":"s9"},{"id":"fc-226-b9d5ee","poly":"cardio","fiche":"226","front":"TVP distale symptomatique : quel est le traitement de référence ?","back":"Un **AOD** à dose curative.","prio":"P1","sec":"s10"},{"id":"fc-226-b0c693","poly":"cardio","fiche":"226","front":"TVP distale, 1er épisode avec facteur déclenchant évident : quelle durée ?","back":"**6 semaines**.","prio":"P1","sec":"s10"},{"id":"fc-226-61f368","poly":"cardio","fiche":"226","front":"TVP distale idiopathique, récidivante, avec facteur persistant ou cancer : quelle durée ?","back":"**Au moins 3 mois**.","prio":"P1","sec":"s10"},{"id":"fc-226-380dd3","poly":"cardio","fiche":"226","front":"TVP distale étendue des veines tibiales postérieures ou fibulaires : quelle durée de contention ?","back":"**Au moins 2 ans** (plus si symptômes).","prio":"P2","sec":"s10"},{"id":"fc-226-8cb23e","poly":"cardio","fiche":"226","front":"TVP distale : où la traiter ?","back":"En **ambulatoire** sauf cas particulier, avec lever précoce.","prio":"P2","sec":"s10"},{"id":"fc-226-465cda","poly":"cardio","fiche":"226","front":"HBPM pour une MTEV postopératoire : quelle surveillance particulière ?","back":"Surveiller les **plaquettes** (exception à la règle).","prio":"P2","sec":"s10"},{"id":"fc-226-b5904c","poly":"cardio","fiche":"226","front":"EP à faible risque : quelle mortalité ?","back":"Environ **1 %**.","prio":"P2","sec":"s11"},{"id":"fc-226-d25ab0","poly":"cardio","fiche":"226","front":"EP traitée sous héparine en ambulatoire : de quoi informer le patient ?","back":"Des **signes de TIH**.","prio":"P3","sec":"s11"},{"id":"fc-226-54ba1e","poly":"cardio","fiche":"226","front":"EP à faible risque ou intermédiaire faible : quels anticoagulants ?","back":"**AOD anti-Xa**, ou **énoxaparine/tinzaparine/fondaparinux** avec relais AVK.","prio":"P2","sec":"s11"},{"id":"fc-226-6e2355","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : faut-il fibrinolyser ?","back":"**Non systématiquement** : reperfusion **si détérioration**.","prio":"P1","sec":"s12"},{"id":"fc-226-e643bb","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : quels traitements complémentaires ?","back":"**Oxygène** (voire ventilation), **remplissage et/ou inotropes**, monitorage.","prio":"P2","sec":"s12"},{"id":"fc-226-467f16","poly":"cardio","fiche":"226","front":"EP à haut risque : quel traitement de reperfusion ?","back":"**Fibrinolyse** en l'absence de contre-indication, en réanimation/USIC.","prio":"P1","sec":"s12"},{"id":"fc-226-6d6353","poly":"cardio","fiche":"226","front":"EP à haut risque avec fibrinolyse contre-indiquée ou en échec : quelle option ?","back":"**Embolectomie** chirurgicale en urgence (sous CEC).","prio":"P1","sec":"s12"},{"id":"fc-226-a243c1","poly":"cardio","fiche":"226","front":"EP à haut risque : quel anticoagulant utiliser ?","back":"L'**HNF** (patient instable, fibrinolyse).","prio":"P1","sec":"s12"},{"id":"fc-226-db8d71","poly":"cardio","fiche":"226","front":"Après embolectomie pour EP massive : quel dispositif est suggéré ?","back":"Un **filtre cave**.","prio":"P2","sec":"s12"},{"id":"fc-226-7d56c8","poly":"cardio","fiche":"226","front":"EP grave avec choc : quelle durée d'anticoagulation ?","back":"**Plus de 6 mois, voire au long cours** (1re EP à haut risque non provoquée : non limitée).","prio":"P3","sec":"s12"},{"id":"fc-226-c0b031","poly":"cardio","fiche":"226","front":"HTAP pendant une EP : quel contrôle ?","back":"**ETT-doppler** pour vérifier que la PAP baisse.","prio":"P2","sec":"s12"},{"id":"fc-226-a6ea52","poly":"cardio","fiche":"226","front":"MTEV avec clairance < 30 mL/min : quel anticoagulant ?","back":"L'**HNF**, avec relais AVK dès J1.","prio":"P1","sec":"s13"},{"id":"fc-226-d9c37a","poly":"cardio","fiche":"226","front":"Filtre cave : quelles indications ?","back":"**CI aux anticoagulants** ; **récidive sous traitement bien conduit** ; suites d'**embolectomie** pour EP massive.","prio":"P1","sec":"s13"},{"id":"fc-226-cea0bd","poly":"cardio","fiche":"226","front":"Contre-indication provisoire aux anticoagulants : quel filtre cave ?","back":"Un filtre **temporaire**, à **retirer** dès que la CI disparaît.","prio":"P1","sec":"s13"},{"id":"fc-226-db82d2","poly":"cardio","fiche":"226","front":"Filtre cave laissé en place : quel risque ?","back":"Risque **augmenté de récidive thrombotique**.","prio":"P2","sec":"s13"},{"id":"fc-226-e9a995","poly":"cardio","fiche":"226","front":"Filtre cave permanent : quelle conséquence sur la durée d'anticoagulation ?","back":"Facteur majeur persistant : **plus de 6 mois, voire au long cours**.","prio":"P3","sec":"s13"},{"id":"fc-226-a0fb6e","poly":"cardio","fiche":"226","front":"TVP proximale ou EP : quelle durée minimale d'anticoagulation ?","back":"**3 mois**.","prio":"P2","sec":"s14"},{"id":"fc-226-f85d9a","poly":"cardio","fiche":"226","front":"TVP proximale ou EP avec facteur transitoire majeur : quelle durée ?","back":"**3 mois**.","prio":"P2","sec":"s14"},{"id":"fc-226-986146","poly":"cardio","fiche":"226","front":"TVP proximale ou EP sans facteur transitoire majeur : quelle durée ?","back":"**6 mois**.","prio":"P2","sec":"s14"},{"id":"fc-226-343e10","poly":"cardio","fiche":"226","front":"MTEV avec facteur majeur persistant ou récidive proximale : quelle durée ?","back":"**Plus de 6 mois**, voire **au long cours**.","prio":"P2","sec":"s14"},{"id":"fc-226-f2036b","poly":"cardio","fiche":"226","front":"MTEV avec cancer : quelle durée d'anticoagulation ?","back":"**Tant que le cancer est actif**.","prio":"P2","sec":"s14"},{"id":"fc-226-44a691","poly":"cardio","fiche":"226","front":"TVP proximale ou EP récidivantes, ou HTP postembolique : quelle durée ?","back":"**Au long cours** (non limitée).","prio":"P2","sec":"s14"},{"id":"fc-226-475b4a","poly":"cardio","fiche":"226","front":"MTEV et SAPL ou HTP-TEC : quel anticoagulant au long cours ?","back":"**AVK (INR 2-3)**, pas d'AOD.","prio":"P2","sec":"s14"},{"id":"fc-226-4a1f3e","poly":"cardio","fiche":"226","front":"Score HERDOO2 : à quoi sert-il ?","back":"Évaluer le **risque de récidive chez la femme** après un 1er épisode non provoqué.","prio":"P3","sec":"s14"},{"id":"fc-226-78e43e","poly":"cardio","fiche":"226","front":"Homme, 1er épisode de MTEV non provoqué sans facteur persistant majeur : quelle durée ?","back":"Risque de récidive **modéré** : **6 mois ou durée non limitée**.","prio":"P3","sec":"s14"},{"id":"fc-226-c115ca","poly":"cardio","fiche":"226","front":"Risque de récidive modéré : quels arguments pour une durée non limitée ?","back":"Facteur persistant mineur, **filtre cave non retirable**, présentation en **EP**, choix du patient.","prio":"P3","sec":"s14"},{"id":"fc-226-6d6a1e","poly":"cardio","fiche":"226","front":"Risque hémorragique élevé : comment adapter la durée d'anticoagulation ?","back":"3-6 mois → **3 mois** ; durée non limitée → **6 mois**, voire 3.","prio":"P3","sec":"s14"},{"id":"fc-226-544e3d","poly":"cardio","fiche":"226","front":"Avant d'arrêter l'anticoagulation après une EP : que faut-il éliminer ?","back":"Une **HTP postembolique**.","prio":"P2","sec":"s14"},{"id":"fc-226-e0be6c","poly":"cardio","fiche":"226","front":"Durée d'anticoagulation : quel élément non médical peut entrer dans la décision ?","back":"La **préférence du patient**.","prio":"P2","sec":"s14"},{"id":"fc-226-1a068a","poly":"cardio","fiche":"226","front":"MTEV sous contraception œstroprogestative : quelle conduite ?","back":"**Arrêt** (devient **contre-indiquée**) ; remplacer par **progestatif continu** ou **DIU**.","prio":"P1","sec":"s15"},{"id":"fc-226-762456","poly":"cardio","fiche":"226","front":"MTEV chez une femme ménopausée sous THM : quelle conduite ?","back":"Le **THM** est **contre-indiqué**.","prio":"P1","sec":"s15"},{"id":"fc-226-01c0e9","poly":"cardio","fiche":"226","front":"MTEV pendant la grossesse : quel anticoagulant ?","back":"Les **HBPM**.","prio":"P1","sec":"s15"},{"id":"fc-226-e70fc4","poly":"cardio","fiche":"226","front":"MTEV liée aux œstroprogestatifs, à la grossesse ou au THM oral : quelle durée ?","back":"Facteurs transitoires majeurs : **3 mois**.","prio":"P3","sec":"s15"},{"id":"fc-226-0ad482","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : est-il systématique après un 1er épisode de MTEV ?","back":"**Non** ; non recommandé non plus après un 1er épisode **après 50 ans**.","prio":"P2","sec":"s16"},{"id":"fc-226-a6de5f","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : quelles indications ?","back":"1er épisode non provoqué **< 50 ans** avec ATCD familial au 1er degré ; MTEV **récidivante** ; site **atypique**.","prio":"P2","sec":"s16"},{"id":"fc-226-e143eb","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : quels sites de thrombose atypiques le justifient ?","back":"**Splanchnique**, **membre supérieur**, **cérébral** (thrombose non provoquée).","prio":"P3","sec":"s16"},{"id":"fc-226-074a02","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : que doser ?","back":"**Antithrombine**, **protéines C et S** ; mutations **facteur V Leiden** et **facteur II G20210A**.","prio":"P2","sec":"s16"},{"id":"fc-226-ac80c5","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : quand le réaliser ?","back":"**Entre le 3e et le 6e mois**, et **72 h après l'arrêt d'un AOD** (pas en phase aiguë).","prio":"P2","sec":"s16"},{"id":"fc-226-d6d19e","poly":"cardio","fiche":"226","front":"MTEV : quelle incidence de cancer découvert ?","back":"**6 à 28 %**, surtout dans les **6 à 12 premiers mois**, et si TVP idiopathique ou récidivante.","prio":"P3","sec":"s16"},{"id":"fc-226-1f7186","poly":"cardio","fiche":"226","front":"Recherche d'un cancer après MTEV : quels examens chez l'homme et chez la femme ?","back":"Homme : **PSA** ; femme : examen gynéco, **mammographie**, écho pelvienne ; tous : sang dans les selles, **radio de thorax**.","prio":"P2","sec":"s16"},{"id":"fc-226-ea59ca","poly":"cardio","fiche":"226","front":"Recherche de cancer après MTEV : endoscopies et body-scanner sont-ils systématiques ?","back":"**Non** : seulement s'il y a des signes d'orientation.","prio":"P2","sec":"s16"},{"id":"fc-226-d185f6","poly":"cardio","fiche":"226","front":"Recherche de cancer après MTEV : chez qui surtout ?","back":"**Après 40 ans** ou si le bilan de thrombophilie est négatif ; surveillance clinique **au moins 1 an**.","prio":"P3","sec":"s16"},{"id":"fc-226-54ebfa","poly":"cardio","fiche":"226","front":"MTEV et cancer actif : pourquoi préférer l'HBPM aux AVK ?","back":"AVK **moins efficaces et moins bien tolérés** ; HBPM prolongée : moins de récidives.","prio":"P2","sec":"s17"},{"id":"fc-226-16badf","poly":"cardio","fiche":"226","front":"MTEV et cancer : quand éviter les AOD en 1re intention ?","back":"Cancers **digestifs** et **génito-urinaires** (risque de saignement).","prio":"P2","sec":"s17"},{"id":"fc-226-f27d22","poly":"cardio","fiche":"226","front":"MTEV et cancer : quelles doses d'HBPM ?","back":"**Daltéparine 200 UI/kg/j** 1 mois puis 150 ; **tinzaparine 175 UI/kg/j** ; **énoxaparine 150 UI/kg/j**.","prio":"P3","sec":"s17"},{"id":"fc-226-94987c","poly":"cardio","fiche":"226","front":"MTEV et cancer : quelle durée idéale d'HBPM ?","back":"**3 à 6 mois** ; au-delà, HBPM si cancer traité, sinon **relais AVK**.","prio":"P3","sec":"s17"},{"id":"fc-226-f3f7ce","poly":"cardio","fiche":"226","front":"MTEV et cancer sous HBPM : quand interrompre l'HBPM ?","back":"Thrombopénie post-chimiothérapie **< 50 G/L** (reprise au-dessus).","prio":"P3","sec":"s17"},{"id":"fc-226-b430bb","poly":"cardio","fiche":"226","front":"TVP du membre supérieur : quelle cause la plus fréquente ?","back":"Du **matériel** (cathéter central, sonde de pacemaker).","prio":"P2","sec":"s17"},{"id":"fc-226-5581bf","poly":"cardio","fiche":"226","front":"TVP du membre supérieur : comment la traiter ?","back":"Comme une **TVP des membres inférieurs** (mêmes molécules, doses, surveillance).","prio":"P3","sec":"s17"},{"id":"fc-226-3421b0","poly":"cardio","fiche":"226","front":"Thrombose veineuse superficielle : quel siège habituel et quels signes ?","back":"**Grande veine saphène** ; douleur, rougeur, **cordon induré**.","prio":"P2","sec":"s18"},{"id":"fc-226-14f769","poly":"cardio","fiche":"226","front":"TVS : pourquoi faire un échodoppler ?","back":"Chercher une extension profonde : **TVP associée dans 10 %** des cas.","prio":"P2","sec":"s18"},{"id":"fc-226-5f4778","poly":"cardio","fiche":"226","front":"TVS sur veine saine non variqueuse : que rechercher ?","back":"Une **cause générale** : cancer, Buerger, Behçet, hémopathie, maladie auto-immune, thrombophilie.","prio":"P2","sec":"s18"},{"id":"fc-226-86e838","poly":"cardio","fiche":"226","front":"TVS atteignant la jonction grande saphène-veine fémorale : quel traitement ?","back":"**Anticoagulant à dose curative** ou **chirurgie**.","prio":"P2","sec":"s18"},{"id":"fc-226-153270","poly":"cardio","fiche":"226","front":"TVS sans atteinte de la jonction saphéno-fémorale : quel traitement anticoagulant ?","back":"**Fondaparinux** (ou HBPM) à dose **prophylactique**, **6 semaines** pour le fondaparinux.","prio":"P2","sec":"s18"},{"id":"fc-226-1043a7","poly":"cardio","fiche":"226","front":"TVS : quels traitements ne sont pas recommandés en 1re intention ?","back":"**AINS par voie générale**, anticoagulant **curatif**, chirurgie sans atteinte de la jonction.","prio":"P3","sec":"s18"},{"id":"fc-226-c43d89","poly":"cardio","fiche":"226","front":"TVS : quelle compression à la phase aiguë ?","back":"Compression veineuse, de préférence par **bandage**.","prio":"P3","sec":"s18"},{"id":"fc-226-e9b201","poly":"cardio","fiche":"226","front":"TVS : si un anticoagulant est instauré, quelle durée ?","back":"**7 à 30 jours** (seules durées évaluées).","prio":"P2","sec":"s18"},{"id":"fc-226-09cfdb","poly":"cardio","fiche":"226","front":"EP : quelle complication précoce mortelle ?","back":"Le **choc cardiogénique réfractaire**.","prio":"P1","sec":"s19"},{"id":"fc-226-ec0e18","poly":"cardio","fiche":"226","front":"EP : quelle complication à moyen terme rare mais grave ?","back":"L'**HTP chronique postembolique**.","prio":"P2","sec":"s19"},{"id":"fc-226-859f69","poly":"cardio","fiche":"226","front":"TVP : quelles complications ?","back":"**Récidive**, **syndrome post-thrombotique**, **EP**.","prio":"P2","sec":"s19"},{"id":"fc-226-6c08a3","poly":"cardio","fiche":"226","front":"Après une MTEV : que faire à chaque nouvelle situation à risque ?","back":"**Reprendre la prévention** : la récidive reste toujours possible, surtout si le facteur favorisant est permanent.","prio":"P2","sec":"s19"},{"id":"fc-226-08d384","poly":"cardio","fiche":"226","front":"Syndrome post-thrombotique : quels signes ?","back":"Lourdeur de jambe, **dilatation des veines superficielles**, **œdème** de cheville, dermite ocre, atrophie blanche, **ulcère sus-malléolaire**.","prio":"P3","sec":"s19"},{"id":"fc-226-c85c56","poly":"cardio","fiche":"226","front":"Syndrome post-thrombotique : quel examen de choix ?","back":"L'**échodoppler veineux** (obstruction, reflux).","prio":"P3","sec":"s19"},{"id":"fc-226-4b3bef","poly":"cardio","fiche":"226","front":"HTP chronique postembolique : quel traitement de choix ?","back":"L'**endartériectomie pulmonaire** (équipes entraînées).","prio":"P3","sec":"s19"},{"id":"fc-226-2b2f45","poly":"cardio","fiche":"226","front":"Endartériectomie vs embolectomie pulmonaire : quelle différence d'indication ?","back":"Endartériectomie : **HTP chronique postembolique** ; embolectomie : **EP aiguë grave** en urgence.","prio":"P3","sec":"s19"},{"id":"fc-226-40dc68","poly":"cardio","fiche":"226","front":"MTEV sous anticoagulant : faut-il une imagerie de suivi pendant le traitement ?","back":"**Non**, sauf HTAP au cours de l'EP (ETT-doppler).","prio":"P1","sec":"s19"},{"id":"fc-226-daf6b7","poly":"cardio","fiche":"226","front":"Prévention de la MTEV : sur quoi s'adapte-t-elle ?","back":"Sur le **risque thrombotique**, le **risque hémorragique** et la **fonction rénale**.","prio":"P1","sec":"s20"},{"id":"fc-226-ef0030","poly":"cardio","fiche":"226","front":"Prévention de la MTEV avec risque hémorragique élevé : quelle mesure ?","back":"**Compression seule** (+ mobilisation précoce).","prio":"P1","sec":"s20"},{"id":"fc-226-79fe4b","poly":"cardio","fiche":"226","front":"Prévention de la MTEV : l'aspirine est-elle indiquée ?","back":"**Non**.","prio":"P1","sec":"s20"},{"id":"fc-226-b1fec5","poly":"cardio","fiche":"226","front":"Voyage de plus de 6 h : quelle prévention pour tous ?","back":"Pas de vêtements serrés, bonne **hydratation**, contraction régulière des **mollets**.","prio":"P2","sec":"s20"},{"id":"fc-226-8a5098","poly":"cardio","fiche":"226","front":"Voyage de plus de 6 h avec facteurs prédisposants : quelle prévention ?","back":"Chaussettes de contention **classe 2 ou 3** ± une injection d'**HBPM avant le départ**.","prio":"P2","sec":"s20"},{"id":"fc-226-753444","poly":"cardio","fiche":"226","front":"Prévention de la MTEV en médecine : quelles posologies ?","back":"**Énoxaparine 0,4 mL/24 h SC** ou **fondaparinux 2,5 mg/24 h**.","prio":"P1","sec":"s20"},{"id":"fc-226-837fc4","poly":"cardio","fiche":"226","front":"Prévention de la MTEV après prothèse de hanche : quelle durée ?","back":"**4 à 6 semaines**.","prio":"P1","sec":"s20"},{"id":"fc-226-0be05e","poly":"cardio","fiche":"226","front":"Prévention de la MTEV après prothèse de genou : quelle durée ?","back":"**10-15 jours**.","prio":"P1","sec":"s20"},{"id":"fc-226-bfcb5f","poly":"cardio","fiche":"226","front":"Énoxaparine préventive (points clés) : quelles doses selon le risque ?","back":"**2 000 UI/j** si risque modéré ; **4 000 UI/j** si risque élevé.","prio":"P2","sec":"s20"},{"id":"fc-230-6d0c03","poly":"cardio","fiche":"230","front":"Douleur thoracique aiguë : quelle est la première question à se poser ?","back":"Le patient est-il en **détresse vitale** ? (la description de la douleur passe au second plan).","prio":"P1","sec":"s1"},{"id":"fc-230-7caeaa","poly":"cardio","fiche":"230","front":"Douleur thoracique aiguë : quelles sont les 4 urgences cardiovasculaires à évoquer ?","back":"**PIED** : **P**éricardite, **I**nfarctus (SCA), **E**mbolie pulmonaire, **D**issection aortique.","prio":"P1","sec":"s1"},{"id":"fc-230-af10f9","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelle cause digestive exceptionnelle est une urgence thérapeutique ?","back":"La **rupture de l'œsophage**.","prio":"P1","sec":"s1"},{"id":"fc-230-dcf411","poly":"cardio","fiche":"230","front":"Rupture de l'œsophage : quels signes l'évoquent ?","back":"Douleur + **dyspnée**, **emphysème sous-cutané** (crépitation neigeuse), **pneumomédiastin**.","prio":"P1","sec":"s1"},{"id":"fc-230-f9feb9","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle complication grave redouter ?","back":"Un épanchement abondant avec **tamponnade**.","prio":"P2","sec":"s1"},{"id":"fc-230-fd81ed","poly":"cardio","fiche":"230","front":"Douleur thoracique : qu'est-ce qui pèse souvent plus lourd que les détails de la douleur ?","back":"Le **terrain**, l'**âge**, le **contexte** et un **examen soigneux**.","prio":"P2","sec":"s1"},{"id":"fc-230-feb190","poly":"cardio","fiche":"230","front":"Douleur thoracique : quels signes de détresse vitale chercher d'emblée ?","back":"**Collapsus/choc**, **détresse respiratoire**, **signes neurologiques**.","prio":"P1","sec":"s2"},{"id":"fc-230-56f121","poly":"cardio","fiche":"230","front":"Douleur thoracique avec détresse vitale : quelle orientation ?","back":"**Réanimation ou Usic**, **via le Samu**.","prio":"P1","sec":"s2"},{"id":"fc-230-815466","poly":"cardio","fiche":"230","front":"Détresse respiratoire : quels signes ?","back":"Polypnée **> 30/min** ou bradypnée **< 10/min**, **tirage**, sueurs, cyanose, **SpO₂ < 90 %**, encéphalopathie.","prio":"P1","sec":"s2"},{"id":"fc-230-c3bf85","poly":"cardio","fiche":"230","front":"Détresse hémodynamique : quels signes ?","back":"**Arrêt circulatoire**, **état de choc** (hypotension, marbrures, oligurie), cœur pulmonaire, **pouls paradoxal**.","prio":"P1","sec":"s2"},{"id":"fc-230-1ab225","poly":"cardio","fiche":"230","front":"Pouls paradoxal : quelle définition ?","back":"Pouls qui **diminue à l'inspiration** profonde.","prio":"P2","sec":"s2"},{"id":"fc-230-22e264","poly":"cardio","fiche":"230","front":"Arrêt circulatoire : quels signes ?","back":"Patient **inconscient**, pouls **carotidien ou fémoral non perçu**.","prio":"P1","sec":"s2"},{"id":"fc-230-9a8a94","poly":"cardio","fiche":"230","front":"Patient avec douleur thoracique : comment organiser le transfert ?","back":"**Médicalisé, via le 15**.","prio":"P1","sec":"s2"},{"id":"fc-230-4e24c8","poly":"cardio","fiche":"230","front":"Douleur thoracique : pourquoi ne pas appeler le 15 est-il une faute grave ?","back":"Si SCA : **mortalité préhospitalière élevée** (risque de **FV**).","prio":"P1","sec":"s2"},{"id":"fc-230-468555","poly":"cardio","fiche":"230","front":"Suspicion d'urgence cardiovasculaire : quels examens systématiques ?","back":"**ECG 12 dérivations + V3R, V4R, V7, V8, V9**, **radiographie pulmonaire**, **troponine ultrasensible**.","prio":"P1","sec":"s3"},{"id":"fc-230-b7e041","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelle notion inacceptable concerne la troponine ?","back":"Doser la troponine **avant** d'avoir réalisé l'**ECG**.","prio":"P1","sec":"s3"},{"id":"fc-230-fdb18e","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelle est la base de la prise en charge ?","back":"**Interrogatoire**, **ECG** et **dosage répété** des troponines ultrasensibles.","prio":"P1","sec":"s3"},{"id":"fc-230-190675","poly":"cardio","fiche":"230","front":"Échocardiographie et scanner thoracique : quelle place dans la douleur thoracique ?","back":"**Souvent** utiles en **2e intention**, mais à faire **en urgence** sur une suspicion d'**EP** (et de dissection).","prio":"P1","sec":"s3"},{"id":"fc-230-e5ba81","poly":"cardio","fiche":"230","front":"SCA : dans quelle proportion clinique et ECG font-ils le diagnostic ?","back":"**Plus de 90 %** des cas.","prio":"P2","sec":"s3"},{"id":"fc-230-6743e9","poly":"cardio","fiche":"230","front":"ECG percritique et troponines normales : excluent-ils des lésions coronariennes ?","back":"**Non**, notamment un **angor instable**.","prio":"P1","sec":"s3"},{"id":"fc-230-eda3d0","poly":"cardio","fiche":"230","front":"Dissection aortique : que montre la radiographie de thorax ?","back":"**Médiastin élargi**, **double contour aortique**, épanchement pleural éventuel.","prio":"P1","sec":"s3"},{"id":"fc-230-cd38f5","poly":"cardio","fiche":"230","front":"SCA : quelle place de la radiographie de thorax ?","back":"Normale, souvent **inutile** sans insuffisance cardiaque.","prio":"P3","sec":"s3"},{"id":"fc-230-066b29","poly":"cardio","fiche":"230","front":"Tamponnade : quels signes ECG et radiographiques ?","back":"**Microvoltage**, parfois **alternance électrique** ; cœur « **en carafe** » si épanchement abondant.","prio":"P1","sec":"s3"},{"id":"fc-230-7b7c51","poly":"cardio","fiche":"230","front":"Coronarographie : quel résultat dans la myopéricardite ?","back":"**Normale**.","prio":"P2","sec":"s3"},{"id":"fc-230-fd521c","poly":"cardio","fiche":"230","front":"Embolie pulmonaire : quels signes ECG ?","back":"**Tachycardie sinusale**, **S1Q3**, **BBD**, ondes **T négatives** dans les précordiales droites (V1, V3).","prio":"P2","sec":"s3"},{"id":"fc-230-179669","poly":"cardio","fiche":"230","front":"SCA : quel terrain et quelles présentations ?","back":"FDR/ATCD coronariens ; douleur de **repos**, angor **de novo** ou **crescendo**.","prio":"P1","sec":"s4"},{"id":"fc-230-231048","poly":"cardio","fiche":"230","front":"SCA : à partir de quelle durée de douleur évoquer un infarctus ?","back":"**Plus de 20 minutes**.","prio":"P1","sec":"s4"},{"id":"fc-230-6206a6","poly":"cardio","fiche":"230","front":"SCA : chez qui les formes atypiques sont-elles fréquentes ?","back":"Chez la **femme** et le **sujet âgé** (douleur de la mandibule à l'ombilic, digestive).","prio":"P1","sec":"s4"},{"id":"fc-230-1ea644","poly":"cardio","fiche":"230","front":"Douleur ischémique : quelles caractéristiques typiques ?","back":"**Constriction**, pesanteur, brûlure ; **rétrosternale** ; irradiations cou, épaules, avant-bras ; déclenchée par l'**effort**.","prio":"P1","sec":"s4"},{"id":"fc-230-59a694","poly":"cardio","fiche":"230","front":"Douleur plutôt non ischémique : quelles caractéristiques ?","back":"**Coup de poignard**, majorée par la **respiration**, punctiforme, provoquée par un mouvement, de quelques secondes.","prio":"P2","sec":"s4"},{"id":"fc-230-184a0a","poly":"cardio","fiche":"230","front":"SCA non compliqué : que montre l'examen clinique ?","back":"Il est **normal** ; il cherche une autre localisation athéromateuse.","prio":"P2","sec":"s4"},{"id":"fc-230-96d49a","poly":"cardio","fiche":"230","front":"Douleur thoracique avec bloc de branche gauche : comment le considérer ?","back":"Comme un **équivalent de SCA ST+**.","prio":"P1","sec":"s4"},{"id":"fc-230-7eee32","poly":"cardio","fiche":"230","front":"Ischémie de la circonflexe : quel piège ECG et quelle conduite ?","back":"**Peut être électriquement muette** : enregistrer **V7, V8, V9**.","prio":"P1","sec":"s4"},{"id":"fc-230-650080","poly":"cardio","fiche":"230","front":"Sous-décalage de ST de V2 à V4 avec douleur prolongée : quelle conduite ?","back":"Occlusion de la **circonflexe** : prise en charge **comme un ST+**.","prio":"P1","sec":"s4"},{"id":"fc-230-fbab97","poly":"cardio","fiche":"230","front":"SCA : quel appareillage implanté peut rendre l'ECG trompeur ?","back":"Un **pacemaker** : l'ECG peut alors être **trompeur**.","prio":"P2","sec":"s4"},{"id":"fc-230-27a0e5","poly":"cardio","fiche":"230","front":"SCA ST+ confirmé à l'ECG : faut-il attendre la troponine ?","back":"**Non** : dosage inutile, la reperfusion se fait **sans attendre** le résultat.","prio":"P1","sec":"s4"},{"id":"fc-230-ed71f4","poly":"cardio","fiche":"230","front":"SCA sans sus-décalage persistant : quand refaire le dosage de troponine ?","back":"**1 ou 2 heures** après H0.","prio":"P1","sec":"s4"},{"id":"fc-230-1c8495","poly":"cardio","fiche":"230","front":"Troponine H0 élevée, ou faible mais en hausse significative : que conclure ?","back":"**SCA ST- à haut risque**.","prio":"P1","sec":"s4"},{"id":"fc-230-1d5999","poly":"cardio","fiche":"230","front":"Troponine faible sans hausse au 2e dosage : quelle conduite ?","back":"Penser à un **diagnostic différentiel** (ou SCA à bas risque) et **poursuivre la surveillance en Usic**.","prio":"P2","sec":"s4"},{"id":"fc-230-653dd9","poly":"cardio","fiche":"230","front":"Infarctus inférieur : quel diagnostic peut-il mimer ?","back":"Une **gastroentérite**.","prio":"P1","sec":"s4"},{"id":"fc-230-f148eb","poly":"cardio","fiche":"230","front":"Dissection aortique : quels facteurs favorisants ?","back":"**HTA ancienne**, **syndrome de Marfan**.","prio":"P1","sec":"s5"},{"id":"fc-230-b5d5df","poly":"cardio","fiche":"230","front":"Dissection aortique : quelle douleur typique ?","back":"Intense, **en déchirement**, irradiant dans le **dos**, **migratrice** vers les lombes ; typiquement sur **poussée hypertensive**.","prio":"P1","sec":"s5"},{"id":"fc-230-d039a5","poly":"cardio","fiche":"230","front":"Dissection aortique : quels signes d'examen ?","back":"**Asymétrie tensionnelle > 20 mmHg**, **pouls aboli**, souffle d'**IA**, **déficit neurologique**.","prio":"P1","sec":"s5"},{"id":"fc-230-5b5f96","poly":"cardio","fiche":"230","front":"Dissection aortique : par quelles complications peut-elle se révéler ?","back":"Ischémie de membre, **AVC**, infarctus **mésentérique**, **tamponnade**, IA aiguë, SCA par dissection coronaire.","prio":"P1","sec":"s5"},{"id":"fc-230-feebd4","poly":"cardio","fiche":"230","front":"Dissection aortique : que montre l'ECG ?","back":"Normal, ou aspect de **SCA** si extension à une coronaire.","prio":"P1","sec":"s5"},{"id":"fc-230-5ebf40","poly":"cardio","fiche":"230","front":"Dissection aortique : les D-dimères sont-ils souvent normaux ?","back":"**Non** : des D-dimères **normaux sont rares** dans une dissection.","prio":"P2","sec":"s5"},{"id":"fc-230-306004","poly":"cardio","fiche":"230","front":"Score de probabilité de dissection : quels groupes et quelle lecture ?","back":"Terrain, douleur, examen (1 point chacun) : **0-1 faible**, **2-3 forte**.","prio":"P3","sec":"s5"},{"id":"fc-230-bf0387","poly":"cardio","fiche":"230","front":"Dissection aortique : quel examen confirme le plus souvent le diagnostic ?","back":"L'**angioscanner thoracique** (notamment si instable ; prépare la chirurgie).","prio":"P2","sec":"s5"},{"id":"fc-230-308177","poly":"cardio","fiche":"230","front":"Dissection aortique : quand réaliser une ETT/ETO ?","back":"**Seulement si l'hémodynamique est stable**.","prio":"P3","sec":"s5"},{"id":"fc-230-64b14b","poly":"cardio","fiche":"230","front":"EP : quel terrain l'évoque ?","back":"**Cancer**, œstroprogestatifs + tabac, **postopératoire**, post-partum, **alitement**, ATCD de MTEV.","prio":"P1","sec":"s6"},{"id":"fc-230-a0dfa0","poly":"cardio","fiche":"230","front":"EP : quelle présentation clinique typique ?","back":"Douleur **basithoracique** avec **dyspnée aiguë**, polypnée, toux, parfois hémoptysie tardive.","prio":"P1","sec":"s6"},{"id":"fc-230-33d2af","poly":"cardio","fiche":"230","front":"EP : quel signe d'examen est un signe de gravité ?","back":"Les signes d'**insuffisance ventriculaire droite**.","prio":"P1","sec":"s6"},{"id":"fc-230-3d15c8","poly":"cardio","fiche":"230","front":"Douleur thoracique + dyspnée + radiographie normale : quel diagnostic évoquer obligatoirement ?","back":"Une **embolie pulmonaire**.","prio":"P1","sec":"s6"},{"id":"fc-230-31067d","poly":"cardio","fiche":"230","front":"Infarctus pulmonaire : quel tableau ?","back":"Douleur **pariétopleurale** fébrile, hémoptysie **noirâtre tardive** ; **bon pronostic**.","prio":"P2","sec":"s6"},{"id":"fc-230-0a5494","poly":"cardio","fiche":"230","front":"Cœur pulmonaire aigu de l'EP : quel tableau ?","back":"**Dyspnée isolée**, défaillance VD ou **collapsus** ; douleur au second plan.","prio":"P2","sec":"s6"},{"id":"fc-230-5f2461","poly":"cardio","fiche":"230","front":"EP à haut risque : quelle définition ?","back":"Choc ou hypotension : PAS **< 90 mmHg** ou baisse **≥ 40 mmHg** > 15 min (hors arythmie, hypovolémie, sepsis).","prio":"P1","sec":"s6"},{"id":"fc-230-8d0bf5","poly":"cardio","fiche":"230","front":"EP à haut risque suspectée : quel examen ?","back":"**Scanner thoracique** s'il est disponible tout de suite, sinon **échocardiographie** (VD dilaté).","prio":"P1","sec":"s6"},{"id":"fc-230-39510b","poly":"cardio","fiche":"230","front":"EP sans choc : quels scores de probabilité ?","back":"**Wells modifié** ou **Genève modifié**.","prio":"P2","sec":"s6"},{"id":"fc-230-44b702","poly":"cardio","fiche":"230","front":"EP en probabilité faible ou modérée : quel premier examen ?","back":"Les **D-dimères** (positifs > 500 µg/L ou > 10 × l'âge après 50 ans → angioscanner).","prio":"P1","sec":"s6"},{"id":"fc-230-fb5a27","poly":"cardio","fiche":"230","front":"D-dimères Elisa négatifs en probabilité modérée d'EP : que conclure ?","back":"**EP éliminée**.","prio":"P1","sec":"s6"},{"id":"fc-230-645a14","poly":"cardio","fiche":"230","front":"EP en probabilité forte : quelle conduite diagnostique ?","back":"D-dimères **inutiles** : **angioscanner d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-230-c34db7","poly":"cardio","fiche":"230","front":"EP en probabilité intermédiaire ou haute : quand débuter l'antithrombotique ?","back":"**Avant même la confirmation**.","prio":"P1","sec":"s6"},{"id":"fc-230-ed52cf","poly":"cardio","fiche":"230","front":"EP : les signes de thrombose veineuse sont-ils constants ?","back":"**Non** : absents dans **un tiers des cas**.","prio":"P3","sec":"s6"},{"id":"fc-230-886831","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quel terrain ?","back":"Contexte **viral**, fièvre, ou forme **récidivante**.","prio":"P2","sec":"s7"},{"id":"fc-230-2c2c2e","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelles caractéristiques de la douleur ?","back":"Majorée à l'**inspiration profonde** et au **décubitus**, **calmée par l'antéflexion**.","prio":"P1","sec":"s7"},{"id":"fc-230-a4e72b","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quel signe d'auscultation ?","back":"Un **frottement péricardique**, classiquement **fugace et inconstant**.","prio":"P2","sec":"s7"},{"id":"fc-230-0d3de1","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quels signes ECG ?","back":"Sus-ST **concave et diffus**, **sans miroir ni onde Q**, **sous-décalage de PQ**, microvoltage.","prio":"P1","sec":"s7"},{"id":"fc-230-7b9c8d","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quels examens sont obligatoires ?","back":"**Échocardiographie** et **troponines**.","prio":"P1","sec":"s7"},{"id":"fc-230-a8552e","poly":"cardio","fiche":"230","front":"Péricardite avec échocardiographie normale : que conclure ?","back":"Elle n'est pas exclue (**péricardite sèche**) : savoir **répéter** l'écho.","prio":"P1","sec":"s7"},{"id":"fc-230-763742","poly":"cardio","fiche":"230","front":"Péricardite aiguë : pourquoi est-ce un diagnostic d'élimination ?","back":"C'est l'étiologie **la plus bénigne**, qui peut ressembler à un **SCA**.","prio":"P2","sec":"s7"},{"id":"fc-230-8e6134","poly":"cardio","fiche":"230","front":"Tamponnade : quels signes cliniques ?","back":"**Dyspnée/orthopnée**, **turgescence jugulaire**, reflux hépatojugulaire, tachycardie, **PAS < 90**, **pouls paradoxal**.","prio":"P1","sec":"s7"},{"id":"fc-230-036713","poly":"cardio","fiche":"230","front":"Tamponnade : quelle définition chiffrée du pouls paradoxal ?","back":"PAS d'inspiration **inférieure de 10 mmHg** à la PAS d'expiration.","prio":"P1","sec":"s7"},{"id":"fc-230-6ca308","poly":"cardio","fiche":"230","front":"Tamponnade : quel examen confirme et que montre-t-il ?","back":"L'**échocardiographie** : **collapsus des cavités droites** en expiration, compression du VG par le VD en inspiration.","prio":"P1","sec":"s7"},{"id":"fc-230-facfc1","poly":"cardio","fiche":"230","front":"Pouls paradoxal de la tamponnade : quel mécanisme ?","back":"À l'inspiration, le retour veineux dilate le **VD**, qui **comprime le VG** et fait baisser la PAS.","prio":"P2","sec":"s7"},{"id":"fc-230-d8b896","poly":"cardio","fiche":"230","front":"Myopéricardite : quelle étiologie la plus fréquente ?","back":"**Virale**.","prio":"P2","sec":"s7"},{"id":"fc-230-149bf2","poly":"cardio","fiche":"230","front":"Myopéricardite : pourquoi est-elle trompeuse ?","back":"Elle peut **mimer un SCA**, avec **élévation prolongée des troponines**.","prio":"P1","sec":"s7"},{"id":"fc-230-238f68","poly":"cardio","fiche":"230","front":"Myopéricardite : que montre l'IRM ?","back":"Œdème et **rehaussement tardif sous-épicardique**, **sans systématisation artérielle**.","prio":"P2","sec":"s7"},{"id":"fc-230-627a8c","poly":"cardio","fiche":"230","front":"Myocardite isolée : quel est son principal diagnostic différentiel ?","back":"Le **SCA**.","prio":"P2","sec":"s7"},{"id":"fc-230-e1031e","poly":"cardio","fiche":"230","front":"4 urgences cardiovasculaires : quelle est la survenue typique de l'EP ?","back":"**Progressive**, avec dyspnée (SCA et dissection : brutale).","prio":"P2","sec":"s8"},{"id":"fc-230-1477c2","poly":"cardio","fiche":"230","front":"4 urgences cardiovasculaires : quel terrain pour la péricardite ?","back":"**Sujet jeune**, **contage viral**.","prio":"P2","sec":"s8"},{"id":"fc-230-a9dd47","poly":"cardio","fiche":"230","front":"4 urgences cardiovasculaires : pour laquelle la radiographie de thorax est-elle la plus contributive ?","back":"La **dissection aortique**.","prio":"P2","sec":"s8"},{"id":"fc-230-6f11a8","poly":"cardio","fiche":"230","front":"Douleur de dissection vs douleur de SCA : quel type typique pour chacune ?","back":"Dissection : **coup de poignard**, transfixiante ; SCA : **constrictive**, brûlure.","prio":"P2","sec":"s8"},{"id":"fc-230-f8a969","poly":"cardio","fiche":"230","front":"EP et péricardite : quel siège de douleur typique pour chacune ?","back":"EP : **latéro- ou basithoracique** ; péricardite : **rétrosternale**.","prio":"P3","sec":"s8"},{"id":"fc-230-50e895","poly":"cardio","fiche":"230","front":"Pneumothorax : quels signes cliniques ?","back":"Douleur pleurale, **tympanisme**, **murmure vésiculaire aboli**, parfois dyspnée.","prio":"P1","sec":"s9"},{"id":"fc-230-317c18","poly":"cardio","fiche":"230","front":"Pneumothorax partiel : quelle radiographie demander ?","back":"Un cliché **en expiration**.","prio":"P3","sec":"s9"},{"id":"fc-230-699caa","poly":"cardio","fiche":"230","front":"Épanchement pleural : quels signes cliniques et radiographiques ?","back":"Douleur pleurale, **matité** ; radio : **ligne de Damoiseau**.","prio":"P2","sec":"s9"},{"id":"fc-230-3d3fda","poly":"cardio","fiche":"230","front":"Pneumopathie infectieuse : quels signes ?","back":"**Fièvre**, souffle tubaire et crépitants, opacité avec **bronchogramme aérien**.","prio":"P2","sec":"s9"},{"id":"fc-230-e9dbf8","poly":"cardio","fiche":"230","front":"Spasme œsophagien : quelles caractéristiques ?","back":"Douleur d'allure **angineuse**, déclenchée par la **déglutition**, parfois **calmée par les nitrés**.","prio":"P2","sec":"s9"},{"id":"fc-230-dd3a03","poly":"cardio","fiche":"230","front":"Syndrome de Tietze : quelle définition et quel signe ?","back":"Inflammation du **cartilage sternocostal** ; douleur **reproduite à la palpation**.","prio":"P2","sec":"s9"},{"id":"fc-230-01c31d","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelles causes abdominales projetées ?","back":"**Lithiase** vésiculaire, **ulcère**, **pancréatite**, appendicite sous-hépatique, abcès sous-phrénique.","prio":"P2","sec":"s9"},{"id":"fc-230-19492e","poly":"cardio","fiche":"230","front":"Douleur thoracique psychogène : quelle fréquence et quelle prudence ?","back":"**Extrêmement fréquente** mais diagnostic à poser **avec la plus grande prudence**.","prio":"P1","sec":"s9"},{"id":"fc-230-5bad60","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelles sont les 6 urgences non cardiaques ?","back":"**Pleurésies/pneumonies**, **pneumothorax**, **pancréatite**, **ulcère compliqué**, **cholécystite**, **douleurs radiculaires**.","prio":"P1","sec":"s9"},{"id":"fc-230-0007a1","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelles causes neurologiques citer ?","back":"**Zona intercostal**, tassement vertébral.","prio":"P3","sec":"s9"},{"id":"fc-230-dcaaa5","poly":"cardio","fiche":"230","front":"Dissection aortique : quel piège abdominal peut-elle donner ?","back":"Une **ischémie mésentérique** (douleur abdominale trompeuse).","prio":"P2","sec":"s9"},{"id":"fc-230-0708a8","poly":"cardio","fiche":"230","front":"Angor stable : quand la douleur est-elle caractéristique ?","back":"**Constrictive**, déclenchée par l'**effort** (ou un repas), cédant à l'arrêt ou à la **trinitrine en 1 à 3 min**.","prio":"P1","sec":"s10"},{"id":"fc-230-65cd62","poly":"cardio","fiche":"230","front":"Angor fonctionnel : quelles causes ?","back":"**RA serré**, **CMH**, **anémie**, **tachycardies** (FA), **hyperthyroïdie**.","prio":"P2","sec":"s10"},{"id":"fc-230-ed8bda","poly":"cardio","fiche":"230","front":"HTAP sévère : pourquoi peut-elle donner une douleur angineuse ?","back":"**Ischémie du VD** quand la pression intra-VD dépasse la pression de perfusion coronaire.","prio":"P3","sec":"s10"},{"id":"fc-230-164b9e","poly":"cardio","fiche":"230","front":"Syndrome coronarien chronique suspecté : quels éléments du score de probabilité clinique ?","back":"**Âge**, **sexe**, **type de douleur/dyspnée** (0-3 points), **nombre de FDR** (0-5).","prio":"P2","sec":"s10"},{"id":"fc-230-dbd051","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie < 5 % : quelle conduite ?","back":"**Aucun** examen complémentaire.","prio":"P1","sec":"s10"},{"id":"fc-230-e0296d","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie modérée (15-50 %) : quel examen ?","back":"**Scanner coronarien** ou **imagerie fonctionnelle**.","prio":"P2","sec":"s10"},{"id":"fc-230-6821cb","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie élevée (> 50-85 %) : quel examen ?","back":"Une **imagerie fonctionnelle**.","prio":"P2","sec":"s10"},{"id":"fc-230-7a0955","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie > 85 % : quel examen ?","back":"Une **coronarographie** diagnostique.","prio":"P1","sec":"s10"},{"id":"fc-230-c681ee","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie faible (5-15 %) : quelle stratégie ?","back":"**Scanner coronaire d'emblée** ou **réévaluer** la probabilité (ECG, épreuve d'effort, écho, score calcique...).","prio":"P3","sec":"s10"},{"id":"fc-230-b71756","poly":"cardio","fiche":"230","front":"Arrêt circulatoire : quand débuter la réanimation ?","back":"Dès qu'il est **diagnostiqué ou suspecté**, avec appel du 15.","prio":"P1","sec":"s11"},{"id":"fc-230-c9dc48","poly":"cardio","fiche":"230","front":"Massage cardiaque externe : quelles modalités ?","back":"Talon de la main au milieu du thorax, **4 à 5 cm**, **100/min**, relais environ toutes les **2 min**.","prio":"P1","sec":"s11"},{"id":"fc-230-6d69d1","poly":"cardio","fiche":"230","front":"Fibrillation ventriculaire : quel est le seul traitement efficace ?","back":"Le **choc électrique externe** (défibrillation précoce).","prio":"P1","sec":"s11"},{"id":"fc-230-8050dc","poly":"cardio","fiche":"230","front":"Arrêt cardiaque : dans quel délai idéal délivrer le 1er choc ?","back":"Dans les **3 minutes** suivant l'arrêt.","prio":"P1","sec":"s11"},{"id":"fc-230-861e54","poly":"cardio","fiche":"230","front":"Après un choc électrique externe : quand vérifier la reprise circulatoire ?","back":"Après **2 min** de RCP.","prio":"P2","sec":"s11"},{"id":"fc-230-53d1ff","poly":"cardio","fiche":"230","front":"Asystolie : faut-il défibriller ?","back":"**Non** : on **masse**.","prio":"P1","sec":"s11"},{"id":"fc-230-9cf016","poly":"cardio","fiche":"230","front":"Activité électrique sans pouls : quelle conduite ?","back":"**Poursuivre le massage**.","prio":"P2","sec":"s11"},{"id":"fc-230-28f21a","poly":"cardio","fiche":"230","front":"RCP de l'adulte : le bouche-à-bouche est-il recommandé ?","back":"**Non** ; libérer les voies aériennes et limiter les interruptions du massage.","prio":"P2","sec":"s11"},{"id":"fc-230-022d59","poly":"cardio","fiche":"230","front":"RCP médicalisée : quelle posologie d'adrénaline ?","back":"**1 mg toutes les 4 min** IV (ou endotrachéale).","prio":"P2","sec":"s11"},{"id":"fc-230-8f9435","poly":"cardio","fiche":"230","front":"FV/TV réfractaire aux chocs : quel antiarythmique et quelle dose ?","back":"**Amiodarone 300 mg IV** avant le 3e choc, puis **150 mg** si réfractaire ou récidivante.","prio":"P2","sec":"s11"},{"id":"fc-230-5edd6a","poly":"cardio","fiche":"230","front":"RCP : quand donner du sulfate de magnésium ?","back":"**Torsades de pointes** ou suspicion d'**hypomagnésémie** (2 g IVD).","prio":"P3","sec":"s11"},{"id":"fc-230-017fef","poly":"cardio","fiche":"230","front":"Intubation pendant la RCP : combien de temps peut-on interrompre le massage ?","back":"**Pas plus de 30 s**.","prio":"P3","sec":"s11"},{"id":"fc-230-fe74e4","poly":"cardio","fiche":"230","front":"Isoprénaline : quelle contre-indication dans le contexte du SCA ?","back":"La **phase aiguë d'un IDM**.","prio":"P3","sec":"s11"},{"id":"fc-230-b58fb6","poly":"cardio","fiche":"230","front":"Douleur thoracique en urgence : quelle surveillance pendant le transfert ?","back":"**Monitorage ECG continu**.","prio":"P2","sec":"s11"},{"id":"fc-230-be8a3f","poly":"cardio","fiche":"230","front":"SCA ST+ : quels équivalents ECG ?","back":"**BBG**, sus-décalage en **V7-V9**, sous-décalage de **V2 à V4** avec douleur prolongée.","prio":"P1","sec":"s12"},{"id":"fc-230-46455b","poly":"cardio","fiche":"230","front":"Douleur thoracique aux urgences : dans quel délai faire l'ECG ?","back":"Dans les **10 minutes** suivant l'admission.","prio":"P1","sec":"s12"},{"id":"fc-230-2134f8","poly":"cardio","fiche":"230","front":"SCA ST+ : où transférer le patient ?","back":"En **Usic** (risque de FV) ou **directement en salle de coronarographie**.","prio":"P1","sec":"s12"},{"id":"fc-230-9f23ca","poly":"cardio","fiche":"230","front":"SCA ST+ : quand choisir l'angioplastie primaire ?","back":"Si elle est faisable dans les **120 minutes** ; sinon **fibrinolyse immédiate**.","prio":"P1","sec":"s12"},{"id":"fc-230-583ac6","poly":"cardio","fiche":"230","front":"SCA ST+ après fibrinolyse : quelle conduite ?","back":"Échec → **angioplastie de sauvetage** ; succès → **coronarographie dans les 24 h**.","prio":"P1","sec":"s12"},{"id":"fc-230-f144aa","poly":"cardio","fiche":"230","front":"SCA ST+ : à partir de quand le bénéfice de la reperfusion devient-il faible ?","back":"À partir de la **12ᵉ heure** (voire nul après la 24ᵉ).","prio":"P1","sec":"s12"},{"id":"fc-230-9dfabe","poly":"cardio","fiche":"230","front":"Angioplastie coronaire : quelle voie d'abord préférer ?","back":"La voie **radiale** (beaucoup moins d'hémorragies).","prio":"P2","sec":"s12"},{"id":"fc-230-e40a81","poly":"cardio","fiche":"230","front":"SCA : quelle posologie d'aspirine ?","back":"**250 mg IVD** puis **75-100 mg/j** per os, au long cours.","prio":"P1","sec":"s12"},{"id":"fc-230-2cc37c","poly":"cardio","fiche":"230","front":"SCA ST+ en angioplastie primaire : quels P2Y12 de 1re intention ?","back":"**Prasugrel** (60 mg puis 10 mg/j) ou **ticagrélor** (180 mg puis 90 mg × 2/j).","prio":"P1","sec":"s12"},{"id":"fc-230-06aac9","poly":"cardio","fiche":"230","front":"Prasugrel : quelles contre-indications et limites ?","back":"**ATCD d'AVC** ; non recommandé après **75 ans** et/ou poids **< 60 kg**.","prio":"P1","sec":"s12"},{"id":"fc-230-d11b01","poly":"cardio","fiche":"230","front":"Ticagrélor : quels effets indésirables ?","back":"**Bradycardie** et **dyspnée**, réversibles à l'arrêt.","prio":"P2","sec":"s12"},{"id":"fc-230-6020eb","poly":"cardio","fiche":"230","front":"Clopidogrel dans le SCA : quelle posologie (hors fibrinolyse) ?","back":"Charge **600 mg** puis **75 mg/j**.","prio":"P2","sec":"s12"},{"id":"fc-230-a21aea","poly":"cardio","fiche":"230","front":"SCA ST+ fibrinolysé : quel P2Y12 utiliser ?","back":"Le **clopidogrel**, seul P2Y12 autorisé (charge 300 mg si < 75 ans, puis 75 mg/j) ; prasugrel et ticagrélor non autorisés.","prio":"P1","sec":"s12"},{"id":"fc-230-bc9b02","poly":"cardio","fiche":"230","front":"SCA : combien de temps poursuivre la bithérapie antiplaquettaire ?","back":"**12 mois**.","prio":"P1","sec":"s12"},{"id":"fc-230-d01564","poly":"cardio","fiche":"230","front":"SCA avec angioplastie immédiate : quel anticoagulant ?","back":"**HNF 70-100 UI/kg IVD** ou **énoxaparine 0,5 mg/kg IVD**.","prio":"P2","sec":"s12"},{"id":"fc-230-05b560","poly":"cardio","fiche":"230","front":"Fibrinolyse : citer des contre-indications absolues.","back":"ATCD d'**AVC hémorragique**, AVC < 6 mois, tumeur cérébrale, traumatisme/hémorragie digestive < 1 mois, **dissection aortique**.","prio":"P1","sec":"s12"},{"id":"fc-230-eff1d3","poly":"cardio","fiche":"230","front":"SCA : quand prescrire de l'oxygène ?","back":"**Uniquement** si SaO₂ **< 90 %** ou PaO₂ **< 60 mmHg** (hyperoxie délétère).","prio":"P1","sec":"s12"},{"id":"fc-230-fa8189","poly":"cardio","fiche":"230","front":"SCA : quelle statine et quelle dose ?","back":"Forte dose : **atorvastatine 80 mg** ou **rosuvastatine 20 mg**.","prio":"P1","sec":"s12"},{"id":"fc-230-f55f7b","poly":"cardio","fiche":"230","front":"Infarctus du VD : quelle classe médicamenteuse est contre-indiquée ?","back":"Les **vasodilatateurs** (dérivés nitrés).","prio":"P1","sec":"s12"},{"id":"fc-230-736e90","poly":"cardio","fiche":"230","front":"Infarctus du VD : quels signes l'évoquent ?","back":"ST+ **inférieur**, **hypotension**, **poumons clairs**, **turgescence jugulaire**.","prio":"P2","sec":"s12"},{"id":"fc-230-cb0047","poly":"cardio","fiche":"230","front":"SCA : quand utiliser un dérivé nitré IV ?","back":"En cas d'**HTA** ou d'**IC congestive** (dinitrate d'isosorbide 2 mg/h).","prio":"P2","sec":"s12"},{"id":"fc-230-a96ef6","poly":"cardio","fiche":"230","front":"Complication du SCA : BAV nodal de l'IDM inférieur ; quel traitement ?","back":"**Atropine** (+ remplissage si hypotension vagale).","prio":"P2","sec":"s12"},{"id":"fc-230-de52ff","poly":"cardio","fiche":"230","front":"Complication du SCA : BAV infranodal ; quelle conduite ?","back":"Stimulation provisoire, le plus souvent **stimulateur permanent**.","prio":"P2","sec":"s12"},{"id":"fc-230-bf6658","poly":"cardio","fiche":"230","front":"Complication du SCA : choc cardiogénique ; quel traitement ?","back":"**Dobutamine** puis assistance circulatoire **si le terrain le permet** ; chercher une complication mécanique à l'écho.","prio":"P2","sec":"s12"},{"id":"fc-230-c1ea65","poly":"cardio","fiche":"230","front":"Complication du SCA : rupture de pilier mitral ; quelle conduite ?","back":"**Chirurgie urgente**.","prio":"P2","sec":"s12"},{"id":"fc-230-9968ea","poly":"cardio","fiche":"230","front":"Complication du SCA : hémopéricarde par rupture de la paroi libre ; quelle conduite ?","back":"**Chirurgie immédiate**.","prio":"P2","sec":"s12"},{"id":"fc-230-847a26","poly":"cardio","fiche":"230","front":"Complication du SCA : thrombus intra-VG ; quel traitement ?","back":"**Anticoagulation curative**.","prio":"P2","sec":"s12"},{"id":"fc-230-8e62bc","poly":"cardio","fiche":"230","front":"Ondes Q de nécrose sur l'ECG : est-il trop tard pour reperfuser ?","back":"**Non**, pas nécessairement.","prio":"P2","sec":"s12"},{"id":"fc-230-6c685b","poly":"cardio","fiche":"230","front":"SCA ST- à très haut risque : quels critères ?","back":"**Choc**, douleur persistante/récidivante, **IC**, **TV/FV**/arrêt, complication mécanique, ECG dynamique.","prio":"P1","sec":"s13"},{"id":"fc-230-c1f838","poly":"cardio","fiche":"230","front":"SCA ST- à haut risque : quels critères ?","back":"IDM ST- confirmé (ECG/troponine), **GRACE > 140**, sus-ST transitoire, sous-ST dynamique ou T négatives.","prio":"P1","sec":"s13"},{"id":"fc-230-10e9b7","poly":"cardio","fiche":"230","front":"SCA ST- : dans quel délai la coronarographie ?","back":"**< 2 h** si très haut risque ; **< 24 h** si haut risque.","prio":"P1","sec":"s13"},{"id":"fc-230-73df3c","poly":"cardio","fiche":"230","front":"SCA ST- : quand pratiquer un pontage plutôt qu'une angioplastie ?","back":"Lésions du **tronc gauche** ou **tritronculaires complexes**, surtout chez le diabétique.","prio":"P3","sec":"s13"},{"id":"fc-230-4a0a2c","poly":"cardio","fiche":"230","front":"SCA ST- : quand ajouter le P2Y12 ?","back":"Le plus souvent **sur table de coronarographie**, avant l'angioplastie (pas de bithérapie dès l'admission).","prio":"P1","sec":"s13"},{"id":"fc-230-6c53c7","poly":"cardio","fiche":"230","front":"SCA ST- à haut risque : quels anticoagulants en Usic ?","back":"**Énoxaparine 1 mg/kg SC × 2/j** ou **fondaparinux 2,5 mg/j SC** (+ bolus d'HNF en coronarographie).","prio":"P1","sec":"s13"},{"id":"fc-230-42c4f3","poly":"cardio","fiche":"230","front":"SCA ST- à haut risque avec IRC sévère (CI aux HBPM/fondaparinux) : quel anticoagulant ?","back":"**HNF IVSE 400-600 UI/kg/24 h**.","prio":"P2","sec":"s13"},{"id":"fc-230-fe7d1c","poly":"cardio","fiche":"230","front":"SCA ST- avec risque hémorragique élevé : quelle durée de bithérapie antiplaquettaire ?","back":"**1 à 6 mois**.","prio":"P2","sec":"s13"},{"id":"fc-230-0b6285","poly":"cardio","fiche":"230","front":"SCA : citer des facteurs de risque hémorragique.","back":"Âge **> 75 ans**, **sexe féminin**, **IR**, AVC ancien, poids < 65 kg, diathèse hémorragique.","prio":"P3","sec":"s13"},{"id":"fc-230-f07345","poly":"cardio","fiche":"230","front":"SCA ST- : quelle notion inacceptable concerne la gravité ?","back":"Ne pas évaluer la **gravité**, qui fixe le **délai de coronarographie**.","prio":"P2","sec":"s13"},{"id":"fc-230-272507","poly":"cardio","fiche":"230","front":"IEC/ARA2 après SCA : quand surtout les prescrire ?","back":"Surtout si **FEVG ≤ 40 %**, diabète ou IRC.","prio":"P2","sec":"s13"},{"id":"fc-230-7d1eed","poly":"cardio","fiche":"230","front":"Dissection aortique : quel objectif tensionnel ?","back":"**Normaliser** la PA (urgence hypertensive) : **PAS < 120 mmHg** le plus vite possible.","prio":"P2","sec":"s14"},{"id":"fc-230-3affac","poly":"cardio","fiche":"230","front":"Dissection aortique : quelles formes relèvent d'une chirurgie urgente ?","back":"Toutes, **sauf** les formes limitées à l'**aorte descendante** (type B non compliqué).","prio":"P1","sec":"s14"},{"id":"fc-230-921720","poly":"cardio","fiche":"230","front":"Dissection aortique de type A : quelle définition et quelle conduite ?","back":"Atteinte de l'**aorte ascendante** : **chirurgie en urgence**.","prio":"P2","sec":"s14"},{"id":"fc-230-c59a54","poly":"cardio","fiche":"230","front":"Dissection aortique de type B sans complication : quelle conduite ?","back":"**Pas de chirurgie en urgence** (une complication périphérique fait changer).","prio":"P2","sec":"s14"},{"id":"fc-230-5249d7","poly":"cardio","fiche":"230","front":"Dissection aortique : quels antihypertenseurs IV ?","back":"**Urapidil** ou **nicardipine** IV (1re intention des urgences hypertensives).","prio":"P3","sec":"s14"},{"id":"fc-230-396501","poly":"cardio","fiche":"230","front":"Dissection aortique : quelle contre-indication thérapeutique absolue retenir ?","back":"La **fibrinolyse**.","prio":"P1","sec":"s14"},{"id":"fc-230-202eb6","poly":"cardio","fiche":"230","front":"Dissection aortique : où hospitaliser et quelle surveillance de la PA ?","back":"**Soins intensifs ou réanimation** ; PA **toutes les 15 min**.","prio":"P3","sec":"s14"},{"id":"fc-230-7c1395","poly":"cardio","fiche":"230","front":"Dissection aortique : quelles complications guetter ?","back":"**Ischémie de membre**, **AVC**, **ischémie mésentérique**, **tamponnade**.","prio":"P2","sec":"s14"},{"id":"fc-230-2e67fd","poly":"cardio","fiche":"230","front":"EP à haut risque en choc sans scanner possible : que suffit-il pour fibrinolyser ?","back":"Une **surcharge droite à l'ETT**.","prio":"P1","sec":"s15"},{"id":"fc-230-711c82","poly":"cardio","fiche":"230","front":"EP à haut risque confirmée : quel traitement ?","back":"**Thrombolyse** (ou embolectomie), en **réanimation/USIC**.","prio":"P1","sec":"s15"},{"id":"fc-230-a09cf6","poly":"cardio","fiche":"230","front":"EP à haut risque avec thrombolyse contre-indiquée ou en échec : quelle option ?","back":"**Embolectomie chirurgicale en urgence** (sous CEC).","prio":"P1","sec":"s15"},{"id":"fc-230-7203a2","poly":"cardio","fiche":"230","front":"EP à haut risque : quel anticoagulant et quelle dose ?","back":"**HNF 500 UI/kg/j** IV continue.","prio":"P1","sec":"s15"},{"id":"fc-230-cf2959","poly":"cardio","fiche":"230","front":"HNF : quelles cibles biologiques (item 226) ?","back":"**TCA 1,5-2,5 × le témoin** ou **anti-Xa 0,3-0,7 U**, 4 h après le début.","prio":"P2","sec":"s15"},{"id":"fc-230-1b3a5f","poly":"cardio","fiche":"230","front":"HNF : quelle surveillance des plaquettes ?","back":"**Avant** puis **2 fois/semaine pendant 21 jours**.","prio":"P1","sec":"s15"},{"id":"fc-230-d50554","poly":"cardio","fiche":"230","front":"Après embolectomie pour EP massive : quel dispositif proposer ?","back":"Un **filtre cave**.","prio":"P2","sec":"s15"},{"id":"fc-230-17a7aa","poly":"cardio","fiche":"230","front":"EP de gravité intermédiaire sans choc : la fibrinolyse est-elle systématique ?","back":"**Non**.","prio":"P1","sec":"s15"},{"id":"fc-230-25e558","poly":"cardio","fiche":"230","front":"Sous HNF : quels critères définissent une thrombopénie induite (TIH) ?","back":"Plaquettes **< 150 G/L** ou **chute de 50 %**.","prio":"P2","sec":"s15"},{"id":"fc-230-85ddaf","poly":"cardio","fiche":"230","front":"EP à risque intermédiaire haut : quelle définition et quelle orientation ?","back":"sPESI ≥ 1, **VD dilaté et troponine +** : anticoagulant en **réanimation/USIC**, reperfusion si aggravation.","prio":"P1","sec":"s16"},{"id":"fc-230-ee18f4","poly":"cardio","fiche":"230","front":"EP à faible risque : quelle définition et quelle orientation ?","back":"**sPESI = 0**, VD normal : **hospitalisation courte ou ambulatoire**.","prio":"P1","sec":"s16"},{"id":"fc-230-c2f9bb","poly":"cardio","fiche":"230","front":"EP sans choc : quel est l'anticoagulant de référence ?","back":"Un **AOD anti-Xa** (rivaroxaban ou apixaban).","prio":"P1","sec":"s16"},{"id":"fc-230-1f6981","poly":"cardio","fiche":"230","front":"Rivaroxaban dans l'EP : quelle posologie ?","back":"**15 mg × 2/j pendant 21 jours**, puis **20 mg/j**.","prio":"P1","sec":"s16"},{"id":"fc-230-f65385","poly":"cardio","fiche":"230","front":"Apixaban dans l'EP : quelle posologie ?","back":"**10 mg × 2/j pendant 7 jours**, puis **5 mg × 2/j**.","prio":"P1","sec":"s16"},{"id":"fc-230-637eb7","poly":"cardio","fiche":"230","front":"EP : quelles posologies d'énoxaparine et de tinzaparine ?","back":"Énoxaparine **100 UI/kg/12 h SC** ; tinzaparine **175 UI/kg/24 h SC**.","prio":"P2","sec":"s16"},{"id":"fc-230-fbb415","poly":"cardio","fiche":"230","front":"HBPM, fondaparinux, AOD : quelle contre-indication rénale commune ?","back":"**DFG < 30 mL/min**.","prio":"P1","sec":"s16"},{"id":"fc-230-b5facd","poly":"cardio","fiche":"230","front":"EP : quand lever le patient ?","back":"Après **24 h d'anticoagulation efficace**, avec bas de contention.","prio":"P2","sec":"s16"},{"id":"fc-230-fa7329","poly":"cardio","fiche":"230","front":"EP sous AVK : quelle INR cible ?","back":"**2,5** (entre 2 et 3).","prio":"P1","sec":"s16"},{"id":"fc-230-092002","poly":"cardio","fiche":"230","front":"EP : quelle durée d'anticoagulation selon le contexte ?","back":"**3 mois** si facteur réversible ; **> 3 mois** sans facteur ; **illimitée** si récidive ou thrombophilie.","prio":"P1","sec":"s16"},{"id":"fc-230-be3f19","poly":"cardio","fiche":"230","front":"EP chez une femme sous œstroprogestatifs : quelle conduite contraceptive ?","back":"**Arrêter puis contre-indiquer** ; alternatives : **progestatif continu** ou **DIU**.","prio":"P1","sec":"s16"},{"id":"fc-230-468e09","poly":"cardio","fiche":"230","front":"EP pendant la grossesse : quel anticoagulant ?","back":"Les **HBPM** (AVK tératogènes).","prio":"P1","sec":"s16"},{"id":"fc-230-dea3f9","poly":"cardio","fiche":"230","front":"EP sur cancer : quelles limites des AOD ?","back":"Évités dans les cancers **digestifs** et **génito-urinaires** (risque hémorragique).","prio":"P3","sec":"s16"},{"id":"fc-230-dd8cf7","poly":"cardio","fiche":"230","front":"EP avec contre-indication aux anticoagulants : quelle option ?","back":"Un **filtre cave** (temporaire si CI provisoire, retiré ensuite).","prio":"P2","sec":"s16"},{"id":"fc-230-1d3c0a","poly":"cardio","fiche":"230","front":"EP, relais par AVK : quand arrêter l'héparine ?","back":"Après **≥ 5 jours** et **2 INR > 2** à 24 h d'intervalle (AVK débuté dès J1).","prio":"P2","sec":"s16"},{"id":"fc-230-7bb3e2","poly":"cardio","fiche":"230","front":"Tamponnade : quelle hospitalisation ?","back":"**Soins intensifs de cardiologie** (urgence médicochirurgicale).","prio":"P2","sec":"s17"},{"id":"fc-230-90e539","poly":"cardio","fiche":"230","front":"Tamponnade confirmée : quel traitement ?","back":"**Drainage** : **ponction péricardique écho-guidée** ou drainage chirurgical.","prio":"P1","sec":"s17"},{"id":"fc-230-1d2353","poly":"cardio","fiche":"230","front":"Tamponnade : quel traitement d'attente avant le drainage ?","back":"**Remplissage** par macromolécules.","prio":"P2","sec":"s17"},{"id":"fc-230-6f8c47","poly":"cardio","fiche":"230","front":"Tamponnade : pourquoi le drainage est-il impératif ?","back":"Risque d'**arrêt cardiaque par adiastolie**.","prio":"P2","sec":"s17"},{"id":"fc-230-537810","poly":"cardio","fiche":"230","front":"Antidote de l'HNF : lequel ?","back":"Le **sulfate de protamine**.","prio":"P1","sec":"s17"},{"id":"fc-230-602d3c","poly":"cardio","fiche":"230","front":"Antidotes des AVK : lesquels ?","back":"**PPSB** (action très rapide) + **vitamine K** (efficace en quelques heures).","prio":"P1","sec":"s17"},{"id":"fc-230-650190","poly":"cardio","fiche":"230","front":"Antidote du dabigatran : lequel ?","back":"L'**idarucizumab**.","prio":"P2","sec":"s17"},{"id":"fc-230-fea664","poly":"cardio","fiche":"230","front":"Tamponnade : quels contextes étiologiques habituels ?","back":"Péricardite **néoplasique**, **traumatique**, **tuberculeuse**, hémopéricarde ; exceptionnellement virale.","prio":"P3","sec":"s17"},{"id":"fc-230-74ff6f","poly":"cardio","fiche":"230","front":"Tamponnade : quelle notion inacceptable le Collège retient-il ?","back":"Ne pas la **reconnaître**, ou ne pas organiser sa **prise en charge urgente**.","prio":"P2","sec":"s17"},{"id":"fc-230-9e025e","poly":"cardio","fiche":"230","front":"Péricardite aiguë : faut-il hospitaliser systématiquement ?","back":"**Non** : seulement si complication ou facteur de gravité majeur.","prio":"P1","sec":"s18"},{"id":"fc-230-65b854","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quels facteurs majeurs imposent l'hospitalisation ?","back":"**Fièvre > 38 °C**, début subaigu, épanchement **> 20 mm** ou tamponnade, **échec** de l'aspirine/AINS à 7 jours.","prio":"P2","sec":"s18"},{"id":"fc-230-31565d","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelles mesures non médicamenteuses ?","back":"**Repos** et **arrêt du sport** jusqu'à normalisation des symptômes, CRP, ECG, écho.","prio":"P2","sec":"s18"},{"id":"fc-230-af1240","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle posologie d'aspirine ?","back":"**750 à 1 000 mg toutes les 8 h**.","prio":"P1","sec":"s18"},{"id":"fc-230-dd6928","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle posologie d'ibuprofène ?","back":"**600 mg toutes les 8 h**.","prio":"P2","sec":"s18"},{"id":"fc-230-032002","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle durée d'anti-inflammatoire ?","back":"Pleine dose **1 à 2 semaines** puis décroissance ; arrêt progressif en **4 à 8 semaines**.","prio":"P2","sec":"s18"},{"id":"fc-230-0b7daa","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle posologie et quelle durée de colchicine ?","back":"**0,5 mg × 2/j** (0,5 mg/j si < 70 kg, > 70 ans ou DFG < 35) pendant **3 mois**.","prio":"P1","sec":"s18"},{"id":"fc-230-cb8f70","poly":"cardio","fiche":"230","front":"Colchicine : quelles interactions surveiller ?","back":"Inhibiteurs du **CYP3A4** : macrolides, ciclosporine, vérapamil, statines.","prio":"P3","sec":"s18"},{"id":"fc-230-ea7c54","poly":"cardio","fiche":"230","front":"Péricardite aiguë : peut-on donner des corticoïdes en 1re intention ?","back":"**Non** (notion inacceptable : récidives) ; seulement après échec AINS + colchicine.","prio":"P1","sec":"s18"},{"id":"fc-230-67ff78","poly":"cardio","fiche":"230","front":"Péricardite récidivante : quelle cause fréquente et quelle prévention ?","back":"Traitement **trop court** ; la **colchicine** prévient les récidives.","prio":"P2","sec":"s18"},{"id":"fc-230-92fc44","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quel suivi ?","back":"Revoir à **7 jours**, **1 mois** (écho avant d'arrêter l'anti-inflammatoire), **3 et 6 mois**.","prio":"P2","sec":"s18"},{"id":"fc-230-8c1f63","poly":"cardio","fiche":"230","front":"Péricardite tuberculeuse : quel traitement ?","back":"**Antituberculeux**, associés pour certains à la **prednisone** (prévenir la constriction).","prio":"P3","sec":"s18"},{"id":"fc-230-077603","poly":"cardio","fiche":"230","front":"Angor de novo : comment le considérer ?","back":"Comme un **SCA** jusqu'à preuve du contraire.","prio":"P1","sec":"s19"},{"id":"fc-230-34837a","poly":"cardio","fiche":"230","front":"Angor stable : quels traitements systématiques ?","back":"Correction des FDR, **aspirine** et **statine**, anti-ischémiques pour les symptômes.","prio":"P1","sec":"s19"},{"id":"fc-230-a31d68","poly":"cardio","fiche":"230","front":"Angor stable : quand faire une coronarographie d'emblée ?","back":"Angor **sévère** (classe ≥ 3) ou **FEVG altérée**.","prio":"P2","sec":"s19"},{"id":"fc-230-4dbb75","poly":"cardio","fiche":"230","front":"Trinitrine sublinguale : quelle précaution de prise ?","back":"**Assis ou allongé** (céphalées, hypotension).","prio":"P2","sec":"s19"},{"id":"fc-230-e8611f","poly":"cardio","fiche":"230","front":"Angor stable : quel anti-ischémique de 1re intention ?","back":"Un **bêtabloquant**.","prio":"P1","sec":"s19"},{"id":"fc-230-733032","poly":"cardio","fiche":"230","front":"Bêtabloquant dans l'angor : quelles contre-indications ?","back":"**Asthme**, BPCO très sévère, Raynaud, bradycardie < 50/min, **BAV 2e ou 3e degré**.","prio":"P2","sec":"s19"},{"id":"fc-230-dad04a","poly":"cardio","fiche":"230","front":"Inhibiteur calcique bradycardisant dans l'angor : quelle association interdire ?","back":"Avec un **bêtabloquant** (troubles de conduction).","prio":"P1","sec":"s19"},{"id":"fc-230-d5fa46","poly":"cardio","fiche":"230","front":"Angor stable : quand préférer un inhibiteur calcique dihydropyridine ?","back":"**1re intention** si BB contre-indiqué ou FC < 60 bpm ; **2e intention** associé au BB.","prio":"P3","sec":"s19"},{"id":"fc-230-75c192","poly":"cardio","fiche":"230","front":"Nicorandil : quel effet indésirable caractéristique ?","back":"**Ulcérations** péribuccales, intestinales, périanales.","prio":"P3","sec":"s19"},{"id":"fc-230-023c10","poly":"cardio","fiche":"230","front":"Ivabradine : quelles conditions et quel effet indésirable ?","back":"Rythme **sinusal** avec FC ≥ 70 bpm (inefficace en FA) ; EI : **phosphènes**.","prio":"P3","sec":"s19"},{"id":"fc-230-cd4672","poly":"cardio","fiche":"230","front":"Dérivés nitrés au long cours : quelle association est contre-indiquée ?","back":"Avec les **inhibiteurs de la PDE5** (sildénafil).","prio":"P2","sec":"s19"},{"id":"fc-230-0266e5","poly":"cardio","fiche":"230","front":"Après angioplastie pour angor stable : quelle bithérapie antiplaquettaire ?","back":"**Aspirine + clopidogrel** habituellement **6 mois** ; **pas de prasugrel ni ticagrélor**.","prio":"P1","sec":"s19"},{"id":"fc-230-63916d","poly":"cardio","fiche":"230","front":"Angor stable : quel objectif de LDL-C ?","back":"**< 0,55 g/L**.","prio":"P1","sec":"s19"},{"id":"fc-230-baeee5","poly":"cardio","fiche":"230","front":"Douleur thoracique sans urgence vitale : quel est l'objectif ?","back":"Il reste **urgent de rassurer et de soulager**.","prio":"P2","sec":"s20"},{"id":"fc-230-c1d2bd","poly":"cardio","fiche":"230","front":"Urgences non cardiaques de douleur thoracique : quel degré d'urgence de prise en charge ?","back":"**Moyenne urgence**, prise en charge spécifique selon la cause.","prio":"P3","sec":"s20"},{"id":"fc-230-e0f202","poly":"cardio","fiche":"230","front":"SCA en Usic : quelle surveillance ?","back":"**Monitorage ECG continu**, ECG 2 fois/j et à chaque douleur, troponine, ETT à l'admission, biologie quotidienne.","prio":"P2","sec":"s21"},{"id":"fc-230-f03f8e","poly":"cardio","fiche":"230","front":"ECG du ST+ après reperfusion : quelle évolution ?","back":"Le sus-décalage **régresse vite** ; persistant si **anévrisme** ; T négative après **48 h**.","prio":"P3","sec":"s21"},{"id":"fc-230-7efe80","poly":"cardio","fiche":"230","front":"Après un SCA ST+ : quel délai de sortie ?","back":"Entre **J3 et J5** (ST- non compliqué : 24-48 h après revascularisation).","prio":"P2","sec":"s21"},{"id":"fc-230-7ea8a1","poly":"cardio","fiche":"230","front":"Après un SCA : quelle ordonnance pour 1 an ?","back":"**Aspirine + P2Y12** (12 mois), **statine forte dose**, ± bêtabloquant et IEC, traitement des FDR.","prio":"P1","sec":"s21"},{"id":"fc-230-82767d","poly":"cardio","fiche":"230","front":"Après un SCA : quel objectif de LDL-C ?","back":"**< 0,55 g/L** et baisse **≥ 50 %**.","prio":"P1","sec":"s21"},{"id":"fc-230-ad1596","poly":"cardio","fiche":"230","front":"Après un SCA, LDL-C hors objectif sous statine maximale : quelle conduite ?","back":"Ajouter **ézétimibe 10 mg**, puis **anti-PCSK9**.","prio":"P2","sec":"s21"},{"id":"fc-230-b584b5","poly":"cardio","fiche":"230","front":"Après un SCA : quand poser un défibrillateur implantable ?","back":"**FEVG < 35 %** persistante à distance (**≥ 6 semaines**) après optimisation.","prio":"P2","sec":"s21"},{"id":"fc-230-da82cc","poly":"cardio","fiche":"230","front":"Après un SCA avec FEVG ≤ 40 % : quels traitements ?","back":"**IEC/ARA2**, **bêtabloquant** ; antagoniste minéralocorticoïde si IC ou diabète.","prio":"P2","sec":"s21"},{"id":"fc-230-3ac6b9","poly":"cardio","fiche":"230","front":"Après un SCA : quelle réadaptation recommander ?","back":"La **réadaptation cardiaque**, recommandée pour tous.","prio":"P2","sec":"s21"},{"id":"fc-231-e7d80c","poly":"cardio","fiche":"231","front":"ECG : que traduit un QRS fin ?","back":"Une activation ventriculaire par les **voies de conduction rapides** (NAV, His, branches, Purkinje).","prio":"P1","sec":"s1"},{"id":"fc-231-9649a9","poly":"cardio","fiche":"231","front":"ECG : que traduit un QRS large ?","back":"Une progression lente **de proche en proche** dans le muscle : **TV** ou **bloc de branche complet**.","prio":"P1","sec":"s1"},{"id":"fc-231-de67ea","poly":"cardio","fiche":"231","front":"Tachycardie régulière à QRS larges : comment la considérer ?","back":"Comme une **TV** jusqu'à preuve du contraire (une TSV avec bloc de branche est possible).","prio":"P1","sec":"s1"},{"id":"fc-231-5e38be","poly":"cardio","fiche":"231","front":"Stimulation du VD par pacemaker : quel aspect de QRS ?","back":"QRS large d'aspect de **BBG**.","prio":"P2","sec":"s1"},{"id":"fc-231-6b270d","poly":"cardio","fiche":"231","front":"Dysfonction sinusale marquée : quel rythme d'échappement apparaît ?","back":"Un **échappement jonctionnel** : pas de P devant le QRS, parfois P rétrograde derrière.","prio":"P2","sec":"s1"},{"id":"fc-231-1db1b7","poly":"cardio","fiche":"231","front":"BAV complet avec échappement à QRS fins : quel siège du bloc ?","back":"**Nodal** (suprahissien).","prio":"P1","sec":"s1"},{"id":"fc-231-dd141e","poly":"cardio","fiche":"231","front":"BAV bas situé : quel échappement et quelles conséquences ?","back":"Échappement à **QRS larges** : bradycardie extrême et **QT long**.","prio":"P3","sec":"s1"},{"id":"fc-231-9b7dbe","poly":"cardio","fiche":"231","front":"ECG : quelle polarité donne un front qui vient vers l'électrode ?","back":"Une onde **positive** (négative s'il s'éloigne ; isodiphasique s'il est perpendiculaire).","prio":"P3","sec":"s1"},{"id":"fc-231-0d45dd","poly":"cardio","fiche":"231","front":"Bloc de branche : quelle orientation de l'onde T est normale ?","back":"En **sens inverse** du QRS (discordance appropriée), à ne pas prendre pour un SCA.","prio":"P1","sec":"s1"},{"id":"fc-231-9f19b6","poly":"cardio","fiche":"231","front":"Dérivations du plan frontal : lesquelles ?","back":"**D1, D2, D3** + **aVR, aVL, aVF** (servent à calculer l'axe).","prio":"P1","sec":"s2"},{"id":"fc-231-ba3897","poly":"cardio","fiche":"231","front":"ECG : quand ajouter V3R et V4R ?","back":"**Parfois**, chez l'**enfant** et en cas de suspicion de **SCA**.","prio":"P2","sec":"s2"},{"id":"fc-231-a882e5","poly":"cardio","fiche":"231","front":"Dérivation de Lewis : à quoi sert-elle ?","back":"À **démasquer une activité atriale** peu visible (lue en D1).","prio":"P3","sec":"s2"},{"id":"fc-231-7683ff","poly":"cardio","fiche":"231","front":"Électrodes V1-V2 posées trop haut : quel aspect peuvent-elles créer ?","back":"Une **pseudonécrose** ou une repolarisation antérieure atypique.","prio":"P2","sec":"s2"},{"id":"fc-231-4dec2f","poly":"cardio","fiche":"231","front":"Territoire inférieur de l'ECG : quelles dérivations ?","back":"**D2, D3, aVF**.","prio":"P1","sec":"s2"},{"id":"fc-231-95e9f4","poly":"cardio","fiche":"231","front":"Territoire antéroseptal de l'ECG : quelles dérivations ?","back":"**V1, V2, V3**.","prio":"P1","sec":"s2"},{"id":"fc-231-6a7251","poly":"cardio","fiche":"231","front":"Territoire latéral haut de l'ECG : quelles dérivations ?","back":"**D1, aVL**.","prio":"P1","sec":"s2"},{"id":"fc-231-ca94ac","poly":"cardio","fiche":"231","front":"Territoire latéral bas de l'ECG : quelles dérivations ?","back":"**V5, V6**.","prio":"P1","sec":"s2"},{"id":"fc-231-c6511f","poly":"cardio","fiche":"231","front":"Territoire postérieur de l'ECG : quelles dérivations ?","back":"**V7, V8, V9**.","prio":"P1","sec":"s2"},{"id":"fc-231-10f3d6","poly":"cardio","fiche":"231","front":"Ventricule droit à l'ECG : quelles dérivations l'explorent ?","back":"**V1, V2, V3R, V4R**.","prio":"P2","sec":"s2"},{"id":"fc-231-a56c4a","poly":"cardio","fiche":"231","front":"Territoire apical de l'ECG : quelle dérivation ?","back":"**V4**.","prio":"P2","sec":"s2"},{"id":"fc-231-2d7904","poly":"cardio","fiche":"231","front":"Axe du QRS : quelles dérivations suffisent pour l'estimer ?","back":"**D1 et aVF** (D2 tranche si D1 positif et aVF négatif).","prio":"P1","sec":"s2"},{"id":"fc-231-1baa19","poly":"cardio","fiche":"231","front":"Axe du QRS : quelles sont les valeurs normales ?","back":"**−30° à +90°**.","prio":"P1","sec":"s2"},{"id":"fc-231-74df90","poly":"cardio","fiche":"231","front":"Axe : D1 positif, aVF négatif, D2 négatif ; que conclure ?","back":"Axe **hypergauche** (au-delà de −30°).","prio":"P2","sec":"s2"},{"id":"fc-231-239827","poly":"cardio","fiche":"231","front":"Axe : D1 négatif et aVF positif ; que conclure ?","back":"Axe **hyperdroit** (+90° à +180°).","prio":"P2","sec":"s2"},{"id":"fc-231-2b39e7","poly":"cardio","fiche":"231","front":"Axe : D1 et aVF négatifs ; que conclure ?","back":"**Axe extrême** (−90° à −180°).","prio":"P2","sec":"s2"},{"id":"fc-231-4069ac","poly":"cardio","fiche":"231","front":"Axe du QRS chez l'obèse ou en cas de cardiomégalie : quelle orientation ?","back":"Cœur **horizontal** : axe proche de **0°** (sujet filiforme : proche de 90°).","prio":"P3","sec":"s2"},{"id":"fc-231-1e480e","poly":"cardio","fiche":"231","front":"D1 négatif avec onde P négative en D1 : à quoi penser d'abord ?","back":"À une **inversion des électrodes** frontales (avant l'HBPG).","prio":"P1","sec":"s2"},{"id":"fc-231-1a0044","poly":"cardio","fiche":"231","front":"Papier ECG à 25 mm/s : que valent un petit et un grand carreau ?","back":"Petit carreau **40 ms** ; grand carreau **200 ms** (1 mm = 0,1 mV).","prio":"P1","sec":"s3"},{"id":"fc-231-a1432e","poly":"cardio","fiche":"231","front":"ECG : comment calculer rapidement la fréquence cardiaque ?","back":"**300 / nombre de grands carreaux** entre deux QRS.","prio":"P1","sec":"s3"},{"id":"fc-231-a8c044","poly":"cardio","fiche":"231","front":"Fréquence cardiaque normale de l'adulte : quelles bornes ?","back":"**60-100 bpm** (bradycardie < 60, tachycardie > 100).","prio":"P1","sec":"s3"},{"id":"fc-231-98f1de","poly":"cardio","fiche":"231","front":"Onde P normale : quelle durée et quelle amplitude ?","back":"Durée **< 120 ms** ; amplitude **< 2,5 mm** en D2.","prio":"P2","sec":"s3"},{"id":"fc-231-517d80","poly":"cardio","fiche":"231","front":"Intervalle PR normal : quelle durée ?","back":"**120 à 200 ms**.","prio":"P1","sec":"s3"},{"id":"fc-231-ff9cca","poly":"cardio","fiche":"231","front":"QRS normal : quelle durée ?","back":"**70 à 110 ms**.","prio":"P1","sec":"s3"},{"id":"fc-231-25730c","poly":"cardio","fiche":"231","front":"Onde Q physiologique : quels critères ?","back":"**< 1/3** du QRS et **< 40 ms**.","prio":"P2","sec":"s3"},{"id":"fc-231-3d5cca","poly":"cardio","fiche":"231","front":"QT corrigé : quelle valeur normale ?","back":"**< 450 ms** à 60 bpm (en pratique 470-480 ms).","prio":"P1","sec":"s3"},{"id":"fc-231-7b5c07","poly":"cardio","fiche":"231","front":"Onde P sinusale : quelle polarité ?","back":"**Positive en D1** et dans les **inférieures** (nœud sinusal en haut à droite de l'OD).","prio":"P1","sec":"s3"},{"id":"fc-231-86c35e","poly":"cardio","fiche":"231","front":"Rythme sinusal : quelle définition ?","back":"Chaque **P suivie d'un QRS** et chaque **QRS précédé d'une P**.","prio":"P1","sec":"s3"},{"id":"fc-231-7a3a18","poly":"cardio","fiche":"231","front":"P sinusales régulières non conduites (BAV3) : s'agit-il d'un rythme sinusal ?","back":"**Non**.","prio":"P2","sec":"s3"},{"id":"fc-231-8d5a30","poly":"cardio","fiche":"231","front":"Intervalle PR : quelle partie de la conduction explore-t-il ?","back":"**Toute la conduction**, de la sortie du nœud sinusal au réseau de Purkinje.","prio":"P2","sec":"s3"},{"id":"fc-231-81eb50","poly":"cardio","fiche":"231","front":"QT : comment le mesurer ?","back":"Du début de Q à la fin de T, là où la T est la plus ample (**souvent V2-V3**), par la **tangente** ; sans l'**onde U**.","prio":"P2","sec":"s3"},{"id":"fc-231-69000a","poly":"cardio","fiche":"231","front":"QTc : quelle formule utiliser ?","back":"**Bazett** : QTc = QT / √RR (RR en secondes).","prio":"P1","sec":"s3"},{"id":"fc-231-2f9cd9","poly":"cardio","fiche":"231","front":"ECG normal : où les ondes T peuvent-elles être négatives ?","back":"**aVR et V1**, parfois **D3 et aVL**.","prio":"P1","sec":"s3"},{"id":"fc-231-80c688","poly":"cardio","fiche":"231","front":"Lecture systématique d'un ECG : quelles 4 étapes ?","back":"**Rythme**, **conduction**, **repolarisation**, **morphologie**.","prio":"P2","sec":"s3"},{"id":"fc-231-6e0aa8","poly":"cardio","fiche":"231","front":"Point J sus-décalé de V1 à V4 chez un homme jeune : que conclure ?","back":"**Repolarisation physiologique**, pas un SCA.","prio":"P1","sec":"s3"},{"id":"fc-231-17fc41","poly":"cardio","fiche":"231","front":"Mesure du QT avec une onde U incluse : quelle erreur ?","back":"Le QT est **surestimé** (ex. hypokaliémie).","prio":"P2","sec":"s3"},{"id":"fc-231-2ebbb3","poly":"cardio","fiche":"231","front":"Bloc de branche : comment déterminer son côté ?","back":"En **V1** : QRS positif = **bloc droit** ; négatif = **bloc gauche**.","prio":"P1","sec":"s4"},{"id":"fc-231-7e3f13","poly":"cardio","fiche":"231","front":"Bloc de branche complet : quelle durée de QRS ?","back":"**> 120 ms**.","prio":"P1","sec":"s4"},{"id":"fc-231-d09fa1","poly":"cardio","fiche":"231","front":"BBD complet : quel aspect ECG ?","back":"V1 : **RsR'** (positif) ; V6 : **qRs** avec S traînante.","prio":"P1","sec":"s4"},{"id":"fc-231-5abd26","poly":"cardio","fiche":"231","front":"BBG complet : quel aspect ECG ?","back":"V1 : **rS ou QS** (négatif) ; V6, D1, aVL : **notch**, R souvent exclusive.","prio":"P1","sec":"s4"},{"id":"fc-231-d7d7d1","poly":"cardio","fiche":"231","front":"Bloc de branche : que décrire avant de parler du bloc ?","back":"Le **rythme atrial** (une TSV associée n'est pas rare).","prio":"P2","sec":"s4"},{"id":"fc-231-de4bc6","poly":"cardio","fiche":"231","front":"Douleur thoracique persistante + BBG : quelle conduite ?","back":"Évoquer un **infarctus antérieur** : avis cardiologique rapide **sans attendre la troponine**.","prio":"P1","sec":"s4"},{"id":"fc-231-d7c061","poly":"cardio","fiche":"231","front":"Hémibloc : sur quoi repose le diagnostic ?","back":"Sur l'**axe** (QRS très modérément élargi > 110 ms + déviation axiale).","prio":"P1","sec":"s4"},{"id":"fc-231-984149","poly":"cardio","fiche":"231","front":"Hémibloc antérieur gauche : quel critère ?","back":"Axe au-delà de **−30°** (D2 négatif) ; **fréquent**.","prio":"P1","sec":"s4"},{"id":"fc-231-aff589","poly":"cardio","fiche":"231","front":"Hémibloc postérieur gauche : quel critère ?","back":"Axe **> +90°** (D1 négatif), sans pathologie du VD, morphologie longiligne ni infarctus latéral ; **rare**.","prio":"P1","sec":"s4"},{"id":"fc-231-5f4393","poly":"cardio","fiche":"231","front":"Bloc bifasciculaire : quelles associations ?","back":"**HBAG + BBD** ou **HBPG + BBD** (QRS > 120 ms).","prio":"P1","sec":"s4"},{"id":"fc-231-298651","poly":"cardio","fiche":"231","front":"Bloc de branche incomplet : quelle durée de QRS ?","back":"Entre **110 et 120 ms**.","prio":"P3","sec":"s4"},{"id":"fc-231-56b2b3","poly":"cardio","fiche":"231","front":"Bloc de branche fonctionnel : quelle définition ?","back":"Bloc qui n'apparaît qu'à partir d'une certaine **fréquence** (en tachycardie ou bradycardie).","prio":"P3","sec":"s4"},{"id":"fc-231-1c113b","poly":"cardio","fiche":"231","front":"Syncope + bloc bifasciculaire : quelle conduite ?","back":"**Hospitalisation en cardiologie avec télémétrie** (risque de BAV complet infrahissien).","prio":"P2","sec":"s4"},{"id":"fc-231-0cca00","poly":"cardio","fiche":"231","front":"Bloc de branche : peut-il donner une bradycardie ?","back":"**Non**.","prio":"P1","sec":"s4"},{"id":"fc-231-4cde8a","poly":"cardio","fiche":"231","front":"Bradycardie : quelles sont les deux structures responsables possibles ?","back":"Le **nœud sinusal** (dysfonction sinusale) ou le **NAV** (BAV 2 ou 3).","prio":"P1","sec":"s5"},{"id":"fc-231-af6fd2","poly":"cardio","fiche":"231","front":"Bradycardie : quelle question pose le diagnostic ?","back":"**Que font les ondes P ?**","prio":"P1","sec":"s5"},{"id":"fc-231-083e0f","poly":"cardio","fiche":"231","front":"Bradycardie avec plus d'ondes P que de QRS : quel diagnostic ?","back":"Un **BAV**.","prio":"P1","sec":"s5"},{"id":"fc-231-38915e","poly":"cardio","fiche":"231","front":"Bradycardie avec P trop lentes ou absentes : quel diagnostic ?","back":"Une **dysfonction sinusale**.","prio":"P1","sec":"s5"},{"id":"fc-231-0333d8","poly":"cardio","fiche":"231","front":"BAV1 : quelle définition ECG ?","back":"PR **constant > 200 ms**, aucune P bloquée.","prio":"P1","sec":"s5"},{"id":"fc-231-72e99a","poly":"cardio","fiche":"231","front":"BAV2 Mobitz 1 : quel aspect et quel siège ?","back":"PR qui **s'allonge progressivement** puis P bloquée (Luciani-Wenckebach) ; **suprahissien**.","prio":"P1","sec":"s5"},{"id":"fc-231-4836c4","poly":"cardio","fiche":"231","front":"BAV2 Mobitz 2 : quel aspect et quel siège ?","back":"PR **constant** puis P bloquée **inopinément** ; **infrahissien**.","prio":"P1","sec":"s5"},{"id":"fc-231-4a914e","poly":"cardio","fiche":"231","front":"BAV 2/1 : comment préciser son siège ?","back":"**Infrahissien** si QRS larges ; **suprahissien** si QRS fins avec du Mobitz 1 à d'autres moments.","prio":"P2","sec":"s5"},{"id":"fc-231-1027bd","poly":"cardio","fiche":"231","front":"BAV3 : quelle définition ECG ?","back":"**Dissociation atrioventriculaire complète** (P dissociées, bien vues en V1).","prio":"P1","sec":"s5"},{"id":"fc-231-4e62bc","poly":"cardio","fiche":"231","front":"Onde P bloquée qui arrive plus tôt que les autres : quel diagnostic évoquer ?","back":"Une **extrasystole atriale bloquée** (et non un BAV2).","prio":"P2","sec":"s5"},{"id":"fc-231-bdad23","poly":"cardio","fiche":"231","front":"Échappement jonctionnel : quel aspect de l'onde P rétrograde ?","back":"Derrière le QRS (dans le ST), **négative en D2**.","prio":"P2","sec":"s5"},{"id":"fc-231-0bf618","poly":"cardio","fiche":"231","front":"Bloc sinoatrial du 2e degré : quel aspect ?","back":"Pause sans P ni QRS valant **le double** de l'intervalle PP normal.","prio":"P3","sec":"s5"},{"id":"fc-231-2f02b1","poly":"cardio","fiche":"231","front":"Maladie de l'oreillette : quel aspect ECG ?","back":"Alternance **FA / bradycardie sinusale** avec **pauses** à l'arrêt de la FA.","prio":"P3","sec":"s5"},{"id":"fc-231-4180e8","poly":"cardio","fiche":"231","front":"FA avec RR devenus constants et lents : quel diagnostic ?","back":"FA + **BAV complet**.","prio":"P3","sec":"s5"},{"id":"fc-231-1b2773","poly":"cardio","fiche":"231","front":"Bradycardie : quel trouble ionique faut-il évoquer ?","back":"L'**hyperkaliémie** (BAV ou dysfonction sinusale).","prio":"P1","sec":"s5"},{"id":"fc-231-2567ed","poly":"cardio","fiche":"231","front":"Tachycardie supraventriculaire : où naît-elle et quel aspect des QRS ?","back":"Au-dessus de la bifurcation du His ; QRS **fins** le plus souvent (larges si bloc de branche).","prio":"P1","sec":"s6"},{"id":"fc-231-ce3112","poly":"cardio","fiche":"231","front":"NAV : quelle propriété le rend vital en cas de tachycardie atriale ?","back":"Sa conduction **décrémentielle** (filtre : sans lui, une FA deviendrait FV).","prio":"P2","sec":"s6"},{"id":"fc-231-60460a","poly":"cardio","fiche":"231","front":"Tachycardie sinusale : quels arguments ?","back":"P **positives en D1, D2, D3, aVF**, fréquence qui varie **progressivement**, contexte d'**hypermétabolisme**.","prio":"P2","sec":"s6"},{"id":"fc-231-4fd73c","poly":"cardio","fiche":"231","front":"TSV non sinusale : comment varie la fréquence ?","back":"Par **« marches d'escalier »**.","prio":"P2","sec":"s6"},{"id":"fc-231-cd85ce","poly":"cardio","fiche":"231","front":"Fibrillation atriale : quel aspect ECG ?","back":"QRS **irrégulièrement irréguliers**, ligne de base en mailles amples ou fine trémulation, 100-200 bpm.","prio":"P1","sec":"s6"},{"id":"fc-231-9ba2ac","poly":"cardio","fiche":"231","front":"Tachycardie complètement irrégulière à QRS fins : quel diagnostic ?","back":"La **FA** est le **seul** diagnostic.","prio":"P1","sec":"s6"},{"id":"fc-231-17406e","poly":"cardio","fiche":"231","front":"Tachycardie irrégulière à QRS larges : quel diagnostic évoquer (hors préexcitation) ?","back":"**FA + bloc de branche**.","prio":"P3","sec":"s6"},{"id":"fc-231-f18f6f","poly":"cardio","fiche":"231","front":"Flutter atrial : quelles caractéristiques ECG ?","back":"Activité atriale **monomorphe** vers **300 bpm**, **sans retour à la ligne isoélectrique** dans au moins une dérivation (dents de scie).","prio":"P1","sec":"s6"},{"id":"fc-231-e415d9","poly":"cardio","fiche":"231","front":"Flutter typique antihoraire : quelle polarité des ondes F ?","back":"**Négatives en D2, D3, aVF**, **positives en V1**.","prio":"P1","sec":"s6"},{"id":"fc-231-aebc35","poly":"cardio","fiche":"231","front":"Flutter typique : quel circuit ?","back":"Réentrée dans l'**OD** par l'**isthme cavotricuspide**.","prio":"P2","sec":"s6"},{"id":"fc-231-bf9547","poly":"cardio","fiche":"231","front":"Flutter : quelle fréquence ventriculaire classique ?","back":"**150 bpm** (conduction 2/1).","prio":"P1","sec":"s6"},{"id":"fc-231-6180e9","poly":"cardio","fiche":"231","front":"Flutter et FA : quel lien ?","back":"**Mêmes facteurs favorisants** ; un même patient peut faire les deux.","prio":"P2","sec":"s6"},{"id":"fc-231-324ff2","poly":"cardio","fiche":"231","front":"Flutter droit vs gauche : lequel est le plus fréquent ?","back":"Le flutter **droit**, beaucoup plus fréquent.","prio":"P3","sec":"s6"},{"id":"fc-231-856058","poly":"cardio","fiche":"231","front":"Tachycardie jonctionnelle (maladie de Bouveret) : quelles caractéristiques ?","back":"**Très régulière**, souvent vers **200 bpm** (130-260).","prio":"P1","sec":"s6"},{"id":"fc-231-73f76c","poly":"cardio","fiche":"231","front":"Réentrée intranodale : que voit-on de l'activité atriale ?","back":"Souvent **invisible**, parfois devinée dans le ST.","prio":"P2","sec":"s6"},{"id":"fc-231-e261d2","poly":"cardio","fiche":"231","front":"Rythme réciproque : quel mécanisme ?","back":"Réentrée par une **voie accessoire** (faisceau de Kent).","prio":"P2","sec":"s6"},{"id":"fc-231-2b218e","poly":"cardio","fiche":"231","front":"Tachycardie jonctionnelle : comment la réduire ?","back":"**Manœuvres vagales** ou **adénosine IV**.","prio":"P2","sec":"s6"},{"id":"fc-231-bf6825","poly":"cardio","fiche":"231","front":"Manœuvres vagales : lesquelles ?","back":"**Valsalva**, compression carotidienne **unilatérale**, grand verre d'**eau froide**.","prio":"P2","sec":"s6"},{"id":"fc-231-73cf55","poly":"cardio","fiche":"231","front":"Compression oculaire : est-elle recommandée ?","back":"**Non** (risque de décollement de rétine du myope).","prio":"P3","sec":"s6"},{"id":"fc-231-0383f1","poly":"cardio","fiche":"231","front":"Adénosine IV : quelles modalités et quelle durée d'effet ?","back":"En **flash IV** ; effet d'**une dizaine de secondes**.","prio":"P3","sec":"s6"},{"id":"fc-231-f40655","poly":"cardio","fiche":"231","front":"Adénosine : quelles contre-indications ?","back":"**Asthme**, **hypotension** ou **HTA non contrôlée** (selon les items), **FA sur voie accessoire**.","prio":"P2","sec":"s6"},{"id":"fc-231-817297","poly":"cardio","fiche":"231","front":"Extrasystole atriale : quel aspect ?","back":"P **précoce** de morphologie différente, puis **QRS fin**.","prio":"P2","sec":"s6"},{"id":"fc-231-d5037a","poly":"cardio","fiche":"231","front":"Extrasystole ventriculaire : quel aspect ?","back":"**QRS large** prématuré ± P' rétrograde.","prio":"P1","sec":"s6"},{"id":"fc-231-3e04cf","poly":"cardio","fiche":"231","front":"Extrasystoles fréquentes ou polymorphes : que rechercher ?","back":"Une **cardiopathie**.","prio":"P2","sec":"s6"},{"id":"fc-231-013c02","poly":"cardio","fiche":"231","front":"Bigéminisme : quelle définition ?","back":"Une extrasystole **1 battement sur 2** (trigéminisme : 1 sur 3).","prio":"P3","sec":"s6"},{"id":"fc-231-d087d5","poly":"cardio","fiche":"231","front":"Flutter conduit en 2/1 : comment démasquer les ondes F ?","back":"Par une **manœuvre vagale** (ralentit transitoirement les ventricules).","prio":"P2","sec":"s6"},{"id":"fc-231-8a4d69","poly":"cardio","fiche":"231","front":"TV : quel risque évolutif ?","back":"**TV → FV → asystolie** (plus de la moitié des morts subites).","prio":"P1","sec":"s7"},{"id":"fc-231-ba0f71","poly":"cardio","fiche":"231","front":"TV : quels mécanismes selon le terrain ?","back":"**Réentrée** : la plus fréquente sur cardiopathie (fibrose) ; **automatisme anormal** : le plus fréquent sur cœur sain.","prio":"P2","sec":"s7"},{"id":"fc-231-bd5779","poly":"cardio","fiche":"231","front":"TV : quels critères ECG de suspicion ?","back":"FC **> 100 bpm** + QRS **> 120 ms** sur au moins **3 battements** consécutifs.","prio":"P1","sec":"s7"},{"id":"fc-231-bb50b1","poly":"cardio","fiche":"231","front":"TV non soutenue vs soutenue : quelle limite ?","back":"Non soutenue : 3 battements à **30 s** ; soutenue : **> 30 s**.","prio":"P1","sec":"s7"},{"id":"fc-231-cfe11a","poly":"cardio","fiche":"231","front":"TV : quels arguments ECG de certitude ?","back":"**Dissociation ventriculoatriale** (plus de QRS que de P), **complexes de capture et de fusion**.","prio":"P1","sec":"s7"},{"id":"fc-231-c40edd","poly":"cardio","fiche":"231","front":"TV : quels arguments en faveur (non formels) ?","back":"**Cardiopathie**, **concordance** V1-V6, **axe extrême** (QRS positif en aVR), aspect atypique de bloc.","prio":"P2","sec":"s7"},{"id":"fc-231-af7639","poly":"cardio","fiche":"231","front":"Fibrillation ventriculaire : quel aspect ECG et quelle conséquence ?","back":"Tachycardie **irrégulière à QRS larges polymorphes** : débit nul, **arrêt cardiaque**.","prio":"P1","sec":"s7"},{"id":"fc-231-228073","poly":"cardio","fiche":"231","front":"Fibrillation ventriculaire : quel geste en premier ?","back":"**Choc électrique immédiat** ; massage en attendant.","prio":"P1","sec":"s7"},{"id":"fc-231-cc88c2","poly":"cardio","fiche":"231","front":"Torsade de pointes : quelle définition ?","back":"TV **polymorphe** qui s'arrête seule ou dégénère en **FV**.","prio":"P2","sec":"s7"},{"id":"fc-231-b06390","poly":"cardio","fiche":"231","front":"Torsade de pointes installée vs FV : comment les distinguer ?","back":"Par le **QT long** sur les tracés antérieurs et le **contexte**.","prio":"P3","sec":"s7"},{"id":"fc-231-802b11","poly":"cardio","fiche":"231","front":"Tachycardie mal tolérée hémodynamiquement : quelle conduite ?","back":"**Cardioversion électrique externe**, quel que soit l'aspect.","prio":"P1","sec":"s7"},{"id":"fc-231-71862e","poly":"cardio","fiche":"231","front":"Tachycardie bien tolérée : quel effet de l'adénosine oriente vers une TV ?","back":"**Aucun effet** (la TV ne dépend pas du NAV).","prio":"P1","sec":"s7"},{"id":"fc-231-363930","poly":"cardio","fiche":"231","front":"Adénosine ou manœuvre vagale qui arrête la tachycardie : quel diagnostic ?","back":"Une **tachycardie jonctionnelle** (réentrée dépendant du NAV).","prio":"P1","sec":"s7"},{"id":"fc-231-25a12b","poly":"cardio","fiche":"231","front":"Adénosine ou manœuvre vagale qui démasque l'activité atriale : quels diagnostics ?","back":"Tachycardie **sinusale**, **flutter**, **tachycardie atriale**.","prio":"P1","sec":"s7"},{"id":"fc-231-e593e2","poly":"cardio","fiche":"231","front":"Dissociation de la TV vs du BAV3 : quelle différence ?","back":"TV : **plus de QRS que de P** ; BAV3 : **plus de P que de QRS**.","prio":"P1","sec":"s7"},{"id":"fc-231-98a38e","poly":"cardio","fiche":"231","front":"Hypertrophie auriculaire droite : quel critère ?","back":"Onde P **> 2,5 mm en D2** (ou > 2 mm en V1-V2).","prio":"P3","sec":"s8"},{"id":"fc-231-f9a30f","poly":"cardio","fiche":"231","front":"Hypertrophie auriculaire gauche : quel critère ?","back":"Onde P **> 110 ms** (120 en pratique), composante négative **> 40 ms en V1**.","prio":"P3","sec":"s8"},{"id":"fc-231-ced348","poly":"cardio","fiche":"231","front":"Indice de Sokolow : quel calcul et quelle norme ?","back":"**S (V1 ou V2) + R (V5 ou V6)** ; normal **< 35 mm**.","prio":"P1","sec":"s8"},{"id":"fc-231-d6d58a","poly":"cardio","fiche":"231","front":"HVG sévère : quels signes de repolarisation ?","back":"**T négatives** avec **sous-ST** en latéral, **disparition de la q septale**.","prio":"P2","sec":"s8"},{"id":"fc-231-cc6c49","poly":"cardio","fiche":"231","front":"HVG électrique : quelles causes les plus fréquentes ?","back":"**HTA**, puis **rétrécissement aortique**.","prio":"P1","sec":"s8"},{"id":"fc-231-8bc704","poly":"cardio","fiche":"231","front":"HVG importante : quels aspects pièges en V1-V2 ?","back":"**QS** (pseudonécrose) et **pseudo sus-décalage de ST**.","prio":"P2","sec":"s8"},{"id":"fc-231-997ba9","poly":"cardio","fiche":"231","front":"HVD : quel est le signe ECG le plus précoce ?","back":"**Axe > 110°** (90° en pratique).","prio":"P3","sec":"s8"},{"id":"fc-231-4fa336","poly":"cardio","fiche":"231","front":"Embolie pulmonaire : quel aspect ECG d'hypertrophie aiguë ?","back":"**S1Q3T3** (S en D1, Q et T négative en D3).","prio":"P3","sec":"s8"},{"id":"fc-231-592c72","poly":"cardio","fiche":"231","front":"Hypokaliémie : quels signes ECG ?","back":"T **plates ou négatives**, **sous-ST**, **QT allongé**, **onde U**.","prio":"P1","sec":"s9"},{"id":"fc-231-ada778","poly":"cardio","fiche":"231","front":"Hypokaliémie : quels troubles du rythme ?","back":"Extrasystoles, TV, **torsade de pointes**, FV.","prio":"P2","sec":"s9"},{"id":"fc-231-6de25c","poly":"cardio","fiche":"231","front":"Hyperkaliémie : quels signes ECG ?","back":"T **amples, pointues, symétriques**, **PR allongé**, **QRS élargi**.","prio":"P1","sec":"s9"},{"id":"fc-231-f5697a","poly":"cardio","fiche":"231","front":"Hyperkaliémie : quels troubles de conduction et du rythme ?","back":"**BAV**, **dysfonction sinusale**, TV.","prio":"P1","sec":"s9"},{"id":"fc-231-46e9ce","poly":"cardio","fiche":"231","front":"QT long : quel risque ?","back":"La **torsade de pointes**.","prio":"P2","sec":"s9"},{"id":"fc-231-3e0a36","poly":"cardio","fiche":"231","front":"QT long : quelles causes ?","back":"**Bradycardie extrême**, **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** associés, QT long **congénital**.","prio":"P1","sec":"s9"},{"id":"fc-231-221d40","poly":"cardio","fiche":"231","front":"QT long sur un ECG : quel réflexe ?","back":"**Vérifier les médicaments** et le **ionogramme**.","prio":"P2","sec":"s9"},{"id":"fc-231-0da2da","poly":"cardio","fiche":"231","front":"Péricardite aiguë : quels signes ECG de la phase 1 ?","back":"**Microvoltage**, sus-ST **concave, diffus, sans miroir**, **sous-décalage de PQ**.","prio":"P2","sec":"s9"},{"id":"fc-231-bbc194","poly":"cardio","fiche":"231","front":"Péricardite aiguë : quelle évolution ECG après la phase 1 ?","back":"T plates, puis **T négatives** persistantes, puis retour progressif à la normale.","prio":"P3","sec":"s9"},{"id":"fc-231-1455bc","poly":"cardio","fiche":"231","front":"Préexcitation (voie accessoire) : quels signes ECG ?","back":"**PR court < 120 ms**, **onde delta**, anomalies de repolarisation.","prio":"P2","sec":"s9"},{"id":"fc-231-ea48bd","poly":"cardio","fiche":"231","front":"Syndrome de Wolff-Parkinson-White : quelle définition ?","back":"**Voie accessoire** antérograde + palpitations par **tachycardie jonctionnelle**.","prio":"P2","sec":"s9"},{"id":"fc-231-86a3c6","poly":"cardio","fiche":"231","front":"FA préexcitée (super-Wolff) : quel aspect ECG ?","back":"Tachycardie **irrégulière, très rapide**, QRS de largeur variable **« en accordéon »**.","prio":"P2","sec":"s9"},{"id":"fc-231-a9ea01","poly":"cardio","fiche":"231","front":"FA préexcitée : quels gestes sont interdits ?","back":"**Bloquer le NAV** : ni massage, ni adénosine (risque de FV).","prio":"P2","sec":"s9"},{"id":"fc-231-0d1e80","poly":"cardio","fiche":"231","front":"SCA ST+ : où se trouve le sus-décalage ?","back":"**En regard de la paroi qui souffre** ; le sous-décalage ailleurs est un **miroir**.","prio":"P1","sec":"s10"},{"id":"fc-231-22219a","poly":"cardio","fiche":"231","front":"Douleur thoracique : quel ECG réaliser ?","back":"Un **ECG 18 dérivations** (+ V7-V9, V3R-V4R).","prio":"P1","sec":"s10"},{"id":"fc-231-4621d8","poly":"cardio","fiche":"231","front":"Ondes T négatives : quand sont-elles pathologiques ?","back":"**Deux T négatives dans un même territoire** (ex. D2 et D3).","prio":"P1","sec":"s10"},{"id":"fc-231-828e2c","poly":"cardio","fiche":"231","front":"T négatives dans toutes les précordiales : quelle étiologie éliminer en premier ?","back":"L'**ischémie myocardique**.","prio":"P2","sec":"s10"},{"id":"fc-231-3215fa","poly":"cardio","fiche":"231","front":"Sus-décalage du ST : quels critères de significativité ?","back":"**≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **au moins 2 dérivations adjacentes**.","prio":"P1","sec":"s10"},{"id":"fc-231-fd542b","poly":"cardio","fiche":"231","front":"Onde de Pardee : quelle définition ?","back":"Sus-décalage du ST qui **englobe l'onde T**.","prio":"P1","sec":"s10"},{"id":"fc-231-e730e9","poly":"cardio","fiche":"231","front":"BBG complet + douleur thoracique aiguë : que faut-il éliminer ?","back":"Un **SCA ST+** (échographie ± coronarographie).","prio":"P1","sec":"s10"},{"id":"fc-231-3c2333","poly":"cardio","fiche":"231","front":"SCA ST+ : comment évolue le sus-décalage avec et sans reperfusion ?","back":"Avec reperfusion : **régression rapide** ; sans : persiste **plusieurs jours** ; indéfiniment si **anévrisme**.","prio":"P2","sec":"s10"},{"id":"fc-231-f667c9","poly":"cardio","fiche":"231","front":"SCA ST+ : quand apparaît l'onde T négative ?","back":"Après **48 h**.","prio":"P2","sec":"s10"},{"id":"fc-231-b9ba85","poly":"cardio","fiche":"231","front":"Ondes Q de nécrose : quand apparaissent-elles et quels critères ?","back":"**En principe** vers la **6ᵉ heure** (parfois plus tôt) ; **≥ 1/3 (ou 1/4)** de l'amplitude du QRS et **> 30-40 ms**.","prio":"P1","sec":"s10"},{"id":"fc-231-7601f4","poly":"cardio","fiche":"231","front":"Ondes Q de nécrose : quel équivalent ECG ?","back":"Le **rabotage** (écrêtement) de l'onde R, surtout décrit en **V2-V3-V4**.","prio":"P3","sec":"s10"},{"id":"fc-231-5a2a1f","poly":"cardio","fiche":"231","front":"SCA sans sus-décalage : quels aspects ECG possibles ?","back":"**Sous-ST**, **T inversées**, **pseudo-normalisation** de T, T aplaties, ou **ECG normal**.","prio":"P1","sec":"s10"},{"id":"fc-231-1aa176","poly":"cardio","fiche":"231","front":"Sus-décalage du ST : quelles sont les 5 causes ?","back":"**SCA**, **anévrisme** ventriculaire, **repolarisation précoce**, **Prinzmetal**, **péricardite**.","prio":"P2","sec":"s10"},{"id":"fc-231-38a5a5","poly":"cardio","fiche":"231","front":"Sus-ST de péricardite vs de SCA : quelle différence ECG ?","back":"Péricardite : **diffus, concave, sans miroir** ; SCA : Pardee **avec miroir**.","prio":"P2","sec":"s10"},{"id":"fc-231-0d87a5","poly":"cardio","fiche":"231","front":"SCA ST+ sans miroir : peut-on conclure à une péricardite ?","back":"**Non** : un SCA ST+ peut manquer de miroir.","prio":"P2","sec":"s10"},{"id":"fc-231-d6a93b","poly":"cardio","fiche":"231","front":"Ondes Q déjà présentes sur un SCA ST+ : la reperfusion est-elle inutile ?","back":"**Non**, elle reste utile.","prio":"P1","sec":"s10"},{"id":"fc-231-05d984","poly":"cardio","fiche":"231","front":"Pacemaker : dans quelles bradycardies est-il indiqué ?","back":"Bradycardies **symptomatiques** ; **BAV infrahissiens** (Mobitz 2, BAV3) **même sans symptôme**.","prio":"P2","sec":"s11"},{"id":"fc-231-707da6","poly":"cardio","fiche":"231","front":"Défibrillateur implantable : quelle fonction en plus de la défibrillation ?","back":"Il fait **toujours pacemaker** (sauf le défibrillateur sous-cutané).","prio":"P3","sec":"s11"},{"id":"fc-231-206912","poly":"cardio","fiche":"231","front":"Resynchronisation cardiaque : quelle indication de principe ?","back":"**BBG** qui désynchronise le VG + **insuffisance cardiaque**.","prio":"P3","sec":"s11"},{"id":"fc-231-84d00d","poly":"cardio","fiche":"231","front":"Spike de stimulation : pourquoi est-il pathognomonique ?","back":"Impulsion de **0,4 à 1 ms**, plus brève que tout phénomène physiologique.","prio":"P3","sec":"s11"},{"id":"fc-231-d6258c","poly":"cardio","fiche":"231","front":"Stimulation bipolaire : quel piège ECG ?","back":"Le spike est **peu visible** et peut passer inaperçu.","prio":"P3","sec":"s11"},{"id":"fc-231-2de4f7","poly":"cardio","fiche":"231","front":"Pacemaker pour BAV : quel aspect ECG après le spike ?","back":"**QRS large d'aspect BBG** (stimulation du VD).","prio":"P2","sec":"s11"},{"id":"fc-231-89b628","poly":"cardio","fiche":"231","front":"Pacemaker pour dysfonction sinusale : quel aspect après le spike ?","back":"Une **onde P** suit le spike (stimulation atriale).","prio":"P3","sec":"s11"},{"id":"fc-231-81d2e5","poly":"cardio","fiche":"231","front":"Pacemaker et SCA : quel piège ECG ?","back":"Le pacemaker peut **masquer** les anomalies ischémiques.","prio":"P2","sec":"s11"},{"id":"fc-231-949492","poly":"cardio","fiche":"231","front":"ECG en urgence : quelles indications ?","back":"**Défaillance d'organe**, **douleur thoracique**, **palpitations**, **syncope**, troubles **K/Ca**.","prio":"P1","sec":"s12"},{"id":"fc-231-b28108","poly":"cardio","fiche":"231","front":"ECG : quelles urgences absolues (item 237) ?","back":"Tachycardie **régulière à QRS larges** ; repolarisation évoquant un **SCA** ; QRS fins **> 150/min** avec signes de gravité.","prio":"P1","sec":"s12"},{"id":"fc-231-eb634f","poly":"cardio","fiche":"231","front":"Monitorage ECG (scope) : quelles indications ?","back":"**Urgences**, réanimation, **transfert médicalisé**, soins intensifs, **syncope** rythmique suspectée, peropératoire.","prio":"P2","sec":"s12"},{"id":"fc-231-12c7c7","poly":"cardio","fiche":"231","front":"ECG 12 dérivations : dans quel bilan est-il obligatoire ?","back":"Le bilan de l'**HTA**.","prio":"P1","sec":"s12"},{"id":"fc-231-babf38","poly":"cardio","fiche":"231","front":"ECG préopératoire : à partir de quel âge ?","back":"Après **65 ans** (ou patient/intervention à risque).","prio":"P2","sec":"s12"},{"id":"fc-231-9abaf7","poly":"cardio","fiche":"231","front":"Holter ECG : quelles caractéristiques ?","back":"**2 à 12 dérivations**, **24 à 96 h**, lu en différé.","prio":"P3","sec":"s12"},{"id":"fc-231-57900c","poly":"cardio","fiche":"231","front":"Holter de 24 h : quelle condition pour l'indiquer devant des symptômes ?","back":"Symptômes **épisodiques** susceptibles de **revenir pendant l'enregistrement**, ECG standard non contributif.","prio":"P3","sec":"s12"},{"id":"fc-231-1a052d","poly":"cardio","fiche":"231","front":"Holter implantable : quelle durée et quelles indications ?","back":"Jusqu'à **3 ans** ; **syncope inexpliquée** ou **FA silencieuse**.","prio":"P3","sec":"s12"},{"id":"fc-231-a892d3","poly":"cardio","fiche":"231","front":"Symptômes rythmiques rares : quel enregistrement proposer ?","back":"ECG ambulatoire jusqu'à **21 jours** ou enregistreur d'événements.","prio":"P3","sec":"s12"},{"id":"fc-231-858c29","poly":"cardio","fiche":"231","front":"Tachycardie (FC > 100/min) : quelle première mesure ?","back":"**Monitorage ECG** continu.","prio":"P2","sec":"s13"},{"id":"fc-231-6b3e5a","poly":"cardio","fiche":"231","front":"Tachycardie bien tolérée à QRS fins : quelle séquence diagnostique ?","back":"**Manœuvres vagales**, puis **adénosine IV** en flash si échec.","prio":"P1","sec":"s13"},{"id":"fc-231-76e929","poly":"cardio","fiche":"231","front":"Flutter d'aspect typique : comment confirmer son caractère typique ?","back":"Par l'**exploration électrophysiologique** qui précède l'**ablation par radiofréquence**.","prio":"P3","sec":"s13"},{"id":"fc-231-56b875","poly":"cardio","fiche":"231","front":"Réentrée intranodale : quel est le traitement de référence au long cours ?","back":"L'**ablation de la voie lente**.","prio":"P2","sec":"s13"},{"id":"fc-231-1e2961","poly":"cardio","fiche":"231","front":"Cardioversion d'une FA : quelle anticoagulation préalable ?","back":"**3 semaines** d'anticoagulation efficace (sauf ETO sans thrombus, FA < 24 h ou urgence vitale).","prio":"P1","sec":"s13"},{"id":"fc-231-f34c20","poly":"cardio","fiche":"231","front":"Après cardioversion d'une FA : combien de temps poursuivre l'anticoagulation ?","back":"**4 semaines au minimum**.","prio":"P1","sec":"s13"},{"id":"fc-231-d205a3","poly":"cardio","fiche":"231","front":"Tachycardie sinusale : quel traitement ?","back":"Traiter la **cause** (nécessaire et le plus souvent suffisant).","prio":"P1","sec":"s13"},{"id":"fc-231-ca4170","poly":"cardio","fiche":"231","front":"Compression carotidienne : quelles contre-indications ?","back":"**Athérome** important ou **souffle carotidien**.","prio":"P3","sec":"s13"},{"id":"fc-231-71ac60","poly":"cardio","fiche":"231","front":"TV suspectée : quelles premières mesures ?","back":"**Alerte (15)**, préparation à la réanimation, **monitorage ECG** continu.","prio":"P1","sec":"s14"},{"id":"fc-231-ba7eed","poly":"cardio","fiche":"231","front":"TV : quel effet des manœuvres vagales et de l'adénosine sur sa fréquence ?","back":"En général **aucun effet**.","prio":"P2","sec":"s14"},{"id":"fc-231-5f4a4d","poly":"cardio","fiche":"231","front":"Après une TV symptomatique : quel dispositif en prévention secondaire ?","back":"Un **défibrillateur automatique implantable**.","prio":"P1","sec":"s14"},{"id":"fc-231-a42543","poly":"cardio","fiche":"231","front":"Fibrillation ventriculaire : peut-elle se réduire spontanément ?","back":"**Jamais**.","prio":"P2","sec":"s14"},{"id":"fc-231-23e93e","poly":"cardio","fiche":"231","front":"FV : dans quel délai délivrer idéalement le premier choc ?","back":"**Dans les 3 minutes** ; à défaut, toujours débuter le massage.","prio":"P1","sec":"s14"},{"id":"fc-231-c9dc48","poly":"cardio","fiche":"231","front":"Massage cardiaque externe : quelles modalités ?","back":"Centre du thorax, **4 à 5 cm**, **100/min**, relais environ toutes les **2 min**.","prio":"P1","sec":"s14"},{"id":"fc-231-1d4f75","poly":"cardio","fiche":"231","front":"Après un choc par DSA : quand vérifier la reprise circulatoire ?","back":"Après **2 minutes** de RCP.","prio":"P2","sec":"s14"},{"id":"fc-231-4d9230","poly":"cardio","fiche":"231","front":"Défibrillateur biphasique : quelle énergie ?","back":"Jusqu'à **200 J** (monophasique : 360 J).","prio":"P3","sec":"s14"},{"id":"fc-231-1d7746","poly":"cardio","fiche":"231","front":"FV réfractaire : quand donner adrénaline et amiodarone ?","back":"Après échec de **2 chocs** : adrénaline + **amiodarone 300 mg**.","prio":"P2","sec":"s14"},{"id":"fc-231-3f2cb1","poly":"cardio","fiche":"231","front":"Arrêt cardiaque : quelle posologie d'adrénaline ?","back":"**1 mg toutes les 4 min** IV.","prio":"P2","sec":"s14"},{"id":"fc-231-d3342d","poly":"cardio","fiche":"231","front":"Lidocaïne dans la FV : quand l'utiliser ?","back":"**Seulement si l'amiodarone n'est pas disponible** (aucun bénéfice démontré).","prio":"P3","sec":"s14"},{"id":"fc-231-53d1ff","poly":"cardio","fiche":"231","front":"Asystolie : faut-il défibriller ?","back":"**Non** : massage.","prio":"P1","sec":"s14"},{"id":"fc-231-0a9d06","poly":"cardio","fiche":"231","front":"Après récupération d'un arrêt cardiaque : quelles mesures ?","back":"Contrôle **thermique** et **glycémique**, éviter hypoxie/hypercapnie, **coronarographie** au moindre doute.","prio":"P2","sec":"s14"},{"id":"fc-231-943f00","poly":"cardio","fiche":"231","front":"Arrêt cardiaque récupéré : quelle est la 1re étiologie ?","back":"La **cardiopathie ischémique**.","prio":"P2","sec":"s14"},{"id":"fc-231-cc1f50","poly":"cardio","fiche":"231","front":"Après arrêt cardiaque par FV récupéré : quel dispositif ?","back":"Un **défibrillateur automatique implantable** (prévention secondaire).","prio":"P1","sec":"s14"},{"id":"fc-231-394d1e","poly":"cardio","fiche":"231","front":"Insuffisant cardiaque à FEVG diminuée : quel seul antiarythmique possible ?","back":"L'**amiodarone**.","prio":"P2","sec":"s14"},{"id":"fc-231-45f364","poly":"cardio","fiche":"231","front":"RCP de l'adulte : quelle place du bouche-à-bouche ?","back":"**Plus recommandé** : le **massage** reste prioritaire.","prio":"P2","sec":"s14"},{"id":"fc-231-0b7785","poly":"cardio","fiche":"231","front":"Thrombolyse préhospitalière dans l'arrêt cardiaque : est-elle recommandée ?","back":"**Non**, sauf au cas par cas (IDM ou EP massive avérés ou fortement suspectés).","prio":"P3","sec":"s14"},{"id":"fc-231-b6bb96","poly":"cardio","fiche":"231","front":"QT long ou torsade de pointes : quels traitements ?","back":"**Corriger les troubles ioniques**, **accélérer la FC**, **arrêter les médicaments** allongeant le QT.","prio":"P2","sec":"s15"},{"id":"fc-231-bffab9","poly":"cardio","fiche":"231","front":"Torsade de pointes : comment accélérer la fréquence cardiaque ?","back":"**Isoprénaline** ou **stimulation** percutanée.","prio":"P2","sec":"s15"},{"id":"fc-231-7a4435","poly":"cardio","fiche":"231","front":"Torsade de pointes : quel sel minéral et quelle dose ?","back":"**Sulfate de magnésium 2 g IV directe**.","prio":"P2","sec":"s15"},{"id":"fc-231-de5e70","poly":"cardio","fiche":"231","front":"Isoprénaline : quelle contre-indication ?","back":"L'**IDM aigu**.","prio":"P2","sec":"s15"},{"id":"fc-231-e29058","poly":"cardio","fiche":"231","front":"Torsade de pointes sur BAV3 : quelle signification ?","back":"Un **signe de gravité** (éviter les médicaments allongeant le QT).","prio":"P3","sec":"s15"},{"id":"fc-231-a19288","poly":"cardio","fiche":"231","front":"FA préexcitée : quel traitement après la phase aiguë ?","back":"L'**ablation de la voie accessoire**.","prio":"P3","sec":"s15"},{"id":"fc-231-c149e7","poly":"cardio","fiche":"231","front":"Sous-décalage du ST de V1 à V3 : quelle conduite ?","back":"Possible **miroir** d'un sus-ST **postérieur** : regarder **V7-V9**.","prio":"P1","sec":"s16"},{"id":"fc-231-9617ea","poly":"cardio","fiche":"231","front":"BBG ou BAV3 à QRS larges chez un douloureux thoracique : quelle limite de l'ECG ?","back":"ECG **non informatif** pour le sus-ST : coronarographie urgente à discuter.","prio":"P2","sec":"s16"},{"id":"fc-231-b981bf","poly":"cardio","fiche":"231","front":"SCA ST+ : quel délai pour préférer l'angioplastie primaire ?","back":"Faisable dans les **120 min**, sinon **fibrinolyse**.","prio":"P1","sec":"s16"},{"id":"fc-231-2ad74c","poly":"cardio","fiche":"231","front":"SCA ST+ : à partir de quand le bénéfice de la reperfusion est-il faible ?","back":"Après la **12ᵉ heure** (voire nul après la 24ᵉ).","prio":"P2","sec":"s16"},{"id":"fc-231-1f4ace","poly":"cardio","fiche":"231","front":"SCA ST+ fibrinolysé : quel P2Y12 ?","back":"**Clopidogrel seul** (charge 300 mg si < 75 ans).","prio":"P1","sec":"s16"},{"id":"fc-231-f0ff93","poly":"cardio","fiche":"231","front":"SCA : quand donner de l'oxygène ?","back":"**Seulement si hypoxémie** (SaO₂ < 90 % ou PaO₂ < 60 mmHg).","prio":"P1","sec":"s16"},{"id":"fc-231-e40a81","poly":"cardio","fiche":"231","front":"SCA : quelle posologie d'aspirine ?","back":"**250 mg IVD** puis **75-100 mg/j**.","prio":"P1","sec":"s16"},{"id":"fc-231-57149f","poly":"cardio","fiche":"231","front":"Bradycardie : quels signes de mauvaise tolérance ?","back":"**Syncope**/lipothymie, angor, **IC**, choc, oligurie, signes neurologiques de bas débit, **torsade**.","prio":"P1","sec":"s17"},{"id":"fc-231-688ddd","poly":"cardio","fiche":"231","front":"BAV3, Mobitz 2 ou BAV de haut degré : quelle orientation ?","back":"**Risque vital** : hospitalisation en **Usic** avec scope.","prio":"P1","sec":"s17"},{"id":"fc-231-c1e06a","poly":"cardio","fiche":"231","front":"Bradycardie : quelles causes aiguës réversibles rechercher ?","back":"**IDM ST+**, **médicament bradycardisant**, **hyperkaliémie**.","prio":"P1","sec":"s17"},{"id":"fc-231-44de2e","poly":"cardio","fiche":"231","front":"Bradycardie mal tolérée : quels traitements d'urgence ?","back":"**Atropine** ou **isoprénaline**, ou **stimulation temporaire**.","prio":"P1","sec":"s17"},{"id":"fc-231-780e2d","poly":"cardio","fiche":"231","front":"Atropine : sur quels troubles conductifs agit-elle ?","back":"**BAV nodaux** et **dysfonction sinusale** seulement (aggrave un bloc infrahissien).","prio":"P2","sec":"s17"},{"id":"fc-231-b71ad7","poly":"cardio","fiche":"231","front":"BAV au cours d'un SCA ST+ inférieur : quelles caractéristiques ?","back":"BAV **nodal**, répond à l'**atropine**, habituellement **transitoire**.","prio":"P1","sec":"s17"},{"id":"fc-231-770d46","poly":"cardio","fiche":"231","front":"BAV au cours d'un SCA ST+ antérieur : quelles caractéristiques ?","back":"BAV **infranodal**, ne répond pas à l'atropine ; souvent **stimulateur définitif**.","prio":"P1","sec":"s17"},{"id":"fc-231-75b9fe","poly":"cardio","fiche":"231","front":"BAV sur IDM inférieur non régressif : quand discuter un stimulateur ?","back":"S'il n'a pas régressé à **J5**.","prio":"P3","sec":"s17"},{"id":"fc-231-f684bc","poly":"cardio","fiche":"231","front":"Bradycardie sans cause curable : quelles indications de stimulateur ?","back":"**Mobitz 2**, **BAV3**, BAV de haut degré ; dysfonction sinusale seulement si **symptomatique**.","prio":"P1","sec":"s17"},{"id":"fc-231-39bfa0","poly":"cardio","fiche":"231","front":"Syncope avec troubles conductifs ou blocs alternants : quelle conduite ?","back":"**Hospitalisation urgente** et recherche d'une **cardiopathie**.","prio":"P1","sec":"s17"},{"id":"fc-231-b6cf3b","poly":"cardio","fiche":"231","front":"Exploration électrophysiologique : quel HV impose un stimulateur ?","back":"**HV ≥ 70 ms**.","prio":"P3","sec":"s17"},{"id":"fc-231-6d4f0a","poly":"cardio","fiche":"231","front":"Resynchronisation cardiaque : quels critères d'indication ?","back":"IC symptomatique (**NYHA II-IV**), **FEVG ≤ 35 %**, **QRS ≥ 130 ms**.","prio":"P2","sec":"s17"},{"id":"fc-231-4b5f62","poly":"cardio","fiche":"231","front":"Syncope chez un cardiaque avec bloc de branche : quelle autre cause évoquer qu'un BAV ?","back":"Une **TV**.","prio":"P1","sec":"s17"},{"id":"fc-231-4b9da6","poly":"cardio","fiche":"231","front":"BAV complet vs dysfonction sinusale : lequel est le plus grave ?","back":"Le **BAV complet** (torsades, asystolie).","prio":"P2","sec":"s17"},{"id":"fc-231-bfc8be","poly":"cardio","fiche":"231","front":"Onde de Pardee : avec quoi ne pas la confondre ?","back":"Avec un **élargissement du QRS**.","prio":"P2","sec":"s18"},{"id":"fc-231-e63e7b","poly":"cardio","fiche":"231","front":"P régulières à fréquence normale : prouvent-elles un rythme sinusal ?","back":"**Non** : BAV3 si elles ne sont pas conduites.","prio":"P2","sec":"s18"},{"id":"fc-231-3bd9b5","poly":"cardio","fiche":"231","front":"SCA ST+ traité par angioplastie : quel inhibiteur P2Y12 et pour quelle durée ?","back":"**Prasugrel** ou **ticagrélor** (clopidogrel si CI) ; **12 mois**.","prio":"P2","sec":"s16"},{"id":"fc-231-171d1f","poly":"cardio","fiche":"231","front":"Inhibiteurs P2Y12 du SCA ST+ : quelles doses de charge et d'entretien ?","back":"Prasugrel **60 mg** puis **10 mg/j** ; ticagrélor **180 mg** puis **90 mg** ×2/j ; clopidogrel **600 mg** puis **75 mg/j**.","prio":"P3","sec":"s16"},{"id":"fc-231-422c84","poly":"cardio","fiche":"231","front":"Prasugrel : quelles restrictions d'emploi ?","back":"CI si **ATCD d'AVC** ; non recommandé après **75 ans** et/ou si poids **< 60 kg**.","prio":"P3","sec":"s16"},{"id":"fc-231-b9a9b0","poly":"cardio","fiche":"231","front":"FV/TV réfractaire : quelle dose d'amiodarone si elle persiste ou récidive après la 1re dose ?","back":"**150 mg** (après 300 mg juste avant le 3ᵉ choc).","prio":"P3","sec":"s14"},{"id":"fc-231-c5412b","poly":"cardio","fiche":"231","front":"Flutters atypiques : quel circuit et quelle fréquence atriale ?","back":"Isthme cavotricuspide **non impliqué** (droits, gauches ou biatriaux) ; **120-320 bpm**, morphologies variables.","prio":"P3","sec":"s6"},{"id":"fc-232-8f5dd6","poly":"cardio","fiche":"232","front":"FA : quelle est sa définition ?","back":"Tachycardie **irrégulière** (arythmie) d'origine **supraventriculaire**.","prio":"P1","sec":"s1"},{"id":"fc-232-aa7a86","poly":"cardio","fiche":"232","front":"FA : à quelle fréquence se fait l'activité électrique des oreillettes ?","back":"**400 à 600/min**, de façon rapide et **désordonnée** (oreillettes sans contraction efficace).","prio":"P1","sec":"s1"},{"id":"fc-232-890dad","poly":"cardio","fiche":"232","front":"FA : quelle structure détermine la fréquence ventriculaire ?","back":"Le **nœud AV**, qui filtre et ne laisse passer qu'une partie des influx, au hasard → rythme ventriculaire **irrégulier**.","prio":"P1","sec":"s1"},{"id":"fc-232-2f1cf8","poly":"cardio","fiche":"232","front":"FA : de quoi dépend le filtrage par le nœud AV ?","back":"Du **système nerveux autonome** et des **médicaments bradycardisants** (cible des freinateurs nodaux).","prio":"P2","sec":"s1"},{"id":"fc-232-61facf","poly":"cardio","fiche":"232","front":"FA « clinique » : sur quel examen et quel critère est-elle retenue ?","back":"**ECG** monopiste ou 12 dérivations : activation atriale anarchique **sans onde P** individualisable.","prio":"P1","sec":"s1"},{"id":"fc-232-3ff0a2","poly":"cardio","fiche":"232","front":"ECG de FA : une durée minimale d'enregistrement de 30 s est-elle encore exigée ?","back":"**Non**, cette durée minimale n'est plus exigée.","prio":"P2","sec":"s1"},{"id":"fc-232-04e6a1","poly":"cardio","fiche":"232","front":"FA évoquée sur la seule photopléthysmographie (montre) : diagnostic valide ?","back":"**Non valide** : il faut un tracé **ECG** (un ECG monopiste connecté convient).","prio":"P1","sec":"s1"},{"id":"fc-232-adcbd3","poly":"cardio","fiche":"232","front":"FA : quelle est sa place parmi les troubles du rythme ?","back":"Le trouble du rythme **le plus fréquent**, **lié à l'âge**.","prio":"P2","sec":"s1"},{"id":"fc-232-69a7dc","poly":"cardio","fiche":"232","front":"FA : combien de patients en France ?","back":"**500 000 à 750 000**.","prio":"P3","sec":"s1"},{"id":"fc-232-03eb7a","poly":"cardio","fiche":"232","front":"FA : comment évolue sa prévalence avec l'âge ?","back":"**Rare avant 50 ans** ; environ **10 %** de la population **après 80 ans**.","prio":"P2","sec":"s1"},{"id":"fc-232-8dce94","poly":"cardio","fiche":"232","front":"Obésité et FA : effet de chaque +5 kg/m² d'IMC ?","back":"Fréquence de la FA augmentée de **30 %**.","prio":"P3","sec":"s1"},{"id":"fc-232-e67a00","poly":"cardio","fiche":"232","front":"FA : quelle part de l'ensemble des AVC lui est due ?","back":"**20 à 25 %** des AVC (par embolie cérébrale).","prio":"P2","sec":"s1"},{"id":"fc-232-dd9d4b","poly":"cardio","fiche":"232","front":"FA et flutter atrial : quel lien ?","back":"La FA peut **succéder** à un flutter (typique ou atypique) ou lui être **associée**.","prio":"P3","sec":"s1"},{"id":"fc-232-83e61f","poly":"cardio","fiche":"232","front":"FA et insuffisance cardiaque : quel lien ?","back":"La FA peut **révéler ou aggraver** une insuffisance cardiaque.","prio":"P2","sec":"s1"},{"id":"fc-232-760980","poly":"cardio","fiche":"232","front":"FA : citer ses 4 conséquences hémodynamiques ?","back":"**Perte de la systole atriale** ; FC mal adaptée à l'effort ; **insuffisance cardiaque** ; risque **thromboembolique**.","prio":"P2","sec":"s1"},{"id":"fc-232-a20012","poly":"cardio","fiche":"232","front":"FA : comment se comporte la fréquence ventriculaire à l'effort ?","back":"Tachycardie irrégulière au repos qui **s'accélère à l'effort**.","prio":"P3","sec":"s1"},{"id":"fc-232-448bd8","poly":"cardio","fiche":"232","front":"FA : où se forme le thrombus et où migre-t-il ?","back":"Dans l'**auricule gauche** (stase) → **circulation systémique** (grande circulation).","prio":"P1","sec":"s1"},{"id":"fc-232-755f59","poly":"cardio","fiche":"232","front":"FA : quel cercle vicieux entretient l'arythmie ?","back":"**Dilatation** atriale (remodelage) qui, à son tour, entretient la FA ; évolution aussi vers la **fibrose** des oreillettes puis, plus tard, du tissu de conduction.","prio":"P3","sec":"s1"},{"id":"fc-232-79cc4d","poly":"cardio","fiche":"232","front":"FA et embolie pulmonaire : cause ou complication ?","back":"L'EP est une **cause** possible de FA, **pas une complication** (les emboles de FA vont dans la grande circulation).","prio":"P1","sec":"s1"},{"id":"fc-232-59aa60","poly":"cardio","fiche":"232","front":"Classification de la FA : définition de la FA paroxystique ?","back":"Retour en sinusal (spontané ou après cardioversion) en **moins de 7 jours**.","prio":"P2","sec":"s2"},{"id":"fc-232-7b7640","poly":"cardio","fiche":"232","front":"Classification de la FA : définition de la FA persistante ?","back":"Retour en sinusal (spontané ou après cardioversion) **au-delà de 7 jours**.","prio":"P2","sec":"s2"},{"id":"fc-232-0eef41","poly":"cardio","fiche":"232","front":"Classification de la FA : définition de la FA permanente ?","back":"Échec ou absence de tentative de cardioversion : stratégie de **contrôle de la fréquence**, on ne cherche plus le sinusal.","prio":"P2","sec":"s2"},{"id":"fc-232-cc415d","poly":"cardio","fiche":"232","front":"Premier épisode de FA : comment le classe-t-on ?","back":"**Pas encore classable**.","prio":"P3","sec":"s2"},{"id":"fc-232-d60d6e","poly":"cardio","fiche":"232","front":"Cardioversion (réduction) : définition ?","back":"Tout geste médical qui rétablit le rythme sinusal : **médicament** ou **choc électrique**.","prio":"P2","sec":"s2"},{"id":"fc-232-900b15","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : définition ?","back":"Coexistence d'une FA **paroxystique** et d'une **dysfonction sinusale** (syndrome bradycardie-tachycardie), surtout chez le **sujet âgé**.","prio":"P2","sec":"s2"},{"id":"fc-232-c4ffb3","poly":"cardio","fiche":"232","front":"FA de cause aiguë (à distinguer des FA récidivantes) : exemples ?","back":"FA **postopératoire**, **infarctus**, infection pulmonaire, **péricardite**…","prio":"P2","sec":"s2"},{"id":"fc-232-870cca","poly":"cardio","fiche":"232","front":"Type de FA (paroxystique, persistante, permanente) : rôle dans l'anticoagulation au long cours ?","back":"**Aucun** : seul compte le risque (**CHA₂DS₂-VA**, terrain).","prio":"P1","sec":"s2"},{"id":"fc-232-325e28","poly":"cardio","fiche":"232","front":"FA : 3 grandes circonstances de découverte ?","back":"**Fortuite** (patient asymptomatique) ; **bilan d'un symptôme** (palpitations, essoufflement récent) ; **complication révélatrice** (AVC, poussée d'IC).","prio":"P1","sec":"s3"},{"id":"fc-232-f6f443","poly":"cardio","fiche":"232","front":"FA : symptômes usuels ?","back":"**Palpitations** ; **dyspnée d'effort** ; **angor fonctionnel** ; **asthénie** inexpliquée.","prio":"P1","sec":"s3"},{"id":"fc-232-f8738a","poly":"cardio","fiche":"232","front":"FA : symptôme trompeur typique de la personne âgée ?","back":"**Chutes inexpliquées** (et lipothymies).","prio":"P1","sec":"s3"},{"id":"fc-232-a26066","poly":"cardio","fiche":"232","front":"FA : autres symptômes trompeurs ?","back":"Incapacité à l'effort, accès de « faiblesse », cœur qui « bat trop lentement », **bouffées de chaleur**, **œdèmes des MI** ; rarement syncope (pause de régularisation).","prio":"P2","sec":"s3"},{"id":"fc-232-0eb32a","poly":"cardio","fiche":"232","front":"FA : valeur du pouls et du récit des palpitations pour le diagnostic ?","back":"**Mal corrélés** à la FA réelle (signes absents ou intermittents) → **ECG indispensable**.","prio":"P1","sec":"s3"},{"id":"fc-232-907927","poly":"cardio","fiche":"232","front":"FA paroxystique : comment la prendre sur le fait ?","back":"**Holter** ou autre monitorage ECG.","prio":"P1","sec":"s3"},{"id":"fc-232-afcdc7","poly":"cardio","fiche":"232","front":"FA : que trouve l'auscultation ?","back":"Bruits du cœur **irréguliers**, rythme plus ou moins rapide.","prio":"P2","sec":"s3"},{"id":"fc-232-abc82c","poly":"cardio","fiche":"232","front":"FA au lit du patient : 4 objectifs de la prise en charge initiale ?","back":"**Tolérance** ; **complication** d'emblée ; **cardiopathie** sous-jacente ; **facteurs déclenchants ou favorisants**.","prio":"P1","sec":"s3"},{"id":"fc-232-dc2653","poly":"cardio","fiche":"232","front":"FA : paramètres de tolérance à évaluer ?","back":"**FC**, **PA**, **diurèse**, **FR**, **état de conscience**.","prio":"P2","sec":"s3"},{"id":"fc-232-271132","poly":"cardio","fiche":"232","front":"FA : complications à rechercher d'emblée ?","back":"**OAP** ou signes d'IC ; **embolie artérielle systémique** (examen des artères + examen neurologique).","prio":"P1","sec":"s3"},{"id":"fc-232-8df615","poly":"cardio","fiche":"232","front":"ECG de FA : aspect des ondes P ?","back":"**Absentes**, remplacées par une activité atriale anarchique.","prio":"P1","sec":"s4"},{"id":"fc-232-b4964a","poly":"cardio","fiche":"232","front":"ECG de FA : aspect de la ligne de base ?","back":"**Trémulations à petites mailles** (habituel) ou FA à **grosses mailles**.","prio":"P2","sec":"s4"},{"id":"fc-232-807c64","poly":"cardio","fiche":"232","front":"ECG de FA : principale caractéristique des QRS ?","back":"Le plus souvent **irréguliers**, et **fins** (largeur le plus souvent < 120 ms).","prio":"P1","sec":"s4"},{"id":"fc-232-5a37c6","poly":"cardio","fiche":"232","front":"FA avec QRS larges : quoi évoquer ?","back":"Un **bloc de branche** associé.","prio":"P1","sec":"s4"},{"id":"fc-232-b5242f","poly":"cardio","fiche":"232","front":"FA avec QRS lents et réguliers : quoi évoquer ?","back":"Une FA associée à un **BAV complet**.","prio":"P1","sec":"s4"},{"id":"fc-232-9cca0d","poly":"cardio","fiche":"232","front":"ECG de FA : que signifient des pauses ?","back":"Pauses ou dysfonction sinusale **de régularisation** (syndrome tachycardie-bradycardie).","prio":"P2","sec":"s4"},{"id":"fc-232-0859ef","poly":"cardio","fiche":"232","front":"FA découverte : bilan biologique de 1re intention ?","back":"**Ionogramme sanguin**, **créatinine**, **TSHus**, **NFS**.","prio":"P1","sec":"s4"},{"id":"fc-232-05ed37","poly":"cardio","fiche":"232","front":"FA : but de l'échocardiographie ?","back":"Rechercher une **cardiopathie sous-jacente**.","prio":"P1","sec":"s4"},{"id":"fc-232-4fd4cc","poly":"cardio","fiche":"232","front":"FA suspectée mais non documentée (ex. bilan d'AVC) : quels moyens ?","back":"**Holter prolongé de 72 h** ; interrogation du **pacemaker ou du DAI** s'il existe.","prio":"P1","sec":"s4"},{"id":"fc-232-8164ed","poly":"cardio","fiche":"232","front":"FA sur cœur normal non captée au holter : quel recours ?","back":"ECG monopistes par **outils connectés** (montre, applications).","prio":"P3","sec":"s4"},{"id":"fc-232-9508f8","poly":"cardio","fiche":"232","front":"Dépistage de routine de la FA à chaque contact médical : pour qui ?","back":"Patient **≥ 65 ans** ou à risque.","prio":"P2","sec":"s4"},{"id":"fc-232-9c55e3","poly":"cardio","fiche":"232","front":"Dépistage organisé de la FA : pour qui ?","back":"Patient **≥ 75 ans**, ou **≥ 65 ans à risque thromboembolique**.","prio":"P2","sec":"s4"},{"id":"fc-232-aa4099","poly":"cardio","fiche":"232","front":"Dépistage systématique de la FA par monitoring prolongé : dans quel bilan ?","back":"Bilan d'une **embolie cryptogénique**.","prio":"P1","sec":"s4"},{"id":"fc-232-574d21","poly":"cardio","fiche":"232","front":"FA : 2 risques majeurs ?","back":"**Insuffisance cardiaque** (cadence rapide et irrégulière) + **embolie artérielle systémique** (caillot de l'OG).","prio":"P1","sec":"s5"},{"id":"fc-232-6377e4","poly":"cardio","fiche":"232","front":"FA très rapide avec état de choc, résistante aux freinateurs : conduite ?","back":"**Cardioversion immédiate par choc électrique externe** (situation très rare), avec prévention thromboembolique obligatoire.","prio":"P1","sec":"s5"},{"id":"fc-232-441c13","poly":"cardio","fiche":"232","front":"FA à grosses mailles : quel piège diagnostique ?","back":"La confondre avec un **flutter atrial**.","prio":"P1","sec":"s5"},{"id":"fc-232-b06a69","poly":"cardio","fiche":"232","front":"FA : asthénie chronique attribuée à la FA ou aux médicaments, quoi évoquer ?","back":"Un **SAOS** méconnu.","prio":"P2","sec":"s5"},{"id":"fc-232-9d3a14","poly":"cardio","fiche":"232","front":"FA : la troponine figure-t-elle dans le bilan biologique de 1re intention du Collège ?","back":"**Non** : ionogramme, créatinine, TSHus, NFS.","prio":"P3","sec":"s5"},{"id":"fc-232-0fdc78","poly":"cardio","fiche":"232","front":"FA : facteurs déclenchants ?","back":"**Hypokaliémie**, **fièvre**, **privation de sommeil**, **réaction vagale**, **alcool** (ivresse) ou substances illicites, **électrocution**.","prio":"P1","sec":"s6"},{"id":"fc-232-a82ec8","poly":"cardio","fiche":"232","front":"FA : facteur prédisposant le plus puissant ?","back":"**L'âge**.","prio":"P2","sec":"s6"},{"id":"fc-232-66d602","poly":"cardio","fiche":"232","front":"FA : facteurs de prédisposition modifiables ?","back":"Obésité, hyperthyroïdie, diabète, HTA, tabac et alcool en excès, **sports de grande endurance**, **SAOS**.","prio":"P2","sec":"s6"},{"id":"fc-232-674b98","poly":"cardio","fiche":"232","front":"FA : première étiologie ?","back":"**HTA** (souvent avec **HVG**, surtout chez le sujet âgé).","prio":"P1","sec":"s6"},{"id":"fc-232-eb6d47","poly":"cardio","fiche":"232","front":"FA : étiologie à toujours rechercher, 2e en fréquence ?","back":"**Valvulopathies**, surtout **mitrales** (plus qu'aortiques).","prio":"P1","sec":"s6"},{"id":"fc-232-519ee0","poly":"cardio","fiche":"232","front":"FA : étiologies cardiaques en dehors de l'HTA et des valvulopathies ?","back":"SCA et séquelles d'infarctus ; **cardiomyopathies** (dilatées, hypertrophiques, restrictives) ; **péricardites** ; chirurgie cardiaque récente ; congénitales (**CIA**).","prio":"P2","sec":"s6"},{"id":"fc-232-a8eda9","poly":"cardio","fiche":"232","front":"FA : étiologies pulmonaires ?","back":"Pneumopathies aiguës ou chroniques, **embolie pulmonaire**, **SAOS**, cœur pulmonaire chronique.","prio":"P2","sec":"s6"},{"id":"fc-232-801cc2","poly":"cardio","fiche":"232","front":"FA : étiologies endocriniennes ?","back":"**Hyperthyroïdie** (cardiothyréose), phéochromocytome.","prio":"P2","sec":"s6"},{"id":"fc-232-10a82c","poly":"cardio","fiche":"232","front":"FA : étiologie rénale ?","back":"**Insuffisance rénale sévère**.","prio":"P3","sec":"s6"},{"id":"fc-232-fa20dd","poly":"cardio","fiche":"232","front":"FA idiopathique : comment est-elle retenue ?","back":"**Par élimination** seulement.","prio":"P2","sec":"s6"},{"id":"fc-232-cc271d","poly":"cardio","fiche":"232","front":"FA idiopathique : poids du terrain génétique ?","back":"Un apparenté du 1er degré en FA augmente de **40 %** la probabilité d'être atteint.","prio":"P3","sec":"s6"},{"id":"fc-232-06212e","poly":"cardio","fiche":"232","front":"FA : quelle comorbidité respiratoire est souvent sous-estimée ?","back":"L'**apnée du sommeil** (SAOS).","prio":"P2","sec":"s6"},{"id":"fc-232-dcbc01","poly":"cardio","fiche":"232","front":"Bilan étiologique de FA : examens non biologiques systématiques ?","back":"**ECG**, **radiographie de thorax**, **échocardiographie transthoracique**.","prio":"P1","sec":"s6"},{"id":"fc-232-1a2a47","poly":"cardio","fiche":"232","front":"Bilan étiologique de FA : examens biologiques ?","back":"**TSHus**, ionogramme, fonction rénale, **bilan hépatique**.","prio":"P2","sec":"s6"},{"id":"fc-232-199d2b","poly":"cardio","fiche":"232","front":"Bilan étiologique de FA : quand demander d'autres examens ?","back":"**Seulement sur signe d'appel**.","prio":"P3","sec":"s6"},{"id":"fc-232-6091ac","poly":"cardio","fiche":"232","front":"FA : HTA difficile à affirmer, quels examens ?","back":"**Automesure** ou **MAPA**, sans hésiter.","prio":"P2","sec":"s6"},{"id":"fc-232-60d5e2","poly":"cardio","fiche":"232","front":"FA : comment rechercher un SAOS ?","back":"**Polygraphie** à encourager, surtout chez l'obèse.","prio":"P2","sec":"s6"},{"id":"fc-232-8e6b40","poly":"cardio","fiche":"232","front":"Cardioversion de FA : pourquoi anticoaguler quel que soit le score ?","back":"Tout retour en sinusal (médicament ou choc) expose à une embolie pendant **au moins 4 semaines** → anticoagulation **obligatoire**.","prio":"P1","sec":"s7"},{"id":"fc-232-b6c8c2","poly":"cardio","fiche":"232","front":"FA + prothèse mécanique ou RM modéré à sévère : calcule-t-on le CHA₂DS₂-VA ?","back":"**Non** : risque thromboembolique d'emblée **très élevé** → anticoagulation d'office par **AVK**.","prio":"P1","sec":"s7"},{"id":"fc-232-b1a61d","poly":"cardio","fiche":"232","front":"FA + cardiomyopathie hypertrophique ou amylose cardiaque : anticoagulation ?","back":"**Systématique**, sans calculer le score : **AOD (ou AVK)**.","prio":"P1","sec":"s7"},{"id":"fc-232-91b0bb","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « C » et points ?","back":"**Congestion** : insuffisance cardiaque clinique, FEVG altérée ou non = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-172267","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « H » et points ?","back":"**HTA**, traitée ou non, équilibrée ou non = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-ea214a","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « A₂ » et points ?","back":"Âge **≥ 75 ans** = **2 points**.","prio":"P1","sec":"s7"},{"id":"fc-232-b0638c","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « D » et points ?","back":"**Diabète**, traité ou non, équilibré ou non = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-224e51","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « S₂ » et points ?","back":"**Stroke** : AVC ou embolie artérielle = **2 points**.","prio":"P1","sec":"s7"},{"id":"fc-232-bbc246","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « V » et points ?","back":"Atteinte **vasculaire** : coronaropathie, AOMI, athérome des troncs cérébraux = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-0e26a2","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « A » (seul) et points ?","back":"Âge **65-74 ans** = **1 point**.","prio":"P1","sec":"s7"},{"id":"fc-232-64301b","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : score maximal ?","back":"**8** points.","prio":"P3","sec":"s7"},{"id":"fc-232-00579b","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : risque embolique annuel selon le score ?","back":"De **1 à 18 %** pour un score de 0 à 8, de façon exponentielle (en gros **+ 2 %** par point).","prio":"P2","sec":"s7"},{"id":"fc-232-a6ce7e","poly":"cardio","fiche":"232","front":"FA : 2 facteurs qui augmentent le risque embolique sans compter dans le CHA₂DS₂-VA ?","back":"**SAOS** et **insuffisance rénale sévère**.","prio":"P2","sec":"s7"},{"id":"fc-232-a3d60d","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : le sexe féminin compte-t-il ?","back":"**Non** (le type de FA non plus).","prio":"P1","sec":"s7"},{"id":"fc-232-cc49e0","poly":"cardio","fiche":"232","front":"FA, CHA₂DS₂-VA = 0 : conduite antithrombotique ?","back":"**Pas d'antithrombotique**.","prio":"P1","sec":"s7"},{"id":"fc-232-e4a29a","poly":"cardio","fiche":"232","front":"FA, CHA₂DS₂-VA = 1 : conduite antithrombotique ?","back":"Anticoagulant **conseillé**, décidé **au cas par cas avec le patient** (bénéfice/risque) ; AOD (ou AVK).","prio":"P1","sec":"s7"},{"id":"fc-232-37ef84","poly":"cardio","fiche":"232","front":"FA, CHA₂DS₂-VA > 1 : conduite antithrombotique ?","back":"Anticoagulant oral **indiscutable** ; AOD (ou AVK).","prio":"P1","sec":"s7"},{"id":"fc-232-ce998a","poly":"cardio","fiche":"232","front":"FA sans valve mécanique ni RM : AOD ou AVK en priorité ?","back":"**AOD à favoriser** par rapport aux AVK.","prio":"P1","sec":"s7"},{"id":"fc-232-fd50db","poly":"cardio","fiche":"232","front":"FA : quel risque évaluer systématiquement avant d'anticoaguler ?","back":"Le **risque hémorragique** (balance bénéfice/risque).","prio":"P1","sec":"s7"},{"id":"fc-232-c93c7d","poly":"cardio","fiche":"232","front":"Insuffisant cardiaque en FA : score recommandé (item 234) pour le risque hémorragique ?","back":"**HAS-BLED**.","prio":"P2","sec":"s7"},{"id":"fc-232-79c252","poly":"cardio","fiche":"232","front":"FA isolée sans cardiopathie ni comorbidité : niveau de risque embolique ?","back":"**Très faible**.","prio":"P2","sec":"s7"},{"id":"fc-232-e0ae2a","poly":"cardio","fiche":"232","front":"FA après choc électrique en urgence : durée minimale d'anticoagulation ?","back":"Anticoagulant oral **au moins 4 semaines**, puis réévaluation du risque chronique (**CHA₂DS₂-VA**).","prio":"P1","sec":"s8"},{"id":"fc-232-9ecec1","poly":"cardio","fiche":"232","front":"Cardioversion de FA en urgence : quel anticoagulant ?","back":"**Héparine ou anticoagulant oral** ; AOD utilisable d'emblée s'il n'y en a pas déjà un efficace (sauf CI).","prio":"P2","sec":"s8"},{"id":"fc-232-5f5e12","poly":"cardio","fiche":"232","front":"Premier épisode de FA bien toléré : quel anticoagulant ?","back":"**AOD d'emblée** (sauf CI) ; les **HBPM ne sont pas approuvées** dans cette indication.","prio":"P2","sec":"s8"},{"id":"fc-232-6d1422","poly":"cardio","fiche":"232","front":"Premier épisode de FA : comment ralentir au départ ?","back":"**Freinateur nodal** : bêtabloquant, vérapamil ou diltiazem, digoxine.","prio":"P2","sec":"s8"},{"id":"fc-232-1d158f","poly":"cardio","fiche":"232","front":"Premier épisode de FA sans retour spontané en sinusal : conduite ?","back":"**Cardioversion programmée**, mêmes règles que la FA persistante (3 semaines d'anticoagulation ou ETO).","prio":"P2","sec":"s8"},{"id":"fc-232-527670","poly":"cardio","fiche":"232","front":"Premier épisode de FA réduit : poursuit-on un antiarythmique ?","back":"**Non**, habituellement ; anticoagulation poursuivie selon le terrain (CHA₂DS₂-VA).","prio":"P2","sec":"s8"},{"id":"fc-232-f7497e","poly":"cardio","fiche":"232","front":"Vérapamil et diltiazem : contre-indication majeure dans la FA ?","back":"**Insuffisance cardiaque**.","prio":"P1","sec":"s8"},{"id":"fc-232-3c2873","poly":"cardio","fiche":"232","front":"Cardioversion programmée : durée d'anticoagulation préalable ?","back":"**Au moins 3 semaines**, efficace et **documentée** (héparine ou anticoagulant oral) ; les points clés disent **3 à 4 semaines**.","prio":"P1","sec":"s9"},{"id":"fc-232-e57a69","poly":"cardio","fiche":"232","front":"Cardioversion programmée : 2 situations qui permettent de raccourcir le délai d'anticoagulation ?","back":"**ETO sans thrombus** dans l'oreillette gauche ; FA débutée de façon **certaine il y a < 24 h** (rare).","prio":"P1","sec":"s9"},{"id":"fc-232-51543c","poly":"cardio","fiche":"232","front":"Cardioversion programmée : quand faire une ETO en plus de l'anticoagulation ?","back":"Risque très élevé (**valve mécanique mitrale**, **RM**) ou anticoagulation préalable incertaine/mal documentée.","prio":"P2","sec":"s9"},{"id":"fc-232-1c4c0c","poly":"cardio","fiche":"232","front":"Cardioversion programmée : modalités ?","back":"**Choc électrique externe sous anesthésie générale** et/ou **antiarythmique** (combinables).","prio":"P2","sec":"s9"},{"id":"fc-232-1ff785","poly":"cardio","fiche":"232","front":"Cardioversion médicamenteuse : antiarythmiques cités ?","back":"**Amiodarone**, **flécaïnide**.","prio":"P2","sec":"s9"},{"id":"fc-232-70507b","poly":"cardio","fiche":"232","front":"Après une cardioversion de FA : durée minimale d'anticoagulation ?","back":"**Au moins 4 semaines**, puis décision selon le risque chronique (CHA₂DS₂-VA).","prio":"P1","sec":"s9"},{"id":"fc-232-0d1e25","poly":"cardio","fiche":"232","front":"Risque embolique après cardioversion médicamenteuse : différent du choc ?","back":"**Non** : même risque, que la cardioversion soit médicamenteuse ou électrique.","prio":"P1","sec":"s9"},{"id":"fc-232-188bbd","poly":"cardio","fiche":"232","front":"FA persistante en attente de cardioversion : quel traitement associer à l'anticoagulation ?","back":"**Ralentir** la cadence ventriculaire par un **bradycardisant** (freinateur nodal).","prio":"P2","sec":"s9"},{"id":"fc-232-2cd13f","poly":"cardio","fiche":"232","front":"FA persistante après cardioversion : quelle stratégie ensuite ?","back":"**Contrôle du rythme**.","prio":"P3","sec":"s9"},{"id":"fc-232-7616b4","poly":"cardio","fiche":"232","front":"Flécaïnide : contre-indication dans la FA ?","back":"**Insuffisance cardiaque** (et coronarien : amiodarone seule).","prio":"P1","sec":"s9"},{"id":"fc-232-2f16b5","poly":"cardio","fiche":"232","front":"Cardioversion guidée par ETO chez un non anticoagulé : quel anticoagulant pendant le geste ?","back":"**HNF** ; anticoagulant oral débuté **le jour même**, pour **au moins 4 semaines**.","prio":"P2","sec":"s9"},{"id":"fc-232-789cc9","poly":"cardio","fiche":"232","front":"Cardioversion guidée par ETO : rôle des héparines ?","back":"Anticoagulant **d'action rapide**, le plus souvent en attendant que l'anticoagulant oral soit efficace.","prio":"P3","sec":"s9"},{"id":"fc-232-f55101","poly":"cardio","fiche":"232","front":"ETO sans thrombus avant cardioversion : de quoi dispense-t-elle ?","back":"Des 3 semaines d'anticoagulation **avant**, **jamais** des 4 semaines **après**.","prio":"P1","sec":"s9"},{"id":"fc-232-41e578","poly":"cardio","fiche":"232","front":"AOD : 3 situations où ils ne remplacent pas les AVK ?","back":"**Valve mécanique**, **insuffisance rénale sévère**, **SAPL triple positif**.","prio":"P1","sec":"s10"},{"id":"fc-232-b95a0c","poly":"cardio","fiche":"232","front":"AOD : délai d'action et relais ?","back":"Efficace environ **2 h** après la 1re prise → **pas de relais** par héparine.","prio":"P2","sec":"s10"},{"id":"fc-232-b8d568","poly":"cardio","fiche":"232","front":"AOD chez le sujet de plus de 80 ans : particularité ?","back":"Souvent **dose réduite**.","prio":"P3","sec":"s10"},{"id":"fc-232-611596","poly":"cardio","fiche":"232","front":"Dabigatran : mécanisme ?","back":"**Anti-IIa** (inhibiteur de la thrombine).","prio":"P2","sec":"s10"},{"id":"fc-232-2d6741","poly":"cardio","fiche":"232","front":"Dabigatran : antidote ?","back":"**Idarucizumab**.","prio":"P1","sec":"s10"},{"id":"fc-232-3e60d5","poly":"cardio","fiche":"232","front":"Rivaroxaban et apixaban : mécanisme ?","back":"**Inhibiteurs du facteur Xa**.","prio":"P2","sec":"s10"},{"id":"fc-232-e26d4f","poly":"cardio","fiche":"232","front":"AOD : nombre de prises par jour ?","back":"Dabigatran **2** ; rivaroxaban **1** ; apixaban **2** (la plupart des indications).","prio":"P3","sec":"s10"},{"id":"fc-232-c52084","poly":"cardio","fiche":"232","front":"Dabigatran : en dessous de quelle clairance (Cockcroft) est-il déconseillé ?","back":"**< 30 à 25 mL/min**.","prio":"P3","sec":"s10"},{"id":"fc-232-065d2c","poly":"cardio","fiche":"232","front":"AVK : molécule de référence et place de la fluindione ?","back":"**Warfarine** ; fluindione en **2e intention** seulement (instauration déconseillée par l'ANSM).","prio":"P2","sec":"s10"},{"id":"fc-232-1dfa0b","poly":"cardio","fiche":"232","front":"Fluindione : effet indésirable spécifique cité ?","back":"**Atteinte rénale immunoallergique**.","prio":"P3","sec":"s10"},{"id":"fc-232-a78044","poly":"cardio","fiche":"232","front":"AVK dans la FA (hors valve mécanique) : INR cible ?","back":"**2,5 (2 à 3)**.","prio":"P1","sec":"s10"},{"id":"fc-232-f9884d","poly":"cardio","fiche":"232","front":"AVK et grossesse ?","back":"**Tératogènes** : contre-indiqués au 1er trimestre.","prio":"P2","sec":"s10"},{"id":"fc-232-419e24","poly":"cardio","fiche":"232","front":"AOD : 3 avantages sur les AVK ?","back":"**Action rapide** ; **pas de surveillance biologique** ; beaucoup moins d'**hémorragies intracrâniennes**.","prio":"P2","sec":"s10"},{"id":"fc-232-1f42de","poly":"cardio","fiche":"232","front":"AOD : 3 inconvénients ?","back":"**Accumulation si insuffisance rénale** ; observance difficile à vérifier ; un peu plus d'hémorragies **digestives et génitales**.","prio":"P2","sec":"s10"},{"id":"fc-232-0c1a1c","poly":"cardio","fiche":"232","front":"Sous AOD : TCA, TP et INR mesurent-ils l'efficacité ?","back":"**Non** : perturbés mais non interprétables ; **pas de test biologique** de routine.","prio":"P1","sec":"s10"},{"id":"fc-232-7b0135","poly":"cardio","fiche":"232","front":"FA + valve mécanique ou RM modéré à sévère : quel anticoagulant ?","back":"**AVK seuls** ; **AOD contre-indiqués** (CI absolue).","prio":"P1","sec":"s11"},{"id":"fc-232-fdeb31","poly":"cardio","fiche":"232","front":"FA sur prothèse mécanique : quelle complication valvulaire vérifier ?","back":"L'absence de **thrombose de valve**.","prio":"P3","sec":"s11"},{"id":"fc-232-316f24","poly":"cardio","fiche":"232","front":"FA valvulaire (prothèse ou RM) : stratégie souvent retenue et pourquoi ?","back":"**Contrôle de la fréquence** : l'oreillette dilatée tient mal le rythme sinusal.","prio":"P2","sec":"s11"},{"id":"fc-232-c97119","poly":"cardio","fiche":"232","front":"AVK : délai d'efficacité et conséquence à l'instauration ?","back":"Efficaces après **4 à 6 jours** → débuter dès J1 **sous héparine**.","prio":"P2","sec":"s11"},{"id":"fc-232-3b9af7","poly":"cardio","fiche":"232","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"Après **au moins 4 à 5 jours** de chevauchement **et 2 INR** efficaces à 24 h d'intervalle.","prio":"P1","sec":"s11"},{"id":"fc-232-6e9633","poly":"cardio","fiche":"232","front":"AVK sur valve mécanique mitrale ou à disque : INR cible ?","back":"**3 à 4,5** (texte) ; les points clés donnent **3,7** pour la valve mécanique mitrale.","prio":"P2","sec":"s11"},{"id":"fc-232-e13441","poly":"cardio","fiche":"232","front":"Fermeture percutanée de l'auricule gauche : rationnel et technique ?","back":"Les thrombi naissent surtout dans l'**auricule gauche** ; dispositif posé par voie veineuse et **cathétérisme transseptal**.","prio":"P3","sec":"s11"},{"id":"fc-232-cca5d3","poly":"cardio","fiche":"232","front":"Fermeture percutanée de l'auricule gauche : indication ?","back":"FA sans prothèse mécanique ni RM modéré à sévère, **CHA₂DS₂-VA ≥ 2**, CI **formelle et permanente** aux anticoagulants, validée en **comité pluridisciplinaire**.","prio":"P2","sec":"s11"},{"id":"fc-232-dfc6cf","poly":"cardio","fiche":"232","front":"Fermeture chirurgicale de l'auricule chez un patient en FA opéré du cœur : dispense-t-elle de l'anticoagulation ?","back":"**Non**, l'anticoagulation est **maintenue**.","prio":"P1","sec":"s11"},{"id":"fc-232-1af820","poly":"cardio","fiche":"232","front":"Contrôle de la fréquence dans la FA : principe ?","back":"**Ralentir** les ventricules en gardant la FA (freinateurs nodaux : bêtabloquants, vérapamil/diltiazem, digitaliques).","prio":"P2","sec":"s12"},{"id":"fc-232-d196e6","poly":"cardio","fiche":"232","front":"Contrôle de la fréquence : objectif et moyen de vérification ?","back":"**FC < 110 bpm** lors d'une marche normale de 5 min, vérifiée par **holter**.","prio":"P2","sec":"s12"},{"id":"fc-232-84da41","poly":"cardio","fiche":"232","front":"Contrôle du rythme dans la FA : moyens ?","back":"Antiarythmiques (**amiodarone**, **flécaïnide**, **propafénone**) ; **ablation par cathéter** (isolation des veines pulmonaires).","prio":"P2","sec":"s12"},{"id":"fc-232-db5691","poly":"cardio","fiche":"232","front":"FA chez le coronarien et/ou l'insuffisant cardiaque : quel antiarythmique ?","back":"**Amiodarone seule**.","prio":"P1","sec":"s12"},{"id":"fc-232-ccf966","poly":"cardio","fiche":"232","front":"FA permanente : cardioversion ou contrôle du rythme ?","back":"**Non, par définition** : contrôle de la fréquence si nécessaire.","prio":"P2","sec":"s12"},{"id":"fc-232-a764da","poly":"cardio","fiche":"232","front":"FA paroxystique (tableau 13.2) : contrôle de la fréquence et du rythme ?","back":"**Oui, le plus souvent** pour les deux (souvent antiarythmique + bêtabloquant).","prio":"P3","sec":"s12"},{"id":"fc-232-ba513b","poly":"cardio","fiche":"232","front":"FA paroxystique : place de l'ablation par cathéter ?","back":"Recommandée **en 1re ligne**, à égalité avec un antiarythmique, selon le patient ; meilleur maintien du sinusal à long terme.","prio":"P2","sec":"s12"},{"id":"fc-232-4209ab","poly":"cardio","fiche":"232","front":"FA : ablation recommandée si l'on suspecte quelle atteinte du VG induite par la FA ?","back":"**Tachycardiomyopathie** (dysfonction systolique VG induite par la FA) ; ablation à considérer chez certains insuffisants cardiaques à FE altérée.","prio":"P2","sec":"s12"},{"id":"fc-232-a0f5fb","poly":"cardio","fiche":"232","front":"FA sur cœur normal : profil typique ?","back":"Sujet d'**âge mûr** (quinquagénaire), FA souvent **paroxystique**, sans cardiopathie ni comorbidité, échocardiographie **normale**.","prio":"P2","sec":"s12"},{"id":"fc-232-325d2e","poly":"cardio","fiche":"232","front":"FA sur cœur normal : quels diagnostics éliminer ?","back":"**HTA** et **SAOS**.","prio":"P2","sec":"s12"},{"id":"fc-232-c4686b","poly":"cardio","fiche":"232","front":"FA paroxystique sur cœur normal : évolution habituelle ?","back":"En quelques mois ou années vers une forme **persistante** (parfois persistante d'emblée).","prio":"P3","sec":"s12"},{"id":"fc-232-f40ce2","poly":"cardio","fiche":"232","front":"FA sur cœur normal : antiarythmique de 1re intention pour maintenir le sinusal ?","back":"**Flécaïnide** ; **ablation** envisageable après information éclairée.","prio":"P2","sec":"s12"},{"id":"fc-232-acc0f9","poly":"cardio","fiche":"232","front":"FA sur cœur normal avec CHA₂DS₂-VA = 0 : anticoagulant au long cours ?","back":"**Non** (risque embolique très faible).","prio":"P2","sec":"s12"},{"id":"fc-232-84d1c1","poly":"cardio","fiche":"232","front":"Amiodarone : effets indésirables à expliquer au patient ?","back":"**Thyroïde**, **photosensibilisation**, **dépôts cornéens**.","prio":"P2","sec":"s12"},{"id":"fc-232-c271d8","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque en urgence : comment ralentir et à quelle condition ?","back":"**Digoxine IV**, seulement si la **kaliémie est normale**.","prio":"P1","sec":"s13"},{"id":"fc-232-dcf3d4","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : délai de la cardioversion ?","back":"**Différée** le temps d'une anticoagulation efficace ; contrôle de la fréquence en attendant.","prio":"P2","sec":"s13"},{"id":"fc-232-ad8667","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : échec du maintien du sinusal, conduite ?","back":"On **respecte la FA** et on contrôle la fréquence par **bêtabloquants**.","prio":"P2","sec":"s13"},{"id":"fc-232-83bf5e","poly":"cardio","fiche":"232","front":"FA + poussée d'insuffisance cardiaque : bêtabloquant ?","back":"**Pas d'introduction** pendant la poussée ; s'il est déjà pris, arrêt ou baisse en général.","prio":"P2","sec":"s13"},{"id":"fc-232-3b36b4","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : durée de l'anticoagulation ?","back":"Avant la cardioversion puis **au long cours dans tous les cas**.","prio":"P2","sec":"s13"},{"id":"fc-232-a1cbc3","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : la FA est-elle cause ou conséquence ?","back":"On ne le sait **pas toujours** ; FA souvent **persistante**.","prio":"P3","sec":"s13"},{"id":"fc-232-8ad8bd","poly":"cardio","fiche":"232","front":"FA révélée par un infarctus cérébral : terrain typique ?","back":"Souvent **femme âgée**, FA méconnue, **HTA mal équilibrée ou diabète** ; embolie souvent **sylvienne superficielle gauche**.","prio":"P2","sec":"s13"},{"id":"fc-232-0edf4b","poly":"cardio","fiche":"232","front":"FA révélée par un AVC : prise en charge initiale ?","back":"**Imagerie cérébrale** obligatoire ; **unité neurovasculaire** ; discussion **thrombolyse** ou **thromboaspiration**.","prio":"P2","sec":"s13"},{"id":"fc-232-85f3eb","poly":"cardio","fiche":"232","front":"Infarctus cérébral sur FA à la phase aiguë : AVK ou héparine ?","back":"**Ni AVK ni héparine** (risque de transformation hémorragique).","prio":"P1","sec":"s13"},{"id":"fc-232-c28641","poly":"cardio","fiche":"232","front":"Infarctus cérébral sur FA : anticoagulation à la sortie ?","back":"**Impérative** au long cours (S₂ = 2 points au CHA₂DS₂-VA).","prio":"P2","sec":"s13"},{"id":"fc-232-313290","poly":"cardio","fiche":"232","front":"FA à la phase aiguë d'un infarctus avec décompensation hémodynamique : conduite ?","back":"**Cardioversion électrique immédiate**.","prio":"P1","sec":"s14"},{"id":"fc-232-aa7a41","poly":"cardio","fiche":"232","front":"FA après SCA : association antithrombotique par défaut ?","back":"**Anticoagulant oral à pleine dose + clopidogrel pendant 12 mois** (éviter les saignements de la trithérapie).","prio":"P1","sec":"s14"},{"id":"fc-232-d52a1a","poly":"cardio","fiche":"232","front":"FA après SCA : quand une trithérapie est-elle possible ?","back":"**Faible risque hémorragique** + **haut risque ischémique**, sur une durée limitée (habituellement **1 mois**).","prio":"P1","sec":"s14"},{"id":"fc-232-11e462","poly":"cardio","fiche":"232","front":"FA après SCA : traitement antithrombotique après 1 an ?","back":"**Anticoagulant seul**.","prio":"P1","sec":"s14"},{"id":"fc-232-b98d75","poly":"cardio","fiche":"232","front":"FA après SCA : posologie du clopidogrel ?","back":"**75 mg/j**.","prio":"P2","sec":"s14"},{"id":"fc-232-e6fb7b","poly":"cardio","fiche":"232","front":"FA après SCA en trithérapie : posologie de l'aspirine ?","back":"**75-100 mg/j** per os.","prio":"P2","sec":"s14"},{"id":"fc-232-547046","poly":"cardio","fiche":"232","front":"FA après SCA : quand ajouter un IPP ?","back":"Risque d'hémorragie digestive élevé : âge **≥ 65 ans**, antécédent d'**ulcère**, **corticothérapie** au long cours…","prio":"P2","sec":"s14"},{"id":"fc-232-c19d01","poly":"cardio","fiche":"232","front":"Sous anticoagulant : quelle classe médicamenteuse éviter ?","back":"Les **anti-inflammatoires** (majorent le risque hémorragique).","prio":"P2","sec":"s14"},{"id":"fc-232-8fadc6","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : que documenter ?","back":"L'**alternance** FA paroxystique rapide / bradycardie sinusale (sujet âgé, asymptomatique ou lipothymies/syncopes).","prio":"P3","sec":"s15"},{"id":"fc-232-7a40da","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : pourquoi les bradycardisants sont-ils périlleux ?","back":"Ils **aggravent la dysfonction sinusale**.","prio":"P2","sec":"s15"},{"id":"fc-232-8cf8ce","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : indications du stimulateur définitif ?","back":"Pauses sinusales symptomatiques (en règle **> 3 s**) ou bradycardie sinusale symptomatique **non iatrogène** (en pratique **< 50 bpm**).","prio":"P2","sec":"s15"},{"id":"fc-232-c91b97","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette avec pause de réduction symptomatique : quel geste considérer ?","back":"**Ablation des veines pulmonaires**.","prio":"P3","sec":"s15"},{"id":"fc-232-e6daf5","poly":"cardio","fiche":"232","front":"AVK : mode d'action ?","back":"Inhibent les facteurs **vitamine K-dépendants** : **II, VII, IX, X**.","prio":"P2","sec":"s16"},{"id":"fc-232-6df8cf","poly":"cardio","fiche":"232","front":"AVK équilibré : fréquence de l'INR ?","back":"**Au moins 1 fois/mois**, résultats notés dans un **carnet**.","prio":"P1","sec":"s16"},{"id":"fc-232-3a5738","poly":"cardio","fiche":"232","front":"AVK à l'instauration : rythme des INR ?","back":"2/semaine de J0 à J14, 1/semaine jusqu'à J30, 1/2 semaines jusqu'à J60, puis **au moins 1/mois**.","prio":"P3","sec":"s16"},{"id":"fc-232-57038f","poly":"cardio","fiche":"232","front":"AVK : quand un patient est-il dit équilibré ?","back":"**Au moins 70 %** des INR dans la cible.","prio":"P2","sec":"s16"},{"id":"fc-232-53ecfa","poly":"cardio","fiche":"232","front":"Automesure de l'INR : chez qui est-elle remboursée ?","back":"Porteurs de **valve mécanique**.","prio":"P3","sec":"s16"},{"id":"fc-232-8b2402","poly":"cardio","fiche":"232","front":"AOD : surveillance ?","back":"Efficacité **clinique** + **fonction rénale au moins 1 fois/an**.","prio":"P1","sec":"s16"},{"id":"fc-232-837a63","poly":"cardio","fiche":"232","front":"AOD : part d'élimination rénale ?","back":"Dabigatran **80 %**, rivaroxaban **33 %**, apixaban **25 %**.","prio":"P3","sec":"s16"},{"id":"fc-232-9956ba","poly":"cardio","fiche":"232","front":"AOD : interactions médicamenteuses citées ?","back":"Macrolides, antiprotéases, antifongiques azolés, certains anticancéreux, **amiodarone**, **diltiazem**, **vérapamil**.","prio":"P3","sec":"s16"},{"id":"fc-232-df8666","poly":"cardio","fiche":"232","front":"HNF : cibles de surveillance ?","back":"**TCA** 2 à 3 fois le témoin et/ou **anti-Xa** 0,5 à 0,8.","prio":"P2","sec":"s16"},{"id":"fc-232-e5fbdf","poly":"cardio","fiche":"232","front":"HNF : quand faire le 1er TCA ?","back":"Vers la **5e heure**, puis au moins 1 fois/j.","prio":"P3","sec":"s16"},{"id":"fc-232-4b6ea7","poly":"cardio","fiche":"232","front":"HNF : quel TCA signe un surdosage ?","back":"TCA **> 3 fois le témoin**.","prio":"P2","sec":"s16"},{"id":"fc-232-716cd0","poly":"cardio","fiche":"232","front":"HNF : surveillance plaquettaire ?","back":"Numération **avant ou dans les 24 h** suivant le début (TIH, typiquement J5-J8).","prio":"P2","sec":"s16"},{"id":"fc-232-192748","poly":"cardio","fiche":"232","front":"Digoxine : précautions de surveillance ?","back":"Risque de **surdosage** (surtout si insuffisance rénale) → **dosage plasmatique** régulier.","prio":"P2","sec":"s16"},{"id":"fc-232-d0c401","poly":"cardio","fiche":"232","front":"AVK : antidotes et rapidité d'action ?","back":"**PPSB** (action très rapide) + **vitamine K** (en quelques heures).","prio":"P1","sec":"s16"},{"id":"fc-232-e6440a","poly":"cardio","fiche":"232","front":"Anti-Xa (rivaroxaban, apixaban) : existe-t-il un antidote ?","back":"En **cours de commercialisation**.","prio":"P3","sec":"s16"},{"id":"fc-232-c229e8","poly":"cardio","fiche":"232","front":"Geste programmé à risque hémorragique modéré sous AVK : arrêt nécessaire ?","back":"La plupart se font **sans arrêt**, INR en limite basse de la cible.","prio":"P3","sec":"s16"},{"id":"fc-232-04fb51","poly":"cardio","fiche":"232","front":"AVK à arrêter avant un geste, FA sans antécédent embolique : relais ?","back":"Arrêt **sans relais** par héparine.","prio":"P2","sec":"s16"},{"id":"fc-232-e05075","poly":"cardio","fiche":"232","front":"AVK à arrêter, FA avec antécédent embolique ou valve mécanique : conduite ?","back":"**Relais préopératoire par héparine curative** ; reprise des AVK en 24-48 h.","prio":"P2","sec":"s16"},{"id":"fc-232-05513b","poly":"cardio","fiche":"232","front":"Avant chirurgie sous AVK : INR visé ?","back":"**< 1,5** (< 1,2 en neurochirurgie).","prio":"P3","sec":"s16"},{"id":"fc-232-692186","poly":"cardio","fiche":"232","front":"FA : place de la correction des comorbidités ?","back":"Étape **obligatoire et fondamentale chez tous les patients**, quelle que soit la stratégie.","prio":"P1","sec":"s17"},{"id":"fc-232-8bbe86","poly":"cardio","fiche":"232","front":"FA chez l'obèse : objectif pondéral ?","back":"Perte de poids de **10 %** et/ou **IMC < 27 kg/m²**.","prio":"P2","sec":"s17"},{"id":"fc-232-6c1069","poly":"cardio","fiche":"232","front":"FA avec HTA : objectif tensionnel ?","back":"**PA systolique < 130 mmHg**.","prio":"P1","sec":"s17"},{"id":"fc-232-23509b","poly":"cardio","fiche":"232","front":"FA : mesures hygiéno-diététiques à proposer ?","back":"**Activité physique adaptée**, **alcool limité**, **sevrage tabagique**, perte de poids.","prio":"P2","sec":"s17"},{"id":"fc-232-4dcd1e","poly":"cardio","fiche":"232","front":"FA et SAOS : dépistage par questionnaire ?","back":"**N'est plus indiqué** : on discute un traitement et on encourage la **polygraphie**.","prio":"P2","sec":"s17"},{"id":"fc-232-f63402","poly":"cardio","fiche":"232","front":"Éducation sous anticoagulant : points clés ?","back":"Interactions, prévention et **signes d'alarme des saignements** ; INR et cible (AVK) ; fonction rénale (AOD) ; **carnet** ; **contraception** (tératogénicité).","prio":"P2","sec":"s17"},{"id":"fc-232-cf8ea1","poly":"cardio","fiche":"232","front":"Sous AVK : conseils supplémentaires au patient ?","back":"Éviter les coprescriptions, connaître les **seuils d'alerte de l'INR**, consulter si saignement, signaler le traitement à tout médecin.","prio":"P2","sec":"s17"},{"id":"fc-232-435b3d","poly":"cardio","fiche":"232","front":"FA : pronostic ?","back":"**Pas de risque de mort subite**, mais un risque d'**embolie cérébrale**.","prio":"P1","sec":"s17"},{"id":"fc-232-1294df","poly":"cardio","fiche":"232","front":"FA due à l'HTA : quel terrain métabolique est souvent associé ?","back":"**Surpoids** et/ou **syndrome métabolique**.","prio":"P3","sec":"s17"},{"id":"fc-232-dc4525","poly":"cardio","fiche":"232","front":"Suivi de la FA : que réévaluer régulièrement ?","back":"La balance **bénéfice/risque de l'anticoagulant** ; HTA (automesure, MAPA) et SAOS (polygraphie) ; fréquence par **holter**.","prio":"P2","sec":"s17"},{"id":"fc-233-2feb57","poly":"cardio","fiche":"233","front":"Rétrécissement aortique (RA) : définition ?","back":"**Obstacle à l'éjection du VG**, siégeant le plus souvent sur la valve aortique elle-même (temps : **systole**).","prio":"P1","sec":"s1"},{"id":"fc-233-beecd5","poly":"cardio","fiche":"233","front":"Valvulopathie la plus fréquente ?","back":"Le **rétrécissement aortique**, surtout dégénératif après 65 ans.","prio":"P1","sec":"s1"},{"id":"fc-233-49dc84","poly":"cardio","fiche":"233","front":"Insuffisance mitrale (IM) : définition ?","back":"Défaut d'étanchéité de la mitrale : **reflux systolique du VG vers l'atrium gauche**.","prio":"P1","sec":"s1"},{"id":"fc-233-cc66f1","poly":"cardio","fiche":"233","front":"IM primaire et IM secondaire : différence ?","back":"**Primaire** = valve malade ; **secondaire** = valve saine, VG ou anneau malade.","prio":"P1","sec":"s1"},{"id":"fc-233-6e11b9","poly":"cardio","fiche":"233","front":"Insuffisance aortique (IA) : définition ?","back":"**Reflux diastolique** (régurgitation) de l'aorte vers le VG.","prio":"P1","sec":"s1"},{"id":"fc-233-d3153a","poly":"cardio","fiche":"233","front":"IA : fréquence et évolution habituelle ?","back":"**Peu fréquente**, prévalence croissante avec l'âge ; peut rester **asymptomatique** de nombreuses années.","prio":"P2","sec":"s1"},{"id":"fc-233-988364","poly":"cardio","fiche":"233","front":"Autres obstacles à l'éjection du VG (hors chapitre) ?","back":"Rétrécissement **supra-aortique**, **sous-aortique** (diaphragme), obstruction dynamique des **cardiomyopathies obstructives**.","prio":"P3","sec":"s1"},{"id":"fc-233-95bee9","poly":"cardio","fiche":"233","front":"Valve aortique normale : nombre de cusps et mode d'ouverture ?","back":"**Tricuspide** (antérodroite, antérogauche, non coronaire) ; s'ouvre **passivement** selon le gradient VG–aorte.","prio":"P2","sec":"s1"},{"id":"fc-233-5fa63f","poly":"cardio","fiche":"233","front":"Bicuspidie aortique : définition et fréquence ?","back":"**2 cusps au lieu de 3** (anomalie congénitale) ; **1 à 2 %** de la population ; favorise le RA (et peut donner une IA).","prio":"P1","sec":"s1"},{"id":"fc-233-bd9f37","poly":"cardio","fiche":"233","front":"Racine aortique : composants ?","back":"**Anneau**, **sinus de Valsalva**, **jonction sinotubulaire**, puis aorte initiale.","prio":"P3","sec":"s1"},{"id":"fc-233-15e760","poly":"cardio","fiche":"233","front":"Valve mitrale : anatomie ?","back":"**2 feuillets** (antérieur = grande valve, postérieur = petite valve) sur un anneau, **2 commissures**, cordages issus de **2 piliers**.","prio":"P2","sec":"s1"},{"id":"fc-233-b16ff1","poly":"cardio","fiche":"233","front":"Valve mitrale en systole : où se rejoignent les feuillets ?","back":"**Dans le plan de l'anneau**.","prio":"P3","sec":"s1"},{"id":"fc-233-fa9eac","poly":"cardio","fiche":"233","front":"IM type I de Carpentier : mécanisme et exemples ?","back":"**Dilatation de l'anneau** ou **perforation**/déchirure d'un feuillet : IM **atriale**, perforation par endocardite.","prio":"P2","sec":"s1"},{"id":"fc-233-e2bae5","poly":"cardio","fiche":"233","front":"IM type II de Carpentier : mécanisme et exemple ?","back":"**Excès de jeu valvulaire** (cordage allongé ou rompu ± excès de tissu) → **prolapsus** : IM **dystrophiques**.","prio":"P1","sec":"s1"},{"id":"fc-233-2253d5","poly":"cardio","fiche":"233","front":"IM type IIIa de Carpentier : mécanisme et exemple ?","back":"**Restriction** du jeu en systole **et** en diastole : IM **rhumatismale** et apparentées (médicaments, radiothérapie).","prio":"P2","sec":"s1"},{"id":"fc-233-0d0630","poly":"cardio","fiche":"233","front":"IM type IIIb de Carpentier : mécanisme et exemple ?","back":"**Limitation du jeu en systole** seulement : IM **secondaire** (ischémique après infarctus inférieur, dilatation/dysfonction du VG).","prio":"P2","sec":"s1"},{"id":"fc-233-85862e","poly":"cardio","fiche":"233","front":"RA : type de surcharge et adaptation du VG ?","back":"**Surcharge de pression** → **hypertrophie concentrique** (loi de Laplace), FEVG longtemps normale.","prio":"P2","sec":"s1"},{"id":"fc-233-907fd5","poly":"cardio","fiche":"233","front":"Gradient VG–aorte normal ?","back":"**2 à 5 mmHg**.","prio":"P3","sec":"s1"},{"id":"fc-233-86822d","poly":"cardio","fiche":"233","front":"RA : pourquoi la FA est-elle en général mal tolérée ?","back":"VG épais qui se remplit mal (**dysfonction diastolique**) : la contraction atriale devient indispensable.","prio":"P2","sec":"s1"},{"id":"fc-233-2d685a","poly":"cardio","fiche":"233","front":"RA : pourquoi la récupération après le geste peut-elle être incomplète ?","back":"Une **fibrose** du VG hypertrophié (coronaires n'irriguant plus tout le muscle).","prio":"P3","sec":"s1"},{"id":"fc-233-d225d9","poly":"cardio","fiche":"233","front":"IM : type de surcharge et adaptation du VG ?","back":"**Surcharge de volume** → dilatation, **hypertrophie excentrique**.","prio":"P2","sec":"s1"},{"id":"fc-233-3571f3","poly":"cardio","fiche":"233","front":"IM : pourquoi la FEVG est-elle surestimée et quel seuil de dysfonction ?","back":"Le VG se vide aussi dans l'oreillette → FEVG surestimée : dysfonction dès **< 60 %**.","prio":"P1","sec":"s1"},{"id":"fc-233-8a1624","poly":"cardio","fiche":"233","front":"IM : de quoi dépend le volume régurgité ?","back":"Taille de l'**orifice de fuite**, **gradient VG–AG**, **durée de la systole**.","prio":"P3","sec":"s1"},{"id":"fc-233-6def39","poly":"cardio","fiche":"233","front":"IM chronique : conséquences en amont ?","back":"**AG dilaté** (risque de **FA**) et **HTP post-capillaire**.","prio":"P2","sec":"s1"},{"id":"fc-233-e3d1f2","poly":"cardio","fiche":"233","front":"IM aiguë : pourquoi l'HTP est-elle immédiate et importante ?","back":"L'AG n'a **pas le temps de se dilater** (pas d'amortissement par sa compliance).","prio":"P2","sec":"s1"},{"id":"fc-233-220247","poly":"cardio","fiche":"233","front":"IM : définition hémodynamique de l'HTP post-capillaire au cathétérisme ?","back":"**PAPO > 15 mmHg**, avec onde V de reflux.","prio":"P3","sec":"s1"},{"id":"fc-233-299e1a","poly":"cardio","fiche":"233","front":"IA : type de surcharge ?","back":"**Mixte** : volume + pression ; VG dilaté et hypertrophié, **plus que dans l'IM**.","prio":"P2","sec":"s1"},{"id":"fc-233-3ae08d","poly":"cardio","fiche":"233","front":"IA : retentissement artériel ?","back":"PAS qui monte, **PAD qui baisse** → pression pulsée large, **hyperpulsatilité**.","prio":"P2","sec":"s1"},{"id":"fc-233-6bf229","poly":"cardio","fiche":"233","front":"IA : pourquoi un angor sans coronaropathie ?","back":"Coronaires perfusées surtout en diastole : la **PAD basse** réduit leur perfusion.","prio":"P2","sec":"s1"},{"id":"fc-233-884ab4","poly":"cardio","fiche":"233","front":"IA aiguë : pourquoi un OAP ?","back":"VG de taille normale ou peu dilaté : les **pressions de remplissage montent d'un coup**.","prio":"P2","sec":"s1"},{"id":"fc-233-03d9e3","poly":"cardio","fiche":"233","front":"IA chronique : de quoi dépend le volume de fuite ?","back":"Orifice régurgitant, **durée de la diastole**, gradient diastolique aorte–VG.","prio":"P3","sec":"s1"},{"id":"fc-233-0193c7","poly":"cardio","fiche":"233","front":"IA chronique avec VG très dilaté ou FE abaissée : risque après chirurgie ?","back":"Remodelage du VG parfois **irréversible**.","prio":"P3","sec":"s1"},{"id":"fc-233-af6bad","poly":"cardio","fiche":"233","front":"IA aiguë : particularité auscultatoire ?","back":"Parfois **peu audible**.","prio":"P3","sec":"s1"},{"id":"fc-233-e4b937","poly":"cardio","fiche":"233","front":"Valvulopathie : une FEVG normale rassure-t-elle ?","back":"**Non** : longtemps normale dans le RA serré ; dans l'IM sévère, **< 60 %** est déjà une dysfonction.","prio":"P2","sec":"s1"},{"id":"fc-233-f560bc","poly":"cardio","fiche":"233","front":"RA : cause la plus fréquente entre 30 et 65 ans ?","back":"La **bicuspidie** aortique.","prio":"P1","sec":"s2"},{"id":"fc-233-fe1004","poly":"cardio","fiche":"233","front":"RA : cause la plus fréquente chez le sujet âgé ?","back":"Le **RA dégénératif** (maladie de **Mönckeberg**), de loin après 65-70 ans.","prio":"P1","sec":"s2"},{"id":"fc-233-d79d4d","poly":"cardio","fiche":"233","front":"RA dégénératif : mécanisme ?","back":"**Calcifications** à la base des valvules qui se rigidifient ; plus la sténose est serrée, plus la valve est calcifiée ; proche de l'**athérosclérose**.","prio":"P2","sec":"s2"},{"id":"fc-233-e9c6e8","poly":"cardio","fiche":"233","front":"Bicuspidie : anomalie aortique associée à rechercher ?","back":"**Anévrisme de l'aorte ascendante** (plus rarement **coarctation**).","prio":"P1","sec":"s2"},{"id":"fc-233-253607","poly":"cardio","fiche":"233","front":"Bicuspidie : transmission et conséquence ?","back":"Possiblement **autosomique dominante** à pénétrance variable → **dépistage des apparentés du 1er degré**.","prio":"P2","sec":"s2"},{"id":"fc-233-f7a2ff","poly":"cardio","fiche":"233","front":"RA post-rhumatismal : fréquence et lésions associées ?","back":"Devenu **rare** (encore chez les migrants) ; **habituellement** associé à une **IA** et une atteinte **mitrale** (RM + IM).","prio":"P3","sec":"s2"},{"id":"fc-233-b2ccd5","poly":"cardio","fiche":"233","front":"IM : première cause des fuites sévères ?","back":"L'**IM dystrophique** (Carpentier II) : élongation ou **rupture de cordages** → prolapsus.","prio":"P1","sec":"s2"},{"id":"fc-233-a0c1ce","poly":"cardio","fiche":"233","front":"Maladie de Barlow : caractéristiques ?","back":"**Dégénérescence myxoïde** : valves redondantes, épaissies, hypermobiles.","prio":"P2","sec":"s2"},{"id":"fc-233-00859e","poly":"cardio","fiche":"233","front":"Dégénérescence fibroélastique mitrale : terrain et atteinte typiques ?","back":"Plus fréquente ; sujet **plus âgé**, surtout **homme**, **valve postérieure**, **rupture de cordage**.","prio":"P2","sec":"s2"},{"id":"fc-233-164508","poly":"cardio","fiche":"233","front":"IM dystrophique : dystrophies du tissu conjonctif associées ?","back":"Parfois **Marfan** ou **Ehlers-Danlos**.","prio":"P3","sec":"s2"},{"id":"fc-233-8319d7","poly":"cardio","fiche":"233","front":"IM rhumatismale : caractéristiques ?","back":"Rare en pays développés, endémique ailleurs ; souvent avec un **RM** (« maladie mitrale ») et une atteinte aortique ; valves épaissies, rétractées.","prio":"P2","sec":"s2"},{"id":"fc-233-fca90e","poly":"cardio","fiche":"233","front":"IM apparentées au rhumatisme : causes médicamenteuses et autres ?","back":"**Dérivés de l'ergot de seigle**, anorexigènes retirés (**fenfluramine**, **benfluorex**) ; **radiothérapie**.","prio":"P2","sec":"s2"},{"id":"fc-233-d09e6a","poly":"cardio","fiche":"233","front":"IM par endocardite : terrain et lésions ?","back":"Plus de la moitié sur **valve déjà lésée** ; **ruptures de cordages** ou **perforations**, surtout de la valve antérieure.","prio":"P2","sec":"s2"},{"id":"fc-233-fe8cac","poly":"cardio","fiche":"233","front":"IM secondaire : causes ?","back":"IM **ischémique** (classiquement après infarctus **inférieur**) ou **dilatation/dysfonction du VG**.","prio":"P1","sec":"s2"},{"id":"fc-233-54d9cf","poly":"cardio","fiche":"233","front":"IM atriale : mécanisme ?","back":"Anneau dilaté par un **AG très dilaté** (Carpentier I) ; plus rare.","prio":"P3","sec":"s2"},{"id":"fc-233-3321c0","poly":"cardio","fiche":"233","front":"CMH obstructive : mécanisme de l'IM ?","back":"Feuillet antérieur aspiré dans la chambre de chasse (**SAM**).","prio":"P3","sec":"s2"},{"id":"fc-233-1a2f71","poly":"cardio","fiche":"233","front":"IA type 1 (mouvement normal des cusps) : mécanismes ?","back":"**Dilatation de la racine aortique** ou **perforation** de cusp (surtout endocardite).","prio":"P2","sec":"s2"},{"id":"fc-233-952bd9","poly":"cardio","fiche":"233","front":"IA par dilatation de la racine : causes ?","back":"Idiopathique, génétique (**Marfan**, Loeys-Dietz, Ehlers-Danlos), **aortites**, bicuspidie, **dissection**.","prio":"P2","sec":"s2"},{"id":"fc-233-ad87da","poly":"cardio","fiche":"233","front":"IA : aortites causales citées ?","back":"**Takayasu**, **Horton**, Behçet, **spondylarthrite ankylosante**, **syphilis**.","prio":"P2","sec":"s2"},{"id":"fc-233-2270f3","poly":"cardio","fiche":"233","front":"Maladie annuloectasiante : définition et risque ?","back":"Dilatation surtout de l'anneau et des sinus → risque de **dissection ou rupture** ; penser **Marfan**.","prio":"P1","sec":"s2"},{"id":"fc-233-e50321","poly":"cardio","fiche":"233","front":"IA type 2 (prolapsus) : causes ?","back":"Dystrophie isolée, **bicuspidie** (prolapsus de la cusp fusionnée) ; plus rarement endocardite, traumatisme, dissection, CIV sous-aortique (**Laubry-Pezzi**).","prio":"P2","sec":"s2"},{"id":"fc-233-022446","poly":"cardio","fiche":"233","front":"IA type 3 (restriction) : causes ?","back":"**RAA** ; **médicaments** (ergot de seigle, fenfluramine, **benfluorex**, MDMA) ; carcinoïde ; **radiothérapie médiastinale**.","prio":"P2","sec":"s2"},{"id":"fc-233-3b30e8","poly":"cardio","fiche":"233","front":"Syndrome carcinoïde : pourquoi les valves gauches sont-elles rarement atteintes ?","back":"La sérotonine est arrêtée par le **filtre pulmonaire** (sauf foramen ovale perméable ou métastase pulmonaire).","prio":"P3","sec":"s2"},{"id":"fc-233-85f070","poly":"cardio","fiche":"233","front":"Bicuspidie : 3 complications valvulaires ou infectieuses ?","back":"**RA** à tout âge, **IA** (prolapsus de la plus grande cusp), **endocardite** ; plus dilatation aortique.","prio":"P2","sec":"s2"},{"id":"fc-233-03acb5","poly":"cardio","fiche":"233","front":"Principales causes d'IA en Occident ?","back":"**Dystrophie valvulaire**, **dilatation aortique**, **bicuspidie**, **endocardite**.","prio":"P1","sec":"s2"},{"id":"fc-233-467890","poly":"cardio","fiche":"233","front":"Causes d'IM aiguë ?","back":"**Rupture de cordages**, **infarctus** (rupture ou dysfonction de pilier), traumatisme thoracique, **perforation** par endocardite.","prio":"P1","sec":"s2"},{"id":"fc-233-832d95","poly":"cardio","fiche":"233","front":"IM dystrophique : ballonnisation ou prolapsus, différence ?","back":"**Ballonnisation** : feuillet qui bombe dans l'AG, bord libre dans le plan de l'anneau ; **prolapsus** : l'extrémité passe en arrière de ce plan.","prio":"P3","sec":"s2"},{"id":"fc-233-b80900","poly":"cardio","fiche":"233","front":"Causes d'IA aiguë ?","back":"Surtout **endocardite** ; **dissection aortique** ; **traumatisme**.","prio":"P1","sec":"s2"},{"id":"fc-233-c4c3cd","poly":"cardio","fiche":"233","front":"IA sur prothèse : une fuite minime est-elle anormale ?","back":"**Non**, une IA minime est **normale** sur toute prothèse.","prio":"P3","sec":"s2"},{"id":"fc-233-ac3ab1","poly":"cardio","fiche":"233","front":"Valvulopathies : circonstances de découverte ?","back":"**Souffle** (souvent fortuit), **symptômes d'effort**, **complication** (IC, OAP, FA), **fièvre** prolongée, écho pour autre chose.","prio":"P2","sec":"s3"},{"id":"fc-233-05797a","poly":"cardio","fiche":"233","front":"RA : 3 symptômes typiques ?","back":"**Dyspnée**, **angor**, **syncope**, tous **à l'effort**.","prio":"P1","sec":"s3"},{"id":"fc-233-bd0849","poly":"cardio","fiche":"233","front":"RA : signification de l'apparition des symptômes ?","back":"**Cassure évolutive** : mauvais pronostic sans traitement.","prio":"P1","sec":"s3"},{"id":"fc-233-3cf3d0","poly":"cardio","fiche":"233","front":"IM : symptômes ?","back":"Rien si modérée ; **dyspnée d'effort** lente et progressive ± asthénie, palpitations ; tard orthopnée ; **OAP tardif et grave**.","prio":"P2","sec":"s3"},{"id":"fc-233-947b15","poly":"cardio","fiche":"233","front":"IA : symptômes ?","back":"Longtemps **asymptomatique** ; dyspnée d'effort, asthénie ; angor rare ; signes de repos tardifs, de mauvais pronostic.","prio":"P2","sec":"s3"},{"id":"fc-233-daf802","poly":"cardio","fiche":"233","front":"Souffle de RA : caractéristiques ?","back":"**Mésosystolique éjectionnel**, losangique, **rude, râpeux**, au **2e EIC droit**, irradiant aux **vaisseaux du cou**.","prio":"P1","sec":"s3"},{"id":"fc-233-a5c286","poly":"cardio","fiche":"233","front":"RA serré calcifié : signe auscultatoire associé ?","back":"**B2 aboli**.","prio":"P1","sec":"s3"},{"id":"fc-233-112953","poly":"cardio","fiche":"233","front":"RA : signification d'un frémissement ?","back":"En général, un RA **significatif** (souffle **4/6**).","prio":"P2","sec":"s3"},{"id":"fc-233-419754","poly":"cardio","fiche":"233","front":"Souffle d'IM : caractéristiques ?","back":"**Holosystolique** (B1 à B2), à la **pointe**, irradiant à l'**aisselle**, en **jet de vapeur**.","prio":"P1","sec":"s3"},{"id":"fc-233-e07e80","poly":"cardio","fiche":"233","front":"Souffle systolique après une diastole longue : RA ou IM ?","back":"**RA** : se renforce ; **IM** : ne se renforce pas.","prio":"P1","sec":"s3"},{"id":"fc-233-af4eae","poly":"cardio","fiche":"233","front":"Souffle d'IA : caractéristiques ?","back":"**Diastolique**, le long du **bord gauche du sternum** ; holodiastolique si importante.","prio":"P1","sec":"s3"},{"id":"fc-233-27b3f6","poly":"cardio","fiche":"233","front":"Souffle d'IA : comment mieux l'entendre ?","back":"Patient **penché en avant**, en **expiration bloquée**.","prio":"P2","sec":"s3"},{"id":"fc-233-0add15","poly":"cardio","fiche":"233","front":"IA : signes auscultatoires de sévérité ?","back":"**Roulement de Flint** apexien ou **galop**.","prio":"P2","sec":"s3"},{"id":"fc-233-5c6726","poly":"cardio","fiche":"233","front":"IM : l'intensité du souffle reflète-t-elle la sévérité ?","back":"**Souvent**, mais **pas toujours**.","prio":"P2","sec":"s3"},{"id":"fc-233-0f3927","poly":"cardio","fiche":"233","front":"Prolapsus mitral : signe auscultatoire caractéristique ?","back":"**Clic mésosystolique**, puis souffle méso-télésystolique ou télésystolique.","prio":"P1","sec":"s3"},{"id":"fc-233-39d95d","poly":"cardio","fiche":"233","front":"IM importante : signes auscultatoires associés ?","back":"Galop **B3**, roulement mésodiastolique d'hyperdébit, éclat de **B2 pulmonaire** (HTP), souffle d'IT fonctionnelle ; crépitants.","prio":"P2","sec":"s3"},{"id":"fc-233-7e368b","poly":"cardio","fiche":"233","front":"IA : signes périphériques ?","back":"**Hyperpulsatilité** des pouls, battements du cou, oscillation de la tête, pulsatilité sous-unguéale.","prio":"P1","sec":"s3"},{"id":"fc-233-e18271","poly":"cardio","fiche":"233","front":"IA : signe tensionnel de sévérité ?","back":"**Différentielle élargie** avec **PAD abaissée**.","prio":"P1","sec":"s3"},{"id":"fc-233-f30a23","poly":"cardio","fiche":"233","front":"RA évolué à bas débit : particularité du souffle ?","back":"**Atténué**, voire presque **inaudible**.","prio":"P2","sec":"s3"},{"id":"fc-233-cfa189","poly":"cardio","fiche":"233","front":"Maladie aortique : définition ?","back":"Association d'un **RA** et d'une **IA**.","prio":"P3","sec":"s3"},{"id":"fc-233-19afba","poly":"cardio","fiche":"233","front":"Frémissement du RA : comment le chercher ?","back":"Plat de la main, patient **penché en avant**, en **fin d'expiration**.","prio":"P3","sec":"s3"},{"id":"fc-233-6bf73c","poly":"cardio","fiche":"233","front":"Souffle d'IA : avis cardiologique nécessaire ?","back":"**Oui**, symptomatique ou non.","prio":"P1","sec":"s3"},{"id":"fc-233-453205","poly":"cardio","fiche":"233","front":"Valvulopathie « asymptomatique » : quel piège à l'interrogatoire ?","back":"Le patient a souvent **réduit ses activités** sans s'en rendre compte : chercher une baisse progressive des efforts.","prio":"P1","sec":"s3"},{"id":"fc-233-38cbf1","poly":"cardio","fiche":"233","front":"Souffle faible : quelles valvulopathies sévères peut-il cacher ?","back":"**RA à bas débit** ; **IM secondaire** (souffle discret voire inaudible, mal corrélé à la sévérité).","prio":"P2","sec":"s3"},{"id":"fc-233-a12db9","poly":"cardio","fiche":"233","front":"Valvulopathies : examen clé ?","back":"L'**échocardiographie transthoracique** (ETT).","prio":"P1","sec":"s4"},{"id":"fc-233-78d7be","poly":"cardio","fiche":"233","front":"ETT d'une valvulopathie : 4 questions ?","back":"**Confirmer** ; **mécanisme et cause** ; **quantifier** ; **retentissement** et voisinage (VG, PAP, oreillette, autres valves, aorte).","prio":"P1","sec":"s4"},{"id":"fc-233-bda131","poly":"cardio","fiche":"233","front":"ETT : signes de RA ?","back":"Valve remaniée, **calcifiée**, qui s'ouvre mal ; vitesses accélérées (**> 2,5 m/s**).","prio":"P2","sec":"s4"},{"id":"fc-233-200c1b","poly":"cardio","fiche":"233","front":"RA serré : seuil de vitesse maximale ?","back":"**Vmax > 4 m/s** (normale ≈ 1 m/s).","prio":"P1","sec":"s4"},{"id":"fc-233-ffe0b1","poly":"cardio","fiche":"233","front":"RA serré : seuil de gradient moyen ?","back":"**> 40 mmHg** (normal 2-5 mmHg).","prio":"P1","sec":"s4"},{"id":"fc-233-577b7b","poly":"cardio","fiche":"233","front":"RA serré : seuil de surface ?","back":"**< 1 cm²** ou **< 0,6 cm²/m²** (normale 2-3,5 cm²).","prio":"P1","sec":"s4"},{"id":"fc-233-7636f4","poly":"cardio","fiche":"233","front":"RA critique : seuil de surface ?","back":"**≤ 0,75 cm²** ou ≤ 0,4 cm²/m².","prio":"P3","sec":"s4"},{"id":"fc-233-e7da14","poly":"cardio","fiche":"233","front":"RA serré à bas gradient : situation et examen ?","back":"**Bas débit** (VES ≤ 35 mL/m²) avec gradient < 40 mmHg → **écho sous faible dose de dobutamine**.","prio":"P1","sec":"s4"},{"id":"fc-233-c7ead1","poly":"cardio","fiche":"233","front":"Pseudosténose aortique : définition et conduite ?","back":"Surface < 1 cm² au repos qui **dépasse 1 cm²** sous dobutamine : **surveiller** et traiter comme une **insuffisance cardiaque**.","prio":"P1","sec":"s4"},{"id":"fc-233-0d7e78","poly":"cardio","fiche":"233","front":"RA : place de l'ETO ?","back":"Peu d'intérêt, sauf **patient peu échogène** (planimétrie si sévérité douteuse).","prio":"P3","sec":"s4"},{"id":"fc-233-74d840","poly":"cardio","fiche":"233","front":"RA asymptomatique : seuil de FEVG faisant discuter le remplacement ?","back":"**FEVG ≤ 55 %** due au seul RA (strain, IRM si doute).","prio":"P2","sec":"s4"},{"id":"fc-233-d6d844","poly":"cardio","fiche":"233","front":"IM : quand l'ETO est-elle obligatoire ?","back":"**Endocardite** suspectée (végétations fines invisibles en ETT).","prio":"P1","sec":"s4"},{"id":"fc-233-0657ca","poly":"cardio","fiche":"233","front":"IM : autre intérêt de l'ETO ?","back":"Préciser le **mécanisme** et la **faisabilité d'une plastie** (souvent en préopératoire).","prio":"P2","sec":"s4"},{"id":"fc-233-ff17a1","poly":"cardio","fiche":"233","front":"IM : grades de sévérité ?","back":"Minime ou modérée = **grades I-II** ; significative ou importante = **grades III-IV**.","prio":"P2","sec":"s4"},{"id":"fc-233-53dbe4","poly":"cardio","fiche":"233","front":"IM : quelle autre valve vérifier à l'écho ?","back":"La **tricuspide** : sa fuite doit parfois être corrigée pendant la chirurgie mitrale.","prio":"P2","sec":"s4"},{"id":"fc-233-370990","poly":"cardio","fiche":"233","front":"IA : quels grades imposent une surcharge de volume significative ?","back":"**Seuls les grades 3 et 4** (sur 4 grades).","prio":"P2","sec":"s4"},{"id":"fc-233-c7120c","poly":"cardio","fiche":"233","front":"ECG du RA serré ?","back":"**HVG de type surcharge systolique** ; HAG ; **BBG**, **BAV 1** ; FA si évolué.","prio":"P2","sec":"s4"},{"id":"fc-233-417af0","poly":"cardio","fiche":"233","front":"RA : un ECG sans HVG exclut-il un RA serré ?","back":"**Non**.","prio":"P2","sec":"s4"},{"id":"fc-233-101276","poly":"cardio","fiche":"233","front":"ECG de l'IM ?","back":"Longtemps **normal** ; HAG, HVG, FA ; **HVD** si HTP sévère.","prio":"P3","sec":"s4"},{"id":"fc-233-271c72","poly":"cardio","fiche":"233","front":"Radiographie de l'IM évoluée ?","back":"**Cardiomégalie**, AG dilaté (arc moyen gauche convexe), signes d'HTP et d'IC (Kerley, redistribution, œdème).","prio":"P3","sec":"s4"},{"id":"fc-233-afa896","poly":"cardio","fiche":"233","front":"ECG de l'IA ?","back":"Rythme sinusal en général ; **HVG diastolique** (grandes R, T positives) ; FA ou ESV = **mauvais pronostic**.","prio":"P3","sec":"s4"},{"id":"fc-233-48faf4","poly":"cardio","fiche":"233","front":"Radiographie de l'IA volumineuse ?","back":"**Index cardiothoracique augmenté** ; aorte déroulée.","prio":"P3","sec":"s4"},{"id":"fc-233-0706ca","poly":"cardio","fiche":"233","front":"Épreuve d'effort dans le RA : indication ?","back":"**RA serré asymptomatique**, pour vérifier objectivement l'absence de symptôme.","prio":"P2","sec":"s4"},{"id":"fc-233-8fff24","poly":"cardio","fiche":"233","front":"Épreuve d'effort dans le RA symptomatique ?","back":"**Contre-indiquée**.","prio":"P1","sec":"s4"},{"id":"fc-233-9f4edb","poly":"cardio","fiche":"233","front":"Épreuve d'effort du RA : quels signes d'anomalie ?","back":"Niveau atteint ; **PA qui monte mal ou qui baisse**.","prio":"P3","sec":"s4"},{"id":"fc-233-3005b9","poly":"cardio","fiche":"233","front":"Valvulopathie : place du cathétérisme ?","back":"Habituellement **inutile** ; seulement si **discordance** clinique/écho ou patient peu échogène.","prio":"P2","sec":"s4"},{"id":"fc-233-1869a2","poly":"cardio","fiche":"233","front":"RA : indications de la coronarographie préopératoire ?","back":"**Homme > 40 ans** ou **femme ménopausée** même sans FDR ; à tout âge si FDR, angor d'effort ou IC.","prio":"P1","sec":"s4"},{"id":"fc-233-1939f9","poly":"cardio","fiche":"233","front":"IM : imagerie coronaire préopératoire ?","back":"**Coroscanner** si faible probabilité prétest ; sinon **coronarographie** (ischémie, baisse de FEVG, homme > 40 ans, femme ménopausée, FDR).","prio":"P2","sec":"s4"},{"id":"fc-233-e657ba","poly":"cardio","fiche":"233","front":"Avant TAVI : examen systématique et but ?","back":"**Scanner cardiaque** : anneau, culot aortique, distance des ostia coronaires → **taille de prothèse**.","prio":"P1","sec":"s4"},{"id":"fc-233-eea95b","poly":"cardio","fiche":"233","front":"Scanner pré-TAVI : autres apports ?","back":"**Axes artériels** (ilio-fémoral, subclavier, carotidien) ; **score calcique valvulaire**.","prio":"P3","sec":"s4"},{"id":"fc-233-5aac0b","poly":"cardio","fiche":"233","front":"IA : place de l'IRM ?","back":"Aorte ascendante (non irradiante ; gadolinium CI si IR sévère) ; volumes du VG, FEVG, volume régurgité.","prio":"P3","sec":"s4"},{"id":"fc-233-e934db","poly":"cardio","fiche":"233","front":"RA : piège du gradient seul ?","back":"Avec un **bas débit**, un RA serré peut avoir un gradient **< 40 mmHg** → compléter par la **surface**.","prio":"P2","sec":"s4"},{"id":"fc-233-90e192","poly":"cardio","fiche":"233","front":"Valvulopathie : 2 éléments qui font basculer vers l'intervention ?","back":"**Apparition de symptômes** et **retentissement** (VG, oreillette/FA, HTP).","prio":"P2","sec":"s5"},{"id":"fc-233-c56b7d","poly":"cardio","fiche":"233","front":"RA serré asymptomatique : critères d'intervention ?","back":"**Épreuve d'effort anormale** ; **Vmax > 5 m/s** ; **aggravation rapide** ; **FEVG < 55 %**.","prio":"P2","sec":"s5"},{"id":"fc-233-e07f1d","poly":"cardio","fiche":"233","front":"IM primaire importante asymptomatique : critères d'intervention ?","back":"**DTS ≥ 40 mm** (avec rupture de cordage), **FEVG ≤ 60 %**, **PAPs ≥ 50 mmHg**, **FA** ou **AG > 60 mL/m²**.","prio":"P2","sec":"s5"},{"id":"fc-233-990641","poly":"cardio","fiche":"233","front":"IA sévère asymptomatique : critères d'intervention formels ?","back":"**DTS > 50 mm ou > 25 mm/m²**, ou **FEVG ≤ 50 %**.","prio":"P2","sec":"s5"},{"id":"fc-233-d042d4","poly":"cardio","fiche":"233","front":"IA sévère asymptomatique, chirurgie à bas risque : critères ?","back":"**DTS > 20 mm/m²** ou **FEVG ≤ 55 %**.","prio":"P3","sec":"s5"},{"id":"fc-233-8230cf","poly":"cardio","fiche":"233","front":"Aorte ascendante : seuils d'intervention ?","back":"**≥ 55 mm** ; **≥ 50 mm si Marfan** ; ≥ 45 mm si Marfan avec FDR ; ≥ 50 mm si bicuspidie avec FDR.","prio":"P2","sec":"s5"},{"id":"fc-233-f33197","poly":"cardio","fiche":"233","front":"IM : progressive ou brutale, quelle tolérance ?","back":"Progressive = **bien tolérée**, IC tardive ; brutale (cordage, endocardite, infarctus) = **OAP rapide**.","prio":"P1","sec":"s5"},{"id":"fc-233-113d9d","poly":"cardio","fiche":"233","front":"IA : 2 déterminants du pronostic ?","back":"**Retentissement sur le VG** et **dilatation aortique** (dissection, rupture).","prio":"P3","sec":"s5"},{"id":"fc-233-3ded2f","poly":"cardio","fiche":"233","front":"IA grades 3-4 : pourquoi opérer souvent avant les symptômes ?","back":"Lésions du VG possiblement **irréversibles**.","prio":"P2","sec":"s5"},{"id":"fc-233-adfc9d","poly":"cardio","fiche":"233","front":"RA : complications ?","back":"**Insuffisance cardiaque**, **FA mal tolérée**, troubles de conduction, **mort subite** (surtout RA serré symptomatique) ; plus rarement endocardite, embolies calcaires.","prio":"P2","sec":"s5"},{"id":"fc-233-908e51","poly":"cardio","fiche":"233","front":"Syndrome de Heyde : définition ?","back":"RA + **anémie ferriprive** par **angiodysplasies intestinales** ± déficit acquis en facteur **von Willebrand**.","prio":"P3","sec":"s5"},{"id":"fc-233-cf9d81","poly":"cardio","fiche":"233","front":"RA : territoires des embolies calcaires ?","back":"**Cerveau**, **rein**, **coronaires**, artère centrale de la rétine.","prio":"P3","sec":"s5"},{"id":"fc-233-382a21","poly":"cardio","fiche":"233","front":"IM : complications ?","back":"**Rupture de cordage**, **endocardite**, **FA ou flutter**, troubles du rythme ventriculaire (rares), **insuffisance cardiaque**.","prio":"P2","sec":"s5"},{"id":"fc-233-678902","poly":"cardio","fiche":"233","front":"IM : signification d'une FA chez l'asymptomatique ?","back":"Elle justifie une **chirurgie précoce**.","prio":"P2","sec":"s5"},{"id":"fc-233-57ca17","poly":"cardio","fiche":"233","front":"IA : complications ?","back":"**Endocardite** (faible surrisque), **IC** tardive, **dissection ou rupture aortique**, mort subite (rare).","prio":"P3","sec":"s5"},{"id":"fc-233-35227c","poly":"cardio","fiche":"233","front":"IM aiguë : gravité ?","back":"Le plus souvent grave sur le plan hémodynamique : **urgence vitale**.","prio":"P1","sec":"s5"},{"id":"fc-233-76ad4b","poly":"cardio","fiche":"233","front":"OAP unilatéral : quelle valvulopathie aiguë évoquer ?","back":"**IM aiguë** par **rupture de cordage** (fuite dirigée vers un poumon).","prio":"P1","sec":"s6"},{"id":"fc-233-ac40c1","poly":"cardio","fiche":"233","front":"Souffle systolique éjectionnel dans une IA : signification la plus fréquente ?","back":"Souffle d'**hyperdébit**, pas forcément un RA.","prio":"P2","sec":"s6"},{"id":"fc-233-dbbff9","poly":"cardio","fiche":"233","front":"Roulement mésodiastolique sans RM : quelles causes ?","back":"**IM importante** (hyperdébit) ou **IA sévère** (**roulement de Flint**).","prio":"P2","sec":"s6"},{"id":"fc-233-b59213","poly":"cardio","fiche":"233","front":"IA aiguë : orientation selon la présence de fièvre ?","back":"**Fièvre → endocardite** ; douleur thoracique ou AVC **sans fièvre → dissection aortique**.","prio":"P1","sec":"s6"},{"id":"fc-233-d9ba15","poly":"cardio","fiche":"233","front":"IM atriale vs IM ventriculaire : types de Carpentier ?","back":"**Atriale** = type I (anneau dilaté) ; **ventriculaire** = type IIIb (piliers déplacés).","prio":"P2","sec":"s6"},{"id":"fc-233-7daedb","poly":"cardio","fiche":"233","front":"Diagnostics différentiels d'un souffle diastolique d'IA ?","back":"**Insuffisance pulmonaire**, rupture d'un sinus aortique, **canal artériel**, fistule coronarienne, frottement péricardique ; l'écho tranche.","prio":"P3","sec":"s6"},{"id":"fc-233-8c84dd","poly":"cardio","fiche":"233","front":"Rupture de pilier post-infarctus : quel piège ?","back":"La prendre pour une simple décompensation cardiaque : c'est une **urgence chirurgicale**.","prio":"P1","sec":"s6"},{"id":"fc-233-6482b0","poly":"cardio","fiche":"233","front":"RA symptomatique : conduite initiale obligatoire ?","back":"**Adresser au spécialiste** (ne pas le faire est inacceptable).","prio":"P1","sec":"s7"},{"id":"fc-233-85eb48","poly":"cardio","fiche":"233","front":"RA serré symptomatique : traitement ?","back":"**Traiter la valve** dans tous les cas : **RVA chirurgical ou TAVI**, pratiquement **sans limite d'âge** si état général conservé.","prio":"P1","sec":"s7"},{"id":"fc-233-efe604","poly":"cardio","fiche":"233","front":"RA : qui décide entre chirurgie et TAVI ?","back":"La **Heart Team** (âge, fragilité, comorbidités, souhaits du patient).","prio":"P2","sec":"s7"},{"id":"fc-233-47735a","poly":"cardio","fiche":"233","front":"RVA par bioprothèse : pour qui et limite ?","back":"Patient **> 65 ans** ; pas d'anticoagulant au long cours ; **dégénérescence en 10-15 ans**.","prio":"P2","sec":"s7"},{"id":"fc-233-0fc2e2","poly":"cardio","fiche":"233","front":"RVA par prothèse mécanique : pour qui et contrainte ?","back":"**Sujet jeune** ; longue durabilité ; **anticoagulation à vie**.","prio":"P2","sec":"s7"},{"id":"fc-233-155523","poly":"cardio","fiche":"233","front":"TAVI : indications ?","back":"**Inopérable ou à risque opératoire** quel que soit l'âge ; **1re intention après 75 ans** si voie fémorale possible.","prio":"P1","sec":"s7"},{"id":"fc-233-1788a6","poly":"cardio","fiche":"233","front":"Valvuloplastie aortique au ballon : seule indication restante ?","back":"**Chirurgie non cardiaque urgente à risque** chez un RA serré symptomatique (**resténose précoce** fréquente).","prio":"P2","sec":"s7"},{"id":"fc-233-7f70a2","poly":"cardio","fiche":"233","front":"RA serré asymptomatique sans critère d'intervention : conduite ?","back":"**Surveillance médicale et ETT**, suivi **annuel** spécialisé ; réadresser si souffle modifié ou symptômes.","prio":"P2","sec":"s7"},{"id":"fc-233-f7722a","poly":"cardio","fiche":"233","front":"Vrai RA serré avec FE < 35 % : opère-t-on ?","back":"**Discuter le remplacement** : risque plus élevé, mais pronostic **le plus mauvais chez les non-opérés**.","prio":"P2","sec":"s7"},{"id":"fc-233-e1c606","poly":"cardio","fiche":"233","front":"Prothèse mécanique : quel anticoagulant et pour combien de temps ?","back":"**AVK à vie** ; **AOD contre-indiqués**.","prio":"P1","sec":"s7"},{"id":"fc-233-490eec","poly":"cardio","fiche":"233","front":"Prothèse mécanique : INR cible (item 153) ?","back":"**Entre 2,5 et 4** selon le risque thrombotique de la prothèse et du patient (ex. aortique à faible risque sans FDR : 2,5).","prio":"P2","sec":"s7"},{"id":"fc-233-9bba53","poly":"cardio","fiche":"233","front":"Prothèse mécanique sous AVK : ajoute-t-on un antiagrégant ?","back":"**Non**, sauf situation particulière (stent récent, embolie sous INR efficace).","prio":"P3","sec":"s7"},{"id":"fc-233-f1a417","poly":"cardio","fiche":"233","front":"Bioprothèse aortique chirurgicale : antithrombotique ?","back":"**Aspirine ou AVK 3 mois** puis rien (sauf autre indication, ex. FA).","prio":"P2","sec":"s7"},{"id":"fc-233-4b38dc","poly":"cardio","fiche":"233","front":"Après TAVI : antithrombotique ?","back":"**Aspirine seule** si rythme sinusal ; **anticoagulation** si FA (AOD autorisés).","prio":"P2","sec":"s7"},{"id":"fc-233-32eea6","poly":"cardio","fiche":"233","front":"Antibioprophylaxie de l'endocardite : schéma de référence avant soin dentaire à risque ?","back":"**Amoxicilline 2 g** per os ou IV **30-60 min avant** (item 152) ; l'item 153 cite 3 g 1 h avant.","prio":"P1","sec":"s7"},{"id":"fc-233-467e61","poly":"cardio","fiche":"233","front":"Antibioprophylaxie chez l'allergique à la pénicilline : quelle erreur éviter ?","back":"Prescrire une **pénicilline** (notion inacceptable).","prio":"P1","sec":"s7"},{"id":"fc-233-dfd7cf","poly":"cardio","fiche":"233","front":"Antibioprophylaxie : alternatives à l'amoxicilline citées ?","back":"**Ampicilline** ; ou **céfazoline** / **ceftriaxone** (1 g IM ou IV).","prio":"P3","sec":"s7"},{"id":"fc-233-d14291","poly":"cardio","fiche":"233","front":"RA avec FE < 35 % : classes de l'IC à FE diminuée ?","back":"**IEC** (ou ARA2/sacubitril-valsartan), **bêtabloquant**, **antialdostérone**, **gliflozine**, **diurétique de l'anse** si congestion.","prio":"P2","sec":"s7"},{"id":"fc-233-911b0d","poly":"cardio","fiche":"233","front":"RA : 3 erreurs thérapeutiques ?","back":"Récuser sur le **seul âge** ; renoncer parce que la **FE est basse** ; proposer la **valvuloplastie** comme traitement de fond.","prio":"P1","sec":"s7"},{"id":"fc-233-01897a","poly":"cardio","fiche":"233","front":"IM importante symptomatique : conduite ?","back":"**On opère** ; il n'y a pas de traitement médical de fond de l'IM primaire.","prio":"P1","sec":"s8"},{"id":"fc-233-54ae1e","poly":"cardio","fiche":"233","front":"IM primaire : technique chirurgicale de préférence ?","back":"**Plastie reconstructrice**, à privilégier dans les **prolapsus**.","prio":"P1","sec":"s8"},{"id":"fc-233-44abea","poly":"cardio","fiche":"233","front":"IM avec VG altéré : plastie possible ?","back":"**Oui**, la plastie peut toujours être envisagée.","prio":"P2","sec":"s8"},{"id":"fc-233-ea903f","poly":"cardio","fiche":"233","front":"IM : remplacement valvulaire contre-indiqué en dessous de quelle FE ?","back":"**FE < 30 %** (contrairement à la plastie).","prio":"P2","sec":"s8"},{"id":"fc-233-00f554","poly":"cardio","fiche":"233","front":"IM à haut risque chirurgical : alternative ?","back":"**Clip percutané** (suture bord à bord), en centre expérimenté.","prio":"P2","sec":"s8"},{"id":"fc-233-8bb6a8","poly":"cardio","fiche":"233","front":"IM primaire importante asymptomatique sans critère : surveillance ?","back":"**Écho-doppler tous les 6 mois** ; chirurgie dès retentissement, dyspnée d'effort ou FA.","prio":"P2","sec":"s8"},{"id":"fc-233-7f9807","poly":"cardio","fiche":"233","front":"IM minime ou modérée (grade I-II) : conduite ?","back":"**Pas d'intervention** ; réévaluation clinique et écho ; hygiène, soins dentaires **sans antibioprophylaxie**.","prio":"P2","sec":"s8"},{"id":"fc-233-f9136b","poly":"cardio","fiche":"233","front":"IM secondaire : première étape thérapeutique ?","back":"**Traiter l'insuffisance cardiaque** (médicaments, **resynchronisation si QRS larges**) ; puis intervention plutôt **percutanée** si échec.","prio":"P1","sec":"s8"},{"id":"fc-233-3b2cbb","poly":"cardio","fiche":"233","front":"Resynchronisation cardiaque : critères (item 234) ?","back":"IC NYHA II-IV, **FEVG ≤ 35 %** et **QRS ≥ 130 ms**.","prio":"P2","sec":"s8"},{"id":"fc-233-8c3b6b","poly":"cardio","fiche":"233","front":"Plastie mitrale : avantages ?","back":"Respecte l'appareil sous-valvulaire, moindre morbimortalité, moindre risque d'endocardite, **pas d'anticoagulant** au long cours.","prio":"P2","sec":"s8"},{"id":"fc-233-7553b8","poly":"cardio","fiche":"233","front":"Plastie mitrale : limites ?","back":"**Léger risque de récidive** ; chirurgien expérimenté ; pas toujours faisable.","prio":"P3","sec":"s8"},{"id":"fc-233-956b15","poly":"cardio","fiche":"233","front":"IM : prothèse mécanique pour qui ?","back":"Plutôt **< 65 ans**, ou anticoagulant déjà nécessaire (**FA**).","prio":"P2","sec":"s8"},{"id":"fc-233-830627","poly":"cardio","fiche":"233","front":"IM : bioprothèse pour qui ?","back":"Plutôt **> 70 ans**, **CI aux anticoagulants**, **désir de grossesse**.","prio":"P2","sec":"s8"},{"id":"fc-233-ea8c73","poly":"cardio","fiche":"233","front":"IM primaire en OAP : traitement médical ?","back":"**Furosémide IV** 1 mg/kg + **trinitrine IV** 1 mg/h si PAS ≥ 110 mmHg.","prio":"P2","sec":"s8"},{"id":"fc-233-491e3e","poly":"cardio","fiche":"233","front":"IM + FA sur valve native sans RM : anticoagulant ?","back":"**AOD à privilégier** sur les AVK, selon le CHA₂DS₂-VA.","prio":"P2","sec":"s8"},{"id":"fc-233-4c82d0","poly":"cardio","fiche":"233","front":"Prothèse mécanique mitrale : INR cible (item 153) ?","back":"**3,0 à 4,0** selon le risque thrombotique de la prothèse (position mitrale = facteur de risque).","prio":"P3","sec":"s8"},{"id":"fc-233-076a10","poly":"cardio","fiche":"233","front":"Bioprothèse ou plastie mitrale : antithrombotique ?","back":"**AVK 3 mois** puis rien (sauf autre indication, ex. FA).","prio":"P3","sec":"s8"},{"id":"fc-233-a6c3cf","poly":"cardio","fiche":"233","front":"Maladie de Marfan : but du bêtabloquant ?","back":"**Réduire le risque de dissection aortique**.","prio":"P3","sec":"s8"},{"id":"fc-233-5c470d","poly":"cardio","fiche":"233","front":"IM : 3 erreurs de prise en charge ?","back":"**Clip** d'emblée chez un opérable ; opérer d'emblée une **IM secondaire** ; se rassurer sur une **FE à 58 %**.","prio":"P2","sec":"s8"},{"id":"fc-233-655073","poly":"cardio","fiche":"233","front":"IA sévère symptomatique : indication opératoire ?","back":"**Formelle**.","prio":"P1","sec":"s9"},{"id":"fc-233-1894ba","poly":"cardio","fiche":"233","front":"IA sévère et autre chirurgie cardiaque prévue (pontage, aorte, valve) : opérer l'IA ?","back":"Oui : indication **formelle** à la traiter dans le même temps.","prio":"P2","sec":"s9"},{"id":"fc-233-f2aea3","poly":"cardio","fiche":"233","front":"IA : l'indication opératoire peut-elle reposer sur le seul diamètre aortique ?","back":"**Oui**, quel que soit le grade de la fuite.","prio":"P2","sec":"s9"},{"id":"fc-233-c21508","poly":"cardio","fiche":"233","front":"IA opérée : à partir de quel diamètre remplacer aussi l'aorte ?","back":"**≥ 45 mm**.","prio":"P3","sec":"s9"},{"id":"fc-233-4a620e","poly":"cardio","fiche":"233","front":"IA aiguë sévère avec insuffisance cardiaque : indication ?","back":"Chirurgie **formelle et urgente**.","prio":"P1","sec":"s9"},{"id":"fc-233-9d92bb","poly":"cardio","fiche":"233","front":"Facteurs de risque aortiques (seuils abaissés) ?","back":"ATCD de **dissection**, IA ou IM sévère, **désir de grossesse**, **HTA non contrôlée**, progression **> 3 mm/an**.","prio":"P3","sec":"s9"},{"id":"fc-233-becc17","poly":"cardio","fiche":"233","front":"IA isolée : traitement chirurgical ?","back":"**RVA** par prothèse mécanique ou biologique, choix discuté avec le patient.","prio":"P2","sec":"s9"},{"id":"fc-233-5f509e","poly":"cardio","fiche":"233","front":"IA : quand préférer une bioprothèse ?","back":"En général **après 60-65 ans** ou si **désir de grossesse** ; prévenir d'une **réopération vers 10 ans**.","prio":"P2","sec":"s9"},{"id":"fc-233-ee15ab","poly":"cardio","fiche":"233","front":"IA + dilatation aortique : intervention de Bentall ?","back":"**RVA + tube aortique** avec **réimplantation des coronaires**.","prio":"P2","sec":"s9"},{"id":"fc-233-97b612","poly":"cardio","fiche":"233","front":"TAVI dans l'IA ?","back":"**Pas un traitement de l'IA** ; exceptionnel (très haut risque, sans endocardite) ; risque de **migration**.","prio":"P2","sec":"s9"},{"id":"fc-233-d8c16a","poly":"cardio","fiche":"233","front":"IA sévère en insuffisance cardiaque : bêtabloquant ?","back":"**Contre-indiqué** classiquement : allonge la diastole et **aggrave la fuite**.","prio":"P1","sec":"s9"},{"id":"fc-233-ed07b8","poly":"cardio","fiche":"233","front":"IA sévère en IC en attente de chirurgie : traitement ?","back":"**Diurétiques**, éventuellement IEC ou autre vasodilatateur ; **ne retarde pas la chirurgie**.","prio":"P2","sec":"s9"},{"id":"fc-233-fa832c","poly":"cardio","fiche":"233","front":"IA symptomatique traitée seulement par les médicaments de l'IC : erreur ?","back":"**Oui**, notion inacceptable : l'amélioration ne doit pas retarder la chirurgie.","prio":"P1","sec":"s9"},{"id":"fc-233-3b5ddc","poly":"cardio","fiche":"233","front":"IA : existe-t-il un médicament efficace ?","back":"**Non**, aucun médicament n'a démontré de bénéfice.","prio":"P1","sec":"s9"},{"id":"fc-233-2c232c","poly":"cardio","fiche":"233","front":"IA modérée à sévère : IEC pour prévenir le remodelage ?","back":"**Non recommandés**.","prio":"P2","sec":"s9"},{"id":"fc-233-053ca9","poly":"cardio","fiche":"233","front":"Marfan avec dilatation aortique : traitement validé ?","back":"**Bêtabloquant** (ARA2 seulement si intolérance).","prio":"P2","sec":"s9"},{"id":"fc-233-f112f8","poly":"cardio","fiche":"233","front":"IA sévère et sport ?","back":"**Compétition contre-indiquée** ; loisir d'endurance modéré encouragé.","prio":"P3","sec":"s9"},{"id":"fc-233-4ff580","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : examen à ne jamais oublier à partir d'un certain âge ?","back":"**Imagerie des coronaires** (coronarographie ou coroscanner).","prio":"P1","sec":"s10"},{"id":"fc-233-d97cde","poly":"cardio","fiche":"233","front":"IA : indications de l'imagerie coronaire préopératoire ?","back":"**Homme > 40 ans**, **femme > 50 ans**, FDR, coroscanner anormal ou non concluant.","prio":"P3","sec":"s10"},{"id":"fc-233-8624cb","poly":"cardio","fiche":"233","front":"Bicuspidie avant chirurgie : quoi mesurer ?","back":"La **taille de l'aorte** (geste associé ?).","prio":"P1","sec":"s10"},{"id":"fc-233-388ee6","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : examen vasculaire pour tous ?","back":"**Échodoppler des troncs supra-aortiques**.","prio":"P2","sec":"s10"},{"id":"fc-233-accb24","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : recherche de foyers infectieux ?","back":"Foyers **ORL et dentaires** : radiographie des sinus, **panoramique dentaire**, traitement des foyers.","prio":"P1","sec":"s10"},{"id":"fc-233-f81c58","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : autres éléments ?","back":"**Comorbidités** (fonction rénale, poumon) ; **avis gériatrique** chez le sujet très âgé.","prio":"P2","sec":"s10"},{"id":"fc-233-6a720f","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : buts ?","back":"**Évaluer le risque opératoire** et préciser le geste (pontage, aorte, tricuspide ?).","prio":"P2","sec":"s10"},{"id":"fc-233-a4bd9a","poly":"cardio","fiche":"233","front":"IM aiguë : tableau clinique ?","back":"**Urgence vitale** : OAP (parfois **unilatéral**), choc.","prio":"P1","sec":"s11"},{"id":"fc-233-d5f1c3","poly":"cardio","fiche":"233","front":"IM aiguë lors d'un SCA : place dans les causes de décompensation ?","back":"Cause **mécanique** (« M » de **CHAMPIT**) ; rupture ou dysfonction de pilier.","prio":"P2","sec":"s11"},{"id":"fc-233-adb1b4","poly":"cardio","fiche":"233","front":"OAP : mesures générales ?","back":"Position **assise**, voie veineuse, monitorage, ECG ; morphine non systématique ; **CPAP** si échec ; intubation si épuisement.","prio":"P2","sec":"s11"},{"id":"fc-233-9e8f6e","poly":"cardio","fiche":"233","front":"OAP : critères d'échec justifiant la CPAP ?","back":"**FR > 25/min**, **SaO₂ < 90 %**.","prio":"P3","sec":"s11"},{"id":"fc-233-c3a9a9","poly":"cardio","fiche":"233","front":"Choc cardiogénique : définition et traitement ?","back":"**PA < 90 mmHg + hypoperfusion** : **inotropes** (dobutamine), sonde urinaire, PA invasive ; assistance (ECMO) si échec.","prio":"P2","sec":"s11"},{"id":"fc-233-bf99d4","poly":"cardio","fiche":"233","front":"IM aiguë mal tolérée : traitement définitif ?","back":"**Chirurgie urgente** après traitement de l'OAP ou du choc.","prio":"P1","sec":"s11"},{"id":"fc-233-2031a6","poly":"cardio","fiche":"233","front":"IM aiguë : oxygénothérapie, quand et quel objectif ?","back":"Si **SaO₂ < 90 %** ; objectif **> 90 %** (prudence si risque d'hypercapnie).","prio":"P2","sec":"s11"},{"id":"fc-233-3ef0f2","poly":"cardio","fiche":"233","front":"Choc cardiogénique chez un patient sous bêtabloquant : quel inotrope à la place de la dobutamine ?","back":"**Milrinone** ou **énoximone**.","prio":"P3","sec":"s11"},{"id":"fc-233-08f2ee","poly":"cardio","fiche":"233","front":"IA aiguë : délai chirurgical selon la cause ?","back":"**Urgente** si IC ou dissection ; un peu **différée** possible si endocardite ou traumatisme selon la tolérance.","prio":"P2","sec":"s11"},{"id":"fc-233-a1017b","poly":"cardio","fiche":"233","front":"Endocardite avec IA : indications chirurgicales discutées ?","back":"**Sepsis non maîtrisé**, **insuffisance cardiaque**, **risque embolique majeur** (grosses végétations).","prio":"P3","sec":"s11"},{"id":"fc-233-c74588","poly":"cardio","fiche":"233","front":"RA : rythme du suivi ?","back":"**Suivi annuel** par le spécialiste ; réadresser si souffle modifié ou nouveaux symptômes.","prio":"P1","sec":"s12"},{"id":"fc-233-5ecd6d","poly":"cardio","fiche":"233","front":"IM significative asymptomatique : suivi ?","back":"Au moins une **ETT annuelle**.","prio":"P1","sec":"s12"},{"id":"fc-233-6ea638","poly":"cardio","fiche":"233","front":"IA importante : rythme du suivi ?","back":"**Tous les 6 mois à 1 an**, par un **cardiologue**.","prio":"P1","sec":"s12"},{"id":"fc-233-ae1708","poly":"cardio","fiche":"233","front":"IA modérée à moyenne : rythme du suivi ?","back":"**Tous les 2 à 3 ans** (IA sévère : 1 à 2 fois/an).","prio":"P3","sec":"s12"},{"id":"fc-233-827cb3","poly":"cardio","fiche":"233","front":"Aorte dilatée : rythme du suivi ?","back":"Écho **chaque année** ; IRM (plutôt) ou scanner de temps en temps.","prio":"P3","sec":"s12"},{"id":"fc-233-ee8b48","poly":"cardio","fiche":"233","front":"Porteur de prothèse : dyspnée ou récidive d'IC, quoi suspecter ?","back":"Une **dysfonction de prothèse**.","prio":"P1","sec":"s12"},{"id":"fc-233-dbabce","poly":"cardio","fiche":"233","front":"Porteur de prothèse : éléments de chaque consultation ?","back":"Symptômes, **auscultation de la prothèse**, **fièvre** ou foyer infectieux, signes ischémiques ou hémorragiques, suivi dentaire.","prio":"P2","sec":"s12"},{"id":"fc-233-9f8547","poly":"cardio","fiche":"233","front":"Après remplacement valvulaire : réadaptation cardiaque ?","back":"Vers **J8**, pendant **3-4 semaines**.","prio":"P3","sec":"s12"},{"id":"fc-233-285ec5","poly":"cardio","fiche":"233","front":"Après remplacement valvulaire : quand l'ETT de référence ?","back":"Au **2e-4e mois** (après une ETT postopératoire précoce).","prio":"P3","sec":"s12"},{"id":"fc-233-335575","poly":"cardio","fiche":"233","front":"Rythme des ETT : prothèse mécanique ou bioprothèse ?","back":"Mécanique : **tous les 1-2 ans** ; bioprothèse : **3 mois, 1 an puis chaque année**.","prio":"P3","sec":"s12"},{"id":"fc-233-a7d505","poly":"cardio","fiche":"233","front":"IA : erreur après régression des signes d'IC sous diurétiques ?","back":"**Repousser la chirurgie** : le remodelage du VG peut persister après remplacement.","prio":"P2","sec":"s12"},{"id":"fc-233-b52581","poly":"cardio","fiche":"233","front":"Patient valvulaire : 2 messages d'éducation ?","back":"**Prévention de l'endocardite** ; **consultation urgente** si symptômes d'effort.","prio":"P1","sec":"s13"},{"id":"fc-233-8ffc34","poly":"cardio","fiche":"233","front":"Fièvre chez un valvulaire : quoi évoquer ?","back":"**Endocardite infectieuse**.","prio":"P1","sec":"s13"},{"id":"fc-233-87a48e","poly":"cardio","fiche":"233","front":"Valvulopathie : quand adresser au spécialiste ?","back":"**Symptômes**, souffle modifié, **suivi annuel** ; une **IA sévère** même asymptomatique.","prio":"P1","sec":"s13"},{"id":"fc-233-d8bd12","poly":"cardio","fiche":"233","front":"Valve native (IM, IA, RA) : antibioprophylaxie avant soin dentaire ?","back":"**Non** (pas de prescription systématique) ; hygiène buccodentaire et cutanée.","prio":"P1","sec":"s13"},{"id":"fc-233-4fd58d","poly":"cardio","fiche":"233","front":"Valvulopathie native : mesures préventives de l'endocardite ?","back":"Hygiène buccodentaire, **dentiste 1 fois/an**, désinfection des plaies, consulter vite si fièvre, **pas d'automédication antibiotique**.","prio":"P2","sec":"s13"},{"id":"fc-233-9eb383","poly":"cardio","fiche":"233","front":"Indications de l'antibioprophylaxie de l'endocardite ?","back":"**Prothèse valvulaire** (TAVI compris) ou matériel de réparation, **antécédent d'endocardite**, **cardiopathie cyanogène**.","prio":"P1","sec":"s13"},{"id":"fc-233-2bdaca","poly":"cardio","fiche":"233","front":"Porteur de prothèse : documents à remettre ?","back":"**Carte de porteur de prothèse**, carnet d'anticoagulant (INR cible), carte d'antibioprophylaxie.","prio":"P2","sec":"s13"},{"id":"fc-233-0827fe","poly":"cardio","fiche":"233","front":"Porteur de prothèse : fréquence du suivi dentaire ?","back":"**Au moins 2 fois/an**.","prio":"P2","sec":"s13"},{"id":"fc-233-b00bcc","poly":"cardio","fiche":"233","front":"Maladie de Marfan : mesure familiale ?","back":"**Dépistage des apparentés du 1er degré**.","prio":"P1","sec":"s13"},{"id":"fc-233-aef3ec","poly":"cardio","fiche":"233","front":"Bicuspidie avec IA : taux de récurrence familiale ?","back":"**10 %** → dépistage familial proposé.","prio":"P3","sec":"s13"},{"id":"fc-233-829395","poly":"cardio","fiche":"233","front":"IA : 3 notions inacceptables ?","back":"Antibiotiques **systématiques** avant tout soin dentaire ; ne pas expliquer la prophylaxie ; ne pas évoquer un **Marfan** devant une IA annuloectasiante.","prio":"P1","sec":"s13"},{"id":"fc-233-44fdd6","poly":"cardio","fiche":"233","front":"IA aiguë : évolution et risques ?","back":"Évolution **rapide** ; risque d'**OAP**, voire de **mort subite** → chirurgie précoce habituelle.","prio":"P2","sec":"s5"},{"id":"fc-233-644857","poly":"cardio","fiche":"233","front":"IA sur prothèse : 2 types et leurs causes ?","back":"**Paraprothétique** (désinsertion septique ou aseptique) ; **intraprothétique** (thrombus, endocardite, dégénérescence).","prio":"P3","sec":"s2"},{"id":"fc-233-97895e","poly":"cardio","fiche":"233","front":"IA : rythme de l'examen dentaire recommandé ?","back":"**Tous les 6 mois** (2 fois par an), avec une bonne hygiène buccodentaire.","prio":"P3","sec":"s13"},{"id":"fc-234-41da80","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : définition physiopathologique ?","back":"Le cœur ne délivre plus un **débit adapté** aux besoins et/ou ne fonctionne qu'avec des **pressions de remplissage anormalement hautes**.","prio":"P1","sec":"s1"},{"id":"fc-234-c5bd0a","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : définition clinique (3 éléments) ?","back":"**Symptômes** (dyspnée, œdèmes, fatigue) + **signes** (tachycardie, crépitants, turgescence jugulaire) + **dysfonction cardiaque** (structure ou fonction).","prio":"P1","sec":"s1"},{"id":"fc-234-49142b","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : origines possibles de la dysfonction ?","back":"**Myocarde**, **valves**, **péricarde**, trouble du **rythme** ou de la **conduction**.","prio":"P2","sec":"s1"},{"id":"fc-234-799a31","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : pourquoi le diagnostic clinique est-il parfois difficile ?","back":"Symptômes **peu spécifiques**, signes **peu sensibles** (la rétention hydrosodée disparaît vite sous traitement).","prio":"P2","sec":"s1"},{"id":"fc-234-9bd9ee","poly":"cardio","fiche":"234","front":"Dysfonction VG systolique asymptomatique : intérêt de la dépister ?","back":"**Traiter tôt** et améliorer le pronostic.","prio":"P2","sec":"s1"},{"id":"fc-234-53c901","poly":"cardio","fiche":"234","front":"IC à FE diminuée : seuil de FEVG ?","back":"**FEVG ≤ 40 %**.","prio":"P1","sec":"s1"},{"id":"fc-234-d0e5fd","poly":"cardio","fiche":"234","front":"IC à FE légèrement diminuée : seuil de FEVG ?","back":"**FEVG 41 à 49 %**.","prio":"P1","sec":"s1"},{"id":"fc-234-86cab7","poly":"cardio","fiche":"234","front":"IC à FE préservée : seuil de FEVG ?","back":"**FEVG ≥ 50 %**.","prio":"P1","sec":"s1"},{"id":"fc-234-3cf582","poly":"cardio","fiche":"234","front":"IC à FE préservée : fréquence et terrain ?","back":"**Au moins 50 %** des IC ; surtout la **femme** et le **sujet âgé**.","prio":"P1","sec":"s1"},{"id":"fc-234-8ea052","poly":"cardio","fiche":"234","front":"IC à FE légèrement diminuée : traitement ?","back":"Mêmes traitements que l'IC à FE diminuée, mais niveau de recommandation **IIb, C** (et non I, A).","prio":"P2","sec":"s1"},{"id":"fc-234-ba5464","poly":"cardio","fiche":"234","front":"IC aiguë : définition ?","back":"Symptômes et signes d'apparition **généralement rapide** (de novo ou cardiopathie connue) : **congestion** et/ou **bas débit** ; le plus souvent hospitalisation pour traitement **IV**.","prio":"P1","sec":"s1"},{"id":"fc-234-a93859","poly":"cardio","fiche":"234","front":"IC chronique : définition ?","back":"Patient **hors décompensation**, ambulatoire, sous traitement **oral**.","prio":"P2","sec":"s1"},{"id":"fc-234-7a0094","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : prévalence ?","back":"**1 à 2 %** de la population, croissante avec l'âge.","prio":"P2","sec":"s1"},{"id":"fc-234-2a5c1c","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : âge moyen au diagnostic ?","back":"**75 à 80 ans** en Europe (78 ans dans les points clés).","prio":"P3","sec":"s1"},{"id":"fc-234-727424","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : mortalité à 5 ans ?","back":"Environ **50 %**.","prio":"P2","sec":"s1"},{"id":"fc-234-309f0c","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : évolution de la prévalence et de l'incidence ?","back":"**Prévalence en hausse** (vieillissement, meilleure prise en charge) ; **incidence standardisée sur l'âge en baisse**.","prio":"P3","sec":"s1"},{"id":"fc-234-1dd34f","poly":"cardio","fiche":"234","front":"Examen clinique pauvre : élimine-t-il une IC ?","back":"**Non** : chez un patient traité, les signes congestifs peuvent avoir disparu.","prio":"P1","sec":"s1"},{"id":"fc-234-7002c8","poly":"cardio","fiche":"234","front":"Débit cardiaque : formule ?","back":"**DC = VES × FC**.","prio":"P2","sec":"s2"},{"id":"fc-234-436e67","poly":"cardio","fiche":"234","front":"Fraction d'éjection : formule ?","back":"**FE = VES / VTD = (VTD − VTS) / VTD**.","prio":"P2","sec":"s2"},{"id":"fc-234-0ddea9","poly":"cardio","fiche":"234","front":"VES : 3 déterminants ?","back":"**Précharge**, **postcharge**, **contractilité**.","prio":"P3","sec":"s2"},{"id":"fc-234-d8982b","poly":"cardio","fiche":"234","front":"IC à FE préservée : mécanisme ?","back":"VG qui se vide bien mais **se remplit mal** : parois épaissies, fibreuses, **rigides** ; cavité en général non dilatée.","prio":"P2","sec":"s2"},{"id":"fc-234-00848a","poly":"cardio","fiche":"234","front":"IC à FE préservée : facteurs associés ?","back":"**HTA** et **obésité** ; sujet âgé, femme.","prio":"P3","sec":"s2"},{"id":"fc-234-18774d","poly":"cardio","fiche":"234","front":"OAP cardiogénique : mécanisme ?","back":"Pression capillaire pulmonaire élevée (en général **≥ 25 mmHg**) → **transsudat** vers les alvéoles.","prio":"P1","sec":"s2"},{"id":"fc-234-885550","poly":"cardio","fiche":"234","front":"Œdème pulmonaire lésionnel : mécanisme ?","back":"Lésion de la **membrane alvéolocapillaire** (causes nombreuses) : œdème **non cardiogénique**.","prio":"P2","sec":"s2"},{"id":"fc-234-00ef68","poly":"cardio","fiche":"234","front":"Mécanismes compensateurs de l'IC : citer ?","back":"**Dilatation** VG, **hypertrophie**, loi de **Starling**, **tachycardie**, **vasoconstriction**, **rétention hydrosodée**, **activation neurohormonale**.","prio":"P2","sec":"s2"},{"id":"fc-234-18b82a","poly":"cardio","fiche":"234","front":"Dilatation ventriculaire compensatrice : bénéfice et prix ?","back":"Maintient le **VES** malgré une FE basse ; mais **contrainte pariétale** accrue.","prio":"P3","sec":"s2"},{"id":"fc-234-d29488","poly":"cardio","fiche":"234","front":"Hypertrophie concentrique : loi en jeu ?","back":"**Laplace** : contrainte = pression × rayon / épaisseur.","prio":"P3","sec":"s2"},{"id":"fc-234-679dec","poly":"cardio","fiche":"234","front":"Loi de Starling : principe ?","back":"Plus les fibres sont étirées par la précharge, plus l'**inotropie** augmente (jusqu'à une limite).","prio":"P3","sec":"s2"},{"id":"fc-234-cc9450","poly":"cardio","fiche":"234","front":"Rétention hydrosodée de l'IC : bénéfice et prix ?","back":"Augmente volume et précharge ; prix : **signes congestifs** (œdèmes, épanchements).","prio":"P3","sec":"s2"},{"id":"fc-234-2f90f7","poly":"cardio","fiche":"234","front":"Activation neurohormonale : effets délétères ?","back":"Travail cardiaque accru, effets **proarythmiques**, **toxicité des catécholamines** sur les myocytes.","prio":"P3","sec":"s2"},{"id":"fc-234-998fca","poly":"cardio","fiche":"234","front":"Désynchronisation ventriculaire : cause typique ?","back":"Trouble de conduction, typiquement le **BBG** : paroi latérale qui se contracte **en retard** → peut aggraver l'IC.","prio":"P2","sec":"s2"},{"id":"fc-234-0f0968","poly":"cardio","fiche":"234","front":"FA dans l'IC : conséquences ?","back":"Perte de la systole atriale (aggrave **souvent** l'IC) et risque accru d'**AVC**.","prio":"P2","sec":"s2"},{"id":"fc-234-0439c3","poly":"cardio","fiche":"234","front":"IC : cause de la plupart des morts subites ?","back":"**TV/FV** (d'où le défibrillateur implantable).","prio":"P2","sec":"s2"},{"id":"fc-234-9fb469","poly":"cardio","fiche":"234","front":"Anciens noms des IC à FE diminuée et préservée ?","back":"IC **systolique** (FE diminuée) et IC **diastolique** (FE préservée).","prio":"P3","sec":"s2"},{"id":"fc-234-df85e5","poly":"cardio","fiche":"234","front":"IC droite : cause la plus fréquente ?","back":"L'**IC gauche** (hypertension pulmonaire).","prio":"P2","sec":"s2"},{"id":"fc-234-f1c785","poly":"cardio","fiche":"234","front":"Dyspnée d'effort dans l'IC : valeur ?","back":"Fréquente, souvent révélatrice, **peu spécifique** ; reflète la sévérité (**NYHA**).","prio":"P2","sec":"s3"},{"id":"fc-234-2a80e1","poly":"cardio","fiche":"234","front":"IC : 2 symptômes plus spécifiques que la dyspnée d'effort ?","back":"**Orthopnée** et **dyspnée paroxystique nocturne**.","prio":"P1","sec":"s3"},{"id":"fc-234-ee7a72","poly":"cardio","fiche":"234","front":"Orthopnée : définition et mécanisme ?","back":"Dyspnée en **décubitus** (dort tête relevée) ; redistribution du sang vers le thorax → pression capillaire en hausse.","prio":"P2","sec":"s3"},{"id":"fc-234-ea15fe","poly":"cardio","fiche":"234","front":"IC : signes trompeurs faisant penser au poumon ?","back":"**Asthme cardiaque** (bradypnée expiratoire sifflante), **toux** d'effort ou de décubitus, **hémoptysies**.","prio":"P1","sec":"s3"},{"id":"fc-234-7547b0","poly":"cardio","fiche":"234","front":"Subœdème pulmonaire : définition ?","back":"Crise de dyspnée de repos (OAP) qui **cède spontanément**.","prio":"P2","sec":"s3"},{"id":"fc-234-11e8fd","poly":"cardio","fiche":"234","front":"NYHA II : définition ?","back":"Gêne pour des **efforts importants** : marche rapide, en côte, escaliers **≥ 2 étages**.","prio":"P1","sec":"s3"},{"id":"fc-234-8886b1","poly":"cardio","fiche":"234","front":"NYHA III : définition ?","back":"Gêne pour des **efforts peu intenses** : marche en terrain plat, escaliers **< 2 étages**.","prio":"P1","sec":"s3"},{"id":"fc-234-083e8c","poly":"cardio","fiche":"234","front":"NYHA IV : définition ?","back":"Gêne **permanente au repos** ou pour des efforts minimes (s'habiller, se laver).","prio":"P1","sec":"s3"},{"id":"fc-234-7a1ce6","poly":"cardio","fiche":"234","front":"NYHA I : définition ?","back":"**Aucune gêne** pour les efforts habituels.","prio":"P2","sec":"s3"},{"id":"fc-234-e54be3","poly":"cardio","fiche":"234","front":"IC sévère : signes ?","back":"Respiration de **Cheyne-Stokes**, **confusion** (bas débit cérébral), troubles digestifs.","prio":"P2","sec":"s3"},{"id":"fc-234-07690c","poly":"cardio","fiche":"234","front":"IC droite : symptôme digestif ?","back":"**Hépatalgie** (hypocondre droit), d'abord à l'effort puis au repos.","prio":"P2","sec":"s3"},{"id":"fc-234-fa3033","poly":"cardio","fiche":"234","front":"IC : signes cardiaques à l'examen ?","back":"Choc de pointe dévié vers l'aisselle, tachycardie ou rythme irrégulier, **galop B3**, éclat de B2 pulmonaire, souffle d'IM ou d'IT.","prio":"P2","sec":"s3"},{"id":"fc-234-53b9a4","poly":"cardio","fiche":"234","front":"IC : épanchement pleural, nature à la ponction ?","back":"**Transsudat** (protides **< 30 g/L**).","prio":"P2","sec":"s3"},{"id":"fc-234-32693b","poly":"cardio","fiche":"234","front":"IC : seuil de PAS signant la gravité ?","back":"**PAS < 100 mmHg**.","prio":"P1","sec":"s3"},{"id":"fc-234-a583ef","poly":"cardio","fiche":"234","front":"OAP avec PA élevée : possible ?","back":"**Oui** : **OAP hypertensif**.","prio":"P2","sec":"s3"},{"id":"fc-234-29e183","poly":"cardio","fiche":"234","front":"IC droite : signes périphériques ?","back":"**TRHOA** : Turgescence jugulaire, Reflux hépatojugulaire, Hépatomégalie, Œdèmes, Ascite.","prio":"P1","sec":"s3"},{"id":"fc-234-99659d","poly":"cardio","fiche":"234","front":"IC droite : signe très spécifique ?","back":"**Turgescence jugulaire** (patient demi-assis).","prio":"P2","sec":"s3"},{"id":"fc-234-7155d8","poly":"cardio","fiche":"234","front":"Œdèmes de l'IC : caractéristiques ?","back":"**Mous, blancs, indolores**, prenant le **godet**, **déclives** (jambes, lombes si alité).","prio":"P2","sec":"s3"},{"id":"fc-234-cd68c0","poly":"cardio","fiche":"234","front":"IC à un stade très avancé : signes ?","back":"Pouls alternant, oligurie, **cachexie**, Cheyne-Stokes.","prio":"P3","sec":"s3"},{"id":"fc-234-79bcc3","poly":"cardio","fiche":"234","front":"IC hors poussée sous traitement : signification de signes physiques présents ?","back":"Élément de **gravité** (examen souvent pauvre).","prio":"P2","sec":"s3"},{"id":"fc-234-0e27e9","poly":"cardio","fiche":"234","front":"IC : rôle de l'ECG ?","back":"Peu utile au diagnostic positif ; oriente vers une **cause** (onde Q, trouble du rythme, hypertrophie).","prio":"P2","sec":"s4"},{"id":"fc-234-bae4a1","poly":"cardio","fiche":"234","front":"IC : anomalie ECG à repérer pour le traitement ?","back":"**Bloc de branche**, surtout **gauche** (QRS > 120 ms) → discuter **resynchronisation**.","prio":"P1","sec":"s4"},{"id":"fc-234-d949e4","poly":"cardio","fiche":"234","front":"Radiographie thoracique dans la dyspnée aiguë : indication ?","back":"**Toujours** faite ; indispensable pour le retentissement pleuropulmonaire.","prio":"P2","sec":"s4"},{"id":"fc-234-d33970","poly":"cardio","fiche":"234","front":"BNP/NT-proBNP : origine et atout principal ?","back":"Dosés en **1re intention** ; libérés par les **myocytes étirés** ; excellente **valeur prédictive négative**.","prio":"P1","sec":"s4"},{"id":"fc-234-02584a","poly":"cardio","fiche":"234","front":"IC : examen clé indispensable ?","back":"**ETT couplée au doppler** : type d'IC (FEVG), cause, retentissement, orientation thérapeutique.","prio":"P1","sec":"s4"},{"id":"fc-234-62735e","poly":"cardio","fiche":"234","front":"Radiographie : seuil de cardiomégalie ?","back":"**Rapport cardiothoracique > 0,5** (son absence n'écarte pas l'IC).","prio":"P2","sec":"s4"},{"id":"fc-234-a9aed2","poly":"cardio","fiche":"234","front":"Radiographie : 3 stades de la stase pulmonaire ?","back":"**Redistribution** vers les sommets → **œdème interstitiel** (Kerley) → **œdème alvéolaire** (ailes de papillon).","prio":"P2","sec":"s4"},{"id":"fc-234-3f9521","poly":"cardio","fiche":"234","front":"Œdème interstitiel radiologique : signes ?","back":"**Lignes B de Kerley**, hiles flous, images réticulonodulaires des bases.","prio":"P3","sec":"s4"},{"id":"fc-234-3fe409","poly":"cardio","fiche":"234","front":"Dyspnée aiguë : seuils BNP/NT-proBNP sous lesquels l'IC est très improbable ?","back":"**BNP < 100 pg/mL** ; **NT-proBNP < 300 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-234-d07d10","poly":"cardio","fiche":"234","front":"Présentation non aiguë : seuils BNP/NT-proBNP sous lesquels l'IC est très improbable ?","back":"**BNP < 35 pg/mL** ; **NT-proBNP < 125 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-234-3e6053","poly":"cardio","fiche":"234","front":"Hors urgence : stratégie diagnostique (ESC 2021) ?","back":"Doser **BNP/NT-proBNP** ; si ≥ seuils (ou forte suspicion, dosage indisponible) → **échocardiographie**.","prio":"P2","sec":"s4"},{"id":"fc-234-7273af","poly":"cardio","fiche":"234","front":"BNP en faveur d'une origine cardiaque d'une dyspnée aiguë ?","back":"**BNP > 300 pg/mL**.","prio":"P3","sec":"s4"},{"id":"fc-234-897304","poly":"cardio","fiche":"234","front":"NT-proBNP en faveur d'une origine cardiaque selon l'âge ?","back":"**> 450** pg/mL avant 50 ans, **> 900** de 50 à 75 ans, **> 1 800** après 75 ans.","prio":"P3","sec":"s4"},{"id":"fc-234-a8b59d","poly":"cardio","fiche":"234","front":"Peptides natriurétiques : facteurs qui les augmentent ou les diminuent ?","back":"Augmentent : **âge**, **insuffisance rénale**, **FA** ; diminuent : **obésité**.","prio":"P2","sec":"s4"},{"id":"fc-234-cfd0ae","poly":"cardio","fiche":"234","front":"BNP en zone grise : interprétation ?","back":"Toujours tenir compte de la **clinique**.","prio":"P3","sec":"s4"},{"id":"fc-234-096709","poly":"cardio","fiche":"234","front":"ETT : orientation étiologique selon l'aspect ?","back":"Trouble segmentaire → **ischémie** ; hypertrophie → **HTA** ; hypertrophie asymétrique septale → **CMH**.","prio":"P3","sec":"s4"},{"id":"fc-234-57ac5f","poly":"cardio","fiche":"234","front":"IC : biologie standard (ESC 2021) ?","back":"Natrémie, kaliémie, créatinine, BNP, glycémie/HbA1c, lipides, bilan hépatique, **TSHus**, NFS, **ferritine** et saturation de la transferrine.","prio":"P3","sec":"s4"},{"id":"fc-234-505644","poly":"cardio","fiche":"234","front":"Coroscanner dans l'IC : quand le privilégier ?","back":"Probabilité coronaire **faible ou intermédiaire**, ou tests d'ischémie non concluants.","prio":"P3","sec":"s4"},{"id":"fc-234-99df79","poly":"cardio","fiche":"234","front":"Coronarographie normale + FEVG basse sans autre cause : diagnostic ?","back":"**Cardiomyopathie dilatée**.","prio":"P3","sec":"s4"},{"id":"fc-234-ce0794","poly":"cardio","fiche":"234","front":"IRM cardiaque dans l'IC : indications ?","back":"FE si peu échogène ; **myocardite**, DAVD, sarcoïdose, **amylose** ; séquelle d'infarctus, viabilité ; fibrose.","prio":"P3","sec":"s4"},{"id":"fc-234-3008f8","poly":"cardio","fiche":"234","front":"Scintigraphie au technétium : quelle indication dans l'IC ?","back":"**Amylose à transthyrétine**.","prio":"P3","sec":"s4"},{"id":"fc-234-8688c5","poly":"cardio","fiche":"234","front":"Épreuve d'effort avec VO₂ : intérêt ?","back":"Capacité d'effort objective ; pic de VO₂ très abaissé → discuter une **greffe**.","prio":"P3","sec":"s4"},{"id":"fc-234-233096","poly":"cardio","fiche":"234","front":"Cathétérisme droit : seuil de résistances pulmonaires contre-indiquant la greffe ?","back":"**> 5 unités Wood**.","prio":"P3","sec":"s4"},{"id":"fc-234-20d224","poly":"cardio","fiche":"234","front":"BNP bas au cours d'une dyspnée aiguë : conséquence ?","back":"**Douter** de l'origine cardiaque.","prio":"P2","sec":"s4"},{"id":"fc-234-f77f7c","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : première cause ?","back":"**Cardiopathie ischémique**.","prio":"P1","sec":"s5"},{"id":"fc-234-aa262a","poly":"cardio","fiche":"234","front":"IC ischémique sans infarctus : particularité ?","back":"FE éventuellement **réversible** après revascularisation (**viabilité**).","prio":"P2","sec":"s5"},{"id":"fc-234-0e983a","poly":"cardio","fiche":"234","front":"HTA et IC : mécanismes ?","back":"Hypertrophie + fibrose → dysfonction **diastolique** (IC à FE préservée du sujet âgé) ; maladie coronaire ; baisse de FE par postcharge élevée.","prio":"P2","sec":"s5"},{"id":"fc-234-b0762a","poly":"cardio","fiche":"234","front":"Cardiomyopathie dilatée : définition et place chez le jeune ?","back":"Dilatation + **baisse de la FEVG** ; **1re cause d'IC et de transplantation chez le sujet jeune**.","prio":"P1","sec":"s5"},{"id":"fc-234-82f895","poly":"cardio","fiche":"234","front":"CMD familiale : fréquence et transmission ?","back":"Environ **25 %** ; monogénique, le plus souvent **autosomique dominante**.","prio":"P2","sec":"s5"},{"id":"fc-234-531982","poly":"cardio","fiche":"234","front":"CMD : causes toxiques ?","back":"**Alcool**, **amphétamines**, **cocaïne**.","prio":"P2","sec":"s5"},{"id":"fc-234-acd647","poly":"cardio","fiche":"234","front":"CMD : causes infectieuses ?","back":"**Myocardites virales** (coxsackie, CMV, HHV-6, VIH) ou bactériennes (brucellose, borréliose) ; **Chagas**.","prio":"P3","sec":"s5"},{"id":"fc-234-efe564","poly":"cardio","fiche":"234","front":"CMD : causes auto-immunes ?","back":"**Sarcoïdose**, Churg et Strauss, sclérodermie, lupus.","prio":"P3","sec":"s5"},{"id":"fc-234-2a40d7","poly":"cardio","fiche":"234","front":"CMD : causes endocriniennes et nutritionnelles ?","back":"Dysthyroïdie, phéochromocytome, hypocalcémie ; carences en **carnitine**, **thiamine**, **sélénium**.","prio":"P3","sec":"s5"},{"id":"fc-234-a20f5a","poly":"cardio","fiche":"234","front":"CMD : causes médicamenteuses et autres ?","back":"Chloroquine, clozapine ; **anthracyclines**, **trastuzumab** ; **péripartum** ; **takotsubo**.","prio":"P2","sec":"s5"},{"id":"fc-234-1465da","poly":"cardio","fiche":"234","front":"Cardiomyopathie hypertrophique : caractéristiques ?","back":"Hypertrophie le plus souvent **asymétrique septale**, FE conservée ; obstruction sous-aortique dans ~**25 %** ; **autosomique dominante** (sarcomère).","prio":"P1","sec":"s5"},{"id":"fc-234-583808","poly":"cardio","fiche":"234","front":"CMH : place dans la mort subite ?","back":"**1re cause de mort subite chez le jeune athlète**.","prio":"P1","sec":"s5"},{"id":"fc-234-53a97c","poly":"cardio","fiche":"234","front":"Cardiomyopathie restrictive : cause la plus fréquente et pronostic ?","back":"**Amylose cardiaque** ; pronostic **en général sévère** dès les signes d'IC.","prio":"P2","sec":"s5"},{"id":"fc-234-62b236","poly":"cardio","fiche":"234","front":"Valvulopathie compliquée d'IC : signification ?","back":"**Tournant évolutif grave** → traitement radical souvent justifié.","prio":"P2","sec":"s5"},{"id":"fc-234-3ced5f","poly":"cardio","fiche":"234","front":"Valvulopathie pouvant donner un OAP avec VG normal ?","back":"Le **RM**.","prio":"P3","sec":"s5"},{"id":"fc-234-b21007","poly":"cardio","fiche":"234","front":"Tachycardiomyopathie : définition ?","back":"Altération de la FE due à une **FA rapide permanente et prolongée** ; traiter le trouble du rythme **guérit souvent** l'IC.","prio":"P2","sec":"s5"},{"id":"fc-234-89ebaa","poly":"cardio","fiche":"234","front":"IC : causes péricardiques ?","back":"Épanchement abondant, **tamponnade**, **péricardite chronique constrictive**.","prio":"P2","sec":"s5"},{"id":"fc-234-52895c","poly":"cardio","fiche":"234","front":"IC à débit augmenté : causes ?","back":"**Anémie**, **fistule artérioveineuse**, **hyperthyroïdie**, carence en **thiamine** (béribéri), Paget.","prio":"P2","sec":"s5"},{"id":"fc-234-1dcb33","poly":"cardio","fiche":"234","front":"IC droite isolée : causes pulmonaires et vasculaires ?","back":"**Cœur pulmonaire** (hypoxémie), **embolie pulmonaire** (aiguë ou séquelles), **HTAP**.","prio":"P2","sec":"s5"},{"id":"fc-234-9534d6","poly":"cardio","fiche":"234","front":"IC droite isolée : causes cardiaques ?","back":"**Infarctus du VD**, cardiomyopathie VD **arythmogène**, valvulopathie **tricuspide**, **péricardite constrictive**.","prio":"P2","sec":"s5"},{"id":"fc-234-a77407","poly":"cardio","fiche":"234","front":"IC à FEVG abaissée : quelle cause toujours éliminer ?","back":"Une origine **ischémique** (coronarographie, ou coroscanner chez le sujet jeune).","prio":"P1","sec":"s5"},{"id":"fc-234-6312e9","poly":"cardio","fiche":"234","front":"OAP cardiogénique : prise en charge ?","back":"**Immédiate** : les examens ne doivent **pas retarder** le traitement.","prio":"P1","sec":"s6"},{"id":"fc-234-a59726","poly":"cardio","fiche":"234","front":"OAP : tableau clinique ?","back":"Polypnée, **orthopnée** (reste assis), anxiété, sueurs, cyanose, expectoration **mousseuse saumonée**, tirage.","prio":"P1","sec":"s6"},{"id":"fc-234-dc7739","poly":"cardio","fiche":"234","front":"OAP : évolution des crépitants avec la sévérité ?","back":"De plus en plus haut dans les champs : « **marée montante** ».","prio":"P2","sec":"s6"},{"id":"fc-234-0e1539","poly":"cardio","fiche":"234","front":"OAP : troponine modérément élevée, signification ?","back":"Possible **sans SCA** ; n'affirme pas une maladie coronaire aiguë.","prio":"P2","sec":"s6"},{"id":"fc-234-6aa7c2","poly":"cardio","fiche":"234","front":"OAP : gaz du sang typiques ?","back":"**Hypoxie**, **hypocapnie**.","prio":"P3","sec":"s6"},{"id":"fc-234-c58d40","poly":"cardio","fiche":"234","front":"IC aiguë : premier facteur déclenchant à rechercher ?","back":"**Rupture** ou mauvaise observance du **traitement** ; **écarts de régime sans sel**.","prio":"P1","sec":"s6"},{"id":"fc-234-f1f3af","poly":"cardio","fiche":"234","front":"IC aiguë : autres facteurs déclenchants ?","back":"Infection, anémie, **FA**, poussée hypertensive, **SCA**, embolie pulmonaire, dysthyroïdie (amiodarone), iatrogénie.","prio":"P2","sec":"s6"},{"id":"fc-234-c4fa75","poly":"cardio","fiche":"234","front":"IC aiguë : médicaments déclenchants ?","back":"Antiarythmique **dépresseur** du cœur, **bêtabloquant**, **AINS**, **diltiazem/vérapamil**, excès de diurétiques ou vasodilatateurs.","prio":"P2","sec":"s6"},{"id":"fc-234-92b4a0","poly":"cardio","fiche":"234","front":"Choc cardiogénique : critère tensionnel ?","back":"**PAS < 90 mmHg**, ou chute de **> 30 mmHg**, pendant **au moins 30 min**.","prio":"P1","sec":"s6"},{"id":"fc-234-63a3b0","poly":"cardio","fiche":"234","front":"Choc cardiogénique : signes d'hypoperfusion ?","back":"Extrémités **froides, cyanosées, marbrées** ; **oligurie < 20 mL/h** ; sueurs ; **confusion**/agitation ; débit bas à l'écho.","prio":"P1","sec":"s6"},{"id":"fc-234-e53e63","poly":"cardio","fiche":"234","front":"Choc cardiogénique : moyen mnémotechnique de la fiche ?","back":"**PSTOC** : Pression effondrée, Sueurs, Troubles de perfusion, Oligurie, Conscience altérée.","prio":"P2","sec":"s6"},{"id":"fc-234-504fef","poly":"cardio","fiche":"234","front":"Choc cardiogénique : définition et pronostic ?","back":"Stade ultime de défaillance aiguë : chute du débit, **anoxie tissulaire** ; **mauvais pronostic**.","prio":"P2","sec":"s6"},{"id":"fc-234-ef0b3b","poly":"cardio","fiche":"234","front":"Choc cardiogénique : la PAS suffit-elle au diagnostic ?","back":"**Non** : hypotension + **hypoperfusion** + **bas débit**.","prio":"P2","sec":"s6"},{"id":"fc-234-fb921c","poly":"cardio","fiche":"234","front":"IC aiguë au cours d'un SCA : principe ?","back":"Traiter **à la fois** le SCA et la poussée.","prio":"P3","sec":"s6"},{"id":"fc-234-50ba35","poly":"cardio","fiche":"234","front":"Dyspnée aiguë : 4 diagnostics différentiels de l'OAP ?","back":"**PEBA** : Pneumopathie, Embolie pulmonaire, BPCO (exacerbation), Asthme.","prio":"P1","sec":"s7"},{"id":"fc-234-a6e01d","poly":"cardio","fiche":"234","front":"Pneumopathie vs OAP : arguments ?","back":"Tableau **infectieux**, crépitants **localisés**, opacité **systématisée**, BNP normal ou peu élevé.","prio":"P2","sec":"s7"},{"id":"fc-234-a15e18","poly":"cardio","fiche":"234","front":"Embolie pulmonaire vs OAP : argument auscultatoire ?","back":"Auscultation pulmonaire souvent **normale** (contexte favorisant).","prio":"P2","sec":"s7"},{"id":"fc-234-fede35","poly":"cardio","fiche":"234","front":"Asthme et BPCO vs OAP : arguments ?","back":"Antécédents ; **sibilants**, dyspnée expiratoire (asthme) ; ronchi, expectoration (BPCO).","prio":"P3","sec":"s7"},{"id":"fc-234-bbbbf9","poly":"cardio","fiche":"234","front":"OAP cardiogénique vs lésionnel : nature du liquide ?","back":"Cardiogénique = **transsudat** ; lésionnel = **exsudat**.","prio":"P1","sec":"s7"},{"id":"fc-234-f6fb5a","poly":"cardio","fiche":"234","front":"OAP au domicile : traitement par le médecin ?","back":"**Asseoir** ; **furosémide IV 1 mg/kg** (à refaire) ; **nitrés sublinguaux si PAS > 100 mmHg** ; Samu, hospitalisation.","prio":"P1","sec":"s8"},{"id":"fc-234-d4ec45","poly":"cardio","fiche":"234","front":"OAP : dose de furosémide ?","back":"**1 mg/kg IV**, puis adaptée à la diurèse.","prio":"P1","sec":"s8"},{"id":"fc-234-c03737","poly":"cardio","fiche":"234","front":"OAP à l'hôpital : trinitrine, dose et condition ?","back":"**1 mg/h IV**, adaptée à la PA, si **PAS ≥ 110 mmHg**.","prio":"P1","sec":"s8"},{"id":"fc-234-235b65","poly":"cardio","fiche":"234","front":"OAP : oxygénothérapie ?","back":"Si **SaO₂ < 90 %**, objectif **> 90 %** ; prudence si risque d'hypercapnie.","prio":"P1","sec":"s8"},{"id":"fc-234-d7738e","poly":"cardio","fiche":"234","front":"OAP : morphine ?","back":"**Pas systématique** : anxiété importante non contrôlée ou douleur thoracique.","prio":"P1","sec":"s8"},{"id":"fc-234-c489e3","poly":"cardio","fiche":"234","front":"OAP : traitement anticoagulant ?","back":"**HBPM préventive**, **systématique**.","prio":"P1","sec":"s8"},{"id":"fc-234-62a5a9","poly":"cardio","fiche":"234","front":"OAP ne répondant pas au traitement : conduite ?","back":"**CPAP** (FR > 25/min, SaO₂ < 90 %) ; si échec ou épuisement → **intubation**.","prio":"P1","sec":"s8"},{"id":"fc-234-c0b2bc","poly":"cardio","fiche":"234","front":"OAP à l'hôpital : voie veineuse et monitorage ?","back":"Voie veineuse avec **G5 %** ; monitorage FC, PA, oxymétrie, scope.","prio":"P2","sec":"s8"},{"id":"fc-234-0631f7","poly":"cardio","fiche":"234","front":"OAP : quelle cause rechercher systématiquement ?","back":"Une cause spécifique (**CHAMPIT**) et le **facteur déclenchant**.","prio":"P2","sec":"s8"},{"id":"fc-234-94038f","poly":"cardio","fiche":"234","front":"OAP sur FA rapide : traitement ajouté ?","back":"**Digoxine IV** (si kaliémie normale) + **anticoagulation efficace**.","prio":"P2","sec":"s8"},{"id":"fc-234-af0bb2","poly":"cardio","fiche":"234","front":"OAP hypertensif : traitements proposés ?","back":"**Trinitrine IV** ; l'item 234 cite aussi la **nicardipine IV 1 à 5 mg/h**.","prio":"P2","sec":"s8"},{"id":"fc-234-1dc173","poly":"cardio","fiche":"234","front":"Nicardipine dans l'OAP : quelle contradiction du Collège ?","back":"Proposée par l'item 234, mais dite **contre-indiquée dans l'IC** par l'item 224, qui préfère les **nitrés IV**.","prio":"P2","sec":"s8"},{"id":"fc-234-f4f0e9","poly":"cardio","fiche":"234","front":"OAP : introduction d'un bêtabloquant ?","back":"**Non** : l'introduire pendant la poussée est une **faute**.","prio":"P1","sec":"s8"},{"id":"fc-234-3ef061","poly":"cardio","fiche":"234","front":"OAP chez un patient déjà sous bêtabloquant ?","back":"Généralement **arrêté ou diminué**.","prio":"P2","sec":"s8"},{"id":"fc-234-d00233","poly":"cardio","fiche":"234","front":"OAP : quand instaurer IEC, ARA2 ou sacubitril/valsartan ?","back":"**Après** la poussée.","prio":"P2","sec":"s8"},{"id":"fc-234-992281","poly":"cardio","fiche":"234","front":"Après un OAP : étapes ?","back":"Bêtabloquant une fois **stabilisé** (avant la sortie possible) ; **ETT** ; recherche d'**ischémie** si FEVG basse ; éducation.","prio":"P2","sec":"s8"},{"id":"fc-234-ff66d6","poly":"cardio","fiche":"234","front":"Choc cardiogénique : inotrope de référence ?","back":"**Dobutamine** IV.","prio":"P2","sec":"s9"},{"id":"fc-234-a0af73","poly":"cardio","fiche":"234","front":"Choc cardiogénique sous bêtabloquant : quel inotrope ?","back":"**Inhibiteur des phosphodiestérases** : **milrinone** ou **énoximone**.","prio":"P2","sec":"s9"},{"id":"fc-234-fcc23e","poly":"cardio","fiche":"234","front":"Choc cardiogénique : surveillance invasive ?","back":"**Sonde urinaire** systématique ; **PA invasive** (cathéter radial).","prio":"P3","sec":"s9"},{"id":"fc-234-3b261b","poly":"cardio","fiche":"234","front":"Lévosimendan : mécanisme et indication ?","back":"**Sensibilisateur calcique** (inotrope + vasodilatateur) ; si **sevrage des inotropes impossible**.","prio":"P3","sec":"s9"},{"id":"fc-234-1ec872","poly":"cardio","fiche":"234","front":"Choc cardiogénique réfractaire : options ?","back":"**Assistance circulatoire** (ECMO, uni- ou biventriculaire), cœur artificiel, **greffe en urgence**.","prio":"P2","sec":"s9"},{"id":"fc-234-5c83cb","poly":"cardio","fiche":"234","front":"CHAMPIT : signification ?","back":"**C**oronarien (SCA), **H**ypertension, **A**rythmie, **M**écanique (rupture, CIV, IM aiguë), **P**ulmonaire (EP), **I**nfection, **T**amponnade.","prio":"P1","sec":"s9"},{"id":"fc-234-984516","poly":"cardio","fiche":"234","front":"Poussée d'IC sans OAP : hospitalisation systématique ?","back":"**Non** : parfois augmenter le diurétique oral suffit ; sinon **cure de diurétiques IV**.","prio":"P2","sec":"s9"},{"id":"fc-234-01503b","poly":"cardio","fiche":"234","front":"Poussée d'IC sans OAP : étapes ?","back":"Diurétique (oral ou IV), **rééquilibrer** le traitement oral, **chercher la cause**, puis éducation.","prio":"P2","sec":"s9"},{"id":"fc-234-fe7362","poly":"cardio","fiche":"234","front":"Décompensation chez un patient sous bêtabloquant (règle générale) ?","back":"**Ne pas arrêter** le bêtabloquant, sauf mauvaise réponse ou **choc cardiogénique**.","prio":"P1","sec":"s9"},{"id":"fc-234-2cdc25","poly":"cardio","fiche":"234","front":"Bêtabloquant après stabilisation : modalités ?","back":"Réintroduit puis augmenté par **paliers hebdomadaires** ; surveiller FC et PA.","prio":"P3","sec":"s9"},{"id":"fc-234-9346bc","poly":"cardio","fiche":"234","front":"Prévention de l'IC : principe ?","back":"Traiter **chaque cause** (HTA, valvulopathie, infarctus, FDR, toxiques, rythme) avant que le myocarde ne s'abîme.","prio":"P2","sec":"s10"},{"id":"fc-234-74974b","poly":"cardio","fiche":"234","front":"Infarctus : mesure préventive de l'IC ?","back":"**Reperfusion précoce** pour limiter la nécrose.","prio":"P2","sec":"s10"},{"id":"fc-234-527695","poly":"cardio","fiche":"234","front":"Diabétique à haut risque CV : antidiabétique à privilégier pour prévenir l'IC ?","back":"Une **gliflozine**.","prio":"P2","sec":"s10"},{"id":"fc-234-d24989","poly":"cardio","fiche":"234","front":"Chimiothérapies cardiotoxiques : mesure préventive ?","back":"**Surveiller la fonction cardiaque**.","prio":"P3","sec":"s10"},{"id":"fc-234-e25da1","poly":"cardio","fiche":"234","front":"IC : apport sodé maximal ?","back":"**5 à 6 g de sel/j**.","prio":"P1","sec":"s10"},{"id":"fc-234-4cd805","poly":"cardio","fiche":"234","front":"IC : conduite après un écart de régime salé ?","back":"**Augmenter le diurétique** le jour même, voire le lendemain.","prio":"P2","sec":"s10"},{"id":"fc-234-fb75ca","poly":"cardio","fiche":"234","front":"IC : prise de poids devant faire consulter ?","back":"**2 à 3 kg**, a fortiori brutale **en 2 à 3 jours**.","prio":"P1","sec":"s10"},{"id":"fc-234-576868","poly":"cardio","fiche":"234","front":"IC : signification d'un amaigrissement progressif sans œdème ?","back":"**Dénutrition** : signe de gravité, mauvais pronostic.","prio":"P2","sec":"s10"},{"id":"fc-234-8be15b","poly":"cardio","fiche":"234","front":"CMD avec consommation d'alcool excessive : conduite ?","back":"**Arrêt total** (régression partielle voire totale possible).","prio":"P2","sec":"s10"},{"id":"fc-234-d29d6f","poly":"cardio","fiche":"234","front":"IC : activité physique ?","back":"**Encouragée** hors décompensation ; **pas de repos strict** (le déconditionnement aggrave).","prio":"P2","sec":"s10"},{"id":"fc-234-b26db0","poly":"cardio","fiche":"234","front":"IC : restrictions professionnelles ?","back":"Proscrire efforts importants, emplois à risque (poids lourds, transports), horaires décalés.","prio":"P3","sec":"s10"},{"id":"fc-234-ca5ed5","poly":"cardio","fiche":"234","front":"IC : vaccinations recommandées ?","back":"**Antigrippale**, **anti-Covid-19**, **antipneumococcique**.","prio":"P2","sec":"s10"},{"id":"fc-234-ab4cac","poly":"cardio","fiche":"234","front":"IC : contraception ?","back":"Œstrogènes **minidosés** ou **DIU** (grossesse à risque).","prio":"P2","sec":"s10"},{"id":"fc-234-e54009","poly":"cardio","fiche":"234","front":"IC : réadaptation cardiaque ?","back":"**Recommandée** si possible : reprise de l'effort + éducation thérapeutique.","prio":"P2","sec":"s10"},{"id":"fc-234-3321c8","poly":"cardio","fiche":"234","front":"IC : notion inacceptable sur le régime ?","back":"**Oublier les conseils de régime pauvre en sel**.","prio":"P1","sec":"s10"},{"id":"fc-234-3221f0","poly":"cardio","fiche":"234","front":"IC : pourquoi prendre en charge les comorbidités ?","back":"Elles réduisent la tolérance des cardioprotecteurs et augmentent erreurs de prise et effets indésirables.","prio":"P2","sec":"s10"},{"id":"fc-234-74b677","poly":"cardio","fiche":"234","front":"IC à FE diminuée : 4 classes réduisant la mortalité ?","back":"**IEC** (ou sacubitril/valsartan, ARA2 si intolérance), **bêtabloquant**, **antialdostérone**, **gliflozine**.","prio":"P1","sec":"s11"},{"id":"fc-234-31bbde","poly":"cardio","fiche":"234","front":"IC à FE diminuée : classe ajoutée pour les signes congestifs ?","back":"**Diurétique de l'anse** (5e classe).","prio":"P1","sec":"s11"},{"id":"fc-234-591752","poly":"cardio","fiche":"234","front":"IC à FE diminuée : première étape avant les médicaments ?","back":"**Corriger une cause curable** (revascularisation, valve) ; éliminer une origine ischémique.","prio":"P2","sec":"s11"},{"id":"fc-234-719aae","poly":"cardio","fiche":"234","front":"IEC dans l'IC à FE diminuée : chez qui ?","back":"**Tous** les patients, **quelle que soit la classe NYHA** ; débuter faible, monter vers les doses des essais.","prio":"P1","sec":"s11"},{"id":"fc-234-1695a3","poly":"cardio","fiche":"234","front":"IEC dans l'IC : doses cibles des essais ?","back":"**Énalapril 20 mg**, **captopril 150 mg**, **ramipril 10 mg**.","prio":"P2","sec":"s11"},{"id":"fc-234-e89aec","poly":"cardio","fiche":"234","front":"IEC : contre-indications ?","back":"**Sténose bilatérale des artères rénales**, ATCD d'**angio-œdème**, **grossesse**, **hyperkaliémie**.","prio":"P2","sec":"s11"},{"id":"fc-234-e5b551","poly":"cardio","fiche":"234","front":"IEC : effets indésirables principaux dans l'IC ?","back":"**Hypotension**, **insuffisance rénale**.","prio":"P2","sec":"s11"},{"id":"fc-234-90b61d","poly":"cardio","fiche":"234","front":"ARA2 dans l'IC : place ?","back":"**Si intolérance aux IEC** ; mieux tolérés (moins de toux), efficacité proche.","prio":"P2","sec":"s11"},{"id":"fc-234-aef60d","poly":"cardio","fiche":"234","front":"Sacubitril/valsartan : mécanisme ?","back":"Bloque le récepteur **AT1** + inhibe la **néprilysine** (dégradation des peptides natriurétiques).","prio":"P2","sec":"s11"},{"id":"fc-234-8e0c89","poly":"cardio","fiche":"234","front":"Sacubitril/valsartan : place ?","back":"En 1re intention possible, ou **en remplacement de l'IEC** si symptômes persistants ; plus efficace que l'énalapril.","prio":"P2","sec":"s11"},{"id":"fc-234-1b4546","poly":"cardio","fiche":"234","front":"Bêtabloquant dans l'IC : conditions d'introduction ?","back":"Patient **stabilisé**, sans décompensation ; départ à **1/8e** de la dose max, paliers **hebdomadaires**.","prio":"P1","sec":"s11"},{"id":"fc-234-b27170","poly":"cardio","fiche":"234","front":"Bêtabloquants de l'IC : molécules ?","back":"**Carvédilol**, **bisoprolol**, métoprolol, nébivolol.","prio":"P2","sec":"s11"},{"id":"fc-234-aaec9a","poly":"cardio","fiche":"234","front":"Bisoprolol dans l'IC : dose initiale et cible ?","back":"**1,25 mg/j** → **10 mg/j** selon tolérance.","prio":"P3","sec":"s11"},{"id":"fc-234-39063a","poly":"cardio","fiche":"234","front":"Carvédilol dans l'IC : dose initiale et cible ?","back":"**3,125 mg × 2/j** → **25 mg × 2/j** selon tolérance.","prio":"P3","sec":"s11"},{"id":"fc-234-a40207","poly":"cardio","fiche":"234","front":"Bêtabloquant : contre-indications ?","back":"**Asthme** ou BPCO sévère, bradycardie ou hypotension symptomatique, **BAV 2 ou 3**.","prio":"P2","sec":"s11"},{"id":"fc-234-5ae699","poly":"cardio","fiche":"234","front":"Bêtabloquants dans l'IC : bénéfices ?","back":"Moins de symptômes, de décès, d'hospitalisations et de **morts subites**.","prio":"P2","sec":"s11"},{"id":"fc-234-559dc0","poly":"cardio","fiche":"234","front":"Antialdostérone dans l'IC à FE basse : indication ?","back":"Tous les patients en **NYHA II à IV**.","prio":"P1","sec":"s11"},{"id":"fc-234-c06bfc","poly":"cardio","fiche":"234","front":"Antialdostérones : molécules et contre-indications ?","back":"**Spironolactone**, **éplérénone** ; CI : **hyperkaliémie**, **insuffisance rénale**.","prio":"P2","sec":"s11"},{"id":"fc-234-b16e5f","poly":"cardio","fiche":"234","front":"Spironolactone : effets indésirables spécifiques ?","back":"**Gynécomastie**, **impuissance**.","prio":"P3","sec":"s11"},{"id":"fc-234-c44cbc","poly":"cardio","fiche":"234","front":"Gliflozine dans l'IC à FE diminuée : chez qui ?","back":"Patient **diabétique ou non**.","prio":"P1","sec":"s11"},{"id":"fc-234-e32203","poly":"cardio","fiche":"234","front":"Gliflozines : molécules et effets indésirables ?","back":"**Dapagliflozine**, **empagliflozine** ; infections génitales, **acidocétose** (surtout diabétique).","prio":"P2","sec":"s11"},{"id":"fc-234-199ad3","poly":"cardio","fiche":"234","front":"Diurétique de l'anse au long cours : dose ?","back":"**Dose minimale** contrôlant les œdèmes : de **20 mg/j** à 500 mg/j, voire 1 g/j de furosémide.","prio":"P2","sec":"s11"},{"id":"fc-234-980289","poly":"cardio","fiche":"234","front":"Diurétique thiazidique dans l'IC : place ?","back":"**En association** au furosémide en cas de **résistance** (formes graves).","prio":"P2","sec":"s11"},{"id":"fc-234-48ba91","poly":"cardio","fiche":"234","front":"IEC/ARA2 : surveillance biologique ?","back":"PA, **créatinine**, **kaliémie** **1 semaine** après l'introduction et chaque hausse de dose.","prio":"P2","sec":"s11"},{"id":"fc-234-411c2b","poly":"cardio","fiche":"234","front":"IEC/ARA2 : quand réduire ou arrêter ?","back":"Hypotension symptomatique ou créatinine augmentée de **> 20-30 %**.","prio":"P3","sec":"s11"},{"id":"fc-234-6515c0","poly":"cardio","fiche":"234","front":"Antialdostérone : surveillance ?","back":"**Kaliémie** et **fonction rénale**, surtout avec un IEC.","prio":"P2","sec":"s11"},{"id":"fc-234-b9423d","poly":"cardio","fiche":"234","front":"Gliflozine : effet sur la fonction rénale ?","back":"Légère baisse initiale, puis effet plutôt **néphroprotecteur**.","prio":"P3","sec":"s11"},{"id":"fc-234-570b18","poly":"cardio","fiche":"234","front":"IC à FE altérée : médicaments contre-indiqués ?","back":"**Diltiazem**, **vérapamil**, **antiarythmiques de classe I** (flécaïnide).","prio":"P1","sec":"s11"},{"id":"fc-234-2455df","poly":"cardio","fiche":"234","front":"IC : AINS ?","back":"**À éviter** (rétention hydrosodée) ; à proscrire avec un IEC.","prio":"P1","sec":"s11"},{"id":"fc-234-4ad145","poly":"cardio","fiche":"234","front":"IC à FE altérée : dihydropyridines (amlodipine) ?","back":"Effet **neutre** sur la mortalité : possibles si angor ou HTA.","prio":"P3","sec":"s11"},{"id":"fc-234-c70fa3","poly":"cardio","fiche":"234","front":"IEC et antialdostérone : peut-on les débuter en même temps ?","back":"**Non** (hyperkaliémie, insuffisance rénale).","prio":"P1","sec":"s11"},{"id":"fc-234-e068d9","poly":"cardio","fiche":"234","front":"IC à FE diminuée + cardiopathie ischémique stable : antiagrégant ?","back":"**Aspirine 75 à 100 mg/j**.","prio":"P3","sec":"s11"},{"id":"fc-234-ed25e5","poly":"cardio","fiche":"234","front":"Ivabradine : mécanisme et indication ?","back":"Bloque le canal **If** (ralentit la FC) ; NYHA II-IV, **rythme sinusal**, FC **> 70-75/min** malgré bêtabloquant (ou CI).","prio":"P2","sec":"s12"},{"id":"fc-234-af3041","poly":"cardio","fiche":"234","front":"Digoxine dans l'IC : effet sur la survie ?","back":"**Neutre** ; améliore les symptômes ; réservée aux IC graves résistantes.","prio":"P2","sec":"s12"},{"id":"fc-234-fddd1d","poly":"cardio","fiche":"234","front":"Dérivés nitrés au long cours dans l'IC ?","back":"En **appoint** si pressions de remplissage élevées.","prio":"P3","sec":"s12"},{"id":"fc-234-9aa85b","poly":"cardio","fiche":"234","front":"IC + FA : anticoagulant préféré ?","back":"**AOD** (rivaroxaban, apixaban, dabigatran) **préférés aux AVK** ; scores **CHA₂DS₂-VA** et **HAS-BLED**.","prio":"P1","sec":"s12"},{"id":"fc-234-f9f773","poly":"cardio","fiche":"234","front":"IC : autres indications d'anticoagulation que la FA ?","back":"**Thrombus intracavitaire**, **AVC embolique**.","prio":"P2","sec":"s12"},{"id":"fc-234-164e21","poly":"cardio","fiche":"234","front":"IC + FA : comment ralentir ?","back":"**Bêtabloquants** et/ou **digitaliques** (vérapamil, diltiazem interdits) ; FC < 110 bpm à la marche.","prio":"P2","sec":"s12"},{"id":"fc-234-1fc0ea","poly":"cardio","fiche":"234","front":"IC à FE diminuée + FA : seul antiarythmique utilisable ?","back":"**Amiodarone** (associable au bêtabloquant).","prio":"P1","sec":"s12"},{"id":"fc-234-257e1e","poly":"cardio","fiche":"234","front":"Amiodarone dans l'IC : risque spécifique ?","back":"**Dysthyroïdie**, pouvant décompenser l'IC.","prio":"P2","sec":"s12"},{"id":"fc-234-f8bd81","poly":"cardio","fiche":"234","front":"AVK chez l'insuffisant cardiaque en FA : INR cible ?","back":"**2,5 (2 à 3)**, sauf valve mécanique mitrale.","prio":"P3","sec":"s12"},{"id":"fc-234-9a922c","poly":"cardio","fiche":"234","front":"Après infarctus avec FE basse : bêtabloquant sans symptôme d'IC ?","back":"**Oui**, même sans symptôme d'IC si la FE est basse.","prio":"P2","sec":"s12"},{"id":"fc-234-e553f4","poly":"cardio","fiche":"234","front":"Après infarctus étendu avec FE < 40 % : antialdostérone de référence ?","back":"**Éplérénone** (moins de décès, de morts subites, de récidives d'IC).","prio":"P2","sec":"s12"},{"id":"fc-234-e9a5d8","poly":"cardio","fiche":"234","front":"Après IDM : contre-indications de l'antialdostérone ?","back":"Insuffisance rénale (créatinine **> 221 µmol/L**), **hyperkaliémie**.","prio":"P3","sec":"s12"},{"id":"fc-234-1e3661","poly":"cardio","fiche":"234","front":"Après IDM : objectif lipidique ?","back":"LDL-C baissé d'au moins **50 %** et **< 0,55 g/L** (statine forte dose).","prio":"P2","sec":"s12"},{"id":"fc-234-7256ad","poly":"cardio","fiche":"234","front":"Après IDM : ajout si LDL non atteint sous statine ?","back":"**Ézétimibe 10 mg** après 4 semaines ; puis **anti-PCSK9** si LDL > 0,7 g/L.","prio":"P3","sec":"s12"},{"id":"fc-234-1e3ea0","poly":"cardio","fiche":"234","front":"Statines forte dose après IDM : doses ?","back":"**Atorvastatine 80 mg** ou **rosuvastatine 20 mg**.","prio":"P3","sec":"s12"},{"id":"fc-234-641ea7","poly":"cardio","fiche":"234","front":"Inhibiteurs P2Y12 d'entretien : doses ?","back":"Clopidogrel **75 mg/j** ; prasugrel **10 mg/j** ; ticagrélor **90 mg × 2/j**.","prio":"P3","sec":"s12"},{"id":"fc-234-2f4c3c","poly":"cardio","fiche":"234","front":"Prasugrel : contre-indication et restrictions ?","back":"CI si **ATCD d'AVC** ; non recommandé **> 75 ans** ou **< 60 kg**.","prio":"P3","sec":"s12"},{"id":"fc-234-eb602f","poly":"cardio","fiche":"234","front":"Après IDM + anticoagulant nécessaire : association par défaut ?","back":"**Clopidogrel + anticoagulant 12 mois**, puis anticoagulant seul.","prio":"P2","sec":"s12"},{"id":"fc-234-efe394","poly":"cardio","fiche":"234","front":"Après IDM avec FEVG < 35 % précoce : conduite rythmique ?","back":"**Gilet défibrillateur**, réévaluation ; **DAI** si FEVG < 35 % **≥ 6 semaines** après, traitement optimisé.","prio":"P2","sec":"s12"},{"id":"fc-234-ea39ae","poly":"cardio","fiche":"234","front":"Après SCA : réadaptation cardiovasculaire ?","back":"Proposée **à tous**.","prio":"P3","sec":"s12"},{"id":"fc-234-e8aadd","poly":"cardio","fiche":"234","front":"Resynchronisation cardiaque : indication ?","back":"IC **NYHA II à IV** + **FEVG ≤ 35 %** + **QRS ≥ 130 ms**.","prio":"P1","sec":"s13"},{"id":"fc-234-1da2be","poly":"cardio","fiche":"234","front":"Resynchronisation : facteurs d'efficacité ?","back":"**BBG**, **QRS ≥ 150 ms**, cardiopathie **non ischémique**.","prio":"P2","sec":"s13"},{"id":"fc-234-7d428d","poly":"cardio","fiche":"234","front":"Resynchronisation : technique ?","back":"Sondes **OD**, **VD** et paroi latérale du VG via le **sinus coronaire** ; stimulation simultanée.","prio":"P3","sec":"s13"},{"id":"fc-234-6fc071","poly":"cardio","fiche":"234","front":"DAI en prévention secondaire : indication ?","back":"Arrêt cardiaque par **FV récupéré** ou **TV symptomatique**.","prio":"P1","sec":"s13"},{"id":"fc-234-83b991","poly":"cardio","fiche":"234","front":"DAI en prévention primaire : indication ?","back":"**NYHA II-III**, **FEVG ≤ 35 %** ; ischémique ≥ **6 semaines** post-IDM ; non ischémique après ≥ **3 mois** de traitement.","prio":"P1","sec":"s13"},{"id":"fc-234-5e2628","poly":"cardio","fiche":"234","front":"DAI : principales complications ?","back":"**Infections de sonde**, **chocs inappropriés**.","prio":"P2","sec":"s13"},{"id":"fc-234-48ca13","poly":"cardio","fiche":"234","front":"DAI en NYHA IV : indiqué ?","back":"**Non**, sauf projet de greffe ou d'assistance (survie probable > 1 an requise).","prio":"P2","sec":"s13"},{"id":"fc-234-2c3d1e","poly":"cardio","fiche":"234","front":"Amiodarone dans l'IC : réduit-elle la mortalité ou la mort subite ?","back":"**Non**, ni l'une ni l'autre.","prio":"P2","sec":"s13"},{"id":"fc-234-de34e0","poly":"cardio","fiche":"234","front":"IC résistante au traitement médical : options ?","back":"**Greffe cardiaque**, ou parfois **assistance ventriculaire** (en attente de greffe ou définitive).","prio":"P1","sec":"s13"},{"id":"fc-234-3292a0","poly":"cardio","fiche":"234","front":"IC avancée sans greffe ni assistance possible : prise en charge ?","back":"**Soins de support** ou **soins palliatifs**.","prio":"P2","sec":"s13"},{"id":"fc-234-2cedb6","poly":"cardio","fiche":"234","front":"IC à FE préservée : critères diagnostiques ?","back":"Symptômes/signes d'IC + **FEVG ≥ 50 %** + **BNP/NT-proBNP augmenté** + arguments ETT (pressions élevées, **HVG** ou **OG dilatée**).","prio":"P1","sec":"s14"},{"id":"fc-234-330f04","poly":"cardio","fiche":"234","front":"IC à FE préservée : seuils échographiques d'HVG et d'OG ?","back":"Masse VG **≥ 115 g/m²** (homme), **≥ 95 g/m²** (femme) ; OG **> 34 mL/m²**.","prio":"P3","sec":"s14"},{"id":"fc-234-447e1c","poly":"cardio","fiche":"234","front":"IC à FE préservée : classe médicamenteuse hautement recommandée ?","back":"**Gliflozines** (dapagliflozine, empagliflozine).","prio":"P1","sec":"s14"},{"id":"fc-234-e71c3f","poly":"cardio","fiche":"234","front":"IC à FE préservée : mesures associées ?","back":"Prévenir la **FA**, les **poussées hypertensives**, la **surcharge volumique** ; traiter l'**ischémie**.","prio":"P1","sec":"s14"},{"id":"fc-234-59f6bb","poly":"cardio","fiche":"234","front":"IC à FE préservée : axes A à G ?","back":"**A**rythmies, **B**lood pressure, **C**omorbidités, **D**iurétique, **E**xercice, **F**ollow-up, **G**liflozines.","prio":"P3","sec":"s14"},{"id":"fc-234-d24550","poly":"cardio","fiche":"234","front":"IC à FE préservée : inhibiteur calcique ralentisseur ?","back":"**Possible** (allonge la diastole), contrairement à l'IC à FE altérée.","prio":"P2","sec":"s14"},{"id":"fc-234-6b7b93","poly":"cardio","fiche":"234","front":"IC à FE préservée : diurétiques ?","back":"Thiazidique ou de l'anse si **congestion**, en surveillant la fonction rénale.","prio":"P3","sec":"s14"},{"id":"fc-234-cce07c","poly":"cardio","fiche":"234","front":"Remodelage inverse : définition ?","back":"Amélioration voire **normalisation** de la fonction après traitement de l'IC ou de sa cause.","prio":"P2","sec":"s15"},{"id":"fc-234-7a97d0","poly":"cardio","fiche":"234","front":"IC en NYHA IV : mortalité ?","back":"Jusqu'à **40 à 50 % par an**.","prio":"P2","sec":"s15"},{"id":"fc-234-0c2ea3","poly":"cardio","fiche":"234","front":"IC : 2 grands modes de décès ?","back":"**Mort subite** (TV/FV) et **IC réfractaire**.","prio":"P2","sec":"s15"},{"id":"fc-234-921d89","poly":"cardio","fiche":"234","front":"Hospitalisation pour décompensation : signification pronostique ?","back":"**Facteur de gravité**.","prio":"P2","sec":"s15"},{"id":"fc-234-f95c5a","poly":"cardio","fiche":"234","front":"IC : complications thromboemboliques ?","back":"Embolies systémiques (thrombus des cavités gauches dilatées, FA) ; **embolie pulmonaire** (alitement).","prio":"P3","sec":"s15"},{"id":"fc-234-0fcbcc","poly":"cardio","fiche":"234","front":"IC : complications rénales et électrolytiques ?","back":"Hypo- ou hyperkaliémie, **hyponatrémie**, **insuffisance rénale**.","prio":"P3","sec":"s15"},{"id":"fc-234-32fb95","poly":"cardio","fiche":"234","front":"Complications de l'IC : moyen mnémotechnique ?","back":"**DÉTHER** : Décès, Épisodes de décompensation, Troubles du rythme, Hypotension, Emboliques, Rein et électrolytes.","prio":"P3","sec":"s15"},{"id":"fc-234-e21381","poly":"cardio","fiche":"234","front":"IC : facteurs pronostiques péjoratifs ?","back":"**NYHA III-IV**, hospitalisations répétées, cause ischémique, **FE basse**, QRS > 120 ms, **hyponatrémie**, BNP élevé, pic de **VO₂** bas.","prio":"P2","sec":"s15"},{"id":"fc-234-21a707","poly":"cardio","fiche":"234","front":"Après hospitalisation pour IC : principal risque ?","back":"**Réhospitalisation** : contrôler la congestion et optimiser le traitement en ambulatoire.","prio":"P2","sec":"s16"},{"id":"fc-234-c49af3","poly":"cardio","fiche":"234","front":"Après hospitalisation pour IC : éducation thérapeutique ?","back":"Patient + entourage : **signes d'alerte**, **régime pauvre en sel**, **observance**, autoprise en charge.","prio":"P1","sec":"s16"},{"id":"fc-234-6b7fe3","poly":"cardio","fiche":"234","front":"IC : télésurveillance, principe ?","back":"Symptômes, PA, FC, **poids** transmis presque chaque jour ; alertes → dépister tôt une décompensation.","prio":"P2","sec":"s16"},{"id":"fc-234-d82952","poly":"cardio","fiche":"234","front":"IC stabilisée : rôle des infirmiers en pratique avancée ?","back":"Suivi et prescription sous **responsabilité médicale**.","prio":"P3","sec":"s16"},{"id":"fc-234-71e423","poly":"cardio","fiche":"234","front":"IC : 4 signes d'alerte à apprendre au patient ?","back":"**Poids** qui monte, **souffle** qui s'aggrave, **dormir assis**, **jambes ou ventre** qui gonflent.","prio":"P2","sec":"s16"},{"id":"fc-234-1300bc","poly":"cardio","fiche":"234","front":"IC : place de l'arrêt du tabac ?","back":"**Impératif chez tous**, a fortiori en cas de **cardiopathie ischémique**.","prio":"P2","sec":"s10"},{"id":"fc-234-64873b","poly":"cardio","fiche":"234","front":"Cardiomyopathie : pourquoi parle-t-on de diagnostic d'élimination ?","back":"Il faut d'abord écarter une cause **ischémique**, **valvulaire**, **congénitale** ou **hypertensive**.","prio":"P3","sec":"s5"},{"id":"fc-234-b3e0bf","poly":"cardio","fiche":"234","front":"Coronarographie dans l'IC : indications ?","back":"Angor, probabilité coronaire **intermédiaire à haute** ou ischémie prouvée, chez un patient **revascularisable**.","prio":"P3","sec":"s4"},{"id":"fc-234-162ae3","poly":"cardio","fiche":"234","front":"IC + FA persistante : anticoagulation autour d'une cardioversion ?","back":"**3 à 4 semaines** d'anticoagulation efficace avant (ou ETO sans thrombus), puis au moins **4 semaines** après.","prio":"P3","sec":"s12"},{"id":"fc-234-7d8eb9","poly":"cardio","fiche":"234","front":"Indication à la fois de resynchronisation et de DAI : quel dispositif ?","back":"**Dispositif combiné** (défibrillation + resynchronisation).","prio":"P3","sec":"s13"},{"id":"fc-234-bc2778","poly":"cardio","fiche":"234","front":"IC à FE préservée : traitement comparé à celui de l'IC à FE altérée ?","back":"Moins codifié (moins d'études) mais finalement **proche** ; mêmes mesures hygiénodiététiques, éducation et suivi.","prio":"P3","sec":"s14"},{"id":"fc-234-1a9a6f","poly":"cardio","fiche":"234","front":"IC avec faiblesse musculaire : que rechercher ?","back":"Une **myopathie associée**, surtout en cas de **CMD**.","prio":"P3","sec":"s3"},{"id":"fc-235-cfe8ad","poly":"cardio","fiche":"235","front":"Péricardite aiguë : définition ?","back":"**Inflammation aiguë des feuillets du péricarde**.","prio":"P1","sec":"s1"},{"id":"fc-235-d3bfae","poly":"cardio","fiche":"235","front":"Péricardite aiguë : 3 enjeux ?","back":"**Diagnostic différentiel** d'une douleur thoracique ; **tamponnade** ; **récidives** (20 à 30 %), ± constriction selon la cause.","prio":"P1","sec":"s1"},{"id":"fc-235-526da3","poly":"cardio","fiche":"235","front":"Douleur thoracique évoquant une péricardite : 3 diagnostics graves à toujours évoquer ?","back":"**SCA**, **embolie pulmonaire**, **dissection aortique**.","prio":"P1","sec":"s1"},{"id":"fc-235-04ae10","poly":"cardio","fiche":"235","front":"Péricardite aiguë : 4 critères diagnostiques ?","back":"**Précordialgie typique** ; **frottement péricardique** ; **ECG typique** ; **épanchement** à l'échocardiographie.","prio":"P1","sec":"s1"},{"id":"fc-235-f4a4e2","poly":"cardio","fiche":"235","front":"Péricardite aiguë : combien de critères faut-il ?","back":"**Au moins 2 sur 4**.","prio":"P1","sec":"s1"},{"id":"fc-235-1f49ff","poly":"cardio","fiche":"235","front":"Suspicion de péricardite : examens systématiques ?","back":"**ECG** et **échocardiographie**.","prio":"P1","sec":"s1"},{"id":"fc-235-8753d9","poly":"cardio","fiche":"235","front":"CRP élevée : fait-elle partie des critères de péricardite ?","back":"**Non**, le syndrome inflammatoire n'est pas un critère.","prio":"P1","sec":"s1"},{"id":"fc-235-d4f9e7","poly":"cardio","fiche":"235","front":"Péricardite aiguë : caractéristiques de la fièvre ?","back":"**Modérée**, présente **dès le début**, avec myalgies, asthénie, souvent après un **épisode grippal**.","prio":"P1","sec":"s2"},{"id":"fc-235-825488","poly":"cardio","fiche":"235","front":"Péricardite chez le sujet âgé : particularité de la fièvre ?","back":"Elle **manque plus souvent**.","prio":"P2","sec":"s2"},{"id":"fc-235-bac473","poly":"cardio","fiche":"235","front":"Douleur de péricardite : facteurs aggravants ?","back":"**Décubitus**, **inspiration profonde**, **toux**.","prio":"P1","sec":"s2"},{"id":"fc-235-4ca2e2","poly":"cardio","fiche":"235","front":"Douleur de péricardite : position antalgique ?","back":"**Antéflexion** (assis, penché en avant).","prio":"P1","sec":"s2"},{"id":"fc-235-3ac2d9","poly":"cardio","fiche":"235","front":"Douleur de péricardite : siège, durée et réponse à la trinitrine ?","back":"Rétrosternale ou précordiale gauche, **prolongée**, **résistante à la trinitrine**.","prio":"P1","sec":"s2"},{"id":"fc-235-f7fbe8","poly":"cardio","fiche":"235","front":"Péricardite : symptômes associés possibles en dehors de la douleur ?","back":"**Dyspnée** (soulagée par l'antéflexion), **toux sèche**, **dysphonie**, **hoquet**.","prio":"P2","sec":"s2"},{"id":"fc-235-a3d8c2","poly":"cardio","fiche":"235","front":"Frottement péricardique : caractéristiques ?","back":"Précoce, **systolodiastolique**, changeant avec le temps et la position ; **inconstant et fugace**.","prio":"P1","sec":"s2"},{"id":"fc-235-14928e","poly":"cardio","fiche":"235","front":"Frottement péricardique : valeur diagnostique ?","back":"Il **confirme** le diagnostic.","prio":"P2","sec":"s2"},{"id":"fc-235-a22c85","poly":"cardio","fiche":"235","front":"Absence de frottement péricardique : élimine-t-elle une péricardite ?","back":"**Non** (frottement inconstant et fugace).","prio":"P1","sec":"s2"},{"id":"fc-235-371e60","poly":"cardio","fiche":"235","front":"Douleur résistante à la trinitrine : élimine-t-elle un SCA ST+ ?","back":"**Non** : dans le SCA ST+, douleur et sus-décalage persistent aussi après trinitrine.","prio":"P2","sec":"s2"},{"id":"fc-235-7c834d","poly":"cardio","fiche":"235","front":"Péricardite virale typique : profil du patient et début ?","back":"Sujet **jeune**, plutôt **masculin**, syndrome grippal récent ; début **brutal et fébrile**.","prio":"P1","sec":"s2"},{"id":"fc-235-5f5ab6","poly":"cardio","fiche":"235","front":"Péricardite virale typique : résultat habituel de l'échocardiographie ?","back":"**Le plus souvent normale**.","prio":"P2","sec":"s2"},{"id":"fc-235-8a6b30","poly":"cardio","fiche":"235","front":"Péricardite : un premier ECG normal élimine-t-il le diagnostic ?","back":"**Non** : l'ECG est **à répéter**.","prio":"P1","sec":"s3"},{"id":"fc-235-9354e3","poly":"cardio","fiche":"235","front":"ECG de péricardite : caractéristiques des anomalies ?","back":"**Diffuses**, **sans territoire coronaire**, **sans image en miroir**.","prio":"P1","sec":"s3"},{"id":"fc-235-4a0b93","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade I : quand et aspect ?","back":"**1er jour** : sus-décalage de ST **concave vers le haut**, T **positives**.","prio":"P1","sec":"s3"},{"id":"fc-235-b5b668","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade II : quand et aspect ?","back":"Entre la **24e et la 48e heure** : ondes T **plates**.","prio":"P2","sec":"s3"},{"id":"fc-235-223432","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade III : quand et aspect ?","back":"**1re semaine** : ondes T **négatives**.","prio":"P2","sec":"s3"},{"id":"fc-235-9ba48d","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade IV : quand et aspect ?","back":"Au cours du **1er mois** : **normalisation**.","prio":"P2","sec":"s3"},{"id":"fc-235-3a71fb","poly":"cardio","fiche":"235","front":"ECG de péricardite : anomalie du segment PQ ?","back":"**Sous-décalage de PQ** à la phase initiale.","prio":"P1","sec":"s3"},{"id":"fc-235-f8dd58","poly":"cardio","fiche":"235","front":"Péricardite : troubles du rythme possibles ?","back":"**Tachycardie sinusale**, extrasystoles atriales, **FA**, **flutter atrial**.","prio":"P2","sec":"s3"},{"id":"fc-235-49c276","poly":"cardio","fiche":"235","front":"Épanchement péricardique abondant : signes ECG ?","back":"**Microvoltage** et parfois **alternance électrique** (mêmes signes que dans la tamponnade).","prio":"P1","sec":"s3"},{"id":"fc-235-813055","poly":"cardio","fiche":"235","front":"Microvoltage : définition ?","back":"QRS **< 5 mm** en dérivations périphériques et **< 10 mm** en précordiales.","prio":"P2","sec":"s3"},{"id":"fc-235-dd40e2","poly":"cardio","fiche":"235","front":"Péricardite : bilan biologique initial ?","back":"**NFS**, **CRP**, **troponine** (imposée), **ionogramme**, **urée**, **créatinine** ; hémocultures si fièvre ; IDR discutée.","prio":"P1","sec":"s3"},{"id":"fc-235-52fa30","poly":"cardio","fiche":"235","front":"Péricardite avec troponine nettement élevée : quoi évoquer ?","back":"Une **myocardite associée** (surtout avec trouble de cinétique du VG) ; ne pas conclure trop vite au **SCA**.","prio":"P1","sec":"s3"},{"id":"fc-235-eee44e","poly":"cardio","fiche":"235","front":"Péricardite typique sans gravité : sérologies virales ?","back":"**Inutiles**.","prio":"P2","sec":"s3"},{"id":"fc-235-8650e2","poly":"cardio","fiche":"235","front":"Péricardite : aspect habituel de la radiographie thoracique ?","back":"**Le plus souvent normale**.","prio":"P3","sec":"s3"},{"id":"fc-235-120e0a","poly":"cardio","fiche":"235","front":"Épanchement abondant : aspect radiologique ?","back":"Cardiomégalie avec cœur triangulaire **« en carafe »** ou rectitude du bord gauche.","prio":"P2","sec":"s3"},{"id":"fc-235-a15a1e","poly":"cardio","fiche":"235","front":"Radiographie de thorax dans la péricardite : intérêt ?","back":"Orientation **étiologique** (pathologie pulmonaire associée, épanchement pleural).","prio":"P3","sec":"s3"},{"id":"fc-235-4b8521","poly":"cardio","fiche":"235","front":"Péricardite « sèche » : définition ?","back":"Péricardite avec **échocardiographie normale** (sans épanchement).","prio":"P2","sec":"s4"},{"id":"fc-235-502b04","poly":"cardio","fiche":"235","front":"Échocardiographie dans la péricardite : apports ?","back":"**Abondance**, **topographie**, **tolérance** de l'épanchement ; confirme une **tamponnade** ; cherche une altération de la **FEVG**.","prio":"P2","sec":"s4"},{"id":"fc-235-af0f64","poly":"cardio","fiche":"235","front":"Masse péricardique à l'écho : signification habituelle ?","back":"Rare, habituellement **maligne**.","prio":"P3","sec":"s4"},{"id":"fc-235-d7bc06","poly":"cardio","fiche":"235","front":"Épanchement péricardique minime : épaisseur ?","back":"**< 10 mm**.","prio":"P2","sec":"s4"},{"id":"fc-235-d8133b","poly":"cardio","fiche":"235","front":"Épanchement péricardique modéré : épaisseur ?","back":"**10 à 20 mm**.","prio":"P2","sec":"s4"},{"id":"fc-235-61e265","poly":"cardio","fiche":"235","front":"Épanchement péricardique abondant : épaisseur ?","back":"**> 20 mm**.","prio":"P1","sec":"s4"},{"id":"fc-235-37ff2d","poly":"cardio","fiche":"235","front":"Péricardite : indications du scanner ou de l'IRM ?","back":"En **2e intention** : patient **non échogène**, **péricardite néoplasique**, **épanchement cloisonné**.","prio":"P2","sec":"s4"},{"id":"fc-235-a66cf4","poly":"cardio","fiche":"235","front":"IRM dans la péricardite : apports ?","back":"Inflammation du péricarde, **myocardite associée** (rehaussement tardif), sans irradiation.","prio":"P3","sec":"s4"},{"id":"fc-235-c412cd","poly":"cardio","fiche":"235","front":"Ponction péricardique : 3 indications ?","back":"**Tamponnade** ; forte suspicion **néoplasique** ; épanchement **abondant symptomatique** persistant après **1 semaine** de traitement.","prio":"P2","sec":"s4"},{"id":"fc-235-a1cda4","poly":"cardio","fiche":"235","front":"Liquide péricardique : analyses biochimiques ?","back":"**Glucose**, **protides**, **LDH**.","prio":"P3","sec":"s4"},{"id":"fc-235-478634","poly":"cardio","fiche":"235","front":"Liquide péricardique : analyses microbiologiques et moléculaires ?","back":"Cytologie, **Gram** et **Ziehl-Nielsen**, **culture**, **PCR** virale et tuberculeuse.","prio":"P3","sec":"s4"},{"id":"fc-235-de4716","poly":"cardio","fiche":"235","front":"Suspicion de péricardite purulente : geste privilégié ?","back":"**Drainage péricardique chirurgical**.","prio":"P2","sec":"s4"},{"id":"fc-235-aa40c2","poly":"cardio","fiche":"235","front":"Péricardite aiguë : hospitalisation systématique ?","back":"**Non**, inutile dans la majorité des cas.","prio":"P1","sec":"s5"},{"id":"fc-235-36e354","poly":"cardio","fiche":"235","front":"Péricardite : combien de facteurs majeurs suffisent à hospitaliser ?","back":"**Un seul**.","prio":"P1","sec":"s5"},{"id":"fc-235-e26c16","poly":"cardio","fiche":"235","front":"Péricardite : 4 facteurs prédictifs majeurs (ESC 2015) ?","back":"**Fièvre > 38 °C** ; **début subaigu** ; **épanchement > 20 mm** ou tamponnade ; **résistance** à l'aspirine/AINS après **7 jours**.","prio":"P1","sec":"s5"},{"id":"fc-235-736493","poly":"cardio","fiche":"235","front":"Péricardite : définition du début subaigu ?","back":"Symptômes présents depuis **plusieurs jours ou semaines**.","prio":"P2","sec":"s5"},{"id":"fc-235-21fecc","poly":"cardio","fiche":"235","front":"Péricardite : facteurs mineurs (hospitalisation discutée) ?","back":"**Immunodépression**, **anticoagulant**, **traumatisme thoracique**, **myocardite associée** (troponine élevée).","prio":"P1","sec":"s5"},{"id":"fc-235-9e5173","poly":"cardio","fiche":"235","front":"Péricardite : autres situations d'hospitalisation que les facteurs majeurs ?","back":"**Complication d'emblée** (tamponnade, récidive, constriction), **mauvaise tolérance**, **étiologie particulière** suspectée.","prio":"P2","sec":"s5"},{"id":"fc-235-51305a","poly":"cardio","fiche":"235","front":"Péricardite typique du jeune sans facteur ni complication : prise en charge ?","back":"**Ambulatoire**, réévaluation à **7 jours**.","prio":"P2","sec":"s5"},{"id":"fc-235-864544","poly":"cardio","fiche":"235","front":"Péricardite avec signes droits, hypotension et pouls paradoxal : conduite ?","back":"Suspecter une **tamponnade** : **USIC** et appel en urgence pour **drainage**.","prio":"P1","sec":"s5"},{"id":"fc-235-30156c","poly":"cardio","fiche":"235","front":"Sus-décalage de ST : péricardite ou SCA, arguments ECG ?","back":"Péricardite : **diffus**, **concave**, sans territoire ni miroir, sous-PQ ; SCA : territorial, **classiquement convexe**, **miroir** habituel, puis **onde Q**.","prio":"P1","sec":"s6"},{"id":"fc-235-8a8782","poly":"cardio","fiche":"235","front":"SCA ST+ : critère de topographie du sus-décalage ?","back":"**Au moins 2 dérivations contiguës**, dont la localisation désigne le territoire.","prio":"P2","sec":"s6"},{"id":"fc-235-1b2991","poly":"cardio","fiche":"235","front":"SCA ST+ : délai d'apparition classique de l'onde Q ?","back":"À partir de la **6e heure**.","prio":"P3","sec":"s6"},{"id":"fc-235-4606c9","poly":"cardio","fiche":"235","front":"Péricardite : y a-t-il des ondes Q ?","back":"**Non**.","prio":"P2","sec":"s6"},{"id":"fc-235-5514e6","poly":"cardio","fiche":"235","front":"Constriction péricardique : diagnostic différentiel principal ?","back":"La **cardiomyopathie restrictive**.","prio":"P2","sec":"s6"},{"id":"fc-235-ef62b3","poly":"cardio","fiche":"235","front":"Péricardite aiguë : cause la plus fréquente ?","back":"**Virale ou inconnue** (idiopathique) : **9 cas sur 10**.","prio":"P1","sec":"s7"},{"id":"fc-235-868cf6","poly":"cardio","fiche":"235","front":"Péricardite : 3 causes à rechercher car elles changent le traitement ?","back":"**Tuberculose**, **cancer**, **maladies auto-immunes**.","prio":"P2","sec":"s7"},{"id":"fc-235-17a5de","poly":"cardio","fiche":"235","front":"Péricardite : 2e cause après la forme virale, et évolution de la tuberculose ?","back":"Cause **néoplasique** en 2e position ; tuberculose **en régression**.","prio":"P3","sec":"s7"},{"id":"fc-235-93991a","poly":"cardio","fiche":"235","front":"Péricardite virale : virus en cause ?","back":"**Entérovirus** (coxsackie A et B), échovirus, adénovirus, CMV, parvovirus B19, EBV, herpès, VIH, VHC, grippe…","prio":"P2","sec":"s7"},{"id":"fc-235-707433","poly":"cardio","fiche":"235","front":"Péricardite virale : mécanisme ?","back":"Infection + **réaction immunitaire** associée ; rarement prouvée.","prio":"P2","sec":"s7"},{"id":"fc-235-2daed8","poly":"cardio","fiche":"235","front":"Péricardite virale : seul examen qui confirme le virus ?","back":"La **PCR** (liquide ou biopsie péricardique) ; deux sérologies à 15 jours ne font qu'**orienter**.","prio":"P2","sec":"s7"},{"id":"fc-235-966880","poly":"cardio","fiche":"235","front":"Péricardite virale : complication la plus fréquente ?","back":"La **récidive** (**20 à 30 %**) ; tamponnade et constriction **rares**.","prio":"P1","sec":"s7"},{"id":"fc-235-3820af","poly":"cardio","fiche":"235","front":"Péricardite chronique récidivante à virus prouvé : traitements discutés ?","back":"**Immunoglobulines**, **interféron α**.","prio":"P3","sec":"s7"},{"id":"fc-235-eeb007","poly":"cardio","fiche":"235","front":"Péricardite chez le patient VIH : mécanismes ?","back":"VIH ou autre virus ; **surinfection** bactérienne ou fongique ; **lymphome** ou **sarcome de Kaposi**.","prio":"P3","sec":"s7"},{"id":"fc-235-54a210","poly":"cardio","fiche":"235","front":"Péricardite du jeune sans complication : principal risque évolutif ?","back":"La **récidive** (la tamponnade est rare dans la forme virale).","prio":"P2","sec":"s7"},{"id":"fc-235-403748","poly":"cardio","fiche":"235","front":"Péricardite purulente : terrain ?","back":"**Immunodéprimé** ; infection sévère (septicémie, pleuropulmonaire, après chirurgie cardiaque ou thoracique).","prio":"P2","sec":"s8"},{"id":"fc-235-914a29","poly":"cardio","fiche":"235","front":"Péricardite purulente : germes cités ?","back":"**Staphylocoques**, **pneumocoques**, **streptocoques**, **bacilles à Gram négatif**…","prio":"P3","sec":"s8"},{"id":"fc-235-3ffb64","poly":"cardio","fiche":"235","front":"Péricardite purulente : traitement ?","back":"**Antibiothérapie adaptée au germe** + **drainage chirurgical** souvent nécessaire.","prio":"P2","sec":"s8"},{"id":"fc-235-0bdcf5","poly":"cardio","fiche":"235","front":"Péricardite purulente : pronostic ?","back":"**Sévère** : tamponnade fréquente, constriction.","prio":"P3","sec":"s8"},{"id":"fc-235-b50254","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : présentation ?","back":"Péricardite **subaiguë liquidienne**, altération de l'état général, fièvre modérée persistante.","prio":"P2","sec":"s8"},{"id":"fc-235-5d20be","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : terrains ?","back":"Sujet tuberculeux, âgé ou greffé, **VIH**, alcoolique ; contage ou virage récent de l'IDR.","prio":"P3","sec":"s8"},{"id":"fc-235-d41243","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : éléments diagnostiques ?","back":"**BK** (direct, culture, PCR) ; **adénosine-déaminase** élevée dans le liquide ; parfois **granulome**.","prio":"P3","sec":"s8"},{"id":"fc-235-c6a7fe","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : traitement ?","back":"**Antituberculeux** ; pour certains + **prednisone** pour limiter la constriction.","prio":"P2","sec":"s8"},{"id":"fc-235-516b30","poly":"cardio","fiche":"235","front":"IDR négative : élimine-t-elle une péricardite tuberculeuse ?","back":"**Non** : faussement négative dans **près d'un tiers** des cas.","prio":"P2","sec":"s8"},{"id":"fc-235-ccafe5","poly":"cardio","fiche":"235","front":"Péricardite néoplasique : cancers en cause ?","back":"Métastases : **cancer bronchique**, **sein**, mélanomes, leucémies, lymphomes, Kaposi.","prio":"P2","sec":"s8"},{"id":"fc-235-12d770","poly":"cardio","fiche":"235","front":"Mésothéliome péricardique primitif : fréquence relative ?","back":"**40 fois moins fréquent** que les métastases.","prio":"P3","sec":"s8"},{"id":"fc-235-a8da21","poly":"cardio","fiche":"235","front":"Péricardite néoplasique : caractéristiques de l'épanchement ?","back":"**Hémorragique**, **tamponnade** fréquente, **récidive** fréquente.","prio":"P2","sec":"s8"},{"id":"fc-235-43933d","poly":"cardio","fiche":"235","front":"Péricardite auto-immune : maladies en cause ?","back":"**Lupus**, **polyarthrite rhumatoïde**, sclérodermie, périartérite noueuse, dermatomyosite.","prio":"P3","sec":"s8"},{"id":"fc-235-f3d345","poly":"cardio","fiche":"235","front":"Péricardite auto-immune : quand la retenir ?","back":"**Diagnostic d'élimination** (liquide : lymphocytes augmentés, anticorps antisarcolemme ; myocardite associée).","prio":"P2","sec":"s8"},{"id":"fc-235-c6da87","poly":"cardio","fiche":"235","front":"Péricardite précoce de l'infarctus : délai et contexte ?","back":"**J3-J5**, après un infarctus **transmural** ; évolution le plus souvent favorable.","prio":"P2","sec":"s8"},{"id":"fc-235-3b6fee","poly":"cardio","fiche":"235","front":"Syndrome de Dressler : délai ?","back":"**2e-16e semaine** (item 235) ; classiquement la **3e semaine** (item 339).","prio":"P2","sec":"s8"},{"id":"fc-235-787d8d","poly":"cardio","fiche":"235","front":"Syndrome de Dressler : tableau ?","back":"Fièvre, péricardite, **pleurésie**, **arthralgies**, AEG, syndrome inflammatoire, **QT allongé** ; devenu rare.","prio":"P2","sec":"s8"},{"id":"fc-235-ac262f","poly":"cardio","fiche":"235","front":"Péricardite urémique : terrain ?","back":"Insuffisance rénale sévère **non encore dialysée** ou **premières semaines** de dialyse.","prio":"P2","sec":"s8"},{"id":"fc-235-266e20","poly":"cardio","fiche":"235","front":"Péricardite chez un dialysé au long cours : signification ?","back":"Le plus souvent une **épuration inadaptée**.","prio":"P3","sec":"s8"},{"id":"fc-235-795a7d","poly":"cardio","fiche":"235","front":"Syndrome postpéricardotomie : définition ?","back":"Péricardite inflammatoire dans les **jours ou mois** après **chirurgie** ou **transplantation cardiaque** ; tamponnade possible ; en postopératoire, penser aussi à l'**hémopéricarde**.","prio":"P2","sec":"s8"},{"id":"fc-235-798f96","poly":"cardio","fiche":"235","front":"Constriction péricardique : première cause actuelle ?","back":"La **chirurgie cardiaque**.","prio":"P2","sec":"s8"},{"id":"fc-235-7390ea","poly":"cardio","fiche":"235","front":"Péricardite post-radique : délai habituel ?","back":"En général **1 an** après l'irradiation thoracique.","prio":"P3","sec":"s8"},{"id":"fc-235-8c1ef9","poly":"cardio","fiche":"235","front":"Péricardite : causes médicamenteuses citées ?","back":"**Hydralazine**, **pénicilline**.","prio":"P3","sec":"s8"},{"id":"fc-235-c66db1","poly":"cardio","fiche":"235","front":"Péricardite : causes citées parmi les « autres causes » (hors médicaments) ?","back":"**Dissection aortique** (avec tamponnade), **irradiation thoracique**, **traumatismes**, **hypothyroïdie**, **rhumatisme articulaire aigu**.","prio":"P3","sec":"s8"},{"id":"fc-235-84f944","poly":"cardio","fiche":"235","front":"Péricardite traumatique : circonstances et fréquence ?","back":"Traumatisme thoracique ou cardiaque (**hémopéricarde**), **cathétérisme** (ablation par radiofréquence, pose de stimulateur), **postopératoire immédiat** ; causes **relativement fréquentes**.","prio":"P3","sec":"s8"},{"id":"fc-235-de1022","poly":"cardio","fiche":"235","front":"Tamponnade : causes à évoquer ?","back":"**Hémopéricarde**, **traumatique**, **néoplasique**, **tuberculeuse**, **post-infarctus**, **dissection aortique** ; virale exceptionnellement.","prio":"P2","sec":"s8"},{"id":"fc-235-9ee51e","poly":"cardio","fiche":"235","front":"Péricardite bénigne : repos ?","back":"**Arrêt de l'exercice physique** jusqu'à normalisation des symptômes, **CRP**, **ECG** et **écho** (en général le 1er mois).","prio":"P1","sec":"s9"},{"id":"fc-235-3509e5","poly":"cardio","fiche":"235","front":"Péricardite bénigne : traitement médicamenteux ?","back":"Antalgique + **AINS** (aspirine ou ibuprofène) + **colchicine** + **protecteur gastrique**.","prio":"P1","sec":"s9"},{"id":"fc-235-069c1f","poly":"cardio","fiche":"235","front":"Péricardite : posologie de l'aspirine ?","back":"**750 à 1 000 mg toutes les 8 h**, 1 à 2 semaines à pleine dose.","prio":"P1","sec":"s9"},{"id":"fc-235-ccca3a","poly":"cardio","fiche":"235","front":"Péricardite : posologie de l'ibuprofène ?","back":"**600 mg toutes les 8 h**, 1 à 2 semaines à pleine dose.","prio":"P1","sec":"s9"},{"id":"fc-235-6b34a3","poly":"cardio","fiche":"235","front":"Péricardite : durée totale de l'AINS (ESC 2015) ?","back":"Pleine dose 1 à 2 semaines puis **arrêt progressif** au bout de **4 à 8 semaines**.","prio":"P2","sec":"s9"},{"id":"fc-235-95fddb","poly":"cardio","fiche":"235","front":"Péricardite : posologie et durée de la colchicine ?","back":"**0,5 mg × 2/j** pendant **3 mois**.","prio":"P1","sec":"s9"},{"id":"fc-235-149af6","poly":"cardio","fiche":"235","front":"Colchicine : quand réduire à 0,5 mg/j ?","back":"Poids **< 70 kg**, âge **> 70 ans** ou DFG **< 35 mL/min**.","prio":"P2","sec":"s9"},{"id":"fc-235-67a43d","poly":"cardio","fiche":"235","front":"Colchicine : contre-indication ?","back":"**Insuffisance rénale sévère**.","prio":"P1","sec":"s9"},{"id":"fc-235-3ad457","poly":"cardio","fiche":"235","front":"Colchicine : modalités d'arrêt ?","back":"Arrêt progressif : la **dernière semaine** à **0,5 mg/j un jour sur deux**.","prio":"P2","sec":"s9"},{"id":"fc-235-8a26aa","poly":"cardio","fiche":"235","front":"Colchicine : interactions via quel cytochrome et quels médicaments ?","back":"**CYP3A4** : macrolides, ciclosporine, vérapamil, statines.","prio":"P2","sec":"s9"},{"id":"fc-235-01340f","poly":"cardio","fiche":"235","front":"Colchicine dans la péricardite : bénéfices ?","back":"Calme la douleur, raccourcit les symptômes, **réduit de 50 %** le risque de récidive.","prio":"P1","sec":"s9"},{"id":"fc-235-0f1409","poly":"cardio","fiche":"235","front":"Péricardite aiguë : corticoïdes en 1re intention ?","back":"**Non** : notion **inacceptable** (risque de récidive).","prio":"P1","sec":"s9"},{"id":"fc-235-3af1fb","poly":"cardio","fiche":"235","front":"Anti-inflammatoires de la péricardite : arrêt brutal ou progressif ?","back":"**Progressif** (AINS comme colchicine).","prio":"P2","sec":"s9"},{"id":"fc-235-7c41d5","poly":"cardio","fiche":"235","front":"Péricardite hospitalisée : traitement de base ?","back":"Le même : **repos**, antalgique, **AINS + colchicine**, protecteur gastrique, puis traitement de la cause ou complication.","prio":"P2","sec":"s10"},{"id":"fc-235-1c7909","poly":"cardio","fiche":"235","front":"Péricardite + myocardite associée : examen de référence ?","back":"**IRM** (et échocardiographie).","prio":"P2","sec":"s10"},{"id":"fc-235-a3105a","poly":"cardio","fiche":"235","front":"Échec de AINS + colchicine : traitement ajouté ?","back":"**Corticoïdes 0,25 à 0,5 mg/kg/j**, **en plus** de la bithérapie.","prio":"P2","sec":"s10"},{"id":"fc-235-0b6e06","poly":"cardio","fiche":"235","front":"Échec de la bithérapie : remplace-t-on AINS + colchicine par les corticoïdes ?","back":"**Non**, on **ajoute** la corticothérapie.","prio":"P2","sec":"s10"},{"id":"fc-235-f49065","poly":"cardio","fiche":"235","front":"Péricardite sous anticoagulant : risque des AINS ?","back":"**Majoration du risque hémorragique** (à éviter sous AVK ou AOD).","prio":"P2","sec":"s10"},{"id":"fc-235-55e502","poly":"cardio","fiche":"235","front":"Péricardite néoplasique avec tamponnade : conduite ?","back":"**Ponction en urgence** ; cytologie ou biopsie ; suivi clinique et échographique (récidives).","prio":"P2","sec":"s11"},{"id":"fc-235-637dc5","poly":"cardio","fiche":"235","front":"Tamponnade : mécanisme ?","back":"Épanchement abondant et/ou brutal qui **comprime les cavités droites** → **adiastolie**, risque d'arrêt cardiocirculatoire.","prio":"P1","sec":"s12"},{"id":"fc-235-a061c4","poly":"cardio","fiche":"235","front":"Pouls paradoxal : définition ?","back":"PAS inspiratoire **inférieure de 10 mmHg** à la PAS expiratoire (baisse marquée du pouls en inspiration).","prio":"P1","sec":"s12"},{"id":"fc-235-622f11","poly":"cardio","fiche":"235","front":"Pouls paradoxal : mécanisme ?","back":"À l'inspiration, le retour veineux dilate le VD qui **comprime le VG** → baisse de la PAS.","prio":"P2","sec":"s12"},{"id":"fc-235-0b52d3","poly":"cardio","fiche":"235","front":"Tamponnade : signes cliniques ?","back":"**Signes droits** (turgescence jugulaire, RHJ), **choc** (tachycardie, **PAS < 90 mmHg**), **bruits du cœur assourdis**, **pouls paradoxal**.","prio":"P1","sec":"s12"},{"id":"fc-235-294718","poly":"cardio","fiche":"235","front":"Tamponnade : symptômes respiratoires ?","back":"**Dyspnée positionnelle** : polypnée puis **orthopnée**, toux.","prio":"P2","sec":"s12"},{"id":"fc-235-35fbbd","poly":"cardio","fiche":"235","front":"Tamponnade : type de choc ?","back":"**Choc obstructif**.","prio":"P2","sec":"s12"},{"id":"fc-235-ae0446","poly":"cardio","fiche":"235","front":"Tamponnade : examen qui confirme ?","back":"L'**échocardiographie**.","prio":"P1","sec":"s12"},{"id":"fc-235-7e826c","poly":"cardio","fiche":"235","front":"Tamponnade : signes échographiques ?","back":"**Collapsus diastolique des cavités droites**, compression du VG par le VD en inspiration, **swinging heart**, septum paradoxal.","prio":"P2","sec":"s12"},{"id":"fc-235-a31acd","poly":"cardio","fiche":"235","front":"Tamponnade : prise en charge ?","back":"**USIC**, **remplissage par macromolécules**, arrêt/neutralisation des anticoagulants discuté, **ponction échoguidée** ou **drainage chirurgical** en urgence.","prio":"P1","sec":"s12"},{"id":"fc-235-e68c5f","poly":"cardio","fiche":"235","front":"Tamponnade confirmée à l'écho : conséquence ?","back":"Elle **impose le drainage** (risque d'arrêt par adiastolie).","prio":"P1","sec":"s12"},{"id":"fc-235-8f9ddc","poly":"cardio","fiche":"235","front":"Tamponnade sous HNF : antidote ?","back":"**Sulfate de protamine** (neutralisation instantanée).","prio":"P2","sec":"s12"},{"id":"fc-235-1b4592","poly":"cardio","fiche":"235","front":"Tamponnade sous AVK : antidotes ?","back":"**PPSB** (action très rapide) + **vitamine K** (quelques heures), toujours associés.","prio":"P2","sec":"s12"},{"id":"fc-235-2d6741","poly":"cardio","fiche":"235","front":"Dabigatran : antidote ?","back":"**Idarucizumab**.","prio":"P2","sec":"s12"},{"id":"fc-235-673763","poly":"cardio","fiche":"235","front":"Anti-Xa oraux : neutralisation possible ?","back":"**PPSB** ou **Feiba®** ; antidote spécifique en cours de commercialisation.","prio":"P3","sec":"s12"},{"id":"fc-235-091119","poly":"cardio","fiche":"235","front":"AOD : meilleur « antidote » selon le Collège ?","back":"Le **temps écoulé depuis la dernière prise** (demi-vie courte).","prio":"P3","sec":"s12"},{"id":"fc-235-a2d2c6","poly":"cardio","fiche":"235","front":"HBPM et fondaparinux : antidote ?","back":"**Pas d'antidote** (en cours de développement).","prio":"P3","sec":"s12"},{"id":"fc-235-9094c9","poly":"cardio","fiche":"235","front":"Hémorragie grave sous AVK : surveillance de l'INR après CCP ?","back":"INR **30 min** après le CCP (complément si **> 1,5**), puis à **6-8 h** et 1 fois/j.","prio":"P3","sec":"s12"},{"id":"fc-235-6e6c58","poly":"cardio","fiche":"235","front":"Péricardite : 6 complications ?","back":"**Épanchement abondant**, **tamponnade**, **myocardite**, **récidive**, **péricardite chronique**, **constriction**.","prio":"P1","sec":"s13"},{"id":"fc-235-817522","poly":"cardio","fiche":"235","front":"Myocardite associée : présentation ?","back":"IC **fébrile**, parfois **choc** (fulminante) ; **troponine** nettement élevée ± trouble de cinétique.","prio":"P2","sec":"s13"},{"id":"fc-235-452cec","poly":"cardio","fiche":"235","front":"Péricardite récidivante : fréquence et cause favorisante ?","back":"**20 à 30 %** (la plus fréquente) ; souvent après un traitement **trop court**.","prio":"P1","sec":"s13"},{"id":"fc-235-ee5f1d","poly":"cardio","fiche":"235","front":"Péricardite récidivante : délai typique ?","back":"**Entre 3 mois et 3 ans** après une péricardite d'allure virale.","prio":"P2","sec":"s13"},{"id":"fc-235-87bfee","poly":"cardio","fiche":"235","front":"Péricardite chronique : définition ?","back":"Évolution **> 3 mois**.","prio":"P2","sec":"s13"},{"id":"fc-235-c76c89","poly":"cardio","fiche":"235","front":"Péricardite chronique : causes retrouvées en pratique ?","back":"Surtout des **causes néoplasiques** (plus que la tuberculose).","prio":"P2","sec":"s13"},{"id":"fc-235-1d88f7","poly":"cardio","fiche":"235","front":"Péricardite chronique : examen pour la biopsie ?","back":"**Péricardoscopie** avec biopsie dirigée.","prio":"P3","sec":"s13"},{"id":"fc-235-32413c","poly":"cardio","fiche":"235","front":"Constriction péricardique : fréquence après péricardite ?","back":"Constriction modérée dans **moins de 10 %** des cas.","prio":"P2","sec":"s13"},{"id":"fc-235-ad408a","poly":"cardio","fiche":"235","front":"Constriction péricardique : mécanisme ?","back":"Péricarde épaissi fibreux ou **fibrocalcaire** → **adiastolie** avec **égalisation des pressions télédiastoliques** des 4 cavités.","prio":"P2","sec":"s13"},{"id":"fc-235-919c9a","poly":"cardio","fiche":"235","front":"Constriction péricardique : présentation clinique ?","back":"IC **droite** souvent prédominante (turgescence jugulaire, **ascite**) et gauche.","prio":"P2","sec":"s13"},{"id":"fc-235-0c170a","poly":"cardio","fiche":"235","front":"Constriction péricardique : signe au cathétérisme droit ?","back":"Aspect en **« dip-plateau »**.","prio":"P3","sec":"s13"},{"id":"fc-235-521768","poly":"cardio","fiche":"235","front":"Constriction péricardique : traitement chirurgical ?","back":"**Péricardectomie**.","prio":"P2","sec":"s13"},{"id":"fc-235-4dfb6a","poly":"cardio","fiche":"235","front":"Constriction péricardique : terrains ?","back":"**Chirurgie cardiaque** (1re cause), **tuberculose**, **péricardite purulente**.","prio":"P3","sec":"s13"},{"id":"fc-235-0f7bf1","poly":"cardio","fiche":"235","front":"Calcifications péricardiques : meilleur examen pour les voir ?","back":"Le **scanner** (parfois visibles à la radio).","prio":"P3","sec":"s13"},{"id":"fc-235-b4ef06","poly":"cardio","fiche":"235","front":"Colchicine : conduite en cas de diarrhée ?","back":"Elle doit **souvent** conduire à **baisser la dose**.","prio":"P2","sec":"s13"},{"id":"fc-235-bfbd67","poly":"cardio","fiche":"235","front":"Colchicine avec un inhibiteur du CYP3A4 : biologie à surveiller ?","back":"**Transaminases**, **créatinine**, **CPK**, **NFS**, **plaquettes**.","prio":"P3","sec":"s13"},{"id":"fc-235-a6658f","poly":"cardio","fiche":"235","front":"Péricardite : calendrier de suivi ?","back":"**J7** (médecin traitant), **1 mois** (cardiologue + écho), **3 et 6 mois**.","prio":"P1","sec":"s14"},{"id":"fc-235-308234","poly":"cardio","fiche":"235","front":"Péricardite : quand l'échocardiographie de contrôle ?","back":"À **1 mois**, **avant l'arrêt** de l'anti-inflammatoire.","prio":"P1","sec":"s14"},{"id":"fc-235-bdb17a","poly":"cardio","fiche":"235","front":"Péricardite : objectif de la consultation à J7 ?","back":"Vérifier l'absence de symptômes (résistance à 7 jours = **facteur majeur**).","prio":"P2","sec":"s14"},{"id":"fc-235-752573","poly":"cardio","fiche":"235","front":"Péricardite : objectifs des consultations à 3 et 6 mois ?","back":"Absence de symptômes, normalisation **CRP** et **écho**, modalités d'**arrêt des traitements**.","prio":"P2","sec":"s14"},{"id":"fc-235-3fd11e","poly":"cardio","fiche":"235","front":"Péricardite : conditions de reprise du sport ?","back":"Disparition des symptômes et normalisation **CRP**, **ECG**, **écho** (en général après le **1er mois**).","prio":"P1","sec":"s14"},{"id":"fc-235-fefccd","poly":"cardio","fiche":"235","front":"Péricardite : message à donner sur la durée du traitement ?","back":"Une durée **insuffisante** expose à la **récidive**.","prio":"P2","sec":"s14"},{"id":"fc-236-e47e43","poly":"cardio","fiche":"236","front":"Troubles de conduction : 3 cadres ?","back":"**Dysfonction sinusale** ; **bloc atrioventriculaire** ; **bloc de branche / hémibloc**.","prio":"P1","sec":"s1"},{"id":"fc-236-ed0fd3","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : ce qui est atteint ?","back":"Le nœud sinusal : trouble de l'**automatisme** et/ou **bloc sinoatrial**.","prio":"P2","sec":"s1"},{"id":"fc-236-d98729","poly":"cardio","fiche":"236","front":"BAV : ce qui est atteint ?","back":"La **jonction atrioventriculaire** et/ou les **deux branches** du His à la fois.","prio":"P2","sec":"s1"},{"id":"fc-236-1a5800","poly":"cardio","fiche":"236","front":"Rythme d'échappement : où naît-il ?","back":"Toujours **en aval** de la zone malade.","prio":"P1","sec":"s1"},{"id":"fc-236-f1b7e6","poly":"cardio","fiche":"236","front":"Troubles de conduction : règle de gravité ?","back":"Plus la lésion est **distale**, plus l'échappement est **lent et instable** → plus c'est grave.","prio":"P1","sec":"s1"},{"id":"fc-236-e0059e","poly":"cardio","fiche":"236","front":"Bloc suprahissien vs hissien/infrahissien : échappement ?","back":"Suprahissien (sinus, NAV) : plus **rapide et stable** ; hissien/infrahissien : **lent, instable**.","prio":"P1","sec":"s1"},{"id":"fc-236-fa2419","poly":"cardio","fiche":"236","front":"Trouble de conduction : sur quel examen repose le diagnostic ?","back":"L'**ECG** (diagnostic électrocardiographique).","prio":"P1","sec":"s1"},{"id":"fc-236-6a2df9","poly":"cardio","fiche":"236","front":"Tissu de conduction : trajet de haut en bas ?","back":"Nœud sinusal → **NAV** → **His** → branches droite et gauche (hémibranches antérieure et postérieure) → **Purkinje**.","prio":"P3","sec":"s1"},{"id":"fc-236-b800cc","poly":"cardio","fiche":"236","front":"NAV : vascularisation ?","back":"**Artère du NAV**, branche de la **coronaire droite** (croix des sillons).","prio":"P3","sec":"s1"},{"id":"fc-236-2179da","poly":"cardio","fiche":"236","front":"Faisceau de His et branches : vascularisation ?","back":"**1re septale de l'IVA** et artère du NAV.","prio":"P3","sec":"s1"},{"id":"fc-236-8c50bb","poly":"cardio","fiche":"236","front":"Tissu nodal vs His-Purkinje : conduction et influence du SNA ?","back":"Nodal : lente, **décrémentielle**, forte influence du SNA ; His-Purkinje : rapide, « **tout ou rien** », peu d'influence.","prio":"P2","sec":"s1"},{"id":"fc-236-1c700c","poly":"cardio","fiche":"236","front":"Échappement nodal (NAV) : fréquence et QRS ?","back":"**40-60 bpm**, QRS **fins**, **stable**.","prio":"P2","sec":"s1"},{"id":"fc-236-7a994e","poly":"cardio","fiche":"236","front":"Échappement hissien : fréquence et QRS ?","back":"**35-45 bpm**, QRS fins, instable.","prio":"P3","sec":"s1"},{"id":"fc-236-9658ad","poly":"cardio","fiche":"236","front":"Échappement infrahissien : fréquence et QRS ?","back":"**< 40 bpm**, QRS **larges**, instable.","prio":"P2","sec":"s1"},{"id":"fc-236-6b5ac3","poly":"cardio","fiche":"236","front":"Trouble de conduction : de quoi peut-il être le marqueur ?","back":"D'une **cardiopathie**, à rechercher.","prio":"P2","sec":"s1"},{"id":"fc-236-3e77e2","poly":"cardio","fiche":"236","front":"QRS large sans bloc de branche systématisé : mécanisme ?","back":"**Bloc intraventriculaire non systématisé** (cardiopathie).","prio":"P3","sec":"s1"},{"id":"fc-236-a618bc","poly":"cardio","fiche":"236","front":"BAV complet nodal vs infranodal : quel est le plus grave ?","back":"**Infranodal** : échappement lent, instable, risque d'**asystolie**.","prio":"P1","sec":"s1"},{"id":"fc-236-bc13e6","poly":"cardio","fiche":"236","front":"Troubles de conduction : sont-ils souvent asymptomatiques ?","back":"**Oui** : dysfonction sinusale latente, BAV 1 et la plupart des BAV 2.","prio":"P2","sec":"s2"},{"id":"fc-236-79fe43","poly":"cardio","fiche":"236","front":"Bas débit cérébral par bradycardie : symptômes ?","back":"**Lipothymies**, **syncopes à l'emporte-pièce (Adams-Stokes)**, pseudovertiges.","prio":"P1","sec":"s2"},{"id":"fc-236-dc3c42","poly":"cardio","fiche":"236","front":"Bradycardie permanente : symptômes de bas débit cardiaque ?","back":"Moindre capacité d'effort, dyspnée d'effort, **asthénie**, **angor**, **insuffisance cardiaque**.","prio":"P2","sec":"s2"},{"id":"fc-236-64dc49","poly":"cardio","fiche":"236","front":"Bradycardie chez le sujet âgé : signes trompeurs ?","back":"**Chutes à répétition**, **déclin cognitif**, réduction d'activité.","prio":"P1","sec":"s2"},{"id":"fc-236-cb7daf","poly":"cardio","fiche":"236","front":"Dysfonction sinusale + FA : symptômes possibles ?","back":"**Palpitations** ou **embolie artérielle** (maladie rythmique atriale).","prio":"P3","sec":"s2"},{"id":"fc-236-372919","poly":"cardio","fiche":"236","front":"BAV à l'effort seulement : siège habituel ?","back":"**Intra- ou infrahissien** (fréquence-dépendant).","prio":"P3","sec":"s2"},{"id":"fc-236-abd4a0","poly":"cardio","fiche":"236","front":"Torsade de pointes sur bradycardie : facteurs favorisants et risque ?","back":"**Bradycardie** + **allongement du QT** ; risque de **fibrillation ventriculaire**.","prio":"P1","sec":"s2"},{"id":"fc-236-c448d6","poly":"cardio","fiche":"236","front":"BAV : circonstances de découverte typiques ?","back":"**Bradycardie constatée** à l'éveil ou bilan d'une **lipothymie/syncope**.","prio":"P2","sec":"s2"},{"id":"fc-236-954999","poly":"cardio","fiche":"236","front":"Bloc de branche isolé : symptômes ?","back":"**Toujours asymptomatique** (découverte fortuite).","prio":"P1","sec":"s2"},{"id":"fc-236-c1100c","poly":"cardio","fiche":"236","front":"Bloc de branche + syncopes : signification ?","back":"**Signe de gravité** immédiat ; peut signer une cardiopathie (surtout BBG) ou faire suspecter un **BAV paroxystique**.","prio":"P1","sec":"s2"},{"id":"fc-236-b9bb38","poly":"cardio","fiche":"236","front":"Dysfonction sinusale du sujet âgé : quel médicament rechercher ?","back":"Un **bradycardisant**, surtout **bêtabloquant**, y compris en **collyre**.","prio":"P2","sec":"s2"},{"id":"fc-236-90164d","poly":"cardio","fiche":"236","front":"Bradycardie sinusale du sportif d'endurance asymptomatique : traiter ?","back":"**Non** (hypertonie vagale).","prio":"P1","sec":"s2"},{"id":"fc-236-9ea516","poly":"cardio","fiche":"236","front":"Dysfonction sinusale du sujet âgé : faut-il traiter ?","back":"**Souvent oui** (fibrose, souvent avec FA ou atteinte du NAV).","prio":"P2","sec":"s2"},{"id":"fc-236-f421b9","poly":"cardio","fiche":"236","front":"Nœud sinusal : localisation ?","back":"Atrium droit, à la jonction avec la **veine cave supérieure**.","prio":"P3","sec":"s3"},{"id":"fc-236-b0056c","poly":"cardio","fiche":"236","front":"Rythme sinusal normal : fréquence ?","back":"**50-100 bpm**.","prio":"P3","sec":"s3"},{"id":"fc-236-b70b90","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : 2 mécanismes ?","back":"Impulsion **non fabriquée** (trouble de l'automatisme) ou **non transmise** à l'oreillette (bloc sinoatrial).","prio":"P2","sec":"s3"},{"id":"fc-236-b85633","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : cause habituelle ?","back":"**Fibrose liée à l'âge**.","prio":"P2","sec":"s3"},{"id":"fc-236-6baa1a","poly":"cardio","fiche":"236","front":"Maladie rythmique atriale : définition ?","back":"Dysfonction sinusale + troubles du rythme atrial : **syndrome brady-tachy** ou **pauses post-réductionnelles**.","prio":"P2","sec":"s3"},{"id":"fc-236-2d1a1a","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : critère de bradycardie ?","back":"Bradycardie sinusale inappropriée **< 50 bpm** à l'éveil (< 40/min la nuit).","prio":"P1","sec":"s3"},{"id":"fc-236-2e11e5","poly":"cardio","fiche":"236","front":"Bradycardie sinusale inappropriée : définition et tolérance ?","back":"Bradycardie diurne marquée (< 50 bpm) **sans cause extrinsèque** ; en général **bien tolérée** (symptômes possibles avec l'âge).","prio":"P3","sec":"s3"},{"id":"fc-236-365f6a","poly":"cardio","fiche":"236","front":"Pause sinusale : seuil pathologique ?","back":"**> 3 secondes**.","prio":"P1","sec":"s3"},{"id":"fc-236-b5fecd","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : critères ECG (liste) ?","back":"Bradycardie < 50 bpm, **incompétence chronotrope**, pauses > 3 s, **BSA 2 ou 3**, brady-tachy, pause > 3 s au massage sinocarotidien ou tilt-test.","prio":"P2","sec":"s3"},{"id":"fc-236-d7eeb6","poly":"cardio","fiche":"236","front":"Pause sinusale : comment se termine-t-elle ?","back":"Par un échappement **atrial** (P différente) ou **jonctionnel** (QRS sans P).","prio":"P3","sec":"s3"},{"id":"fc-236-83a3a2","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : examen de référence ?","back":"**Holter** (ECG continu).","prio":"P2","sec":"s3"},{"id":"fc-236-19d318","poly":"cardio","fiche":"236","front":"BSA du 1er degré : aspect ECG ?","back":"**Rien** (invisible à l'ECG).","prio":"P2","sec":"s3"},{"id":"fc-236-488ef7","poly":"cardio","fiche":"236","front":"BSA 2e degré type I : aspect ECG ?","back":"P irrégulières puis pause **inférieure au double** du cycle sinusal le plus court.","prio":"P3","sec":"s3"},{"id":"fc-236-9e4d4d","poly":"cardio","fiche":"236","front":"BSA 2e degré type II : aspect ECG ?","back":"Pauses égales à un **multiple** du cycle sinusal (2/1, 3/1).","prio":"P2","sec":"s3"},{"id":"fc-236-22d030","poly":"cardio","fiche":"236","front":"BSA 3e degré : aspect ECG ?","back":"Bradycardie à **échappement jonctionnel** (QRS fins) sans activité sinusale.","prio":"P2","sec":"s3"},{"id":"fc-236-f10294","poly":"cardio","fiche":"236","front":"Insuffisance chronotrope : définition ?","back":"FC qui n'accélère pas assez à l'effort ; seuil habituel : FC max **< 75 %** de la fréquence maximale théorique ; courbe **aplatie** au holter.","prio":"P2","sec":"s3"},{"id":"fc-236-2f0fd0","poly":"cardio","fiche":"236","front":"Pauses post-réductionnelles : mécanisme ?","back":"**Sidération du nœud sinusal** à l'arrêt de l'arythmie atriale.","prio":"P3","sec":"s3"},{"id":"fc-236-120688","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : comment prouver le lien avec les symptômes ?","back":"**Holter avec journal** des symptômes ; si rares : enregistreur longue durée ou **moniteur implantable**.","prio":"P2","sec":"s3"},{"id":"fc-236-e68f65","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : intérêt du test d'effort ?","back":"Diagnostic de l'**insuffisance chronotrope**.","prio":"P3","sec":"s3"},{"id":"fc-236-442c76","poly":"cardio","fiche":"236","front":"Dysfonction sinusale sévère symptomatique : bilan minimal ?","back":"**Échocardiographie**, **ionogramme**, **créatinine**, **troponine** + causes extrinsèques.","prio":"P3","sec":"s3"},{"id":"fc-236-ab3f3d","poly":"cardio","fiche":"236","front":"Ondes P bloquées : compatibles avec une dysfonction sinusale ?","back":"**Non**, jamais : penser au **BAV**.","prio":"P1","sec":"s3"},{"id":"fc-236-c1a36b","poly":"cardio","fiche":"236","front":"Faisceau de His : particularité anatomique ?","back":"**Seule communication électrique** entre oreillettes et ventricules.","prio":"P2","sec":"s4"},{"id":"fc-236-ef694d","poly":"cardio","fiche":"236","front":"Phénomène de Wenckebach : définition ?","back":"Stimulation atriale de plus en plus rapide → la conduction nodale s'allonge progressivement jusqu'au **blocage** (conduction **décrémentielle**).","prio":"P2","sec":"s4"},{"id":"fc-236-1641e0","poly":"cardio","fiche":"236","front":"BAV complet infranodal : fréquence d'échappement ?","back":"**15-40/min**, instable, risque d'**asystolie**.","prio":"P2","sec":"s4"},{"id":"fc-236-27c2e7","poly":"cardio","fiche":"236","front":"BAV : 4 éléments à préciser à l'ECG ?","back":"**Degré**, **paroxystique ou permanent**, **congénital ou acquis**, et surtout **siège**.","prio":"P2","sec":"s4"},{"id":"fc-236-0bac45","poly":"cardio","fiche":"236","front":"BAV du 1er degré : critère ECG ?","back":"**PR > 200 ms**, fixe et constant.","prio":"P1","sec":"s4"},{"id":"fc-236-96b5ed","poly":"cardio","fiche":"236","front":"BAV du 1er degré : siège habituel ?","back":"Généralement **nodal** (exceptionnellement intrahissien).","prio":"P2","sec":"s4"},{"id":"fc-236-646088","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 1 : critère ECG ?","back":"**Allongement progressif du PR** jusqu'à une P bloquée, puis PR plus court.","prio":"P1","sec":"s4"},{"id":"fc-236-798533","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 1 : siège ?","back":"**Toujours nodal**.","prio":"P1","sec":"s4"},{"id":"fc-236-9fbe30","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 2 : critère ECG ?","back":"**Une P bloquée** inopinée **sans allongement préalable du PR**.","prio":"P1","sec":"s4"},{"id":"fc-236-c880b7","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 2 : siège ?","back":"**Toujours hissien ou infrahissien** ; évolue souvent vers le BAV complet.","prio":"P1","sec":"s4"},{"id":"fc-236-ad8157","poly":"cardio","fiche":"236","front":"BAV de haut degré : critère ECG ?","back":"**Plusieurs P bloquées** de suite ou conduction rythmée (ex. 3:1).","prio":"P2","sec":"s4"},{"id":"fc-236-71aa2e","poly":"cardio","fiche":"236","front":"BAV de haut degré : siège habituel ?","back":"**Hissien ou infrahissien**, rarement nodal ; évolue souvent vers le BAV complet.","prio":"P2","sec":"s4"},{"id":"fc-236-862b37","poly":"cardio","fiche":"236","front":"BAV 2/1 : peut-on le classer en Mobitz 1 ou 2 ?","back":"**Non**, inclassable : la **largeur du QRS** oriente (large → infranodal).","prio":"P1","sec":"s4"},{"id":"fc-236-bd516b","poly":"cardio","fiche":"236","front":"BAV du 3e degré : critère ECG ?","back":"Aucune P conduite : **dissociation atrioventriculaire**, ventricules plus lents que les oreillettes.","prio":"P1","sec":"s4"},{"id":"fc-236-df840a","poly":"cardio","fiche":"236","front":"BAV complet sur FA : aspect ECG ?","back":"Bradycardie avec rythme ventriculaire **régulier**.","prio":"P2","sec":"s4"},{"id":"fc-236-13d530","poly":"cardio","fiche":"236","front":"Bloc nodal : effet de l'atropine, isoprénaline et effort ?","back":"**Amélioré**.","prio":"P1","sec":"s4"},{"id":"fc-236-88e2d4","poly":"cardio","fiche":"236","front":"Bloc hissien/infrahissien : effet de l'atropine et de l'effort ?","back":"**Aggravé**.","prio":"P1","sec":"s4"},{"id":"fc-236-8bd597","poly":"cardio","fiche":"236","front":"Bloc nodal vs infranodal : effet du massage sinocarotidien ?","back":"Aggrave le **nodal** ; améliore l'infranodal.","prio":"P2","sec":"s4"},{"id":"fc-236-690e75","poly":"cardio","fiche":"236","front":"Bloc infranodal : terrain fréquent ?","back":"**Bloc de branche** préexistant.","prio":"P2","sec":"s4"},{"id":"fc-236-dd791d","poly":"cardio","fiche":"236","front":"QRS < 120 ms avec BAV : orientation ?","back":"Très en faveur d'un bloc **nodal**, sans certitude.","prio":"P2","sec":"s4"},{"id":"fc-236-e97178","poly":"cardio","fiche":"236","front":"BAV à QRS fins : piège classique ?","back":"Le BAV **intrahissien**, rare, à QRS fins.","prio":"P1","sec":"s4"},{"id":"fc-236-14adca","poly":"cardio","fiche":"236","front":"Bloc hissien/infrahissien : examen de référence pour l'affirmer ?","back":"L'**EEP** (étude électrophysiologique endocavitaire).","prio":"P2","sec":"s4"},{"id":"fc-236-77d53c","poly":"cardio","fiche":"236","front":"BAV : lesquels sont symptomatiques ?","back":"**Haut degré** et **BAV 3** ; Mobitz 1 et 2 : inconstants ; BAV 1 : sans symptôme (sauf PR très long).","prio":"P2","sec":"s4"},{"id":"fc-236-b51c03","poly":"cardio","fiche":"236","front":"BAV : forme la plus fréquente ?","back":"**BAV dégénératif du sujet âgé** ; toujours chercher une cause **médicamenteuse** associée.","prio":"P2","sec":"s4"},{"id":"fc-236-2ec9a9","poly":"cardio","fiche":"236","front":"BAV permanent : examen suffisant ?","back":"L'**ECG**.","prio":"P3","sec":"s4"},{"id":"fc-236-8e9f9f","poly":"cardio","fiche":"236","front":"BAV non permanent suspecté : examens ?","back":"**Holter**, parfois **moniteur cardiaque implantable**.","prio":"P3","sec":"s4"},{"id":"fc-236-19dd61","poly":"cardio","fiche":"236","front":"EEP : seuil pathologique de l'intervalle HV ?","back":"**HV ≥ 70 ms** (atteinte infrahissienne).","prio":"P2","sec":"s4"},{"id":"fc-236-880057","poly":"cardio","fiche":"236","front":"BAV : bilan minimal étiologique ?","back":"**Ionogramme**, **échocardiographie**, **troponine**.","prio":"P2","sec":"s4"},{"id":"fc-236-481c63","poly":"cardio","fiche":"236","front":"BAV chez un sujet < 50 ans : bilan approfondi ?","back":"**IRM cardiaque** (myocardite) et recherche **génétique**.","prio":"P3","sec":"s4"},{"id":"fc-236-77fae9","poly":"cardio","fiche":"236","front":"BAV congénital : cause principale ?","back":"**Immunologique** : anticorps maternels **anti-Ro/SSA** (lupus, Gougerot-Sjögren).","prio":"P3","sec":"s4"},{"id":"fc-236-d22d24","poly":"cardio","fiche":"236","front":"Bradyarythmie : définition ?","back":"**BAV sur FA permanente** : FA lente avec pauses > 3 s, ou rythme lent **régulier** (BAV 3) ou **irrégulier** (BAV 2).","prio":"P3","sec":"s4"},{"id":"fc-236-b13d67","poly":"cardio","fiche":"236","front":"Branche gauche du His : subdivisions ?","back":"Hémibranche **antérieure (fine)** et **postérieure (épaisse)**.","prio":"P3","sec":"s5"},{"id":"fc-236-67abf9","poly":"cardio","fiche":"236","front":"Branches et Purkinje : sensibilité au SNA et à l'ischémie ?","back":"**Peu sensibles**.","prio":"P3","sec":"s5"},{"id":"fc-236-d3eb27","poly":"cardio","fiche":"236","front":"Bloc de branche : définition ?","back":"**Ralentissement** ou **interruption** de la conduction dans une branche du His.","prio":"P2","sec":"s5"},{"id":"fc-236-aa7fec","poly":"cardio","fiche":"236","front":"Bloc de branche complet : critère de durée du QRS ?","back":"**QRS > 120 ms**.","prio":"P1","sec":"s5"},{"id":"fc-236-43ee37","poly":"cardio","fiche":"236","front":"Bloc de branche : comment déterminer le côté ?","back":"**V1 positif = droit** ; **V1 négatif = gauche**.","prio":"P1","sec":"s5"},{"id":"fc-236-a36376","poly":"cardio","fiche":"236","front":"Bloc de branche incomplet : valeur ?","back":"QRS ≤ 120 ms : **peu de valeur** sémiologique ou clinique.","prio":"P3","sec":"s5"},{"id":"fc-236-a630c9","poly":"cardio","fiche":"236","front":"BBD complet : aspect en V1 et V6 ?","back":"V1 **rsR'** ; V6 qRs avec **onde S traînante**.","prio":"P2","sec":"s5"},{"id":"fc-236-3b86e7","poly":"cardio","fiche":"236","front":"BBG complet : aspect en V1 et V6 ?","back":"V1 **rS ou QS** ; D1 et V6 **R avec notch**.","prio":"P2","sec":"s5"},{"id":"fc-236-0679df","poly":"cardio","fiche":"236","front":"BBD : localisation des T négatives ?","back":"En général **V1-V2** (parfois V3).","prio":"P2","sec":"s5"},{"id":"fc-236-25a1f7","poly":"cardio","fiche":"236","front":"BBG : localisation des T négatives ?","back":"En général **D1, aVL, V5-V6**.","prio":"P2","sec":"s5"},{"id":"fc-236-b02577","poly":"cardio","fiche":"236","front":"BBG et suspicion d'infarctus : conduite ?","back":"Prendre en charge comme un **SCA ST+** (le BBG gêne le diagnostic).","prio":"P1","sec":"s5"},{"id":"fc-236-38badd","poly":"cardio","fiche":"236","front":"HBAG : critères ?","back":"QRS < 120 ms, **axe gauche au-delà de −45°**, qR en D1-aVL, rS en D2-D3-aVF avec **S3 > S2**.","prio":"P2","sec":"s5"},{"id":"fc-236-000067","poly":"cardio","fiche":"236","front":"HBPG : critères ?","back":"**Axe droit > +90°** (hors pathologie du VD ou morphologie longiligne), aspect **S1Q3**.","prio":"P2","sec":"s5"},{"id":"fc-236-b43395","poly":"cardio","fiche":"236","front":"HBAG vs HBPG : fréquence et gravité ?","back":"HBAG **fréquent** ; HBPG plus **rare**, potentiellement **plus grave**.","prio":"P2","sec":"s5"},{"id":"fc-236-a04314","poly":"cardio","fiche":"236","front":"Bloc bifasciculaire : définition ?","back":"**BBD + HBAG** ou **BBD + HBPG**.","prio":"P2","sec":"s5"},{"id":"fc-236-2a78b4","poly":"cardio","fiche":"236","front":"Bloc alternant : définition et signification ?","back":"BBD puis BBG, ou HBAG/HBPG alternants sur BBD : **trifasciculaire** = BAV complet paroxystique infrahissien, **grave**.","prio":"P1","sec":"s5"},{"id":"fc-236-b784ad","poly":"cardio","fiche":"236","front":"IDM antérieur : fréquence et risque du bloc de branche ?","back":"**10 %** ; nécrose septale étendue → risque de **BAV complet brutal** avec asystolie.","prio":"P2","sec":"s5"},{"id":"fc-236-b88243","poly":"cardio","fiche":"236","front":"Bloc bifasciculaire + perte de connaissance : conduite ?","back":"Rechercher une **cardiopathie**, puis **EEP** (HV ≥ 70 ms → stimulateur).","prio":"P2","sec":"s5"},{"id":"fc-236-19013c","poly":"cardio","fiche":"236","front":"Trouble de conduction : 3 éléments qui guident la conduite ?","back":"**Type** de trouble, **contexte** clinique, **tolérance hémodynamique**.","prio":"P2","sec":"s6"},{"id":"fc-236-d95d21","poly":"cardio","fiche":"236","front":"Bradycardie mal tolérée : critères ?","back":"**Syncope**/lipothymie, **angor**, **insuffisance cardiaque**, **choc** (hypotension, oligurie, signes neurologiques), **torsade de pointes**.","prio":"P1","sec":"s6"},{"id":"fc-236-a5c71a","poly":"cardio","fiche":"236","front":"Troubles de conduction imposant l'hospitalisation urgente ?","back":"**BAV 3**, **Mobitz 2**, **haut degré**, **blocs alternants**, **BSA 3**, **syncope + trouble conductif** (M.A.S.H. 33).","prio":"P1","sec":"s6"},{"id":"fc-236-6398c2","poly":"cardio","fiche":"236","front":"Bloc de branche isolé sans symptôme aigu : explorations ?","back":"**Non urgentes**.","prio":"P2","sec":"s6"},{"id":"fc-236-4eca47","poly":"cardio","fiche":"236","front":"Trouble de conduction à risque vital : conduite immédiate ?","back":"**USIC**, **scope**, surveillance pouls, PA, FR, SpO₂, diurèse ; traiter une cause réversible.","prio":"P1","sec":"s6"},{"id":"fc-236-d5db11","poly":"cardio","fiche":"236","front":"BAV 3 : comment prévenir la torsade de pointes ?","back":"**Éviter les médicaments allongeant le QT** ; **corriger une hypokaliémie**.","prio":"P1","sec":"s6"},{"id":"fc-236-73c596","poly":"cardio","fiche":"236","front":"Bradycardie par BAV complet vs dysfonction sinusale : laquelle est la plus grave ?","back":"Le **BAV complet** (torsades, asystolie).","prio":"P1","sec":"s6"},{"id":"fc-236-0f840e","poly":"cardio","fiche":"236","front":"Mauvaise tolérance d'une bradycardie : moyen mnémotechnique ?","back":"**ACTIONS** : Angor, Choc, Torsade, Insuffisance cardiaque, Oligurie, signes Neurologiques, Syncope.","prio":"P3","sec":"s6"},{"id":"fc-236-bbd9bb","poly":"cardio","fiche":"236","front":"Trouble de conduction : notion inacceptable ?","back":"**Oublier de rechercher une cause curable**.","prio":"P1","sec":"s7"},{"id":"fc-236-6cf6ef","poly":"cardio","fiche":"236","front":"Troubles de conduction : 3 causes aiguës réversibles prioritaires ?","back":"**IDM ST+**, **médicament bradycardisant**, **hyperkaliémie**.","prio":"P1","sec":"s7"},{"id":"fc-236-e07192","poly":"cardio","fiche":"236","front":"Hyperkaliémie : particularités des troubles conductifs ?","back":"Atteinte **à tous les étages** ; ondes T **amples et pointues**.","prio":"P1","sec":"s7"},{"id":"fc-236-c2ac0c","poly":"cardio","fiche":"236","front":"Hyperkaliémie responsable de troubles conductifs : contextes à risque ?","back":"**Insuffisance rénale** ; **médicaments hyperkaliémiants**.","prio":"P2","sec":"s7"},{"id":"fc-236-31cc3f","poly":"cardio","fiche":"236","front":"Troubles de conduction vagaux : pronostic ?","back":"**Bénins**.","prio":"P2","sec":"s7"},{"id":"fc-236-b7b3cf","poly":"cardio","fiche":"236","front":"Troubles de conduction : cause chronique la plus fréquente ?","back":"**Dégénérescence fibreuse** liée à l'âge.","prio":"P2","sec":"s7"},{"id":"fc-236-d5baf8","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : médicaments en cause ?","back":"**Bêtabloquants**, inhibiteurs calciques bradycardisants, **amiodarone**, **ivabradine**, **digitaliques**, **clonidine**.","prio":"P2","sec":"s7"},{"id":"fc-236-865d4a","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : causes extrinsèques non médicamenteuses ?","back":"Vagale, **HTIC**, syndromes méningés, hyperkaliémie, hypoxie/hypercapnie/acidose **sévères**, apnées du sommeil, **hypothermie**, **hypothyroïdie**, ictère rétentionnel sévère.","prio":"P3","sec":"s7"},{"id":"fc-236-238ed0","poly":"cardio","fiche":"236","front":"Maladie de Lenègre : définition ?","back":"BAV dégénératif du sujet âgé (**fibrose** ± calcifications).","prio":"P2","sec":"s7"},{"id":"fc-236-d6eb39","poly":"cardio","fiche":"236","front":"BAV : causes infectieuses ?","back":"**Endocardite** (abcès de l'anneau), myocardite de **Lyme** ou virale.","prio":"P2","sec":"s7"},{"id":"fc-236-96710e","poly":"cardio","fiche":"236","front":"BAV : causes iatrogènes interventionnelles ?","back":"Chirurgie valvulaire, **TAVI**, myomectomie, cathétérisme, **ablation** par radiofréquence.","prio":"P3","sec":"s7"},{"id":"fc-236-511fd9","poly":"cardio","fiche":"236","front":"BAV : valvulopathie en cause ?","back":"**Rétrécissement aortique calcifié**.","prio":"P3","sec":"s7"},{"id":"fc-236-118512","poly":"cardio","fiche":"236","front":"BAV : maladies infiltratives en cause ?","back":"**Sarcoïdose**, **amylose**, hémochromatose, maladie de Fabry.","prio":"P3","sec":"s7"},{"id":"fc-236-bbfb41","poly":"cardio","fiche":"236","front":"Bloc de branche : causes extrinsèques ?","back":"**Hyperkaliémie** ; antiarythmiques de classe I (**flécaïnide**), **antidépresseurs tricycliques**.","prio":"P2","sec":"s7"},{"id":"fc-236-b1c298","poly":"cardio","fiche":"236","front":"BBD : causes ?","back":"Variante de la normale ou atteinte du **VD** (congénitale, HTP, séquelle d'EP).","prio":"P3","sec":"s7"},{"id":"fc-236-4b4176","poly":"cardio","fiche":"236","front":"Causes aiguës réversibles de trouble de conduction : moyen mnémotechnique ?","back":"**MIMI** : Médicament, Ischémie, Métabolique (hyperkaliémie), Infectieuse/inflammatoire.","prio":"P2","sec":"s7"},{"id":"fc-236-b2d6b0","poly":"cardio","fiche":"236","front":"Trouble de conduction : bilan minimal ?","back":"**É.T.I.** : Échocardiographie, Troponine, Ionogramme.","prio":"P2","sec":"s7"},{"id":"fc-236-04ad41","poly":"cardio","fiche":"236","front":"BBG ou BAV 3 à QRS larges avec suspicion d'IDM : piège ?","back":"ECG **non informatif** : ne pas se rassurer sur l'absence de sus-ST ; coronarographie urgente à discuter.","prio":"P1","sec":"s8"},{"id":"fc-236-80e5c8","poly":"cardio","fiche":"236","front":"Syncope chez un cardiopathe porteur d'un bloc de branche : diagnostic à évoquer en plus du BAV ?","back":"**Tachycardie ventriculaire**.","prio":"P1","sec":"s8"},{"id":"fc-236-ee6ef5","poly":"cardio","fiche":"236","front":"FA lente et régulière : quoi évoquer ?","back":"Un **BAV complet** sur FA.","prio":"P1","sec":"s8"},{"id":"fc-236-cd85f6","poly":"cardio","fiche":"236","front":"BAV sur FA permanente vs maladie rythmique atriale : différence ?","back":"**Bradyarythmie** = BAV sur FA permanente ; **maladie rythmique atriale** = FA le plus souvent paroxystique + dysfonction sinusale.","prio":"P2","sec":"s8"},{"id":"fc-236-5ad11d","poly":"cardio","fiche":"236","front":"BBD isolé vs BBG : pronostic ?","back":"BBD typique isolé du jeune asymptomatique à examen normal = **variante de la normale** ; **BBG jamais bénin**.","prio":"P2","sec":"s8"},{"id":"fc-236-04fe06","poly":"cardio","fiche":"236","front":"Bradycardie mal tolérée : moyens pour accélérer le cœur ?","back":"**Isoprénaline**, **atropine**, ou **stimulation temporaire**.","prio":"P1","sec":"s9"},{"id":"fc-236-ad93df","poly":"cardio","fiche":"236","front":"Isoprénaline : mode d'administration et efficacité ?","back":"**Perfusion IV continue** ; efficace sur **tous les blocs** ; à privilégier.","prio":"P2","sec":"s9"},{"id":"fc-236-d2b3f1","poly":"cardio","fiche":"236","front":"Isoprénaline : contre-indication majeure ?","back":"**IDM aigu** (inférieur comme antérieur).","prio":"P1","sec":"s9"},{"id":"fc-236-9ac8de","poly":"cardio","fiche":"236","front":"Atropine : mode d'administration et indications ?","back":"**Bolus IV**, action **brève** ; seulement **BAV nodal** ou **dysfonction sinusale**.","prio":"P2","sec":"s9"},{"id":"fc-236-be9aeb","poly":"cardio","fiche":"236","front":"Atropine sur un bloc infranodal ?","back":"**Inefficace**, voire **aggrave** le bloc.","prio":"P1","sec":"s9"},{"id":"fc-236-b4017e","poly":"cardio","fiche":"236","front":"Échec de l'isoprénaline avec mauvaise tolérance : conduite ?","back":"**Stimulation temporaire percutanée** (sonde d'entraînement).","prio":"P2","sec":"s9"},{"id":"fc-236-72afb2","poly":"cardio","fiche":"236","front":"Stimulation externe transthoracique : place et inconvénient ?","back":"**Secours** en attendant ; **douloureuse**.","prio":"P2","sec":"s9"},{"id":"fc-236-b50ea2","poly":"cardio","fiche":"236","front":"Sonde de stimulation temporaire : complications ?","back":"**Tamponnade**, **thrombose**.","prio":"P3","sec":"s9"},{"id":"fc-236-f61e3b","poly":"cardio","fiche":"236","front":"Atropine et isoprénaline : statut thérapeutique ?","back":"**Traitements d'attente** (régression du trouble ou pose du stimulateur).","prio":"P2","sec":"s9"},{"id":"fc-236-8b6913","poly":"cardio","fiche":"236","front":"Atropine dans l'arrêt cardiaque (item 331) : dose ?","back":"**1 mg** toutes les **3 à 5 min**, jusqu'à **0,04 mg/kg** au total.","prio":"P3","sec":"s9"},{"id":"fc-236-a87a20","poly":"cardio","fiche":"236","front":"Isoprénaline dans l'arrêt cardiaque (item 331) : préparation ?","back":"**5 ampoules à 0,2 mg** dans **250 mL** de G5 %, débit adapté, objectif ≥ 50-60/min.","prio":"P3","sec":"s9"},{"id":"fc-236-12ba3f","poly":"cardio","fiche":"236","front":"Trouble de conduction avec cause réversible : stimulateur ?","back":"**Non** : on traite la cause.","prio":"P1","sec":"s10"},{"id":"fc-236-cd64ae","poly":"cardio","fiche":"236","front":"Trouble de conduction : SCA le plus souvent en cause ?","back":"**Inférieur**.","prio":"P2","sec":"s10"},{"id":"fc-236-b92886","poly":"cardio","fiche":"236","front":"Bradycardie médicamenteuse : conduite ?","back":"**Arrêt** du bradycardisant (bêtabloquant y compris **collyre**, inhibiteur calcique, amiodarone, digitalique).","prio":"P2","sec":"s10"},{"id":"fc-236-9560e7","poly":"cardio","fiche":"236","front":"BAV complet sur IDM : fréquence ?","back":"**2-5 %** des IDM, plus souvent **inférieurs**.","prio":"P2","sec":"s11"},{"id":"fc-236-d8b823","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur : siège et installation ?","back":"**Nodal** (> 90 %), installation **progressive** (souvent BAV 1 puis BAV 2 à QRS fins).","prio":"P1","sec":"s11"},{"id":"fc-236-4e7867","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur : mécanisme ?","back":"**Vagal** s'il est précoce, ou ischémie de l'**artère du NAV**.","prio":"P2","sec":"s11"},{"id":"fc-236-962fbe","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur : évolution et traitement ?","back":"**Régressif** en règle ; répond bien à l'**atropine**.","prio":"P1","sec":"s11"},{"id":"fc-236-2177d8","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur persistant : quand discuter un stimulateur ?","back":"S'il persiste à **J5**.","prio":"P2","sec":"s11"},{"id":"fc-236-d050c4","poly":"cardio","fiche":"236","front":"BAV de l'IDM antérieur : caractéristiques ?","back":"**Infranodal**, **brutal**, souvent précédé d'un **bloc de branche**, nécrose étendue, **mortalité importante**.","prio":"P1","sec":"s11"},{"id":"fc-236-2a0d2e","poly":"cardio","fiche":"236","front":"BAV de l'IDM antérieur : traitement ?","back":"Ne répond pas à l'atropine : **stimulation temporaire**, souvent **stimulateur définitif**.","prio":"P1","sec":"s11"},{"id":"fc-236-2d62a0","poly":"cardio","fiche":"236","front":"Hypertonie vagale du SCA inférieur : traitement ?","back":"**Atropine** + **remplissage par macromolécules**.","prio":"P2","sec":"s11"},{"id":"fc-236-1a1adb","poly":"cardio","fiche":"236","front":"BAV sur infarctus aigu : 2 médicaments contre-indiqués ?","back":"**Isoprénaline** et **bêtabloquants** (en aigu).","prio":"P1","sec":"s11"},{"id":"fc-236-702bfc","poly":"cardio","fiche":"236","front":"BBG apparu à la phase aiguë d'un IDM antérieur : signification ?","back":"Atteinte **infrahissienne** de mauvais pronostic (IC, choc cardiogénique).","prio":"P2","sec":"s11"},{"id":"fc-236-73aaa8","poly":"cardio","fiche":"236","front":"Torsade de pointes sur bradycardie : traitement principal ?","back":"**Accélérer la FC** : isoprénaline et/ou stimulation.","prio":"P1","sec":"s12"},{"id":"fc-236-01bb29","poly":"cardio","fiche":"236","front":"Torsade de pointes : corrections électrolytiques ?","back":"**Hypomagnésémie** et **hypokaliémie**.","prio":"P2","sec":"s12"},{"id":"fc-236-f599bb","poly":"cardio","fiche":"236","front":"Torsade de pointes : médicaments à arrêter ?","back":"Tout médicament **allongeant le QT**.","prio":"P2","sec":"s12"},{"id":"fc-236-2c3127","poly":"cardio","fiche":"236","front":"Sulfate de magnésium dans les torsades (item 331) : dose ?","back":"**2 g en IV directe**.","prio":"P3","sec":"s12"},{"id":"fc-236-7d67e3","poly":"cardio","fiche":"236","front":"BAV : indications du stimulateur définitif ?","back":"**Mobitz 2**, **BAV 3**, **haut degré**, en l'absence de cause curable ou réversible.","prio":"P1","sec":"s13"},{"id":"fc-236-18374c","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : indication du stimulateur ?","back":"**Symptomatique** avec **preuve du lien** bradycardie-symptômes, sans cause réversible.","prio":"P1","sec":"s13"},{"id":"fc-236-97c9f4","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : pauses justifiant un stimulateur même asymptomatiques ?","back":"Pauses **> 6 s**, documentées chez un sujet de **plus de 40 ans**.","prio":"P2","sec":"s13"},{"id":"fc-236-a6e466","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : exception au critère symptomatique ?","back":"**Bradycardisant indispensable** (FA rapide de maladie rythmique, bêtabloquant d'une cardiopathie).","prio":"P3","sec":"s13"},{"id":"fc-236-614564","poly":"cardio","fiche":"236","front":"BAV 2 : quand poser un stimulateur ?","back":"Siège **infrahissien** évoqué, ou **symptomatique** quel que soit le siège.","prio":"P2","sec":"s13"},{"id":"fc-236-d84c4c","poly":"cardio","fiche":"236","front":"Bloc de branche : indications du stimulateur ?","back":"**Syncope + HV ≥ 70 ms** ; **bloc alternant**.","prio":"P2","sec":"s13"},{"id":"fc-236-9a72f4","poly":"cardio","fiche":"236","front":"BBG : quand discuter une resynchronisation ?","back":"**BBG ≥ 130 ms** + insuffisance cardiaque + **FEVG ≤ 35 %**.","prio":"P2","sec":"s13"},{"id":"fc-236-35436f","poly":"cardio","fiche":"236","front":"Stimulateur simple chambre : sonde et mode ?","back":"Sonde dans le **VD**, mode **VVI**.","prio":"P2","sec":"s13"},{"id":"fc-236-a40440","poly":"cardio","fiche":"236","front":"Stimulateur double chambre : sondes et mode ?","back":"**Oreillette droite** + **VD**, mode **DDD**.","prio":"P2","sec":"s13"},{"id":"fc-236-3b2f07","poly":"cardio","fiche":"236","front":"Stimulateur triple chambre : principe et indication ?","back":"Stimule **VD + VG** (sonde via le sinus coronaire) ; stimulation ventriculaire nécessaire avec **dysfonction VG**.","prio":"P2","sec":"s13"},{"id":"fc-236-2a9586","poly":"cardio","fiche":"236","front":"Stimulateur sans sonde : principe ?","back":"Capsule dans le **VD** par voie **veineuse fémorale**.","prio":"P3","sec":"s13"},{"id":"fc-236-3d8931","poly":"cardio","fiche":"236","front":"Pose d'un stimulateur : conditions ?","back":"**Consentement** ; **bloc opératoire**, anesthésie locale, **asepsie rigoureuse** ; voie **subclavière**.","prio":"P2","sec":"s13"},{"id":"fc-236-2da767","poly":"cardio","fiche":"236","front":"Dysfonction sinusale asymptomatique ou bradycardie de cause réversible : faut-il un stimulateur ?","back":"**Non** : ce serait une erreur (hors pauses > 6 s) ; la cause d'abord, le lien symptômes-ECG ensuite.","prio":"P2","sec":"s13"},{"id":"fc-236-d85feb","poly":"cardio","fiche":"236","front":"Bloc de branche + syncope sans BAV documenté : examen ?","back":"**EEP** avec mesure du HV ; si normale → **moniteur cardiaque implantable**.","prio":"P2","sec":"s14"},{"id":"fc-236-a916d8","poly":"cardio","fiche":"236","front":"BBG découvert : notion inacceptable ?","back":"Ne pas rechercher de **cardiopathie sous-jacente**.","prio":"P1","sec":"s14"},{"id":"fc-236-3d7dac","poly":"cardio","fiche":"236","front":"BBG isolé : bilan ?","back":"Recherche d'**HTA** méconnue ou de cardiopathie par **échocardiographie**.","prio":"P2","sec":"s14"},{"id":"fc-236-e36d7e","poly":"cardio","fiche":"236","front":"BBD isolé : bilan ?","back":"Recherche d'une pathologie **pulmonaire** ou du **VD**.","prio":"P2","sec":"s14"},{"id":"fc-236-a266e3","poly":"cardio","fiche":"236","front":"Bloc de branche sans indication de stimulateur : surveillance ?","back":"**Clinique et ECG** (sauf BBD typique sur cœur sain).","prio":"P2","sec":"s14"},{"id":"fc-236-80c059","poly":"cardio","fiche":"236","front":"Après pose d'un stimulateur : contrôles initiaux ?","back":"**Radiographie** (position des sondes) et contrôle au **programmateur**.","prio":"P2","sec":"s15"},{"id":"fc-236-b2e47a","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : rythme des contrôles ?","back":"Premier à **1-3 mois**, puis **annuel** au centre implanteur.","prio":"P2","sec":"s15"},{"id":"fc-236-89f60b","poly":"cardio","fiche":"236","front":"Contrôle de stimulateur : contenu ?","back":"ECG, **télémétrie** (pile, sondes), lecture des mémoires, reprogrammation.","prio":"P3","sec":"s15"},{"id":"fc-236-3fb2b9","poly":"cardio","fiche":"236","front":"Stimulateur : durée de vie du boîtier ?","back":"Changement tous les **8 à 12 ans** environ.","prio":"P2","sec":"s15"},{"id":"fc-236-dd0561","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : IRM possible ?","back":"**Oui** le plus souvent (dispositifs **IRM-conditionnels**) : mode IRM avant, reprogrammation après.","prio":"P2","sec":"s15"},{"id":"fc-236-98eaa7","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : signes devant faire consulter ?","back":"**Rougeur**, **écoulement**, douleur du boîtier, **fièvre inexpliquée** (infection du matériel).","prio":"P2","sec":"s15"},{"id":"fc-236-a9a795","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : documents et informations ?","back":"**Carte** du dispositif ; risque d'**interférences** électromagnétiques.","prio":"P3","sec":"s15"},{"id":"fc-236-c4cad8","poly":"cardio","fiche":"236","front":"Télésurveillance du stimulateur : intérêts ?","back":"Transmissions automatiques, **téléalertes** (dysfonctionnement, événement rythmique), moins de déplacements.","prio":"P3","sec":"s15"},{"id":"fc-237-9f823d","poly":"cardio","fiche":"237","front":"Palpitations : définition ?","back":"Perception **anormale** de battements cardiaques, normaux ou anormaux (trouble **subjectif**).","prio":"P1","sec":"s1"},{"id":"fc-237-42f282","poly":"cardio","fiche":"237","front":"Palpitations : valeur diagnostique du symptôme ?","back":"**Très peu spécifique** : de la tachycardie sinusale réflexe à la **TV**.","prio":"P1","sec":"s1"},{"id":"fc-237-ba950a","poly":"cardio","fiche":"237","front":"Palpitations : 4 buts du bilan ?","back":"**Diagnostic positif**, **étiologie**, **tolérance** et pronostic, risque d'**arythmie maligne** et de **mort subite**.","prio":"P2","sec":"s1"},{"id":"fc-237-7250c2","poly":"cardio","fiche":"237","front":"Palpitations associées à une syncope, douleur thoracique ou dyspnée : priorité ?","back":"Les palpitations **passent au second plan** derrière le symptôme plus grave.","prio":"P2","sec":"s1"},{"id":"fc-237-581d28","poly":"cardio","fiche":"237","front":"Troubles du rythme les plus fréquents donnant des palpitations ?","back":"**FA** et **flutters atriaux**, puis **tachycardies jonctionnelles**.","prio":"P2","sec":"s1"},{"id":"fc-237-c50644","poly":"cardio","fiche":"237","front":"Palpitations : 3 notions indispensables ?","back":"**ECG pendant les symptômes** (corrélation électroclinique) ; recherche d'une **cardiopathie** ; recherche des **signes de gravité**.","prio":"P1","sec":"s1"},{"id":"fc-237-888f39","poly":"cardio","fiche":"237","front":"Palpitations : place de l'interrogatoire ?","back":"**Premier temps**, indispensable ; oriente **le plus souvent** le diagnostic.","prio":"P2","sec":"s2"},{"id":"fc-237-6ba304","poly":"cardio","fiche":"237","front":"Palpitations : caractéristiques à préciser à l'interrogatoire ?","back":"**Durée**, **déclencheur**, **début et fin** (brutaux/progressifs), paroxystique ou permanent, **repos/effort**, **fréquence**, **régularité**.","prio":"P1","sec":"s2"},{"id":"fc-237-1f3e0c","poly":"cardio","fiche":"237","front":"Palpitations : antécédents à rechercher ?","back":"**Cardiopathie** (IDM, HTA, myocardiopathie) et **mort subite familiale** (Brugada, QT long, DAVD).","prio":"P2","sec":"s2"},{"id":"fc-237-1ee604","poly":"cardio","fiche":"237","front":"Palpitations : traitements à rechercher ?","back":"**Antiarythmique** ; médicament qui **allonge le QT**.","prio":"P2","sec":"s2"},{"id":"fc-237-fd9313","poly":"cardio","fiche":"237","front":"Palpitations : astuce pour caractériser le rythme ?","back":"Faire **tapoter du doigt** le rythme sur le bord d'une table.","prio":"P2","sec":"s2"},{"id":"fc-237-15796c","poly":"cardio","fiche":"237","front":"Palpitations : éléments orientant vers une tachycardie jonctionnelle ?","back":"**Début et fin brutaux**, **polyurie** en fin d'accès, démarrage au **changement brusque de position**.","prio":"P1","sec":"s2"},{"id":"fc-237-b860c3","poly":"cardio","fiche":"237","front":"Palpitations : causes extracardiaques à chercher ?","back":"**Excitants** (alcool, tabac, cocaïne, amphétamines), sympathomimétiques, hormones thyroïdiennes, **grossesse**, **hyperthyroïdie**, fièvre, déshydratation, **apnées du sommeil**.","prio":"P2","sec":"s2"},{"id":"fc-237-667b5b","poly":"cardio","fiche":"237","front":"Palpitations : priorité absolue ?","back":"Éliminer une **arythmie ventriculaire potentiellement létale** (TV, FV).","prio":"P1","sec":"s3"},{"id":"fc-237-a05e3c","poly":"cardio","fiche":"237","front":"Palpitations : antécédents personnels alarmants ?","back":"**IDM**, HTA ou cardiopathie, trouble du rythme connu, porteur de **stimulateur** ou **défibrillateur**.","prio":"P2","sec":"s3"},{"id":"fc-237-0f29c3","poly":"cardio","fiche":"237","front":"Mort subite familiale évoquant une arythmie génétique : âge ?","back":"Mort subite **du nourrisson** ou **avant 35 ans**.","prio":"P1","sec":"s3"},{"id":"fc-237-065cf3","poly":"cardio","fiche":"237","front":"Mort subite familiale précoce : arythmies génétiques et conduite ?","back":"**Brugada**, **QT long**, **DAVD** ; dresser l'**arbre généalogique**.","prio":"P2","sec":"s3"},{"id":"fc-237-322ded","poly":"cardio","fiche":"237","front":"Palpitations : signes cliniques de gravité ?","back":"**FC > 150 bpm**, **hypotension**/hypoperfusion, **angor**, **dyspnée**, signes **neurologiques**, trouble de **conscience**, **syncope**/lipothymie.","prio":"P1","sec":"s3"},{"id":"fc-237-f2edcf","poly":"cardio","fiche":"237","front":"Palpitations : signe neurologique de gravité, mécanisme ?","back":"**Infarctus cérébral** par embolie sur **FA**.","prio":"P3","sec":"s3"},{"id":"fc-237-a7dea8","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS larges : diagnostic à retenir ?","back":"**TV jusqu'à preuve du contraire** : se préparer à réanimer.","prio":"P1","sec":"s3"},{"id":"fc-237-02ae03","poly":"cardio","fiche":"237","front":"Tachycardie très rapide avec anomalie de repolarisation : interprétation ?","back":"Urgence (SCA possible), mais **angor fonctionnel** possible, surtout si **FC > 200 bpm**.","prio":"P2","sec":"s3"},{"id":"fc-237-50f37e","poly":"cardio","fiche":"237","front":"Tachycardie à QRS fins > 150 bpm avec signes de gravité : niveau d'urgence ?","back":"**Urgence absolue**.","prio":"P1","sec":"s3"},{"id":"fc-237-852333","poly":"cardio","fiche":"237","front":"Signes de gravité des palpitations : moyen mnémotechnique ?","back":"**THADNCS** : Tachycardie > 150, Hypotension, Angor, Dyspnée, Neurologique, Conscience, Syncope.","prio":"P3","sec":"s3"},{"id":"fc-237-2f2989","poly":"cardio","fiche":"237","front":"Palpitations : ECG de repos, place et résultat habituel ?","back":"**Systématique** ; **le plus souvent normal**.","prio":"P1","sec":"s4"},{"id":"fc-237-679749","poly":"cardio","fiche":"237","front":"ECG de repos : extrasystoles supraventriculaires, que rechercher ?","back":"**FA**, **flutter** ou **tachycardie atriale** focale.","prio":"P2","sec":"s4"},{"id":"fc-237-aab24b","poly":"cardio","fiche":"237","front":"ECG de repos : extrasystole ventriculaire, que rechercher ?","back":"Une **TV**.","prio":"P2","sec":"s4"},{"id":"fc-237-a2dd49","poly":"cardio","fiche":"237","front":"ECG de repos chez un patient à palpitations : anomalies à repérer ?","back":"**Brugada**, ischémie, **préexcitation**, **QT long**, **CMH**, repolarisation précoce.","prio":"P2","sec":"s4"},{"id":"fc-237-d19336","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS fins : hypothèses ?","back":"**Jonctionnelle**, **sinusale**, **flutter** ou **tachycardie atriale**.","prio":"P1","sec":"s4"},{"id":"fc-237-6a168e","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS larges : hypothèses ?","back":"**TV**, ou tachycardie supraventriculaire avec **anomalie de conduction**.","prio":"P2","sec":"s4"},{"id":"fc-237-293b67","poly":"cardio","fiche":"237","front":"Tachycardie irrégulière : hypothèse principale ?","back":"**Fibrillation atriale**.","prio":"P1","sec":"s4"},{"id":"fc-237-18e44b","poly":"cardio","fiche":"237","front":"Manœuvres vagales et adénosine : mécanisme ?","back":"**Blocage transitoire du nœud AV**.","prio":"P2","sec":"s4"},{"id":"fc-237-d16165","poly":"cardio","fiche":"237","front":"Test vagal ou à l'adénosine : intérêt diagnostique ?","back":"Utile **dès que le diagnostic n'est pas évident** : diagnostic précis de la tachycardie dans **la majorité des cas**.","prio":"P2","sec":"s12"},{"id":"fc-237-0bdc8f","poly":"cardio","fiche":"237","front":"Test vagal ou adénosine : arrêt brutal de la tachycardie, diagnostic ?","back":"**Tachycardie jonctionnelle** (réentrée intranodale ou voie accessoire).","prio":"P1","sec":"s4"},{"id":"fc-237-b4aa8f","poly":"cardio","fiche":"237","front":"Test vagal ou adénosine : ralentissement avec activité atriale visible, diagnostic ?","back":"**FA**, **flutter** ou **tachycardie atriale**.","prio":"P1","sec":"s4"},{"id":"fc-237-292589","poly":"cardio","fiche":"237","front":"Test vagal ou adénosine : aucun effet, diagnostic ?","back":"Évoque une **TV** (absence d'effet **en général**) ; une **dissociation AV** en fait le diagnostic de certitude.","prio":"P1","sec":"s4"},{"id":"fc-237-dd0228","poly":"cardio","fiche":"237","front":"Adénosine : contre-indications ?","back":"**Asthme**, **HTA non contrôlée** ; aussi **hypotension artérielle** et **FA sur voie accessoire**.","prio":"P1","sec":"s12"},{"id":"fc-237-c46fa9","poly":"cardio","fiche":"237","front":"Palpitations : 3 principes du diagnostic étiologique ?","back":"Chercher une **cardiopathie** ; sinon une **cause extracardiaque** ; obtenir une **corrélation électroclinique**.","prio":"P2","sec":"s5"},{"id":"fc-237-c1b402","poly":"cardio","fiche":"237","front":"Corrélation électroclinique : définition ?","back":"Concordance entre les **symptômes** et une **anomalie ECG** enregistrée simultanément.","prio":"P1","sec":"s5"},{"id":"fc-237-606bdc","poly":"cardio","fiche":"237","front":"Palpitations : examen d'imagerie systématique ?","back":"**ETT** (FEVG, cinétique, cardiopathie, taille des oreillettes).","prio":"P2","sec":"s5"},{"id":"fc-237-d45351","poly":"cardio","fiche":"237","front":"Palpitations : biologie de routine ?","back":"Notamment **ionogramme**, **NFS**, **alcoolémie**, **β-hCG**, **TSH** (ou selon le contexte).","prio":"P2","sec":"s5"},{"id":"fc-237-809c77","poly":"cardio","fiche":"237","front":"Palpitations : examens complémentaires selon le contexte ?","back":"**IRM**, **épreuve d'effort** (palpitations d'effort), **coronarographie** (doute ischémique).","prio":"P3","sec":"s5"},{"id":"fc-237-4a6275","poly":"cardio","fiche":"237","front":"Enregistrement ECG : lien entre durée et sensibilité ?","back":"Plus l'enregistrement est **long**, meilleure est la **sensibilité**.","prio":"P2","sec":"s5"},{"id":"fc-237-b1ca7b","poly":"cardio","fiche":"237","front":"Palpitations fréquentes : enregistrement adapté ?","back":"**Holter ECG 24 à 96 h**.","prio":"P1","sec":"s5"},{"id":"fc-237-baac1f","poly":"cardio","fiche":"237","front":"Palpitations peu fréquentes (< 1/semaine) : enregistrement externe adapté ?","back":"**ECG ambulatoire de longue durée**, jusqu'à **21 jours**.","prio":"P1","sec":"s5"},{"id":"fc-237-d0a3f1","poly":"cardio","fiche":"237","front":"Holter implantable : durée et position ?","back":"Surveillance de **3 à 5 ans** ; position **parasternale sous-cutanée**.","prio":"P2","sec":"s5"},{"id":"fc-237-d42308","poly":"cardio","fiche":"237","front":"Holter implantable : ce qu'il enregistre et suivi ?","back":"Asystolies, bradycardies, tachycardies ; suivi par **télécardiologie**.","prio":"P3","sec":"s5"},{"id":"fc-237-532d3f","poly":"cardio","fiche":"237","front":"Holter implantable : indication ?","back":"Crises **peu fréquentes** (surveillance de 3 à 5 ans).","prio":"P2","sec":"s5"},{"id":"fc-237-fc98ed","poly":"cardio","fiche":"237","front":"Montre connectée : type de tracé et intérêt ?","back":"Tracé **D1** (automatique ou déclenché) ; permet la **corrélation électroclinique**.","prio":"P2","sec":"s5"},{"id":"fc-237-a73bad","poly":"cardio","fiche":"237","front":"Étude électrophysiologique : intérêts diagnostiques ?","back":"**Dualité nodale**, **voie accessoire**, déclenchement d'arythmies (stimulation atriale ou ventriculaire en 2 sites).","prio":"P3","sec":"s5"},{"id":"fc-237-279aa5","poly":"cardio","fiche":"237","front":"Étude électrophysiologique : intérêt thérapeutique ?","back":"Traiter dans le même temps une arythmie atriale, une **réentrée intranodale**, une **voie accessoire**.","prio":"P3","sec":"s5"},{"id":"fc-237-0b3af4","poly":"cardio","fiche":"237","front":"Palpitations : tests pharmacologiques spécialisés cités ?","back":"**Isoprénaline**, **ajmaline**.","prio":"P3","sec":"s5"},{"id":"fc-237-fd3cb7","poly":"cardio","fiche":"237","front":"ECG de repos normal chez un patient à palpitations : rassurant ?","back":"**Non** : il faut un tracé **pendant** les palpitations.","prio":"P1","sec":"s5"},{"id":"fc-237-776bfd","poly":"cardio","fiche":"237","front":"Extrasystole : définition ?","back":"**Activation ectopique prématurée**, supraventriculaire ou ventriculaire.","prio":"P1","sec":"s6"},{"id":"fc-237-2bb649","poly":"cardio","fiche":"237","front":"Extrasystole : repos compensateur vs interpolée ?","back":"**Repos compensateur** : total = double période ; **interpolée** : pas de repos compensateur.","prio":"P2","sec":"s6"},{"id":"fc-237-919f61","poly":"cardio","fiche":"237","front":"Extrasystoles bigéminées et trigéminées : définitions ?","back":"**Bigéminées** : 1 normal / 1 ES en alternance ; **trigéminées** : 2 normaux puis 1 ES.","prio":"P2","sec":"s6"},{"id":"fc-237-b32e58","poly":"cardio","fiche":"237","front":"Extrasystoles monomorphes vs polymorphes : définitions ?","back":"**Monomorphes** : toutes identiques ; **polymorphes** : plusieurs morphologies.","prio":"P3","sec":"s6"},{"id":"fc-237-1b5747","poly":"cardio","fiche":"237","front":"Extrasystole supraventriculaire : aspect ECG ?","back":"Onde **P'** différente de la P sinusale, QRS habituellement **identique** au QRS sinusal.","prio":"P2","sec":"s6"},{"id":"fc-237-49aabb","poly":"cardio","fiche":"237","front":"Extrasystole atriale bloquée : piège clinique ?","back":"Fausse « **bradycardie au pouls** » (ex. trigéminisme atrial bloqué).","prio":"P2","sec":"s6"},{"id":"fc-237-3650f4","poly":"cardio","fiche":"237","front":"Extrasystole ventriculaire : aspect ECG ?","back":"**QRS prématuré, élargi**, sans activité atriale avant lui.","prio":"P1","sec":"s6"},{"id":"fc-237-cc244b","poly":"cardio","fiche":"237","front":"ESV à couplage court : risque ?","back":"**Phénomène R/T** : **peut déclencher** des arythmies ventriculaires **létales** (indicateur majeur de risque).","prio":"P1","sec":"s6"},{"id":"fc-237-e4dc0a","poly":"cardio","fiche":"237","front":"ESV bénignes : exemple cité ?","back":"ESV **infundibulaires ventriculaires droites**.","prio":"P3","sec":"s6"},{"id":"fc-237-5dcde4","poly":"cardio","fiche":"237","front":"Extrasystoles : sont-elles pathologiques en elles-mêmes ?","back":"**Non**, mais imposent de chercher une **cardiopathie** ou une **cause extracardiaque**.","prio":"P1","sec":"s6"},{"id":"fc-237-0d4ba0","poly":"cardio","fiche":"237","front":"Extrasystoles : causes extracardiaques ?","back":"Alcoolisation, électrocution, maladies respiratoires, **hyperthyroïdie**, troubles électrolytiques, anxiété ou dépression, **grossesse**, **apnées du sommeil**.","prio":"P2","sec":"s6"},{"id":"fc-237-bd04c2","poly":"cardio","fiche":"237","front":"Extrasystoles : bilan de base ?","back":"ECG, **ETT**, **épreuve d'effort**, **holter** (charge, morphologies, couplage).","prio":"P2","sec":"s6"},{"id":"fc-237-9b28b8","poly":"cardio","fiche":"237","front":"Extrasystoles chez un obèse, diabétique ou hypertendu : surveillance ?","back":"**Répéter les holters** pour dépister une **FA** à risque thromboembolique.","prio":"P1","sec":"s6"},{"id":"fc-237-ee3224","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : définition ?","back":"Fréquence sinusale de repos **> 100 bpm**.","prio":"P1","sec":"s7"},{"id":"fc-237-875f31","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : mode de début et de fin ?","back":"**Progressifs**.","prio":"P1","sec":"s7"},{"id":"fc-237-52ece4","poly":"cardio","fiche":"237","front":"Tachycardie sinusale adaptée : causes cardiaques ou cardiopulmonaires ?","back":"**Insuffisance cardiaque**, **embolie pulmonaire**, **épanchement péricardique**.","prio":"P2","sec":"s7"},{"id":"fc-237-f6befa","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : causes extracardiaques ?","back":"Fièvre, hypoxie, anémie, hypovolémie, hypotension, **hyperthyroïdie**, **grossesse**, **apnées du sommeil**, alcool.","prio":"P2","sec":"s7"},{"id":"fc-237-72c09e","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : 4 causes à retenir ?","back":"**Grossesse**, **hyperthyroïdie**, **apnées du sommeil**, **alcoolisme**.","prio":"P1","sec":"s7"},{"id":"fc-237-2ccb81","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : causes médicamenteuses ?","back":"Sympathomimétiques, vasodilatateurs, atropiniques ; **sevrage brutal en bêtabloquants**.","prio":"P2","sec":"s7"},{"id":"fc-237-9b99ad","poly":"cardio","fiche":"237","front":"Tachycardie sinusale inappropriée : définition ?","back":"Forme **non adaptative**, exceptionnelle, isolée (orthostatisme, anxiété).","prio":"P2","sec":"s7"},{"id":"fc-237-42f6df","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : traitement ?","back":"**Traiter la cause** : nécessaire et le plus souvent **suffisant**.","prio":"P1","sec":"s7"},{"id":"fc-237-8b70e6","poly":"cardio","fiche":"237","front":"Tachycardies jonctionnelles : définition ?","back":"Tachycardies incluant la **jonction AV** : **réentrée intranodale** et **voies accessoires** (maladie de Bouveret).","prio":"P2","sec":"s8"},{"id":"fc-237-7bb3a6","poly":"cardio","fiche":"237","front":"Réentrée intranodale : terrain ?","back":"**Adolescent ou adulte jeune à cœur sain** ; tachycardie jonctionnelle la plus fréquente.","prio":"P1","sec":"s8"},{"id":"fc-237-76eea9","poly":"cardio","fiche":"237","front":"Réentrée intranodale : tableau clinique ?","back":"Début et fin **brutaux**, minutes à heures, **polyurie** en fin d'accès, parfois battements dans le cou, **bien tolérée le plus souvent**.","prio":"P1","sec":"s8"},{"id":"fc-237-c89092","poly":"cardio","fiche":"237","front":"Réentrée intranodale : comment arrêter la crise ?","back":"**Manœuvre vagale** ou **adénosine** (ou ATP).","prio":"P2","sec":"s8"},{"id":"fc-237-2872fe","poly":"cardio","fiche":"237","front":"Réentrée intranodale : 2 voies nodales et leurs périodes réfractaires ?","back":"**Voie rapide** : période réfractaire **longue** ; **voie lente** : période réfractaire **plus courte**.","prio":"P2","sec":"s8"},{"id":"fc-237-9a7b9c","poly":"cardio","fiche":"237","front":"Réentrée intranodale : mécanisme de déclenchement ?","back":"Souvent une ES atriale bloquée dans la voie rapide → descend par la **voie lente** → remonte par la voie rapide.","prio":"P3","sec":"s8"},{"id":"fc-237-067a1d","poly":"cardio","fiche":"237","front":"Réentrée intranodale en crise : aspect ECG ?","back":"Tachycardie régulière **130 à 250 bpm**, **QRS fins** le plus souvent, **P' rétrogrades négatives en inférieur**.","prio":"P1","sec":"s8"},{"id":"fc-237-7aa3b1","poly":"cardio","fiche":"237","front":"Réentrée intranodale : ECG de repos ?","back":"**Le plus souvent normal**.","prio":"P2","sec":"s8"},{"id":"fc-237-05df63","poly":"cardio","fiche":"237","front":"Réentrée intranodale : comment confirmer l'activité atriale rétrograde ?","back":"La **négativité inférieure disparaît** sur les complexes sinusaux après la crise.","prio":"P3","sec":"s8"},{"id":"fc-237-073f61","poly":"cardio","fiche":"237","front":"Voie accessoire : définition ?","back":"**Bandelette musculaire** (ex. faisceau de **Kent**) reliant directement oreillette et ventricule.","prio":"P2","sec":"s9"},{"id":"fc-237-105dea","poly":"cardio","fiche":"237","front":"Préexcitation : mécanisme ?","back":"Activation ventriculaire en **fusion** : d'abord par la voie accessoire, puis par le nœud AV.","prio":"P2","sec":"s9"},{"id":"fc-237-2634f2","poly":"cardio","fiche":"237","front":"Wolff-Parkinson-White : signes ECG de repos ?","back":"**PR < 120 ms**, **onde delta**, **QRS > 120 ms**, troubles de **repolarisation**.","prio":"P2","sec":"s9"},{"id":"fc-237-0b3a64","poly":"cardio","fiche":"237","front":"Préexcitation : effet de l'atropine et des manœuvres vagales ?","back":"**Diminue** sous atropine ; **augmente** avec les manœuvres vagales.","prio":"P3","sec":"s9"},{"id":"fc-237-9a0cb9","poly":"cardio","fiche":"237","front":"Voie accessoire : évolution avec l'âge et terrain ?","back":"**Involue** habituellement avec l'âge ; **jeunes à cœur sain**.","prio":"P3","sec":"s9"},{"id":"fc-237-8429e7","poly":"cardio","fiche":"237","front":"Tachycardie orthodromique : circuit et QRS ?","back":"Descente par le **His**, remontée par la voie accessoire : **QRS fins**.","prio":"P2","sec":"s9"},{"id":"fc-237-68da80","poly":"cardio","fiche":"237","front":"Tachycardie antidromique : circuit et QRS ?","back":"Descente par la **voie accessoire**, remontée par le His : **QRS larges** préexcités.","prio":"P2","sec":"s9"},{"id":"fc-237-4f012a","poly":"cardio","fiche":"237","front":"Wolff-Parkinson-White : principal danger ?","back":"**FA** conduite très vite (**super-Wolff**) → **FV**, mort subite.","prio":"P1","sec":"s9"},{"id":"fc-237-8368e8","poly":"cardio","fiche":"237","front":"Wolff-Parkinson-White : traitement réduisant le risque de mort subite ?","back":"**Ablation de la voie accessoire**.","prio":"P2","sec":"s9"},{"id":"fc-237-e413ef","poly":"cardio","fiche":"237","front":"Tachycardie sinusale vs réentrée intranodale : différences ?","back":"Sinusale : début/fin **progressifs**, P sinusales ; TRIN : **brutaux**, polyurie, **P' rétrogrades**, arrêt par vagal.","prio":"P1","sec":"s10"},{"id":"fc-237-537aa4","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS larges : piège ?","back":"La prendre pour une tachycardie avec **simple bloc de branche** alors que c'est une **TV**.","prio":"P1","sec":"s10"},{"id":"fc-237-d5f172","poly":"cardio","fiche":"237","front":"Tachycardie irrégulière à QRS très larges : quoi évoquer ?","back":"**FA sur voie accessoire** (super-Wolff) : risque de FV.","prio":"P2","sec":"s10"},{"id":"fc-237-5cd59f","poly":"cardio","fiche":"237","front":"Névrose cardiaque : définition ?","back":"Diagnostic d'**élimination** : **crainte irraisonnée de mort subite**.","prio":"P2","sec":"s10"},{"id":"fc-237-1d8ecf","poly":"cardio","fiche":"237","front":"Névrose cardiaque : critère diagnostique ?","back":"**ECG strictement normal pendant les palpitations** (monitorage prolongé).","prio":"P2","sec":"s10"},{"id":"fc-237-48f5b4","poly":"cardio","fiche":"237","front":"Névrose cardiaque : quand l'évoquer ?","back":"Examens **tous normaux**, aucune pathologie extracardiaque, signes d'**anxiété** ou de **dépression**.","prio":"P2","sec":"s10"},{"id":"fc-237-87a994","poly":"cardio","fiche":"237","front":"Palpitations : notion inacceptable sur la cause psychogène ?","back":"S'orienter **d'emblée** vers une cause psychogène **sans bilan minimal**.","prio":"P1","sec":"s10"},{"id":"fc-237-89510d","poly":"cardio","fiche":"237","front":"Tachycardie régulière mal tolérée (QRS fins ou larges) : traitement ?","back":"**Cardioversion par choc électrique externe**.","prio":"P1","sec":"s11"},{"id":"fc-237-59a119","poly":"cardio","fiche":"237","front":"Arrêt cardiaque sur TV/FV : traitement initial ?","back":"**Défibrillation** par choc électrique externe.","prio":"P1","sec":"s11"},{"id":"fc-237-9e8922","poly":"cardio","fiche":"237","front":"Arrêt cardiaque sur TV/FV après échec de 2 chocs : médicaments ?","back":"**Adrénaline IV** + **amiodarone 300 mg**.","prio":"P1","sec":"s11"},{"id":"fc-237-491b61","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : délai idéal du premier choc ?","back":"Dans les **3 minutes**.","prio":"P2","sec":"s11"},{"id":"fc-237-c65d7d","poly":"cardio","fiche":"237","front":"Défibrillation : énergie ?","back":"Jusqu'à **200 J** (biphasique) ; **360 J** (monophasique).","prio":"P3","sec":"s11"},{"id":"fc-237-77c04f","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : posologie de l'adrénaline ?","back":"**1 mg toutes les 4 minutes**, IV ou endotrachéale.","prio":"P2","sec":"s11"},{"id":"fc-237-bdadd4","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : modalités de l'amiodarone ?","back":"300 mg dilués, juste avant le **3e choc** ; puis **150 mg** si TV/FV réfractaire ou récidivante.","prio":"P3","sec":"s11"},{"id":"fc-237-3d0a1a","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : alternative à l'amiodarone ?","back":"**Lidocaïne 1,5 mg/kg** IV lente (max 3 mg/kg), si amiodarone indisponible.","prio":"P3","sec":"s11"},{"id":"fc-237-2d657b","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : indication du sulfate de magnésium ?","back":"**Torsades de pointes** ou suspicion d'**hypomagnésémie** : **2 g** IV directe.","prio":"P3","sec":"s11"},{"id":"fc-237-3514e8","poly":"cardio","fiche":"237","front":"TV : effet des manœuvres vagales et de l'adénosine ?","back":"**Généralement aucun** sur la fréquence ventriculaire : ne la traitent pas.","prio":"P2","sec":"s11"},{"id":"fc-237-67dbfd","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS fins bien tolérée : conduite ?","back":"**Enregistrer l'ECG en crise**, puis **manœuvres vagales**, puis **adénosine** si échec.","prio":"P1","sec":"s12"},{"id":"fc-237-bf6825","poly":"cardio","fiche":"237","front":"Manœuvres vagales : lesquelles ?","back":"**Valsalva**, compression d'**une seule** carotide, grand verre d'**eau froide**.","prio":"P2","sec":"s12"},{"id":"fc-237-7503df","poly":"cardio","fiche":"237","front":"Compression carotidienne : contre-indications ?","back":"**Athérome important** ou **souffle carotidien**.","prio":"P2","sec":"s12"},{"id":"fc-237-0284d1","poly":"cardio","fiche":"237","front":"Compression oculaire bilatérale : encore recommandée ?","back":"**Non** (décollement de rétine chez le myope).","prio":"P3","sec":"s12"},{"id":"fc-237-efce88","poly":"cardio","fiche":"237","front":"Adénosine : mode d'administration et durée d'effet ?","back":"**IV en flash** ; effet d'une **dizaine de secondes**.","prio":"P2","sec":"s12"},{"id":"fc-237-e5bb82","poly":"cardio","fiche":"237","front":"Adénosine : effet indésirable rare ?","back":"**Bronchospasme** intense et transitoire, même chez un non-asthmatique.","prio":"P3","sec":"s12"},{"id":"fc-237-b55c59","poly":"cardio","fiche":"237","front":"Réentrée intranodale : traitement de référence au long cours ?","back":"**Ablation de la voie lente**.","prio":"P1","sec":"s13"},{"id":"fc-237-08cfa3","poly":"cardio","fiche":"237","front":"Ablation de la voie lente : complication à connaître ?","back":"**BAV complet** (risque très faible).","prio":"P1","sec":"s13"},{"id":"fc-237-877107","poly":"cardio","fiche":"237","front":"Réentrée intranodale : options au long cours selon la gêne ?","back":"**Abstention**, « **pill in the pocket** », **ablation**.","prio":"P2","sec":"s13"},{"id":"fc-237-b48763","poly":"cardio","fiche":"237","front":"Tachycardie jonctionnelle sur voie accessoire : réduction ?","back":"**Manœuvres vagales** ou **adénosine IV** ; la préexcitation réapparaît après.","prio":"P2","sec":"s14"},{"id":"fc-237-b89da2","poly":"cardio","fiche":"237","front":"FA sur voie accessoire : adénosine ?","back":"**Contre-indiquée**.","prio":"P2","sec":"s14"},{"id":"fc-237-a9a24d","poly":"cardio","fiche":"237","front":"Après ablation d'une voie accessoire : aspect ECG ?","back":"La **préexcitation disparaît**.","prio":"P3","sec":"s14"},{"id":"fc-237-9f716d","poly":"cardio","fiche":"237","front":"Névrose cardiaque : conduite ?","back":"**Arrêter les explorations**, **rassurer**, éviter un vocabulaire inadapté (« spasmophilie ») ; **avis psychiatrique** souhaitable.","prio":"P2","sec":"s15"},{"id":"fc-237-459e1f","poly":"cardio","fiche":"237","front":"Extrasystoles : traitement propre précisé par le Collège ?","back":"**Aucun** : rechercher la cardiopathie ou la cause extracardiaque.","prio":"P2","sec":"s15"},{"id":"fc-238-dbe4ee","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quelles sont les deux grandes familles ?","back":"Souffle **organique** (anomalie anatomique du cœur) · souffle **anorganique** = fonctionnel = **innocent** (cœur sain).","prio":"P1","sec":"s1"},{"id":"fc-238-5b75e2","poly":"cardio","fiche":"238","front":"Souffle innocent : pourquoi l'entend-on chez l'enfant et pas chez l'adulte ?","back":"Cœur **plus près du stéthoscope** + cavités **plus petites** ; il disparaît à l'âge adulte (persiste parfois chez le jeune adulte).","prio":"P2","sec":"s1"},{"id":"fc-238-d1ccdf","poly":"cardio","fiche":"238","front":"Souffle innocent avant 3 mois : quel mécanisme possible ?","back":"Accélération du flux dans les **branches pulmonaires**, de calibre différent du tronc à cet âge.","prio":"P3","sec":"s1"},{"id":"fc-238-19305d","poly":"cardio","fiche":"238","front":"Malformations cardiaques congénitales : quelle fréquence à la naissance ?","back":"**1 %** des enfants.","prio":"P1","sec":"s1"},{"id":"fc-238-9f6ffe","poly":"cardio","fiche":"238","front":"Souffle chez le nourrisson : quelle proportion est organique ?","back":"**90 %**.","prio":"P1","sec":"s1"},{"id":"fc-238-89e27b","poly":"cardio","fiche":"238","front":"Souffle chez l'enfant d'âge scolaire : quelle proportion est fonctionnelle ?","back":"**Plus des trois quarts**.","prio":"P1","sec":"s1"},{"id":"fc-238-106e24","poly":"cardio","fiche":"238","front":"Souffle fonctionnel : quelle proportion des enfants d'âge scolaire en ont un à un moment de l'enfance ?","back":"**Un tiers à la moitié**.","prio":"P2","sec":"s1"},{"id":"fc-238-d2464c","poly":"cardio","fiche":"238","front":"Souffles innocents : à quel âge se voient-ils surtout ?","back":"À l'**âge scolaire** ; **rarement** chez le nourrisson et le nouveau-né.","prio":"P2","sec":"s1"},{"id":"fc-238-ad21b4","poly":"cardio","fiche":"238","front":"Souffle systolique asymptomatique découvert dans la 2e enfance : quelle origine le plus souvent ?","back":"Le plus souvent **innocent**.","prio":"P2","sec":"s1"},{"id":"fc-238-35db94","poly":"cardio","fiche":"238","front":"Pays occidentaux : quelle est presque toujours la cause d'une cardiopathie organique de l'enfant ?","back":"Une **malformation congénitale** (plus quelques rares cardiomyopathies hypertrophiques ou dilatées).","prio":"P1","sec":"s1"},{"id":"fc-238-a8efa6","poly":"cardio","fiche":"238","front":"Cardiopathie acquise de l'enfant en Occident : quelle fréquence ?","back":"**Exceptionnelle** : les valvulopathies rhumatismales y ont totalement disparu.","prio":"P3","sec":"s1"},{"id":"fc-238-de22ce","poly":"cardio","fiche":"238","front":"Cardiomyopathie ou myocardite comme cause de souffle de l'enfant : quelle fréquence ?","back":"**Rare**.","prio":"P3","sec":"s1"},{"id":"fc-238-623f85","poly":"cardio","fiche":"238","front":"« Souffle au cœur » de l'enfant : pourquoi ne jamais le banaliser d'emblée ?","back":"Le plus souvent innocent, mais il peut être le **seul signe d'appel** d'une cardiopathie congénitale (et source d'anxiété majeure pour les parents).","prio":"P2","sec":"s1"},{"id":"fc-238-6a2208","poly":"cardio","fiche":"238","front":"Auscultation de l'enfant : pourquoi est-elle souvent difficile ?","back":"**Cœur rapide** ; **cris, pleurs, agitation** → distraire l'enfant (jouets, sucette), **stéthoscope pédiatrique**.","prio":"P2","sec":"s2"},{"id":"fc-238-3fc813","poly":"cardio","fiche":"238","front":"Rythme irrégulier chez l'enfant : quelle cause physiologique, et que faire au moindre doute ?","back":"**Arythmie sinusale respiratoire** (parfois très marquée) ; au moindre doute → **ECG**.","prio":"P2","sec":"s2"},{"id":"fc-238-fd9843","poly":"cardio","fiche":"238","front":"Auscultation de l'enfant : quels foyers ajouter aux 4 foyers classiques ?","back":"Région **sous-claviculaire gauche** + **fontanelle antérieure** chez le nourrisson.","prio":"P1","sec":"s2"},{"id":"fc-238-310338","poly":"cardio","fiche":"238","front":"Enfant : que signifie un DB2 au bord sternal gauche variable avec la respiration ?","back":"Fréquent et **physiologique**.","prio":"P1","sec":"s2"},{"id":"fc-238-770fb6","poly":"cardio","fiche":"238","front":"Enfant : quelles causes évoquer devant un DB2 large et fixe ?","back":"**Communication interatriale** ou **bloc de branche droit** (anormal).","prio":"P1","sec":"s2"},{"id":"fc-238-3ee1d7","poly":"cardio","fiche":"238","front":"Enfant : que peut traduire un éclat de B2 au bord sternal gauche ?","back":"Une **HTAP** (pression pulmonaire anormalement élevée).","prio":"P1","sec":"s2"},{"id":"fc-238-f6fe99","poly":"cardio","fiche":"238","front":"Enfant : B3 à l'apex, quelle signification ?","back":"Fréquent (**50 %** des cas) et **physiologique**.","prio":"P1","sec":"s2"},{"id":"fc-238-9de1f7","poly":"cardio","fiche":"238","front":"Enfant : clic mésosystolique apexien, quel diagnostic ?","back":"**Prolapsus mitral**.","prio":"P2","sec":"s2"},{"id":"fc-238-790ed7","poly":"cardio","fiche":"238","front":"Enfant : clic protosystolique, que traduit-il ?","back":"Bruit anormal d'ouverture valvulaire : **sténose valvulaire** aortique ou pulmonaire.","prio":"P1","sec":"s2"},{"id":"fc-238-d0ceb3","poly":"cardio","fiche":"238","front":"Enfant : galop avec B3 associé au souffle, quelle conduite ?","back":"**Anormal** → avis spécialisé.","prio":"P2","sec":"s2"},{"id":"fc-238-6c070e","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : l'intensité est-elle corrélée à la gravité ?","back":"**Généralement non** : cardiopathie grave possible **sans souffle** ; **petite CIV** (mineure) = souffle **intense**.","prio":"P1","sec":"s2"},{"id":"fc-238-30e459","poly":"cardio","fiche":"238","front":"Nouveau-né, nourrisson : quels symptômes font suspecter une cardiopathie ?","back":"**Cyanose** et/ou **insuffisance cardiaque**.","prio":"P1","sec":"s3"},{"id":"fc-238-b1e307","poly":"cardio","fiche":"238","front":"Cyanose du nouveau-né : quelles causes non hypoxiques évoquer ?","back":"**Hypothermie** ou **hypoglycémie**.","prio":"P1","sec":"s3"},{"id":"fc-238-fdf279","poly":"cardio","fiche":"238","front":"Cyanose : quel examen affirme l'hypoxie ?","back":"La **saturation cutanée en O₂** (réfractaire à l'O₂ si cardiaque).","prio":"P1","sec":"s3"},{"id":"fc-238-928a12","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque du nourrisson : quelles 3 manifestations ?","back":"**Difficultés alimentaires** ; **retard staturopondéral** ; **signes respiratoires** (polypnée, tirage, toux).","prio":"P1","sec":"s3"},{"id":"fc-238-3f2d59","poly":"cardio","fiche":"238","front":"Enfant plus grand : quels symptômes font suspecter une cardiopathie ?","back":"**Infections respiratoires à répétition**, **dyspnée d'effort**, **fatigabilité** (+ mêmes symptômes que le nourrisson, plus rarement).","prio":"P2","sec":"s3"},{"id":"fc-238-68155b","poly":"cardio","fiche":"238","front":"Enfant plus grand : syncope ou douleur thoracique d'effort, quelle cause cardiaque évoquer ?","back":"**Obstacle à l'éjection du VG** : sténose aortique, cardiomyopathie obstructive (symptômes **rares**).","prio":"P2","sec":"s3"},{"id":"fc-238-83f482","poly":"cardio","fiche":"238","front":"Enfant plus grand : quels signes généraux peuvent révéler une cardiopathie ?","back":"Parfois altération de l'état général : **anorexie**, **asthénie**, **douleurs abdominales**.","prio":"P3","sec":"s3"},{"id":"fc-238-418465","poly":"cardio","fiche":"238","front":"Enfant sans symptôme : quel signe d'examen révèle le plus souvent une cardiopathie ?","back":"Un **souffle** (à n'importe quel âge) ou une **anomalie des bruits du cœur**.","prio":"P2","sec":"s3"},{"id":"fc-238-8ec4a1","poly":"cardio","fiche":"238","front":"Nourrisson, enfant : quel est le signe d'insuffisance cardiaque le plus pertinent ?","back":"L'**hépatomégalie**.","prio":"P1","sec":"s3"},{"id":"fc-238-a42f06","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque de l'enfant : que dire des œdèmes des membres inférieurs ?","back":"**Exceptionnels**.","prio":"P1","sec":"s3"},{"id":"fc-238-32cded","poly":"cardio","fiche":"238","front":"Enfant : pouls absent, surtout fémoral, quel diagnostic évoquer d'emblée ?","back":"**Coarctation aortique**.","prio":"P1","sec":"s3"},{"id":"fc-238-784a3f","poly":"cardio","fiche":"238","front":"Quels signes extracardiaques peuvent révéler une cardiopathie de l'enfant ?","back":"**AVC** ; **fièvre au long cours** ; **cassure de la courbe de croissance pondérale**.","prio":"P2","sec":"s3"},{"id":"fc-238-d91d7e","poly":"cardio","fiche":"238","front":"Syndrome polymalformatif : quel examen cardiaque, et dans quels cas ?","back":"**Échocardiographie systématique** au bilan, avec ou sans symptôme, avec ou sans souffle.","prio":"P1","sec":"s3"},{"id":"fc-238-0e02fa","poly":"cardio","fiche":"238","front":"Quels contextes imposent le cardiopédiatre même sans souffle ?","back":"**Syndrome polymalformatif** ; **maladie génétique familiale** touchant cœur/gros vaisseaux (ex. Marfan) ; **cardiopathie congénitale** chez un apparenté du 1er degré.","prio":"P1","sec":"s3"},{"id":"fc-238-d26270","poly":"cardio","fiche":"238","front":"Cardiopédiatre : quels examens pratique-t-il pour poser le diagnostic ?","back":"**Échocardiographie-doppler**, souvent avec un **ECG** ; diagnostic le plus souvent posé d'emblée.","prio":"P2","sec":"s3"},{"id":"fc-238-c15498","poly":"cardio","fiche":"238","front":"Citer les syndromes le plus souvent associés aux cardiopathies congénitales ?","back":"**Trisomie 21**, **DiGeorge**, **Turner**, **Williams-Beuren**, **Noonan**, **CHARGE**, **Marfan** (« Tata dit toujours : Willy ne charge mal »).","prio":"P2","sec":"s3"},{"id":"fc-238-6b4409","poly":"cardio","fiche":"238","front":"Syndrome de DiGeorge : quelle anomalie génétique ?","back":"Microdélétion **22q11**.","prio":"P2","sec":"s3"},{"id":"fc-238-28119f","poly":"cardio","fiche":"238","front":"Syndrome de Turner : quel caryotype ?","back":"**45,X0**.","prio":"P2","sec":"s3"},{"id":"fc-238-93a44c","poly":"cardio","fiche":"238","front":"Syndrome de Williams-Beuren : quelle anomalie génétique ?","back":"Microdélétion du **chromosome 7**.","prio":"P2","sec":"s3"},{"id":"fc-238-4d1ed8","poly":"cardio","fiche":"238","front":"Syndrome CHARGE : que regroupe-t-il ?","back":"**Colobome**, **cardiopathie**, **atrésie des choanes**, **retard** de croissance et de développement, **hypoplasie génitale**, anomalies de l'**oreille** ou surdité.","prio":"P3","sec":"s3"},{"id":"fc-238-85b71a","poly":"cardio","fiche":"238","front":"Trisomie 21 : quelle cardiopathie est citée ?","back":"Le **canal atrioventriculaire**.","prio":"P2","sec":"s3"},{"id":"fc-238-b80a7d","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : les signes fonctionnels sont-ils habituellement présents ?","back":"**Souvent absents** : découverte **fortuite** lors d'un examen systématique.","prio":"P2","sec":"s4"},{"id":"fc-238-c0e360","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quel signe fonctionnel est le plus fréquent ?","back":"La **dyspnée d'effort**.","prio":"P2","sec":"s4"},{"id":"fc-238-75e923","poly":"cardio","fiche":"238","front":"Malaises de l'enfant : sont-ils souvent cardiaques ?","back":"**Assez rarement** : spasmes du sanglot (petit nourrisson), malaises vagaux (grand enfant, adolescent).","prio":"P2","sec":"s4"},{"id":"fc-238-127815","poly":"cardio","fiche":"238","front":"Syncopes du BAV congénital ou des canalopathies : par quels examens les diagnostiquer ?","back":"**ECG** et **holter**.","prio":"P2","sec":"s4"},{"id":"fc-238-6eef2d","poly":"cardio","fiche":"238","front":"Citer des canalopathies pouvant donner des syncopes chez l'enfant ?","back":"**QT long congénital**, **Brugada**…","prio":"P3","sec":"s4"},{"id":"fc-238-25d859","poly":"cardio","fiche":"238","front":"Douleurs thoraciques de l'enfant : sont-elles souvent cardiaques ?","back":"Fréquentes mais **exceptionnellement cardiaques** (à l'inverse de l'adulte).","prio":"P2","sec":"s4"},{"id":"fc-238-d35efa","poly":"cardio","fiche":"238","front":"Décrire un souffle de l'enfant : quels caractères analyser ?","back":"**T**emps, **D**urée, **I**ntensité, **F**rémissement, **T**opographie, **I**rradiations, **V**ariabilité (+ bruits du cœur associés).","prio":"P1","sec":"s4"},{"id":"fc-238-f5f9b4","poly":"cardio","fiche":"238","front":"Souffle systolique : quelles durées possibles ?","back":"**Proto-**, **méso-**, **télé-** ou **holosystolique**.","prio":"P2","sec":"s4"},{"id":"fc-238-26eec6","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quelles irradiations rechercher ?","back":"Dans le **dos** ; en **écharpe** de la base vers l'apex ; en **rayon de roue** sur tout le précordium.","prio":"P2","sec":"s4"},{"id":"fc-238-d26749","poly":"cardio","fiche":"238","front":"Variabilité d'un souffle : avec quelles manœuvres la rechercher ?","back":"**Respiration**, **position** (couché, assis, debout), **compression** d'une carotide ou d'une jugulaire (point très important).","prio":"P1","sec":"s4"},{"id":"fc-238-d85b1c","poly":"cardio","fiche":"238","front":"Cotation d'intensité : que signifie 2/6 ?","back":"**Faible**, mais entendu **tout de suite**.","prio":"P2","sec":"s4"},{"id":"fc-238-3060f1","poly":"cardio","fiche":"238","front":"Cotation d'intensité : que signifie 3/6 ?","back":"Souffle **fort**.","prio":"P2","sec":"s4"},{"id":"fc-238-455e05","poly":"cardio","fiche":"238","front":"Cotation d'intensité : que signifie 4/6 ?","back":"Avec **thrill**, ou entendu avec le **rebord** du stéthoscope.","prio":"P1","sec":"s4"},{"id":"fc-238-5c72da","poly":"cardio","fiche":"238","front":"Cotation d'intensité : comment distinguer 5/6 et 6/6 ?","back":"Entendus à distance du thorax : **5/6 avec** stéthoscope ; **6/6 sans** stéthoscope.","prio":"P2","sec":"s4"},{"id":"fc-238-fdab57","poly":"cardio","fiche":"238","front":"Souffle variable dans le temps et avec la position : quelle orientation ?","back":"**Pratiquement toujours innocent** (mais cette variabilité manque parfois dans un souffle innocent).","prio":"P1","sec":"s4"},{"id":"fc-238-39a8a9","poly":"cardio","fiche":"238","front":"Souffle bruyant et largement irradié : quelle orientation ?","back":"**A priori organique** (les souffles innocents irradient peu).","prio":"P1","sec":"s4"},{"id":"fc-238-929b55","poly":"cardio","fiche":"238","front":"Souffle diastolique ou double souffle chez l'enfant : quelle orientation ?","back":"**Toujours organique**.","prio":"P1","sec":"s4"},{"id":"fc-238-bb94b2","poly":"cardio","fiche":"238","front":"Souffle frémissant chez l'enfant : quelle orientation ?","back":"**Toujours organique**.","prio":"P1","sec":"s4"},{"id":"fc-238-665db5","poly":"cardio","fiche":"238","front":"Souffle innocent systolodiastolique : lequel ?","back":"Le souffle « **veineux** » du cou (le souffle innocent est presque toujours systolique).","prio":"P2","sec":"s4"},{"id":"fc-238-5eac76","poly":"cardio","fiche":"238","front":"Souffle entendu ou frémissant dans le cou et en sus-sternal : quelle orientation ?","back":"Probable **obstacle aortique**.","prio":"P2","sec":"s4"},{"id":"fc-238-79b5e2","poly":"cardio","fiche":"238","front":"Souffle de l'enfant entendu dans le dos : quelle orientation ?","back":"**Obstacle pulmonaire**.","prio":"P1","sec":"s4"},{"id":"fc-238-f09318","poly":"cardio","fiche":"238","front":"Souffle panradiant à partir de la région mésocardiaque : quelle orientation ?","back":"**CIV**.","prio":"P1","sec":"s4"},{"id":"fc-238-c536ea","poly":"cardio","fiche":"238","front":"Souffle systolique de l'enfant : quels caractères interdisent de l'étiqueter innocent ?","back":"**Holo-** ou **télésystolique**, irradié dans le **dos**, **frémissant**, ou coté **≥ 3/6**.","prio":"P1","sec":"s4"},{"id":"fc-238-4ddc65","poly":"cardio","fiche":"238","front":"Cyanose : à partir de quelle SaO₂ devient-elle cliniquement visible ?","back":"Quand la SaO₂ est **< 85 %**.","prio":"P1","sec":"s5"},{"id":"fc-238-05794b","poly":"cardio","fiche":"238","front":"Cyanose discrète : comment la confirmer ?","back":"Au **saturomètre de pouls** (difficile à voir si SaO₂ transcutanée **> 80 à 85 %**).","prio":"P2","sec":"s5"},{"id":"fc-238-60a0d5","poly":"cardio","fiche":"238","front":"Cyanose : où la chercher ?","back":"**Lèvres**, **muqueuse buccale**, **ongles**.","prio":"P2","sec":"s5"},{"id":"fc-238-f14867","poly":"cardio","fiche":"238","front":"Hypoxie : comment distinguer origine cardiaque et bronchopulmonaire ?","back":"**Cardiaque** = **réfractaire** à l'O₂ (inchangée sous O₂ **100 %**) ; **bronchopulmonaire** = sensible à l'O₂.","prio":"P1","sec":"s5"},{"id":"fc-238-c480a0","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque du nourrisson : quels symptômes digestifs ?","back":"**Difficultés alimentaires**, **vomissements** après les biberons, **stagnation ou perte de poids**.","prio":"P1","sec":"s5"},{"id":"fc-238-cb7306","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque du nourrisson : quels signes à l'examen ?","back":"**Polypnée de repos**, **tachycardie**, **hépatomégalie** (signe majeur).","prio":"P1","sec":"s5"},{"id":"fc-238-90bcbf","poly":"cardio","fiche":"238","front":"Retard staturopondéral du nourrisson cardiaque : dans quelles cardiopathies est-il fréquent ?","back":"Les **larges shunts** (biberons mal pris, dyspnée, sueurs) → la **courbe de poids** est clé.","prio":"P2","sec":"s5"},{"id":"fc-238-ee0ae7","poly":"cardio","fiche":"238","front":"Fréquence cardiaque de l'enfant : que peut traduire un rythme rapide au repos ?","back":"Une **insuffisance cardiaque** (la FC baisse normalement avec l'âge).","prio":"P2","sec":"s5"},{"id":"fc-238-deafab","poly":"cardio","fiche":"238","front":"Enfant : comment mesurer la PA ?","back":"**Brassard pédiatrique** adapté à la taille et à l'âge ; au **membre inférieur autant qu'au supérieur**.","prio":"P1","sec":"s5"},{"id":"fc-238-5802df","poly":"cardio","fiche":"238","front":"Pouls de l'enfant : quelle comparaison faire ?","back":"Présence et amplitude des **huméraux** vs **fémoraux**.","prio":"P1","sec":"s5"},{"id":"fc-238-2c75c6","poly":"cardio","fiche":"238","front":"Enfant avec HTA et pouls fémoraux absents : quel diagnostic d'emblée ?","back":"**Coarctation aortique**.","prio":"P1","sec":"s5"},{"id":"fc-238-0f371b","poly":"cardio","fiche":"238","front":"Frémissement (thrill) précordial ou sus-sternal chez l'enfant : quelle valeur ?","back":"**Toujours pathologique**.","prio":"P1","sec":"s5"},{"id":"fc-238-ca03e1","poly":"cardio","fiche":"238","front":"Citer les signes qui imposent d'adresser l'enfant au cardiopédiatre (un seul suffit) ?","back":"**Cyanose**, **IC**, **retard staturopondéral** inexpliqué, **HTA**, **pouls fémoraux** anormaux, **frémissement**, **DB2 fixe**, **éclat de B2**, **clic protosystolique**, **galop**.","prio":"P1","sec":"s5"},{"id":"fc-238-efa5e5","poly":"cardio","fiche":"238","front":"Combien de signes d'alerte faut-il pour adresser un enfant au cardiopédiatre ?","back":"**Un seul** (ne pas l'adresser = notion inacceptable).","prio":"P1","sec":"s5"},{"id":"fc-238-4ae6e6","poly":"cardio","fiche":"238","front":"Cardiopédiatre devant un signe d'alerte : quels examens ?","back":"**Échocardiographie dans tous les cas**, un **ECG**, **rarement** une radiographie thoracique.","prio":"P2","sec":"s5"},{"id":"fc-238-229adb","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : qu'est-ce qui suffit le plus souvent à trancher innocent ou organique ?","back":"**Interrogatoire** + bon **examen** (surtout bonne **auscultation**) ; échocardiographie **au moindre doute**.","prio":"P2","sec":"s6"},{"id":"fc-238-30a5e6","poly":"cardio","fiche":"238","front":"ECG et radiographie thoracique devant un souffle de l'enfant : quelle valeur ?","back":"Une simple **valeur d'orientation**.","prio":"P2","sec":"s6"},{"id":"fc-238-62170b","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quel est l'examen clé du diagnostic ?","back":"L'**échocardiographie**.","prio":"P1","sec":"s6"},{"id":"fc-238-6020c3","poly":"cardio","fiche":"238","front":"Radiographie de l'enfant : quel piège devant une cardiomégalie ?","back":"**Fausse cardiomégalie** due au **thymus** superposé.","prio":"P2","sec":"s6"},{"id":"fc-238-9d6c9d","poly":"cardio","fiche":"238","front":"Radiographie : cardiomégalie vraie chez l'enfant, que permet-elle de dire ?","back":"Une **cardiopathie**, sans en préciser la nature (malformative, plus rarement cardiomyopathie ou myocardite aiguë).","prio":"P3","sec":"s6"},{"id":"fc-238-c17846","poly":"cardio","fiche":"238","front":"Radiographie : arc moyen gauche saillant, quelle signification ?","back":"Tronc de l'artère pulmonaire dilaté → **shunt gauche-droite**.","prio":"P2","sec":"s6"},{"id":"fc-238-d86a4a","poly":"cardio","fiche":"238","front":"Radiographie : arc moyen gauche concave, quelle signification ?","back":"Voie pulmonaire proximale **hypoplasique** (ex. **tétralogie de Fallot**).","prio":"P2","sec":"s6"},{"id":"fc-238-464b4f","poly":"cardio","fiche":"238","front":"Radiographie : pédicule vasculaire étroit, quelle signification ?","back":"**Anomalie de position** des gros vaisseaux.","prio":"P3","sec":"s6"},{"id":"fc-238-016ec4","poly":"cardio","fiche":"238","front":"Radiographie : hypervascularisation pulmonaire, quelle signification ?","back":"**Hyperdébit** pulmonaire → **shunt gauche-droite**.","prio":"P2","sec":"s6"},{"id":"fc-238-921bea","poly":"cardio","fiche":"238","front":"Radiographie : hypovascularisation pulmonaire, quelle signification ?","back":"**Obstacle** sur la voie pulmonaire.","prio":"P2","sec":"s6"},{"id":"fc-238-65560a","poly":"cardio","fiche":"238","front":"ECG de l'enfant : comment sont l'axe de QRS et le PR par rapport à l'adulte ?","back":"Axe **plus droit** ; PR **plus court**.","prio":"P3","sec":"s6"},{"id":"fc-238-2d59ec","poly":"cardio","fiche":"238","front":"ECG de l'enfant : comment varie la fréquence cardiaque ?","back":"D'autant **plus rapide** que l'enfant est **jeune**.","prio":"P3","sec":"s6"},{"id":"fc-238-7072bd","poly":"cardio","fiche":"238","front":"ECG de l'enfant : évolution des ondes T en précordiales droites ?","back":"**Positives** à la naissance, **négatives** vers la fin de la 1re semaine, puis **négatives de V1 à V4** toute l'enfance (normal).","prio":"P2","sec":"s6"},{"id":"fc-238-f17059","poly":"cardio","fiche":"238","front":"Échocardiographie de l'enfant : quelles conditions d'un diagnostic fiable ?","back":"Appareil performant, **capteurs pédiatriques**, **opérateur expérimenté** formé aux cardiopathies congénitales.","prio":"P3","sec":"s6"},{"id":"fc-238-c845bd","poly":"cardio","fiche":"238","front":"Holter ECG chez l'enfant : quelles indications ?","back":"Troubles du rythme **idiopathiques** ou **postopératoires**.","prio":"P3","sec":"s6"},{"id":"fc-238-e3b988","poly":"cardio","fiche":"238","front":"Épreuve d'effort chez l'enfant : quelles modalités ?","back":"**Tapis roulant** chez le petit, **bicyclette ergométrique**.","prio":"P3","sec":"s6"},{"id":"fc-238-fb1438","poly":"cardio","fiche":"238","front":"IRM cardiaque chez l'enfant : quel intérêt particulier ?","back":"Très performante, notamment pour les **gros vaisseaux intrathoraciques**.","prio":"P3","sec":"s6"},{"id":"fc-238-e1e6a7","poly":"cardio","fiche":"238","front":"Scanner cardiaque de l'enfant : quel inconvénient par rapport à l'IRM ?","back":"**Irradiant** (bonne résolution spatiale).","prio":"P3","sec":"s6"},{"id":"fc-238-4e87b7","poly":"cardio","fiche":"238","front":"Cathétérisme cardiaque de l'enfant : quelle principale utilisation aujourd'hui ?","back":"Le **cathétérisme interventionnel** (peu d'indications diagnostiques : bilan préopératoire des cardiopathies complexes).","prio":"P2","sec":"s6"},{"id":"fc-238-b2adbe","poly":"cardio","fiche":"238","front":"Cathétérisme cardiaque de l'enfant : dans quelles conditions avant 10 ans ?","back":"En général sous **anesthésie générale**.","prio":"P3","sec":"s6"},{"id":"fc-238-cb55cd","poly":"cardio","fiche":"238","front":"Souffle innocent : quel temps du cycle ?","back":"**Systolique** (jamais diastolique), ou parfois **continu**.","prio":"P1","sec":"s7"},{"id":"fc-238-37b416","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle durée dans la systole ?","back":"**Proto-** ou **mésosystolique**, **jamais télésystolique** ; éjectionnel, **bref** (1er tiers de la systole).","prio":"P1","sec":"s7"},{"id":"fc-238-e64a40","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle intensité ?","back":"**Faible** : **< 3/6**, souvent variable avec la position.","prio":"P1","sec":"s7"},{"id":"fc-238-16399a","poly":"cardio","fiche":"238","front":"Souffle innocent : quel timbre ?","back":"**Doux**, parfois **musical**.","prio":"P2","sec":"s7"},{"id":"fc-238-2affa9","poly":"cardio","fiche":"238","front":"Souffle innocent : irradiation et frémissement ?","back":"**Ni irradié, ni frémissant**.","prio":"P1","sec":"s7"},{"id":"fc-238-767afb","poly":"cardio","fiche":"238","front":"Souffle innocent : quel reste de l'examen exige-t-il ?","back":"Souffle **isolé**, asymptomatique ; B1 et B2 normaux (DB2 variable possible) ; **pouls fémoraux perçus** ; **PA normale**.","prio":"P1","sec":"s7"},{"id":"fc-238-0b0fc5","poly":"cardio","fiche":"238","front":"Souffle innocent : combien de critères doivent être réunis ?","back":"**Tous** (un seul critère d'organicité suffit à adresser).","prio":"P1","sec":"s7"},{"id":"fc-238-d4a034","poly":"cardio","fiche":"238","front":"Quelles situations hémodynamiques favorisent un souffle innocent ?","back":"Tout ce qui **augmente le débit cardiaque** : **fièvre**, **effort**, **émotion**, **anémie**, **hyperthyroïdie**.","prio":"P1","sec":"s7"},{"id":"fc-238-4ff602","poly":"cardio","fiche":"238","front":"Quelles anomalies morphologiques favorisent un souffle innocent ?","back":"Syndrome du « **dos droit** » ou « **dos plat** », **thorax en entonnoir**, **scolioses**.","prio":"P3","sec":"s7"},{"id":"fc-238-dcf7c4","poly":"cardio","fiche":"238","front":"Souffle innocent : que montrent radiographie, ECG et ETT ?","back":"Un **cœur normal**.","prio":"P2","sec":"s7"},{"id":"fc-238-61a373","poly":"cardio","fiche":"238","front":"Enfant fébrile avec souffle systolique irradié dans le dos : conclusion ?","back":"**Pas innocent** (tous les critères ne sont pas remplis) → **cardiopédiatre**.","prio":"P1","sec":"s7"},{"id":"fc-238-e9a6fd","poly":"cardio","fiche":"238","front":"Absence de variabilité avec la position : élimine-t-elle un souffle innocent ?","back":"**Non** : la variabilité est **inconstante**.","prio":"P2","sec":"s7"},{"id":"fc-238-ff1e93","poly":"cardio","fiche":"238","front":"Nouveau-né : définition de la période ?","back":"De la **naissance** à la **fin du 2e mois**.","prio":"P2","sec":"s8"},{"id":"fc-238-c99989","poly":"cardio","fiche":"238","front":"Coarctation aortique néonatale : quand apparaissent les symptômes ?","back":"À la **fermeture du canal artériel** (parfois dès les premiers jours de vie).","prio":"P2","sec":"s8"},{"id":"fc-238-05ff39","poly":"cardio","fiche":"238","front":"Coarctation néonatale : quels signes cliniques clés ?","back":"**Pouls fémoraux abolis** ; tableau **bruyant** ; souffle systolique doux **sous-claviculaire gauche** irradiant en **interscapulaire**.","prio":"P2","sec":"s8"},{"id":"fc-238-2a2cde","poly":"cardio","fiche":"238","front":"Coarctation néonatale : quel traitement ?","back":"**Chirurgie urgente**.","prio":"P2","sec":"s8"},{"id":"fc-238-35f39c","poly":"cardio","fiche":"238","front":"Quelle est la cause la plus classique de cyanose néonatale ?","back":"La **transposition des gros vaisseaux** (sans souffle ; urgence cardiologique néonatale type).","prio":"P1","sec":"s8"},{"id":"fc-238-9c32c9","poly":"cardio","fiche":"238","front":"Sténose valvulaire pulmonaire serrée néonatale : quel mécanisme de la cyanose ?","back":"**Shunt droite-gauche** par le **foramen ovale perméable**.","prio":"P2","sec":"s8"},{"id":"fc-238-7fac4e","poly":"cardio","fiche":"238","front":"Sténose valvulaire pulmonaire : quel souffle ?","back":"Systolique **râpeux** au foyer pulmonaire **avec clic protosystolique**.","prio":"P2","sec":"s8"},{"id":"fc-238-9adc7a","poly":"cardio","fiche":"238","front":"Cardiopathies complexes néonatales : quel souffle, et exemples ?","back":"Souffle **absent ou faible** ; ex. **ventricule unique**, **tronc artériel commun**.","prio":"P3","sec":"s8"},{"id":"fc-238-e1b014","poly":"cardio","fiche":"238","front":"Nourrisson : définition de la période ?","back":"De **2 mois** à l'**âge de la marche**.","prio":"P2","sec":"s8"},{"id":"fc-238-8f3d93","poly":"cardio","fiche":"238","front":"Petite CIV restrictive : quel souffle ?","back":"**Holosystolique**, **râpeux**, **intense**, parasternal gauche, en **rayons de roue**.","prio":"P2","sec":"s8"},{"id":"fc-238-363b29","poly":"cardio","fiche":"238","front":"CIV large : quelle auscultation ?","back":"Souffle **faible** + **B1 fort** à la pointe.","prio":"P2","sec":"s8"},{"id":"fc-238-1f3d89","poly":"cardio","fiche":"238","front":"Persistance du canal artériel : quel souffle ?","back":"**Continu** au bord gauche du sternum, crescendo en systole, decrescendo en diastole.","prio":"P2","sec":"s8"},{"id":"fc-238-d84d8b","poly":"cardio","fiche":"238","front":"Quelle est la cardiopathie cyanogène la plus fréquente ?","back":"La **tétralogie de Fallot**.","prio":"P1","sec":"s8"},{"id":"fc-238-becca8","poly":"cardio","fiche":"238","front":"Tétralogie de Fallot : quand apparaît la cyanose ?","back":"**Retardée** (quelques semaines ou mois) ; diagnostic en général à la naissance (souffle) ou en anténatal.","prio":"P2","sec":"s8"},{"id":"fc-238-030acf","poly":"cardio","fiche":"238","front":"Tétralogie de Fallot : quel souffle ?","back":"Systolique **râpeux** au foyer pulmonaire **sans clic**.","prio":"P2","sec":"s8"},{"id":"fc-238-b80b27","poly":"cardio","fiche":"238","front":"Souffle râpeux au foyer pulmonaire : quel signe distingue sténose valvulaire et Fallot ?","back":"Le **clic protosystolique** : présent dans la sténose valvulaire, **absent** dans le Fallot.","prio":"P2","sec":"s8"},{"id":"fc-238-ce47ce","poly":"cardio","fiche":"238","front":"Tétralogie de Fallot : à quel âge la corriger ?","back":"**Entre 6 mois et 1 an**.","prio":"P2","sec":"s8"},{"id":"fc-238-185d25","poly":"cardio","fiche":"238","front":"2e enfance : quelle tranche d'âge ?","back":"De **2 à 16 ans**.","prio":"P2","sec":"s8"},{"id":"fc-238-0ceaca","poly":"cardio","fiche":"238","front":"CIA : quelle auscultation ?","back":"Souffle systolique au foyer pulmonaire (**hyperdébit**), souvent avec **DB2 fixe et constant**.","prio":"P2","sec":"s8"},{"id":"fc-238-87d2ca","poly":"cardio","fiche":"238","front":"CIA : quel mécanisme du dédoublement de B2 ?","back":"**Fermeture retardée** de la valve pulmonaire.","prio":"P3","sec":"s8"},{"id":"fc-238-6e6a08","poly":"cardio","fiche":"238","front":"Coarctation de la 2e enfance : quels signes ?","back":"**HTA**, pouls fémoraux **diminués**, **gradient tensionnel** membre supérieur/inférieur, souffle systolique doux sous-claviculaire gauche irradiant en interscapulaire.","prio":"P2","sec":"s8"},{"id":"fc-238-5a247d","poly":"cardio","fiche":"238","front":"Sténose valvulaire pulmonaire de la 2e enfance : quand est-elle découverte ?","back":"À des âges **variables** selon sa sévérité (dyspnée d'effort possible).","prio":"P3","sec":"s8"},{"id":"fc-238-505b73","poly":"cardio","fiche":"238","front":"Nouveau-né : quelles cardiopathies chirurgicales sont les plus fréquentes ?","back":"**Coarctation**, **transposition des gros vaisseaux**, **malformations complexes**.","prio":"P2","sec":"s8"},{"id":"fc-238-115711","poly":"cardio","fiche":"238","front":"Nouveau-né : quelles cardiopathies bénignes sont les plus répandues ?","back":"Les **petites CIV**.","prio":"P2","sec":"s8"},{"id":"fc-238-09474c","poly":"cardio","fiche":"238","front":"Nourrisson : quelles malformations sont les plus communes ?","back":"Les **shunts gauche-droite**, surtout les **CIV**.","prio":"P2","sec":"s8"},{"id":"fc-238-7e0d1a","poly":"cardio","fiche":"238","front":"2e enfance : quels souffles dominent ?","back":"Les **souffles fonctionnels** (cardiopathies en général bien tolérées).","prio":"P1","sec":"s8"},{"id":"fc-238-4bea2a","poly":"cardio","fiche":"238","front":"Nourrisson : un souffle faible signe-t-il une petite CIV ?","back":"**Non** : CIV **large** = souffle faible (+ B1 fort) ; **petite** CIV = souffle intense.","prio":"P2","sec":"s8"},{"id":"fc-238-cf95ed","poly":"cardio","fiche":"238","front":"Souffle réunissant tous les critères d'innocence : quels examens complémentaires ?","back":"**Aucun** ; échocardiographie **uniquement en cas de doute**.","prio":"P1","sec":"s9"},{"id":"fc-238-2c5398","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle conclusion donner à la famille, et quand ?","back":"Conclusion **ferme et précise** dès la **première consultation**.","prio":"P1","sec":"s9"},{"id":"fc-238-ace9cf","poly":"cardio","fiche":"238","front":"Souffle innocent : quel traitement et quelle surveillance ?","back":"**Aucun** traitement ; **aucune** surveillance (inutile de revoir l'enfant).","prio":"P1","sec":"s9"},{"id":"fc-238-9e78d9","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle restriction sportive ?","back":"**Aucune** : tous les sports, **y compris en compétition**.","prio":"P1","sec":"s9"},{"id":"fc-238-802c2c","poly":"cardio","fiche":"238","front":"Souffle en période néonatale : quelle notion est inacceptable ?","back":"Le **méconnaître** : même chez un nouveau-né asymptomatique, il est **toujours potentiellement pathologique**.","prio":"P1","sec":"s10"},{"id":"fc-238-f6f6c4","poly":"cardio","fiche":"238","front":"Souffle néonatal : quel bilan avant la sortie de maternité ?","back":"Examen complet + **échographie cardiaque systématique** + souvent **ECG** + souvent **radiographie** pulmonaire de face.","prio":"P2","sec":"s10"},{"id":"fc-238-f083cf","poly":"cardio","fiche":"238","front":"Souffle néonatal : quels signes associés rechercher ?","back":"**Saturation** (cyanose), signes d'**IC**, **pouls fémoraux**, PA au membre inférieur autant qu'au supérieur.","prio":"P1","sec":"s10"},{"id":"fc-238-5c9d87","poly":"cardio","fiche":"238","front":"Nouveau-né : l'absence de souffle élimine-t-elle une cardiopathie grave ?","back":"**Non** : la **transposition des gros vaisseaux** ne donne **pas de souffle**.","prio":"P2","sec":"s10"},{"id":"fc-238-c8a469","poly":"cardio","fiche":"238","front":"Nouveau-né cyanosé : première étape ?","back":"**Confirmer l'hypoxie** par la **saturation transcutanée** (penser hypothermie, hypoglycémie).","prio":"P1","sec":"s11"},{"id":"fc-238-8fb602","poly":"cardio","fiche":"238","front":"Nouveau-né cyanosé sous O₂ à 100 % : que signe une hypoxie inchangée ?","back":"Une origine **cardiaque** → **cardiopédiatre** (échocardiographie).","prio":"P1","sec":"s11"},{"id":"fc-238-7f3d30","poly":"cardio","fiche":"238","front":"Nourrisson, cyanose retardée, souffle râpeux pulmonaire sans clic : quel diagnostic et quelle conduite ?","back":"**Tétralogie de Fallot** → **correction chirurgicale entre 6 mois et 1 an**.","prio":"P2","sec":"s11"},{"id":"fc-238-d5d830","poly":"cardio","fiche":"238","front":"Cardiopathie congénitale cyanogène : quel risque infectieux, et quelle conséquence ?","back":"**Haut risque d'endocardite** → **antibioprophylaxie** avant soins dentaires à risque.","prio":"P1","sec":"s11"},{"id":"fc-238-6c5eb1","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite (adulte) : quelle molécule de référence et quelle dose ?","back":"**Amoxicilline** (ou ampicilline) **2 g** per os ou IV, **30 à 60 min** avant le soin.","prio":"P1","sec":"s11"},{"id":"fc-238-b114f5","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite (adulte) : quelle alternative injectable à l'amoxicilline ?","back":"**Céfazoline** (ou ceftriaxone) **1 g** IM ou IV.","prio":"P2","sec":"s11"},{"id":"fc-238-5fa5a2","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite : quelle durée ?","back":"**Dose unique**, avant un soin dentaire touchant la **gencive** ou la région **périapicale**, ou avec **effraction de la muqueuse**.","prio":"P2","sec":"s11"},{"id":"fc-238-39e629","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite et allergie à la pénicilline : quelle notion inacceptable ?","back":"**Prescrire une pénicilline**.","prio":"P1","sec":"s11"},{"id":"fc-238-66cec4","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite chez l'enfant : posologie selon le Collège ?","back":"**Non précisée** dans le Collège (seule la dose adulte est donnée).","prio":"P3","sec":"s11"},{"id":"fc-238-8d33cb","poly":"cardio","fiche":"238","front":"Nourrisson en IC : quels gestes associer à l'examen ?","back":"**Pouls fémoraux** (vs huméraux), **PA au membre inférieur** autant qu'au supérieur, **poids** sur la courbe → cardiopédiatre.","prio":"P2","sec":"s12"},{"id":"fc-238-aa70ef","poly":"cardio","fiche":"238","front":"Nouveau-né symptomatique à la fermeture du canal, pouls fémoraux abolis : diagnostic et conduite ?","back":"**Coarctation aortique** → **chirurgie urgente**.","prio":"P2","sec":"s12"},{"id":"fc-238-7d7ed1","poly":"cardio","fiche":"238","front":"Large shunt gauche-droite du nourrisson : quand opérer ?","back":"**Tôt**, en général **dans la 1re année de vie**.","prio":"P2","sec":"s12"},{"id":"fc-238-a0f8b8","poly":"cardio","fiche":"238","front":"Large shunt gauche-droite opéré trop tard : quel risque ?","back":"**HTAP irréversible**.","prio":"P2","sec":"s12"},{"id":"fc-238-6308cb","poly":"cardio","fiche":"238","front":"Citer des larges shunts gauche-droite du nourrisson à opérer tôt ?","back":"**CIV large**, **canal artériel**, **canal atrioventriculaire** (trisomie 21).","prio":"P3","sec":"s12"},{"id":"fc-238-3afe9e","poly":"cardio","fiche":"238","front":"Cardiopathie significative de l'enfant : quel paramètre surveiller à chaque examen ?","back":"La **croissance pondérale**.","prio":"P2","sec":"s12"},{"id":"fc-238-4fe5b0","poly":"cardio","fiche":"238","front":"Nourrisson avec signes respiratoires et digestifs : quels signes chercher avant de conclure à une cause non cardiaque ?","back":"L'**hépatomégalie** et les **pouls fémoraux**.","prio":"P1","sec":"s12"},{"id":"fc-238-6428c3","poly":"cardio","fiche":"238","front":"Enfant avec HTA : quel examen clinique pour ne pas rater une coarctation ?","back":"PA aux membres **supérieurs et inférieurs** (brassard adapté) + **pouls huméraux vs fémoraux** ; HTA + fémoraux absents/diminués → **cardiopédiatre**.","prio":"P1","sec":"s13"},{"id":"fc-238-3356cd","poly":"cardio","fiche":"238","front":"Coarctation de l'enfant : quels examens de confirmation ?","back":"**Échocardiographie** et **IRM**.","prio":"P2","sec":"s13"},{"id":"fc-238-c5907f","poly":"cardio","fiche":"238","front":"Coarctation de l'enfant : quels traitements ?","back":"**Chirurgical** ou **endoluminal** (dilatation + **endoprothèse**).","prio":"P2","sec":"s13"},{"id":"fc-238-ea8a46","poly":"cardio","fiche":"238","front":"Coarctation de l'enfant : quels arguments cliniques en plus de l'HTA ?","back":"**Gradient tensionnel** membre supérieur/inférieur ; souffle systolique doux sous-claviculaire gauche irradiant en **interscapulaire** dans le dos.","prio":"P2","sec":"s13"},{"id":"fc-238-55acbe","poly":"cardio","fiche":"238","front":"Souffle innocent : évolution naturelle ?","back":"Il **disparaît avec l'âge** (parfois encore entendu chez le jeune adulte).","prio":"P1","sec":"s14"},{"id":"fc-238-ed8f47","poly":"cardio","fiche":"238","front":"Cardiopathie congénitale réparée avec matériel prothétique : combien de temps à haut risque d'endocardite ?","back":"**6 mois** après l'intervention ; **à vie** s'il persiste un **shunt résiduel**.","prio":"P1","sec":"s14"},{"id":"fc-238-a12d59","poly":"cardio","fiche":"238","front":"Cardiopathie à risque d'endocardite : quel rythme de visites chez le dentiste ?","back":"**2 fois/an** si haut risque ; **1 fois/an** pour les autres.","prio":"P2","sec":"s14"},{"id":"fc-238-73a2e3","poly":"cardio","fiche":"238","front":"Cardiopathie à risque d'endocardite : quelles précautions cutanées ?","back":"**Désinfecter les plaies** ; éviter **tatouages** et **piercing**.","prio":"P2","sec":"s14"},{"id":"fc-238-038313","poly":"cardio","fiche":"238","front":"Cardiopathie à risque d'endocardite : quels conseils en cas de fièvre ?","back":"**Pas d'antibiotique en automédication** ; **consulter vite**.","prio":"P1","sec":"s14"},{"id":"fc-238-3f0325","poly":"cardio","fiche":"238","front":"Prévention de l'endocardite : quelles autres mesures générales ?","back":"Éradiquer les **colonisations** chroniques (cutanées, urinaires), traiter les infections locales, **asepsie** stricte, **limiter les voies veineuses**.","prio":"P3","sec":"s14"},{"id":"fc-238-48412d","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite : pour quels patients et quels soins ?","back":"Cardiopathies à **haut risque** seulement, avant les **soins dentaires à risque** (l'éducation concerne tous les patients à risque).","prio":"P1","sec":"s14"},{"id":"fc-330-11b95e","poly":"cardio","fiche":"330","front":"Antiagrégants plaquettaires : sur quelle étape de l'hémostase agissent-ils ?","back":"L'**hémostase primaire** (agrégation des plaquettes), étape clé du thrombus **artériel**.","prio":"P1","sec":"s1"},{"id":"fc-330-1e4696","poly":"cardio","fiche":"330","front":"Anticoagulants : à quel niveau agissent-ils ?","back":"Sur la **coagulation** (héparines, AVK, AOD).","prio":"P1","sec":"s1"},{"id":"fc-330-c308ca","poly":"cardio","fiche":"330","front":"Fibrinolytiques : quel mode d'action ?","back":"Ils **activent la fibrinolyse** → destruction d'un caillot **déjà formé**.","prio":"P1","sec":"s1"},{"id":"fc-330-bc89a0","poly":"cardio","fiche":"330","front":"Antiagrégants : dans quelle maladie les retrouve-t-on surtout ?","back":"La **maladie athérothrombotique** (SCA, stent, AOMI, AVC).","prio":"P2","sec":"s1"},{"id":"fc-330-31c772","poly":"cardio","fiche":"330","front":"Anticoagulants : quel risque majeur impose de peser chaque prescription ?","back":"Une **iatrogénie importante** : chaque prescription se pèse, se surveille et s'explique au patient.","prio":"P2","sec":"s1"},{"id":"fc-330-7c1889","poly":"cardio","fiche":"330","front":"HNF, HBPM, fondaparinux : quel est leur mécanisme commun ?","back":"**Activation de l'antithrombine** (anticoagulant physiologique du sang).","prio":"P1","sec":"s1"},{"id":"fc-330-ba551c","poly":"cardio","fiche":"330","front":"AVK : sur quelle cible agissent-ils ?","back":"Synthèse hépatique des facteurs **II, VII, IX, X** (et des **protéines C et S**).","prio":"P1","sec":"s1"},{"id":"fc-330-870fbb","poly":"cardio","fiche":"330","front":"AOD : quelles cibles selon la molécule ?","back":"**Facteur II** (dabigatran) ; **facteur X** (rivaroxaban, apixaban).","prio":"P1","sec":"s1"},{"id":"fc-330-1d376b","poly":"cardio","fiche":"330","front":"Quelle notion transversale ne pas oublier sous AVK et sous AOD ?","back":"L'**éducation du patient**.","prio":"P1","sec":"s1"},{"id":"fc-330-7d5960","poly":"cardio","fiche":"330","front":"Aspirine : quel mécanisme d'action ?","back":"Inhibe la **cyclo-oxygénase** (Cox-1, moindrement Cox-2) → baisse du **thromboxane A2**.","prio":"P1","sec":"s2"},{"id":"fc-330-38b4c3","poly":"cardio","fiche":"330","front":"Aspirine : combien de temps dure son effet antiagrégant ?","back":"**Irréversible**, toute la vie de la plaquette : **7 à 10 jours**.","prio":"P1","sec":"s2"},{"id":"fc-330-9478b8","poly":"cardio","fiche":"330","front":"Aspirine per os : quel délai d'action ?","back":"Rapide : **quelques dizaines de minutes**.","prio":"P3","sec":"s2"},{"id":"fc-330-4e46c8","poly":"cardio","fiche":"330","front":"Inhibiteurs de P2Y12 : quelle voie bloquent-ils ?","back":"La voie de l'**ADP** (récepteur P2Y12).","prio":"P1","sec":"s2"},{"id":"fc-330-fc548a","poly":"cardio","fiche":"330","front":"Citer les inhibiteurs de P2Y12 utilisés ?","back":"**Clopidogrel**, **prasugrel**, **ticagrélor**.","prio":"P1","sec":"s2"},{"id":"fc-330-855583","poly":"cardio","fiche":"330","front":"Clopidogrel : pourquoi est-il inefficace chez certains patients ?","back":"**Prodrogue** activée par le CYP450 (surtout **CYP2C19**) ; mauvais métabolisme chez **15 à 25 %**.","prio":"P1","sec":"s2"},{"id":"fc-330-f91a9b","poly":"cardio","fiche":"330","front":"Inhibition plaquettaire moyenne : clopidogrel vs prasugrel/ticagrélor ?","back":"Clopidogrel **40-50 %** ; prasugrel et ticagrélor **70-80 %** (plus puissants et plus rapides).","prio":"P2","sec":"s2"},{"id":"fc-330-c6c4d8","poly":"cardio","fiche":"330","front":"Double antiagrégation : quelle molécule comporte-t-elle toujours ?","back":"L'**aspirine** (+ un inhibiteur de P2Y12).","prio":"P1","sec":"s2"},{"id":"fc-330-544693","poly":"cardio","fiche":"330","front":"Aspirine dans le SCA : quelle posologie ?","back":"**250 mg IVD**, puis **75-100 mg/j** per os, avec un **IPP**.","prio":"P1","sec":"s2"},{"id":"fc-330-2c2168","poly":"cardio","fiche":"330","front":"Aspirine : à partir de quelle dose apparaissent les effets antalgique, antipyrétique, anti-inflammatoire ?","back":"Au-delà de **1 g/j** chez l'adulte (dose antiagrégante très inférieure).","prio":"P2","sec":"s2"},{"id":"fc-330-8a2199","poly":"cardio","fiche":"330","front":"Aspirine : quelles indications en prévention ?","back":"**Secondaire** : coronaropathie, AOMI, AVC ; **primaire** seulement si très haut risque vasculaire **et** faible risque hémorragique.","prio":"P1","sec":"s2"},{"id":"fc-330-cc6a32","poly":"cardio","fiche":"330","front":"Aspirine : quels effets indésirables ?","back":"**Saignements**, **intolérance gastrique** ; allergie très rare (bien plus souvent suspectée qu'avérée).","prio":"P2","sec":"s2"},{"id":"fc-330-2c4e8e","poly":"cardio","fiche":"330","front":"Syndrome de Widal : quelle triade ?","back":"**Asthme** + **polypose nasale** + **allergie à l'aspirine**.","prio":"P2","sec":"s2"},{"id":"fc-330-9f4e26","poly":"cardio","fiche":"330","front":"Clopidogrel : quelle posologie dans le SCA ?","back":"Charge **600 mg** per os → **75 mg/j**.","prio":"P1","sec":"s2"},{"id":"fc-330-9be336","poly":"cardio","fiche":"330","front":"Clopidogrel associé à une fibrinolyse : quelle dose de charge ?","back":"**300 mg** seulement, avant 75 ans.","prio":"P1","sec":"s2"},{"id":"fc-330-194e3f","poly":"cardio","fiche":"330","front":"Clopidogrel : quelles indications ?","back":"**Angioplastie coronaire programmée** ; SCA si prasugrel/ticagrélor non indiqués, ou **après fibrinolyse** ; avec l'aspirine **3 à 12 mois**.","prio":"P2","sec":"s2"},{"id":"fc-330-76aac2","poly":"cardio","fiche":"330","front":"Clopidogrel : quand est-il le recours dans le SCA ?","back":"Si prasugrel et ticagrélor sont **contre-indiqués** (risque hémorragique, antécédent d'AVC, insuffisance hépatique sévère).","prio":"P2","sec":"s2"},{"id":"fc-330-ff45d2","poly":"cardio","fiche":"330","front":"Prasugrel : quelle posologie ?","back":"Charge **60 mg** per os → **10 mg/j**.","prio":"P1","sec":"s2"},{"id":"fc-330-ab5108","poly":"cardio","fiche":"330","front":"Prasugrel : quelle indication ?","back":"**SCA traité par angioplastie**, patient **< 75 ans**, avec l'aspirine.","prio":"P2","sec":"s2"},{"id":"fc-330-fa0cb8","poly":"cardio","fiche":"330","front":"Prasugrel : quelle contre-indication absolue ?","back":"**Antécédent d'AVC**.","prio":"P1","sec":"s2"},{"id":"fc-330-7dc108","poly":"cardio","fiche":"330","front":"Prasugrel : quelles contre-indications relatives ?","back":"**Poids < 60 kg**, **âge > 75 ans**.","prio":"P1","sec":"s2"},{"id":"fc-330-e2e107","poly":"cardio","fiche":"330","front":"Ticagrélor : quelle posologie ?","back":"Charge **180 mg** → **90 mg matin et soir**.","prio":"P1","sec":"s2"},{"id":"fc-330-b87f2b","poly":"cardio","fiche":"330","front":"Ticagrélor : quel effet indésirable principal ?","back":"**Dyspnée** (**18 %** des patients) ; bradycardie et dyspnée réversibles à l'arrêt.","prio":"P1","sec":"s2"},{"id":"fc-330-4d8896","poly":"cardio","fiche":"330","front":"Duoplavin® : quelle association ?","back":"**Aspirine + clopidogrel** dans un même comprimé.","prio":"P3","sec":"s2"},{"id":"fc-330-4ab5a4","poly":"cardio","fiche":"330","front":"Aspirine : quel effet possible est décrit en plus des effets antiagrégant, antalgique, antipyrétique et anti-inflammatoire ?","back":"Possible effet **anticancéreux** (surtout sur les adénocarcinomes).","prio":"P3","sec":"s2"},{"id":"fc-330-680e9c","poly":"cardio","fiche":"330","front":"Anti-GPIIb/IIIa : quelle cible, et exemples ?","back":"Le **récepteur du fibrinogène** ; **tirofiban**, **eptifibatide**.","prio":"P3","sec":"s2"},{"id":"fc-330-46752b","poly":"cardio","fiche":"330","front":"Antiagrégants : comment surveiller biologiquement leur activité ?","back":"**Aucun test biologique fiable** : pas de surveillance en routine.","prio":"P1","sec":"s2"},{"id":"fc-330-6b2634","poly":"cardio","fiche":"330","front":"SCA : durée classique de l'association inhibiteur de P2Y12 + aspirine ?","back":"Classiquement **12 mois** (de **1 à 12 mois** selon le risque hémorragique).","prio":"P2","sec":"s2"},{"id":"fc-330-2d6ca9","poly":"cardio","fiche":"330","front":"Double antiagrégation : quelle est la tendance actuelle ?","back":"**Raccourcir** la bithérapie et **remplacer l'aspirine** au long cours par l'autre antiagrégant (clopidogrel ou ticagrélor).","prio":"P2","sec":"s2"},{"id":"fc-330-91bac0","poly":"cardio","fiche":"330","front":"Coronarien stenté : combien de temps garder l'aspirine ?","back":"**Le plus souvent à vie**.","prio":"P3","sec":"s2"},{"id":"fc-330-74f948","poly":"cardio","fiche":"330","front":"Patient en prévention secondaire : quel risque à arrêter l'aspirine par crainte du saignement ?","back":"Un **événement athérothrombotique**.","prio":"P1","sec":"s2"},{"id":"fc-330-70334d","poly":"cardio","fiche":"330","front":"HNF : quelles formes existent ?","back":"**Héparine IV** et **héparine calcique** (Calciparine®, SC).","prio":"P2","sec":"s3"},{"id":"fc-330-499ba3","poly":"cardio","fiche":"330","front":"Citer les HBPM ?","back":"**Énoxaparine** (Lovenox®), **tinzaparine** (Innohep®), **nadroparine** (Fraxiparine®), **daltéparine** (Fragmine®).","prio":"P2","sec":"s3"},{"id":"fc-330-9fdd82","poly":"cardio","fiche":"330","front":"Citer les apparentés aux héparines ?","back":"**Fondaparinux** (Arixtra®), **danaparoïde** (Orgaran®), **bivalirudine**.","prio":"P2","sec":"s3"},{"id":"fc-330-558c80","poly":"cardio","fiche":"330","front":"HNF : quelle demi-vie, et conséquence pratique ?","back":"Environ **1 h 30** → **seringue autopousseuse continue** ou plusieurs injections/j (2-3 pour l'héparine calcique).","prio":"P1","sec":"s3"},{"id":"fc-330-aa4580","poly":"cardio","fiche":"330","front":"HNF : comment est-elle éliminée ?","back":"Surtout par **fixation** (protéines, endothélium, macrophages), **peu par le rein**.","prio":"P2","sec":"s3"},{"id":"fc-330-3f28b1","poly":"cardio","fiche":"330","front":"HBPM : combien d'injections par jour ?","back":"**1 ou 2 injections SC/j** (bolus IV possible pour un effet immédiat).","prio":"P2","sec":"s3"},{"id":"fc-330-44cfef","poly":"cardio","fiche":"330","front":"Fondaparinux : combien d'injections par jour ?","back":"**Une seule**, SC ou IV.","prio":"P2","sec":"s3"},{"id":"fc-330-efb541","poly":"cardio","fiche":"330","front":"HBPM et fondaparinux : quelle voie d'élimination, et conséquence ?","back":"**Rénale** essentiellement → **plutôt CI si ClCr < 30 mL/min**.","prio":"P1","sec":"s3"},{"id":"fc-330-db3830","poly":"cardio","fiche":"330","front":"Demi-vie des HBPM et du fondaparinux ?","back":"HBPM **8 à 24 h** ; fondaparinux **17 à 21 h**.","prio":"P3","sec":"s3"},{"id":"fc-330-c7256a","poly":"cardio","fiche":"330","front":"Insuffisance rénale sévère (ClCr < 20-30 mL/min) : quel est le seul anticoagulant utilisable ?","back":"L'**HNF**.","prio":"P1","sec":"s3"},{"id":"fc-330-b85414","poly":"cardio","fiche":"330","front":"HBPM sous 30 mL/min de clairance : quelle exception récente ?","back":"Des règles récentes autorisent l'**énoxaparine** sous ce seuil.","prio":"P2","sec":"s3"},{"id":"fc-330-454cd4","poly":"cardio","fiche":"330","front":"HNF : quel antidote ?","back":"**Sulfate de protamine** IV (neutralisation instantanée).","prio":"P1","sec":"s3"},{"id":"fc-330-77b0dc","poly":"cardio","fiche":"330","front":"HBPM et fondaparinux : existe-t-il un antidote ?","back":"**Non** : en cours de développement.","prio":"P2","sec":"s3"},{"id":"fc-330-ac9d11","poly":"cardio","fiche":"330","front":"Héparines : quelles indications curatives ?","back":"**TVP et EP** ; **troubles du rythme** à anticoaguler (en attendant les anticoagulants oraux) ; **SCA**.","prio":"P1","sec":"s3"},{"id":"fc-330-36d3da","poly":"cardio","fiche":"330","front":"HBPM : quelle utilisation préventive ?","back":"**Prévention de la thrombose veineuse** en chirurgie ou en médecine à risque.","prio":"P2","sec":"s3"},{"id":"fc-330-2f93c9","poly":"cardio","fiche":"330","front":"Danaparoïde : quelle indication principale ?","back":"Patient avec **TIH** actuelle ou passée devant être anticoagulé.","prio":"P1","sec":"s3"},{"id":"fc-330-f3e936","poly":"cardio","fiche":"330","front":"Bivalirudine : quelle utilisation ?","back":"Anticoagulant IV surtout utilisé pendant les **angioplasties coronaires**.","prio":"P2","sec":"s3"},{"id":"fc-330-3bcaa4","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative de l'HNF ?","back":"**500 UI/kg/j**, SC ou IV continue, puis adaptée.","prio":"P1","sec":"s3"},{"id":"fc-330-2989e9","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative de l'énoxaparine ?","back":"**100 UI/kg/12 h** (1 mg/kg/12 h) SC.","prio":"P1","sec":"s3"},{"id":"fc-330-0b09dd","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative de la tinzaparine ?","back":"**175 UI/kg/24 h** SC.","prio":"P2","sec":"s3"},{"id":"fc-330-d722b0","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative du fondaparinux ?","back":"**7,5 mg/24 h** SC pour un poids de 50 à 100 kg.","prio":"P2","sec":"s3"},{"id":"fc-330-3a74df","poly":"cardio","fiche":"330","front":"TVP/EP : dans quelles situations l'HNF est-elle recommandée ?","back":"**Insuffisance rénale sévère**, patient **instable**, **geste** possible imposant un arrêt, patient **fibrinolysé**.","prio":"P2","sec":"s3"},{"id":"fc-330-3d95c9","poly":"cardio","fiche":"330","front":"SCA avec angioplastie immédiate : quelles doses d'anticoagulant ?","back":"HNF **70-100 UI/kg IVD** ou énoxaparine **0,5 mg/kg IVD** ; arrêt juste après revascularisation.","prio":"P2","sec":"s3"},{"id":"fc-330-295589","poly":"cardio","fiche":"330","front":"SCA ST- à haut risque : quelles doses d'anticoagulant SC ?","back":"Énoxaparine **1 mg/kg SC matin et soir** ou fondaparinux **2,5 mg/j SC**.","prio":"P2","sec":"s3"},{"id":"fc-330-b6babc","poly":"cardio","fiche":"330","front":"SCA ST- sous fondaparinux : que faut-il ajouter pendant la coronarographie ?","back":"Un **bolus d'HNF**.","prio":"P3","sec":"s3"},{"id":"fc-330-91d372","poly":"cardio","fiche":"330","front":"HNF : quand faire la numération plaquettaire ?","back":"**Avant** l'héparine ou dans les **24 h** suivant son introduction (dépistage TIH).","prio":"P1","sec":"s3"},{"id":"fc-330-857943","poly":"cardio","fiche":"330","front":"HNF IV (item 330) : quand faire le 1er TCA ?","back":"**Vers la 5ᵉ heure** après l'instauration, puis **au moins 1 fois/j**.","prio":"P1","sec":"s3"},{"id":"fc-330-5f561c","poly":"cardio","fiche":"330","front":"HNF IV (item 330) : quelle cible biologique ?","back":"**TCA 2 à 3 fois** le témoin et/ou **anti-Xa 0,5 à 0,8**.","prio":"P1","sec":"s3"},{"id":"fc-330-95af60","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA < 45 s ?","back":"**+ 6 000 UI/24 h** + **bolus de 5 000 U**.","prio":"P2","sec":"s3"},{"id":"fc-330-19044c","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA entre 46 et 54 s ?","back":"**+ 3 000 UI/24 h**.","prio":"P3","sec":"s3"},{"id":"fc-330-86a562","poly":"cardio","fiche":"330","front":"Seringue d'HNF : quelle zone de TCA laisse la dose inchangée ?","back":"**55 à 85 s**.","prio":"P2","sec":"s3"},{"id":"fc-330-c0f4b5","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA entre 86 et 110 s ?","back":"**− 3 000 UI/24 h** + arrêt de la seringue **1 h**.","prio":"P3","sec":"s3"},{"id":"fc-330-bf59d4","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA > 110 s ?","back":"**− 6 000 UI/24 h** + arrêt de la seringue **1 h**.","prio":"P2","sec":"s3"},{"id":"fc-330-ee53dd","poly":"cardio","fiche":"330","front":"HNF, chapitre MTEV : quelle cible biologique ?","back":"**TCA 1,5 à 2,5 fois** le témoin ou **anti-Xa 0,3 à 0,7** (≠ item 330).","prio":"P2","sec":"s3"},{"id":"fc-330-809b92","poly":"cardio","fiche":"330","front":"HNF, chapitre MTEV : quand mesurer TCA ou anti-Xa ?","back":"**4 h** après le début de l'IV continue et après chaque changement de dose (entre 2 injections si SC).","prio":"P3","sec":"s3"},{"id":"fc-330-15fe7c","poly":"cardio","fiche":"330","front":"HNF, chapitre MTEV : quel rythme de surveillance des plaquettes ?","back":"Avant traitement puis **2 fois/semaine pendant 21 jours** (inutile au-delà d'un mois).","prio":"P3","sec":"s3"},{"id":"fc-330-fbd84b","poly":"cardio","fiche":"330","front":"HBPM : faut-il mesurer leur activité ?","back":"**Non** en règle, si dose **adaptée au poids** et pas d'**insuffisance rénale**.","prio":"P1","sec":"s3"},{"id":"fc-330-020cc4","poly":"cardio","fiche":"330","front":"HBPM : quand un anti-Xa est-il suggéré (chapitre MTEV) ?","back":"**4 h** après l'initiation si risque d'accumulation ou hémorragique (IR modérée, âge élevé, petit poids, obésité).","prio":"P3","sec":"s3"},{"id":"fc-330-c41600","poly":"cardio","fiche":"330","front":"MTEV : pourquoi préférer HBPM et fondaparinux à l'HNF ?","back":"**Plus commodes**, pas d'adaptation à un test d'hémostase, **moins de TIH**.","prio":"P2","sec":"s3"},{"id":"fc-330-b0448d","poly":"cardio","fiche":"330","front":"Sous HBPM ou fondaparinux : quand surveiller les plaquettes (chapitre MTEV) ?","back":"HBPM après HNF ou MTEV **postopératoire**, nouvel épisode thromboembolique, **lésion cutanée** douloureuse au point d'injection.","prio":"P3","sec":"s3"},{"id":"fc-330-c1819b","poly":"cardio","fiche":"330","front":"Héparines : quels effets indésirables principaux ?","back":"Complications **hémorragiques** ; **TIH** (classique mais rare, immunoallergique).","prio":"P1","sec":"s3"},{"id":"fc-330-cb4dd4","poly":"cardio","fiche":"330","front":"Héparines : citer des effets indésirables plus rares ?","back":"**Ostéoporose**, **alopécie**, élévation des **transaminases**, **priapisme**, **insuffisance surrénalienne aiguë**.","prio":"P3","sec":"s3"},{"id":"fc-330-74206d","poly":"cardio","fiche":"330","front":"Quel est l'AVK de référence ?","back":"La **warfarine** (Coumadine®).","prio":"P2","sec":"s4"},{"id":"fc-330-5e0261","poly":"cardio","fiche":"330","front":"Fluindione : quelle restriction depuis 2017 ?","back":"**Instauration déconseillée** par l'ANSM (risque immunoallergique rare mais grave d'**insuffisance rénale**).","prio":"P1","sec":"s4"},{"id":"fc-330-b49319","poly":"cardio","fiche":"330","front":"Fluindione chez un patient bien équilibré depuis longtemps : faut-il la remplacer ?","back":"**Non** (complications survenant en règle dans les **6 mois**).","prio":"P2","sec":"s4"},{"id":"fc-330-e9c0af","poly":"cardio","fiche":"330","front":"Acénocoumarol (Sintrom®) : combien de prises par jour, et est-ce l'AVK recommandé ?","back":"**2 prises/j** ; ce **n'est pas** l'AVK recommandé.","prio":"P3","sec":"s4"},{"id":"fc-330-ec10c5","poly":"cardio","fiche":"330","front":"AVK : en combien de temps sont-ils pleinement efficaces ?","back":"**3 à 5 jours** de prise (longue demi-vie de certains facteurs).","prio":"P1","sec":"s4"},{"id":"fc-330-7670c7","poly":"cardio","fiche":"330","front":"AVK : pourquoi commencer par une héparine ?","back":"Délai d'action long : l'héparine assure l'anticoagulation jusqu'à ce que l'**INR** prouve le relais.","prio":"P1","sec":"s4"},{"id":"fc-330-7648fc","poly":"cardio","fiche":"330","front":"AVK : quel facteur a la demi-vie la plus courte ?","back":"Le **facteur VII** (4-6 h).","prio":"P3","sec":"s4"},{"id":"fc-330-520ce9","poly":"cardio","fiche":"330","front":"AVK : quel facteur a la demi-vie la plus longue ?","back":"Le **facteur II** (prothrombine, 50-120 h).","prio":"P3","sec":"s4"},{"id":"fc-330-1b5a46","poly":"cardio","fiche":"330","front":"Warfarine : quels dosages de comprimés ?","back":"**2 et 5 mg**.","prio":"P3","sec":"s4"},{"id":"fc-330-60ecd4","poly":"cardio","fiche":"330","front":"Relais héparine → AVK : quand introduire l'AVK ?","back":"**Tôt, dès J1** (sauf exception) ; non effectif avant **4 à 6 jours**.","prio":"P1","sec":"s4"},{"id":"fc-330-564cde","poly":"cardio","fiche":"330","front":"Relais héparine → AVK : quelles conditions pour arrêter l'héparine ?","back":"**Au moins 4 à 5 jours de chevauchement** ET **2 INR efficaces à 24 h d'intervalle**.","prio":"P1","sec":"s4"},{"id":"fc-330-5296ed","poly":"cardio","fiche":"330","front":"AVK dans la MTEV : quelle dose initiale ?","back":"Warfarine **5 mg** (ou acénocoumarol **4 mg**), plus faible chez le **sujet âgé**, puis adaptation à l'INR.","prio":"P2","sec":"s4"},{"id":"fc-330-ff1c12","poly":"cardio","fiche":"330","front":"INR : quelle valeur normale sans traitement ?","back":"**1**.","prio":"P1","sec":"s4"},{"id":"fc-330-98f567","poly":"cardio","fiche":"330","front":"AVK : quelle cible d'INR pour la plupart des indications ?","back":"Entre **2 et 3**.","prio":"P1","sec":"s4"},{"id":"fc-330-d87d87","poly":"cardio","fiche":"330","front":"AVK : qui fixe les cibles d'INR plus élevées ?","back":"Le **spécialiste** (ex. prothèse mécanique **mitrale**).","prio":"P2","sec":"s4"},{"id":"fc-330-06d24b","poly":"cardio","fiche":"330","front":"AVK : quand dit-on un patient correctement équilibré ?","back":"**Au moins 70 %** de ses INR dans la cible.","prio":"P1","sec":"s4"},{"id":"fc-330-823277","poly":"cardio","fiche":"330","front":"Rythme des INR sous AVK : de J0 à J14 ?","back":"**2 fois/semaine**.","prio":"P2","sec":"s4"},{"id":"fc-330-83a30a","poly":"cardio","fiche":"330","front":"Rythme des INR sous AVK : de J14 à J30, puis J30 à J60 ?","back":"J14-J30 : **1 fois/semaine** ; J30-J60 : **1 fois toutes les 2 semaines**.","prio":"P2","sec":"s4"},{"id":"fc-330-8f8fc5","poly":"cardio","fiche":"330","front":"Rythme des INR sous AVK : après J60 ?","back":"**1 fois/mois** (minimum au long cours).","prio":"P2","sec":"s4"},{"id":"fc-330-f0a99d","poly":"cardio","fiche":"330","front":"Automesure de l'INR : chez qui est-elle remboursée en France ?","back":"L'**enfant** et le **porteur de valve mécanique**.","prio":"P2","sec":"s4"},{"id":"fc-330-ac8a67","poly":"cardio","fiche":"330","front":"AVK : quels antidotes ?","back":"**PPSB** (très rapide) + **vitamine K** (en quelques heures).","prio":"P1","sec":"s4"},{"id":"fc-330-07a9fe","poly":"cardio","fiche":"330","front":"AVK et grossesse : quelle contre-indication ?","back":"**Tératogènes** : CI lors de la **première partie du 1er trimestre**.","prio":"P1","sec":"s4"},{"id":"fc-330-5f72f8","poly":"cardio","fiche":"330","front":"Dans quelles situations les AVK restent-ils préférés aux AOD ?","back":"**Valve mécanique**, **insuffisance rénale sévère**, **SAPL triple positif**.","prio":"P1","sec":"s4"},{"id":"fc-330-397e24","poly":"cardio","fiche":"330","front":"Éducation sous AVK : quels messages clés ?","back":"Éviter les **coprescriptions**, connaître les **seuils d'alerte** de l'INR, consulter si **saignement**, prévenir tout médecin.","prio":"P2","sec":"s4"},{"id":"fc-330-8f94f8","poly":"cardio","fiche":"330","front":"Citer les 3 AOD et leur activité ?","back":"**Dabigatran** (anti-IIa) ; **rivaroxaban** et **apixaban** (anti-Xa).","prio":"P1","sec":"s5"},{"id":"fc-330-5f5d19","poly":"cardio","fiche":"330","front":"AOD : délai d'efficacité après la première prise ?","back":"**Environ 2 heures** → pas de relais par héparine.","prio":"P1","sec":"s5"},{"id":"fc-330-b3c327","poly":"cardio","fiche":"330","front":"Dabigatran : quelle part d'élimination rénale ?","back":"**80 %**.","prio":"P1","sec":"s5"},{"id":"fc-330-653eca","poly":"cardio","fiche":"330","front":"Rivaroxaban et apixaban : quelle part d'élimination rénale ?","back":"Rivaroxaban **33 %** ; apixaban **25 %**.","prio":"P2","sec":"s5"},{"id":"fc-330-782fd8","poly":"cardio","fiche":"330","front":"Nombre de prises quotidiennes des AOD ?","back":"Dabigatran **2** ; apixaban **2** ; rivaroxaban **1** (2 au début du traitement d'une TVP/EP).","prio":"P2","sec":"s5"},{"id":"fc-330-67070f","poly":"cardio","fiche":"330","front":"AOD et rein : quel seuil de clairance ?","back":"**Déconseillés** si Cockcroft **< 30 à 25 mL/min** ; **CI** en insuffisance rénale sévère.","prio":"P1","sec":"s5"},{"id":"fc-330-beb3ed","poly":"cardio","fiche":"330","front":"AOD : à quels paramètres adapter la posologie ?","back":"**Âge**, **fonction rénale**, **poids**.","prio":"P2","sec":"s5"},{"id":"fc-330-0658fa","poly":"cardio","fiche":"330","front":"AOD : citer des médicaments en interaction ?","back":"**Macrolides**, **antiprotéases**, **azolés**, certains anticancéreux, **amiodarone**, **diltiazem**, **vérapamil**.","prio":"P2","sec":"s5"},{"id":"fc-330-930889","poly":"cardio","fiche":"330","front":"AOD et AVK : quelle classe éviter en association ?","back":"Les **anti-inflammatoires** (risque hémorragique accru).","prio":"P2","sec":"s5"},{"id":"fc-330-1c94ef","poly":"cardio","fiche":"330","front":"AOD : quelle surveillance biologique en routine ?","back":"**Aucune** ; le dosage du médicament est réservé à des situations particulières.","prio":"P1","sec":"s5"},{"id":"fc-330-4ab7e6","poly":"cardio","fiche":"330","front":"Sous AOD : TCA, TP et INR permettent-ils de juger l'efficacité ?","back":"**Non** : ils sont **perturbés** mais ne mesurent pas l'efficacité.","prio":"P1","sec":"s5"},{"id":"fc-330-3c2fa5","poly":"cardio","fiche":"330","front":"Dabigatran : quel antidote ?","back":"**Idarucizumab** (Praxbind®).","prio":"P1","sec":"s5"},{"id":"fc-330-b9b854","poly":"cardio","fiche":"330","front":"AOD vs AVK : quel avantage hémorragique majeur ?","back":"**Beaucoup moins d'hémorragies** globales et surtout **intracrâniennes**.","prio":"P1","sec":"s5"},{"id":"fc-330-e9878a","poly":"cardio","fiche":"330","front":"AOD vs AVK : quels inconvénients ?","back":"**Accumulation** si insuffisance rénale ; **observance** difficile à vérifier ; un peu plus d'hémorragies **digestives et génitales**.","prio":"P2","sec":"s5"},{"id":"fc-330-438f6a","poly":"cardio","fiche":"330","front":"AOD : quelles indications ?","back":"Traitement curatif de la **MTEV** (anti-Xa), prévention thromboembolique de la **FA**, prévention de la MTEV pour certains anti-Xa.","prio":"P2","sec":"s5"},{"id":"fc-330-c9b441","poly":"cardio","fiche":"330","front":"TVP/EP : posologie du rivaroxaban ?","back":"**15 mg 2 fois/j pendant 21 jours**, puis **20 mg 1 fois/j**.","prio":"P1","sec":"s5"},{"id":"fc-330-0b833c","poly":"cardio","fiche":"330","front":"TVP/EP : posologie de l'apixaban ?","back":"**10 mg 2 fois/j pendant 7 jours**, puis **5 mg 2 fois/j**.","prio":"P1","sec":"s5"},{"id":"fc-330-1a3dbb","poly":"cardio","fiche":"330","front":"MTEV : quelle place actuelle des AOD ?","back":"La **référence** de la prise en charge.","prio":"P2","sec":"s5"},{"id":"fc-330-1b77e5","poly":"cardio","fiche":"330","front":"FA : quel score guide la prescription d'un AOD ?","back":"Le score **CHA₂DS₂-VA** (doses souvent réduites après 80 ans).","prio":"P3","sec":"s5"},{"id":"fc-330-2acf09","poly":"cardio","fiche":"330","front":"AOD : quelles prescriptions sont des notions inacceptables ?","back":"AOD sur **valve mécanique**, **rétrécissement mitral** ou **insuffisance rénale sévère**.","prio":"P1","sec":"s5"},{"id":"fc-330-1d213a","poly":"cardio","fiche":"330","front":"Fibrinolytiques : quelles indications actuelles ?","back":"**Infarctus du myocarde**, **AVC**, **embolie pulmonaire grave**.","prio":"P1","sec":"s6"},{"id":"fc-330-e3711c","poly":"cardio","fiche":"330","front":"Fibrinolytiques : quel risque principal ?","back":"**Hémorragique significatif**, notamment **cérébral**.","prio":"P1","sec":"s6"},{"id":"fc-330-a8ce6b","poly":"cardio","fiche":"330","front":"SCA ST+ : quand préférer l'angioplastie primaire à la fibrinolyse ?","back":"Si faisable dans les **120 minutes**.","prio":"P1","sec":"s6"},{"id":"fc-330-b576a0","poly":"cardio","fiche":"330","front":"SCA ST+ fibrinolysé : quelle suite ?","back":"Transfert vers un centre avec salle de cathétérisme (**angioplastie de sauvetage** si échec).","prio":"P2","sec":"s6"},{"id":"fc-330-f144aa","poly":"cardio","fiche":"330","front":"SCA ST+ : à partir de quand le bénéfice de la reperfusion devient-il faible ?","back":"À partir de la **12ᵉ heure** (voire nul à partir de la 24ᵉ).","prio":"P2","sec":"s6"},{"id":"fc-330-700ecf","poly":"cardio","fiche":"330","front":"Fibrinolyse : quel est le seul inhibiteur de P2Y12 autorisé ?","back":"Le **clopidogrel** (charge **300 mg** uniquement avant 75 ans).","prio":"P1","sec":"s6"},{"id":"fc-330-e82998","poly":"cardio","fiche":"330","front":"Fibrinolyse : quelles contre-indications absolues cérébrales ?","back":"ATCD d'**AVC hémorragique** ; **AVC < 6 mois** ; malformation artérioveineuse ou tumeur cérébrale ; **traumatisme cérébral < 1 mois**.","prio":"P1","sec":"s6"},{"id":"fc-330-1888f5","poly":"cardio","fiche":"330","front":"Fibrinolyse : quelles contre-indications absolues hors cerveau ?","back":"**Hémorragie digestive < 1 mois** ; **dissection aortique** ; ponction/biopsie hépatique ou rénale ou PL **< 24 h** ; anomalie de l'hémostase.","prio":"P1","sec":"s6"},{"id":"fc-330-c64719","poly":"cardio","fiche":"330","front":"EP grave : quel traitement ?","back":"**Fibrinolyse** (réanimation/soins intensifs) ; **embolectomie** si thrombolyse contre-indiquée.","prio":"P1","sec":"s6"},{"id":"fc-330-f00a6e","poly":"cardio","fiche":"330","front":"EP de gravité intermédiaire : fibrinolyse systématique ?","back":"**Non**.","prio":"P2","sec":"s6"},{"id":"fc-330-095a6c","poly":"cardio","fiche":"330","front":"Patient fibrinolysé : quelle héparine ?","back":"L'**HNF**.","prio":"P2","sec":"s6"},{"id":"fc-330-5acbc6","poly":"cardio","fiche":"330","front":"TVP : quand discuter une thrombolyse ?","back":"Pas en 1re intention ; seulement **syndrome obstructif sévère** ou **phlegmatia caerulea** (sauvetage de membre).","prio":"P2","sec":"s6"},{"id":"fc-330-f7adfa","poly":"cardio","fiche":"330","front":"SCA sans contre-indication hémorragique : quelle association antithrombotique ?","back":"**Trithérapie** : **aspirine** + **inhibiteur de P2Y12** + **anticoagulant**.","prio":"P1","sec":"s7"},{"id":"fc-330-a8bde8","poly":"cardio","fiche":"330","front":"SCA ST+ traité par angioplastie primaire : quel P2Y12 en 1re intention ?","back":"**Prasugrel** ou **ticagrélor**.","prio":"P1","sec":"s7"},{"id":"fc-330-db180f","poly":"cardio","fiche":"330","front":"SCA ST- : faut-il une bithérapie antiplaquettaire dès l'admission ?","back":"**Non** avant la coronarographie (plus de saignements) ; envisageable si coronarographie prévue **au-delà de 24 h**.","prio":"P2","sec":"s7"},{"id":"fc-330-f93609","poly":"cardio","fiche":"330","front":"SCA ST- à haut risque : quand utiliser l'HNF IVSE, et à quelle dose ?","back":"Si HBPM et fondaparinux contre-indiqués (**insuffisance rénale chronique sévère**) : **400-600 UI/kg/24 h**.","prio":"P2","sec":"s7"},{"id":"fc-330-73df27","poly":"cardio","fiche":"330","front":"SCA ST- à haut risque : combien de temps dure l'anticoagulation SC ?","back":"De l'**admission en Usic** jusqu'à l'**angioplastie** ou au **pontage**.","prio":"P2","sec":"s7"},{"id":"fc-330-f7cebf","poly":"cardio","fiche":"330","front":"Sortie après SCA : quel traitement antiplaquettaire ?","back":"**Double antiagrégation** classiquement **12 mois**, **aspirine au long cours**.","prio":"P1","sec":"s7"},{"id":"fc-330-d080d7","poly":"cardio","fiche":"330","front":"Échec du clopidogrel : quelle cause penser ?","back":"Un **mauvais métabolisme** (15-25 % des patients, CYP2C19).","prio":"P2","sec":"s7"},{"id":"fc-330-856e49","poly":"cardio","fiche":"330","front":"SCA avec anticoagulant oral justifié (FA, thrombus VG) : quelle association ?","back":"Anticoagulant à pleine dose + **clopidogrel pendant 12 mois**, puis anticoagulant seul.","prio":"P2","sec":"s7"},{"id":"fc-330-84d291","poly":"cardio","fiche":"330","front":"SCA avec anticoagulant oral : quand une trithérapie est-elle possible, et combien de temps ?","back":"Faible risque hémorragique + haut risque ischémique : durée limitée, habituellement **1 mois**.","prio":"P3","sec":"s7"},{"id":"fc-330-f4960d","poly":"cardio","fiche":"330","front":"SCA : citer des facteurs de risque hémorragique ?","back":"**Âge > 75 ans**, **sexe féminin**, **insuffisance rénale**, diathèse hémorragique, AVC ancien, **poids < 65 kg**, chirurgie/traumatisme récents.","prio":"P3","sec":"s7"},{"id":"fc-330-0c0ae5","poly":"cardio","fiche":"330","front":"Après un SCA et/ou un stent : quelle conduite pour un geste invasif hémorragique non urgent ?","back":"Le **reporter**.","prio":"P2","sec":"s7"},{"id":"fc-330-0d7697","poly":"cardio","fiche":"330","front":"Prévention secondaire athérothrombotique : quelle alternative à l'aspirine ?","back":"Le **clopidogrel** (intolérance à l'aspirine ou atteinte polyvasculaire compliquée, notamment AOMI).","prio":"P1","sec":"s8"},{"id":"fc-330-43de42","poly":"cardio","fiche":"330","front":"Prévention secondaire : quelle dose d'aspirine (item 221) ?","back":"**75 à 325 mg/j**.","prio":"P2","sec":"s8"},{"id":"fc-330-f9ce4c","poly":"cardio","fiche":"330","front":"Prévention secondaire : quelle dose d'entretien du clopidogrel ?","back":"**75 mg/j**.","prio":"P2","sec":"s8"},{"id":"fc-330-ffbce8","poly":"cardio","fiche":"330","front":"AOMI symptomatique : quel antiagrégant, et pour quel bénéfice ?","back":"**Aspirine ou clopidogrel** pour réduire **infarctus et AVC**.","prio":"P2","sec":"s8"},{"id":"fc-330-d90ec9","poly":"cardio","fiche":"330","front":"AOMI asymptomatique (IPS < 0,90) : faut-il un antiagrégant ?","back":"**Débattu**, sauf autre localisation athéromateuse (ex. cardiopathie ischémique).","prio":"P3","sec":"s8"},{"id":"fc-330-f031f1","poly":"cardio","fiche":"330","front":"Aspirine en prévention primaire chez le diabétique : est-elle systématique ?","back":"**Non** : seulement si très haut risque vasculaire **et** faible risque de saignement.","prio":"P1","sec":"s8"},{"id":"fc-330-1038c0","poly":"cardio","fiche":"330","front":"Angioplastie artérielle des membres inférieurs : durée de la bithérapie antiplaquettaire ?","back":"**1 à 6 mois** selon le geste et sa localisation.","prio":"P3","sec":"s8"},{"id":"fc-330-708ffc","poly":"cardio","fiche":"330","front":"Après stent coronarien : combien de temps retarder un acte invasif hémorragique non urgent (p. 562) ?","back":"**3 à 6 mois** (points clés : **au moins 1 à 3 mois**).","prio":"P1","sec":"s8"},{"id":"fc-330-f83ddb","poly":"cardio","fiche":"330","front":"Geste à risque hémorragique modéré sous aspirine en prévention secondaire : conduite ?","back":"**Ne pas arrêter** l'aspirine (chirurgie, fibroscopie avec biopsie, stomatologie…).","prio":"P1","sec":"s8"},{"id":"fc-330-cdecda","poly":"cardio","fiche":"330","front":"Geste à risque hémorragique très important sous aspirine : conduite ?","back":"Arrêt **court**, **5 jours avant**, reprise **le plus tôt possible**.","prio":"P1","sec":"s8"},{"id":"fc-330-738075","poly":"cardio","fiche":"330","front":"Citer des chirurgies à risque hémorragique très important justifiant d'arrêter l'aspirine ?","back":"Chirurgie **ORL**, **urologique**, **neurologique**.","prio":"P2","sec":"s8"},{"id":"fc-330-2d6944","poly":"cardio","fiche":"330","front":"TVP/EP : quel bilan biologique avant traitement anticoagulant ?","back":"**Hémogramme** avec plaquettes, **TP**, **TCA**, **fibrinogène**, **créatininémie** avec clairance.","prio":"P2","sec":"s9"},{"id":"fc-330-d7ecf6","poly":"cardio","fiche":"330","front":"TVP/EP traitée par AOD anti-Xa : faut-il une héparine préalable ou un relais AVK ?","back":"**Non** : prescription d'emblée.","prio":"P1","sec":"s9"},{"id":"fc-330-e37807","poly":"cardio","fiche":"330","front":"TVP/EP sous AVK : quelle cible d'INR ?","back":"**2,5** (entre 2 et 3).","prio":"P2","sec":"s9"},{"id":"fc-330-ee78bc","poly":"cardio","fiche":"330","front":"TVP proximale et/ou EP : durée minimale d'anticoagulation ?","back":"Au minimum **3 mois**.","prio":"P3","sec":"s9"},{"id":"fc-330-63a410","poly":"cardio","fiche":"330","front":"TVP/EP : posologies curatives de la daltéparine et de la nadroparine (2 injections) ?","back":"Daltéparine **100 UI/kg/12 h** ; nadroparine **85 UI/kg/12 h**.","prio":"P3","sec":"s9"},{"id":"fc-330-7e07d3","poly":"cardio","fiche":"330","front":"Quelles HBPM ont l'AMM dans l'EP ?","back":"**Énoxaparine** et **tinzaparine** seulement.","prio":"P3","sec":"s9"},{"id":"fc-330-083677","poly":"cardio","fiche":"330","front":"Fraxodi® (nadroparine 1 injection/j) : quelle posologie curative ?","back":"**171 UI/kg/24 h**.","prio":"P3","sec":"s9"},{"id":"fc-330-79fe4b","poly":"cardio","fiche":"330","front":"Prévention de la MTEV : l'aspirine est-elle indiquée ?","back":"**Non** (mobilisation précoce, ± compression, anticoagulant injectable).","prio":"P1","sec":"s9"},{"id":"fc-330-519ddf","poly":"cardio","fiche":"330","front":"Prévention de la MTEV en chirurgie : quelles molécules ?","back":"**Énoxaparine** ou **fondaparinux** ; **AOD** possibles en postopératoire selon protocoles.","prio":"P2","sec":"s9"},{"id":"fc-330-15ef7d","poly":"cardio","fiche":"330","front":"Prévention de la MTEV en milieu médical : sur quels critères ?","back":"**Pathologie** (IC, insuffisance respiratoire, rhumatismale…), possibilité de **lever précoce**, **terrain** (âge, cancer, ATCD de MTEV, obésité).","prio":"P2","sec":"s9"},{"id":"fc-330-c23702","poly":"cardio","fiche":"330","front":"Prévention de la MTEV : dose d'énoxaparine en milieu médical ?","back":"**0,4 mL/24 h SC**.","prio":"P1","sec":"s9"},{"id":"fc-330-ad668d","poly":"cardio","fiche":"330","front":"Prévention de la MTEV : dose de fondaparinux ?","back":"**2,5 mg/24 h SC**.","prio":"P2","sec":"s9"},{"id":"fc-330-4b048a","poly":"cardio","fiche":"330","front":"Prévention de la MTEV par HBPM : durée en chirurgie orthopédique ?","back":"**4 à 6 semaines** (prothèse de hanche) ; **10-15 jours** (prothèse de genou).","prio":"P2","sec":"s9"},{"id":"fc-330-78560c","poly":"cardio","fiche":"330","front":"Voyage de plus de 6 h : quelles mesures de prévention de la MTEV ?","back":"Pas de vêtements serrés, **s'hydrater**, contracter les **mollets** ; si facteurs prédisposants : **contention classe 2 ou 3** ± HBPM préventive.","prio":"P3","sec":"s9"},{"id":"fc-330-674696","poly":"cardio","fiche":"330","front":"Héparine : pourquoi garder une durée la plus courte possible ?","back":"Pour **prévenir la TIH**.","prio":"P2","sec":"s9"},{"id":"fc-330-6deb28","poly":"cardio","fiche":"330","front":"Avant de prescrire un AOD : quel paramètre est capital ?","back":"La **clairance de la créatinine**.","prio":"P1","sec":"s10"},{"id":"fc-330-050daa","poly":"cardio","fiche":"330","front":"Insuffisance rénale sévère : quel anticoagulant au long cours ?","back":"L'**AVK** (préféré à l'AOD).","prio":"P2","sec":"s10"},{"id":"fc-330-d2ed59","poly":"cardio","fiche":"330","front":"Valve mécanique ou RM serré : quel anticoagulant oral ?","back":"**AVK** (AOD = **contre-indication absolue**).","prio":"P1","sec":"s10"},{"id":"fc-330-f6e815","poly":"cardio","fiche":"330","front":"Prothèse valvulaire mécanique : combien de temps dure l'AVK ?","back":"**À vie** (débuté dès les premiers jours postopératoires).","prio":"P2","sec":"s10"},{"id":"fc-330-72de14","poly":"cardio","fiche":"330","front":"Valve mécanique : de quoi dépend l'INR cible ?","back":"De la **thrombogénicité de la prothèse** et des **facteurs de risque du patient**.","prio":"P2","sec":"s10"},{"id":"fc-330-bf2ddd","poly":"cardio","fiche":"330","front":"Valve mécanique : quels facteurs de risque patient augmentent l'INR cible ?","back":"Remplacement **mitral** ou **tricuspide**, ATCD **thromboembolique**, **FA**, **sténose mitrale**, **FEVG < 35 %**.","prio":"P3","sec":"s10"},{"id":"fc-330-88d7a9","poly":"cardio","fiche":"330","front":"Valve mécanique peu thrombogène : quelle cible d'INR ?","back":"**2,5** sans facteur de risque ; **3,0** si au moins un.","prio":"P2","sec":"s10"},{"id":"fc-330-723dfb","poly":"cardio","fiche":"330","front":"Valve mécanique moyennement ou très thrombogène : quelle cible d'INR ?","back":"Moyen : **3,0 ou 3,5** ; élevé (valves à bille ou à disque) : **3,5 ou 4,0**.","prio":"P3","sec":"s10"},{"id":"fc-330-8285a7","poly":"cardio","fiche":"330","front":"FA sous AVK (points clés FA) : quelle cible d'INR ?","back":"**2,5** (2 à 3), sauf valve mécanique **mitrale** : **3,7**.","prio":"P3","sec":"s10"},{"id":"fc-330-32b3ef","poly":"cardio","fiche":"330","front":"Valve mécanique et geste programmé : quelle conduite pour l'AVK ?","back":"Arrêt avec **relais préopératoire par héparine curative** (haut risque thrombotique).","prio":"P2","sec":"s10"},{"id":"fc-330-8abf7f","poly":"cardio","fiche":"330","front":"Grossesse : quel anticoagulant pour traiter une MTEV ?","back":"Les **HBPM**.","prio":"P1","sec":"s10"},{"id":"fc-330-342821","poly":"cardio","fiche":"330","front":"Bioprothèse : quand les AOD sont-ils autorisés ?","back":"**Au-delà de 3 mois** si l'indication n'est pas valvulaire (dès le postopératoire si FA sur bioprothèse mitrale).","prio":"P2","sec":"s10"},{"id":"fc-330-200d8a","poly":"cardio","fiche":"330","front":"Bioprothèse aortique : quel traitement les 3 premiers mois ?","back":"**Aspirine** ou **AVK** pendant **3 mois**.","prio":"P3","sec":"s10"},{"id":"fc-330-a978ee","poly":"cardio","fiche":"330","front":"Valve mécanique sous AVK : faut-il ajouter un antiagrégant ?","back":"**Non** (pratique européenne), sauf stent récent ou thromboembolie malgré INR efficace.","prio":"P2","sec":"s10"},{"id":"fc-330-fb60f1","poly":"cardio","fiche":"330","front":"Geste programmé sous AVK à risque hémorragique modéré : conduite ?","back":"**Ne pas interrompre** l'AVK, après avoir vérifié un INR dans la **limite basse** de la fourchette.","prio":"P1","sec":"s11"},{"id":"fc-330-beef46","poly":"cardio","fiche":"330","front":"Geste sous AVK à risque hémorragique plus important : quel INR viser ?","back":"**< 1,5** (**< 1,2 en neurochirurgie**).","prio":"P1","sec":"s11"},{"id":"fc-330-96dd94","poly":"cardio","fiche":"330","front":"AVK et risque thrombotique modéré : conduite avant un geste ?","back":"Arrêt **3 à 4 jours**, **sans relais**, reprise le soir même.","prio":"P1","sec":"s11"},{"id":"fc-330-18345a","poly":"cardio","fiche":"330","front":"Citer des situations à risque thrombotique modéré sous AVK ?","back":"**FA sans antécédent embolique**, TVP/EP **au-delà du 3e mois**, MTEV à risque modéré.","prio":"P2","sec":"s11"},{"id":"fc-330-775e95","poly":"cardio","fiche":"330","front":"AVK et risque thrombotique élevé : conduite avant un geste ?","back":"Arrêt **4 à 5 jours avant** + **relais par héparine à dose curative**.","prio":"P1","sec":"s11"},{"id":"fc-330-6a534f","poly":"cardio","fiche":"330","front":"Citer les situations à risque thrombotique élevé sous AVK ?","back":"**Valve mécanique**, **FA avec antécédent embolique**, **TVP proximale/EP < 3 mois**, **MTEV récidivante idiopathique**.","prio":"P1","sec":"s11"},{"id":"fc-330-97dfe7","poly":"cardio","fiche":"330","front":"Après un geste sous AVK (tableau HAS 22.8) : dans quel délai reprendre l'AVK ?","back":"Dans les **24-48 h**.","prio":"P1","sec":"s11"},{"id":"fc-330-83b77b","poly":"cardio","fiche":"330","front":"Après un geste : au plus tôt quand reprendre une héparine curative ?","back":"**Pas avant la 6ᵉ heure** postopératoire, si le risque hémorragique est contrôlé.","prio":"P1","sec":"s11"},{"id":"fc-330-d8c008","poly":"cardio","fiche":"330","front":"Relais par héparine autour d'un geste : pourquoi ne pas le faire « par sécurité » ?","back":"Source de complications **hémorragiques et thrombotiques** → réservé au haut risque thrombotique.","prio":"P2","sec":"s11"},{"id":"fc-330-9216f3","poly":"cardio","fiche":"330","front":"MTEV récidivante idiopathique : définition ?","back":"**Au moins 2 épisodes**, dont au moins un **sans facteur déclenchant**.","prio":"P2","sec":"s11"},{"id":"fc-330-b54419","poly":"cardio","fiche":"330","front":"MTEV à haut risque et geste programmé : quel dispositif se discute ?","back":"Un **filtre cave** préopératoire, au cas par cas.","prio":"P3","sec":"s11"},{"id":"fc-330-86e639","poly":"cardio","fiche":"330","front":"Héparines : fréquence des accidents hémorragiques ?","back":"**1 à 4 %** en curatif ; **1 à 2 %** en préventif.","prio":"P1","sec":"s12"},{"id":"fc-330-68a685","poly":"cardio","fiche":"330","front":"Héparine : quelles associations médicamenteuses augmentent le risque hémorragique ?","back":"Un autre **antithrombotique** (AVK, antiagrégant) ou un **AINS**.","prio":"P2","sec":"s12"},{"id":"fc-330-fcd71a","poly":"cardio","fiche":"330","front":"Héparine : citer des facteurs de risque hémorragique liés au patient ?","back":"**Âge**, **sexe féminin**, **faible poids**, intensité et durée de l'anticoagulation, **insuffisance rénale**, thrombopénie…","prio":"P3","sec":"s12"},{"id":"fc-330-a0e3a0","poly":"cardio","fiche":"330","front":"Héparine au long cours : quelle anémie typique sans saignement visible ?","back":"Anémie **microcytaire ferriprive** (d'où une NFS régulière).","prio":"P2","sec":"s12"},{"id":"fc-330-9a1131","poly":"cardio","fiche":"330","front":"Surdosage biologique sous HNF : quel seuil de TCA ?","back":"**TCA > 3 fois** le témoin (ou héparinémie élevée).","prio":"P2","sec":"s12"},{"id":"fc-330-a53eeb","poly":"cardio","fiche":"330","front":"Saignement mineur ou surdosage asymptomatique sous héparine : conduite ?","back":"**Adapter les doses** + surveillance clinique et biologique rapprochée.","prio":"P1","sec":"s12"},{"id":"fc-330-53c629","poly":"cardio","fiche":"330","front":"Saignement majeur sous héparine : conduite ?","back":"Peser le risque d'arrêt ; **remplissage** IV puis **transfusion** si besoin ; discuter le **sulfate de protamine**.","prio":"P1","sec":"s12"},{"id":"fc-330-58fe70","poly":"cardio","fiche":"330","front":"Thrombopénie de type I sous héparine : caractéristiques ?","back":"**Précoce**, **bénigne**, **non immune**, sans thrombose ; régresse même si on poursuit l'héparine.","prio":"P2","sec":"s12"},{"id":"fc-330-5c416e","poly":"cardio","fiche":"330","front":"TIH (type II) : quel mécanisme ?","back":"**Immunoallergique** : anticorps contre le **PF4** modifié par l'héparine → activation plaquettaire et de la coagulation.","prio":"P1","sec":"s12"},{"id":"fc-330-c9e56b","poly":"cardio","fiche":"330","front":"TIH : quel est le danger principal ?","back":"**Thrombotique** : thromboses veineuses (**80 %**) et/ou artérielles (**20 %**), pas hémorragique (sauf CIVD).","prio":"P1","sec":"s12"},{"id":"fc-330-dec8a4","poly":"cardio","fiche":"330","front":"TIH : quel délai typique d'apparition ?","back":"**5 à 8 jours** après le début de l'héparine.","prio":"P1","sec":"s12"},{"id":"fc-330-722a42","poly":"cardio","fiche":"330","front":"TIH : quand peut-elle survenir dès J1 ?","back":"Si exposition à l'héparine dans les **3 mois** précédents.","prio":"P1","sec":"s12"},{"id":"fc-330-f8a2a6","poly":"cardio","fiche":"330","front":"TIH sous HBPM : particularité du délai ?","back":"**Plus long** (parfois plus de 3 semaines).","prio":"P2","sec":"s12"},{"id":"fc-330-9b4ffd","poly":"cardio","fiche":"330","front":"TIH : quels seuils plaquettaires doivent la faire évoquer (item 330) ?","back":"Plaquettes **< 100 G/L** et/ou **chute relative de 30 à 50 %** sur deux numérations.","prio":"P1","sec":"s12"},{"id":"fc-330-9abd9e","poly":"cardio","fiche":"330","front":"TIH : quels signes cliniques ou biologiques non plaquettaires l'évoquent ?","back":"Thrombose **nouvelle ou extensive** sous héparine ; **résistance à l'HNF** ; placards au point d'injection ; rarement insuffisance surrénalienne aiguë.","prio":"P1","sec":"s12"},{"id":"fc-330-59fad6","poly":"cardio","fiche":"330","front":"TIH, chapitre MTEV : quels seuils plaquettaires ?","back":"**< 150 G/L** ou baisse de **50 %** par rapport à avant traitement.","prio":"P3","sec":"s12"},{"id":"fc-330-52ec12","poly":"cardio","fiche":"330","front":"Suspicion de TIH : première étape biologique ?","back":"**Confirmer la thrombopénie** sur tube **citraté** et/ou capillaire, avec contrôle sur **lame**.","prio":"P2","sec":"s12"},{"id":"fc-330-5bca7c","poly":"cardio","fiche":"330","front":"TIH : quel test immunologique, et quelle valeur ?","back":"**ELISA anti-PF4** : meilleure valeur prédictive **négative** que positive.","prio":"P3","sec":"s12"},{"id":"fc-330-fb8e4a","poly":"cardio","fiche":"330","front":"Suspicion forte de TIH : conduite ?","back":"**Arrêter l'héparine** et la remplacer par un antithrombotique d'action immédiate, **sans attendre** la biologie.","prio":"P2","sec":"s12"},{"id":"fc-330-3d85bc","poly":"cardio","fiche":"330","front":"Prévention primaire de la TIH : quels 3 principes ?","back":"Héparine **la plus courte possible** ; **relais précoce** par AOD ou AVK ; préférer **HBPM ou fondaparinux**.","prio":"P1","sec":"s12"},{"id":"fc-330-8b4097","poly":"cardio","fiche":"330","front":"TIH : avec quelle héparine et dans quel contexte est-elle plus fréquente ?","back":"Avec l'**HNF** ; en **chirurgie** (cardiaque, orthopédique) plus qu'en médecine.","prio":"P3","sec":"s12"},{"id":"fc-330-714e77","poly":"cardio","fiche":"330","front":"TIH : quelles complications graves possibles ?","back":"**CIVD** (10-20 %) ; thromboses artérielles (aorte abdominale) ; complications **neurologiques** (9,5 %).","prio":"P3","sec":"s12"},{"id":"fc-330-dd84b7","poly":"cardio","fiche":"330","front":"Sous HBPM (item 330) : quand la surveillance des plaquettes reste-t-elle préconisée ?","back":"En **chirurgie ou traumatologie** et chez les patients à risque (héparine dans les **6 mois**, comorbidités **importantes**).","prio":"P3","sec":"s12"},{"id":"fc-330-50c6fa","poly":"cardio","fiche":"330","front":"AVK : quelle place dans la iatrogénie ?","back":"**1re cause iatrogène d'hospitalisation** (13 % des hospitalisations pour effet indésirable médicamenteux).","prio":"P3","sec":"s13"},{"id":"fc-330-ab97ef","poly":"cardio","fiche":"330","front":"Surdosage en AVK asymptomatique : quelle prise en charge ?","back":"Le plus souvent **ambulatoire**, selon l'**INR mesuré** et l'**INR cible**.","prio":"P1","sec":"s13"},{"id":"fc-330-3501aa","poly":"cardio","fiche":"330","front":"Cible INR 2,5, INR mesuré entre 4 et 6 sans saignement : conduite ?","back":"**Sauter une prise**, pas de vitamine K ; adapter à la reprise.","prio":"P2","sec":"s13"},{"id":"fc-330-2a88df","poly":"cardio","fiche":"330","front":"Cible INR 2,5, INR mesuré entre 6 et 10 sans saignement : conduite ?","back":"**Arrêt de l'AVK** + **1 à 2 mg de vitamine K per os**.","prio":"P2","sec":"s13"},{"id":"fc-330-ec4e3c","poly":"cardio","fiche":"330","front":"Cible INR 2,5, INR > 10 sans saignement : conduite ?","back":"**Arrêt de l'AVK** + **5 mg de vitamine K per os** (½ ampoule buvable adulte).","prio":"P2","sec":"s13"},{"id":"fc-330-edba87","poly":"cardio","fiche":"330","front":"Cible INR 3, INR > 10 sans saignement : conduite ?","back":"**Avis spécialisé sans délai** ou **hospitalisation**.","prio":"P3","sec":"s13"},{"id":"fc-330-dfeb57","poly":"cardio","fiche":"330","front":"Cible INR 3, INR mesuré entre 4 et 6 sans saignement : conduite ?","back":"**Ni saut de prise ni vitamine K** ; adapter la posologie.","prio":"P3","sec":"s13"},{"id":"fc-330-f67702","poly":"cardio","fiche":"330","front":"Cible INR 3, INR entre 6 et 10 sans saignement : conduite ?","back":"**Sauter une prise** ; avis spécialisé pour discuter 1 à 2 mg de vitamine K per os.","prio":"P3","sec":"s13"},{"id":"fc-330-97fba7","poly":"cardio","fiche":"330","front":"Après tout surdosage en AVK : quelles mesures communes ?","back":"**Rechercher la cause**, **INR de contrôle le lendemain**, puis surveillance comme à l'instauration.","prio":"P1","sec":"s13"},{"id":"fc-330-9af2e1","poly":"cardio","fiche":"330","front":"Hémorragie sous AVK : quels critères de gravité ?","back":"**Non contrôlable** ; **instabilité hémodynamique** ; besoin d'un **geste hémostatique** ; besoin d'une **transfusion** ; localisation menaçant le **pronostic vital ou fonctionnel**.","prio":"P1","sec":"s13"},{"id":"fc-330-4cf799","poly":"cardio","fiche":"330","front":"Hémorragie sous AVK : combien de critères pour la dire grave ?","back":"**Au moins un** des 5.","prio":"P1","sec":"s13"},{"id":"fc-330-446590","poly":"cardio","fiche":"330","front":"Hémorragie non grave sous AVK : conduite ?","back":"Souvent **ambulatoire** ; **INR en urgence** ; corriger un surdosage ; **rechercher la cause**.","prio":"P2","sec":"s13"},{"id":"fc-330-114d4f","poly":"cardio","fiche":"330","front":"Citer des gestes hémostatiques locaux sous anticoagulant ?","back":"**Compression** (suture), colle à la **fibrine/thrombine**, **adrénaline** locale, **embolisation**.","prio":"P3","sec":"s13"},{"id":"fc-330-be00a7","poly":"cardio","fiche":"330","front":"Hémorragie grave sous AVK : quels antidotes ?","back":"**CCP/PPSB** (très rapide mais bref) **+ vitamine K** ; hospitalisation et arrêt des AVK.","prio":"P2","sec":"s13"},{"id":"fc-330-bcc4df","poly":"cardio","fiche":"330","front":"Hémorragie grave sous AVK : faut-il attendre l'INR pour traiter ?","back":"**Non** : traitement instauré sans attendre le résultat.","prio":"P2","sec":"s13"},{"id":"fc-330-4a09ff","poly":"cardio","fiche":"330","front":"Hémorragie grave sous AVK : quand contrôler l'INR après le CCP ?","back":"**30 min** après (dose complémentaire si INR > 1,5), puis à **6-8 h**, puis 1 fois/j.","prio":"P3","sec":"s13"},{"id":"fc-330-7bae26","poly":"cardio","fiche":"330","front":"Après une hémorragie grave sous AVK : quelle suite ?","back":"Indication de l'AVK **à nouveau pesée** ; relais par **héparine** si anticoagulation impérative.","prio":"P3","sec":"s13"},{"id":"fc-330-3aebb0","poly":"cardio","fiche":"330","front":"Traumatisme crânien sous AVK : conduite ?","back":"**Hospitalisation ≥ 24 h** + **scanner cérébral en urgence**.","prio":"P1","sec":"s13"},{"id":"fc-330-ad3063","poly":"cardio","fiche":"330","front":"Polytraumatisé sous AVK : conduite ?","back":"**INR en urgence** ; conduite d'une hémorragie grave ou non grave selon la gravité.","prio":"P2","sec":"s13"},{"id":"fc-330-b9a96d","poly":"cardio","fiche":"330","front":"Prévention des hémorragies sous AVK : quelles mesures ?","back":"**Éducation**, vigilance sur les **interactions**, **automesure** de l'INR.","prio":"P2","sec":"s13"},{"id":"fc-330-f25333","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quel est le meilleur antidote ?","back":"Le **temps** écoulé depuis la dernière prise (demi-vie courte).","prio":"P1","sec":"s14"},{"id":"fc-330-d4717b","poly":"cardio","fiche":"330","front":"Anti-Xa (rivaroxaban, apixaban) : comment les antagoniser ?","back":"**PPSB** ou **Feiba®** (antidote spécifique en cours de commercialisation).","prio":"P1","sec":"s14"},{"id":"fc-330-26dd18","poly":"cardio","fiche":"330","front":"Feiba® : de quoi s'agit-il ?","back":"Mélange de **PPSB** et de **facteur VIII**.","prio":"P3","sec":"s14"},{"id":"fc-330-070dda","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quelles informations noter ?","back":"Âge, poids, molécule, dose, prises/j, **heure de la dernière prise**, indication.","prio":"P1","sec":"s14"},{"id":"fc-330-d193ed","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quels prélèvements ?","back":"**Créatinine** (Cockcroft) + **dosage spécifique** du médicament ; contacter le laboratoire d'hémostase.","prio":"P2","sec":"s14"},{"id":"fc-330-71f80b","poly":"cardio","fiche":"330","front":"Saignement actif sous AOD : faut-il attendre le dosage du médicament ?","back":"**Non** : la conduite n'attend pas son résultat.","prio":"P1","sec":"s14"},{"id":"fc-330-c41fd6","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quelles étapes après le recueil d'informations ?","back":"**Prélever**, contacter l'**hémostase**, **interrompre** le traitement, **antagoniser** si besoin.","prio":"P2","sec":"s14"},{"id":"fc-330-0d4792","poly":"cardio","fiche":"330","front":"Quelles sont les notions indispensables de l'item antithrombotiques ?","back":"**Éducation** sous AVK et AOD ; pas d'AOD sur valve mécanique ou RM ; savoir faire un **relais héparine-AVK**.","prio":"P2","sec":"s15"},{"id":"fc-330-731f53","poly":"cardio","fiche":"330","front":"HBPM ou AOD en insuffisance rénale sévère : quel statut ?","back":"**Notion inacceptable**.","prio":"P2","sec":"s15"},{"id":"fc-330-a30024","poly":"cardio","fiche":"330","front":"Aspirine et acte à risque très important : quelle erreur éviter sur le délai d'arrêt ?","back":"L'arrêter **plus de 5 jours** avant.","prio":"P2","sec":"s15"},{"id":"fc-330-c91e4b","poly":"cardio","fiche":"330","front":"Antidotes : citer celui de l'HNF, des AVK, du dabigatran et des anti-Xa ?","back":"**P**rotamine (héparine), **K** + PPSB (AVK), **I**darucizumab (dabigatran), PPSB/Feiba® (anti-Xa).","prio":"P2","sec":"s15"},{"id":"fc-331-afccaa","poly":"cardio","fiche":"331","front":"Mort subite (OMS) : quelle définition ?","back":"Mort **instantanée et soudaine** liée à une maladie aiguë, symptômes annonciateurs de quelques minutes, **1 heure** au plus.","prio":"P2","sec":"s1"},{"id":"fc-331-a621f0","poly":"cardio","fiche":"331","front":"Arrêt cardiocirculatoire : quelle définition ?","back":"Plus d'activité mécanique du cœur : **absence de pouls** + **apnée** ou respiration agonique (**gasping**).","prio":"P1","sec":"s1"},{"id":"fc-331-b05d99","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : sur quoi repose le diagnostic positif ?","back":"**Absence de réponse** + **ventilation inefficace**.","prio":"P1","sec":"s1"},{"id":"fc-331-09dbfe","poly":"cardio","fiche":"331","front":"Arrêt cardiaque récupéré : quelle définition ?","back":"Retour d'une **hémodynamique stable** (pouls et PA convenables) = « réanimé avec succès ».","prio":"P2","sec":"s1"},{"id":"fc-331-1c60f3","poly":"cardio","fiche":"331","front":"Arrêt cardiaque réfractaire : quelle définition française ?","back":"Pas de circulation spontanée après **30 minutes** de réanimation médicale bien conduite.","prio":"P1","sec":"s1"},{"id":"fc-331-f5e612","poly":"cardio","fiche":"331","front":"No-flow : quelle définition ?","back":"Intervalle entre l'arrêt et le **début de la réanimation**, sans mécanique cardiaque efficace.","prio":"P2","sec":"s1"},{"id":"fc-331-841c5e","poly":"cardio","fiche":"331","front":"Low-flow : quelle définition ?","back":"Durée de **réanimation** sans retour d'une hémodynamique convenable (pouls et PA stables).","prio":"P2","sec":"s1"},{"id":"fc-331-bbbdff","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quel est le déterminant le plus important de la survie ?","back":"Le **délai** entre l'arrêt et le début de la réanimation (durée du **no-flow**).","prio":"P1","sec":"s1"},{"id":"fc-331-73d114","poly":"cardio","fiche":"331","front":"Au-delà de 10 min sans hémodynamique : quel pronostic, et quelle exception ?","back":"Récupération et survie **très faibles**, sauf en cas d'**hypothermie**.","prio":"P1","sec":"s1"},{"id":"fc-331-13f4ec","poly":"cardio","fiche":"331","front":"No-flow de plus de 5 min : quel pronostic ?","back":"Pronostic et chances de survie sans séquelle **faibles** (décès très fréquents, séquelles fréquentes).","prio":"P2","sec":"s1"},{"id":"fc-331-813a27","poly":"cardio","fiche":"331","front":"No-flow de plus de 10 min : quel pronostic ?","back":"Survie **quasi nulle** ; les reprises évoluent en général vers une **encéphalopathie anoxique**.","prio":"P2","sec":"s1"},{"id":"fc-331-4f4dca","poly":"cardio","fiche":"331","front":"No-flow bref : quel poids garde la durée du low-flow ?","back":"Elle **pèse moins** : une réanimation longue, mais précoce et efficace, peut aboutir à une récupération cardiaque et cérébrale.","prio":"P2","sec":"s1"},{"id":"fc-331-2aaefa","poly":"cardio","fiche":"331","front":"France : combien de décès par arrêt cardiaque extrahospitalier par an ?","back":"**40 000 par an** (incidence **0,75 ‰**).","prio":"P3","sec":"s1"},{"id":"fc-331-24b51c","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle survie au-delà de 5 min et au-delà de 10 min d'arrêt ?","back":"**7 à 8 %** au-delà de 5 min ; **proche de 0** au-delà de 10 min.","prio":"P3","sec":"s1"},{"id":"fc-331-6a1881","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle survie sans séquelle, notamment neurologique ?","back":"**2 à 4 %**.","prio":"P3","sec":"s1"},{"id":"fc-331-3f12ad","poly":"cardio","fiche":"331","front":"Arrêt cardiaque intrahospitalier : quelle survie ?","back":"Plus élevée : **40-50 %**.","prio":"P3","sec":"s1"},{"id":"fc-331-148e97","poly":"cardio","fiche":"331","front":"Survie sans séquelle : que devient-elle après 30 min de RCP ?","back":"**Nulle**.","prio":"P2","sec":"s1"},{"id":"fc-331-24d99c","poly":"cardio","fiche":"331","front":"Quelles recommandations encadrent la prise en charge de l'arrêt cardiaque en France ?","back":"**ERC 2021**, Société européenne de cardiologie **2022**, recommandations américaines **2020**.","prio":"P3","sec":"s1"},{"id":"fc-331-33b14e","poly":"cardio","fiche":"331","front":"Témoin : comment reconnaître un arrêt cardiaque ?","back":"Personne **inconsciente**, qui **ne bouge plus**, **ne réagit plus**, **ne respire plus** ou fait des **gasps**.","prio":"P1","sec":"s2"},{"id":"fc-331-5cb6e2","poly":"cardio","fiche":"331","front":"Secouriste ou soignant : quel signe ajoute-t-il au diagnostic d'arrêt cardiaque ?","back":"**Absence de pouls carotidien ou fémoral**.","prio":"P1","sec":"s2"},{"id":"fc-331-344c44","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : faut-il une certitude pour débuter la réanimation ?","back":"**Non** : la simple **suspicion** suffit → **15** + réanimation immédiate.","prio":"P1","sec":"s2"},{"id":"fc-331-fc4995","poly":"cardio","fiche":"331","front":"Patient inconscient qui fait des gasps : conduite ?","back":"C'est un **arrêt cardiaque** → **masser**.","prio":"P1","sec":"s2"},{"id":"fc-331-a0851c","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quels prodromes possibles ?","back":"**Palpitations**, **douleur thoracique**.","prio":"P3","sec":"s2"},{"id":"fc-331-22cea8","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : sur quel terrain survient-il fréquemment ?","back":"**Maladie coronarienne** ou **insuffisance cardiaque** ; médicaments ayant pu faciliter l'arrêt.","prio":"P3","sec":"s2"},{"id":"fc-331-e7079b","poly":"cardio","fiche":"331","front":"Trouble du rythme de l'arrêt cardiaque : dans quelles circonstances survient-il ?","back":"**Au repos comme à l'effort** : FV d'emblée ou TV dégénérant en FV en quelques minutes.","prio":"P2","sec":"s2"},{"id":"fc-331-95c1a1","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quel est le mode électrique initial le plus fréquent ?","back":"La **fibrillation ventriculaire** (FV).","prio":"P1","sec":"s3"},{"id":"fc-331-87457d","poly":"cardio","fiche":"331","front":"FV : quel est le seul traitement efficace et potentiellement durable ?","back":"Le **choc électrique externe** (CEE), + massage.","prio":"P1","sec":"s3"},{"id":"fc-331-38b601","poly":"cardio","fiche":"331","front":"TV sans pouls : quelle conduite ?","back":"**CEE** + massage (peut dégénérer en FV en quelques minutes).","prio":"P1","sec":"s3"},{"id":"fc-331-3fec5b","poly":"cardio","fiche":"331","front":"Asystolie : quelle conduite ?","back":"**Massage**, **pas de défibrillation**.","prio":"P1","sec":"s3"},{"id":"fc-331-b6f50b","poly":"cardio","fiche":"331","front":"Dissociation électromécanique : quelle définition et quelle conduite ?","back":"Activité électrique sans pouls ni PA (cœur agonique) → **poursuivre le massage**.","prio":"P2","sec":"s3"},{"id":"fc-331-936b41","poly":"cardio","fiche":"331","front":"Choc électrique sur une FV : quel mécanisme ?","back":"Dépolarise simultanément une **masse critique** de cellules → interrompt les **réentrées**.","prio":"P2","sec":"s3"},{"id":"fc-331-96bdfe","poly":"cardio","fiche":"331","front":"Quels rythmes le DSA reconnaît-il comme chocables ?","back":"**FV**, **flutter ventriculaire**, **TV à fréquence élevée**.","prio":"P3","sec":"s3"},{"id":"fc-331-ebdec5","poly":"cardio","fiche":"331","front":"Sans ECG : comment le DSA décide-t-il du choc ?","back":"Il **analyse lui-même** le rythme et ne choque que s'il est chocable.","prio":"P2","sec":"s3"},{"id":"fc-331-3e44ad","poly":"cardio","fiche":"331","front":"Défibrillateurs biphasiques vs monophasiques : quelles énergies ?","back":"Biphasique **jusqu'à 200 J** (plus sûr, plus efficace) ; monophasique **360 J**.","prio":"P3","sec":"s3"},{"id":"fc-331-604331","poly":"cardio","fiche":"331","front":"Au tout début de la RCP : dans quelle proportion trouve-t-on une FV ?","back":"**40 à 70 %** selon la rapidité de la RCP (sinon asystolie).","prio":"P3","sec":"s3"},{"id":"fc-331-cb3a05","poly":"cardio","fiche":"331","front":"Rythme initial selon l'ILCOR 2015 : quelles proportions ?","back":"**FV 70 à 80 %** ; **bradycardie extrême** (BAV haut degré, asystolie) **15 à 20 %**.","prio":"P3","sec":"s3"},{"id":"fc-331-dee6e1","poly":"cardio","fiche":"331","front":"FV non réanimée : comment évolue-t-elle ?","back":"Grosses puis petites mailles, puis tracé plat : **50 %** deviennent une asystolie entre la **4e et la 8e minute**.","prio":"P2","sec":"s3"},{"id":"fc-331-bb0d78","poly":"cardio","fiche":"331","front":"Asystolie : que traduit-elle sur le plan pronostique ?","back":"Un **marqueur du temps écoulé** depuis l'arrêt → **mauvais pronostic** (ou cause extracardiaque).","prio":"P2","sec":"s3"},{"id":"fc-331-ed596e","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sur FV : délai idéal du premier choc ?","back":"Dans les **3 minutes** suivant l'arrêt.","prio":"P1","sec":"s3"},{"id":"fc-331-6f3223","poly":"cardio","fiche":"331","front":"Chaîne de survie : qui l'a décrite et quand ?","back":"**Cummins**, **1991**.","prio":"P1","sec":"s4"},{"id":"fc-331-459879","poly":"cardio","fiche":"331","front":"Chaîne de survie de Cummins : citer les 6 maillons ?","back":"**Alerte** précoce (15) ; **RCP** précoce ; **défibrillation** précoce ; **RCP spécialisée** (Smur) ; réanimation hospitalière ; **rétablissement**.","prio":"P1","sec":"s4"},{"id":"fc-331-4b05dc","poly":"cardio","fiche":"331","front":"Chaîne de survie : quels maillons relèvent du grand public ?","back":"L'**alerte précoce** (15) et la **RCP précoce**.","prio":"P2","sec":"s4"},{"id":"fc-331-4f12bc","poly":"cardio","fiche":"331","front":"Chaîne de survie en France : quels maillons sont faibles ?","back":"Les **3 premiers** : alerte, RCP et défibrillation précoces.","prio":"P1","sec":"s4"},{"id":"fc-331-102190","poly":"cardio","fiche":"331","front":"Chaîne de survie : qu'est-ce qui fait la survie ?","back":"La **rapidité** et la **complémentarité** des maillons.","prio":"P2","sec":"s4"},{"id":"fc-331-3cec6d","poly":"cardio","fiche":"331","front":"5e maillon de la chaîne de Cummins : que comprend-il ?","back":"Réanimation hospitalière de **haut niveau** : traiter la cause, hypothermie contrôlée, assistance circulatoire, correction métabolique.","prio":"P3","sec":"s4"},{"id":"fc-331-665dda","poly":"cardio","fiche":"331","front":"France : qui peut défibriller ?","back":"Médecins, mais aussi **infirmiers**, **secouristes** et **ambulanciers**.","prio":"P2","sec":"s4"},{"id":"fc-331-832532","poly":"cardio","fiche":"331","front":"DSA en France : quelle limite à leur déploiement ?","back":"**Peu nombreux** (notamment en cabinet médical) et **mal localisés**.","prio":"P3","sec":"s4"},{"id":"fc-331-1daa65","poly":"cardio","fiche":"331","front":"France : quelle proportion de la population est formée à la RCP ?","back":"Seulement **10 à 15 %**.","prio":"P2","sec":"s4"},{"id":"fc-331-930727","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quel est le rôle primordial du témoin ?","back":"**Raccourcir le no-flow** ; il peut être guidé par téléphone par le **régulateur**.","prio":"P1","sec":"s4"},{"id":"fc-331-132e40","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : de quels facteurs dépend le pronostic ?","back":"**Étiologie**, **lieu**, présence d'un **témoin**, **rapidité des premiers gestes**, et moindrement **durée de réanimation**.","prio":"P3","sec":"s4"},{"id":"fc-331-ba66db","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quels éléments améliorent le pronostic ?","back":"Un **rythme chocable** ou la présence d'un **témoin**.","prio":"P1","sec":"s4"},{"id":"fc-331-0300d1","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : au-delà de quelle durée de réanimation le pronostic devient-il nul ?","back":"**30 à 45 minutes**.","prio":"P1","sec":"s4"},{"id":"fc-331-898449","poly":"cardio","fiche":"331","front":"Arrêt cardiaque (points clés) : comment qualifier le pronostic ?","back":"**Catastrophique** ; le principal facteur pronostique reste la **durée du no-flow**.","prio":"P1","sec":"s4"},{"id":"fc-331-391ae4","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quels facteurs initiaux favorables évalue le Smur ?","back":"**Témoin**, **FV** initiale, réanimation **précoce**, défibrillation **rapide**, réanimation **courte**.","prio":"P3","sec":"s4"},{"id":"fc-331-de6a25","poly":"cardio","fiche":"331","front":"Arrêt cardiaque préhospitalier : quelle survie globale ?","back":"**5 à 20 %** (mort quasi certaine **sans témoin**).","prio":"P3","sec":"s4"},{"id":"fc-331-a1fdaa","poly":"cardio","fiche":"331","front":"Patients arrivés vivants à l'hôpital : quelle proportion sort sans séquelle neurologique ?","back":"Seulement **20 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-f35c3b","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sans réanimation : de combien baisse la survie par minute ?","back":"De **10 % par minute**.","prio":"P3","sec":"s4"},{"id":"fc-331-495a76","poly":"cardio","fiche":"331","front":"FV défibrillée en 1 à 3 min : quelle survie ?","back":"**40 à 60 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-12c0f1","poly":"cardio","fiche":"331","front":"FV défibrillée en 4 à 6 min puis en 7 à 10 min : quelle survie ?","back":"**35 %** puis **25 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-db69eb","poly":"cardio","fiche":"331","front":"FV au-delà de 10 min : chance de récupérer un rythme efficace ?","back":"**< 5 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-5b207f","poly":"cardio","fiche":"331","front":"Arrêt cardiaque de l'adulte : quelle est la 1re étiologie ?","back":"**Coronaire** : cardiopathie ischémique aiguë (SCA inaugural) ou **séquelle d'infarctus**.","prio":"P1","sec":"s5"},{"id":"fc-331-ce9103","poly":"cardio","fiche":"331","front":"Cause immédiate la plus fréquente d'arrêt cardiaque : quel mécanisme ?","back":"Une **FV** d'origine **ischémique**.","prio":"P1","sec":"s5"},{"id":"fc-331-08e606","poly":"cardio","fiche":"331","front":"Citer les 3 grands mécanismes électriques d'arrêt cardiaque ?","back":"**FV**, **TV**, **asystolie**.","prio":"P1","sec":"s5"},{"id":"fc-331-69cb19","poly":"cardio","fiche":"331","front":"Bradycardies extrêmes responsables d'arrêt cardiaque : lesquelles ?","back":"**BAV de haut grade** ; **asystolie**.","prio":"P2","sec":"s5"},{"id":"fc-331-2ab8b5","poly":"cardio","fiche":"331","front":"Causes non cardiovasculaires d'arrêt cardiaque : quelle proportion et lesquelles ?","back":"**5 à 25 %** : surtout **toxiques**, **traumatiques**, **insuffisances respiratoires aiguës**, **noyades**.","prio":"P1","sec":"s5"},{"id":"fc-331-5c638d","poly":"cardio","fiche":"331","front":"Cardiomyopathies et valvulopathies causes d'arrêt cardiaque : lesquelles ?","back":"**CMH**, CMD, **dysplasie VD arythmogène**, valvulopathies (surtout **rétrécissement aortique**).","prio":"P3","sec":"s5"},{"id":"fc-331-9f7e03","poly":"cardio","fiche":"331","front":"CMH et mort subite : quelle circonstance fréquente ?","back":"**L'effort** (mais pas seulement) ; surtout CMH familiale et/ou obstructive.","prio":"P3","sec":"s5"},{"id":"fc-331-42bac6","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sur cœur structurellement normal : quelles causes rythmiques ?","back":"**FV idiopathique**, **Brugada**, **QT long** ou **QT court**, **WPW**, troubles conductifs paroxystiques.","prio":"P3","sec":"s5"},{"id":"fc-331-c7654d","poly":"cardio","fiche":"331","front":"Citer d'autres causes cardiovasculaires d'arrêt cardiaque ?","back":"**Myocardite**, **tamponnade**, **dissection aortique**, **EP massive**, rupture d'anévrisme, cardiopathies congénitales.","prio":"P3","sec":"s5"},{"id":"fc-331-82e051","poly":"cardio","fiche":"331","front":"Morts subites : fréquence des lésions coronaires retrouvées ?","back":"**40 à 77 %** selon les études.","prio":"P3","sec":"s5"},{"id":"fc-331-e98a47","poly":"cardio","fiche":"331","front":"Quelle proportion d'arrêts cardiaques complique un infarctus ?","back":"**20 à 40 %**.","prio":"P3","sec":"s5"},{"id":"fc-331-2dc220","poly":"cardio","fiche":"331","front":"Arrêt cardiaque avant 30 ans : quelles causes évoquer ?","back":"Troubles du rythme ventriculaire **non ischémiques** et **cardiopathies congénitales** décompensées (coronaire rare).","prio":"P2","sec":"s5"},{"id":"fc-331-55b442","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quand alerter le 15 ?","back":"Dès que l'arrêt est **diagnostiqué ou seulement suspecté** ; demander de l'aide autour de soi.","prio":"P1","sec":"s6"},{"id":"fc-331-b6efbb","poly":"cardio","fiche":"331","front":"ACD : que signifient les 3 lettres ?","back":"**A** : libérer les voies aériennes ; **C** : massage cardiaque ; **D** : défibrillation.","prio":"P1","sec":"s6"},{"id":"fc-331-2bdfbf","poly":"cardio","fiche":"331","front":"Libération des voies aériennes (A) : quels gestes ?","back":"**Basculer la tête** en arrière, **relever le menton**, retirer un corps étranger (doigts en crochet).","prio":"P2","sec":"s6"},{"id":"fc-331-dea7e0","poly":"cardio","fiche":"331","front":"RCP : quel geste est la priorité ?","back":"Le **massage cardiaque externe** (raccourcit le no-flow).","prio":"P1","sec":"s6"},{"id":"fc-331-8d2630","poly":"cardio","fiche":"331","front":"Massage cardiaque externe de l'adulte : profondeur et fréquence ?","back":"**4 à 5 cm**, **100/min**, talon de la main au centre du thorax, victime à plat dos.","prio":"P1","sec":"s6"},{"id":"fc-331-b197b1","poly":"cardio","fiche":"331","front":"Plusieurs sauveteurs : tous les combien changer de masseur ?","back":"Environ toutes les **2 minutes**.","prio":"P2","sec":"s6"},{"id":"fc-331-26c394","poly":"cardio","fiche":"331","front":"Arrêt cardiaque de l'adulte : faut-il faire du bouche-à-bouche ?","back":"**Non** : pas d'insufflations ; interrompre le massage le moins possible.","prio":"P1","sec":"s6"},{"id":"fc-331-744cc3","poly":"cardio","fiche":"331","front":"DSA disponible avant le Smur : conduite ?","back":"L'**utiliser sans attendre** le Smur si on sait s'en servir.","prio":"P1","sec":"s6"},{"id":"fc-331-f10c31","poly":"cardio","fiche":"331","front":"Après un choc du DSA : que faire ?","back":"**Poursuivre la RCP 2 minutes** avant de rechercher une reprise circulatoire.","prio":"P1","sec":"s6"},{"id":"fc-331-0f5a47","poly":"cardio","fiche":"331","front":"Arrivée des secours : quel dispositif de libération des voies aériennes ?","back":"Une **canule de Guedel**.","prio":"P2","sec":"s6"},{"id":"fc-331-7e80ac","poly":"cardio","fiche":"331","front":"Pas de défibrillateur disponible : pourquoi masser dans tous les cas ?","back":"Le massage maintient une **oxygénation tissulaire minimale** et une circulation, d'abord vers le **cerveau**.","prio":"P1","sec":"s6"},{"id":"fc-331-4006d9","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle notion est inacceptable ?","back":"Ne pas connaître l'**ACD** (voies aériennes, massage, défibrillation).","prio":"P1","sec":"s6"},{"id":"fc-331-824755","poly":"cardio","fiche":"331","front":"Pourquoi l'oxygénation reste-t-elle essentielle chez l'enfant et le nourrisson ?","back":"L'arrêt y est souvent d'origine **hypoxique**.","prio":"P2","sec":"s6"},{"id":"fc-331-6f8ca9","poly":"cardio","fiche":"331","front":"Arrivée du Smur : quelles premières étapes ?","back":"**Évaluer les chances de survie**, puis RCP médicalisée selon l'**algorithme universel**.","prio":"P3","sec":"s7"},{"id":"fc-331-2595a5","poly":"cardio","fiche":"331","front":"Rythme chocable (points clés) : quand donner l'adrénaline et l'amiodarone ?","back":"Après **échec de 2 CEE** : **adrénaline IV** + **amiodarone 300 mg**.","prio":"P1","sec":"s7"},{"id":"fc-331-b20098","poly":"cardio","fiche":"331","front":"RCP médicalisée : quelle qualité de compressions ?","back":"**Très bonne qualité** (relais ou appareil), interruptions **minimales**, même pendant la ventilation.","prio":"P2","sec":"s7"},{"id":"fc-331-ac6f2a","poly":"cardio","fiche":"331","front":"RCP médicalisée : pendant l'intubation, combien de temps peut-on interrompre le massage ?","back":"**30 secondes** au plus (ventilation au masque si intubation difficile).","prio":"P2","sec":"s7"},{"id":"fc-331-fcc5a5","poly":"cardio","fiche":"331","front":"RCP médicalisée : quelle surveillance instrumentale ?","back":"**Capnographie** et **pression artérielle invasive**.","prio":"P3","sec":"s7"},{"id":"fc-331-a53444","poly":"cardio","fiche":"331","front":"FV/TV persistante après le 1er choc : quand donner l'adrénaline (texte) ?","back":"Après **2 min de RCP**, juste avant le **2e ou 3e choc**, puis toutes les **4 min**.","prio":"P2","sec":"s7"},{"id":"fc-331-77c04f","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : posologie de l'adrénaline ?","back":"**1 mg IV** (ou endotrachéale) **toutes les 4 minutes**.","prio":"P2","sec":"s7"},{"id":"fc-331-bd1411","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sur FV : quand donner l'amiodarone ?","back":"**300 mg** juste avant le **3e choc** ; **150 mg** de plus si FV/TV réfractaire ou récidivante.","prio":"P2","sec":"s7"},{"id":"fc-331-37bdd0","poly":"cardio","fiche":"331","front":"Amiodarone dans l'arrêt cardiaque : comment l'administrer ?","back":"**300 mg** dilués dans **20 à 30 mL** de sérum salé isotonique, **IV rapide**.","prio":"P3","sec":"s7"},{"id":"fc-331-a31816","poly":"cardio","fiche":"331","front":"Lidocaïne dans l'arrêt cardiaque : quelle place et quelle dose ?","back":"Seulement si **amiodarone indisponible** : **1,5 mg/kg** IV lente, sans dépasser **3 mg/kg**.","prio":"P3","sec":"s7"},{"id":"fc-331-49d140","poly":"cardio","fiche":"331","front":"Adrénaline dans l'arrêt cardiaque : quel pronostic selon la dose totale ?","back":"D'autant plus mauvais que la dose est forte : **au-delà de 1 à 2 mg**, survie faible.","prio":"P3","sec":"s7"},{"id":"fc-331-987382","poly":"cardio","fiche":"331","front":"Adrénaline : quel effet est surtout bénéfique dans l'arrêt cardiaque ?","back":"L'effet **alpha-adrénergique** (hausse des débits myocardique et cérébral).","prio":"P3","sec":"s7"},{"id":"fc-331-cc6edc","poly":"cardio","fiche":"331","front":"Amiodarone vs lidocaïne : laquelle améliore la survie à court terme ?","back":"L'**amiodarone**.","prio":"P3","sec":"s7"},{"id":"fc-331-54946d","poly":"cardio","fiche":"331","front":"Antiarythmiques dans l'arrêt cardiaque : quelle indication ?","back":"AC **réfractaire** avec troubles du rythme ventriculaire **récidivants après ≥ 2 chocs**.","prio":"P3","sec":"s7"},{"id":"fc-331-b43269","poly":"cardio","fiche":"331","front":"Rythme chocable : quels traitements préparer pendant la RCP ?","back":"Traitement de la **cause** (intoxication, revascularisation) ; discuter une **assistance circulatoire extracorporelle**.","prio":"P2","sec":"s7"},{"id":"fc-331-5b3225","poly":"cardio","fiche":"331","front":"Asystolie (points clés) : quel médicament ?","back":"**Adrénaline IV**.","prio":"P1","sec":"s8"},{"id":"fc-331-746d99","poly":"cardio","fiche":"331","front":"AC réfractaire en asystolie : quelle place de l'adrénaline ?","back":"Traitement **incontournable** : **1 mg toutes les 4 min**.","prio":"P2","sec":"s8"},{"id":"fc-331-feb8dd","poly":"cardio","fiche":"331","front":"Activité électrique au scope : suffit-elle à conclure à une circulation efficace ?","back":"**Non** : rechercher **pouls** et **PA**.","prio":"P2","sec":"s8"},{"id":"fc-331-da0907","poly":"cardio","fiche":"331","front":"Pronostic : FV ou asystolie ?","back":"Meilleur en **FV** qu'en asystolie.","prio":"P2","sec":"s8"},{"id":"fc-331-1861a0","poly":"cardio","fiche":"331","front":"Torsades de pointes ou hypomagnésémie suspectée pendant un arrêt : quel traitement ?","back":"**Sulfate de magnésium 2 g** en IV directe.","prio":"P2","sec":"s9"},{"id":"fc-331-44a69f","poly":"cardio","fiche":"331","front":"Bradycardie sinusale extrême pendant un arrêt : quel traitement et à quelle dose ?","back":"**Atropine 1 mg**, répétée toutes les **3 à 5 min**, jusqu'à **0,04 mg/kg** au total.","prio":"P2","sec":"s9"},{"id":"fc-331-6001d5","poly":"cardio","fiche":"331","front":"BAV du 3e degré sans hémodynamique efficace : quel traitement ?","back":"**Isoprénaline** (si cause conductive certaine).","prio":"P2","sec":"s9"},{"id":"fc-331-d61b5d","poly":"cardio","fiche":"331","front":"Isoprénaline : quelle préparation et quel objectif ?","back":"**5 ampoules à 0,2 mg** dans **250 mL** de G5 % ; objectif **classiquement** FC d'au moins **50-60/min**.","prio":"P3","sec":"s9"},{"id":"fc-331-07d1b2","poly":"cardio","fiche":"331","front":"Atropine et isoprénaline pendant un arrêt : quelle condition préalable ?","back":"Une cause **conductive ou vagale maligne certaine**.","prio":"P3","sec":"s9"},{"id":"fc-331-80bb73","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : après combien de temps apparaissent acidose métabolique et hyperkaliémie ?","back":"Après **3 à 4 minutes**.","prio":"P2","sec":"s9"},{"id":"fc-331-30e6aa","poly":"cardio","fiche":"331","front":"Bicarbonate de sodium 84 ‰ : dans quelles situations ?","back":"Réanimation **prolongée**, **hyperkaliémie**, acidose préexistante, intoxication aux **stabilisants de membrane** (tricycliques, phénobarbital).","prio":"P3","sec":"s9"},{"id":"fc-331-353639","poly":"cardio","fiche":"331","front":"Bicarbonate dans l'arrêt cardiaque : quel bénéfice démontré ?","back":"La plupart des études ne montrent **pas de gain significatif** de survie.","prio":"P3","sec":"s9"},{"id":"fc-331-0d9fc9","poly":"cardio","fiche":"331","front":"Thrombolyse préhospitalière pendant un arrêt : quand la discuter ?","back":"**Au cas par cas** si **IDM** ou **EP massive** avérés ou fortement suspectés (pas en routine).","prio":"P2","sec":"s9"},{"id":"fc-331-8dc9eb","poly":"cardio","fiche":"331","front":"Après reprise d'activité cardiaque : quand faire une coronarographie ?","back":"**Au moindre doute** de cause coronaire.","prio":"P1","sec":"s10"},{"id":"fc-331-8a897f","poly":"cardio","fiche":"331","front":"Arrêt cardiaque récupéré : quels arguments pour une cause coronaire ?","back":"**Antécédents**, **douleur thoracique** avant l'arrêt, **ECG** post-récupération compatible avec un SCA (sus-ST, BBG…).","prio":"P2","sec":"s10"},{"id":"fc-331-304815","poly":"cardio","fiche":"331","front":"Sidération myocardique post-arrêt : quel traitement de choix ?","back":"La **dobutamine** (inotrope positif).","prio":"P2","sec":"s10"},{"id":"fc-331-1a7de6","poly":"cardio","fiche":"331","front":"Sidération myocardique résistant à la dobutamine : quel recours ?","back":"**Assistance circulatoire** par pompe extracorporelle (± décharge VG).","prio":"P2","sec":"s10"},{"id":"fc-331-6e864c","poly":"cardio","fiche":"331","front":"Post-arrêt : comment surveiller la fonction cardiaque ?","back":"**Échocardiographie**, parfois cathéter de **Swan-Ganz**.","prio":"P3","sec":"s10"},{"id":"fc-331-dbaba8","poly":"cardio","fiche":"331","front":"Quels facteurs favorisent la sidération myocardique post-arrêt ?","back":"**No-flow** et **low-flow** prolongés, **fortes doses de vasopresseurs**, **chocs** nombreux et intenses.","prio":"P3","sec":"s10"},{"id":"fc-331-5757cb","poly":"cardio","fiche":"331","front":"Récupération d'un pouls après un arrêt : est-elle synonyme de survie ?","back":"**Non** : survie rare, séquelles **neurologiques** fréquentes.","prio":"P1","sec":"s10"},{"id":"fc-331-4217e1","poly":"cardio","fiche":"331","front":"Post-arrêt : quelles mesures sont indispensables pour protéger le cerveau ?","back":"**Contrôle thermique**, **contrôle glycémique**, **ni hypoxie ni hypercapnie**.","prio":"P1","sec":"s11"},{"id":"fc-331-3b2dfa","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi éviter hypoxie et hypercapnie ?","back":"Elles provoquent une **hypertension intracrânienne** fatale.","prio":"P2","sec":"s11"},{"id":"fc-331-f34699","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi lutter contre l'hyperglycémie ?","back":"Elle crée un **œdème cérébral** (effet osmotique).","prio":"P2","sec":"s11"},{"id":"fc-331-6acb21","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi prévenir l'hyperthermie ?","back":"Elle **aggrave les lésions d'ischémie-reperfusion**.","prio":"P2","sec":"s11"},{"id":"fc-331-46bb22","poly":"cardio","fiche":"331","front":"Hypothermie contrôlée post-arrêt : quelle cible et quelle place ?","back":"Autour de **34 °C** ; place **débattue** (éviter surtout l'hyperthermie).","prio":"P3","sec":"s11"},{"id":"fc-331-ff7fb9","poly":"cardio","fiche":"331","front":"Post-arrêt : quel rôle de la sédation ?","back":"Met le cerveau **au repos**, baisse ses besoins en O₂, limite l'œdème.","prio":"P3","sec":"s11"},{"id":"fc-331-0247be","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi la pression artérielle est-elle cruciale ?","back":"L'**autorégulation** cérébrale peut être perdue : la PA conditionne le pronostic cérébral.","prio":"P3","sec":"s11"},{"id":"fc-331-874b16","poly":"cardio","fiche":"331","front":"Pronostic cérébral post-arrêt : quels examens, et quand sont-ils fiables ?","back":"**Glasgow**, **EEG**, **potentiels évoqués** répétés ; fiabilité accrue entre **J1 et J3**.","prio":"P3","sec":"s11"},{"id":"fc-331-86e607","poly":"cardio","fiche":"331","front":"Arrêt de la réanimation : comment est prise la décision ?","back":"Décision **collégiale**, orientée par un algorithme de **neuropronostication**.","prio":"P1","sec":"s11"},{"id":"fc-331-2593ed","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle information doit être donnée aux proches ?","back":"Une **information régulière** sur le pronostic et l'évolution.","prio":"P1","sec":"s11"},{"id":"fc-331-fd6e04","poly":"cardio","fiche":"331","front":"Information des proches après un arrêt : quelles modalités ?","back":"**Précoce**, permanente mais contrôlée (**peu d'interlocuteurs**).","prio":"P3","sec":"s11"},{"id":"fc-331-9745fb","poly":"cardio","fiche":"331","front":"Mort cérébrale après arrêt cardiaque : condition d'un prélèvement d'organes ?","back":"Information de la famille et absence d'inscription au **registre national des refus**.","prio":"P3","sec":"s11"},{"id":"fc-331-e693ca","poly":"cardio","fiche":"331","front":"Au-delà de quelle durée de no-flow peut-on s'interroger sur l'éthique de la réanimation ?","back":"**10 minutes**.","prio":"P3","sec":"s11"},{"id":"fc-331-953f8d","poly":"cardio","fiche":"331","front":"Survivants d'un arrêt cardiaque : quelles séquelles possibles ?","back":"De l'**état végétatif** aux séquelles **motrices et cognitives** lourdes, perte d'autonomie.","prio":"P3","sec":"s11"},{"id":"fc-339-bafe46","poly":"cardio","fiche":"339","front":"SCA : quelle définition générale ?","back":"Ensemble des manifestations d'une **ischémie myocardique aiguë**.","prio":"P1","sec":"s1"},{"id":"fc-339-320b24","poly":"cardio","fiche":"339","front":"SCA : quel examen sépare SCA ST+ et SCA ST- ?","back":"L'**ECG** du premier contact : sus-décalage **persistant** du ST ou non.","prio":"P1","sec":"s1"},{"id":"fc-339-9aaed4","poly":"cardio","fiche":"339","front":"SCA ST+ : quel mécanisme ?","back":"**Occlusion aiguë** d'une coronaire par un thrombus **fibrinocruorique** (ischémie transmurale).","prio":"P1","sec":"s1"},{"id":"fc-339-4986e0","poly":"cardio","fiche":"339","front":"SCA ST+ : quel traitement en urgence ?","back":"**Désobstruction immédiate** : angioplastie primaire ou fibrinolytique IV.","prio":"P1","sec":"s1"},{"id":"fc-339-723eee","poly":"cardio","fiche":"339","front":"SCA ST+ : quelle douleur typique ?","back":"Persistante **> 30 min**, **non soulagée** par la trinitrine sublinguale.","prio":"P1","sec":"s1"},{"id":"fc-339-95a776","poly":"cardio","fiche":"339","front":"SCA ST+ : faut-il attendre la troponine ?","back":"**Non** : elle est dosée mais son résultat n'est **pas attendu**.","prio":"P1","sec":"s1"},{"id":"fc-339-71897f","poly":"cardio","fiche":"339","front":"SCA ST- : comment distinguer IDM ST- et angor instable ?","back":"Par la **troponine** : élevée = **IDM ST-** ; non élevée = **angor instable**.","prio":"P1","sec":"s1"},{"id":"fc-339-c5c52f","poly":"cardio","fiche":"339","front":"Angor instable : est-ce un SCA ?","back":"**Oui** : diagnostic clinique, il reste un **SCA ST-** (troponine normale).","prio":"P1","sec":"s1"},{"id":"fc-339-5a49d3","poly":"cardio","fiche":"339","front":"SCA ST- : quels aspects ECG possibles ?","back":"**Sous-décalage** de ST, anomalies de **T**, ou ECG **normal** ; sus-décalage percritique régressif possible.","prio":"P2","sec":"s1"},{"id":"fc-339-1dd83f","poly":"cardio","fiche":"339","front":"Infarctus du myocarde : quelle définition biologique ?","back":"Troponine ultrasensible **> 99ᵉ percentile** de la limite supérieure + **au moins un** autre critère.","prio":"P1","sec":"s1"},{"id":"fc-339-413a9c","poly":"cardio","fiche":"339","front":"IDM : quels critères associer à la troponine élevée ?","back":"**Symptômes** ischémiques ; nouvelles anomalies **ECG** (repolarisation, onde Q) ; perte de myocarde viable en **imagerie** ; **thrombus** en coronarographie/autopsie.","prio":"P1","sec":"s1"},{"id":"fc-339-2cd706","poly":"cardio","fiche":"339","front":"IDM de type 1 : quel mécanisme ?","back":"**Accident de plaque** (rupture, ulcération, fissuration, érosion) avec thrombus.","prio":"P2","sec":"s1"},{"id":"fc-339-fe9640","poly":"cardio","fiche":"339","front":"IDM de type 2 : quel mécanisme ?","back":"**Déséquilibre apport/demande** en O₂ **sans** instabilité de plaque (anémie, hypoxémie, arythmie, hypo/hypertension…).","prio":"P2","sec":"s1"},{"id":"fc-339-bcefb4","poly":"cardio","fiche":"339","front":"IDM de type 3, 4 et 5 : quelles définitions ?","back":"Type 3 : **mort subite** sans troponine disponible ; types 4 et 5 : **iatrogènes** (angioplastie, pontage).","prio":"P3","sec":"s1"},{"id":"fc-339-9f11e4","poly":"cardio","fiche":"339","front":"IDM de type 1 : la lésion coronaire est-elle toujours sévère ?","back":"Le plus souvent, mais **mineure dans 5-10 %** des cas.","prio":"P3","sec":"s1"},{"id":"fc-339-0b8fb1","poly":"cardio","fiche":"339","front":"Incidence : comment évoluent SCA ST+ et SCA ST- ?","back":"Le ST+ **diminue**, le ST- **augmente** (probablement mieux repéré par la troponine ultrasensible).","prio":"P2","sec":"s1"},{"id":"fc-339-8c987d","poly":"cardio","fiche":"339","front":"IDM ST+ : quelle mortalité hospitalière en Europe ?","back":"**4 à 12 %** (proche de **10 % à 1 an**).","prio":"P2","sec":"s1"},{"id":"fc-339-f84b96","poly":"cardio","fiche":"339","front":"IDM ST+ : quels facteurs augmentent la mortalité ?","back":"Âge, diabète, insuffisance rénale ou cardiaque, ATCD d'IDM, **FEVG altérée**, atteinte diffuse, **prise en charge tardive**.","prio":"P3","sec":"s1"},{"id":"fc-339-b32311","poly":"cardio","fiche":"339","front":"France : combien d'hospitalisations par an pour IDM ?","back":"**Plus de 60 000**.","prio":"P3","sec":"s1"},{"id":"fc-339-88ab5f","poly":"cardio","fiche":"339","front":"SCA et sexe : quelle répartition selon l'âge ?","back":"Avant 60 ans : **4 fois plus** chez l'homme ; après 75 ans : plus fréquents chez la **femme** (retard de 7 à 10 ans).","prio":"P2","sec":"s1"},{"id":"fc-339-dcdf96","poly":"cardio","fiche":"339","front":"SCA chez la femme : la prise en charge diffère-t-elle ?","back":"**Non** : la même dans les deux sexes (symptômes plus souvent atypiques, hospitalisation plus tardive).","prio":"P1","sec":"s1"},{"id":"fc-339-27e655","poly":"cardio","fiche":"339","front":"SCA : quelle complication peut compliquer toutes les formes ?","back":"La **mort subite** (rythmique).","prio":"P2","sec":"s1"},{"id":"fc-339-0949e5","poly":"cardio","fiche":"339","front":"Plaque vulnérable : quelles caractéristiques ?","back":"Gros **cœur lipidique nécrotique** + **fine chape fibreuse**.","prio":"P3","sec":"s1"},{"id":"fc-339-089bfa","poly":"cardio","fiche":"339","front":"Thrombus du SCA : quel type selon la forme ?","back":"Petit thrombus **blanc** (plaquettaire) non occlusif → **ST-** ; gros thrombus **rouge** occlusif → **ST+**.","prio":"P3","sec":"s1"},{"id":"fc-339-9ad93e","poly":"cardio","fiche":"339","front":"Sus-décalage de ST : comment distinguer spasme et thrombose occlusive ?","back":"**Spasme** (Prinzmetal) : régresse sous **trinitrine** ; thrombose occlusive (ST+) : **persiste**.","prio":"P3","sec":"s1"},{"id":"fc-339-177807","poly":"cardio","fiche":"339","front":"Angor stable vs SCA : quelle différence de mécanisme ?","back":"Angor stable : rétrécissement **progressif** ; SCA : rupture **brutale et imprévisible** de plaque.","prio":"P3","sec":"s1"},{"id":"fc-339-81f0e8","poly":"cardio","fiche":"339","front":"SCA : citer des facteurs déclenchants ?","back":"**Effort violent**, manque de sommeil, excès alimentaire, **infection aiguë**.","prio":"P3","sec":"s1"},{"id":"fc-339-033e67","poly":"cardio","fiche":"339","front":"Douleur thoracique aiguë : quel premier réflexe ?","back":"**Appeler le 15** (Smur, ECG sur place) ; un autre intervenant en 1re intention est à proscrire.","prio":"P1","sec":"s2"},{"id":"fc-339-c8ace5","poly":"cardio","fiche":"339","front":"Douleur thoracique au SAU : dans quel délai faire l'ECG ?","back":"Dans les **10 minutes**.","prio":"P1","sec":"s2"},{"id":"fc-339-c03b32","poly":"cardio","fiche":"339","front":"Douleur angineuse typique : quelles caractéristiques ?","back":"**Rétrosternale**, **en barre**, **constrictive** ; irradiation bras, cou, **mâchoire** ; intermittente ou persistante.","prio":"P1","sec":"s2"},{"id":"fc-339-8e71fa","poly":"cardio","fiche":"339","front":"SCA : quels signes associés possibles ?","back":"**Sueurs**, nausées, gêne épigastrique, **dyspnée**, malaise lipothymique, voire syncope.","prio":"P2","sec":"s2"},{"id":"fc-339-95605f","poly":"cardio","fiche":"339","front":"SCA : quelles formes atypiques ?","back":"Douleur **épigastrique** ou absente, limitée aux irradiations, brûlure, **dyspnée** ou **asthénie** isolée.","prio":"P1","sec":"s2"},{"id":"fc-339-479a3e","poly":"cardio","fiche":"339","front":"SCA atypique : chez quels patients est-il plus fréquent ?","back":"**Sujet âgé**, **femme**, **diabétique**, **insuffisant rénal**, patient **dément**.","prio":"P1","sec":"s2"},{"id":"fc-339-18b901","poly":"cardio","fiche":"339","front":"Soulagement par la trinitrine : quelle valeur diagnostique ?","back":"**Évocateur mais non spécifique**, et seulement dans le SCA ST-.","prio":"P2","sec":"s2"},{"id":"fc-339-eddce8","poly":"cardio","fiche":"339","front":"Quels tableaux douloureux orientent vers un SCA ST- ?","back":"Douleur spontanée **> 20 min** ; angor **inaugural récent** (< 1 mois) ; angor **crescendo** ; angor **post-IDM**.","prio":"P1","sec":"s2"},{"id":"fc-339-7a645b","poly":"cardio","fiche":"339","front":"Angor inaugural récent orientant vers un SCA ST- : quels critères ?","back":"Moins d'**1 mois**, pour des efforts modérés (classes **II-III** de la CCS).","prio":"P2","sec":"s2"},{"id":"fc-339-28338a","poly":"cardio","fiche":"339","front":"SCA : citer des facteurs de déstabilisation ?","back":"**Anémie**, **infection**, hyperthermie, poussée hypertensive, émotion, exercice violent, **hyperthyroïdie**, chirurgie.","prio":"P2","sec":"s2"},{"id":"fc-339-ab364c","poly":"cardio","fiche":"339","front":"SCA : quel terrain le rend plus probable ?","back":"Âge, homme, **tabac**, hérédité, **diabète**, dyslipidémie, **HTA**, IRC, athérome connu.","prio":"P2","sec":"s2"},{"id":"fc-339-9a2f9c","poly":"cardio","fiche":"339","front":"SCA : que chercher à l'examen physique ?","back":"**Insuffisance cardiaque** congestive, **souffle systolique** (complication mécanique), facteurs de risque, autres localisations athéromateuses.","prio":"P2","sec":"s2"},{"id":"fc-339-1d7250","poly":"cardio","fiche":"339","front":"Douleur thoracique : pourquoi mesurer la PA aux deux bras ?","back":"Une **asymétrie** évoque une **dissection aortique**.","prio":"P1","sec":"s2"},{"id":"fc-339-afffee","poly":"cardio","fiche":"339","front":"ECG 12 dérivations initial du SCA : quels sont ses deux buts ?","back":"**Diagnostic** (sus-décalage persistant ou non) + détection d'une **arythmie ventriculaire** menaçante (**TV**, **FV**).","prio":"P2","sec":"s3"},{"id":"fc-339-023d22","poly":"cardio","fiche":"339","front":"SCA ST- : quand doser la troponine ultrasensible ?","back":"À l'**admission** puis **1 à 2 h** plus tard.","prio":"P1","sec":"s3"},{"id":"fc-339-08a4fe","poly":"cardio","fiche":"339","front":"SCA : quel bilan biologique standard ?","back":"**Glycémie**, **bilan lipidique**, **créatininémie**, **NFS**.","prio":"P2","sec":"s3"},{"id":"fc-339-0f93c6","poly":"cardio","fiche":"339","front":"ETT dans le SCA : quelle place selon le type ?","back":"Ne doit **pas retarder** un ST+ (sauf complication mécanique suspectée) ; très largement indiquée dans le ST-.","prio":"P2","sec":"s3"},{"id":"fc-339-a866b0","poly":"cardio","fiche":"339","front":"Sus-décalage du ST : quel aspect et combien de dérivations ?","back":"Onde de **Pardee** convexe vers le haut, dans **au moins 2 dérivations contiguës**.","prio":"P1","sec":"s3"},{"id":"fc-339-40ad39","poly":"cardio","fiche":"339","front":"Sus-décalage du ST : quel seuil en V2-V3 ?","back":"**≥ 2 mm** (≥ 2,5 mm chez l'homme < 40 ans ; ≥ 1,5 mm chez la femme).","prio":"P1","sec":"s3"},{"id":"fc-339-6344f2","poly":"cardio","fiche":"339","front":"Sus-décalage du ST : quel seuil hors V2-V3 ?","back":"**≥ 1 mm** (en l'absence de BBG ou d'HVG).","prio":"P1","sec":"s3"},{"id":"fc-339-4ec244","poly":"cardio","fiche":"339","front":"SCA ST+ : à partir de quand apparaît l'onde Q de nécrose ?","back":"Classiquement à partir de la **6ᵉ heure**.","prio":"P2","sec":"s3"},{"id":"fc-339-57fbb4","poly":"cardio","fiche":"339","front":"SCA ST+ : qu'est-ce que le miroir ?","back":"Un **sous-décalage** dans les dérivations **opposées** (habituel).","prio":"P2","sec":"s3"},{"id":"fc-339-653817","poly":"cardio","fiche":"339","front":"Sus-décalage en V1, V2, V3 : quel territoire ?","back":"**Antéroseptal**.","prio":"P1","sec":"s3"},{"id":"fc-339-9e312a","poly":"cardio","fiche":"339","front":"Sus-décalage en V4 : quel territoire ?","back":"**Apical**.","prio":"P2","sec":"s3"},{"id":"fc-339-a88541","poly":"cardio","fiche":"339","front":"Sus-décalage en V5, V6 : quel territoire ?","back":"**Latéral bas**.","prio":"P2","sec":"s3"},{"id":"fc-339-56fa92","poly":"cardio","fiche":"339","front":"Sus-décalage en D1, aVL : quel territoire ?","back":"**Latéral haut**.","prio":"P1","sec":"s3"},{"id":"fc-339-a7fcdd","poly":"cardio","fiche":"339","front":"Sus-décalage en D2, D3, aVF : quel territoire ?","back":"**Inférieur**.","prio":"P1","sec":"s3"},{"id":"fc-339-90a62a","poly":"cardio","fiche":"339","front":"Sus-décalage en V7, V8, V9 : quel territoire ?","back":"**Postérieur**.","prio":"P1","sec":"s3"},{"id":"fc-339-cbba67","poly":"cardio","fiche":"339","front":"Sus-décalage de V1 à V6 : quel territoire ?","back":"**Antérieur étendu**.","prio":"P2","sec":"s3"},{"id":"fc-339-382484","poly":"cardio","fiche":"339","front":"Sus-décalage inférieur : quelles dérivations ajouter ?","back":"**V3R-V4R** (extension au ventricule droit).","prio":"P1","sec":"s3"},{"id":"fc-339-dcc759","poly":"cardio","fiche":"339","front":"Sous-décalage V1-V3 avec angor persistant : quelle conduite ECG ?","back":"Enregistrer **V7-V9** : un sus-décalage **≥ 0,5 mm** confirme un SCA ST+ (miroir).","prio":"P1","sec":"s3"},{"id":"fc-339-b1188b","poly":"cardio","fiche":"339","front":"BBG chez un patient avec angor persistant : quelle valeur ?","back":"**Équivalent de sus-décalage** (récent ou non).","prio":"P1","sec":"s3"},{"id":"fc-339-e6ab9d","poly":"cardio","fiche":"339","front":"BBG supposé récent chez un patient asymptomatique : quelle valeur ?","back":"**Aucune valeur diagnostique**.","prio":"P2","sec":"s3"},{"id":"fc-339-62cb57","poly":"cardio","fiche":"339","front":"BBD associé à une ischémie : quelle valeur ?","back":"**Équivalent de sus-décalage** (pronostic péjoratif, souvent territoire antérieur).","prio":"P2","sec":"s3"},{"id":"fc-339-049a6c","poly":"cardio","fiche":"339","front":"Pacemaker en stimulation ventriculaire : quelle limite de l'ECG ?","back":"Il ne permet **pas de voir** un sus-décalage.","prio":"P3","sec":"s3"},{"id":"fc-339-9fdfc6","poly":"cardio","fiche":"339","front":"Angor prolongé persistant avec ECG non contributif : conduite ?","back":"**Coronarographie au plus vite**, même si un autre diagnostic est évoqué, dès que le terrain expose.","prio":"P2","sec":"s3"},{"id":"fc-339-4b4d2c","poly":"cardio","fiche":"339","front":"SCA ST- : un ECG normal élimine-t-il le diagnostic ?","back":"**Non** : normal chez **plus de 30 %** des patients.","prio":"P1","sec":"s3"},{"id":"fc-339-edb499","poly":"cardio","fiche":"339","front":"SCA ST- : quand renouveler l'ECG ?","back":"Si la **douleur revient**, et systématiquement **1 à 2 h** plus tard.","prio":"P1","sec":"s3"},{"id":"fc-339-f2a6e7","poly":"cardio","fiche":"339","front":"BBD chez un patient symptomatique : quel aspect oriente vers un SCA ST- ?","back":"**Sous-décalage** de ST en **D1-aVL** et **V5-V6**.","prio":"P3","sec":"s3"},{"id":"fc-339-b4e53d","poly":"cardio","fiche":"339","front":"Troponine ultrasensible : quelle cinétique ?","back":"Monte **dans l'heure** suivant la douleur, reste élevée **plusieurs jours**.","prio":"P2","sec":"s3"},{"id":"fc-339-99bd50","poly":"cardio","fiche":"339","front":"Troponine élevée : quelles causes non coronaires ?","back":"**Tachyarythmie**, **IC**, poussée hypertensive, **myocardite**, valvulopathie, **EP**, **dissection aortique**, **takotsubo**…","prio":"P1","sec":"s3"},{"id":"fc-339-71af2a","poly":"cardio","fiche":"339","front":"Troponine ultrasensible : de quels paramètres dépendent ses valeurs ?","back":"**Âge**, **insuffisance rénale**, délai depuis les symptômes, **sexe**.","prio":"P3","sec":"s3"},{"id":"fc-339-d60eb2","poly":"cardio","fiche":"339","front":"Algorithme troponine 0/1-2 h : que signifie rule-in ?","back":"SCA **très probable** : valeur initiale très élevée ou **hausse significative**.","prio":"P2","sec":"s3"},{"id":"fc-339-c6df05","poly":"cardio","fiche":"339","front":"Algorithme troponine 0/1-2 h : que signifie rule-out ?","back":"SCA **très peu probable** : valeur initiale **très basse et stable**.","prio":"P2","sec":"s3"},{"id":"fc-339-b45453","poly":"cardio","fiche":"339","front":"ETT dans le SCA : qu'apporte-t-elle ?","back":"Troubles de **cinétique segmentaire** et **FEVG** (pronostique) ; aide au diagnostic différentiel.","prio":"P2","sec":"s3"},{"id":"fc-339-697b07","poly":"cardio","fiche":"339","front":"Coroscanner : quel est son principal atout diagnostique ?","back":"Excellente **valeur prédictive négative** (peu invasif, montre la sténose et analyse la plaque).","prio":"P3","sec":"s3"},{"id":"fc-339-c38149","poly":"cardio","fiche":"339","front":"SCA ST+ : quel délai décide entre angioplastie primaire et fibrinolyse ?","back":"**120 minutes** : angioplastie si faisable dans ce délai, sinon **fibrinolyse**.","prio":"P1","sec":"s4"},{"id":"fc-339-d2e4c2","poly":"cardio","fiche":"339","front":"SCA ST+ avec angioplastie faisable à temps : quel trajet du patient ?","back":"Transfert **direct en salle de coronarographie** puis Usic après revascularisation.","prio":"P1","sec":"s4"},{"id":"fc-339-716aab","poly":"cardio","fiche":"339","front":"Après fibrinolyse : quelle conduite selon le résultat ?","back":"**Échec** → angioplastie de **sauvetage** ; **succès** → coronarographie **dans les 24 h**.","prio":"P1","sec":"s4"},{"id":"fc-339-1d5f83","poly":"cardio","fiche":"339","front":"Reperfusion du SCA ST+ : à partir de quand le bénéfice devient-il faible ?","back":"À partir de la **12ᵉ heure** (voire nul après la 24ᵉ).","prio":"P1","sec":"s4"},{"id":"fc-339-97e500","poly":"cardio","fiche":"339","front":"SCA ST- à très haut risque : dans quel délai la coronarographie ?","back":"**Dans les 2 heures** (comme un ST+), transfert immédiat.","prio":"P1","sec":"s4"},{"id":"fc-339-8a5798","poly":"cardio","fiche":"339","front":"SCA ST- : quels critères de très haut risque ?","back":"**Instabilité hémodynamique**/choc ; douleur **réfractaire** ; **IC** ; **TV/FV**/arrêt ; **complication mécanique** ; ECG dynamique.","prio":"P1","sec":"s4"},{"id":"fc-339-b10e91","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : dans quel délai la coronarographie ?","back":"**Dans les 24 heures**.","prio":"P1","sec":"s4"},{"id":"fc-339-518f10","poly":"cardio","fiche":"339","front":"SCA ST- : quels critères de haut risque ?","back":"**IDM ST- confirmé** (troponine) ; **GRACE > 140** ; sus-décalage **transitoire** ; sous-décalage **dynamique** ou T négativées.","prio":"P1","sec":"s4"},{"id":"fc-339-f67a57","poly":"cardio","fiche":"339","front":"SCA ST- sans critère de risque : quelle stratégie ?","back":"Stratégie invasive **ou** test non invasif, selon les habitudes et les explorations disponibles.","prio":"P2","sec":"s4"},{"id":"fc-339-76d0b1","poly":"cardio","fiche":"339","front":"SCA : quels facteurs de risque hémorragique évaluer ?","back":"**> 75 ans**, sexe **féminin**, **insuffisance rénale**, diathèse hémorragique, **AVC ancien**, poids **< 65 kg**, chirurgie récente.","prio":"P3","sec":"s4"},{"id":"fc-339-c02cb1","poly":"cardio","fiche":"339","front":"SCA ST- : où hospitaliser le patient ?","back":"Habituellement **soins intensifs** ; **unité douleur thoracique** possible si non compliqué ou bas risque.","prio":"P2","sec":"s4"},{"id":"fc-339-2e0b96","poly":"cardio","fiche":"339","front":"SCA : citer les notions inacceptables ?","back":"Ne pas **évoquer** le diagnostic à l'interrogatoire ; ne pas faire l'**ECG** immédiat ; ne pas doser la **troponine** 0 et 1-2 h ; ne pas évaluer la **gravité** du ST-.","prio":"P1","sec":"s4"},{"id":"fc-339-cc7371","poly":"cardio","fiche":"339","front":"Douleur thoracique au SAU : quelle part est d'origine non cardiaque ?","back":"Environ **50 %**.","prio":"P2","sec":"s5"},{"id":"fc-339-47f760","poly":"cardio","fiche":"339","front":"Douleur thoracique au SAU : quelle part d'IDM ST+, d'IDM ST- et d'angor instable ?","back":"**5-10 %** IDM ST+ ; **15-20 %** IDM ST- ; **10 %** angor instable.","prio":"P3","sec":"s5"},{"id":"fc-339-238a18","poly":"cardio","fiche":"339","front":"SCA : quels diagnostics différentiels cardiovasculaires non coronariens ?","back":"**Dissection aortique**, **embolie pulmonaire**, **myocardite/péricardite**, **takotsubo**.","prio":"P1","sec":"s5"},{"id":"fc-339-1f92d9","poly":"cardio","fiche":"339","front":"SCA : citer des diagnostics différentiels extracardiaques ?","back":"**Pneumothorax**, pleurésie, pneumopathie, fracture de côte, **pancréatite**, cholécystite, **RGO**, œsophagite.","prio":"P2","sec":"s5"},{"id":"fc-339-8e55a0","poly":"cardio","fiche":"339","front":"Syndrome de takotsubo : quelle particularité ECG ?","back":"Le **sus-décalage** de ST est parfois **absent**.","prio":"P3","sec":"s5"},{"id":"fc-339-ceb2cb","poly":"cardio","fiche":"339","front":"MINOCA : quelle définition ?","back":"Critères d'**IDM** **sans** sténose **> 50 %** en coronarographie ou coroscanner.","prio":"P2","sec":"s5"},{"id":"fc-339-30cd49","poly":"cardio","fiche":"339","front":"MINOCA : quelle fréquence et quel profil ?","back":"Environ **6 %** des SCA ; plutôt **IDM ST-**, patients plus **jeunes**, ≈ 40 % de **femmes**.","prio":"P3","sec":"s5"},{"id":"fc-339-becf09","poly":"cardio","fiche":"339","front":"MINOCA : quels examens ont une place importante dans le diagnostic ?","back":"L'**IRM** et l'**imagerie endocoronarienne**.","prio":"P3","sec":"s5"},{"id":"fc-339-9aa581","poly":"cardio","fiche":"339","front":"Spasme, dissection coronaire spontanée, embolie coronaire : quel type d'IDM ?","back":"**Type 2**.","prio":"P3","sec":"s5"},{"id":"fc-339-a0b546","poly":"cardio","fiche":"339","front":"SCA ST+ : quand débuter l'aspirine, et à quelle dose ?","back":"**Dès la suspicion** : **250 mg IVD**, puis **75-100 mg/j** per os, + IPP.","prio":"P1","sec":"s6"},{"id":"fc-339-58f2a5","poly":"cardio","fiche":"339","front":"SCA ST+ par angioplastie primaire : quel P2Y12 en 1re intention ?","back":"**Prasugrel** ou **ticagrélor** (clopidogrel si CI ou risque hémorragique).","prio":"P1","sec":"s6"},{"id":"fc-339-2d94fc","poly":"cardio","fiche":"339","front":"SCA : quelle dose du prasugrel ?","back":"Charge **60 mg** per os → **10 mg/j**.","prio":"P1","sec":"s6"},{"id":"fc-339-dfc6da","poly":"cardio","fiche":"339","front":"SCA : quelle dose du ticagrélor ?","back":"Charge **180 mg** → **90 mg matin et soir**.","prio":"P1","sec":"s6"},{"id":"fc-339-79388b","poly":"cardio","fiche":"339","front":"SCA : quelle dose du clopidogrel (hors fibrinolyse) ?","back":"Charge **600 mg** per os → **75 mg/j**.","prio":"P1","sec":"s6"},{"id":"fc-339-3fbc31","poly":"cardio","fiche":"339","front":"Prasugrel : quand est-il contre-indiqué ou non recommandé ?","back":"**CI** si ATCD d'**AVC** ; non recommandé si **> 75 ans** et/ou **< 60 kg**.","prio":"P1","sec":"s6"},{"id":"fc-339-d11b01","poly":"cardio","fiche":"339","front":"Ticagrélor : quels effets indésirables ?","back":"**Bradycardie** et **dyspnée**, réversibles à l'arrêt.","prio":"P2","sec":"s6"},{"id":"fc-339-d50f92","poly":"cardio","fiche":"339","front":"Clopidogrel dans le SCA : quand l'utiliser ?","back":"Si prasugrel et ticagrélor **contre-indiqués** (risque hémorragique, ATCD d'AVC, insuffisance hépatique sévère).","prio":"P2","sec":"s6"},{"id":"fc-339-0f0e45","poly":"cardio","fiche":"339","front":"Angioplastie primaire : quel anticoagulant et quelle dose ?","back":"**HNF 70-100 UI/kg IVD** ou **énoxaparine 0,5 mg/kg IVD**.","prio":"P1","sec":"s6"},{"id":"fc-339-be0521","poly":"cardio","fiche":"339","front":"Angioplastie primaire : quand arrêter l'anticoagulant ?","back":"Habituellement **juste après la revascularisation**.","prio":"P2","sec":"s6"},{"id":"fc-339-b0bf64","poly":"cardio","fiche":"339","front":"Angioplastie coronaire : quelle voie d'abord préférer et pourquoi ?","back":"**Radiale** : beaucoup **moins de saignements** que la fémorale.","prio":"P1","sec":"s6"},{"id":"fc-339-f0ff93","poly":"cardio","fiche":"339","front":"SCA : quand donner de l'oxygène ?","back":"Seulement si **SaO₂ < 90 %** ou **PaO₂ < 60 mmHg** (hyperoxie délétère).","prio":"P1","sec":"s6"},{"id":"fc-339-e2bdc4","poly":"cardio","fiche":"339","front":"SCA : quand donner de la morphine ?","back":"Si **douleur persistante invalidante**.","prio":"P2","sec":"s6"},{"id":"fc-339-adaf9d","poly":"cardio","fiche":"339","front":"Dérivés nitrés IV dans le SCA : quelle molécule et quelle dose ?","back":"**Dinitrate d'isosorbide 2 mg/h**, adapté à la PA.","prio":"P2","sec":"s6"},{"id":"fc-339-9f0a8b","poly":"cardio","fiche":"339","front":"Infarctus du VD : quelle classe est contre-indiquée ?","back":"Les **vasodilatateurs** (dérivés nitrés…).","prio":"P1","sec":"s6"},{"id":"fc-339-758eb6","poly":"cardio","fiche":"339","front":"SCA ST+ pluritronculaire : que faire des autres sténoses significatives ?","back":"**Revascularisation systématique** recommandée.","prio":"P2","sec":"s6"},{"id":"fc-339-df492c","poly":"cardio","fiche":"339","front":"Bêtabloquants dans le SCA : quel effet recherché ?","back":"Baisse de la **consommation d'O₂** (bradycardisants, hypotenseurs, inotropes négatifs).","prio":"P2","sec":"s6"},{"id":"fc-339-bd89b9","poly":"cardio","fiche":"339","front":"Fibrinolyse : quel est le seul inhibiteur P2Y12 autorisé ?","back":"Le **clopidogrel**.","prio":"P1","sec":"s7"},{"id":"fc-339-b579be","poly":"cardio","fiche":"339","front":"Clopidogrel avec fibrinolyse : quelle dose de charge ?","back":"**300 mg**, seulement si âge **< 75 ans** (pas de charge sinon) ; entretien 75 mg/j.","prio":"P1","sec":"s7"},{"id":"fc-339-e37303","poly":"cardio","fiche":"339","front":"Fibrinolyse du SCA ST+ : où et quand ?","back":"IV, **immédiate**, **dès le domicile**.","prio":"P2","sec":"s7"},{"id":"fc-339-7178d4","poly":"cardio","fiche":"339","front":"Fibrinolyse réussie : faut-il transférer le patient ?","back":"**Oui** : vers un centre avec salle de cathétérisme (coronarographie dans les 24 h).","prio":"P1","sec":"s7"},{"id":"fc-339-e82998","poly":"cardio","fiche":"339","front":"Fibrinolyse : quelles contre-indications absolues cérébrales ?","back":"ATCD d'**AVC hémorragique** ; **AVC < 6 mois** ; malformation ou tumeur cérébrale ; **traumatisme cérébral < 1 mois**.","prio":"P1","sec":"s7"},{"id":"fc-339-d4d12c","poly":"cardio","fiche":"339","front":"Fibrinolyse : quelles contre-indications absolues non cérébrales ?","back":"**Hémorragie digestive < 1 mois** ; anomalie de l'hémostase ; ponction/biopsie ou PL **< 24 h** ; **dissection aortique**.","prio":"P1","sec":"s7"},{"id":"fc-339-9cd3b1","poly":"cardio","fiche":"339","front":"SCA ST- : quand donner l'inhibiteur P2Y12 ?","back":"**Après la coronarographie**, **avant l'angioplastie** (souvent sur table).","prio":"P1","sec":"s8"},{"id":"fc-339-df238f","poly":"cardio","fiche":"339","front":"SCA ST- : quand peut-on donner le P2Y12 avant la coronarographie ?","back":"Si la coronarographie ne peut être faite **avant 24 h**.","prio":"P2","sec":"s8"},{"id":"fc-339-25f932","poly":"cardio","fiche":"339","front":"SCA ST- : pourquoi pas de double antiagrégation dès l'admission ?","back":"**Plus de saignements**.","prio":"P2","sec":"s8"},{"id":"fc-339-1458a6","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : quelle dose d'énoxaparine ?","back":"**1 mg/kg SC matin et soir**.","prio":"P1","sec":"s8"},{"id":"fc-339-716c84","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : quelle dose de fondaparinux, et quel ajout ?","back":"**2,5 mg/j SC** + **bolus d'HNF** pendant la coronarographie.","prio":"P1","sec":"s8"},{"id":"fc-339-539773","poly":"cardio","fiche":"339","front":"SCA ST- : quand utiliser l'HNF IVSE, et à quelle dose ?","back":"Si **IRC sévère** (CI des HBPM et du fondaparinux) : **400-600 UI/kg/24 h**.","prio":"P2","sec":"s8"},{"id":"fc-339-29c5d5","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : combien de temps dure l'anticoagulation ?","back":"De l'**admission en Usic** jusqu'à l'**angioplastie** ou au **pontage**.","prio":"P2","sec":"s8"},{"id":"fc-339-c68e76","poly":"cardio","fiche":"339","front":"SCA ST- : de quoi dépend le choix angioplastie ou pontage ?","back":"**Siège et étendue** des lésions, **âge**, **comorbidités**, **risque opératoire**.","prio":"P2","sec":"s8"},{"id":"fc-339-316be4","poly":"cardio","fiche":"339","front":"SCA ST- : quand le pontage est-il plutôt retenu ?","back":"Lésions du **tronc coronaire gauche** ou **tritronculaires complexes**, surtout chez le **diabétique**.","prio":"P3","sec":"s8"},{"id":"fc-339-0788ec","poly":"cardio","fiche":"339","front":"SCA ST- sans complication : quand le patient sort-il ?","back":"**24-48 h** après la revascularisation.","prio":"P2","sec":"s8"},{"id":"fc-339-3ee148","poly":"cardio","fiche":"339","front":"Dérivés nitrés IV dans le SCA ST- : quel but ?","back":"Visée **antalgique** (aussi antihypertensive ou IC congestive).","prio":"P2","sec":"s8"},{"id":"fc-339-3647c4","poly":"cardio","fiche":"339","front":"Angioplastie coronaire : comment se déroule-t-elle ?","back":"Lésion franchie par un **guide**, dilatée au **ballonnet** ; un **stent** serti sur le ballonnet peut être plaqué dans la paroi.","prio":"P2","sec":"s9"},{"id":"fc-339-438220","poly":"cardio","fiche":"339","front":"Angioplastie : pourquoi donner HNF ou HBPM pendant le geste ?","back":"Pour éviter la **thrombose du cathéter**.","prio":"P2","sec":"s9"},{"id":"fc-339-06630e","poly":"cardio","fiche":"339","front":"Après angioplastie pour SCA : durée de la bithérapie antiagrégante ?","back":"**12 mois** (modulable selon les risques ischémique et hémorragique).","prio":"P1","sec":"s9"},{"id":"fc-339-a179da","poly":"cardio","fiche":"339","front":"Après angioplastie dans l'angor stable : durée habituelle de la bithérapie ?","back":"**6 mois**.","prio":"P2","sec":"s9"},{"id":"fc-339-7e2e2c","poly":"cardio","fiche":"339","front":"Pontage coronarien : quel greffon préférer ?","back":"**Artériel** (artères **mammaires**) ; possiblement veineux (**veine saphène**).","prio":"P2","sec":"s9"},{"id":"fc-339-d9b662","poly":"cardio","fiche":"339","front":"Pontage coronarien : traite-t-il la lésion ?","back":"**Non** : il la **contourne**.","prio":"P2","sec":"s9"},{"id":"fc-339-b9efbf","poly":"cardio","fiche":"339","front":"Pontage coronarien : quelles conditions opératoires habituelles ?","back":"**Sternotomie**, anesthésie générale, cœur arrêté, **circulation extracorporelle**.","prio":"P3","sec":"s9"},{"id":"fc-339-914246","poly":"cardio","fiche":"339","front":"Usic après SCA : quelle surveillance clinique et ECG ?","back":"PA et auscultation **2 fois/j** ; **monitorage ECG continu**.","prio":"P2","sec":"s10"},{"id":"fc-339-93764a","poly":"cardio","fiche":"339","front":"Usic après SCA : quelle surveillance biologique ?","back":"Troponine, glycémie, créatininémie, NFS **chaque jour**.","prio":"P2","sec":"s10"},{"id":"fc-339-77a736","poly":"cardio","fiche":"339","front":"Usic après SCA : quand faire l'ETT ?","back":"**Le jour de l'admission**, puis selon l'évolution.","prio":"P2","sec":"s10"},{"id":"fc-339-369647","poly":"cardio","fiche":"339","front":"SCA ST+ sans complication : quand le patient sort-il ?","back":"Entre **J3 et J5**.","prio":"P2","sec":"s10"},{"id":"fc-339-2a6bbf","poly":"cardio","fiche":"339","front":"Usic : quel est l'objectif principal ?","back":"Dépister et traiter une **complication précoce** (surtout **rythmique**) ; plus fréquentes dans le ST+.","prio":"P1","sec":"s10"},{"id":"fc-339-5f4688","poly":"cardio","fiche":"339","front":"Phase aiguë du SCA : quel trouble du rythme cause la plupart des morts subites ?","back":"La **fibrillation ventriculaire**.","prio":"P1","sec":"s10"},{"id":"fc-339-12f7e3","poly":"cardio","fiche":"339","front":"FV au cours d'un SCA : conduite ?","back":"**Choc électrique externe immédiat** (jamais réversible spontanément).","prio":"P1","sec":"s10"},{"id":"fc-339-895cd5","poly":"cardio","fiche":"339","front":"Troubles du rythme ventriculaire à la phase aiguë : fréquence et lien avec l'étendue de l'ischémie ?","back":"**Très fréquents** et **indépendants** de l'étendue de l'ischémie (ESV → TV → FV).","prio":"P2","sec":"s10"},{"id":"fc-339-efb1f5","poly":"cardio","fiche":"339","front":"FA compliquant un SCA : conduite ?","back":"**Cardioversion** immédiate si mal tolérée ; **anticoagulation** (prévention des embolies).","prio":"P2","sec":"s10"},{"id":"fc-339-3bd9f9","poly":"cardio","fiche":"339","front":"BAV nodal compliquant un SCA : quel territoire et quelle évolution ?","back":"SCA ST+ **inférieur** ; habituellement **transitoire**, répond à l'**atropine**.","prio":"P1","sec":"s10"},{"id":"fc-339-1017df","poly":"cardio","fiche":"339","front":"BAV infranodal compliquant un SCA : quel territoire et quel traitement ?","back":"SCA ST+ **antérieur** ; **pas** de réponse à l'atropine → sonde d'entraînement, souvent **stimulateur permanent**.","prio":"P1","sec":"s10"},{"id":"fc-339-6cee26","poly":"cardio","fiche":"339","front":"Hypertonie vagale du SCA ST+ inférieur : quel traitement ?","back":"**Atropine** + **remplissage** macromoléculaire.","prio":"P2","sec":"s10"},{"id":"fc-339-15d18d","poly":"cardio","fiche":"339","front":"IVG compliquant un SCA : quel traitement ?","back":"**Diurétiques**, **IEC**, **antagonistes des récepteurs minéralocorticoïdes**.","prio":"P2","sec":"s10"},{"id":"fc-339-9feca8","poly":"cardio","fiche":"339","front":"IVG après SCA : quel examen systématique ?","back":"L'**échographie** (complication mécanique ?).","prio":"P2","sec":"s10"},{"id":"fc-339-d78830","poly":"cardio","fiche":"339","front":"Classification de Killip : quels 4 stades ?","back":"**1** pas de râles ; **2** râles < moitié des champs ; **3** râles > moitié (**OAP**), galop ; **4** **choc cardiogénique**.","prio":"P1","sec":"s10"},{"id":"fc-339-689bfb","poly":"cardio","fiche":"339","front":"Préchoc cardiogénique après SCA : quelle définition ?","back":"**PAS < 90 mmHg** mal tolérée, ne répondant pas au remplissage, persistant après correction d'une bradycardie vagale.","prio":"P2","sec":"s10"},{"id":"fc-339-e594d6","poly":"cardio","fiche":"339","front":"Choc cardiogénique constitué : quels signes ?","back":"**Extrémités froides**, **oligurie**, **confusion**.","prio":"P2","sec":"s10"},{"id":"fc-339-a0f089","poly":"cardio","fiche":"339","front":"Choc cardiogénique constitué après SCA : quel traitement ?","back":"**Dobutamine** puis, si le terrain le permet, **assistance circulatoire**.","prio":"P1","sec":"s10"},{"id":"fc-339-548291","poly":"cardio","fiche":"339","front":"Choc cardiogénique compliquant un SCA : quelle mortalité hospitalière ?","back":"**Supérieure à 70 %**.","prio":"P2","sec":"s10"},{"id":"fc-339-f6a123","poly":"cardio","fiche":"339","front":"Préchoc cardiogénique après SCA : quel traitement ?","back":"**Revascularisation rapide** ou chirurgie de la complication mécanique.","prio":"P3","sec":"s10"},{"id":"fc-339-a84f61","poly":"cardio","fiche":"339","front":"Infarctus du VD : quelle triade clinique ?","back":"**Hypotension** + **champs pulmonaires clairs** + **turgescence jugulaire** (complique l'IDM inférieur).","prio":"P1","sec":"s10"},{"id":"fc-339-d98f46","poly":"cardio","fiche":"339","front":"Infarctus du VD : quels signes ECG et échographiques ?","back":"Sus-décalage en **V3R-V4R** ; ETT : **VD dilaté hypokinétique**, OD dilatée, IT.","prio":"P2","sec":"s10"},{"id":"fc-339-5894ab","poly":"cardio","fiche":"339","front":"Rupture de la paroi libre du VG : quels signes de la forme subaiguë ?","back":"**Récidive douloureuse** + **ST qui remonte** + **hypotension** brutale et prolongée.","prio":"P2","sec":"s10"},{"id":"fc-339-dd43b5","poly":"cardio","fiche":"339","front":"Rupture de la paroi libre du VG : conduite ?","back":"**ETT immédiate** ; hémopéricarde → **chirurgie immédiate**.","prio":"P2","sec":"s10"},{"id":"fc-339-0bf1b8","poly":"cardio","fiche":"339","front":"Rupture septale post-IDM : quel signe clinique ?","back":"**Souffle systolique** typiquement **« en rayon de roue »** (dans les 24-48 h).","prio":"P2","sec":"s10"},{"id":"fc-339-a5f9e2","poly":"cardio","fiche":"339","front":"Rupture septale post-IDM : quand la fermer ?","back":"De préférence **différée de quelques jours** (chirurgicale ou percutanée).","prio":"P3","sec":"s10"},{"id":"fc-339-b5f6ff","poly":"cardio","fiche":"339","front":"OAP compliquant un IDM inférieur : quelle complication évoquer ?","back":"Une **rupture de pilier mitral** (postéromédian).","prio":"P1","sec":"s10"},{"id":"fc-339-aa9470","poly":"cardio","fiche":"339","front":"Rupture de pilier mitral : pourquoi le pilier postéromédian ?","back":"Vascularisé par la **coronaire droite seule**.","prio":"P2","sec":"s10"},{"id":"fc-339-0fd6a1","poly":"cardio","fiche":"339","front":"Rupture de pilier mitral : quel traitement ?","back":"**Chirurgie urgente** (suture ou remplacement valvulaire) ; parfois Mitraclip®.","prio":"P2","sec":"s10"},{"id":"fc-339-b39e6f","poly":"cardio","fiche":"339","front":"Thrombus intra-VG post-IDM : quand le dépister et comment le traiter ?","back":"**ETT dans les 48 h** (surtout ST+ antérieur) ; **anticoagulation curative**.","prio":"P2","sec":"s10"},{"id":"fc-339-296182","poly":"cardio","fiche":"339","front":"TVP/EP après SCA : pourquoi sont-elles devenues rares ?","back":"**Anticoagulants** à la phase aiguë et **mobilisation rapide**.","prio":"P3","sec":"s10"},{"id":"fc-339-37cf83","poly":"cardio","fiche":"339","front":"Récidive ischémique après SCA : quels mécanismes ?","back":"**Réocclusion** de l'artère traitée (ST+) ou ischémie à distance chez le **pluritronculaire**.","prio":"P3","sec":"s10"},{"id":"fc-339-212692","poly":"cardio","fiche":"339","front":"Syndrome de Dressler : quand survient-il et comment se présente-t-il ?","back":"**Classiquement 3ᵉ semaine** post-IDM étendu : épanchement péricardique ± pleural, **arthralgies**, **fièvre**, syndrome inflammatoire.","prio":"P2","sec":"s10"},{"id":"fc-339-60f259","poly":"cardio","fiche":"339","front":"Syndrome de Dressler : quel traitement ?","back":"**Anti-inflammatoire** (évolution habituellement favorable).","prio":"P3","sec":"s10"},{"id":"fc-339-6ede29","poly":"cardio","fiche":"339","front":"IVG tardive post-IDM : quels mécanismes ?","back":"**Remodelage** (dilatation du VG) ou **anévrisme** ventriculaire.","prio":"P3","sec":"s10"},{"id":"fc-339-4dc975","poly":"cardio","fiche":"339","front":"Post-IDM : quand implanter un DAI ?","back":"Si **FEVG < 35 %** à au moins **6 semaines** de l'IDM sous traitement optimisé.","prio":"P1","sec":"s10"},{"id":"fc-339-4defea","poly":"cardio","fiche":"339","front":"Post-IDM avec FEVG < 35 % à la phase précoce : quelle protection d'attente ?","back":"**Lifevest** (gilet défibrillateur) + ETT de contrôle après quelques semaines.","prio":"P2","sec":"s10"},{"id":"fc-339-387a49","poly":"cardio","fiche":"339","front":"Après un SCA : quelle durée pour l'aspirine ?","back":"**Au long cours**, **75-100 mg/j**.","prio":"P1","sec":"s11"},{"id":"fc-339-267d6b","poly":"cardio","fiche":"339","front":"Après un SCA : quelle durée pour l'inhibiteur P2Y12 ?","back":"**12 mois** par défaut (réduite à 1-6 mois si risque hémorragique, ou prolongée).","prio":"P1","sec":"s11"},{"id":"fc-339-f1b898","poly":"cardio","fiche":"339","front":"SCA avec anticoagulant oral nécessaire (FA, thrombus VG) : quelle association ?","back":"**Clopidogrel + anticoagulant pleine dose** pendant **12 mois**, puis **anticoagulant seul**.","prio":"P1","sec":"s11"},{"id":"fc-339-31379c","poly":"cardio","fiche":"339","front":"SCA avec anticoagulant oral : quand une trithérapie courte ?","back":"Faible risque hémorragique + haut risque ischémique : habituellement **1 mois**.","prio":"P3","sec":"s11"},{"id":"fc-339-74c28c","poly":"cardio","fiche":"339","front":"Après un SCA : quand prescrire un IPP ?","back":"Si **risque digestif élevé** (≥ 65 ans, ATCD d'ulcère, corticothérapie prolongée…).","prio":"P2","sec":"s11"},{"id":"fc-339-0296d0","poly":"cardio","fiche":"339","front":"Après un SCA : quelle statine en 1re intention ?","back":"**Atorvastatine 80 mg** ou **rosuvastatine 20 mg**.","prio":"P1","sec":"s11"},{"id":"fc-339-82767d","poly":"cardio","fiche":"339","front":"Après un SCA : quel objectif de LDL-C ?","back":"Baisse **≥ 50 %** **et** LDL-C **< 0,55 g/L**.","prio":"P1","sec":"s11"},{"id":"fc-339-02f3a7","poly":"cardio","fiche":"339","front":"Après un SCA, LDL-C non à l'objectif : quel ajout et quand ?","back":"**Ézétimibe 10 mg** si objectif non atteint à **4 semaines** à dose maximale tolérée.","prio":"P2","sec":"s11"},{"id":"fc-339-5225ca","poly":"cardio","fiche":"339","front":"Anti-PCSK9 après SCA : quand sont-ils remboursés ?","back":"Si le LDL-C reste **> 0,7 g/L**.","prio":"P3","sec":"s11"},{"id":"fc-339-e4b56a","poly":"cardio","fiche":"339","front":"Après un SCA : les IEC/ARA2 sont-ils systématiques ?","back":"**Non** : surtout si **FEVG ≤ 40 %**, **diabète**, **IRC**.","prio":"P2","sec":"s11"},{"id":"fc-339-be2923","poly":"cardio","fiche":"339","front":"Après un SCA : quand les bêtabloquants sont-ils formellement indiqués ?","back":"Si **FEVG ≤ 40 %** (non systématiques sinon ; poursuivis si angor résiduel).","prio":"P1","sec":"s11"},{"id":"fc-339-ce8a75","poly":"cardio","fiche":"339","front":"Après un SCA : quand prescrire un antagoniste des récepteurs minéralocorticoïdes ?","back":"**FEVG ≤ 40 %** avec **IC** ou **diabète**, après bêtabloquant + IEC.","prio":"P2","sec":"s11"},{"id":"fc-339-2d4d6a","poly":"cardio","fiche":"339","front":"Antagonistes des récepteurs minéralocorticoïdes : quelles contre-indications ?","back":"**Créatininémie > 221 µmol/L** ou **hyperkaliémie**.","prio":"P3","sec":"s11"},{"id":"fc-339-e40a4b","poly":"cardio","fiche":"339","front":"Réadaptation cardiovasculaire après SCA : à qui la proposer ?","back":"**À tous** les patients.","prio":"P1","sec":"s11"},{"id":"fc-339-cadbd0","poly":"cardio","fiche":"339","front":"Réadaptation cardiovasculaire : que comporte-t-elle ?","back":"Surveillance, **éducation thérapeutique**, **reprise d'activité physique** ; équipe pluridisciplinaire.","prio":"P2","sec":"s11"},{"id":"fc-339-eb095f","poly":"cardio","fiche":"339","front":"Après un SCA : quelle mnémotechnique pour l'ordonnance de sortie ?","back":"**BASIC** : **B**êtabloquant, **A**ntiagrégants, **S**tatine, **I**EC, **C**ontrôle des facteurs de risque (B et I non systématiques).","prio":"P2","sec":"s11"},{"id":"fc-339-9dab53","poly":"cardio","fiche":"339","front":"Suivi après SCA : quelles autres localisations athéromateuses rechercher ?","back":"**Troncs supra-aortiques**, **aorte abdominale** (anévrisme), artères des **membres inférieurs**.","prio":"P2","sec":"s11"},{"id":"fc-339-8b3f90","poly":"cardio","fiche":"339","front":"Après un SCA : quelles notions sont inacceptables ?","back":"Ne pas prescrire la **double antiagrégation**, ni de **statine**, ni prendre en charge les **facteurs de risque**.","prio":"P1","sec":"s11"},{"id":"fc-339-9bdee4","poly":"cardio","fiche":"339","front":"Angor stable : quel mécanisme ?","back":"Besoins en O₂ **> apports**, par **obstruction** (le plus souvent athérosclérose) ou **spasme**.","prio":"P1","sec":"s12"},{"id":"fc-339-5f1aea","poly":"cardio","fiche":"339","front":"Angor stable : quelles circonstances de survenue ?","back":"Surtout l'**effort**, toujours le **même type d'effort** ; aussi stress, repas copieux, **froid**.","prio":"P1","sec":"s12"},{"id":"fc-339-edab8c","poly":"cardio","fiche":"339","front":"Angor typique : comment cède-t-il ?","back":"Très vite à l'**arrêt de l'effort** ou sous **trinitrine sublinguale**.","prio":"P1","sec":"s12"},{"id":"fc-339-077603","poly":"cardio","fiche":"339","front":"Angor de novo : comment le considérer ?","back":"Comme un **SCA jusqu'à preuve du contraire**.","prio":"P1","sec":"s12"},{"id":"fc-339-1dfc5f","poly":"cardio","fiche":"339","front":"Angor stable : quelle classification de sévérité, et quelles classes à haut risque ?","back":"**Société canadienne de cardiologie (CCS)** ; classes **3 ou 4**.","prio":"P2","sec":"s12"},{"id":"fc-339-e8dd03","poly":"cardio","fiche":"339","front":"Angor stable : quelles formes atypiques ?","back":"Épigastrique ou limitée aux irradiations, **blocpnée d'effort**, palpitations d'effort, IVG, **ischémie silencieuse**.","prio":"P2","sec":"s12"},{"id":"fc-339-939794","poly":"cardio","fiche":"339","front":"Blocpnée d'effort : de quoi s'agit-il ?","back":"Impossibilité de **vider l'air à l'expiration** à l'effort (équivalent angineux).","prio":"P3","sec":"s12"},{"id":"fc-339-b44bc3","poly":"cardio","fiche":"339","front":"Angor stable : quelle cause associée chercher à l'auscultation ?","back":"Un souffle de **rétrécissement aortique**.","prio":"P2","sec":"s12"},{"id":"fc-339-c7617e","poly":"cardio","fiche":"339","front":"Cascade ischémique : dans quel ordre surviennent les anomalies ?","back":"Métaboliques (H⁺, K⁺) → **cinétique** (diastole puis systole) → **ST-T** → **douleur** (peut manquer).","prio":"P3","sec":"s12"},{"id":"fc-339-95f952","poly":"cardio","fiche":"339","front":"Angor stable : quels tests fonctionnels ?","back":"**Épreuve d'effort**, de préférence couplée à une imagerie (**écho**, **scintigraphie**, **IRM de stress**).","prio":"P1","sec":"s12"},{"id":"fc-339-04feb0","poly":"cardio","fiche":"339","front":"Tests fonctionnels d'ischémie : quelle contre-indication habituelle ?","back":"Un **SCA récent**.","prio":"P1","sec":"s12"},{"id":"fc-339-0b62a5","poly":"cardio","fiche":"339","front":"Probabilité pré-test d'angor : sur quels éléments ?","back":"**Âge**, **sexe**, **type de douleur**.","prio":"P2","sec":"s12"},{"id":"fc-339-2e9007","poly":"cardio","fiche":"339","front":"Probabilité pré-test : quels profils extrêmes ?","back":"Forte : **homme > 40 ans**, angor typique ; faible : **femme < 50 ans**, douleur atypique.","prio":"P3","sec":"s12"},{"id":"fc-339-1aeab5","poly":"cardio","fiche":"339","front":"Tests fonctionnels : quels arguments pour des sténoses sévères ou multiples ?","back":"Test **précocement positif**, ischémie étendue à **plusieurs segments**, **chute de PA**.","prio":"P2","sec":"s12"},{"id":"fc-339-875fd7","poly":"cardio","fiche":"339","front":"FFR : quel seuil définit une sténose critique ?","back":"**≤ 0,8**.","prio":"P3","sec":"s12"},{"id":"fc-339-a498a7","poly":"cardio","fiche":"339","front":"Coronarographie : citer ses risques ?","back":"**Rénaux** et **anaphylactiques** (iode), infectieux, **vasculaires**, emboliques, **rythmiques**.","prio":"P3","sec":"s12"},{"id":"fc-339-761e31","poly":"cardio","fiche":"339","front":"Coronarographie chez l'insuffisant rénal : quelles précautions ?","back":"**Hyperhydratation** préalable et **moins de contraste**.","prio":"P3","sec":"s12"},{"id":"fc-339-9c2394","poly":"cardio","fiche":"339","front":"Coroscanner : quand est-il utile dans l'angor stable ?","back":"Si tests fonctionnels **douteux ou impossibles** ; très bon pour vérifier un **pontage**.","prio":"P3","sec":"s12"},{"id":"fc-339-bf55e7","poly":"cardio","fiche":"339","front":"Coroscanner : quelles limites ?","back":"**FC rapide ou irrégulière**, **calcifications**, petites artères, stents, **irradiation**.","prio":"P3","sec":"s12"},{"id":"fc-339-daaf65","poly":"cardio","fiche":"339","front":"Angor stable : quelles mortalités annuelles définissent le risque bas, intermédiaire, haut ?","back":"Bas **< 1 %** ; intermédiaire **1 à 3 %** ; haut **> 3 %**.","prio":"P2","sec":"s12"},{"id":"fc-339-17fa9c","poly":"cardio","fiche":"339","front":"Angor stable : quels critères de haut risque ?","back":"Classe **3-4** ; **FEVG diminuée** ; épreuve d'effort positive **≤ 6 min** ; ischémie **> 10 % du VG**.","prio":"P1","sec":"s12"},{"id":"fc-339-b18ce8","poly":"cardio","fiche":"339","front":"Angor stable : quelles lésions à haut risque justifient une revascularisation ?","back":"**Tronc commun gauche**, **IVA proximale**, **tritronculaire proximale**.","prio":"P2","sec":"s12"},{"id":"fc-339-5a6675","poly":"cardio","fiche":"339","front":"Angor stable : quels traitements sont systématiques ?","back":"Correction des **facteurs de risque** + **aspirine** + **statine**.","prio":"P1","sec":"s13"},{"id":"fc-339-f9a20d","poly":"cardio","fiche":"339","front":"Crise d'angor : quel traitement ?","back":"**Trinitrine sublinguale** en spray (assis ou allongé).","prio":"P1","sec":"s13"},{"id":"fc-339-6a90e9","poly":"cardio","fiche":"339","front":"Trinitrine sublinguale : quels effets indésirables ?","back":"**Céphalées**, **chute de PA**.","prio":"P2","sec":"s13"},{"id":"fc-339-add3a3","poly":"cardio","fiche":"339","front":"Angor stable : quel anti-ischémique en 1re intention ?","back":"Les **bêtabloquants**.","prio":"P1","sec":"s13"},{"id":"fc-339-1633a3","poly":"cardio","fiche":"339","front":"Bêtabloquants : quelles contre-indications ?","back":"**Asthme**, BPCO très sévère, **Raynaud**, bradycardie **< 50/min**, **BAV 2ᵉ ou 3ᵉ degré**.","prio":"P1","sec":"s13"},{"id":"fc-339-a31d68","poly":"cardio","fiche":"339","front":"Angor stable : quand faire une coronarographie d'emblée ?","back":"Angor sévère (**classe ≥ 3**) ou **FEVG altérée**.","prio":"P2","sec":"s13"},{"id":"fc-339-4ee5b6","poly":"cardio","fiche":"339","front":"Angor stable : la revascularisation systématique est-elle supérieure au traitement médical ?","back":"**Non** : indications **symptomatique** (angor malgré traitement optimal) ou **pronostique** (haut risque).","prio":"P1","sec":"s13"},{"id":"fc-339-a27e85","poly":"cardio","fiche":"339","front":"Angor stable : quand préférer le pontage ?","back":"Lésions **diffuses** (notamment diabétique) du **tronc commun** et de l'**IVA proximale**, lit d'aval accessible.","prio":"P2","sec":"s13"},{"id":"fc-339-f51402","poly":"cardio","fiche":"339","front":"Inhibiteurs calciques bradycardisants : lesquels, et quelle association interdite ?","back":"**Diltiazem**, **vérapamil** : **ne pas associer aux bêtabloquants** (troubles de conduction).","prio":"P1","sec":"s13"},{"id":"fc-339-07595d","poly":"cardio","fiche":"339","front":"Dihydropyridines dans l'angor : quelle place ?","back":"1re intention si bêtabloquants CI ou **FC < 60/min** ; 2e intention en **association** aux bêtabloquants.","prio":"P2","sec":"s13"},{"id":"fc-339-420dd4","poly":"cardio","fiche":"339","front":"Inhibiteurs calciques : quel effet indésirable commun ?","back":"**Œdèmes des membres inférieurs** (surtout dihydropyridines).","prio":"P2","sec":"s13"},{"id":"fc-339-6d8b44","poly":"cardio","fiche":"339","front":"Dérivés nitrés LP : quelle association est contre-indiquée ?","back":"Les **inhibiteurs de la PDE5** (sildénafil).","prio":"P1","sec":"s13"},{"id":"fc-339-ed5b8a","poly":"cardio","fiche":"339","front":"Dérivés nitrés LP et molsidomine : quelle place dans l'angor stable ?","back":"**3e intention**, formes invalidantes ; timbre posé **18 h/j**.","prio":"P3","sec":"s13"},{"id":"fc-339-75c192","poly":"cardio","fiche":"339","front":"Nicorandil : quel effet indésirable caractéristique ?","back":"**Ulcérations** péribuccales, intestinales, périanales.","prio":"P3","sec":"s13"},{"id":"fc-339-82c0c3","poly":"cardio","fiche":"339","front":"Ivabradine : quelles conditions d'utilisation ?","back":"**Rythme sinusal** avec **FC ≥ 70/min** ; inefficace en FA.","prio":"P2","sec":"s13"},{"id":"fc-339-4588ec","poly":"cardio","fiche":"339","front":"Ivabradine : quel effet indésirable ?","back":"**Phosphènes** (transitoires).","prio":"P3","sec":"s13"},{"id":"fc-339-4f56bc","poly":"cardio","fiche":"339","front":"Angor stable : dose d'aspirine ?","back":"**75-100 mg/j**, systématique chez tout coronarien.","prio":"P2","sec":"s13"},{"id":"fc-339-df0610","poly":"cardio","fiche":"339","front":"Angor stable : quand prescrire le clopidogrel ?","back":"Si **CI à l'aspirine** ; avec l'aspirine après **stent actif** (≈ **6 mois**) ; parfois chez le polyartériel.","prio":"P2","sec":"s13"},{"id":"fc-339-9986ea","poly":"cardio","fiche":"339","front":"Angor stable stenté : prasugrel et ticagrélor sont-ils indiqués ?","back":"**Non**.","prio":"P2","sec":"s13"},{"id":"fc-339-1016a3","poly":"cardio","fiche":"339","front":"Stent actif : quel avantage sur le stent nu ?","back":"**Moins de resténose** (antimitotique).","prio":"P3","sec":"s13"},{"id":"fc-339-cd59ad","poly":"cardio","fiche":"339","front":"Angor stable hypertendu : quels antihypertenseurs en 1re intention ?","back":"**IEC**, **ARA2** ou **bêtabloquant** (HTA > 135/85 en automesure).","prio":"P2","sec":"s13"},{"id":"fc-342-d8163d","poly":"cardio","fiche":"342","front":"« Malaise » : est-ce un diagnostic ?","back":"**Non** : c'est une **plainte**, un motif de recours (mal-être, gêne vague).","prio":"P1","sec":"s1"},{"id":"fc-342-756100","poly":"cardio","fiche":"342","front":"PDCB : quelle définition ?","back":"Perte de conscience réelle ou apparente, **brève**, avec **amnésie** de l'épisode, perte du contrôle moteur et de la réactivité.","prio":"P1","sec":"s1"},{"id":"fc-342-5a74f2","poly":"cardio","fiche":"342","front":"PDCB : quelle première distinction faire ?","back":"PDCB **traumatique** ou **non traumatique**.","prio":"P2","sec":"s1"},{"id":"fc-342-531f6a","poly":"cardio","fiche":"342","front":"PDCB non traumatiques : quelles 3 catégories ?","back":"**Syncope**, **crise d'épilepsie**, **PDCB psychogène**.","prio":"P1","sec":"s1"},{"id":"fc-342-a693e7","poly":"cardio","fiche":"342","front":"Syncope : quelle définition ?","back":"PDCB due à une **hypoperfusion cérébrale**, de déclenchement rapide, avec récupération **complète et spontanée**.","prio":"P1","sec":"s1"},{"id":"fc-342-edc096","poly":"cardio","fiche":"342","front":"Après une syncope : comment sont le comportement et l'orientation ?","back":"**Normaux** ; aucun souvenir de la PDCB.","prio":"P2","sec":"s1"},{"id":"fc-342-320deb","poly":"cardio","fiche":"342","front":"Lipothymie : quelle définition ?","back":"Prodromes **sans perte de connaissance** (présyncope).","prio":"P1","sec":"s1"},{"id":"fc-342-46c72e","poly":"cardio","fiche":"342","front":"Lipothymie : comment la prendre en charge ?","back":"De façon **identique** à une syncope.","prio":"P1","sec":"s1"},{"id":"fc-342-a9847c","poly":"cardio","fiche":"342","front":"Syncope « à l'emporte-pièce » : quelle définition ?","back":"Syncope **sans prodrome**.","prio":"P2","sec":"s1"},{"id":"fc-342-5fe904","poly":"cardio","fiche":"342","front":"Crise d'épilepsie : quel mécanisme de la PDCB ?","back":"**Hyperactivité** cérébrale.","prio":"P3","sec":"s1"},{"id":"fc-342-cbcd53","poly":"cardio","fiche":"342","front":"PDCB psychogène : quel mécanisme ?","back":"Phénomène de **conversion** (imite une épilepsie ou une syncope).","prio":"P3","sec":"s1"},{"id":"fc-342-5311d8","poly":"cardio","fiche":"342","front":"Syncope de Stokes-Adams : que désignait ce terme ?","back":"Syncope **sans prodrome**, pâleur, **< 30 s**, réveil brutal, le plus souvent **rythmique**.","prio":"P2","sec":"s1"},{"id":"fc-342-72abe8","poly":"cardio","fiche":"342","front":"« Malaise » : que peut-il recouvrir d'autre qu'une syncope ?","back":"**Douleur thoracique**, **dyspnée**, **vertige**…","prio":"P2","sec":"s1"},{"id":"fc-342-2e839d","poly":"cardio","fiche":"342","front":"Syncope : quelle durée d'arrêt du flux cérébral suffit à perdre connaissance ?","back":"**6 à 8 secondes**.","prio":"P2","sec":"s2"},{"id":"fc-342-e09a6d","poly":"cardio","fiche":"342","front":"Syncope : quelle structure cérébrale « éteint » la conscience ?","back":"La **substance réticulée activatrice** du tronc cérébral.","prio":"P3","sec":"s2"},{"id":"fc-342-741caf","poly":"cardio","fiche":"342","front":"Syncope : quels deux mécanismes de chute de la PA ?","back":"Baisse du **débit cardiaque** et/ou chute des **résistances périphériques**.","prio":"P2","sec":"s2"},{"id":"fc-342-34096e","poly":"cardio","fiche":"342","front":"Baisse du débit cardiaque responsable de syncope : quelles causes ?","back":"**Bradycardie** ou **tachycardie** ; baisse du **retour veineux** ; **obstacle** circulatoire.","prio":"P3","sec":"s2"},{"id":"fc-342-838361","poly":"cardio","fiche":"342","front":"Chute des résistances responsable de syncope : quelles causes ?","back":"**Réflexe** (levée du tonus sympathique) ; **dysautonomie** ; **médicaments**.","prio":"P3","sec":"s2"},{"id":"fc-342-d66377","poly":"cardio","fiche":"342","front":"Myoclonies de la syncope : quelles caractéristiques ?","back":"Brèves (**< 15 s**), **toujours après** la PDC (souvent après la 30ᵉ s) ; ne signent **pas** une épilepsie.","prio":"P2","sec":"s2"},{"id":"fc-342-b41f96","poly":"cardio","fiche":"342","front":"Pourquoi éviter le terme « syncope convulsivante » ?","back":"Les **myoclonies** de la syncope ne sont pas une épilepsie.","prio":"P3","sec":"s2"},{"id":"fc-342-6176a9","poly":"cardio","fiche":"342","front":"Épilepsie : quelles crises donnent une PDCB ?","back":"Les crises **généralisées** (toniques, cloniques, tonicocloniques, atoniques).","prio":"P3","sec":"s2"},{"id":"fc-342-0fbae0","poly":"cardio","fiche":"342","front":"PDCB psychogènes : quelles caractéristiques de durée et de fréquence ?","back":"Souvent **prolongées** et répétées **plusieurs fois par jour**.","prio":"P3","sec":"s2"},{"id":"fc-342-a0a04d","poly":"cardio","fiche":"342","front":"Causes de syncope : quelle mnémotechnique en 4 familles ?","back":"**O.T.H.R** : **O**bstacle mécanique, **T**rouble du rythme/conduction, **H**ypotension orthostatique, **R**éflexe.","prio":"P1","sec":"s3"},{"id":"fc-342-0e9c77","poly":"cardio","fiche":"342","front":"Causes de syncope (O.T.H.R) : quelles familles sont cardiaques ?","back":"Les deux premières : **Obstacle mécanique** et **Trouble du rythme/conduction**.","prio":"P2","sec":"s3"},{"id":"fc-342-076c6e","poly":"cardio","fiche":"342","front":"Quelle est la 1re cause de syncope ?","back":"L'**hypotension orthostatique**.","prio":"P1","sec":"s3"},{"id":"fc-342-6e0359","poly":"cardio","fiche":"342","front":"Sur cœur sain avec ECG normal : quelle syncope est la plus fréquente ?","back":"La syncope **réflexe**.","prio":"P1","sec":"s3"},{"id":"fc-342-702b08","poly":"cardio","fiche":"342","front":"Rétrécissement aortique serré : quel type de syncope ?","back":"Syncope **à l'effort**.","prio":"P1","sec":"s3"},{"id":"fc-342-949b51","poly":"cardio","fiche":"342","front":"CMH obstructive : quel mécanisme d'obstruction ?","back":"Septum hypertrophié au contact de la grande valve mitrale → obstruction de la **chambre de chasse du VG**.","prio":"P2","sec":"s3"},{"id":"fc-342-0997f0","poly":"cardio","fiche":"342","front":"CMH obstructive : quels signes évoquer ?","back":"**Souffle systolique éjectionnel** au bord gauche du sternum ; syncope **à l'effort ou juste après**.","prio":"P1","sec":"s3"},{"id":"fc-342-1a793a","poly":"cardio","fiche":"342","front":"CMH : quel mode de transmission ?","back":"Souvent génétique, **autosomique dominante** (protéines du sarcomère).","prio":"P3","sec":"s3"},{"id":"fc-342-e8591a","poly":"cardio","fiche":"342","front":"Embolie pulmonaire responsable de syncope : quel mécanisme et quelle gravité ?","back":"Thrombus occlusif du **tronc pulmonaire** ou de la chambre de chasse du VD ; souvent EP **à haut risque**.","prio":"P2","sec":"s3"},{"id":"fc-342-73304a","poly":"cardio","fiche":"342","front":"Tamponnade : pourquoi donne-t-elle une syncope ?","back":"L'épanchement **comprime les cavités à basse pression**, dont le VD.","prio":"P2","sec":"s3"},{"id":"fc-342-2d6913","poly":"cardio","fiche":"342","front":"Citer des causes rares de syncope par obstacle ?","back":"**Thrombose de valve mécanique**, **myxome**, dissection aortique, **HTP sévère**.","prio":"P3","sec":"s3"},{"id":"fc-342-47cf99","poly":"cardio","fiche":"342","front":"Insuffisance cardiaque sévère : est-elle une cause de syncope ?","back":"**Jamais en elle-même** (confusion ou trouble de conscience possibles).","prio":"P1","sec":"s3"},{"id":"fc-342-faa429","poly":"cardio","fiche":"342","front":"Troubles conductifs syncopaux : quels BAV surtout ?","back":"**BAV 3** (surtout **infrahissien**), BAV de **haut degré**, **Mobitz 2**.","prio":"P1","sec":"s3"},{"id":"fc-342-7cde6e","poly":"cardio","fiche":"342","front":"Dysfonction sinusale : à partir de quelle durée de pause devient-elle syncopale ?","back":"Pauses **> 6 secondes** (parfois moins chez le sujet âgé).","prio":"P1","sec":"s3"},{"id":"fc-342-048b60","poly":"cardio","fiche":"342","front":"Maladie de l'oreillette : quelle définition ?","back":"Syndrome **tachycardie-bradycardie** : FA paroxystique + dysfonction sinusale, pauses au retour en sinusal.","prio":"P2","sec":"s3"},{"id":"fc-342-56f2b3","poly":"cardio","fiche":"342","front":"Porteur de stimulateur avec syncope : quelles défaillances rechercher ?","back":"**Sonde déplacée ou rompue**, **batterie usée**.","prio":"P2","sec":"s3"},{"id":"fc-342-14da11","poly":"cardio","fiche":"342","front":"TV responsables de syncope : quelle cause principale ?","back":"La **maladie coronarienne** (SCA ou **séquelle d'infarctus**, parfois des années après).","prio":"P1","sec":"s3"},{"id":"fc-342-b2c180","poly":"cardio","fiche":"342","front":"TV : citer d'autres cardiopathies en cause ?","back":"**Cardiomyopathies** dilatées, hypertrophiques, restrictives ; **dysplasie arythmogène du VD**.","prio":"P2","sec":"s3"},{"id":"fc-342-b45e22","poly":"cardio","fiche":"342","front":"Torsades de pointes : sur quel terrain ECG ?","back":"**QT long**.","prio":"P1","sec":"s3"},{"id":"fc-342-656f2d","poly":"cardio","fiche":"342","front":"TSV : sont-elles une cause fréquente de syncope ?","back":"**Non** : exceptionnelle.","prio":"P1","sec":"s3"},{"id":"fc-342-6ee31f","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelle définition ?","back":"Chute de PAS **≥ 20 mmHg** ou de PAD **≥ 10 mmHg**, ou PAS **< 90 mmHg**, dans les **1 à 3 min** debout.","prio":"P1","sec":"s3"},{"id":"fc-342-e319ae","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quels facteurs favorisants ?","back":"**Effort préalable**, période **postprandiale**, **alitement prolongé**.","prio":"P2","sec":"s3"},{"id":"fc-342-85f3a0","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quels médicaments en cause ?","back":"**Vasodilatateurs** (nitrés, inhibiteurs calciques, bloqueurs du SRAA…), **diurétiques**, **psychotropes**, **antiparkinsoniens**.","prio":"P1","sec":"s3"},{"id":"fc-342-38f51f","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles causes d'hypovolémie ?","back":"**Déshydratation**, diarrhée, vomissements, **hémorragie**, **insuffisance surrénalienne**.","prio":"P2","sec":"s3"},{"id":"fc-342-d889c6","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles dysautonomies primaires et secondaires ?","back":"Primaires : **Parkinson**, **corps de Lewy** ; secondaires : **diabète**, **amylose**, neuropathies paranéoplasiques.","prio":"P2","sec":"s3"},{"id":"fc-342-270471","poly":"cardio","fiche":"342","front":"Syncopes réflexes : quels 3 types ?","back":"**Vasovagale**, **situationnelle**, **syndrome du sinus carotidien**.","prio":"P1","sec":"s3"},{"id":"fc-342-febd26","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel mécanisme ?","back":"Activation **parasympathique** (bradycardie) + baisse du tonus **sympathique** (vasodilatation).","prio":"P2","sec":"s3"},{"id":"fc-342-15defc","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quelles formes ?","back":"**Cardio-inhibitrice**, **vasoplégique** ou **mixte**.","prio":"P3","sec":"s3"},{"id":"fc-342-045b1b","poly":"cardio","fiche":"342","front":"Syncope situationnelle : citer des circonstances ?","back":"**Miction**, vomissements, **défécation**, **toux** (ictus laryngé), éternuements, après effort intense, Valsalva.","prio":"P2","sec":"s3"},{"id":"fc-342-cb9a2c","poly":"cardio","fiche":"342","front":"Syndrome du sinus carotidien : quel déclencheur ?","back":"**Compression du cou** sur le glomus carotidien (rasage, cravate…).","prio":"P2","sec":"s3"},{"id":"fc-342-312dc8","poly":"cardio","fiche":"342","front":"Syndrome du sinus carotidien : de quel « sinus » s'agit-il ?","back":"Du **glomus de l'artère carotide**, pas du nœud sinusal.","prio":"P2","sec":"s3"},{"id":"fc-342-d892dd","poly":"cardio","fiche":"342","front":"Torsade de pointes dégénérant en FV : syncope ou autre ?","back":"**Arrêt cardiaque**, pas une syncope.","prio":"P2","sec":"s3"},{"id":"fc-342-72b7e5","poly":"cardio","fiche":"342","front":"Interrogatoire d'une syncope : quel est son but ?","back":"**Confirmer la PDCB** et écarter si possible une **épilepsie** ou une PDCB **psychogène**.","prio":"P2","sec":"s4"},{"id":"fc-342-caab4d","poly":"cardio","fiche":"342","front":"Interrogatoire d'une syncope : quels éléments de terrain rechercher ?","back":"**Mort subite familiale**, **cardiopathie**, **médicaments** (hypotenseurs, changement récent), cause de **dysautonomie**.","prio":"P1","sec":"s4"},{"id":"fc-342-945700","poly":"cardio","fiche":"342","front":"Syncope : quels symptômes précédents sont des diagnostics prioritaires ?","back":"**Douleur thoracique** ou **dyspnée**.","prio":"P1","sec":"s4"},{"id":"fc-342-f6eac6","poly":"cardio","fiche":"342","front":"Syncope : quels prodromes orientent vers une origine vasovagale ?","back":"**Nausées**, **sueurs froides**.","prio":"P2","sec":"s4"},{"id":"fc-342-7264e9","poly":"cardio","fiche":"342","front":"Syncope : quelles circonstances déclenchantes rechercher ?","back":"Position, effort/repos, **douleur**, **émotion**, phobie du sang/prise de sang, **postprandial**, station debout prolongée, **chaleur**, lieu confiné.","prio":"P2","sec":"s4"},{"id":"fc-342-c5b9c6","poly":"cardio","fiche":"342","front":"Mouvements anormaux : quel élément de chronologie distingue crise et syncope ?","back":"**Dès** la perte de connaissance = **crise** ; **retardés** = myoclonies de **syncope**.","prio":"P1","sec":"s4"},{"id":"fc-342-207f75","poly":"cardio","fiche":"342","front":"Après l'épisode : quel signe oriente vers une crise comitiale ?","back":"**Courbatures** (et phase post-critique).","prio":"P2","sec":"s4"},{"id":"fc-342-2cca55","poly":"cardio","fiche":"342","front":"Témoin rapportant un pouls « aboli » : quelle valeur ?","back":"À prendre avec **prudence** (pouls radial imperceptible si hypotension).","prio":"P2","sec":"s4"},{"id":"fc-342-83ff80","poly":"cardio","fiche":"342","front":"PDC complète impossible à affirmer : sur quoi s'appuyer ?","back":"Sur le **terrain** et l'**ECG initial**.","prio":"P2","sec":"s4"},{"id":"fc-342-bff3e9","poly":"cardio","fiche":"342","front":"Syncope : que signifient un déficit neurologique ou une altération prolongée de la conscience ?","back":"On **sort du domaine cardiovasculaire**.","prio":"P1","sec":"s4"},{"id":"fc-342-de3fc2","poly":"cardio","fiche":"342","front":"Examen d'une syncope : quelle morsure de langue oriente vers une crise comitiale ?","back":"Morsure profonde du **bord latéral** de la langue.","prio":"P1","sec":"s4"},{"id":"fc-342-737285","poly":"cardio","fiche":"342","front":"Syncope : quels signes cardiovasculaires orientent vers un obstacle mécanique ?","back":"**Souffle systolique**, cœur pulmonaire aigu, bruits de **prothèse mécanique assourdis**.","prio":"P2","sec":"s4"},{"id":"fc-342-8dbc38","poly":"cardio","fiche":"342","front":"Syncope avec hypotension prolongée au décours immédiat : quelle orientation ?","back":"Cause **iatrogène** ou **réflexe**.","prio":"P2","sec":"s4"},{"id":"fc-342-d6897b","poly":"cardio","fiche":"342","front":"Recherche d'hypotension orthostatique : quel protocole ?","back":"**5 à 10 min** couché, puis PA à **1, 2 et 3 min** debout.","prio":"P1","sec":"s4"},{"id":"fc-342-bd65a2","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : qu'est-ce qui renforce son imputabilité ?","back":"La **reproduction des symptômes** pendant la chute de PA.","prio":"P2","sec":"s4"},{"id":"fc-342-396701","poly":"cardio","fiche":"342","front":"Syncope : l'âge permet-il de conclure à une cause vasovagale ?","back":"**Non** : il oriente mais trompe (pas forcément vasovagale chez le jeune, possible chez le sujet âgé).","prio":"P2","sec":"s4"},{"id":"fc-342-5966b9","poly":"cardio","fiche":"342","front":"Quel est le diagnostic différentiel le plus fréquent de la syncope aux urgences ?","back":"La **crise d'épilepsie**.","prio":"P1","sec":"s5"},{"id":"fc-342-082d03","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : fréquence d'un déclencheur ?","back":"Syncope : **très fréquent** ; épilepsie : **rare** (stimulation lumineuse, manque de sommeil, alcool).","prio":"P2","sec":"s5"},{"id":"fc-342-4ae710","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quels prodromes respectifs ?","back":"Syncope : tête vide, nausées, sueurs, palpitations ; épilepsie : **aura** (déjà-vu, hallucinations, sensation épigastrique).","prio":"P1","sec":"s5"},{"id":"fc-342-8dedb1","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quelles caractéristiques des mouvements ?","back":"Syncope : **< 10**, **tardifs**, asymétriques ; épilepsie : **> 20**, **dès** la PDCB, synchrones.","prio":"P1","sec":"s5"},{"id":"fc-342-c2cd98","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : où est mordue la langue ?","back":"Syncope : **bout** ; épilepsie : **bord latéral**.","prio":"P1","sec":"s5"},{"id":"fc-342-a6b369","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quelle couleur de peau ?","back":"Syncope : normale ou **pâle** ; épilepsie : **cyanosée**.","prio":"P2","sec":"s5"},{"id":"fc-342-f2aa15","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quel délai de réveil ?","back":"Syncope : **10 à 30 s** ; épilepsie : **plusieurs minutes**.","prio":"P1","sec":"s5"},{"id":"fc-342-8c9fbd","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quelle durée de confusion ?","back":"Syncope : **< 10 s** ; épilepsie : amnésie de fixation de **plusieurs minutes**.","prio":"P2","sec":"s5"},{"id":"fc-342-a6846a","poly":"cardio","fiche":"342","front":"Quels éléments font basculer vers l'épilepsie ?","back":"**Aura**, survenue **pendant le sommeil**, **morsure latérale**, **cyanose**, **confusion prolongée**, courbatures.","prio":"P1","sec":"s5"},{"id":"fc-342-c79089","poly":"cardio","fiche":"342","front":"PDCB psychogène : que montrent rythme, PA et EEG pendant l'épisode ?","back":"Ils sont **normaux**.","prio":"P2","sec":"s5"},{"id":"fc-342-d14664","poly":"cardio","fiche":"342","front":"PDCB psychogène : quels arguments cliniques ?","back":"**Résistance à l'ouverture des yeux**, PDC **> 15 min**, **répétition fréquente** dans la semaine.","prio":"P1","sec":"s5"},{"id":"fc-342-3cb1a4","poly":"cardio","fiche":"342","front":"Perte d'urines et somnolence après l'épisode : quelle valeur ?","back":"**Peu discriminantes** entre syncope et crise.","prio":"P2","sec":"s5"},{"id":"fc-342-4edaae","poly":"cardio","fiche":"342","front":"AIT vertébrobasilaire : en quoi diffère-t-il d'une syncope ?","back":"PDC plutôt **prolongée** + **déficit focal** (vertiges, ataxie, diplopie…) ; cause très rare de PDCB.","prio":"P3","sec":"s5"},{"id":"fc-342-f0822d","poly":"cardio","fiche":"342","front":"Vol sous-clavier : quels signes ?","back":"AIT déclenché par les mouvements du **membre supérieur gauche** ; **différence de PA** entre les bras.","prio":"P3","sec":"s5"},{"id":"fc-342-3c4475","poly":"cardio","fiche":"342","front":"AIT carotidien : donne-t-il une PDCB ?","back":"**Quasiment jamais**.","prio":"P2","sec":"s5"},{"id":"fc-342-37dfbe","poly":"cardio","fiche":"342","front":"Coma et arrêt cardiaque : pourquoi ne sont-ils pas des syncopes ?","back":"Ni **brefs** ni **spontanément résolutifs**.","prio":"P2","sec":"s5"},{"id":"fc-342-badc1c","poly":"cardio","fiche":"342","front":"Confusion mentale : pourquoi n'est-ce pas une syncope ?","back":"**Pas de perte de connaissance** (penser hypoglycémie, hypoxie…).","prio":"P2","sec":"s5"},{"id":"fc-342-03cae5","poly":"cardio","fiche":"342","front":"Cataplexie : quelle définition ?","back":"Perte brutale du **tonus** déclenchée par une **émotion**, **sans** perte de connaissance ni amnésie.","prio":"P2","sec":"s5"},{"id":"fc-342-335a9d","poly":"cardio","fiche":"342","front":"« Drop-attacks » : pourquoi éviter ce terme ?","back":"Il mélange épilepsies rares, maladie de **Ménière** et chutes inexpliquées.","prio":"P3","sec":"s5"},{"id":"fc-342-48d893","poly":"cardio","fiche":"342","front":"Causes neurologiques de malaise ou de crise : lesquelles citer ?","back":"**Hypoglycémie**, **toxiques**, **méningite**, **arrêt de traitement**, **lésion intracérébrale focale**.","prio":"P2","sec":"s5"},{"id":"fc-342-b8d0e2","poly":"cardio","fiche":"342","front":"Malaises ni cardiaques ni neurologiques : lesquels ?","back":"**Malaise somatomorphe**, **attaque de panique**.","prio":"P2","sec":"s5"},{"id":"fc-342-1f3e4f","poly":"cardio","fiche":"342","front":"Malaise avec déficit neurologique : quelle orientation ?","back":"**Urgence neurovasculaire**.","prio":"P1","sec":"s5"},{"id":"fc-342-eb76bf","poly":"cardio","fiche":"342","front":"Syncope au cours d'un SCA ou d'un infarctus : qu'est-ce qui dicte la prise en charge ?","back":"Le **SCA / l'infarctus** lui-même.","prio":"P2","sec":"s5"},{"id":"fc-342-38be38","poly":"cardio","fiche":"342","front":"Syncope : quelles anomalies ECG sinusales ont une valeur diagnostique ?","back":"Bradycardie **< 40 bpm** ou pauses **> 3 s** chez un patient **éveillé**.","prio":"P1","sec":"s6"},{"id":"fc-342-342aa9","poly":"cardio","fiche":"342","front":"Syncope : citer les anomalies ECG à valeur diagnostique immédiate ?","back":"Brady **< 40 bpm** ou pause **> 3 s** éveillé, **TV**, **torsades**, **BAV 3/Mobitz 2**, **bloc alternant**, **TSV > 150 bpm**, défaillance de stimulateur/DAI.","prio":"P1","sec":"s6"},{"id":"fc-342-5d6d67","poly":"cardio","fiche":"342","front":"TSV : à partir de quelle fréquence a-t-elle valeur diagnostique de syncope ?","back":"**> 150 bpm**.","prio":"P2","sec":"s6"},{"id":"fc-342-c7f5ad","poly":"cardio","fiche":"342","front":"Bloc de branche alternant : quelle valeur devant une syncope ?","back":"**Diagnostique** (trifasciculaire).","prio":"P2","sec":"s6"},{"id":"fc-342-06f36f","poly":"cardio","fiche":"342","front":"Bradycardie 40-50 bpm ou pauses < 3 s : quelle valeur ?","back":"**Orientation** vers une dysfonction sinusale causale.","prio":"P2","sec":"s6"},{"id":"fc-342-6f99aa","poly":"cardio","fiche":"342","front":"Mobitz 1, BBG, bloc bifasciculaire : vers quoi orientent-ils ?","back":"Un **BAV paroxystique**.","prio":"P1","sec":"s6"},{"id":"fc-342-d796d9","poly":"cardio","fiche":"342","front":"ESV nombreuses ou en salves : vers quoi orientent-elles ?","back":"Une **TV**.","prio":"P2","sec":"s6"},{"id":"fc-342-b4eaca","poly":"cardio","fiche":"342","front":"QT long : vers quoi oriente-t-il ?","back":"Des **torsades de pointes**.","prio":"P1","sec":"s6"},{"id":"fc-342-7f76a8","poly":"cardio","fiche":"342","front":"Syndrome de Brugada : quel aspect ECG et quel risque ?","back":"**Sus-décalage convexe** de ST en **V1-V3** sans miroir → **FV** (syncope si elle cède, mort subite sinon).","prio":"P2","sec":"s6"},{"id":"fc-342-8e01d9","poly":"cardio","fiche":"342","front":"Wolff-Parkinson-White : quelle valeur devant une syncope ?","back":"**Orientation** vers une cause rythmique.","prio":"P2","sec":"s6"},{"id":"fc-342-c7191c","poly":"cardio","fiche":"342","front":"Onde Q, HVG, troubles de repolarisation : quelle orientation ?","back":"Cardiopathie (**séquelle d'infarctus**…) → chercher une **TV**.","prio":"P2","sec":"s6"},{"id":"fc-342-0844d1","poly":"cardio","fiche":"342","front":"Après clinique + ECG : dans quelle proportion la cause est-elle trouvée ?","back":"**Plus de 50 %**.","prio":"P1","sec":"s6"},{"id":"fc-342-e2f7d0","poly":"cardio","fiche":"342","front":"Syncope sans diagnostic avec anomalie ECG ou cardiopathie : quelle hypothèse dominante ?","back":"Un **trouble du rythme ventriculaire** annonciateur de **mort subite**.","prio":"P1","sec":"s6"},{"id":"fc-342-9ab193","poly":"cardio","fiche":"342","front":"ECG normal et pas de cardiopathie clinique : faut-il arrêter le bilan ?","back":"**Non** : poursuivre les examens pour s'en assurer.","prio":"P2","sec":"s6"},{"id":"fc-342-e07e9d","poly":"cardio","fiche":"342","front":"Bilan d'une syncope : quelle est la question principale ?","back":"Existe-t-il une **cardiopathie sous-jacente** (risque de **mort subite**) ?","prio":"P1","sec":"s7"},{"id":"fc-342-1e3e83","poly":"cardio","fiche":"342","front":"Syncope : quels antécédents imposent de garder le patient ?","back":"**Mort subite familiale** jeune ; **cardiopathie**, IC, infarctus, FEVG altérée.","prio":"P1","sec":"s7"},{"id":"fc-342-f6f68d","poly":"cardio","fiche":"342","front":"Syncope : quelles caractéristiques imposent de garder le patient ?","back":"**À l'effort**, **précédée de palpitations**, ou **en position couchée**.","prio":"P1","sec":"s7"},{"id":"fc-342-572ba8","poly":"cardio","fiche":"342","front":"Syncope : quels symptômes associés imposent de garder le patient ?","back":"**Douleur thoracique** ou abdominale, **céphalées**, **dyspnée brutale**, **traumatisme grave**.","prio":"P1","sec":"s7"},{"id":"fc-342-b60917","poly":"cardio","fiche":"342","front":"Syncope : quel signe d'examen impose de garder le patient ?","back":"Un **souffle systolique éjectionnel**.","prio":"P1","sec":"s7"},{"id":"fc-342-1a49e4","poly":"cardio","fiche":"342","front":"Syncope : quelle anomalie ECG impose de garder le patient ?","back":"Toute anomalie à valeur **diagnostique** ou d'**orientation**.","prio":"P1","sec":"s7"},{"id":"fc-342-b990b0","poly":"cardio","fiche":"342","front":"Critères de gravité d'une syncope : quelle mnémotechnique ?","back":"**3A - 3S** : **A**TCD familiaux, **A**TCD personnels, **A**nomalie ECG ; **S**yncope d'effort/couchée/palpitations, **S**ymptôme grave, **S**ouffle.","prio":"P2","sec":"s7"},{"id":"fc-342-3d8bea","poly":"cardio","fiche":"342","front":"Syncope : quelles conditions pour un retour à domicile ?","back":"**Réflexe évidente** ou **HTO** traitée + **examen et ECG normaux** + **aucune cardiopathie**.","prio":"P1","sec":"s7"},{"id":"fc-342-8e5a92","poly":"cardio","fiche":"342","front":"Syncope à risque vital suspecté : quelle surveillance aux urgences ?","back":"**Monitorage ECG obligatoire**.","prio":"P2","sec":"s7"},{"id":"fc-342-c33802","poly":"cardio","fiche":"342","front":"Syncope chez un cardiaque : quand retenir une syncope vasovagale ?","back":"Seulement **après bilan complet** : c'est un **diagnostic d'élimination**.","prio":"P1","sec":"s7"},{"id":"fc-342-a0cf37","poly":"cardio","fiche":"342","front":"Syncope : quelle place de l'échocardiographie ?","back":"**Quasi systématique**.","prio":"P2","sec":"s8"},{"id":"fc-342-34b7c7","poly":"cardio","fiche":"342","front":"Syncope avec cardiopathie du VG à FEVG altérée : quelle conduite possible ?","back":"**DAI** d'emblée en prévention de la mort subite, **sans autre examen**.","prio":"P2","sec":"s8"},{"id":"fc-342-248de6","poly":"cardio","fiche":"342","front":"Épreuve d'effort pour syncope : comment interpréter le moment de survenue ?","back":"**Pendant ou juste après** l'effort → **cardiaque** ; **après** l'effort → **réflexe**.","prio":"P2","sec":"s8"},{"id":"fc-342-8cc312","poly":"cardio","fiche":"342","front":"Syncope : quels biomarqueurs aident à repérer une cause cardiaque ?","back":"**BNP/NT-proBNP**, **troponine**.","prio":"P3","sec":"s8"},{"id":"fc-342-a7393e","poly":"cardio","fiche":"342","front":"Holter ECG pour syncope : quelle durée et quelle indication ?","back":"**24 h à 3 semaines**, si pas de haut risque et épisodes **fréquents**.","prio":"P2","sec":"s8"},{"id":"fc-342-5f5858","poly":"cardio","fiche":"342","front":"Holter normal : qu'est-ce qu'il n'élimine pas ?","back":"Un **trouble du rythme ventriculaire** ni un **BAV hissien/infrahissien** paroxystique.","prio":"P2","sec":"s8"},{"id":"fc-342-3c3ce7","poly":"cardio","fiche":"342","front":"Holter : pour quels troubles est-il sensible ?","back":"**Dysfonction sinusale** et troubles de conduction AV **nodaux**.","prio":"P3","sec":"s8"},{"id":"fc-342-7d6049","poly":"cardio","fiche":"342","front":"Massage du sinus carotidien : quand est-il positif ?","back":"Pause **> 3 s** ou baisse de PAS **> 50 mmHg** **reproduisant les symptômes**.","prio":"P2","sec":"s8"},{"id":"fc-342-c92349","poly":"cardio","fiche":"342","front":"Massage du sinus carotidien : quelles contre-indications ?","back":"**AIT** ou **AVC** antérieur, **sténose carotidienne**.","prio":"P2","sec":"s8"},{"id":"fc-342-106c35","poly":"cardio","fiche":"342","front":"Massage du sinus carotidien : quelles modalités ?","back":"Couché puis debout, **un côté puis l'autre**, **5 à 10 s**, à hauteur du cricoïde.","prio":"P3","sec":"s8"},{"id":"fc-342-12e33d","poly":"cardio","fiche":"342","front":"EEP : quelle indication devant une syncope ?","back":"Syncope **non élucidée** + **cardiopathie** ou **anomalie ECG** (bloc bifasciculaire, BBG).","prio":"P2","sec":"s8"},{"id":"fc-342-acb355","poly":"cardio","fiche":"342","front":"EEP : que mesure-t-on ou recherche-t-on ?","back":"**HV** (conduction infrahissienne), stimulation atriale, **stimulation ventriculaire programmée** (déclencher une TV).","prio":"P3","sec":"s8"},{"id":"fc-342-79d771","poly":"cardio","fiche":"342","front":"EEP : quand ne pas la proposer ?","back":"**Cœur normal** à l'écho **et ECG normal**, sauf palpitations avant la syncope.","prio":"P2","sec":"s8"},{"id":"fc-342-e50cda","poly":"cardio","fiche":"342","front":"EEP : quelle voie d'abord et quelle surveillance ?","back":"Voie **veineuse fémorale** ; surveiller le point de ponction, mobilisation **4 h** après.","prio":"P3","sec":"s8"},{"id":"fc-342-71f132","poly":"cardio","fiche":"342","front":"MAPA : quel intérêt devant une syncope ?","back":"Peut suggérer une **HTO** (souvent **HTA nocturne paradoxale**).","prio":"P3","sec":"s8"},{"id":"fc-342-44609b","poly":"cardio","fiche":"342","front":"Test d'inclinaison : que reproduit-il ?","back":"La syncope **vasovagale** ; parfois une **PDCB psychogène** (ECG et PA normaux).","prio":"P2","sec":"s8"},{"id":"fc-342-7a007b","poly":"cardio","fiche":"342","front":"Test d'inclinaison : quelles modalités ?","back":"Décubitus **≥ 5 min**, table à **60-70°**, **20 à 45 min**, sensibilisation par isoprénaline ou trinitrine.","prio":"P3","sec":"s8"},{"id":"fc-342-20ebd9","poly":"cardio","fiche":"342","front":"Test d'inclinaison positif : élimine-t-il une cause cardiaque ?","back":"**Non** (prudence).","prio":"P2","sec":"s8"},{"id":"fc-342-4f33bd","poly":"cardio","fiche":"342","front":"Moniteur ECG implantable : quelle autonomie et quelles indications ?","back":"**> 2 ans** : syncopes **espacées** ; EEP négative avec faux négatif suspecté ; syncopes sévères, fréquentes et **totalement inexpliquées**.","prio":"P2","sec":"s8"},{"id":"fc-342-573e67","poly":"cardio","fiche":"342","front":"Moniteur ECG implantable : quand n'est-il pas indiqué ?","back":"Patient relevant déjà d'un **DAI** ou d'un **stimulateur**.","prio":"P2","sec":"s8"},{"id":"fc-342-4bd286","poly":"cardio","fiche":"342","front":"Syncope : quelle hiérarchie des examens rythmiques ?","back":"**Holter et écho** avant l'**EEP** ; **MEI** si EEP négative.","prio":"P2","sec":"s8"},{"id":"fc-342-4e913d","poly":"cardio","fiche":"342","front":"Patients cardiaques : quelle est la 1re cause de mort subite ?","back":"Les **TV** (la syncope peut en être le signe annonciateur).","prio":"P1","sec":"s8"},{"id":"fc-342-057e8b","poly":"cardio","fiche":"342","front":"TV déclenchée lors de l'exploration d'une syncope : quel traitement ?","back":"Pose d'un **défibrillateur automatique implantable**.","prio":"P1","sec":"s8"},{"id":"fc-342-74273a","poly":"cardio","fiche":"342","front":"Toute syncope : quel trépied initial ?","back":"**Interrogatoire** + **examen** (avec HTO) + **ECG**.","prio":"P1","sec":"s9"},{"id":"fc-342-5d6ed5","poly":"cardio","fiche":"342","front":"Syncope sans cause évidente : que rechercher avant tout ?","back":"Une **cardiopathie sous-jacente**.","prio":"P1","sec":"s9"},{"id":"fc-342-e5e453","poly":"cardio","fiche":"342","front":"Syncope : si tous les examens sont normaux, quelle cause est probable ?","back":"Une syncope **réflexe**.","prio":"P1","sec":"s9"},{"id":"fc-342-3c0619","poly":"cardio","fiche":"342","front":"Syncope sans cause : quelles explorations si syncope grave possible ?","back":"**DAI d'emblée**, **EEP**, **MEI**.","prio":"P3","sec":"s9"},{"id":"fc-342-cb472f","poly":"cardio","fiche":"342","front":"Syncope sans cause : quelles explorations si syncope réflexe probable ?","back":"**Test d'inclinaison**, **MEI**.","prio":"P3","sec":"s9"},{"id":"fc-342-5e330d","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel geste immédiat ?","back":"**Allonger** le patient et **surélever ses jambes**.","prio":"P1","sec":"s10"},{"id":"fc-342-d816f1","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quels contextes déclenchants ?","back":"**Station debout prolongée**, lieu confiné, foule, **chaleur**, **douleur**, **émotion**, vue du sang.","prio":"P2","sec":"s10"},{"id":"fc-342-55a3e9","poly":"cardio","fiche":"342","front":"Syncopes réflexes : quelles circonstances favorisent toutes les formes ?","back":"La **nuit**, la **chaleur**, la période **postprandiale**.","prio":"P2","sec":"s10"},{"id":"fc-342-d6c18d","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel terrain typique ?","back":"Sujet **jeune**, **souvent** anxieux, émotif ou dépressif ; souvent passé de syncopes répétées **avant 40 ans**.","prio":"P2","sec":"s10"},{"id":"fc-342-4dc5ec","poly":"cardio","fiche":"342","front":"Syndrome du sinus carotidien : quel terrain typique ?","back":"L'**homme âgé**.","prio":"P1","sec":"s10"},{"id":"fc-342-d29788","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel tableau typique ?","back":"**Prodromes** (nausées, vue trouble, jambes faibles), **sueurs**, **pâleur**, chute, bradycardie parfois sévère.","prio":"P2","sec":"s10"},{"id":"fc-342-a77024","poly":"cardio","fiche":"342","front":"Syncope réflexe : quel est le traitement de fond de base ?","back":"**Non médicamenteux** : **réassurance**, éducation, **eau et sel**, baisse des **hypotenseurs**.","prio":"P2","sec":"s10"},{"id":"fc-342-61470d","poly":"cardio","fiche":"342","front":"Syncope réflexe : quelles mesures éducatives ?","back":"Éviter les déclencheurs, **reconnaître les prodromes** pour s'asseoir ou se coucher, **contractions isométriques**.","prio":"P3","sec":"s10"},{"id":"fc-342-ef3f82","poly":"cardio","fiche":"342","front":"Syncope réflexe : quels médicaments, rarement ?","back":"**Fludrocortisone** ou **agonistes alpha**.","prio":"P3","sec":"s10"},{"id":"fc-342-e13e5e","poly":"cardio","fiche":"342","front":"Syncope réflexe : quand discuter un pacemaker ?","back":"Composante **bradycardique prédominante et documentée**.","prio":"P3","sec":"s10"},{"id":"fc-342-84398a","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelle cause la plus fréquente ?","back":"**Iatrogène** (psychotropes, antiparkinsoniens, antihypertenseurs).","prio":"P2","sec":"s11"},{"id":"fc-342-50834a","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelle circonstance médicamenteuse typique ?","back":"**Introduction ou changement de dose** d'un hypotenseur (vasodilatateur, diurétique).","prio":"P1","sec":"s11"},{"id":"fc-342-4e4e34","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quel terrain fréquent ?","back":"Le **sujet âgé**, parfois avec **dysautonomie**.","prio":"P2","sec":"s11"},{"id":"fc-342-cbb3b8","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles mesures de 1re ligne ?","back":"**Hydratation** et **apports sodés**, **baisse ou arrêt des hypotenseurs**, **bas de contention**, **lever prudent**.","prio":"P1","sec":"s11"},{"id":"fc-342-0c8131","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles manœuvres physiques ?","back":"**Croiser les jambes**, **s'accroupir**.","prio":"P2","sec":"s11"},{"id":"fc-342-db08f8","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quels médicaments si besoin ?","back":"**Midodrine** (alpha-agoniste) ou **fludrocortisone** (minéralocorticoïde).","prio":"P2","sec":"s11"},{"id":"fc-342-36e7f2","poly":"cardio","fiche":"342","front":"Fludrocortisone : quel mécanisme dans l'hypotension orthostatique ?","back":"**Rétention hydrosodée**.","prio":"P3","sec":"s11"},{"id":"fc-342-70787f","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quels diagnostics finaux les plus fréquents ?","back":"**TV** ou **BAV**.","prio":"P1","sec":"s12"},{"id":"fc-342-701c36","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quel terrain ?","back":"ATCD (parfois très ancien) d'**infarctus** ou de **cardiomyopathie dilatée**, en général à **FEVG abaissée** ; **parfois** morts subites familiales.","prio":"P2","sec":"s12"},{"id":"fc-342-725614","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quand la suspecter ?","back":"Syncope **à l'effort**, **en position couchée** ou **précédée de palpitations**.","prio":"P1","sec":"s12"},{"id":"fc-342-e11ba0","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quelle sanction thérapeutique selon le mécanisme ?","back":"**TV** → **défibrillateur** ; atteinte des **voies de conduction** → **stimulateur**.","prio":"P3","sec":"s12"},{"id":"fc-342-90e539","poly":"cardio","fiche":"342","front":"Tamponnade confirmée : quel traitement ?","back":"**Drainage** en urgence (ponction échoguidée ou chirurgical) en Usic ; remplissage par **macromolécules**.","prio":"P1","sec":"s13"},{"id":"fc-342-cc7ce9","poly":"cardio","fiche":"342","front":"Tamponnade non traitée : quel risque ?","back":"**Arrêt cardiaque** par **adiastolie**.","prio":"P2","sec":"s13"},{"id":"fc-342-2d12d6","poly":"cardio","fiche":"342","front":"EP à haut risque : quel traitement ?","back":"**Fibrinolyse** sauf CI ; **embolectomie chirurgicale** si CI ou échec.","prio":"P1","sec":"s13"},{"id":"fc-342-137d3a","poly":"cardio","fiche":"342","front":"EP à haut risque fibrinolysée : quel anticoagulant et quelle cible ?","back":"**HNF** : TCA **2 à 3 fois** le témoin ou anti-Xa **0,5 à 0,8**.","prio":"P2","sec":"s13"},{"id":"fc-342-a3ad95","poly":"cardio","fiche":"342","front":"RA serré symptomatique : quel traitement ?","back":"Toujours le traiter : **remplacement valvulaire** ou **TAVI**, pratiquement sans limite d'âge.","prio":"P2","sec":"s13"},{"id":"fc-342-5a4c24","poly":"cardio","fiche":"342","front":"Rétrécissement aortique symptomatique : quelle notion est inacceptable ?","back":"Ne **pas l'adresser** au spécialiste.","prio":"P1","sec":"s13"},{"id":"fc-342-753749","poly":"cardio","fiche":"342","front":"Thrombose de prothèse mécanique : quelle prise en charge initiale ?","back":"**INR en urgence**, Usic, **héparine IV** à la seringue + **aspirine** (bolus IV puis per os).","prio":"P1","sec":"s13"},{"id":"fc-342-3942c5","poly":"cardio","fiche":"342","front":"Thrombose de prothèse mécanique : quelle cause fréquente ?","back":"Une **anticoagulation insuffisante**.","prio":"P2","sec":"s13"},{"id":"fc-342-8c3c7e","poly":"cardio","fiche":"342","front":"Thrombose de prothèse : quels signes d'auscultation ?","back":"Bruits de prothèse **diminués** ; souffle systolique (aortique) ou roulement diastolique (mitral).","prio":"P2","sec":"s13"},{"id":"fc-342-542a21","poly":"cardio","fiche":"342","front":"Thrombose de prothèse : quels examens diagnostiques ?","back":"**Radiocinéma**, **ETT/ETO**, scanner injecté synchronisé.","prio":"P3","sec":"s13"},{"id":"fc-342-b9333b","poly":"cardio","fiche":"342","front":"Thrombose aiguë de prothèse mécanique : quel traitement et quelle mortalité ?","back":"**Réintervention en urgence** (changement de valve) ; mortalité **30 %**.","prio":"P2","sec":"s13"},{"id":"fc-342-83c65e","poly":"cardio","fiche":"342","front":"Thrombose de prothèse : quand recourir à la thrombolyse ?","back":"Si **chirurgie contre-indiquée** ou forme **subaiguë** résistante.","prio":"P3","sec":"s13"},{"id":"fc-342-b8a1bc","poly":"cardio","fiche":"342","front":"Syncope par obstacle : quelles causes prédominent ?","back":"**RA** et **EP**, puis CMH obstructive, tamponnade, thrombose de valve mécanique.","prio":"P2","sec":"s13"},{"id":"fc-342-82dfe6","poly":"cardio","fiche":"342","front":"Après une EP : comment se fait le lever ?","back":"Avec **bas de contention**, **sans alitement**.","prio":"P3","sec":"s13"},{"id":"fc-342-681233","poly":"cardio","fiche":"342","front":"Crise généralisée : sur quoi repose le diagnostic rétrospectif ?","back":"L'**interrogatoire de l'entourage**.","prio":"P1","sec":"s14"},{"id":"fc-342-3e170f","poly":"cardio","fiche":"342","front":"Crise convulsive généralisée : quel antiépileptique de courte durée administrer ?","back":"Une **benzodiazépine**.","prio":"P1","sec":"s14"},{"id":"fc-342-ff1ebd","poly":"cardio","fiche":"342","front":"Antiépileptique de courte durée : à quoi l'associer ?","back":"À un traitement de **longue durée d'action**.","prio":"P2","sec":"s14"},{"id":"fc-342-e34043","poly":"cardio","fiche":"342","front":"Syncope réflexe : quel message clé au patient ?","back":"Sa **bénignité** (récidives souvent moins nombreuses après évaluation).","prio":"P2","sec":"s15"},{"id":"fc-342-225744","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quel objectif du suivi ?","back":"**Prévention de la mort subite** (DAI si TV, stimulateur si trouble conductif).","prio":"P2","sec":"s15"},{"id":"fc-342-9d6a68","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quel suivi ?","back":"**Sécurité des médicaments** (hypotenseurs réduits), **lever prudent**, contention ; penser au sujet âgé.","prio":"P2","sec":"s15"}],"fiches":{"152":{"title":"Endocardite infectieuse","poly":"cardio"},"153":{"title":"Surveillance des porteurs de valve et prothèses","poly":"cardio"},"203":{"title":"Dyspnée aiguë et chronique","poly":"cardio"},"221":{"title":"Athérome et malade polyathéromateux","poly":"cardio"},"222":{"title":"Facteurs de risque cardiovasculaire et prévention","poly":"cardio"},"223":{"title":"Dyslipidémies","poly":"cardio"},"224":{"title":"HTA de l'adulte et de l'enfant","poly":"cardio"},"225":{"title":"Artériopathie de l'aorte, des artères viscérales et des membres inférieurs ; anévrismes","poly":"cardio"},"226":{"title":"Thrombose veineuse profonde et embolie pulmonaire","poly":"cardio"},"230":{"title":"Douleur thoracique aiguë","poly":"cardio"},"231":{"title":"Électrocardiogramme","poly":"cardio"},"232":{"title":"Fibrillation atriale","poly":"cardio"},"233":{"title":"Valvulopathies","poly":"cardio"},"234":{"title":"Insuffisance cardiaque de l'adulte","poly":"cardio"},"235":{"title":"Péricardite aiguë","poly":"cardio"},"236":{"title":"Troubles de la conduction intracardiaque","poly":"cardio"},"237":{"title":"Palpitations","poly":"cardio"},"238":{"title":"Souffle cardiaque chez l'enfant","poly":"cardio"},"330":{"title":"Prescription et surveillance des antithrombotiques","poly":"cardio"},"331":{"title":"Arrêt cardiocirculatoire","poly":"cardio"},"339":{"title":"Syndromes coronariens aigus","poly":"cardio"},"342":{"title":"Malaises, perte de connaissance, syncope","poly":"cardio"}}};
